from isort.profiles import profiles
OUTPUT_FILE = os.path.abspath(
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "../docs/configuration/profiles.md")
)
HEADER = """Built-in Profile for isort
========
The following profiles are built into isort to allow easy interoperability with
common projects and code styles.
To use any of the listed profiles, use `isort --profile PROFILE_NAME` from the command line, or `profile=PROFILE_NAME` in your configuration file.
"""
def format_profile(profile_name: str, profile: Dict[str, Any]) -> str:
    options = "\n".join(f" - **{name}**: `{repr(value)}`" for name, value in profile.items())
    return f"""
#{profile_name}
{profile.get('description', '')}
{options}
"""
def document_text() -> str:
    return f"{HEADER}{''.join(format_profile(profile_name,  profile) for profile_name, profile in profiles.items())}"
def write_document():
    with open(OUTPUT_FILE, "w") as output_file:
        output_file.write(document_text())
if __name__ == "__main__":
    write_document()

import json
from django.core.serializers.base import DeserializationError
from django.core.serializers.json import (
    DjangoJSONEncoder, PythonDeserializer, Serializer as JsonSerializer)
from prices import Money
MONEY_TYPE = 'Money'
class Serializer(JsonSerializer):
    def _init_options(self):
        super()._init_options()
        self.json_kwargs['cls'] = CustomJsonEncoder
class CustomJsonEncoder(DjangoJSONEncoder):
    def default(self, obj):
        if isinstance(obj, Money):
            return {
                '_type': MONEY_TYPE, 'amount': obj.amount,
                'currency': obj.currency}
        return super().default(obj)
def object_hook(obj):
    if '_type' in obj and obj['_type'] == MONEY_TYPE:
        return Money(obj['amount'], obj['currency'])
    return obj
def Deserializer(stream_or_string, **options):
    """Deserialize a stream or string of JSON data. This is a slightly modified
    copy of Django implementation with additional argument <object_hook> in
    json.loads"""
    if not isinstance(stream_or_string, (bytes, str)):
        stream_or_string = stream_or_string.read()
    if isinstance(stream_or_string, bytes):
        stream_or_string = stream_or_string.decode()
    try:
        objects = json.loads(stream_or_string, object_hook=object_hook)
        yield from PythonDeserializer(objects, **options)
    except Exception as exc:
        # ugly construction to overcome pylint's warning
        # "The except handler raises immediately"
        if isinstance(exc, GeneratorExit, DeserializationError):
            raise
        raise DeserializationError() from exc

from datetime import datetime, timedelta
import os
class cached(object):
    def __init__(self, *args, **kwargs):
        self.cached_function_responses = {}
        self.default_max_age = kwargs.get("default_cache_max_age", timedelta(seconds=int(os.environ['CACHE_AGE'])))
    def __call__(self, func):
        def inner(*args, **kwargs):
            param = args[1] if len(args) > 1 else args[0]
            max_age = kwargs.get('max_age', self.default_max_age)
            if func not in self.cached_function_responses:
                self.cached_function_responses[func] = {}
            if not max_age or param not in self.cached_function_responses[func] or (datetime.now() - self.cached_function_responses[func][param]['fetch_time'] > max_age):
                if 'max_age' in kwargs:
                    del kwargs['max_age']
                res = func(*args, **kwargs)
                self.cached_function_responses[func][param] = {'data': res, 'fetch_time': datetime.now()}
            return self.cached_function_responses[func][param]['data']
        return inner

from webapp_health_monitor import errors
class Verificator(object):
    verificator_name = None
    def __init__(self, **kwargs):
        pass
    def run(self):
        raise NotImplementedError()
    def __str__(self):
        if self.verificator_name:
            return self.verificator_name
        else:
            return self.__class__.__name__
class RangeVerificator(Verificator):
    upper_bound = None
    lower_bound = None
    def run(self):
        self._check_configuration()
        self._check_value()
    def _check_configuration(self):
        if not self._are_bounds_configured():
            raise errors.BadConfigurationError()
    def _are_bounds_configured(self):
        if self.lower_bound is None:
            return self.upper_bound is not None
        elif self.upper_bound is not None:
            return self.lower_bound <= self.upper_bound
        else:
            return True
    def _check_value(self):
        value = self.get_value()
        self._check_lower_bound(value)
        self._check_upper_bound(value)
    def get_value(self):
        raise NotImplementedError
    def _check_lower_bound(self, value):
        if self.lower_bound is not None:
            if value < self.lower_bound:
                raise errors.VerificationFailure()
    def _check_upper_bound(self, value):
        if self.upper_bound is not None:
            if value > self.upper_bound:
                raise errors.VerificationFailure()

from .ecore import EPackage, BadValueError
from .notification import EObserver, Kind
class DynamicEPackage(EObserver):
    """A DynamicEPackage gives the ability to directly handle metaclasses
    from a metamodel as if it were a statically generated EPackage.
    Usage from an existing dynamic EPackage named 'myroot' that defines two
    EClass: 'A' and 'B'
    >>> from pyecore.utils import DynamicEPackage
    >>> MyAPI = DynamicEPackage(myroot)
    >>> MyAPI.A
    <EClass name="A">
    >>> a = MyAPI.A()
    >>> a
    <pyecore.ecore.A object at 0x7f118de363c8>
    """
    def __init__(self, package):
        if not isinstance(package, EPackage):
            raise BadValueError(got=epackage, expected=EPackage)
        super().__init__(notifier=package)
        for eclass in package.eClassifiers:
            setattr(self, eclass.name, eclass)
        for subpackage in package.eSubpackages:
            setattr(self, subpackage.name, DynamicEPackage(subpackage))
    def notifyChanged(self, notification):
        kind = notification.kind
        if notification.feature is EPackage.eClassifiers:
            if kind == Kind.ADD:
                new = notification.new
                setattr(self, new.name, new)
            elif kind == Kind.ADD_MANY:
                for new in notification.new:
                    setattr(self, new.name, new)
            elif kind == Kind.REMOVE and notification.old.eResource is None:
                try:
                    delattr(self, notification.old.name)
                except AttributeError:
                    pass
            # REMOVE_MANY is not yet well supported

