from inspect import isgenerator
class Element(object):
    tag = ''
    self_closing = False
    def __init__(self, *children, **attrs):
        if children and isinstance(children[0], dict):
            self.attrs = children[0]
            children = children[1:]
        else:
            self.attrs = attrs
        # Some helpers for the `class` attribute
        if 'classes' in attrs:
            attrs['class'] = ' '.join(c for c in attrs.pop('classes') if c)
        elif 'class_' in attrs:
            attrs['class'] = attrs.pop('class_')
        self.children = []
        self.add_children(children)
    def __call__(self, *children):
        self.add_children(children)
        return self
    def __repr__(self):
        attr_string = ''.join(' {}="{}"'.format(key, val) for key, val in self.attrs.items() if val)
        return '<{}{}>'.format(self.tag, attr_string)
    def add_children(self, children):
        if self.self_closing and children:
            raise ValueError("Self-closing tags can't have children.")
        if children and isgenerator(children[0]):
            children = children[0]
        for child in children:
            if child is not None:
                if isinstance(child, list):
                    self.add_children(child)
                else:
                    self.children.append(child)

from typing import Iterable, List, Tuple
from werkzeug.http import HTTP_STATUS_CODES
from apistar import http
__all__ = ['WSGIEnviron', 'WSGIResponse']
STATUS_CODES = {
    code: "%d %s" % (code, msg)
    for code, msg in HTTP_STATUS_CODES.items()
}
ACCESS_CONTROL_ALLOW_ORIGIN = 'Access-Control-Allow-Origin'
WSGIEnviron = http.WSGIEnviron
class WSGIResponse(object):
    __slots__ = ('status', 'headers', 'iterator')
    def __init__(self,
                 status: str,
                 headers: List[Tuple[str, str]],
                 iterator: Iterable[bytes]) -> None:
        self.status = status
        self.headers = headers
        self.iterator = iterator
    @classmethod
    def build(cls, response: http.Response):
        try:
            status_text = STATUS_CODES[response.status]
        except KeyError:
            status_text = str(response.status)
        headers = list(response.headers.items())
        if ACCESS_CONTROL_ALLOW_ORIGIN not in response.headers:
            headers += [(ACCESS_CONTROL_ALLOW_ORIGIN, '*')]
        return WSGIResponse(
            status=status_text,
            headers=headers,
            iterator=[response.content]
        )

