from numpy import asarray, vstack, newaxis, zeros, nonzero, concatenate, transpose, atleast_2d
def check_colors(clrs):

    clrs = asarray(clrs)
    if clrs.ndim == 2 and clrs.shape[1] == 1:
        clrs = clrs.flatten()
    if clrs.ndim == 2 and clrs.shape[0] == 1:
        clrs = clrs.flatten()
    if clrs.ndim == 1:
        clrs = clrs[:,newaxis]
    elif clrs.shape[1] != 3:
        raise Exception("Color array must have three values per point")
    return clrs
def array_to_lines(data):
    data = asarray(data)
    return data
def vecs_to_points(x, y):

    x = asarray(x)
    y = asarray(y)
    points = vstack([x, y, range(0,len(x))]).T
    return points
def mat_to_links(mat, labels=None):
    # get nonzero entries as list with the source, target, and value as columns

    mat = asarray(mat)
    if mat.ndim < 2:
            raise Exception('Matrix input must be two-dimensional')
    inds = nonzero(mat)
    links = concatenate((transpose(nonzero(mat)), atleast_2d(mat[inds]).T), axis=1)
    # pick group assignments (default is all 1s)
    n = mat.shape[0]
    if labels is None:
        nodes = zeros((1, n)).T
    else:
        if labels.size != n:
            raise Exception("Must provide label for each row")
        nodes = labels.astype(int).reshape(labels.size, 1)
    return links, nodes
def array_to_im(im):
    from matplotlib.pyplot import imsave
    from matplotlib.pyplot import cm
    import io
    imfile = io.BytesIO()
    if im.ndim == 3:
        # if 3D, show as RGB
        imsave(imfile, im, format="png")
    else:
        # if 2D, show as grayscale
        imsave(imfile, im, format="png", cmap=cm.gray)
    if im.ndim > 3:
        raise Exception("Images must be 2 or 3 dimensions")
    return imfile.getvalue()

import glob
import re
import snmpy
class log_processor(snmpy.plugin):
    def create(self):
        for k, v in sorted(self.conf['objects'].items()):
            extra = {
                'count':  re.compile(v['count']),
                'reset':  re.compile(v['reset']) if 'reset' in v else None,
                'start':  int(v['start']) if 'start' in v else 0,
                'rotate': bool(v['rotate']) if 'rotate' in v else False
            }
            self.data['1.%s' % k] = 'string', v['label']
            self.data['2.%s' % k] = 'integer', extra['start'], extra
        self.tail()
    @snmpy.plugin.task
    def tail(self):
        for line in snmpy.plugin.tail(glob.glob(self.conf['file_name'])[0], True):
            if line is True:
                for item in self.data['2.0':]:
                    if self.data[item:'rotate'] and line is True:
                        self.data[item] = self.data[item:'start']
                continue
            for item in self.data['2.0':]:
                count = self.data[item:'count'].search(line)
                if count:
                    self.data[item] = self.data[item:True] + (int(count.group(1)) if len(count.groups()) > 0 else 1)
                    break
                if self.data[item:'reset'] is not None and self.data[item:'reset'].search(line):
                    self.data[item] = self.data[item:'start']
                    break

