    if migrate_engine.name == "postgresql":
        sql = """ALTER TABLE cells_id_seq RENAME TO zones_id_seq;
              ALTER TABLE ONLY cells DROP CONSTRAINT cells_pkey;
              ALTER TABLE ONLY cells ADD CONSTRAINT zones_pkey
