import re
class InvalidType(ValueError):
	"""Exception class for invalid type in arguments."""
	pass
class InvalidSelector(ValueError):
	"""Exception class for invalid in arguments."""
	pass
class InvalidOutputType(ValueError):
	"""Exception class for invalid output_type in arguments."""
	pass
def check_arguments(args):
	"""
	Validates the arguments passed through the CLI commands.
	:param args: The arguments passed in the CLI, parsed by the docopt module
	:return: None
	"""
	projectname_re = re.compile(r'[^a-zA-Z0-9_]')
	if args['genconfig']:
		if args['--type'] not in ['scraper', 'crawler']:
			raise InvalidType("--type has to be 'scraper' or 'crawler'")
		if args['--selector'] not in ['xpath', 'css']:
			raise InvalidSelector("--selector has to be 'xpath' or 'css'")
	if args['generate'] or args['run']:
		if args['--output_type'] not in ['json', 'csv']:
			raise InvalidOutputType("--output_type has to be 'json' or 'csv'")
	if args['genconfig'] or args['generate'] or args['run']:
		if projectname_re.search(args['<projectname>']) is not None:
			raise Exception("<projectname> should consist of letters, digits or _")
	if int(args['--levels']) < 1:
		raise Exception("--levels should be greater than, or equal to 1")
	return

import collections
import typing
class Meta(collections.OrderedDict, typing.MutableMapping[str, float]):
  def __init__(self, *args, **kwargs) -> None:
    self._smallest = float('inf')
    self._largest = 0
    self._ordered = True
    super(Meta, self).__init__(*args, **kwargs)
  def __setitem__(self, key: str, value: float) -> None:
    if key in self and self[key] == value:
      raise AssertionError('Redundant assignment')
    if value > self._smallest:
      self._ordered = False
    else:
      self._smallest = value
    if value > self._largest:
      self._largest = value
    super(Meta, self).__setitem__(key, value)
    self._changed()
  def items(self) -> typing.ItemsView[str, float]:
    self._reorder()
    return super(Meta, self).items()
  def first(self) -> typing.Tuple[str, float]:
    self._reorder()
    for k, v in self.items():
      return k, v
  def peek(self) -> str:
    self._reorder()
    for first in self:
      return first
  def magnitude(self) -> float:
    return self._largest
  def _reorder(self) -> None:
    if self._ordered:
      return
    order = sorted(super(Meta, self).items(), key=lambda x: x[1], reverse=True)
    for k, v in order:
      self.move_to_end(k)
    self._ordered = True
  def _changed(self):
    pass

from django.core.exceptions import ImproperlyConfigured
from rest_framework.permissions import BasePermission
SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS']
class OAuth2ScopePermission(BasePermission):
    """
    Make sure request is authenticated and token has right scope set.
    """
    def has_permission(self, request, view):
        token = request.auth
        read_only = request.method in SAFE_METHODS
        if not token:
            return False
        if hasattr(token, 'scope'):
            scopes = self.get_scopes(request, view)
            if scopes['required'] is not None:
                is_valid = token.is_valid(scopes['required'])
                if is_valid == False:
                    return False
            else:
                # View did not define any required scopes
                is_valid = False
            # Check for method specific scopes
            if read_only:
                if scopes['read'] is not None:
                    return token.is_valid(scopes['read'])
            else:
                if scopes['write'] is not None:
                    return token.is_valid(scopes['write'])
            return is_valid
        assert False, ('OAuth2ScopePermission requires the '
                       '`oauth_api.authentication.OAuth2Authentication` '
                       'class to be used.')
    def get_scopes(self, request, view):
        required = getattr(view, 'required_scopes', None)
        read = getattr(view, 'read_scopes', None)
        write = getattr(view, 'write_scopes', None)
        if not required and not read and not write:
            raise ImproperlyConfigured('OAuth protected resources requires scopes. Please add required_scopes, read_scopes or write_scopes.')
        return {
            'required': required,
            'read': read,
            'write': write,
        }

import ast
import os
from collections import deque
import sys
from stdlib_list import stdlib_list
conf = {
    'ignore_relative_imports': True,
    'ignore_builtin_modules': True,
    'pyver': None,
}
def get_imported_libs(code):
    tree = ast.parse(code)
    imports = deque()
    for t in tree.body:
        # ast.Import represents lines like 'import foo' and 'import foo, bar'
        # the extra for name in t.names is needed, because names is a list that
        # would be ['foo'] for the first and ['foo', 'bar'] for the second
        if type(t) == ast.Import:
            imports.extend([name.name.split('.')[0] for name in t.names])
        # ast.ImportFrom represents lines like 'from foo import bar'
        # t.level == 0 is to get rid of 'from .foo import bar' and higher levels
        # of relative importing
        if type(t) == ast.ImportFrom:
            if t.level > 0:
                if conf['ignore_relative_imports'] or not t.module:
                    continue
                else:
                    imports.append(t.module.split('.')[0])
    return list(imports)
def iterate_over_library(path_to_source_code):
    libs = set()
    for parent, folders, files in os.walk(path_to_source_code):
        for file in files:
            if file.endswith('.py'):
                print('.', end='')
                full_file_path = os.path.join(parent, file)
                with open(full_file_path, 'r') as f:
                    code = f.read()
                libs.update(set(get_imported_libs(code)))
    if conf['ignore_builtin_modules']:
        if not conf['pyver']:
            pyver = '%s.%s' % (sys.version_info.major, sys.version_info.minor)
        std_libs = stdlib_list("3.4")
        # print(std_libs)
        libs = [lib for lib in libs if lib not in std_libs]
    return libs

