    if key is not None and isinstance(value, dict):
        kws = []
        for item_key in value.keys():
            kws += keywords(key+[item_key], value[item_key])
        return kws
    if key is None and isinstance(value, dict):
        kws = []
        for item_key in value.keys():
            kws += keywords([item_key], value[item_key])
        return kws
@click.command()
@click.option('--threshold', default=1.0, help='Minimun similarity to show')
@click.option('--min-length', default=10, help='Minimun size of the string to show')
@click.option('--omit-identical', default=False, is_flag=True, help='Omit identical strings')
def verify_similarity(threshold, min_length, omit_identical):
    locales = json.load(open(DEFAULT_LOCALE_PATH))
    all_keywords = keywords(None, locales)
    already_shown_keys = set()
    for key1, value1 in all_keywords:
        for key2, value2 in all_keywords:
            if key1 == key2:
                continue
            if len(value1) < min_length and len(value2) < min_length:
                continue
            similarity = SequenceMatcher(None, value1, value2).ratio()
            if omit_identical and similarity == 1.0:
                continue
            if similarity >= threshold:
                if (key1, key2) not in already_shown_keys:
                    already_shown_keys.add((key1, key2))
                    already_shown_keys.add((key2, key1))
                    click.echo(
                        "The keys {} and {} has a similarity of {}\n - {}\n - {}".format(
                            key1,
                            key2,
                            similarity,
                            value1,
                            value2
                        )
                    )
if __name__ == "__main__":
    verify_similarity()

import math
import re
def filter_thing_flags_read(value, table):
    """
    Filters a thing's flags value.

    Extended patches can use mnemonics for flag names, separated by plus signs.

    @raise LookupError: if the value contains an unknown mnemonic.
        """ 
    if value.isdigit() == True:
        return value

    items = re.split(r"[,+| \t\f\r]+", value)
    out = 0

    for item in items:
        item = item.strip()

        # Find the index of the flag mnemonic and convert it to a flag value.
        flag = table.flags.get(item)
        if flag is None:
            raise LookupError('Ignoring unknown thing flag {}.'.format(item))
        bit = int(math.pow(2, flag['index']))
        out += bit

    return out


def filter_thing_flags_write(value, table):
    """
    Returns a thing flags value as a string of mnemonics. 
    """

    bit = 1
    out = []

    for _ in range(0, 32):
        if (value & bit) == 0:
            bit *= 2
            continue

        for key, flag in table.flags.iteritems():
            if int(math.pow(2, flag['index'])) == bit:    
                out.append(key)
                break

        bit *= 2

    if len(out) == 0:
        return 0
    else:
        return '+'.join(out)

