import numpy as np
class Activator:
    @staticmethod
    def sigmoid(signal, deriv=False):
        if deriv:
            return np.multiply(signal, 1 - signal)
        activation = 1 / (1 + np.exp(-signal))
        return activation
    @staticmethod
    def tanh(signal, deriv=False):
        if deriv:
            return 1 - np.power(np.tanh(signal), 2)
        activation = np.tanh(signal)
        return activation
    @staticmethod
    def elu(signal, deriv=False, alpha=1.0):
        activation = (signal >= 0).astype(int) * signal + \
                     (signal < 0).astype(int) * (alpha * (np.exp(signal) - 1))
        if deriv:
            derivation = (signal >= 0).astype(int) + \
                         (signal < 0) * (activation + alpha)
            return derivation
        return activation
    @staticmethod
    def softmax(signal, deriv=False):
        signal = signal - np.max(signal)
        activation = np.exp(signal) / np.array([np.sum(np.exp(signal), axis=1)]).T
        if deriv:
            jacobian = - activation[..., None] * activation[:, None, :]
            iy, ix = np.diag_indices_from(jacobian[0])
            jacobian[:, iy, ix] = activation * (1 - activation)
            return jacobian.sum(axis=1)
        return activation

import os
import sys
import json
import collections
import unicodedata
TEXT_FIELD = "t"
OPTIONS_FIELD = "o"
KIND_FIELD = "k"
CORRECT_FIELD = "c"
MANDATORY_FIELDS = {TEXT_FIELD, OPTIONS_FIELD, CORRECT_FIELD}
def norm(s):
    return unicodedata.normalize("NFD", s)
def error(message, *, n):
    raise ValueError(" ".join((message, "({})".format(n))))
def check(questions):
    text_occurences = collections.defaultdict(list)
    for n, question in enumerate(questions, start=1):
        # Contains mandatory fields.
        missing = MANDATORY_FIELDS - set(question.keys())
        if missing:
            error("missing {}".format(", ".join(missing)), n=n)
        text_occurences[norm(question[TEXT_FIELD])].append(n)
        # Kind, if present, is "tr".
        if KIND_FIELD in question and question[KIND_FIELD] != "tr":
            error("{} != tr".format(KIND_FIELD), n=n)
        # There are at least four options & they are unique.
        options = tuple(map(norm, question[OPTIONS_FIELD]))
        options_count = len(options)
        if len(set(options)) != options_count or options_count < 4:
            error(">= 4 unique options are required", n=n)
        # There is at least one correct index.
        correct = question[CORRECT_FIELD]
        if len(correct) < 1:
            error(">= 1 correct index is required", n=n)
        for index in correct:
            try:
                options[index]
            except IndexError:
                error("index {} is not adressable".format(index), n=n)
    # Text is not repeated.
    for text, ns in text_occurences.items():
        if len(ns) > 1:
            error(
                "t {} is repeated at {}".format(
                    text, ", ".join(map(str, ns[1:]))), n=ns[0])
def main():
    questions_path = os.path.normpath(
        os.path.join(
            os.path.dirname(__file__), "..", "src", "questions.json"))
    with open(questions_path, "r", encoding="utf-8") as file:
