from collections import Counter
from typing import Iterable, TextIO
import numpy  # type: ignore
def parse_layers(width: int, height: int, data: TextIO) -> Iterable[numpy.array]:
    chunk_size = width * height
    content = next(data).strip()
    for pos in range(0, len(content), chunk_size):
        yield numpy.array([int(c) for c in content[pos:pos + chunk_size]])
def part1(data: TextIO) -> int:
    best_layer: Counter[int] = min((Counter(layer) for layer in parse_layers(25, 6, data)), key=lambda c: c[0])
    return best_layer[1] * best_layer[2]
def format_row(row: Iterable[int]) -> str:
    return ''.join('#' if p == 1 else ' ' for p in row)
def part2(data: TextIO) -> str:
    background = numpy.zeros(25 * 6, numpy.int8)
    background.fill(2)
    for layer in parse_layers(25, 6, data):
        mask = background == 2
        background[mask] = layer[mask]
    return '\n'.join(format_row(row) for row in background.reshape(6, 25))

import functools
from pyp2rpm import settings
def memoize_by_args(func):
    """Memoizes return value of a func based on args."""
    memory = {}
    @functools.wraps(func)
    def memoized(*args):
        if not args in memory.keys():
            value = func(*args)
            memory[args] = value
        return memory[args]
    return memoized
def license_from_trove(trove):
    """Finds out license from list of trove classifiers.
    Args:
        trove: list of trove classifiers
    Returns:
        Fedora name of the package license or empty string, if no licensing information is found in trove classifiers.
    """
    license = []
    for classifier in trove:
        if classifier is None: continue
        if 'License' in classifier != -1:
            stripped = classifier.strip()
            # if taken from EGG-INFO, begins with Classifier:
            stripped = stripped[stripped.find('License'):]
            if stripped in settings.TROVE_LICENSES:
                license.append(settings.TROVE_LICENSES[stripped])
    return ' and '.join(license)

