import json, os, re, sys
def load_rules(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)
def scan_file(filepath, rules):
    findings = []
    try:
        with open(filepath, "r", encoding="utf-8", errors="ignore") as f:
            lines = f.readlines()
    except Exception:
        return findings
    for rule in rules:
        try:
            pat = re.compile(rule["pattern"], re.IGNORECASE if rule.get("case_insensitive", True) else 0)
        except re.error:
            continue
        for i, line in enumerate(lines, 1):
            if pat.search(line):
                # False positive filters
                if rule["id"] == "MC-008":
                    if not re.search(r"(KEY|SECRET|PASSWORD|TOKEN|CREDENTIAL)", line, re.IGNORECASE):
                        continue
                if rule["id"] == "MC-014":
                    if re.search(r"(github\.com|gitlab\.com|bitbucket\.org)", line, re.IGNORECASE):
                        continue
                if rule["id"] == "MC-017":
                    if not re.search(r"(rm\s|git push.*force|git reset|del\s|destroy|drop\s)", line, re.IGNORECASE):
                        continue
                findings.append({
                    "rule_id": rule["id"],
                    "rule_name": rule["name"],
                    "severity": rule["severity"],
                    "category": rule["category"],
                    "file": filepath,
                    "line": i,
                    "matched": line.strip()[:120],
                    "description": rule["description"]
                })
    return findings
def main():
    if len(sys.argv) != 2:
        print("Usage: python scan.py <path-to-skill-folder>")
        sys.exit(1)
    skill_path = sys.argv[1]
    if not os.path.isdir(skill_path):
        print(f"Error: {skill_path} is not a directory")
        sys.exit(1)
    script_dir = os.path.dirname(os.path.abspath(__file__))
    # Check same directory first (ClawHub flattens structure), then parent
    rules_path = os.path.join(script_dir, "rules.json")
    if not os.path.exists(rules_path):
        rules_path = os.path.join(os.path.dirname(script_dir), "rules.json")
    if not os.path.exists(rules_path):
        print("Error: rules.json not found")
        sys.exit(1)
    rules = load_rules(rules_path)
    print("MoltCops Security Scanner")
    print("=" * 40)
    print(f"Scanning: {skill_path}")
    # Find files
    exts = {".md", ".py", ".js", ".ts", ".sh", ".jsx", ".tsx", ".html", ".htm", ".json", ".json5", ".yaml", ".yml", ".toml", ".cfg", ".conf", ".ini"}
    files = []
    for root, dirs, fnames in os.walk(skill_path):
        dirs[:] = [d for d in dirs if d not in ("node_modules", ".git", "__pycache__")]
        for fn in fnames:
            if os.path.splitext(fn)[1] in exts:
                files.append(os.path.join(root, fn))
    print(f"Files: {len(files)}")
    print(f"Rules: {len(rules)}")
    print()
    all_findings = []
    for f in files:
        all_findings.extend(scan_file(f, rules))
    critical = sum(1 for f in all_findings if f["severity"] == "CRITICAL")
    high = sum(1 for f in all_findings if f["severity"] == "HIGH")
    medium = sum(1 for f in all_findings if f["severity"] == "MEDIUM")
    if all_findings:
        print("FINDINGS")
        print("-" * 40)
        for f in all_findings:
            sev = f["severity"]
            color = {"CRITICAL": "\033[0;31m", "HIGH": "\033[1;33m", "MEDIUM": "\033[0;34m"}.get(sev, "")
            nc = "\033[0m"
            rel = os.path.relpath(f["file"], skill_path)
            print(f"{color}[{sev}]{nc} {f['rule_id']}: {f['rule_name']} ({rel}:{f['line']})")
        print()
    print("SUMMARY")
    print("=" * 40)
    print(f"Files scanned: {len(files)}")
    print(f"Total findings: {len(all_findings)}")
    print(f"  Critical: {critical}")
    print(f"  High:     {high}")
    print(f"  Medium:   {medium}")
    print()
    if critical > 0:
        print("\033[0;31mVERDICT: BLOCK\033[0m")
        print("Critical threats detected. Do NOT install this skill.")
        sys.exit(2)
    elif high > 0:
        print("\033[1;33mVERDICT: WARN\033[0m")
        print("High-risk patterns found. Review before installing.")
        sys.exit(1)
    else:
        print("\033[0;32mVERDICT: PASS\033[0m")
        print("No critical or high-risk threats detected.")
        sys.exit(0)
if __name__ == "__main__":
    main()

import json
import os
import ssl
import sys
import urllib.request
BF_API_KEY = os.environ.get('BF_API_KEY', '')
BF_BASE = 'https://bananafarmer.app/api/bot/v1'
def bf_get(endpoint, timeout=15):
    if not BF_API_KEY:
        print("ERROR: BF_API_KEY not set. Get your key at https://bananafarmer.app")
        sys.exit(1)
    url = f"{BF_BASE}/{endpoint}"
    headers = {'x-bf-bot-key': BF_API_KEY, 'User-Agent': 'BananaFarmerBot/1.0'}
    req = urllib.request.Request(url, headers=headers)
    ctx = ssl.create_default_context()
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as resp:
            body = json.loads(resp.read().decode('utf-8'))
            return body.get('data', body)
    except urllib.error.HTTPError as e:
        if e.code == 403:
            try:
                err_body = json.loads(e.read().decode('utf-8'))
                err_code = err_body.get('error', {}).get('code', '')
            except Exception:
                err_code = ''
            if err_code == 'TIER_ACCESS_DENIED':
                print(f"ERROR: This endpoint requires a higher tier. Upgrade at https://bananafarmer.app/pricing")
                print(f"  Endpoint: /{endpoint}")
                print(f"  Free tier has access to: health, discover, signals/top, requests/mine")
                return None
            print(f"ERROR: 403 Forbidden on /{endpoint}. Check your API key and User-Agent header.")
            return None
        elif e.code == 429:
            print(f"ERROR: Rate limit exceeded. Wait a moment and try again.")
            return None
        raise
def cmd_health():
    data = bf_get('health')
    if not data:
        print("Could not reach BF API")
        return
    status = data.get('marketStatus', data.get('market', {}).get('status', 'unknown'))
    freshness = data.get('dataFreshness', data.get('data', {}).get('freshness', 'unknown'))
    print(f"Market: {status}")
    print(f"Data freshness: {freshness}")
    if data.get('safetyAdvisory'):
        print(f"Advisory: {data['safetyAdvisory']}")
    print("System: OK")
def cmd_top(args):
    limit = 10
    badge = 'all'
    i = 0
    while i < len(args):
        if args[i] == '--limit' and i + 1 < len(args):
            limit = int(args[i + 1])
            i += 2
        elif args[i] == '--badge' and i + 1 < len(args):
            badge = args[i + 1]
            i += 2
        else:
            i += 1
    endpoint = f'signals/top?limit={limit}'
    if badge != 'all':
        endpoint += f'&badge={badge}'
    data = bf_get(endpoint)
    if not data:
        print("No signals available")
        return
    signals = data if isinstance(data, list) else data.get('signals', [])
    # Dedup by symbol
    seen = set()
    unique = []
    for s in signals:
        sym = s.get('symbol', '')
        if sym not in seen:
            seen.add(sym)
            unique.append(s)
    print(f"TOP {len(unique)} SIGNALS")
    print(f"{'Symbol':<8} {'Score':>5} {'Badge':<12} {'1d Change':<10} {'5d Change':<10}")
    print("-" * 52)
    for s in unique[:limit]:
        sym = s.get('symbol', '?')
        score = s.get('score', 0)
        badge_val = s.get('badge', '?')
        move = s.get('movement', {})
        c1d = move.get('priceChange1d', s.get('technicals', {}).get('change1d', ''))
        c5d = move.get('priceChange5d', s.get('technicals', {}).get('change5d', ''))
        print(f"${sym:<7} {score:>5} {badge_val:<12} {str(c1d):<10} {str(c5d):<10}")
        drivers = s.get('drivers', [])
        if drivers:
            print(f"         Drivers: {', '.join(drivers[:3])}")
def cmd_pulse():
    data = bf_get('market/pulse')
    if not data:
        print("Could not get market pulse")
        return
    print("MARKET PULSE")
    print("=" * 40)
    narrative = data.get('narrative')
    if narrative:
        if isinstance(narrative, dict):
            print(f"\n{narrative.get('summary', '')}")
        else:
            print(f"\n{narrative}")
    counts = data.get('signalCounts', data.get('counts', {}))
    if counts:
        print(f"\nSignal counts:")
        for badge, count in counts.items():
            print(f"  {badge}: {count}")
    trending = data.get('trending', [])
    if trending:
        if isinstance(trending, list):
            print(f"\nTrending: {', '.join(['$' + t.get('symbol', t) if isinstance(t, dict) else '$' + t for t in trending[:8]])}")
        elif isinstance(trending, dict):
            parts = []
            mover = trending.get('biggestMover')
            if mover and isinstance(mover, dict):
                parts.append(f"Biggest mover: ${mover.get('symbol', '?')} (+{mover.get('scoreChange', '?')})")
            sector = trending.get('hottestSector')
            if sector:
                parts.append(f"Hottest sector: {sector}")
            new_ripe_today = trending.get('newRipeToday', [])
            if new_ripe_today:
                symbols = ['$' + s for s in new_ripe_today[:5]]
                parts.append(f"New ripe: {', '.join(symbols)}")
            about = trending.get('aboutToRipe', [])
            if about:
                symbols = ['$' + s for s in about[:5]]
                parts.append(f"About to ripe: {', '.join(symbols)}")
            if parts:
                print(f"\n" + "\n".join(parts))
    new_ripe = data.get('newRipe', [])
    if new_ripe:
        print(f"\nNewly Ripe: {', '.join(['$' + s.get('symbol', s) if isinstance(s, dict) else '$' + s for s in new_ripe[:5]])}")
def main():
    if len(sys.argv) < 2:
        print("Usage: python3 bf-market.py <command> [options]")
        print()
        print("Commands:")
        print("  health              Check system and market status")
        print("  top [--limit N] [--badge ripe|ripening|all]")
        print("                      Show top momentum signals")
        print("  pulse               Market overview and trends")
        sys.exit(1)
    cmd = sys.argv[1].lower()
    if cmd == 'health':
        cmd_health()
    elif cmd == 'top':
        cmd_top(sys.argv[2:])
    elif cmd == 'pulse':
        cmd_pulse()
    else:
        print(f"Unknown command: {cmd}")
        sys.exit(1)
