import json
import sys
import requests
BASE_URL = "https://compute.x402layer.cc"
def browse_regions() -> dict:
    """Fetch available deployment regions."""
    response = requests.get(f"{BASE_URL}/compute/regions", timeout=30)
    if response.status_code != 200:
        return {"error": f"HTTP {response.status_code}", "response": response.text[:500]}
    data = response.json()
    regions = data.get("regions", [])
    print(f"Found {len(regions)} region(s)")
    for r in regions:
        print(f"  {r['id']:6s}  {r['city']}, {r['country']} ({r['continent']})")
    return data
if __name__ == "__main__":
    result = browse_regions()
    if "error" in result:
        print(json.dumps(result, indent=2))
        sys.exit(1)

import logging
import types
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.distributed.tensor import DTensor
logger = logging.getLogger(__name__)
def get_chunkloss_forward_fn():
    def chunkloss_forward(self, hidden_states: torch.Tensor, loss_func: callable):
        # Handle distributed tensor (DTensor) weights and biases by converting to local tensors.
        if isinstance(self.weight, DTensor):
            w = self.weight.to_local()
            if self.bias is not None:
                if not isinstance(self.bias, DTensor):
                    raise TypeError(
                        f"Expected bias to be a DTensor when weight is a DTensor, "
                        f"but got bias of type {type(self.bias)}."
                    )
                b = self.bias.to_local()
            else:
                b = None
        else:
            w = self.weight
            b = self.bias
        loss = loss_func(hidden_states, w, b)
        return loss
    return chunkloss_forward
def apply_chunkloss_module(module):
    chunkloss_forward = get_chunkloss_forward_fn()
    module.forward = types.MethodType(chunkloss_forward, module)
def get_chunkloss_module(modules, plan):
    chunkloss_module = getattr(modules, plan.apply_module, None)
    if chunkloss_module is None:
        raise ValueError(f"{plan.apply_module} does not exists, please set correct apply modules for chunk loss.")
    if not isinstance(chunkloss_module, torch.nn.Linear):
        raise ValueError(f"Chunk loss configuration error for module '{chunkloss_module}': "
                         f"expected torch.nn.Linear, got {repr(type(chunkloss_module))}. ")
    return chunkloss_module

import random
import torch
class CogVideoXI2VProcessor:
    """
    The I2V Processor of CogVideoX:
    1. add noise to first frame
    2. encode the first frame
    3. random dropout image latent
    Args:
        config (dict): the processor config
        {
            "noised_image_all_concat": False,
            "noised_image_dropout": 0.05,
            "noised_image_input": True
        }
    """
    def __init__(self, config):
        self.noised_image_all_concat = config.get("noised_image_all_concat", False)
        self.noised_image_dropout = config.get("noised_image_dropout", 0.05)
        self.noised_image_input = config.get("noised_image_input", True)
    @staticmethod
    def add_noise_to_image(image):
        sigma = torch.normal(mean=-3.0, std=0.5, size=(image.shape[0],)).to(image.device)
        sigma = torch.exp(sigma).to(image.dtype)
        image_noise = torch.randn_like(image) * sigma[:, None, None, None, None]
        image = image + image_noise
        return image
    def __call__(self, vae_model, videos, video_latents, images=None, **kwargs):
        if images is None:
            images = videos[:, 0:1]
        images = images.to(videos.dtype)
        if random.random() < self.noised_image_dropout:
            image_latents = torch.zeros_like(video_latents)
        else:
            if self.noised_image_input:
                images = self.add_noise_to_image(images)
            image_latents = vae_model.encode(images, enable_cp=False)
            if self.noised_image_all_concat:
                image_latents = image_latents.repeat(1, 1, video_latents.size(2), 1, 1)
            else:
                image_latents = torch.concat(
                    [
                        image_latents,
                        torch.zeros_like(video_latents[:, :, 1:])
                    ],
                    dim=2
                )
        return {"masked_video": image_latents}

