                            self.docs_by_resource[f"doc.{doc_name}"] = doc_content

            except Exception as e:
                print(f"Error parsing {yaml_file}: {e}")

    def _parse_sql_models(self):
        """Parse SQL files to find models"""
        sql_files = list(self.project_dir.glob('models/**/*.sql'))

        for sql_file in sql_files:
            model_name = sql_file.stem
            sql_content = self._extract_sql_content(sql_file)

            # Find existing model in resources
            existing_model = next(
                (m for m in self.resources['models'] if m['name'] == model_name),
                None
            )

            if existing_model:
                # Update existing model with SQL content
                existing_model['sql_content'] = sql_content
            else:
                # If not found in YAML, add from SQL file
                description = self._extract_sql_description(sql_file)
                self.resources['models'].append({
                    'name': model_name,
                    'path': str(sql_file),
                    'type': 'model_sql',
                    'description': description,
                    'sql_content': sql_content
                })

                # Store documentation for this model
                if description:
                    self.docs_by_resource[f"model.{model_name}"] = description
            # Check for tests in SQL files (singular tests)
            if 'tests' in str(sql_file) and not any(t['name'] == model_name for t in self.resources['tests']):
                description = self._extract_sql_description(sql_file)
                self.resources['tests'].append({
                    'name': model_name,
                    'path': str(sql_file),
                    'type': 'singular_test',
                    'description': description,
                    'sql_content': self._extract_sql_content(sql_file)
                })
        return self.resources
    def _extract_sql_content(self, sql_file):
        """Extract the SQL content from a file"""
        try:
            with open(sql_file, 'r') as f:
                return f.read()
        except:
            return ''

    def _extract_sql_description(self, sql_file):
        """Extract description from SQL file comments if available"""
        try:
            with open(sql_file, 'r') as f:
                content = f.read()

            # Look for description in SQL comments
            comment_match = re.search(r'/\*\*(.*?)\*/', content, re.DOTALL)
            if comment_match:
                return comment_match.group(1).strip()
            return ''
        except:
            return ''

    def _find_macros(self):
        """Find all macros in the project"""
        macro_files = list(self.project_dir.glob('macros/**/*.sql'))

        for macro_file in macro_files:
            try:
                with open(macro_file, 'r') as f:
                    content = f.read()

                # Extract macro names using regex
                macro_matches = re.findall(r'{%-?\s*macro\s+([a-zA-Z0-9_]+)', content)

                for macro_name in macro_matches:
                    self.resources['macros'].append({
                        'name': macro_name,
                        'path': str(macro_file),
                        'type': 'macro',
                        'sql_content': content,  # Store raw file content
                    })
            except Exception as e:
                print(f"Error parsing macro {macro_file}: {e}")

    def _find_seeds(self):
        """Find all seed files"""
        seed_files = list(self.project_dir.glob('seeds/**/*.csv'))

        for seed_file in seed_files:
            self.resources['seeds'].append({
                'name': seed_file.stem,
                'path': str(seed_file),
                'type': 'seed'
            })

    def get_summary(self):
        """Get a summary of all resources found"""
        summary = {}
        for resource_type, items in self.resources.items():
            summary[resource_type] = len(items)
        return summary

    def export_to_csv(self, output_file):
        """Export all resources to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource Type', 'Name', 'Path', 'Description', 'Additional Info'])

            for resource_type, items in self.resources.items():
                for item in items:
                    # Prepare additional info as a string
                    additional_info = {}
                    for key, value in item.items():
                        if key not in ['name', 'path', 'type', 'description']:
                            additional_info[key] = value

                    writer.writerow([
                        resource_type,
                        item.get('name', ''),
                        item.get('path', ''),
                        item.get('description', ''),
                        str(additional_info) if additional_info else ''
                    ])

    def export_columns_to_csv(self, output_file):
        """Export all columns to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource', 'Column Name', 'Description', 'Data Type', 'Tests', 'Meta'])

            for resource, columns in self.columns_by_resource.items():
                for column in columns:
                    writer.writerow([
                        resource,
                        column.get('name', ''),
                        column.get('description', ''),
                        column.get('data_type', ''),
                        str(column.get('tests', [])),
                        str(column.get('meta', {}))
                    ])

    def export_docs_to_csv(self, output_file):
        """Export all documentation to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource', 'Documentation'])

            for resource, doc in self.docs_by_resource.items():
                writer.writerow([resource, doc])

import re
from datetime import datetime, timedelta
from dateutil import parser as dateutil_parser
from dateutil.relativedelta import relativedelta
# Prefixes commonly prepended by banks to transaction descriptions
STRIP_PREFIXES = [
    r"^POS\s+(DEBIT\s+)?",
    r"^DEBIT\s+(CARD\s+)?(PURCHASE\s+)?",
    r"^ACH\s+(DEBIT\s+|CREDIT\s+)?",
    r"^CHECKCARD\s+\d+\s+",
    r"^PURCHASE\s+(AUTHORIZED\s+ON\s+)?",
    r"^RECURRING\s+(DEBIT\s+|PAYMENT\s+)?",
    r"^VISA\s+DDA\s+",
    r"^PENDING\s+",
    r"^ELECTRONIC\s+",
    r"^ONLINE\s+(BANKING\s+)?(PAYMENT\s+|TRANSFER\s+)?",
    r"^WIRE\s+(TRANSFER\s+)?",
    r"^BILL\s+PAY(MENT)?\s+",
    r"^AUTOPAY\s+",
    r"^MOBILE\s+(PURCHASE\s+)?",
    r"^SQ\s+\*",
    r"^TST\s+\*",
    r"^SP\s+\*?\s*",
]
# Suffixes to strip (dates, card numbers, reference numbers)
STRIP_SUFFIXES = [
    r"\s+\d{2}/\d{2}$",
    r"\s+\d{2}/\d{2}/\d{2,4}$",
    r"\s+\d{4,}$",
    r"\s+#\d+$",
    r"\s+REF\s*#?\s*\d+$",
    r"\s+CARD\s+\d+$",
    r"\s+X{2,}\d{4}$",
    r"\s+\d{2}:\d{2}:\d{2}$",
    r"\s+[A-Z]{2}\s+\d{5}(-\d{4})?$",  # state + zip
]
def clean_merchant_name(description):
    if not description:
        return ""
    name = description.strip().upper()
    for prefix in STRIP_PREFIXES:
        name = re.sub(prefix, "", name, flags=re.IGNORECASE).strip()
    for suffix in STRIP_SUFFIXES:
        name = re.sub(suffix, "", name, flags=re.IGNORECASE).strip()
    # Remove multiple spaces
    name = re.sub(r"\s+", " ", name)
    # Title case for readability
    name = name.title()
    return name
def parse_date(date_str):
    if not date_str:
        return None
    date_str = str(date_str).strip()
    # Common bank date formats
    formats = [
        "%m/%d/%Y",
        "%m/%d/%y",
        "%Y-%m-%d",
        "%m-%d-%Y",
        "%m-%d-%y",
        "%d/%m/%Y",
        "%Y%m%d",
        "%m/%d/%Y %H:%M:%S",
        "%Y-%m-%dT%H:%M:%S",
    ]
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    # Fallback to dateutil
    try:
        return dateutil_parser.parse(date_str).strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return None
def parse_amount(amount_str):
    if amount_str is None:
        return None
    if isinstance(amount_str, (int, float)):
        return round(float(amount_str), 2)
    s = str(amount_str).strip()
    s = s.replace("$", "").replace(",", "").strip()
    # Handle parentheses for negative (accounting style)
    if s.startswith("(") and s.endswith(")"):
        s = "-" + s[1:-1]
    try:
        return round(float(s), 2)
    except ValueError:
        return None
def format_currency(amount):
    if amount is None:
        return "$0.00"
    if amount < 0:
        return f"-${abs(amount):,.2f}"
    return f"${amount:,.2f}"
def resolve_time_reference(text):
    """Resolve natural language time references to (start_date, end_date) tuples."""
    today = datetime.now()
    text = text.lower().strip()
    if text in ("this month", "current month"):
        start = today.replace(day=1)
        end = (start + relativedelta(months=1)) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")
    if text in ("last month", "previous month"):
        start = (today.replace(day=1) - relativedelta(months=1))
        end = today.replace(day=1) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")
    if text in ("this year", "current year", "ytd"):
        start = today.replace(month=1, day=1)
        return start.strftime("%Y-%m-%d"), today.strftime("%Y-%m-%d")
    if text in ("last year", "previous year"):
        start = today.replace(year=today.year - 1, month=1, day=1)
        end = today.replace(year=today.year - 1, month=12, day=31)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")
    if text in ("this week", "current week"):
        start = today - timedelta(days=today.weekday())
        end = start + timedelta(days=6)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")
    if text in ("last week", "previous week"):
        start = today - timedelta(days=today.weekday() + 7)
        end = start + timedelta(days=6)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")
    if text == "today":
        d = today.strftime("%Y-%m-%d")
        return d, d
    if text == "yesterday":
        d = (today - timedelta(days=1)).strftime("%Y-%m-%d")
        return d, d
    # "last N days/weeks/months"
    m = re.match(r"last\s+(\d+)\s+(day|week|month|year)s?", text)
    if m:
        n = int(m.group(1))
        unit = m.group(2)
        if unit == "day":
            start = today - timedelta(days=n)
        elif unit == "week":
            start = today - timedelta(weeks=n)
        elif unit == "month":
            start = today - relativedelta(months=n)
        elif unit == "year":
            start = today - relativedelta(years=n)
        return start.strftime("%Y-%m-%d"), today.strftime("%Y-%m-%d")
    # Month names: "january", "february 2024", etc.
    month_names = {
        "january": 1, "february": 2, "march": 3, "april": 4,
        "may": 5, "june": 6, "july": 7, "august": 8,
        "september": 9, "october": 10, "november": 11, "december": 12,
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "jun": 6, "jul": 7, "aug": 8, "sep": 9, "sept": 9,
        "oct": 10, "nov": 11, "dec": 12,
    }
    m = re.match(r"(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)(?:\s+(\d{4}))?", text)
    if m:
        month = month_names[m.group(1)]
        year = int(m.group(2)) if m.group(2) else today.year
        start = datetime(year, month, 1)
        end = (start + relativedelta(months=1)) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")
    # Try parsing as explicit date range: "2024-01-01 to 2024-01-31"
    m = re.match(r"(\d{4}-\d{2}-\d{2})\s+to\s+(\d{4}-\d{2}-\d{2})", text)
    if m:
        return m.group(1), m.group(2)
    return None, None

import os
def read_file(filename):
    """Read file - CONTAINS PATH TRAVERSAL"""
    # CRITICAL: No path validation - allows ../../../etc/passwd
    base_dir = "/path/to/user/documents"
