import os
import jax
import numpy as np
from MaxText import max_logging, max_utils, maxtext_utils
from MaxText.metric_logger import MetadataKey, MetricLogger
from .max_utils import close_wandb_writer, initialize_wandb_writer
class PrimusMetricLogger(MetricLogger):
    """
    Logger for saving metrics to a local file, GCS and TensorBoard/WandB.
    """
    def __init__(self, config, learning_rate_schedule):
        super().__init__(config, learning_rate_schedule)
        self.wandb_writer = None
        if self.config.enable_wandb:
            self.wandb_writer = initialize_wandb_writer(config)
    def write_metrics(self, metrics, step, is_training=True):
        """Entry point for all metrics writing in Train's Main."""
        super().write_metrics(metrics, step, is_training)
        if self.config.enable_wandb:
            self.write_metrics_to_wandb(metrics, step, is_training)
    def write_metrics_to_wandb(self, metrics, step, is_training):
        """Writes metrics to WandB."""
        if jax.process_index() != 0 or self.wandb_writer is None:
            return
        log_dict = {}
        for name in metrics.get("scalar", []):
            log_dict[name] = float(np.array(metrics["scalar"][name]))
        for name in metrics.get("scalars", []):
            # multi scalars flatten
            for k, v in metrics["scalars"][name].items():
                log_dict[f"{name}/{k}"] = float(v)
        self.wandb_writer.log(log_dict, step=step)
    def write_setup_info_to_tensorboard(self, params):
        """Writes setup information like train config params, num model params, and XLA flags to TensorBoard."""
        num_model_parameters = max_utils.calculate_num_params_from_pytree(params)
        self.metadata[MetadataKey.PER_DEVICE_TFLOPS], _, _ = (
            maxtext_utils.calculate_tflops_training_per_device(self.config)
        )
        self.metadata[MetadataKey.PER_DEVICE_TOKENS] = maxtext_utils.calculate_tokens_training_per_device(
            self.config
        )
        max_logging.log(f"number parameters: {num_model_parameters/1e9:.3f} billion")
        max_utils.add_text_to_summary_writer("num_model_parameters", str(num_model_parameters), self.writer)
        max_utils.add_text_to_summary_writer("libtpu_init_args", os.environ["LIBTPU_INIT_ARGS"], self.writer)
        maxtext_utils.add_config_to_summary_writer(self.config, self.writer)
        if self.wandb_writer is not None:
            self.wandb_writer.log({"num_model_parameters": num_model_parameters})
    def flush_metrics_and_cleanup(self):
        super().flush_metrics_and_cleanup()
        if self.config.enable_wandb:
            close_wandb_writer(self.wandb_writer)

import asyncio
import time
from django.contrib.auth import authenticate, login, logout
from django.http import JsonResponse, StreamingHttpResponse
from django.shortcuts import redirect
from django.urls import reverse
import test_data
async def index(request):
    return JsonResponse(test_data.JSON_1K, safe=False)
async def sse(request):
    """Server-Sent Events endpoint that sends timestamp data every second."""
    async def gen():
        while True:
            await asyncio.sleep(1)
            yield f"data: {time.time()}\n\n"
    return StreamingHttpResponse(gen(), content_type="text/event-stream")
def accounts_index(request):
    """Mounted Django accounts testing index."""
    base = reverse("accounts-index").rstrip("/")
    return JsonResponse(
        {
            "source": "django_mount",
            "message": "Mounted Django accounts test endpoints",
            "endpoints": {
                "login": reverse("accounts-login"),
                "logout": reverse("accounts-logout"),
                "profile": reverse("accounts-profile"),
                "provider_callback": f"{reverse('accounts-provider-callback')}?code=demo&state=xyz",
                "django_auth_urls": f"{base}/auth/",
                "allauth_if_installed": f"{base}/allauth/",
            },
        }
    )
def accounts_login(request):
    """
    Minimal login endpoint for mounted-Django testing.
    POST form fields:
    - username
    - password
    - next (optional, default: /accounts/profile/)
    """
    if request.method == "GET":
        return JsonResponse(
            {
                "source": "django_mount",
                "action": "login",
                "method": "POST",
                "required_fields": ["username", "password"],
                "optional_fields": ["next"],
            }
        )
    username = request.POST.get("username") or request.GET.get("username")
    password = request.POST.get("password") or request.GET.get("password")
    next_url = request.POST.get("next") or request.GET.get("next") or reverse("accounts-profile")
    if not username or not password:
        return JsonResponse(
            {"ok": False, "error": "username and password are required"},
            status=400,
        )
    user = authenticate(request, username=username, password=password)
    if user is None:
        return JsonResponse({"ok": False, "error": "invalid credentials"}, status=401)
    login(request, user)
    return redirect(next_url)
def accounts_logout(request):
    """Logout endpoint for mounted-Django testing."""
    logout(request)
    return redirect(reverse("accounts-login"))
def accounts_profile(request):
    """Simple auth state endpoint for mounted-Django testing."""
    user = request.user
    is_authenticated = bool(getattr(user, "is_authenticated", False))
    return JsonResponse(
        {
            "source": "django_mount",
            "authenticated": is_authenticated,
            "username": user.get_username() if is_authenticated else None,
        }
    )
def accounts_provider_callback(request):
    """
    Simulates an OAuth provider callback endpoint (allauth-style URL shape).
    Example:
    /accounts/provider/callback/?code=demo-code&state=demo-state
    """
    return JsonResponse(
        {
            "source": "django_mount",
            "action": "provider_callback",
            "query": dict(request.GET.items()),
        }
    )

import json
import sys
from pypdf import PdfReader
# Extracts data for the fillable form fields in a PDF and outputs JSON that
# Claude uses to fill the fields. See forms.md.
# This matches the format used by PdfReader `get_fields` and `update_page_form_field_values` methods.
def get_full_annotation_field_id(annotation):
    components = []
    while annotation:
        field_name = annotation.get('/T')
        if field_name:
            components.append(field_name)
        annotation = annotation.get('/Parent')
    return ".".join(reversed(components)) if components else None
def make_field_dict(field, field_id):
    field_dict = {"field_id": field_id}
    ft = field.get('/FT')
    if ft == "/Tx":
        field_dict["type"] = "text"
    elif ft == "/Btn":
        field_dict["type"] = "checkbox"  # radio groups handled separately
        states = field.get("/_States_", [])
        if len(states) == 2:
            # "/Off" seems to always be the unchecked value, as suggested by
            # https://opensource.adobe.com/dc-acrobat-sdk-docs/standards/pdfstandards/pdf/PDF32000_2008.pdf#page=448
            # It can be either first or second in the "/_States_" list.
            if "/Off" in states:
                field_dict["checked_value"] = states[0] if states[0] != "/Off" else states[1]
                field_dict["unchecked_value"] = "/Off"
            else:
                print(f"Unexpected state values for checkbox `${field_id}`. Its checked and unchecked values may not be correct; if you're trying to check it, visually verify the results.")
                field_dict["checked_value"] = states[0]
                field_dict["unchecked_value"] = states[1]
    elif ft == "/Ch":
        field_dict["type"] = "choice"
        states = field.get("/_States_", [])
        field_dict["choice_options"] = [{
            "value": state[0],
            "text": state[1],
        } for state in states]
    else:
        field_dict["type"] = f"unknown ({ft})"
    return field_dict
# Returns a list of fillable PDF fields:
# [
#   {
#     "field_id": "name",
#     "page": 1,
#     "type": ("text", "checkbox", "radio_group", or "choice")
#     // Per-type additional fields described in forms.md
#   },
# ]
def get_field_info(reader: PdfReader):
    fields = reader.get_fields()
    field_info_by_id = {}
    possible_radio_names = set()
    for field_id, field in fields.items():
        # Skip if this is a container field with children, except that it might be
        # a parent group for radio button options.
        if field.get("/Kids"):
            if field.get("/FT") == "/Btn":
                possible_radio_names.add(field_id)
            continue
        field_info_by_id[field_id] = make_field_dict(field, field_id)
    # Bounding rects are stored in annotations in page objects.
    # Radio button options have a separate annotation for each choice;
    # all choices have the same field name.
    # See https://westhealth.github.io/exploring-fillable-forms-with-pdfrw.html
    radio_fields_by_id = {}
    for page_index, page in enumerate(reader.pages):
        annotations = page.get('/Annots', [])
        for ann in annotations:
            field_id = get_full_annotation_field_id(ann)
            if field_id in field_info_by_id:
                field_info_by_id[field_id]["page"] = page_index + 1
                field_info_by_id[field_id]["rect"] = ann.get('/Rect')
            elif field_id in possible_radio_names:
                try:
                    # ann['/AP']['/N'] should have two items. One of them is '/Off',
                    # the other is the active value.
                    on_values = [v for v in ann["/AP"]["/N"] if v != "/Off"]
                except KeyError:
                    continue
                if len(on_values) == 1:
                    rect = ann.get("/Rect")
                    if field_id not in radio_fields_by_id:
                        radio_fields_by_id[field_id] = {
                            "field_id": field_id,
                            "type": "radio_group",
                            "page": page_index + 1,
                            "radio_options": [],
                        }
                    # Note: at least on macOS 15.7, Preview.app doesn't show selected
                    # radio buttons correctly. (It does if you remove the leading slash
                    # from the value, but that causes them not to appear correctly in
                    # Chrome/Firefox/Acrobat/etc).
                    radio_fields_by_id[field_id]["radio_options"].append({
                        "value": on_values[0],
                        "rect": rect,
                    })
    # Some PDFs have form field definitions without corresponding annotations,
    # so we can't tell where they are. Ignore these fields for now.
    fields_with_location = []
    for field_info in field_info_by_id.values():
        if "page" in field_info:
            fields_with_location.append(field_info)
        else:
            print(f"Unable to determine location for field id: {field_info.get('field_id')}, ignoring")
    # Sort by page number, then Y position (flipped in PDF coordinate system), then X.
    def sort_key(f):
        if "radio_options" in f:
            rect = f["radio_options"][0]["rect"] or [0, 0, 0, 0]
        else:
            rect = f.get("rect") or [0, 0, 0, 0]
        adjusted_position = [-rect[1], rect[0]]
        return [f.get("page"), adjusted_position]
    sorted_fields = fields_with_location + list(radio_fields_by_id.values())
    sorted_fields.sort(key=sort_key)
    return sorted_fields
def write_field_info(pdf_path: str, json_output_path: str):
    reader = PdfReader(pdf_path)
    field_info = get_field_info(reader)
    with open(json_output_path, "w") as f:
        json.dump(field_info, f, indent=2)
    print(f"Wrote {len(field_info)} fields to {json_output_path}")
