import importlib.abc
import importlib.util
import sys
from collections import defaultdict
import wrapt
from ucm.logger import init_logger
logger = init_logger(__name__)
_POST_IMPORT_HOOKS = defaultdict(list)
class HookingFinder(importlib.abc.MetaPathFinder):
    """
    A custom Finder that intercepts the import process to wrap the Loader.
    It doesn't load code itself but attaches a post-load hook to the module's loader.
    """
    def find_spec(self, fullname, path, target=None):
        if fullname not in _POST_IMPORT_HOOKS:
            return None
        meta_path_original = sys.meta_path[:]
        sys.meta_path = [x for x in sys.meta_path if not isinstance(x, HookingFinder)]
        try:
            spec = importlib.util.find_spec(fullname, path)
            if spec is None or spec.loader is None:
                return None
            orig_loader = spec.loader
            class PostImportLoader(importlib.abc.Loader):
                """Wraps the original loader to execute hooks after exec_module."""
                def create_module(self, spec):
                    return orig_loader.create_module(spec)
                def exec_module(self, module):
                    orig_loader.exec_module(module)
                    if fullname in _POST_IMPORT_HOOKS:
                        try:
                            for hook in _POST_IMPORT_HOOKS[fullname]:
                                hook(module)
                        except Exception as e:
                            logger.error(
                                f"Error executing post-import hooks for {fullname}: {e}"
                            )
                            raise
            spec.loader = PostImportLoader()
            return spec
        finally:
            sys.meta_path = meta_path_original
            sys.path_importer_cache.clear()
class PatchOpProxy(wrapt.ObjectProxy):
    """
    Specifically designed for patching PyTorch operators (torch.ops).
    This is tailored for operators registered via vLLM's 'direct_register_custom_op'.
    """
    def __init__(self, wrapped, impl, fake_impl=None):
        super(PatchOpProxy, self).__init__(wrapped)
        self._self_impl = impl
        self._self_fake_impl = fake_impl or getattr(wrapped, "fake_impl", None)
    def __call__(self, *args, **kwargs):
        return self._self_impl(*args, **kwargs)
    @property
    def fake_impl(self):
        return self._self_fake_impl
_FINDER = HookingFinder()
if not any(isinstance(x, HookingFinder) for x in sys.meta_path):
    sys.meta_path.insert(0, _FINDER)
def when_imported(module_name):
    """
    Decorator to register a function to be called as soon as a module is imported.
    """
    def decorator(func):
        if module_name not in _POST_IMPORT_HOOKS:
            _POST_IMPORT_HOOKS[module_name] = []
        _POST_IMPORT_HOOKS[module_name].append(func)
        if module_name in sys.modules:
            mod = sys.modules[module_name]
            if not getattr(mod, "_ucm_patched", False):
                setattr(mod, "_ucm_patched", True)
                func(mod)
        return func
    return decorator
def patch_dataclass_fields(
    target_cls, src_cls, *, include_methods=True, include_ext=True
):
    """
    Structural migration for dataclasses.
    Designed to replace or extend dataclass field definitions from src_cls to target_cls.
    """
    target_cls.__annotations__ = getattr(src_cls, "__annotations__", {})
    target_cls.__dataclass_fields__ = getattr(src_cls, "__dataclass_fields__", {})
    target_cls.__dataclass_params__ = getattr(src_cls, "__dataclass_params__", None)
    for method_name in ["__init__", "__post_init__"]:
        if hasattr(src_cls, method_name):
            setattr(target_cls, method_name, getattr(src_cls, method_name))
    if include_methods:
        for method_name in [
            "__repr__",
            "__eq__",
            "__hash__",
            "__ne__",
            "__lt__",
            "__le__",
            "__gt__",
            "__ge__",
        ]:
            if hasattr(src_cls, method_name):
                setattr(target_cls, method_name, getattr(src_cls, method_name))
    if include_ext and hasattr(src_cls, "__match_args__"):
        target_cls.__match_args__ = src_cls.__match_args__
    return target_cls
def _get_replace_wrapper(new_func):
    def wrapper(wrapped, instance, args, kwargs):
        if instance is not None:
            return new_func(instance, *args, **kwargs)
        return new_func(*args, **kwargs)
    return wrapper
def patch_or_inject(target_obj, func_name, replacement_func):
    """
    A general-purpose utility to modify objects or modules.
    If the function exists, it wraps it;
    if it doesn't exist, it injects it.
    """
    if hasattr(target_obj, func_name):
        wrapt.wrap_function_wrapper(
            target_obj, func_name, _get_replace_wrapper(replacement_func)
        )
        logger.debug(
            f"Wrapped: {getattr(target_obj, '__name__', 'module')}.{func_name}"
        )
    else:
        setattr(target_obj, func_name, replacement_func)
        logger.debug(
            f"Injected: {getattr(target_obj, '__name__', 'module')}.{func_name}"
        )

import logging
import os
from datetime import datetime
from flask import Blueprint, request, jsonify, redirect, send_file
from app.web import (
    require_auth, _auth_required,
    get_config_manager, get_on_config_changed,
    _get_client_ip,
)
from werkzeug.utils import secure_filename
audit_log = logging.getLogger("docsis.audit")
log = logging.getLogger("docsis.web")
bp = Blueprint("backup_bp", __name__)
@bp.route("/api/backup", methods=["POST"])
@require_auth
def api_backup_download():
    """Create a backup and stream it as download."""
    _config_manager = get_config_manager()
    if not _config_manager:
        return jsonify({"error": "Not initialized"}), 500
    try:
        from .backup import create_backup
        buf = create_backup(_config_manager.data_dir)
        ts = datetime.now().strftime("%Y-%m-%d_%H%M%S")
        filename = f"docsight_backup_{ts}.tar.gz"
        audit_log.info("Backup downloaded: ip=%s", _get_client_ip())
        return send_file(buf, mimetype="application/gzip", as_attachment=True, download_name=filename)
    except Exception as e:
        log.error("Backup creation failed: %s", e)
        return jsonify({"error": str(e)}), 500
@bp.route("/api/backup/scheduled", methods=["POST"])
@require_auth
def api_backup_scheduled():
    """Create a backup in the configured backup path."""
    _config_manager = get_config_manager()
    if not _config_manager:
        return jsonify({"error": "Not initialized"}), 500
    backup_path = _config_manager.get("backup_path", "/backup")
    retention = _config_manager.get("backup_retention", 5)
    try:
        from .backup import create_backup_to_file, cleanup_old_backups
        filename = create_backup_to_file(_config_manager.data_dir, backup_path)
        cleanup_old_backups(backup_path, keep=retention)
        audit_log.info("Scheduled backup created: ip=%s file=%s", _get_client_ip(), filename)
        return jsonify({"success": True, "filename": filename})
    except Exception as e:
        log.error("Scheduled backup failed: %s", e)
        return jsonify({"error": str(e)}), 500
@bp.route("/api/backup/list")
@require_auth
def api_backup_list():
    """List backups in the configured backup path."""
    _config_manager = get_config_manager()
    if not _config_manager:
        return jsonify([])
    backup_path = _config_manager.get("backup_path", "/backup")
    from .backup import list_backups
    return jsonify(list_backups(backup_path))
@bp.route("/api/backup/<filename>", methods=["DELETE"])
@require_auth
def api_backup_delete(filename):
    """Delete a backup file."""
    _config_manager = get_config_manager()
    if not _config_manager:
        return jsonify({"error": "Not initialized"}), 500
    backup_path = _config_manager.get("backup_path", "/backup")
    safe_name = secure_filename(filename)
    if not safe_name or safe_name != filename:
        return jsonify({"error": "Invalid filename"}), 400
    fpath = os.path.join(backup_path, safe_name)
    real_fpath = os.path.realpath(fpath)
    real_backup = os.path.realpath(backup_path)
    if not real_fpath.startswith(real_backup + os.sep):
        return jsonify({"error": "Invalid path"}), 400
    if not os.path.exists(real_fpath):
        return jsonify({"error": "Not found"}), 404
    os.remove(real_fpath)
    audit_log.info("Backup deleted: ip=%s file=%s", _get_client_ip(), safe_name)
    return jsonify({"success": True})
@bp.route("/api/restore/validate", methods=["POST"])
def api_restore_validate():
    """Validate a backup archive and return metadata.
    No auth required during initial setup (not configured yet).
    Auth required if already configured.
    """
    _config_manager = get_config_manager()
    if _config_manager and _config_manager.is_configured() and _auth_required():
        return redirect("/login")
    if "file" not in request.files:
        return jsonify({"error": "No file provided"}), 400
    f = request.files["file"]
    if not f.filename:
        return jsonify({"error": "No file selected"}), 400
    data = f.read()
    if len(data) > 500 * 1024 * 1024:  # 500 MB limit
        return jsonify({"error": "File too large"}), 400
    try:
        from .backup import validate_backup
        meta = validate_backup(data)
        return jsonify({"valid": True, "meta": meta})
    except ValueError as e:
        return jsonify({"valid": False, "error": str(e)}), 400
@bp.route("/api/restore", methods=["POST"])
def api_restore():
    """Restore a backup archive.
    No auth required during initial setup (not configured yet).
    Auth required if already configured.
    """
    _config_manager = get_config_manager()
    if _config_manager and _config_manager.is_configured() and _auth_required():
        return redirect("/login")
    if "file" not in request.files:
        return jsonify({"error": "No file provided"}), 400
    f = request.files["file"]
    if not f.filename:
        return jsonify({"error": "No file selected"}), 400
    data = f.read()
    if len(data) > 500 * 1024 * 1024:
        return jsonify({"error": "File too large"}), 400
    try:
        from .backup import restore_backup
        data_dir = _config_manager.data_dir if _config_manager else "/data"
        result = restore_backup(data, data_dir)
        audit_log.info(
            "Backup restored: ip=%s files=%s",
            _get_client_ip(), result["restored_files"],
        )
        # Reload config so the app recognizes the restored state
        if _config_manager:
            _config_manager._load()
        _on_config_changed = get_on_config_changed()
        if _on_config_changed:
            _on_config_changed()
        configured = bool(_config_manager and _config_manager.is_configured())
        return jsonify({
            "success": True,
            "restored_files": result["restored_files"],
            "configured": configured,
        })
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    except Exception as e:
        log.error("Restore failed: %s", e)
        return jsonify({"error": str(e)}), 500
@bp.route("/api/browse")
