# Define Epoch class inheriting from datetime.datetime
class Epoch(datetime.datetime):
    # Julian Date property
    @property
    def jd(self):
        jd = (367.0 * self.year
              - np.floor((7 * (self.year + np.floor((self.month + 9) / 12.0))) * 0.25)
              + np.floor(275 * self.month / 9.0)
              + self.day + 1721013.5
              + ((self.second / 60.0 + self.minute) / 60.0 + self.hour) / 24.0)
        return jd

    # JD2000 property (Julian Date relative to J2000.0)
    @property
    def jd2000(self):
        return self.jd - 2451544.5

    # JD1950 property (Julian Date relative to J1950.0)
    @property
    def jd1950(self):
        return self.jd - 2433282.5

    # Modified Julian Date property
    @property
    def mjd(self):
        return self.jd - 2400000.5

