from typing import Dict, Any
import attr

@attr.s(slots=True)
class Rule:
    """
    A rule describes how and when to make backups.
    """
    # Basic attributes for the rule
    name = attr.ib()
    namespace = attr.ib()
    deltas = attr.ib()
    gce_disk = attr.ib()
    gce_disk_zone = attr.ib()
    claim_name = attr.ib()

    @property
    def pretty_name(self):
        """Returns claim_name if available, otherwise returns name."""
        return self.claim_name or self.name

    def to_dict(self) -> Dict[str, Any]:
        """Helper method: converts the instance to a dictionary."""
        return attr.asdict(self)

    def __str__(self):
        """String representation of the rule."""
        return self.name

