        """Show a dialog window with a 'message' next an image 'type'"""
        subprocess.run(["zenity", "--warning",
                        "--text={}".format(message)])

    def error_dialog(self, message: str):
        """Show a dialog window with a 'message' next an image 'type'"""
        subprocess.run(["zenity", "--error",
                        "--text={}".format(message)])

