    SUBVERSIONS = {
        3: 0,
    }

    @classmethod
    def convert(cls, event_details, dict_version):
        # Dictionary mapping versions to their converter methods
        CONVERTERS = {
            3: cls.eventDetailsConverter_v3,
        }

        # Call the appropriate converter based on version
        return CONVERTERS[dict_version](event_details)

