# Import necessary modules
import copy
import os
from subprocess import STDOUT, run as _run, CalledProcessError, TimeoutExpired

# This env stuff is to catch glibc errors, because
# it apparently prints to /dev/tty instead of stderr.
# (see http://stackoverflow.com/a/27797579)
ENV = copy.copy(os.environ)
ENV["LIBC_FATAL_STDERR_"] = "1"

def run(cmd, input_data=None, timeout=None):
    status = 'success'

    try:
        result = _run(
            cmd,
            stderr=STDOUT,
            timeout=timeout,
            input=input_data,
            env=ENV,
            check=True
        )

    except CalledProcessError as err:
        status = 'called process error'
        result = err.output if err.output else str(err)

    except TimeoutExpired as err:
        status = 'timed out after {} seconds'.format(timeout)
        result = err.output if err.output else str(err)

    except FileNotFoundError as err:
        status = 'not found'
        result = str(err)

    except ProcessLookupError as err:
        try:
            status, result = run(cmd, input_data=input_data, timeout=timeout)
        except:
            status = 'process lookup error'
            result = str(err)

    try:
        if not isinstance(result, str):
            result = str(result, 'utf-8')
    except UnicodeDecodeError:
        result = str(result, 'cp437')

    return (status, result)

# Import necessary modules
import sys
import lxml.etree

# Custom exception for XPath errors
class XPathError(Exception):
    pass

# Parse XML from a file
def parse_xml_filename(filename):
    return lxml.etree.parse(filename)

# Compile an XPath query string
def compile_xpath(query):
    try:
        return lxml.etree.XPath(query)
    except lxml.etree.XPathSyntaxError as e:
        # Re-raise with custom exception, preserving traceback
        raise XPathError(e.msg), None, sys.exc_info()[2]

# Register custom XPath extensions
def register_extensions():
    ns = lxml.etree.FunctionNamespace(None)
    ns['is_call'] = is_call

# Check if the current node represents a function call to specified names
def is_call(context, *names):
    node = context.context_node

    # Must be a ParameterizedExpr
    if node.tag != 'ParameterizedExpr':
        return False

    # First child must be a NameExpr with kind='FUN'
    if node[0].tag != 'NameExpr' or node[0].get('kind') != 'FUN':
        return False

    # Extract the called function name
    called_name = node[0][0].get('nameId')

    # Compare against provided names (supports both strings and lists)
    for name in names:
        if isinstance(name, basestring) and called_name == name:
            return True
        elif any(called_name == n for n in name):
            return True

    return False

