import collections
import typing

# Define Meta class inheriting from OrderedDict and MutableMapping
class Meta(collections.OrderedDict, typing.MutableMapping[str, float]):
    def __init__(self, *args, **kwargs) -> None:
        # Initialize tracking variables
        self._smallest = float('inf')
        self._largest = 0
        self._ordered = True
        super(Meta, self).__init__(*args, **kwargs)

    def __setitem__(self, key: str, value: float) -> None:
        # Check for redundant assignment
        if key in self and self[key] == value:
            raise AssertionError('Redundant assignment')

        # Update ordering state and tracking values
        if value > self._smallest:
            self._ordered = False
        else:
            self._smallest = value

        if value > self._largest:
            self._largest = value

        # Set the item and notify of change
        super(Meta, self).__setitem__(key, value)
        self._changed()

    def items(self) -> typing.ItemsView[str, float]:
        # Ensure items are ordered before returning
        self._reorder()
        return super(Meta, self).items()

    def first(self) -> typing.Tuple[str, float]:
        # Return the first (smallest value) item as a tuple
        self._reorder()
        for k, v in self.items():
            return k, v

    def peek(self) -> str:
        # Return the key of the first item without removing it
        self._reorder()
        for first in self:
            return first

    def magnitude(self) -> float:
        # Return the largest value stored
        return self._largest

    def _reorder(self) -> None:
        # Reorder items by value in descending order if not already ordered
        if self._ordered:
            return
        order = sorted(super(Meta, self).items(), key=lambda x: x[1], reverse=True)
        for k, v in order:
            self.move_to_end(k)
        self._ordered = True

    def _changed(self):
        # Placeholder method for subclasses to override
        pass

