from collections import OrderedDict

def _convert_sheets_to_lists(content):
    # Convert spreadsheet content to list format with headers
    cols = OrderedDict()

    if not content or len(content) == 0:
        return [], None

    # Extract column names from first row if it's a list
    if isinstance(content[0], list):
        cols.update(OrderedDict.fromkeys(content[0]))

    # Update columns with keys from dict rows
    for row in content:
        if isinstance(row, dict):
            cols.update(OrderedDict.fromkeys(row.keys()))

    # Get the final column list
    cols = cols.keys()

    # Build output content
    out_content = []
    _valid = False

    for row in content:
        out_row = []
        for col in cols:
            _val = row.get(col, '')
            if _val is None:
                _val = ''
            out_row.append(_val)

        if len(out_row) > 0:
            _valid = True

        out_content.append(out_row)

    return cols, out_content if _valid else None


def ss_structure_to_mdtable(content):
    """
    receives a dict or OrderedDict with arrays of arrays representing
    a spreadsheet, and returns a markdown document with tables
    """
    import tabulate

    out_sheets = OrderedDict()
    output = []

    def cell_to_str(cell):
        return '' if cell is None else str(cell)

    for (sheet_name, contents) in content.items():
        out_sheets[sheet_name] = output
        (headers, content) = _convert_sheets_to_lists(contents)

        if content:
            output.append('#{}'.format(sheet_name))
            output.append(tabulate.tabulate(
                content,
                headers=headers,
                tablefmt="orgtbl"
            ))

    return '\n\n'.join(output)

# Parser implementation for Django query transformation
from django.db.models.expressions import Star
from django.db.models.sql.datastructures import EmptyResultSet
from django.db.models.sql.where import SubqueryConstraint
from .version_19 import Parser as BaseParser

class Parser(BaseParser):
    def _prepare_for_transformation(self):
        from django.db.models.sql.where import EmptyWhere

        # Check if the WHERE clause is empty
        if isinstance(self.django_query.where, EmptyWhere):
            # Empty where means return nothing!
            raise EmptyResultSet()

    def _where_node_leaf_callback(self, node, negated, new_parent, connection, model, compiler):
        # Skip subquery constraints as they are handled by parent method
        if not isinstance(node, SubqueryConstraint):
            # Check for empty Q() objects (leaf nodes without lhs/rhs)
            if not hasattr(node, "lhs") and not hasattr(node, "rhs"):
                # Empty Q() object - basically an empty where node that needs nothing doing to it
                return

        # Delegate to parent class for further processing
        return super(Parser, self)._where_node_leaf_callback(node, negated, new_parent, connection, model, compiler)

    def _determine_query_kind(self):
        query = self.django_query

        # Check if annotations exist and specifically look for COUNT operations
        if query.annotations:
            if "__count" in query.annotations:
                field = query.annotations["__count"].input_field

                # Handle both Star (*) and explicit "*" value cases
                if isinstance(field, Star) or field.value == "*":
                    return "COUNT"

        # Default to SELECT query type
        return "SELECT"

