from math import factorial
from random import randrange

# Analytical function to compute expected value
def analytical(n):
    # Sum over i from 1 to n of (n! / (n^i * (n-i)!))
    return sum(
        factorial(n) / pow(n, i) / float(factorial(n - i))
        for i in range(1, n + 1)
    )

# Testing function using Monte Carlo simulation
def testing(n, times):
    total_count = 0

    # Run simulation 'times' iterations
    for _ in range(times):
        x, bits = 1, 0

        # Continue until all bits are set (collision detected)
        while not (bits & x):
            total_count += 1
            bits |= x
            x = 1 << randrange(n)

    # Return average count
    return total_count / times

