    # the best language to attempt this in. Doing so causes a RecursionError
    # to be raised. Also of note: using a decorator like `functools.lru_cache`
    # for memoization causes the recursion limit to be reached more quickly.
    # See: http://stackoverflow.com/questions/15239123/maximum-recursion-depth-reached-faster-when-using-functools-lru-cache.

    while n > 1:
        length += 1

        if n % 2 == 0:
            n /= 2
        else:
            n = (3 * n) + 1

    return length


# Function to find the longest Collatz sequence up to a given ceiling
def longest_collatz_sequence(ceiling):
    longest_chain = {
        'number': 1,
        'length': 1
    }

    for i in range(ceiling):
        length = collatz_sequence(i)

        if length > longest_chain['length']:
            longest_chain = {
                'number': i,
                'length': length
            }

    return longest_chain

# Import necessary modules
from __future__ import print_function
import json
import sys
import re

def parse_select(sel_str):
    steps = []
    match_rule = None

    # Process each word in the selector string
    for word in sel_str.strip().split(' '):
        if match_rule:
            if match_rule == '=':
                # Exact match rule
                steps.append(lambda data, word=word: data == word)
            elif match_rule == '=~':
                # Regex match rule
                matcher = re.compile(word)
                steps.append(lambda data: isinstance(data, unicode) and matcher.match(data))

            match_rule = None
            continue

        match_rule = None

        # Handle special characters and tokens
        if word == '{':
            # Start nested selector block
            parent_steps, test_steps = steps, []
            steps = test_steps
        elif word == '}':
            # End nested selector block
            parent_steps.append(lambda data, steps=test_steps: match_selector(steps, data))
            steps = parent_steps
            parent_steps, test_steps = None, None
        elif word in {'=', '=~'}:
            match_rule = word
        elif word.isdigit():
            steps.append(int(word))
        else:
            steps.append(word)

    return steps

def match_selector(selector, data):
    current = data

    for i, step in enumerate(selector):
        if callable(step):
            # Execute callable step (lambda function)
            if step(current):
                continue
            else:
                return False

        if isinstance(step, int):
            # Index into list
            current = current[step]
        else:
            # String key lookup
            if isinstance(current, list):
                # For lists, try to match in each item
                selector_trail = selector[i:]
                for item in current:
                    if match_selector(selector_trail, item):
                        return item
                return False
            else:
                # Dictionary lookup
                current = current.get(step)

        if current is None:
            return False

    return current

if __name__ == '__main__':
    args = sys.argv[1:]

    # Parse selector from command line arguments
    selector = parse_select(args.pop(0)) if args else None

    match_count = 0

    # Process input line by line
    for i, l in enumerate(sys.stdin):
        if not l.rstrip():
            continue

        # Handle escaped quotes
        l = l.replace(b'\\\\"', b'\\"')

        # Progress indicator every 100k lines
        if i % 100000 == 0:
            print("At line", i, file=sys.stderr)

        try:
            # Parse JSON
            data = json.loads(l)

            # Extract ID
            try:
                data_id = data.get('@id') or data['@graph'][0]['@id']
            except KeyError:
                data_id = None

            # Apply selector if provided
            if selector:
                result = match_selector(selector, data)
                if result:
                    match_count += 1
                    print("Line", i, "id", data_id, "matched on", json.dumps(result))
                    sys.stdout.flush()

        except ValueError as e:
            # Handle JSON parsing errors
            print("ERROR at", i, "in data:", file=sys.stderr)
            print(l, file=sys.stderr)
            print(e, file=sys.stderr)

            # Show context around error position
            for char_index in re.findall(r'.+\(char (\d+)\)$', e.message):
                char_index = int(char_index)
                start = char_index - 20 if char_index > 20 else char_index
                end = char_index + 20
                print(l[start:end], file=sys.stderr)
                print(('-' * 20) + '^', file=sys.stderr)
                break

    # Output total matches if selector was used
    if selector:
        print("Total matches:", match_count)

