from __future__ import unicode_literals

from django.db.transaction import atomic
from django.db import migrations
from shuup.core.models import Shop
from shuup.xtheme.models import SavedViewConfig, ThemeSettings


@atomic
def convert_shop_themes(*args):
    # Process ThemeSettings for shops without theme settings
    for theme_setting in ThemeSettings.objects.filter(shop__isnull=True):
        for (index, shop) in enumerate(Shop.objects.all()):
            # Skip if theme already exists for this shop
            if ThemeSettings.objects.filter(
                shop=shop,
                theme_identifier=theme_setting.theme_identifier
            ).exists():
                continue

            # The first shop gets the original object; others get copies
            if index > 0:
                theme_setting.pk = None

            theme_setting.shop = shop
            theme_setting.save()

    # Process SavedViewConfig for shops without saved configs
    for saved_config in SavedViewConfig.objects.filter(shop__isnull=True):
        for (index, shop) in enumerate(Shop.objects.all()):
            # Skip if saved config already exists for this shop
            if SavedViewConfig.objects.filter(
                shop=shop,
                theme_identifier=saved_config.theme_identifier
            ).exists():
                continue

            # The first shop gets the original object; others get copies
            if index > 0:
                saved_config.pk = None

            saved_config.shop = shop
            saved_config.save()


class Migration(migrations.Migration):
    dependencies = [
        ('shuup_xtheme', '0003_shop_theme'),
    ]

    operations = [
        migrations.RunPython(convert_shop_themes, migrations.RunPython.noop)
    ]

# Import necessary modules
import logging
LOGGER = logging.getLogger('BigML')
import numbers
from bigml.model import Model

def avg(data):
    """Calculate the average of a list of numbers."""
    return float(sum(data)) / len(data) if len(data) > 0 else float('nan')

class MultipleModel(object):
    """A multiple local model.

    Uses a number of BigML remote models to build a local version that can be
    used to generate predictions locally using majority voting for classification
    and average voting for regression.
    """

    def __init__(self, models):
        self.models = []

        # Handle both single model and list of models
        if isinstance(models, list):
            for model in models:
                self.models.append(Model(model))
        else:
            # Note: Original code has typo 'apend' instead of 'append'
            self.models.append(Model(models))

    def predict(self, input_data):
        """Makes a prediction based on the prediction made by every model.

        For regression tasks, returns the average of all model predictions.
        For classification tasks, returns the mode (most frequent prediction).
        """
        predictions = []

        # Collect predictions from all models
        for model in self.models:
            predictions.append(model.predict(input_data, by_name=False))

        # Check if all predictions are numeric (regression)
        if all([isinstance(prediction, numbers.Number) for prediction in predictions]):
            return avg(predictions)
        else:
            # Classification: find the most frequent prediction
            mode = {}
            for prediction in predictions:
                if prediction in mode:
                    mode[prediction] = mode[prediction] + 1
                else:
                    mode[prediction] = 1
            return max(mode, key=mode.get)

# Import necessary module
from virtool.pathoscope import sam

def run(isolate_sam, host_sam, snap=False):
    # Get a mapping score for every read mapped to the host genome
    host_scores = sam.all_scores(host_sam, snap=snap)

    # This list will contain the read_ids for all reads that had better mapping qualities against the host
    # genome
    skipped = list()
    subtracted_list = list()

    for line in isolate_sam:
        # Parse the virus SAM file and get the alignment score for each line
        if line[0] in ["#", "@"]:
            subtracted_list.append(line)
            continue

        l = line.split("\t")
        read_id = l[0]
        virus_score = sam.get_score(l, snap=snap)

        # Write each line from the virus SAM to a new file if its score is better against the virus
        # than the host. Discard it if it isn't and add the read_id to the list of skipped reads
        if virus_score is not None:
            try:
                if host_scores[read_id] >= virus_score:
                    subtracted_list.append(line)
                else:
                    skipped.append(read_id)
            except KeyError:
                subtracted_list.append(line)

    # Return the number of read mapping that were eliminated due to higher similarity to the host than to
    # the intitially mapped virus
    return subtracted_list, len((set(skipped)))

# Migration script to handle duplicate preprint_license_updated logs
import sys
import logging

from modularodm import Q
from framework.transactions.context import TokuTransaction
from scripts import utils as script_utils
from website.app import init_app
from website.project.model import Node, NodeLog

logger = logging.getLogger(__name__)

# This is where all your migration log will go


def do_migration():
    # Find nodes with multiple 'preprint_license_updated' logs
    dupe_nodes = [
        n for n in Node.find(
            Q('_id', 'in', list(set([
                l.node._id for l in NodeLog.find(Q('action', 'eq', 'preprint_license_updated'))
            ])))
        ) if NodeLog.find(
            Q('action', 'eq', 'preprint_license_updated') &
            Q('node', 'eq', n._id)
        ).count() > 1
    ]

    logger.info('Found {} nodes with multiple preprint_license_updated logs'.format(len(dupe_nodes)))

    for node in dupe_nodes:
        # Get all preprint_license_updated logs for this node, sorted by date descending
        preprint_license_updated_logs = [
            log for log in node.logs if log.action == 'preprint_license_updated'
        ]

        # Sort logs by date descending to process newest first
        preprint_license_updated_logs.sort(key=lambda x: x.date, reverse=True)

        log = preprint_license_updated_logs.pop()

        while preprint_license_updated_logs:
            next_log = preprint_license_updated_logs.pop()
            timedelta = log.date - next_log.date

            if timedelta.seconds < 1:
                logger.info(
                    'Hiding duplicate preprint_license_updated log with ID {} from node {}, timedelta was {}'.format(
                        log._id, node._id, timedelta
                    )
                )
                log.should_hide = True
                log.save()
            else:
                logger.info(
                    'Skipping preprint_license_updated log with ID {} from node {}, timedelta was {}'.format(
                        log._id, node._id, timedelta
                    )
                )

            log = next_log


def main(dry=True):
    init_app(set_backends=True, routes=False)  # Sets the storage backends on all models

    # Start a transaction that will be rolled back if any exceptions are unhandled
    with TokuTransaction():
        do_migration()

        if dry:
            # When running in dry mode force the transaction to rollback
            raise Exception('Abort Transaction - Dry Run')


if __name__ == '__main__':
    dry = '--dry' in sys.argv

    if not dry:
        # If we're not running in dry mode log everything to a file
        script_utils.add_file_logger(logger, __file__)

    # Allow setting the log level just by appending the level to the command
    if 'debug' in sys.argv:
        logger.setLevel(logging.DEBUG)
    elif 'warning' in sys.argv:
        logger.setLevel(logging.WARNING)
    elif 'info' in sys.argv:
        logger.setLevel(logging.INFO)
    elif 'error' in sys.argv:
        logger.setLevel(logging.ERROR)

    # Finally run the migration
    main(dry=dry)

