# Function to find the next palindrome
def next_palindrome(k):
    palin = list(k)
    n = len(k)
    mid = n // 2

    # case 1: forward right
    just_copy = False
    for i in range(mid, n):
        mirrored = n - 1 - i
        if k[i] < k[mirrored]:
            just_copy = True
        if just_copy:
            palin[i] = palin[mirrored]

    # case 2: backward left
    if not just_copy:
        i = (n - 1) // 2
        while i >= 0 and k[i] == '9':
            i -= 1
        if i >= 0:
            palin[i] = str(int(k[i]) + 1)
            for j in range(i + 1, (n + 1) // 2):
                palin[j] = '0'
            for j in range((n + 1) // 2, n):
                mirrored = n - 1 - j
                palin[j] = palin[mirrored]
        else:
            # case 3: "99...9" -> "100..01"
            palin = ['0'] * (n + 1)
            palin[0] = palin[-1] = '1'

    return ''.join(palin)

# Main execution
