    source_file,
    map_file,
    ck_list,
    ck_list_file,
    map_suffix,
    map_location,
    max_example_lines: int,
    must_has_no_miss_match: bool,
    cb_unmatch_ck=None,
    cb_match_ck=None
):
    """Check one file for unmapped lines based on line-function mapping."""
    info(f"Checking line-function mapping for file '{source_file}'...")

    abs_source_file = os.path.abspath(workspace + os.path.sep + source_file)

    if not os.path.exists(abs_source_file):
        return False, {"error": f"Source file '{source_file}' does not exist."}

    if not map_file:
        map_file_name = source_file.replace(os.path.sep, "_").replace(".", "_") + map_suffix
        map_file = os.path.join(map_location + os.path.sep + map_file_name)

    if not os.path.exists(os.path.abspath(workspace + os.path.sep + map_file)):
        return False, {"error": f"Mapping file '{map_file}' does not exist. You should create it first."}

    try:
        line_ck_map = fc.parse_line_CK_map_file(workspace, map_file)
    except Exception as e:
        error_details = str(e)
        warning(f"Error occurred while parsing mapping file {map_file}: {error_details}")
        warning(traceback.format_exc())
        return False, {"error": f"Mapping file parsing failed for file '{map_file}': {error_details}."}

    # compare ck_list and line_ck_map
    miss_matched_lines = []
    erro_lines_keys = []

    for k in line_ck_map.keys():
        if k not in ck_list:
            if str(k).startswith("IGNORE/"):
                continue
            if str(k).startswith("MISSMT/"):
                miss_matched_lines.append((k, line_ck_map[k]))
                continue
            erro_lines_keys.append((k, line_ck_map[k]))
            if cb_unmatch_ck:
                cb_unmatch_ck(k, line_ck_map[k])
        else:
            if cb_match_ck:
                cb_match_ck(k, line_ck_map[k])

    if len(erro_lines_keys) > 0:
        emsg = [
            f"Found {len(erro_lines_keys)} line block(s) in mapping file '{map_file}' "
            "that do not have corresponding CK tags:"
        ]

        for ck_name, _ in erro_lines_keys[:max_example_lines]:
            emsg.append(f"  '{ck_name}' which is not found in documentation file '{ck_list_file}'.")

        if len(erro_lines_keys) > max_example_lines:
            emsg.append(f"  ... and {len(erro_lines_keys) - max_example_lines} more.")

        emsg.append("Validate CKs are:")
        for ck in ck_list[:max_example_lines]:
            emsg.append(f"  '{ck}'")

        if len(ck_list) > max_example_lines:
            emsg.append(f"  ... and {len(ck_list) - max_example_lines} more.")

        return False, {"error": emsg}

    if must_has_no_miss_match and len(miss_matched_lines) > 0:
        emsg = [
            f"Found {len(miss_matched_lines)} line block(s) in mapping file '{map_file}' "
            "that are marked as MISSMT (miss-matched):"
        ]

        for ck_name, _ in miss_matched_lines[:max_example_lines]:
            emsg.append(f"  '{ck_name}' which is not matched in documentation file '{ck_list_file}'.")

        if len(miss_matched_lines) > max_example_lines:
            emsg.append(f"  ... and {len(miss_matched_lines) - max_example_lines} more.")

        emsg.append(
            f"You need to add those missing CKs to file '{ck_list_file}' or correct the mapping."
        )
        return False, {"error": emsg}

    # find un-mapped lines
    un_mapped_lines, detail_msg = fc.get_un_mapped_lines(
        workspace, source_file, line_ck_map, max_example_lines
    )

    if len(un_mapped_lines) > 0:
        emsg = f"Found {len(un_mapped_lines)} un-mapped line block(s) in source file '{source_file}':\n" + detail_msg        
        return False, {"error": emsg}

    info(f"All lines in file '{source_file}' are properly mapped.")
    return True, f"All lines in file '{source_file}' are properly mapped."


class FileLineMapChecker(Checker):
    """Check unmapped lines in file based on line-function mapping."""

    def __init__(
        self,
        source_file,
        func_check_file,
        map_file=None,
        map_suffix="_line_func_map.txt",
        map_location="line_map",
        max_example_lines=20,
        need_human_check=False,
        must_has_no_miss_match=False,
        **kw
    ):
        self.source_file = source_file
        self.func_check_file = func_check_file
        self.map_file = map_file
        self.map_suffix = map_suffix
        self.map_location = map_location
        self.max_example_lines = max_example_lines
        self.must_has_no_miss_match = must_has_no_miss_match
        self.set_human_check_needed(need_human_check)

    def do_check(self, **kw) -> tuple[bool, object]:
        """Check file for unmapped lines."""
        success, ck_list_or_msg = get_func_check_marks(
            self.workspace, self.func_check_file
        )

        if not success:
            return False, ck_list_or_msg

        success, result_msg = line_map_check_one_file(
            self.workspace,
            self.source_file,
            self.map_file,
            ck_list_or_msg,
            self.func_check_file,
            self.map_suffix,
            self.map_location,
            self.max_example_lines,
            self.must_has_no_miss_match
        )

        return success, result_msg

# Image processing pipeline using PIL and Click
from functools import update_wrapper
from PIL import Image
from PIL import ImageEnhance
from PIL import ImageFilter
import click

@click.group(chain=True)
def cli():
    """This script processes a bunch of images through pillow in a unix
    pipe.  One commands feeds into the next.
    Example:
    \b
        imagepipe open -i example01.jpg resize -w 128 display
        imagepipe open -i example02.jpg blur save
    """

@cli.result_callback()
def process_commands(processors):
    """This result callback is invoked with an iterable of all the chained
    subcommands.  As in this example each subcommand returns a function
    we can chain them together to feed one into the other, similar to how
    a pipe on unix works.
    """
    # Start with an empty iterable.
    stream = ()

    # Pipe it through all stream processors.
    for processor in processors:
        stream = processor(stream)

    # Evaluate the stream and throw away the items.
    for _ in stream:
        pass

def processor(f):
    """Helper decorator to rewrite a function so that it returns another
    function from it.
    """
    def new_func(*args, **kwargs):
        def processor(stream):
            return f(stream, *args, **kwargs)
        return processor

    return update_wrapper(new_func, f)

def generator(f):
    """Similar to the :func:`processor` but passes through old values
    unchanged and does not pass through the values as parameter.
    """
    @processor
    def new_func(stream, *args, **kwargs):
        yield from stream
        yield from f(*args, **kwargs)

    return update_wrapper(new_func, f)

def copy_filename(new, old):
    new.filename = old.filename
    return new

@cli.command("open")
@click.option(
    "-i",
    "--image",
    "images",
    type=click.Path(),
    multiple=True,
    help="The image file to open.",
)
@generator
def open_cmd(images):
    """Loads one or multiple images for processing.  The input parameter
    can be specified multiple times to load more than one image.
    """
    for image in images:
        try:
            click.echo(f"Opening '{image}'")

            if image == "-":
                img = Image.open(click.get_binary_stdin())
                img.filename = "-"
            else:
                img = Image.open(image)

            yield img
        except Exception as e:
            click.echo(f"Could not open image '{image}': {e}", err=True)

@cli.command("save")
@click.option(
    "--filename",
    default="processed-{:04}.png",
    type=click.Path(),
    help="The format for the filename.",
    show_default=True,
)
@processor
def save_cmd(images, filename):
    """Saves all processed images to a series of files."""
    for idx, image in enumerate(images):
        try:
            fn = filename.format(idx + 1)
            click.echo(f"Saving '{image.filename}' as '{fn}'")
            yield image.save(fn)
        except Exception as e:
            click.echo(f"Could not save image '{image.filename}': {e}", err=True)

@cli.command("display")
@processor
def display_cmd(images):
    """Opens all images in an image viewer."""
    for image in images:
        click.echo(f"Displaying '{image.filename}'")
        image.show()
        yield image

@cli.command("resize")
@click.option("-w", "--width", type=int, help="The new width of the image.")
@click.option("-h", "--height", type=int, help="The new height of the image.")
@processor
def resize_cmd(images, width, height):
    """Resizes an image by fitting it into the box without changing
    the aspect ratio.
    """
    for image in images:
        w, h = (width or image.size[0], height or image.size[1])
        click.echo(f"Resizing '{image.filename}' to {w}x{h}")
        image.thumbnail((w, h))
        yield image

@cli.command("crop")
@click.option(
    "-b", "--border", type=int, help="Crop the image from all sides by this amount."
)
@processor
def crop_cmd(images, border):
    """Crops an image from all edges."""
    for image in images:
        box = [0, 0, image.size[0], image.size[1]]

        if border is not None:
            for idx, val in enumerate(box):
                box[idx] = max(0, val - border)

            click.echo(f"Cropping '{image.filename}' by {border}px")
            yield copy_filename(image.crop(box), image)
        else:
            yield image

def convert_rotation(ctx, param, value):
    if value is None:
        return

    value = value.lower()

    if value in ("90", "r", "right"):
        return (Image.ROTATE_90, 90)
    if value in ("180", "-180"):
        return (Image.ROTATE_180, 180)
    if value in ("-90", "270", "l", "left"):
        return (Image.ROTATE_270, 270)

    raise click.BadParameter(f"invalid rotation '{value}'")

def convert_flip(ctx, param, value):
    if value is None:
        return

    value = value.lower()

    if value in ("lr", "leftright"):
        return (Image.FLIP_LEFT_RIGHT, "left to right")
    if value in ("tb", "topbottom", "upsidedown", "ud"):
        return (Image.FLIP_LEFT_RIGHT, "top to bottom")

    raise click.BadParameter(f"invalid flip '{value}'")

@cli.command("transpose")
@click.option(
    "-r", "--rotate", callback=convert_rotation, help="Rotates the image (in degrees)"
)
@click.option("-f", "--flip", callback=convert_flip, help="Flips the image  [LR / TB]")
@processor
def transpose_cmd(images, rotate, flip):
    """Transposes an image by either rotating or flipping it."""
    for image in images:
        if rotate is not None:
            mode, degrees = rotate
            click.echo(f"Rotate '{image.filename}' by {degrees}deg")
            image = copy_filename(image.transpose(mode), image)

        if flip is not None:
            mode, direction = flip
            click.echo(f"Flip '{image.filename}' {direction}")
            image = copy_filename(image.transpose(mode), image)

        yield image

@cli.command("blur")
@click.option("-r", "--radius", default=2, show_default=True, help="The blur radius.")
@processor
def blur_cmd(images, radius):
    """Applies gaussian blur."""
    blur = ImageFilter.GaussianBlur(radius)

    for image in images:
        click.echo(f"Blurring '{image.filename}' by {radius}px")
        yield copy_filename(image.filter(blur), image)

@cli.command("smoothen")
@click.option(
    "-i",
    "--iterations",
    default=1,
    show_default=True,
    help="How many iterations of the smoothen filter to run.",
)
@processor
def smoothen_cmd(images, iterations):
    """Applies a smoothening filter."""
    for image in images:
        click.echo(
            f"Smoothening {image.filename!r} {iterations}"
            f" time{'s' if iterations != 1 else ''}"
        )

        for _ in range(iterations):
            image = copy_filename(image.filter(ImageFilter.BLUR), image)

        yield image

@cli.command("emboss")
@processor
def emboss_cmd(images):
    """Embosses an image."""
    for image in images:
        click.echo(f"Embossing '{image.filename}'")
        yield copy_filename(image.filter(ImageFilter.EMBOSS), image)

@cli.command("sharpen")
@click.option(
    "-f", "--factor", default=2.0, help="Sharpens the image.", show_default=True
)
@processor
def sharpen_cmd(images, factor):
    """Sharpens an image."""
    for image in images:
        click.echo(f"Sharpen '{image.filename}' by {factor}")
        enhancer = ImageEnhance.Sharpness(image)
        yield copy_filename(enhancer.enhance(max(1.0, factor)), image)

@cli.command("paste")
@click.option("-l", "--left", default=0, help="Offset from left.")
@click.option("-r", "--right", default=0, help="Offset from right.")
@processor
def paste_cmd(images, left, right):
    """Pastes the second image on the first image and leaves the rest
    unchanged.
    """
    imageiter = iter(images)
    image = next(imageiter, None)
    to_paste = next(imageiter, None)

    if to_paste is None:
        if image is not None:
            yield image
        return

    click.echo(f"Paste '{to_paste.filename}' on '{image.filename}'")
    mask = None

    if to_paste.mode == "RGBA" or "transparency" in to_paste.info:
        mask = to_paste

    image.paste(to_paste, (left, right), mask)
    image.filename += f"+{to_paste.filename}"
    yield image
    yield from imageiter

# Dynamic batching data loader implementation
import traceback
import warnings
from collections.abc import Iterable
import torch
from torch.utils.data import default_collate
from megatron.training import print_rank_0
from mindspeed_mm.data.dataloader.batching_strategy import TextBatchingStrategy

class DynamicBatchingDataLoader:
    def __init__(
        self,
        dataloader,
        max_seq_len: int,
        dynamic_batch_buffer_size: int,
        drop_last: bool = False,
        vision_layout: str = 'TND',
        consumed_train_samples: int = 0
    ) -> None:
        # Initialize the dynamic batching data loader
        print_rank_0("[INFO] initializing dynamic batching DataLoader")
        self.vision_layout = vision_layout
        self.dataloader = dataloader
        self.num_step = len(self.dataloader)

        # Create batching strategy instance
        self.batching_strategy = TextBatchingStrategy(
            max_seq_len=max_seq_len,
            buffer_size=dynamic_batch_buffer_size,
        )

        self.drop_last = drop_last
        self.consumed_train_samples = consumed_train_samples
        self.non_packing_data = {}

        print_rank_0("[INFO] Successfully initialize dynamic batching DataLoader")

    def __len__(self):
        return len(self.dataloader)

    def __iter__(self):
        self.step = 0
        self._data_iter = iter(self.dataloader)
        self._batched_data_iter = self.dynamic_batching_data_generator()
        return self

    def __next__(self):
        return next(self._batched_data_iter)

    def dynamic_batching_data_generator(self):
        while True:
            # Process when buffer is full
            if self.batching_strategy.is_full_filled():
                micro_batch = self._get_micro_batch()
                yield micro_batch
                self.step += 1

            try:
                processing_item = self._get_data_from_dataloader()
            except Exception as e:
                if isinstance(e, StopIteration):
                    # Handle remaining items when dataloader is exhausted
                    if not self.drop_last and not self.batching_strategy.empty():
                        while not self.batching_strategy.empty():
                            micro_batch = self._get_micro_batch()
                            yield micro_batch
                            self.step += 1
                        return
                    else:
                        return
                else:
                    # Print error information and re-raise exception
                    print(f"DynamicBatchDataset iter data exception: {e} \n{traceback.format_exc()}")
                    raise

            # Add item(s) to buffer
            if isinstance(processing_item, dict):
                processing_item = [processing_item]

            for item in processing_item:
                self.batching_strategy.put_item(item)

    def _get_data_from_dataloader(self):
        data = next(self._data_iter)

        # Identify and separate non-packing data
        origin_mbs = data['input_ids'].shape[0]

        for data_name, value in data.items():
            # Check if value is non-iterable or string-like
            if not isinstance(value, Iterable) or isinstance(value, (str, bytes)):
                self.non_packing_data[data_name] = value
            # Check length consistency with micro batch size
            elif data_name != 'pixel_values' and len(value) != origin_mbs:
                warnings.warn(
                    f"The iterable data {data_name} (of type {type(value)}) in micro batch extracted from "
                    f"the original dataloader has a length inconsistent with the micro batch size (mbs). To ensure "
                    f"correct decomposition into mbs individual samples, it has been moved to non_packing_data. "
                    f"Please verify the actual purpose of this data and apply appropriate adjustments."
                )
                self.non_packing_data[data_name] = value

        # Remove non-packing data from main data dictionary
        for data_name in self.non_packing_data:
            data.pop(data_name)

        data_names = data.keys()

        # Apply attention mask to filter sequences
        data['input_ids'] = [
            data['input_ids'][i][mask] 
            for i, mask in enumerate(data['attention_mask'].bool())
        ]
        data['labels'] = [
            data['labels'][i][mask] 
            for i, mask in enumerate(data['attention_mask'].bool())
        ]
        data['attention_mask'] = [
            data['attention_mask'][i][mask]
            for i, mask in enumerate(data['attention_mask'].bool())
        ]

        # Split pixel values based on image grid dimensions
        pixel_length = (
            data['image_grid_thw'][:, 0] * 
            data['image_grid_thw'][:, 1] * 
            data['image_grid_thw'][:, 2]
        )
        data['pixel_values'] = data['pixel_values'].split(pixel_length.tolist())

        # Convert back to list of dictionaries
        return [dict(zip(data_names, row)) for row in zip(*data.values())]

    def _get_micro_batch(self):
        micro_batch = self.batching_strategy.get_micro_batch()
        self.consumed_train_samples += len(micro_batch)
        micro_batch = self.collect_fn(micro_batch, self.vision_layout)
        return micro_batch

    def collect_fn(self, features, vision_layout):
        # Calculate sequence lengths
        seqlens = torch.tensor(
            [len(feature['input_ids']) for feature in features], 
            dtype=torch.long
        )
        batch = {"seqlens": seqlens}

        # Restore non-packing data
        for data_name, value in self.non_packing_data.items():
            batch[data_name] = value

        # Process each input field
        for input_name in features[0].keys():
            if input_name in ('input_ids', 'attention_mask', 'labels'):
                # Concatenate tensors and add batch dimension
                batch[input_name] = torch.cat([
                    feature[input_name] for feature in features
                ]).unsqueeze(0)
            else:
                if input_name == 'pixel_values' and vision_layout == "TND":
                    batch[input_name] = torch.cat([
                        feature[input_name] for feature in features
                    ])
                else:
                    batch[input_name] = default_collate([
                        feature[input_name] for feature in features
                    ])

        # Generate indices based on attention mask
        if "attention_mask" in batch.keys():
            batch["indices"] = torch.arange(len(batch["attention_mask"][0]))
        else:
            raise ValueError("Need attention mask to generate indices")

        return batch

# Model pool implementation for loading and managing models
from ..core.loader import load_model, hash_model_file
from ..core.vram import AutoWrappedModule
from ..configs import MODEL_CONFIGS, VRAM_MANAGEMENT_MODULE_MAPS
import importlib, json, torch


class ModelPool:
    def __init__(self):
        self.model = []
        self.model_name = []
        self.model_path = []

    def import_model_class(self, model_class):
        # Split the full module path from class name
        split = model_class.rfind(".")
        model_resource, model_class = model_class[:split], model_class[split+1:]
        model_class = importlib.import_module(model_resource).__getattribute__(model_class)
        return model_class

    def need_to_enable_vram_management(self, vram_config):
        # Check if VRAM offloading is configured
        return vram_config["offload_dtype"] is not None and vram_config["offload_device"] is not None

    def fetch_module_map(self, model_class, vram_config):
        if self.need_to_enable_vram_management(vram_config):
            if model_class in VRAM_MANAGEMENT_MODULE_MAPS:
                # Create mapping between source and target modules
                module_map = {
                    self.import_model_class(source): self.import_model_class(target)
                    for source, target in VRAM_MANAGEMENT_MODULE_MAPS[model_class].items()
                }
            else:
                # Default mapping to AutoWrappedModule
                module_map = {self.import_model_class(model_class): AutoWrappedModule}
        else:
            module_map = None
        return module_map

    def load_model_file(self, config, path, vram_config, vram_limit=None):
        # Import model class
        model_class = self.import_model_class(config["model_class"])

        # Get extra configuration kwargs
        model_config = config.get("extra_kwargs", {})

        # Handle state dict converter if specified
        if "state_dict_converter" in config:
            state_dict_converter = self.import_model_class(config["state_dict_converter"])
        else:
            state_dict_converter = None

        # Get module mapping for VRAM management
        module_map = self.fetch_module_map(config["model_class"], vram_config)

        # Load the actual model
        model = load_model(
            model_class, path, model_config,
            vram_config["computation_dtype"], vram_config["computation_device"],
            state_dict_converter,
            use_disk_map=True,
            vram_config=vram_config, module_map=module_map, vram_limit=vram_limit,
        )
        return model

    def default_vram_config(self):
        # Default VRAM configuration settings
        vram_config = {
            "offload_dtype": None,
            "offload_device": None,
            "onload_dtype": torch.bfloat16,
            "onload_device": "cpu",
            "preparing_dtype": torch.bfloat16,
            "preparing_device": "cpu",
            "computation_dtype": torch.bfloat16,
            "computation_device": "cpu",
        }
        return vram_config

    def auto_load_model(self, path, vram_config=None, vram_limit=None, clear_parameters=False):
        print(f"Loading models from: {json.dumps(path, indent=4)}")

        # Use default VRAM config if none provided
        if vram_config is None:
            vram_config = self.default_vram_config()

        # Compute hash of model file
        model_hash = hash_model_file(path)
        loaded = False

        # Try to match with known model configurations
        for config in MODEL_CONFIGS:
            if config["model_hash"] == model_hash:
                # Load the model
                model = self.load_model_file(config, path, vram_config, vram_limit=vram_limit)

                # Clear parameters if requested
                if clear_parameters:
                    self.clear_parameters(model)

                # Store model metadata
                self.model.append(model)
                model_name = config["model_name"]
                self.model_name.append(model_name)
                self.model_path.append(path)

                # Log model info
                model_info = {
                    "model_name": model_name,
                    "model_class": config["model_class"],
                    "extra_kwargs": config.get("extra_kwargs")
                }
                print(f"Loaded model: {json.dumps(model_info, indent=4)}")
                loaded = True

        if not loaded:
            raise ValueError(f"Cannot detect the model type. File: {path}. Model hash: {model_hash}")

    def fetch_model(self, model_name, index=None):
        fetched_models = []
        fetched_model_paths = []

        # Search through loaded models
        for model, model_path, model_name_ in zip(self.model, self.model_path, self.model_name):
            if model_name == model_name_:
                fetched_models.append(model)
                fetched_model_paths.append(model_path)

        # Handle cases based on number of matches
        if len(fetched_models) == 0:
            print(f"No {model_name} models available. This is not an error.")
            model = None
        elif len(fetched_models) == 1:
            print(f"Using {model_name} from {json.dumps(fetched_model_paths[0], indent=4)}.")
            model = fetched_models[0]
        else:
            # Multiple models found - decide which to use
            if index is None:
                model = fetched_models[0]
                print(f"More than one {model_name} models are loaded: {fetched_model_paths}. Using {model_name} from {json.dumps(fetched_model_paths[0], indent=4)}.")
            elif isinstance(index, int):
                model = fetched_models[:index]
                print(f"More than one {model_name} models are loaded: {fetched_model_paths}. Using {model_name} from {json.dumps(fetched_model_paths[:index], indent=4)}.")
            else:
                model = fetched_models
                print(f"More than one {model_name} models are loaded: {fetched_model_paths}. Using {model_name} from {json.dumps(fetched_model_paths, indent=4)}.")
        return model

    def clear_parameters(self, model: torch.nn.Module):
        # Recursively clear all parameters in the model
        for name, module in model.named_children():
            self.clear_parameters(module)
        for name, param in model.named_parameters(recurse=False):
            setattr(model, name, None)

