class PydanticMagicMock(MagicMock):
    """`MagicMock` that's able to generate pydantic-core schemas and avoids _mock_name=None errors."""
    def __init__(self, *args, **kwargs):
        name = kwargs.pop("name", None)
        super().__init__(*args, **kwargs)
        self.__spec__ = ModuleSpec(name, None)
        self._mock_name = name or "mock"

    def __get_pydantic_core_schema__(self, source_type, handler):
        return core_schema.any_schema()


# --- Static extraction for CLI argument docs ---
def extract_omni_serve_subparser_init():
    """
    Statically parse vllm_omni/entrypoints/cli/serve.py to extract the subparser_init method
    and return a callable that adds arguments to a parser. This avoids import and mock issues.
    """
    serve_path = ROOT_DIR / "vllm_omni" / "entrypoints" / "cli" / "serve.py"
    with open(serve_path, encoding="utf-8") as f:
        source = f.read()
    tree = ast.parse(source, filename=str(serve_path))

    # Find class OmniServeCommand
    for node in tree.body:
        if isinstance(node, ast.ClassDef) and node.name == "OmniServeCommand":
            for item in node.body:
                if isinstance(item, ast.FunctionDef) and item.name == "subparser_init":
                    # We'll exec this function body in a dummy context
                    func_code = ast.Module(body=[item], type_ignores=[])
                    code = compile(func_code, filename=str(serve_path), mode="exec")
                    # Prepare dummy context
                    local_vars = {}

                    # Provide a dummy subparsers with add_parser returning our parser
                    class DummySubparsers:
                        def add_parser(self, name, **kwargs):
                            return _FlexibleArgumentParser(prog=name)

                    dummy_subparsers = DummySubparsers()

                    # Provide globals for exec
                    # Extract DESCRIPTION from the source file (assume it's a triple-quoted string at the top)
                    m = re.search(r'DESCRIPTION\s*=\s*([ru]?""".*?""")', source, re.DOTALL)
                    DESCRIPTION = m.group(1)[3:-3] if m else ""

                    exec_globals = {
                        "_FlexibleArgumentParser": _FlexibleArgumentParser,
                        "FlexibleArgumentParser": _FlexibleArgumentParser,
                        "make_arg_parser": lambda parser: parser,  # no-op for doc
                        "VLLM_SUBCMD_PARSER_EPILOG": "",
                        "logger": logger,
                        "DummySubparsers": DummySubparsers,
                        "argparse": __import__("argparse"),
                        "json": __import__("json"),
                        "DESCRIPTION": DESCRIPTION,
                    }

                    exec(code, exec_globals, local_vars)

                    # Get the function
                    subparser_init = local_vars["subparser_init"]

                    # Return a callable that mimics OmniServeCommand().subparser_init
                    def parser_factory():
                        class DummySelf:
                            name = "serve"

                        return subparser_init(DummySelf(), dummy_subparsers)

                    return parser_factory

    raise RuntimeError("Could not statically extract OmniServeCommand.subparser_init")


OmniServeCommand = type("OmniServeCommand", (), {"subparser_init": staticmethod(extract_omni_serve_subparser_init())})


class MarkdownFormatter(HelpFormatter):
    """Custom formatter that generates markdown for argument groups."""
    def __init__(self, prog: str, starting_heading_level: int = 3):
        super().__init__(prog, max_help_position=sys.maxsize, width=sys.maxsize)
        self._section_heading_prefix = "#" * starting_heading_level
        self._argument_heading_prefix = "#" * (starting_heading_level + 1)
        self._markdown_output = []

    def start_section(self, heading: str):
        if heading not in {"positional arguments", "options"}:
            heading_md = f"\n{self._section_heading_prefix} {heading}\n\n"
            self._markdown_output.append(heading_md)

    def end_section(self):
        pass

    def add_text(self, text: str):
        if text:
            self._markdown_output.append(f"{text.strip()}\n\n")

    def add_usage(self, usage, actions, groups, prefix=None):
        pass

    def add_arguments(self, actions: Iterable[Action]):
        for action in actions:
            if len(action.option_strings) == 0 or "--help" in action.option_strings:
                continue

            option_strings = f"`{'`, `'.join(action.option_strings)}`"
            heading_md = f"{self._argument_heading_prefix} {option_strings}\n\n"
            self._markdown_output.append(heading_md)

            if choices := action.choices:
                choices = f"`{'`, `'.join(str(c) for c in choices)}`"
                self._markdown_output.append(f"Possible choices: {choices}\n\n")
            elif (metavar := action.metavar) and isinstance(metavar, (list, tuple)):
                metavar = f"`{'`, `'.join(str(m) for m in metavar)}`"
                self._markdown_output.append(f"Possible choices: {metavar}\n\n")

            if action.help:
                self._markdown_output.append(f"{action.help}\n\n")

            if (default := action.default) != SUPPRESS:
                # Make empty string defaults visible
                if default == "":
                    default = '""'
                self._markdown_output.append(f"Default: `{default}`\n\n")

    def format_help(self):
        """Return the formatted help as markdown."""
        return "".join(self._markdown_output)


# Function to create parser using subparser_init style CLI class
def create_parser_subparser_init(subcmd_class):
    """
    Create an argparse parser using subparser_init style CLI class, with MarkdownFormatter.
    Compatible with both AST-extracted static parser_factory and real class instance method.
    """
    class DummySubparsers:
        def add_parser(self, name, **kwargs):
            return _FlexibleArgumentParser(prog=name)

    dummy_subparsers = DummySubparsers()

    # If subparser_init is a zero-arg static function (AST-extracted), call it directly
    subparser_init = getattr(subcmd_class, "subparser_init", None)
    if subparser_init is not None:
        import inspect
        sig = inspect.signature(subparser_init)
        if len(sig.parameters) == 0:
            parser = subparser_init()
        else:
            parser = subcmd_class().subparser_init(dummy_subparsers)
    else:
        parser = subcmd_class().subparser_init(dummy_subparsers)

    parser.formatter_class = MarkdownFormatter
    return parser


def on_startup(command: Literal["build", "gh-deploy", "serve"], dirty: bool):
    """
    Entry point for doc generation. Builds doc directory and outputs markdown for each CLI command.
    """
    logger.info("Generating vllm-omni argparse documentation")
    logger.debug("Root directory: %s", ROOT_DIR.resolve())
    logger.debug("Output directory: %s", ARGPARSE_DOC_DIR.resolve())

    if not ARGPARSE_DOC_DIR.exists():
        ARGPARSE_DOC_DIR.mkdir(parents=True)

    # Register all CLI parsers; you can easily add more commands here
    parsers = {
        "omni_serve": create_parser_subparser_init(OmniServeCommand),
        # "another_cmd": create_parser_subparser_init(AnotherCommandClass),
    }

    for stem, parser in parsers.items():
        doc_path = ARGPARSE_DOC_DIR / f"{stem}.inc.md"
        with open(doc_path, "w", encoding="utf-8") as f:
            f.write(super(type(parser), parser).format_help())
        logger.info("Argparse generated: %s", doc_path.relative_to(ROOT_DIR))


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    on_startup("build", False)

import re
import torch

def convert_glm4moe_to_hf(args, name, param):
    # Handle embedding and output layer mappings
    if name == "module.module.embedding.word_embeddings.weight":
        return [("model.embed_tokens.weight", param)]

    if name == "module.module.output_layer.weight":
        return [("lm_head.weight", param)]

    if name == "module.module.decoder.final_layernorm.weight":
        return [("model.norm.weight", param)]

    # Calculate head dimension with fallback
    try:
        head_dim = args.kv_channels if args.kv_channels is not None else args.hidden_size // args.num_attention_heads
    except AttributeError:
        head_dim = args.hidden_size // args.num_attention_heads

    value_num_per_group = args.num_attention_heads // args.num_query_groups

    # Process decoder layers
    decoder_layers_pattern = r"module\.module\.decoder\.layers\.(\d+)\.(.+)"
    match = re.match(decoder_layers_pattern, name)

    if match:
        layer_idx, rest = match.groups()

        # Experts processing
        expert_pattern = r"mlp.experts\.(.+)\.weight(\d+)"
        match = re.match(expert_pattern, rest)

        if match:
            rest, expert_idx = match.groups()

            if rest == "linear_fc1":
                gate_weight, up_weight = param.chunk(2, dim=0)
                outputs = [
                    (f"model.layers.{layer_idx}.mlp.experts.{expert_idx}.gate_proj.weight", gate_weight),
                    (f"model.layers.{layer_idx}.mlp.experts.{expert_idx}.up_proj.weight", up_weight),
                ]
                return outputs

            elif rest == "linear_fc2":
                outputs = [
                    (f"model.layers.{layer_idx}.mlp.experts.{expert_idx}.down_proj.weight", param),
                ]
                return outputs

            else:
                raise ValueError(f"Unknown expert parameter name: {name}")

        # Shared experts processing
        shared_expert_pattern = r"mlp.shared_experts\.(.+)"
        match = re.match(shared_expert_pattern, rest)

        if match:
            rest = match.groups()[0]

            if rest == "linear_fc1.weight":
                gate_weight, up_weight = param.chunk(2, dim=0)
                return [
                    (f"model.layers.{layer_idx}.mlp.shared_experts.gate_proj.weight", gate_weight),
                    (f"model.layers.{layer_idx}.mlp.shared_experts.up_proj.weight", up_weight),
                ]

            elif rest == "linear_fc2.weight":
                return [
                    (f"model.layers.{layer_idx}.mlp.shared_experts.down_proj.weight", param),
                ]

            else:
                raise ValueError(f"Unknown shared expert parameter name: {name}")

        # Self-attention projection
        if rest == "self_attention.linear_proj.weight":
            return [(f"model.layers.{layer_idx}.self_attn.o_proj.weight", param)]

        # QKV weight transformation
        elif rest == "self_attention.linear_qkv.weight":
            param = param.view(args.num_query_groups, -1, head_dim, args.hidden_size)
            q_param, k_param, v_param = torch.split(param, split_size_or_sections=[value_num_per_group, 1, 1], dim=1)
            q_param = q_param.reshape(-1, args.hidden_size)
            k_param = k_param.reshape(-1, args.hidden_size)
            v_param = v_param.reshape(-1, args.hidden_size)
            return [
                (f"model.layers.{layer_idx}.self_attn.q_proj.weight", q_param),
                (f"model.layers.{layer_idx}.self_attn.k_proj.weight", k_param),
                (f"model.layers.{layer_idx}.self_attn.v_proj.weight", v_param),
            ]

        # QKV bias transformation
        elif rest == "self_attention.linear_qkv.bias":
            param = param.view(args.num_query_groups, -1)
            q_bias, k_bias, v_bias = torch.split(
                param,
                split_size_or_sections=[value_num_per_group * head_dim, head_dim, head_dim],
                dim=1,
            )
            q_bias = q_bias.contiguous().flatten()
            k_bias = k_bias.contiguous().flatten()
            v_bias = v_bias.contiguous().flatten()
            return [
                (f"model.layers.{layer_idx}.self_attn.q_proj.bias", q_bias),
                (f"model.layers.{layer_idx}.self_attn.k_proj.bias", k_bias),
                (f"model.layers.{layer_idx}.self_attn.v_proj.bias", v_bias),
            ]

        # MLP linear layers
        elif rest == "mlp.linear_fc1.weight":
            gate_weight, up_weight = param.chunk(2, dim=0)
            return [
                (f"model.layers.{layer_idx}.mlp.gate_proj.weight", gate_weight),
                (f"model.layers.{layer_idx}.mlp.up_proj.weight", up_weight),
            ]

        elif rest == "mlp.linear_fc2.weight":
            return [(f"model.layers.{layer_idx}.mlp.down_proj.weight", param)]

        # Layer normalization weights
        elif rest == "self_attention.linear_qkv.layer_norm_weight":
            return [(f"model.layers.{layer_idx}.input_layernorm.weight", param)]

        elif rest == "mlp.linear_fc1.layer_norm_weight":
            return [(f"model.layers.{layer_idx}.post_attention_layernorm.weight", param)]

        elif rest == "post_self_attn_layernorm.weight":
            return [(f"model.layers.{layer_idx}.post_self_attn_layernorm.weight", param)]

        elif rest == "post_mlp_layernorm.weight":
            return [(f"model.layers.{layer_idx}.post_mlp_layernorm.weight", param)]

        elif rest == "pre_mlp_layernorm.weight":
            return [(f"model.layers.{layer_idx}.post_attention_layernorm.weight", param)]

        # Router weights for MoE
        elif rest == "mlp.router.weight":
            return [(f"model.layers.{layer_idx}.mlp.gate.weight", param)]

        elif rest == "mlp.router.expert_bias":
            return [(f"model.layers.{layer_idx}.mlp.gate.e_score_correction_bias", param)]

        # QK normalization weights
        elif rest == "self_attention.q_layernorm.weight":
            return [(f"model.layers.{layer_idx}.self_attn.q_norm.weight", param)]

        elif rest == "self_attention.k_layernorm.weight":
            return [(f"model.layers.{layer_idx}.self_attn.k_norm.weight", param)]

    # Handle MTP layers
    mtp_layer_pattern = r"module\.module\.mtp\.layers\.(\d+)\.(.+)"
    match = re.match(mtp_layer_pattern, name)

    if match:
        layer_idx, rest = match.groups()
        layer_idx = int(layer_idx) + args.num_layers

        if rest == "eh_proj.weight":
            return [(f"model.layers.{layer_idx}.eh_proj.weight", param)]

        elif rest == "enorm.weight":
            return [(f"model.layers.{layer_idx}.enorm.weight", param)]

        elif rest == "hnorm.weight":
            return [(f"model.layers.{layer_idx}.hnorm.weight", param)]

        elif rest == "final_layernorm.weight":
            return [(f"model.layers.{layer_idx}.shared_head.norm.weight", param)]

        else:
            name = f"module.module.decoder.layers.{layer_idx}.{rest}"
            name = name.replace("transformer_layer.", "")
            return convert_glm4moe_to_hf(args, name, param)

    raise ValueError(f"Unknown parameter name: {name}")

import re
import warnings
from contextlib import contextmanager
from ...processing_utils import ProcessorMixin

class DonutProcessor(ProcessorMixin):
    r"""
    Constructs a Donut processor which wraps a Donut image processor and an XLMRoBERTa tokenizer into a single
    processor.
    [`DonutProcessor`] offers all the functionalities of [`DonutImageProcessor`] and
    [`XLMRobertaTokenizer`/`XLMRobertaTokenizerFast`]. See the [`~DonutProcessor.__call__`] and
    [`~DonutProcessor.decode`] for more information.
    Args:
        image_processor ([`DonutImageProcessor`], *optional*):
            An instance of [`DonutImageProcessor`]. The image processor is a required input.
        tokenizer ([`XLMRobertaTokenizer`/`XLMRobertaTokenizerFast`], *optional*):
            An instance of [`XLMRobertaTokenizer`/`XLMRobertaTokenizerFast`]. The tokenizer is a required input.
    """
    attributes = ["image_processor", "tokenizer"]
    image_processor_class = "AutoImageProcessor"
    tokenizer_class = "AutoTokenizer"

    def __init__(self, image_processor=None, tokenizer=None, **kwargs):
        feature_extractor = None
        if "feature_extractor" in kwargs:
            warnings.warn(
                "The `feature_extractor` argument is deprecated and will be removed in v5, use `image_processor`"
                " instead.",
                FutureWarning,
            )
            feature_extractor = kwargs.pop("feature_extractor")

        image_processor = image_processor if image_processor is not None else feature_extractor
        if image_processor is None:
            raise ValueError("You need to specify an `image_processor`.")
        if tokenizer is None:
            raise ValueError("You need to specify a `tokenizer`.")

        super().__init__(image_processor, tokenizer)
        self.current_processor = self.image_processor
        self._in_target_context_manager = False

    def __call__(self, *args, **kwargs):
        """
        When used in normal mode, this method forwards all its arguments to AutoImageProcessor's
        [`~AutoImageProcessor.__call__`] and returns its output. If used in the context
        [`~DonutProcessor.as_target_processor`] this method forwards all its arguments to DonutTokenizer's
        [`~DonutTokenizer.__call__`]. Please refer to the doctsring of the above two methods for more information.
        """
        # For backward compatibility
        if self._in_target_context_manager:
            return self.current_processor(*args, **kwargs)

        images = kwargs.pop("images", None)
        text = kwargs.pop("text", None)

        if len(args) > 0:
            images = args[0]
            args = args[1:]

        if images is None and text is None:
            raise ValueError("You need to specify either an `images` or `text` input to process.")

        if images is not None:
            inputs = self.image_processor(images, *args, **kwargs)

        if text is not None:
            encodings = self.tokenizer(text, **kwargs)

        if text is None:
            return inputs
        elif images is None:
            return encodings
        else:
            inputs["labels"] = encodings["input_ids"]
            return inputs

    def batch_decode(self, *args, **kwargs):
        """
        This method forwards all its arguments to DonutTokenizer's [`~PreTrainedTokenizer.batch_decode`]. Please refer
        to the docstring of this method for more information.
        """
        return self.tokenizer.batch_decode(*args, **kwargs)

    def decode(self, *args, **kwargs):
        """
        This method forwards all its arguments to DonutTokenizer's [`~PreTrainedTokenizer.decode`]. Please refer to the
        docstring of this method for more information.
        """
        return self.tokenizer.decode(*args, **kwargs)

    @contextmanager
    def as_target_processor(self):
        """
        Temporarily sets the tokenizer for processing the input. Useful for encoding the labels when fine-tuning TrOCR.
        """
        warnings.warn(
            "`as_target_processor` is deprecated and will be removed in v5 of Transformers. You can process your "
            "labels by using the argument `text` of the regular `__call__` method (either in the same call as "
            "your images inputs, or in a separate call."
        )

        self._in_target_context_manager = True
        self.current_processor = self.tokenizer
        yield
        self.current_processor = self.image_processor
        self._in_target_context_manager = False

    def token2json(self, tokens, is_inner_value=False, added_vocab=None):
        """
        Convert a (generated) token sequence into an ordered JSON format.
        """
        if added_vocab is None:
            added_vocab = self.tokenizer.get_added_vocab()

        output = {}
        while tokens:
            start_token = re.search(r"<s_(.*?)>", tokens, re.IGNORECASE)
            if start_token is None:
                break

            key = start_token.group(1)
            key_escaped = re.escape(key)
            end_token = re.search(rf"</s_{key_escaped}>", tokens, re.IGNORECASE)
            start_token = start_token.group()

            if end_token is None:
                tokens = tokens.replace(start_token, "")
            else:
                end_token = end_token.group()
                start_token_escaped = re.escape(start_token)
                end_token_escaped = re.escape(end_token)

                content = re.search(
                    f"{start_token_escaped}(.*?){end_token_escaped}", tokens, re.IGNORECASE | re.DOTALL
                )
                if content is not None:
                    content = content.group(1).strip()

                    if r"<s_" in content and r"</s_" in content:  # non-leaf node
                        value = self.token2json(content, is_inner_value=True, added_vocab=added_vocab)
                        if value:
                            if len(value) == 1:
                                value = value[0]
                            output[key] = value
                    else:  # leaf nodes
                        output[key] = []
                        for leaf in content.split(r"<sep/>"):
                            leaf = leaf.strip()
                            if leaf in added_vocab and leaf[0] == "<" and leaf[-2:] == "/>":
                                leaf = leaf[1:-2]  # for categorical special tokens
                            output[key].append(leaf)

                        if len(output[key]) == 1:
                            output[key] = output[key][0]

                tokens = tokens[tokens.find(end_token) + len(end_token) :].strip()
                if tokens[:6] == r"<sep/>":  # non-leaf nodes
                    return [output] + self.token2json(tokens[6:], is_inner_value=True, added_vocab=added_vocab)

        if len(output):
            return [output] if is_inner_value else output
        else:
            return [] if is_inner_value else {"text_sequence": tokens}

    @property
    def feature_extractor_class(self):
        warnings.warn(
            "`feature_extractor_class` is deprecated and will be removed in v5. Use `image_processor_class` instead.",
            FutureWarning,
        )
        return self.image_processor_class

    @property
    def feature_extractor(self):
        warnings.warn(
            "`feature_extractor` is deprecated and will be removed in v5. Use `image_processor` instead.",
            FutureWarning,
        )
        return self.image_processor

# WebAuthn API endpoints for managing security keys
from flask import Blueprint, request, g
from auth.unified import require_auth
from models import db
from models.webauthn import WebAuthnCredential
from services.webauthn_service import WebAuthnService
from services.audit_service import AuditService
from utils.response import success_response, error_response

# Create blueprint for WebAuthn routes
bp = Blueprint('webauthn', __name__, url_prefix='/api/v2/webauthn')

@bp.route('/credentials', methods=['GET'])
@require_auth()
def list_credentials():
    """List user's WebAuthn credentials"""
    user = g.current_user
    credentials = WebAuthnService.get_user_credentials(user.id)
    return success_response(data=[c.to_dict() for c in credentials])

@bp.route('/credentials/<int:credential_id>', methods=['DELETE'])
@require_auth()
def delete_credential(credential_id):
    """Delete a WebAuthn credential"""
    user = g.current_user

    # Attempt to delete the credential
    success, message = WebAuthnService.delete_credential(credential_id, user.id)

    if not success:
        return error_response(message, 404)

    # Log audit event
    AuditService.log_action(
        action='webauthn_delete',
        resource_type='webauthn',
        resource_id=str(credential_id),
        resource_name=f'WebAuthn credential {credential_id}',
        details=f'Deleted WebAuthn credential {credential_id}',
        success=True
    )

    return success_response(message=message)

@bp.route('/credentials/<int:credential_id>/toggle', methods=['POST'])
@require_auth()
def toggle_credential(credential_id):
    """Enable/disable a WebAuthn credential"""
    user = g.current_user

    # Get enabled status from request body
    data = request.get_json() or {}
    enabled = data.get('enabled', True)

    # Attempt to toggle credential
    success, message = WebAuthnService.toggle_credential(credential_id, user.id, enabled)

    if not success:
        return error_response(message, 404)

    # Log audit event
    AuditService.log_action(
        action='webauthn_toggle',
        resource_type='webauthn',
        resource_id=str(credential_id),
        resource_name=f'WebAuthn credential {credential_id}',
        details=f'{"Enabled" if enabled else "Disabled"} WebAuthn credential {credential_id}',
        success=True
    )

    return success_response(message=message)

@bp.route('/register/options', methods=['POST'])
@require_auth()
def registration_options():
    """Get WebAuthn registration options - uses WebAuthnService for proper crypto"""
    user = g.current_user
    hostname = request.host

    # Generate registration options using WebAuthnService
    options = WebAuthnService.generate_registration_options(user, hostname)
    return success_response(data=options)

@bp.route('/register/verify', methods=['POST'])
@require_auth()
def verify_registration():
    """Verify WebAuthn registration and create credential"""
    user = g.current_user
    data = request.get_json()

    # Extract registration data
    credential_data = data.get('credential', {})
    credential_name = data.get('name', 'Security Key')
    hostname = request.host

    # Verify registration with WebAuthnService
    success, message, credential = WebAuthnService.verify_registration(
        user.id, credential_data, hostname, credential_name
    )

    if not success:
        return error_response(message, 400)

    # Log audit event
    AuditService.log_action(
        action='webauthn_register',
        resource_type='webauthn',
        resource_id=str(credential.id) if credential else None,
        resource_name=credential_name,
        details=f'Registered WebAuthn credential: {credential_name}',
        success=True
    )

    return success_response(
        data=credential.to_dict() if credential else None, 
        message=message
    )

# Custom YAML-based rule implementation for Skylos
from __future__ import annotations

import ast
import fnmatch
from pathlib import Path

from skylos.rules.base import SkylosRule


class YAMLRule(SkylosRule):
    def __init__(self, config):
        # Initialize rule properties from configuration
        self._rule_id = config["rule_id"]
        self._name = config["name"]
        self.severity = config.get("severity", "MEDIUM")
        self.category = config.get("category", "custom")

        # Extract pattern and message from yaml_config
        yaml_config = config.get("yaml_config", {})
        self.pattern = yaml_config.get("pattern", {})
        self.message = yaml_config.get(
            "message", "Custom rule violation"
        )

    @property
    def rule_id(self):
        return self._rule_id

    @property
    def name(self):
        return self._name

    def visit_node(self, node, context):
        # Dispatch based on pattern type
        pattern_type = self.pattern.get("type")

        if pattern_type == "function":
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                return self._check_function_pattern(node, context)

        elif pattern_type == "class":
            if isinstance(node, ast.ClassDef):
                return self._check_class_pattern(node, context)

        elif pattern_type == "call":
            if isinstance(node, ast.Call):
                return self._check_call_pattern(node, context)

        return None

    def _check_function_pattern(self, node, context):
        decorators = self.pattern.get("decorators", {})
        has_any = decorators.get("has_any", [])
        must_also_have_any = decorators.get("must_also_have_any", [])

        # No triggers specified - nothing to check
        if not has_any:
            return None

        # Collect decorator names
        found = set()
        for deco in node.decorator_list:
            found.add(self._get_decorator_name(deco))

        # Check if any trigger matches
        triggered = False
        for trigger in has_any:
            for f in found:
                if trigger in f:
                    triggered = True
                    break
            if triggered:
                break

        if not triggered:
            return None

        # Check required decorators if specified
        if must_also_have_any:
            has_required = False
            for required in must_also_have_any:
                for f in found:
                    if required in f:
                        has_required = True
                        break
                if has_required:
                    break

            if not has_required:
                return [self._make_finding(node, context)]

        return None

    def _check_class_pattern(self, node, context):
        name_pattern = self.pattern.get("name_pattern", "*")
        must_inherit_any = self.pattern.get("must_inherit_any", [])

        # Check class name against pattern
        if not fnmatch.fnmatch(node.name, name_pattern):
            return None

        # Check inheritance requirements if specified
        if must_inherit_any:
            base_names = set()
            for base in node.bases:
                base_names.add(self._get_base_name(base))

            if not (set(must_inherit_any) & base_names):
                return [self._make_finding(node, context)]

        return None

    def _check_call_pattern(self, node, context):
        function_match = self.pattern.get("function_match", [])
        args_config = self.pattern.get("args", {})

        func_name = self._get_call_name(node)
        if not func_name:
            return None

        # Check if function name matches any pattern
        matched = any(p in func_name for p in function_match)
        if not matched:
            return None

        # Check for dynamic string arguments if configured
        if args_config.get("is_dynamic"):
            pos = args_config.get("position", 0)
            if len(node.args) > pos:
                if self._is_dynamic_string(node.args[pos]):
                    return [self._make_finding(node, context)]

        return None

    def _get_decorator_name(self, deco):
        # Extract decorator name from AST node
        if isinstance(deco, ast.Name):
            return deco.id
        elif isinstance(deco, ast.Attribute):
            parent = self._get_decorator_name(deco.value)
            return f"{parent}.{deco.attr}" if parent else deco.attr
        elif isinstance(deco, ast.Call):
            return self._get_decorator_name(deco.func)
        return ""

    def _get_base_name(self, base):
        # Extract base class name from AST node
        if isinstance(base, ast.Name):
            return base.id
        elif isinstance(base, ast.Attribute):
            return base.attr
        return ""

    def _get_call_name(self, node):
        # Build fully qualified function name from call node
        func = node.func
        parts = []

        while isinstance(func, ast.Attribute):
            parts.append(func.attr)
            func = func.value

        if isinstance(func, ast.Name):
            parts.append(func.id)
            parts.reverse()
            return ".".join(parts)

        return None

    def _is_dynamic_string(self, node):
        # Check if node represents a dynamic string (format, concatenation, etc.)
        if isinstance(node, ast.JoinedStr):
            return True
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Mod)):
            return True
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Attribute) and node.func.attr == "format":
                return True
        return False

    def _make_finding(self, node, context):
        # Create finding dictionary with location and metadata
        name = None
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            name = getattr(node, "name", None)
        if name is None and isinstance(node, ast.Call):
            name = self._get_call_name(node) or "<call>"

        filename = context.get("filename", "")

        return {
            "rule_id": self.rule_id,
            "kind": "custom",
            "category": self.category,
            "severity": self.severity,
            "message": self.message,
            "name": name or "<custom>",
            "simple_name": name or "<custom>",
            "value": "-",
            "file": filename,
            "basename": Path(filename).name,
            "line": getattr(node, "lineno", 0),
            "col": getattr(node, "col_offset", 0),
        }


def load_custom_rules(rules_data):
    # Load enabled YAML rules from configuration data
    rules = []

    for config in rules_data:
        if not config.get("enabled", True):
            continue
        if config.get("rule_type") != "yaml":
            continue

        try:
            rules.append(YAMLRule(config))
        except Exception as e:
            print(f"Warning: Failed to load rule {config.get('rule_id')}: {e}")

    return rules

