def forex_market_open():
    # Checks if the forex market is currently open
    now = datetime.datetime.now()

    # Friday == 4
    # Saturday == 5
    # TODO Technically it resumes at 5pm sunday but I don't handle that
    if now.weekday() >= 5:
        return False
    elif now.weekday() >= 4 and now.hour >= 17:
        return False
    else:
        return True

