# Calculate the number of operations to reduce all elements
def reduce_trees(arr):
    # Find the largest and second largest values in the list
    highest = max(arr)
    # Replace the maximum with -1 temporarily to find second maximum
    second_highest = max(map(lambda val: -1 if val == highest else val, arr))

    if highest == second_highest:
        return [0] * len(arr)
    else:
        gap = highest - second_highest
        return map(lambda val: val - gap if val == highest else val, arr)

def count_operations(arr):
    steps = 0
    while not all(value == 0 for value in arr):
        arr = reduce_trees(arr)
        steps += 1
    return steps - 1

