# Import necessary selector components
from .selectors import (
    HAS_SELECT,
    DefaultSelector,
    EVENT_READ,
    EVENT_WRITE
)

def _await_io_activity(sockets_list, event_mask, timeout=None):
    """ 
    Waits for I/O activity to occur on a collection of sockets.
    Accepts either a list or a single socket object. Returns a list
    of sockets ready for the specified I/O operations. """
    if not HAS_SELECT:
        raise RuntimeError('Platform lacks selector support')

    # Ensure sockets_list is a list
    if not isinstance(sockets_list, list):
        # Handle single socket case
        if hasattr(sockets_list, "fileno"):
            sockets_list = [sockets_list]
        # Handle non-list iterables
        else:
            sockets_list = list(sockets_list)

    with DefaultSelector() as selector:
        # Register each socket for the specified events
        for socket in sockets_list:
            selector.register(socket, event_mask)

        # Return only sockets with matching events
        return [sock.fileobj for sock, flags in selector.select(timeout) 
                if flags & event_mask]

def await_read_ready(sockets, timeout=None):
    """ 
    Waits until reading is possible from one or more sockets.
    Accepts a list or single socket. Returns sockets ready for reading. """
    return _await_io_activity(sockets, EVENT_READ, timeout)

def await_write_ready(sockets, timeout=None):
    """ 
    Waits until writing is possible to one or more sockets.
    Accepts a list or single socket. Returns sockets ready for writing. """
    return _await_io_activity(sockets, EVENT_WRITE, timeout)

# Custom JSON serialization for Money objects
import json
from django.core.serializers.base import DeserializationError
from django.core.serializers.json import (
    DjangoJSONEncoder, PythonDeserializer, Serializer as BaseJsonSerializer)
from prices import Money

MONEY_MARKER = 'Money'

class Serializer(BaseJsonSerializer):
    def _init_options(self):
        super()._init_options()
        self.json_kwargs['cls'] = CustomMoneyEncoder

class CustomMoneyEncoder(DjangoJSONEncoder):
    def default(self, value):
        if isinstance(value, Money):
            return {
                '_type': MONEY_MARKER, 'amount': value.amount,
                'currency': value.currency}
        return super().default(value)

def money_object_hook(data):
    if '_type' in data and data['_type'] == MONEY_MARKER:
        return Money(data['amount'], data['currency'])
    return data

def Deserializer(stream_or_string, **kwargs):
    """Deserialize a stream or string of JSON data. This is a slightly modified
    copy of Django implementation with additional argument <object_hook> in
    json.loads"""
    if not isinstance(stream_or_string, (bytes, str)):
        stream_or_string = stream_or_string.read()
    if isinstance(stream_or_string, bytes):
        stream_or_string = stream_or_string.decode()
    try:
        parsed_data = json.loads(stream_or_string, object_hook=money_object_hook)
        yield from PythonDeserializer(parsed_data, **kwargs)
    except Exception as error:
        # Handle exceptions while satisfying linting rules
        if isinstance(error, (GeneratorExit, DeserializationError)):
            raise
        raise DeserializationError() from error

# Cache decorator implementation with configurable expiration time
from datetime import datetime, timedelta
import os

class cache_decorator(object):
    def __init__(self, *args, **kwargs):
        self.cache_storage = {}
        # Get cache duration from environment variable or use default
        self.default_expiration = kwargs.get("cache_duration", timedelta(seconds=int(os.environ.get('CACHE_TTL', '300'))))

    def __call__(self, function_to_cache):
        def wrapper(*func_args, **func_kwargs):
            # Extract parameter for cache key (second arg if available, otherwise first)
            cache_key = func_args[1] if len(func_args) > 1 else func_args[0]

            # Determine expiration time for this call
            expiration_time = func_kwargs.get('expiration', self.default_expiration)

            # Initialize cache structure for this function if needed
            if function_to_cache not in self.cache_storage:
                self.cache_storage[function_to_cache] = {}

            # Check if we need to fetch new data
            needs_refresh = (
                expiration_time is None or 
                cache_key not in self.cache_storage[function_to_cache] or 
                (datetime.now() - self.cache_storage[function_to_cache][cache_key]['timestamp'] > expiration_time)
            )

            if needs_refresh:
                # Clean up max_age from kwargs if present
                if 'expiration' in func_kwargs:
                    del func_kwargs['expiration']

                # Execute original function and store result
                result = function_to_cache(*func_args, **func_kwargs)
                self.cache_storage[function_to_cache][cache_key] = {
                    'value': result, 
                    'timestamp': datetime.now()
                }

            return self.cache_storage[function_to_cache][cache_key]['value']

        return wrapper

# Import required modules for health monitoring verification
from webapp_health_monitor import errors

class Checker(object):
    checker_name = None

    def __init__(self, **parameters):
        # Initialize with optional keyword arguments
        pass

    def execute(self):
        # Method to be implemented by subclasses
        raise NotImplementedError()

    def __str__(self):
        # Return the checker's name or class name if not set
        if self.checker_name:
            return self.checker_name
        else:
            return self.__class__.__name__

class IntervalChecker(Checker):
    max_value = None
    min_value = None

    def execute(self):
        # Run validation checks in sequence
        self._validate_setup()
        self._validate_measurement()

    def _validate_setup(self):
        # Ensure bounds are properly configured
        if not self._are_limits_set():
            raise errors.BadConfigurationError()

    def _are_limits_set(self):
        # Check if lower bound is None but upper bound is set
        if self.min_value is None:
            return self.max_value is not None
        # Check if both bounds exist and lower <= upper
        elif self.max_value is not None:
            return self.min_value <= self.max_value
        # Only lower bound is set
        else:
            return True

    def _validate_measurement(self):
        # Get current value and validate against bounds
        current_value = self.fetch_value()
        self._verify_minimum(current_value)
        self._verify_maximum(current_value)

    def fetch_value(self):
        # Abstract method to be implemented by subclasses
        raise NotImplementedError

    def _verify_minimum(self, value):
        # Check if value is below minimum threshold
        if self.min_value is not None:
            if value < self.min_value:
                raise errors.VerificationFailure()

    def _verify_maximum(self, value):
        # Check if value exceeds maximum threshold
        if self.max_value is not None:
            if value > self.max_value:
                raise errors.VerificationFailure()

# DynamicEPackage implementation for handling metamodel classes dynamically
from .ecore import EPackage, BadValueError
from .notification import EObserver, Kind

class DynamicEPackage(EObserver):
    """A DynamicEPackage enables direct access to metaclasses
    from a metamodel as if it were a statically generated EPackage.
    Usage with an existing dynamic EPackage named 'myroot' that defines two 
    EClass: 'X' and 'Y'
    >>> from pyecore.utils import DynamicEPackage
    >>> MyAPI = DynamicEPackage(myroot)
    >>> MyAPI.X
    <EClass name="X">
    >>> x = MyAPI.X()
    >>> x
    <pyecore.ecore.X object at 0x7f118de363c8>
    """
    def __init__(self, package):
        if not isinstance(package, EPackage):
            raise BadValueError(got=package, expected=EPackage)
        super().__init__(notifier=package)
        for classifier in package.eClassifiers:
            setattr(self, classifier.name, classifier)
        for subpkg in package.eSubpackages:
            setattr(self, subpkg.name, DynamicEPackage(subpkg))

    def notifyChanged(self, notification):
        kind = notification.kind
        if notification.feature is EPackage.eClassifiers:
            if kind == Kind.ADD:
                new_item = notification.new
                setattr(self, new_item.name, new_item)
            elif kind == Kind.ADD_MANY:
                for item in notification.new:
                    setattr(self, item.name, item)
            elif kind == Kind.REMOVE and notification.old.eResource is None:
                try:
