# Helper module for HTML element generation
from inspect import isgenerator

class TagElement(object):
    tag_name = ''
    is_self_closing = False

    def __init__(self, *content, **attributes):
        if content and isinstance(content[0], dict):
            self.attributes = content[0]
            content = content[1:]
        else:
            self.attributes = attributes

        # Utility functions for handling 'class' attribute
        if 'styles' in attributes:
            attributes['class'] = ' '.join(s for s in attributes.pop('styles') if s)
        elif 'class_' in attributes:
            attributes['class'] = attributes.pop('class_')

        self.content_list = []
        self.append_content(content)

    def __call__(self, *content):
        self.append_content(content)
        return self

    def __repr__(self):
        attr_text = ''.join(' {}="{}"'.format(k, v) for k, v in self.attributes.items() if v)
        return '<{}{}>'.format(self.tag_name, attr_text)

    def append_content(self, content):
        if self.is_self_closing and content:
            raise ValueError("Self-closing elements cannot contain children.")

        if content and isgenerator(content[0]):
            content = content[0]

        for item in content:
            if item is not None:
                if isinstance(item, list):
                    self.append_content(item)
                else:
                    self.content_list.append(item)

# Modified version with renamed variables and reordered statements
from typing import Iterable, List, Tuple
from werkzeug.http import HTTP_STATUS_CODES
from apistar import http

__all__ = ['WSGIEnviron', 'WSGIResponse']

# Create status code mappings
STATUS_CODES = {
    code: "%d %s" % (code, msg)
    for code, msg in HTTP_STATUS_CODES.items()
}

# CORS header constant
ACCESS_CONTROL_ALLOW_ORIGIN = 'Access-Control-Allow-Origin'

# Alias for WSGI environment
WSGIEnviron = http.WSGIEnviron

class WSGIResponse(object):
    __slots__ = ('status', 'headers', 'iterator')

    def __init__(self,
                 status_message: str,
                 response_headers: List[Tuple[str, str]],
                 content_iterator: Iterable[bytes]) -> None:
        self.status = status_message
        self.headers = response_headers
        self.iterator = content_iterator

    @classmethod
    def build(cls, api_response: http.Response):
        try:
            status_text = STATUS_CODES[api_response.status]
        except KeyError:
            status_text = str(api_response.status)

        headers = list(api_response.headers.items())

        # Add CORS header if not present
        if ACCESS_CONTROL_ALLOW_ORIGIN not in api_response.headers:
            headers.append((ACCESS_CONTROL_ALLOW_ORIGIN, '*'))

        return WSGIResponse(
            status=status_text,
            headers=headers,
            iterator=[api_response.content]
        )

