import datetime
import numpy as np

class TimePoint(datetime.datetime):
    @property
    def julian_date(self):
        jd = (367.0 * self.year
              - np.floor( (7 * (self.year + np.floor( (self.month + 9) / 12.0) ) ) * 0.25 )
              + np.floor( 275 * self.month / 9.0 )
              + self.day + 1721013.5
              + ( (self.second/60.0 + self.minute ) / 60.0 + self.hour ) / 24.0)
        return jd

    @property
    def j2000(self):
        return self.julian_date - 2451544.5

    @property
    def j1950(self):
        return self.julian_date - 2433282.5

    @property
    def modified_jd(self):
        return self.julian_date - 2400000.5

class OrbitalState:
