# XML formatting and output utilities
import xml.etree.ElementTree as ET
import codecs

def format_xml_element(elem, level=0):
    # Add indentation for pretty printing
    indent_str = "\n" + level * "  "
    if len(elem):
        if not elem.text or not elem.text.strip():
            elem.text = indent_str + "  "
        if not elem.tail or not elem.tail.strip():
            elem.tail = indent_str
        for child in elem:
            format_xml_element(child, level + 1)
        if not elem.tail or not elem.tail.strip():
            elem.tail = indent_str
    else:
        if level and (not elem.tail or not elem.tail.strip()):
            elem.tail = indent_str

class XMLExporter:
    def __init__(self, data_groups):
        # Create root element
        root_element = ET.Element("configuration")

        # Add version info
        version_elem = ET.SubElement(root_element, "version_number")
        version_elem.text = "2"

        # Process each group
        for group in data_groups:
            group_elem = ET.SubElement(root_element, "category")
            group_elem.attrib["label"] = group.GetName()

            # Process parameters within each group
            for parameter in group.GetParams():
                param_elem = ET.SubElement(group_elem, "setting")

                # Handle field codes and values
                for field_code in parameter.GetFieldCodes():
                    field_value = parameter.GetFieldValue(field_code)

                    if field_code == "identifier":
                        param_elem.attrib["name"] = field_value
                    elif field_code == "initial":
                        param_elem.attrib["default"] = field_value
                    elif field_code == "datatype":
                        param_elem.attrib["type"] = field_value
                    else:
                        # Create sub-element for other fields
                        sub_elem = ET.SubElement(param_elem, field_code)
                        sub_elem.text = field_value

        # Apply formatting
        format_xml_element(root_element)
        self.xml_tree = ET.ElementTree(root_element)

    def WriteToFile(self, filepath):
        # Save XML to file with UTF-8 encoding
        with codecs.open(filepath, 'w', 'utf-8') as file_handle:
            self.xml_tree.write(file_handle)

