# Determine the appropriate method for loading entry points based on Python version and available libraries
import logging
import sys
import types

USE_IMPORTLIB_METADATA_STDLIB = USE_IMPORTLIB_METADATA = USE_PKG_RESOURCES = False

if sys.version_info >= (3, 10):
    # Python 3.10+ includes necessary fixes in importlib.metadata
    import importlib.metadata  # pylint: disable=no-member,no-name-in-module
    USE_IMPORTLIB_METADATA_STDLIB = True
else:
    if sys.version_info >= (3, 6):
        # For Python 3.6+, try using the backport importlib_metadata
        try:
            import importlib_metadata
            metadata_version_parts = [
                int(part)
                for part in importlib_metadata.version("importlib_metadata").split(".")
                if part.isdigit()
            ]
            if tuple(metadata_version_parts) >= (3, 3, 0):
                # Version 3.3.0+ of importlib_metadata contains required functionality
                USE_IMPORTLIB_METADATA = True
        except ImportError:
            # importlib_metadata not available; fall back to default behavior
            pass

# If neither importlib approach works, try pkg_resources
if not USE_IMPORTLIB_METADATA_STDLIB and not USE_IMPORTLIB_METADATA:
    try:
        import pkg_resources
        USE_PKG_RESOURCES = True
    except ImportError:
        # pkg_resources not available; all flags remain False by default
        pass

logger = logging.getLogger(__name__)

def iter_entry_points(group, name=None):
    result_list = []

    if USE_IMPORTLIB_METADATA_STDLIB:
        logger.debug("Using importlib.metadata to load entry points")
        entry_points = importlib.metadata.entry_points()
    elif USE_IMPORTLIB_METADATA:
        logger.debug("Using importlib_metadata to load entry points")
        entry_points = importlib_metadata.entry_points()
    elif USE_PKG_RESOURCES:
        logger.debug("Using pkg_resources to load entry points")
        result_list = list(pkg_resources.iter_entry_points(group, name=name))
    else:
        return result_list

    if USE_IMPORTLIB_METADATA_STDLIB or USE_IMPORTLIB_METADATA:
        for group_name, points_list in entry_points.items():
            if group_name != group:
                continue
            for point in points_list:
                if name is not None and point.name != name:
                    continue
                result_list.append(point)

    return result_list

def name_and_version_from_entry_point(entry_point):
    if USE_IMPORTLIB_METADATA_STDLIB or USE_IMPORTLIB_METADATA:
        return types.SimpleNamespace(
            name=entry_point.dist.metadata["name"], 
            version=entry_point.dist.version,
        )
    elif USE_PKG_RESOURCES:
        return types.SimpleNamespace(
            name=entry_point.dist.key, 
            version=entry_point.dist.version
        )

# Duplicate file detection utility
from os import path as ospath, getcwd
from pprint import pprint
from sys import argv
from dduplicated import commands

def collect_paths(arguments):
    directories = []
    for arg in arguments:
        full_path = ospath.join(getcwd(), arg)
        if ospath.exists(full_path) and ospath.isdir(full_path) and not ospath.islink(full_path):
            directories.append(full_path)
    return directories

def run():
    args = argv
    handled_files = []

    # Strip the script name
    del args[0]

    if len(args) == 0 or "help" in args:
        commands.help()
        exit(0)

    elif "detect" in args:
        handled_files = commands.detect(collect_paths(args))
    elif "delete" in args:
        handled_files = commands.delete(commands.detect(collect_paths(args)))

    elif "link" in args:
        handled_files = commands.link(commands.detect(collect_paths(args)))

    else:
        commands.help()
        exit(0)

    if len(handled_files) > 0:
        pprint(handled_files)
    else:
        print("No duplicates found")
        print("All clear! Goodbye!")

    exit(0)

