# Unit tests for datatyping validation functionality
import pytest
from hypothesis import given
from hypothesis.strategies import lists, integers, floats, one_of, composite
from datatyping.datatyping import validate

def test_empty_list():
    assert validate([], []) is None

@given(items=lists(integers()))
def test_valid_int_list(items):
    assert validate([int], items) is None

@given(values=lists(floats(), min_size=1))
def test_invalid_type_raises_error(values):
    with pytest.raises(TypeError):
        validate([int], values)

@given(data=one_of(lists(integers(), min_size=5),
                   lists(integers(), max_size=3)))
def test_length_mismatch_raises_error(data):
    with pytest.raises(ValueError):
        validate([int, int, int, str], data)

@given(nested_data=lists(lists(integers(), min_size=1), min_size=1))
def test_nested_structure(nested_data):
    assert validate([[int]], nested_data) is None
    with pytest.raises(TypeError):
        validate([int], nested_data)

@composite
def complex_nested_structure(draw):
    return [draw(lists(integers(), min_size=1, max_size=3)),
            draw(floats()),
            draw(lists(lists(floats(), min_size=1, max_size=3), min_size=1, max_size=3))]

@given(data=complex_nested_structure())
def test_heavy_nested_validation(data):
    assert validate([[int], float, [[float]]], data) is None
    with pytest.raises(TypeError):
        validate([[str], int, int], data)
    with pytest.raises(TypeError):
        validate([[[float]]], data)

