# Slack integration module for sending notifications
from slackclient import SlackClient
import json

class SlackNotifier:
    """Class representing a Slack channel for sending notifications"""
    def __init__(self, api_token, target_channel):
        self.channel_id = None
        self.channel_name = None
        self.api_token = None

        # Initialize Slack client with provided token
        self.api_token = SlackClient(api_token)

        # Attempt to find the channel by name in public channels
        response = self.api_token.api_call("channels.list")

        if response["ok"] == True:
            for current_channel in response["channels"]:
                if current_channel["name"] == target_channel:
                    self.channel_id = current_channel["id"]
                    self.channel_name = current_channel["name"]
                    break

            # If not found in public channels, search private groups
            if self.channel_id is None:
                response = self.api_token.api_call("groups.list")
                for current_channel in response["groups"]:
                    if current_channel["name"] == target_channel:
                        self.channel_id = current_channel["id"]
                        self.channel_name = current_channel["name"]
                        break

    def post_message(self, text_content, extra_attachments=None):
        """Function that sends a message using SLACK API"""
        # Send the message
        response = self.api_token.api_call(
            "chat.postMessage",
            channel=self.channel_id,
            text=text_content,
            attachments=extra_attachments,
            link_names=1,
            unfurl_links=True
        )

        # Handle errors
        if response["ok"] == False:
            raise SystemError("Slack API Error: %s" % response["error"])

def send_slack_rating_notification(rating_data, application):
    # Create Slack notifier instance if configuration exists
    if application.config.has_key("SLACK_TOKEN") and application.config.get("SLACK_NOTIFICATION_CHANNEL"):
        slack_instance = SlackNotifier(
            application.config["SLACK_TOKEN"],
            application.config["SLACK_NOTIFICATION_CHANNEL"]
        )
        application.logger.info(
            "Sending notification to SLACK for rating by %s on movie %s" % 
            (rating_data.user.nickname, rating_data.movie.name)
        )
        try:
            attachment_data = json.dumps([
                {
                    "text": rating_data.comment
                }
            ])
            # Encode URLs as strings to prevent SLACK API parsing during URL unfurling
            slack_instance.post_message(
                text_content="<" + rating_data.movie.url.encode("utf-8") + "?language=fr|" + 
                            rating_data.movie.name.encode("utf-8") + ">"
            )
            slack_instance.post_message(
                text_content="Rating from @%s: *%s*" % (
