def _configure_osf_client(cli_args):
    # CLI arguments take precedence over environment variables
    user = os.getenv("OSF_USERNAME")
    if cli_args.username is not None:
        user = cli_args.username
    pwd = None
    if user is not None:
        pwd = os.getenv("OSF_PASSWORD")
    return OSF(username=user, password=pwd)

def download_files(cli_args):
    osf_client = _configure_osf_client(cli_args)
    project = osf_client.project(cli_args.project)
    destination_dir = cli_args.project
    if cli_args.output is not None:
        destination_dir = cli_args.output

    for storage in project.storages:
        base_path = os.path.join(destination_dir, storage.name)
        for file_obj in storage.files:
            rel_path = file_obj.path
            if rel_path.startswith('/'):
                rel_path = rel_path[1:]
            full_path = os.path.join(base_path, rel_path)
            parent_dir, _ = os.path.split(full_path)
            os.makedirs(parent_dir, exist_ok=True)
            with open(full_path, "wb") as output_file:
                file_obj.write_to(output_file)

