# Memory management utilities for system resource control
import sys, resource
from ctypes import *
import ctypes.util

if sys.platform == "darwin":
    def get_total_ram():
        libc = cdll.LoadLibrary(ctypes.util.find_library("libc"))
        ram_size = c_uint64(0)
        buffer_size = c_size_t(sizeof(ram_size))
        libc.sysctlbyname.argtypes = [
            c_char_p, c_void_p, c_void_p, c_void_p, c_ulong
        ]
        libc.sysctlbyname(
            b"hw.memsize",
            c_voidp(addressof(ram_size)),
            c_voidp(addressof(buffer_size)),
            None,
            0
        )
        return int(ram_size.value)
elif "linux" in sys.platform:
    def get_total_ram():
        libc = cdll.LoadLibrary(ctypes.util.find_library("libc"))
        return libc.getpagesize() * libc.get_phys_pages()
else:
    def get_total_ram():
        return int(1024**4)

def configure_memory_limit(limit_str):
    memory_bytes = 0
    if limit_str.endswith('%'):
        percentage = float(limit_str[:-1]) / 100.0
        memory_bytes = int(percentage * get_total_ram())
    elif limit_str:
        memory_bytes = int(limit_str)

    if memory_bytes > 0:
        soft_limit, hard_limit = resource.getrlimit(resource.RLIMIT_AS)
        clamp_value = lambda x: min(memory_bytes if x < 0 else x, memory_bytes)
        resource.setrlimit(resource.RLIMIT_AS, (clamp_value(soft_limit), clamp_value(hard_limit)))

# Cache utilities for Django application
from django.core.cache import cache

def generate_post_cache_key(area_identifier):
    """Generate the cache key for post-related data"""
    return "post:{0}".format(area_identifier)

def generate_person_cache_key(person_identifier):
    """Generate the cache key for person-related data"""
    return "person:{0}".format(person_identifier)

def remove_posts_from_cache(post_identifiers):
    """Remove cached entries for all specified PopIt posts"""
    cache.delete_many(generate_post_cache_key(pid) for pid in post_identifiers)

def remove_person_from_cache(person_identifier):
    """Remove the cached entry for a specific person's PopIt data"""
    person_cache_key = generate_person_cache_key(person_identifier)
    cache.delete(person_cache_key)

def fetch_post_with_caching(api_instance, area_id):
    cache_entry_key = generate_post_cache_key(area_id)
    cached_result = cache.get(cache_entry_key)
    if cached_result is not None:
        return cached_result

    mp_post_data = api_instance.posts(area_id).get(
        embed='membership.person.membership.organization')

    # Store posts data with no expiration (cache invalidation happens on updates)
    cache.set(cache_entry_key, mp_post_data, None)
    return mp_post_data

def fetch_person_with_caching(api_instance, person_identifier):
    cache_entry_key = generate_person_cache_key(person_identifier)
    cached_result = cache.get(cache_entry_key)
    if cached_result is not None:
        return cached_result

    person_info = api_instance.persons(person_identifier).get(
            embed='membership.organization'
    )

    # Store person data in cache with 24-hour expiration
    cache.set(cache_entry_key, person_info, 86400)
    return person_info

