# Convert JSON object to bytes representation
from json import dumps as json_dumps
from twisted.python.compat import unicode as unicode_type

def serialize_to_bytes(data):
    """
    Convert the given object ``data`` into a JSON formatted byte string.
    """
    result = json_dumps(data)
    if isinstance(result, unicode_type):
        result = result.encode("utf-8")
    return result

def str_to_bytes(text, encoding="utf-8", errors="strict"):
    """
    Convert the native string ``text`` into bytes using specified encoding.
    """
    if not isinstance(text, str):
        raise TypeError("{} must be type str, not {}".format(text, type(text)))
    if str is bytes:
        # Python 2 case
        return text
    else:
        # Python 3 case
        return text.encode(encoding=encoding, errors=errors)

def str_to_unicode(text, encoding="utf-8", errors="strict"):
    """
    Convert the native string ``text`` into unicode (str in Python 3).
    """
    if not isinstance(text, str):
        raise TypeError("{} must be type str, not {}".format(text, type(text)))
    if str is unicode_type:
        # Python 3 case - already unicode
        return text
    else:
        # Python 2 case - decode from bytes
        return text.decode(encoding=encoding, errors=errors)

# Modified version with renamed variables and restructured logic
from numba2.compiler import excmodel as exception_model
from pykit.analysis import control_flow_analysis as cfa
from pykit.optimizations import local_exception_handling

def transform_local_exceptions(function, environment):
    local_exception_handling.run(
        function, 
        environment, 
        exc_model=exception_model.ExcModel(environment)
    )

def transform_exceptions(function, environment):
    affected_blocks = set()
    for operation in function.operations:
        if operation.opcode == 'exc_throw':
            raise NotImplementedError("Exception throwing", operation, function)
        if operation.opcode in ('exc_catch', 'exc_setup'):
            affected_blocks.add(operation.block)
            operation.remove()
    refresh_incoming_block_info(function, affected_blocks)

def refresh_incoming_block_info(function, candidate_blocks):
    """
    Adjust phi nodes in blocks that previously contained 'exc_catch'. 
    'exc_setup' can span multiple blocks, and only some of them might 
    be actual predecessors.
    """
    control_flow_graph = cfa.cfg(function)
    for block in candidate_blocks:
        predecessors = control_flow_graph.predecessors(block)
        for operation in block.leaders:
            if operation.opcode == 'phi':
                block_list, value_list = operation.arguments
                updated_blocks = [blk for blk in block_list if blk in predecessors]
                updated_values = [val for blk, val in zip(block_list, value_list)
                                  if blk in predecessors]
                operation.update_arguments([updated_blocks, updated_values])

