# Determine the number of valid knight moves from a given chess cell
def chessKnight(position):
    # Validate the input cell format
    import re
    pattern = re.search(r'^([a-h])([1-8])$', position, re.IGNORECASE)
    if not pattern:
        # Invalid cell notation
        return 0
    column, row = pattern.group(1).lower(), int(pattern.group(2))
    possible_moves = 8

    # Adjust moves based on column (file) position
    if column in "ah":
        possible_moves -= 4
        if row == 2 or row == 7:
            possible_moves -= 1
        elif row == 1 or row == 8:
            possible_moves -= 2
    elif column in "bg":
        possible_moves -= 2
        if row == 2 or row == 7:
            possible_moves -= 2
        elif row == 1 or row == 8:
            possible_moves -= 3
    elif row == 2 or row == 7:
        possible_moves -= 2
    elif row == 1 or row == 8:
        possible_moves -= 4

    return possible_moves

def main():
    test_cases = [
        ["a1", 2],
        ["c2", 6],
        ["d4", 8],
        ["g6", 6],
        ["a10", 0]
    ]

    for case in test_cases:
        result = chessKnight(case[0])
        expected = case[1]
        if expected == result:
            print("PASSED: chessKnight({}) returned {}".format(case[0], result))
        else:
            print("FAILED: chessKnight({}) returned {}, expected: {}".format(case[0], result, expected))

if __name__ == '__main__':
    main()

