import copy
import os
from subprocess import STDOUT, run as _execute_command, CalledProcessError, TimeoutExpired

# Environment configuration to capture glibc errors,
# as they may output to /dev/tty instead of stderr.
# (Reference: http://stackoverflow.com/a/27797579)
ENVIRONMENT = copy.copy(os.environ)
ENVIRONMENT["LIBC_FATAL_STDERR_"] = "1"

def execute_command(command, input_data=None, time_limit=None):
    execution_status = 'success'
    try:
        output = _execute_command(
            command,
            stderr=STDOUT,
            timeout=time_limit,
            input=input_data,
            env=ENVIRONMENT,
            check=True)
    except CalledProcessError as error:
        execution_status = 'called process error'
        output = error.output if error.output else str(error)
    except TimeoutExpired as error:
        execution_status = 'timed out after {} seconds'.format(time_limit)
        output = error.output if error.output else str(error)
    except FileNotFoundError as error:
        execution_status = 'not found'
        output = str(error)
    except ProcessLookupError as error:
        try:
            execution_status, output = execute_command(
                command, 
                input_data=input_data, 
                time_limit=time_limit
            )
        except:
            execution_status = 'process lookup error'
            output = str(error)

    try:
        if not isinstance(output, str):
            output = str(output, 'utf-8')
    except UnicodeDecodeError:
        output = str(output, 'cp437')

    return (execution_status, output)

