import sys
import lxml.etree

class XPathException(Exception):
    pass

def load_xml_file(filepath):
    return lxml.etree.parse(filepath)

def create_xpath_expression(expression):
    try:
        return lxml.etree.XPath(expression)
    except lxml.etree.XPathSyntaxError as error:
        raise XPathException(error.msg), None, sys.exc_info()[2]

def register_custom_functions():
    namespace = lxml.etree.FunctionNamespace(None)
    namespace['is_invoke'] = is_invoke

def is_invoke(context, *identifiers):
    element = context.context_node
    if element.tag != 'ParameterizedExpr':
        return False
    if element[0].tag != 'NameExpr' or element[0].get('kind') != 'FUN':
        return False
    invoked_name = element[0][0].get('nameId')
    # Could this function like
    # is_invoke('eval', 'feval') -> identifiers is a tuple of strings
    # is_invoke(//some/sequence) -> identifiers[0] is a list of strings
    for identifier in identifiers:
        if isinstance(identifier, basestring) and invoked_name == identifier:
            return True
        elif any(invoked_name == i for i in identifier):
            return True
    return False

