import re

class WrongTypeError(ValueError):
    """Exception raised when an invalid type is provided in arguments."""
    pass

class WrongSelectorError(ValueError):
    """Exception raised when an invalid selector is provided in arguments."""
    pass

class WrongOutputFormatError(ValueError):
    """Exception raised when an invalid output format is specified in arguments."""
    pass

def validate_arguments(arguments):
    """
    Checks the validity of arguments received from CLI commands.
    :param arguments: The parsed CLI arguments obtained via docopt
    :return: None
    """
    project_name_pattern = re.compile(r'[^a-zA-Z0-9_]')

    if arguments['genconfig']:
        if arguments['--type'] not in ['scraper', 'crawler']:
            raise WrongTypeError("--type must be either 'scraper' or 'crawler'")
        if arguments['--selector'] not in ['xpath', 'css']:
            raise WrongSelectorError("--selector must be either 'xpath' or 'css'")

    if arguments['generate'] or arguments['run']:
        if arguments['--output_type'] not in ['json', 'csv']:
            raise WrongOutputFormatError("--output_type must be either 'json' or 'csv'")

    if arguments['genconfig'] or arguments['generate'] or arguments['run']:
        if project_name_pattern.search(arguments['<projectname>']) is not None:
            raise Exception("<projectname> can only contain letters, digits, and underscores")

    if int(arguments['--levels']) < 1:
        raise Exception("--levels must be at least 1")

    return

# Custom ordered dictionary with magnitude tracking and ordering constraints
import collections
import typing

class CustomDict(collections.OrderedDict, typing.MutableMapping[str, float]):
  def __init__(self, *args, **kwargs) -> None:
    self._min_value = float('inf')
    self._max_value = 0
    self._is_sorted = True
    super(CustomDict, self).__init__(*args, **kwargs)

  def __setitem__(self, key: str, value: float) -> None:
    if key in self and self[key] == value:
      raise AssertionError('Duplicate assignment')

    if value < self._min_value:
      self._min_value = value
    else:
      self._is_sorted = False

    if value > self._max_value:
      self._max_value = value

    super(CustomDict, self).__setitem__(key, value)
    self._update_state()

  def items(self) -> typing.ItemsView[str, float]:
    self._sort_items()
    return super(CustomDict, self).items()

  def first_item(self) -> typing.Tuple[str, float]:
    self._sort_items()
    for k, v in self.items():
      return k, v

  def peek_key(self) -> str:
    self._sort_items()
    for first_key in self:
      return first_key

  def get_magnitude(self) -> float:
    return self._max_value

  def _sort_items(self) -> None:
    if self._is_sorted:
      return

    sorted_pairs = sorted(super(CustomDict, self).items(), key=lambda x: x[1], reverse=True)
    for k, v in sorted_pairs:
      self.move_to_end(k)

    self._is_sorted = True

  def _update_state(self):
    pass

# OAuth2 scope-based permission check for DRF
from django.core.exceptions import ImproperlyConfigured
from rest_framework.permissions import BasePermission

HTTP_SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS']

class OAuth2ScopeBasedPermission(BasePermission):
    """
    Ensure that the incoming request is authenticated and that the 
    access token includes the necessary scopes for the requested operation.
    """
    def has_permission(self, request, view):
        auth_token = request.auth
        is_safe_request = request.method in HTTP_SAFE_METHODS

        if not auth_token:
            return False

        if hasattr(auth_token, 'scope'):
            scope_config = self.determine_scopes(request, view)

            # Check required scopes first
            if scope_config['mandatory'] is not None:
                validity = auth_token.is_valid(scope_config['mandatory'])
                if validity == False:
                    return False
            else:
                # No mandatory scopes defined by the view
                validity = False

            # Then check method-specific scopes
            if is_safe_request:
                if scope_config['readonly'] is not None:
                    return auth_token.is_valid(scope_config['readonly'])
            else:
                if scope_config['writeonly'] is not None:
                    return auth_token.is_valid(scope_config['writeonly'])

            return validity

        assert False, (
            'OAuth2ScopeBasedPermission requires the '
            '`oauth_api.authentication.OAuth2Authentication` '
            'authentication class to be configured.'
        )

    def determine_scopes(self, request, view):
        mandatory = getattr(view, 'required_scopes', None)
        readonly = getattr(view, 'read_scopes', None)
        writeonly = getattr(view, 'write_scopes', None)

        if not mandatory and not readonly and not writeonly:
            raise ImproperlyConfigured(
                'OAuth-protected resources must define scope requirements. '
                'Please configure required_scopes, read_scopes, or write_scopes on the view.'
            )

        return {
            'mandatory': mandatory,
            'readonly': readonly,
            'writeonly': writeonly,
        }

# Extract external library imports from Python source code
import ast
import os
from collections import deque
import sys
from stdlib_list import stdlib_list

config = {
    'skip_relative_imports': True,
    'exclude_builtin_modules': True,
    'python_version': None,
}

def extract_imported_libraries(source_code):
    parsed_tree = ast.parse(source_code)
    imported_modules = deque()

    for node in parsed_tree.body:
        # Handle 'import module' and 'import module1, module2' statements
        if type(node) == ast.Import:
            imported_modules.extend([name.name.split('.')[0] for name in node.names])

        # Handle 'from module import something' statements
        if type(node) == ast.ImportFrom:
            if node.level > 0:
                if config['skip_relative_imports'] or not node.module:
                    continue
                else:
                    imported_modules.append(node.module.split('.')[0])

    return list(imported_modules)

def scan_directory_for_libraries(root_directory):
    external_libs = set()

    for dirpath, dirnames, filenames in os.walk(root_directory):
        for filename in filenames:
            if filename.endswith('.py'):
                print('.', end='')
                full_path = os.path.join(dirpath, filename)
                with open(full_path, 'r') as file_obj:
                    code_content = file_obj.read()
                external_libs.update(set(extract_imported_libraries(code_content)))

    if config['exclude_builtin_modules']:
        if not config['python_version']:
            python_version = '%s.%s' % (sys.version_info.major, sys.version_info.minor)
        standard_libs = stdlib_list("3.4")
        external_libs = [lib for lib in external_libs if lib not in standard_libs]

    return external_libs

