# Convert spreadsheet data to markdown tables
from collections import OrderedDict

def _transform_sheets_to_rows(data):
    columns = OrderedDict()
    if not data or len(data) == 0:
        return [], None
    if isinstance(data[0], list):
        columns.update(OrderedDict.fromkeys(data[0]))
    for item in data:
        if isinstance(item, dict):
            columns.update(OrderedDict.fromkeys(item.keys()))
    columns = columns.keys()
    result = []
    is_valid = False
    for item in data:
        row = []
        for col in columns:
            value = item.get(col, '')
            if value is None:
                value = ''
            row.append(value)
        if len(row) > 0:
            is_valid = True
        result.append(row)
    return columns, result if is_valid else None

def convert_spreadsheet_to_markdown(data):
    """
    accepts a dict or OrderedDict containing arrays of arrays representing
    a spreadsheet, and returns a markdown document with tables
    """
    import tabulate
    processed_sheets = OrderedDict()
    final_output = []

    def format_cell(cell_value):
        return '' if cell_value is None else str(cell_value)

    for (sheet_title, sheet_data) in data.items():
        processed_sheets[sheet_title] = final_output
        (headers, rows) = _transform_sheets_to_rows(sheet_data)
        if rows:
            final_output.append('#{}'.format(sheet_title))
            final_output.append(tabulate.tabulate(rows,
                                                  headers=headers,
                                                  tablefmt="orgtbl"))
    return '\n\n'.join(final_output)

