# Modified version of the Parser class with renamed variables and restructured logic
from django.db.models.expressions import Star
from django.db.models.sql.datastructures import EmptyResultSet
from django.db.models.sql.where import SubqueryConstraint
from .version_19 import Parser as BaseQueryParser

class CustomParser(BaseQueryParser):
    def _setup_for_transformation(self):
        from django.db.models.sql.where import EmptyWhere
        if isinstance(self.query_object.where, EmptyWhere):
            # If the WHERE clause is empty, no results should be returned
            raise EmptyResultSet()

    def _handle_leaf_node_in_where(self, condition_node, is_negated, updated_parent, join_type, model_class, sql_compiler):
        if not isinstance(condition_node, SubqueryConstraint):
            # Skip subqueries; let the parent method handle them
            if not hasattr(condition_node, "lhs") and not hasattr(condition_node, "rhs"):
                # Handle empty Q() objects - these are essentially no-op where conditions
                return
        return super(CustomParser, self)._handle_leaf_node_in_where(
            condition_node, is_negated, updated_parent, join_type, model_class, sql_compiler
        )

    def _classify_query_type(self):
        query = self.query_object
        if query.extra_select or query.annotations:
            if "__count" in query.annotations:
                field = query.annotations["__count"].get_source_expressions()[0]
                if isinstance(field, Star) or str(field) == "*":
                    return "AGGREGATE_COUNT"
        return "STANDARD_SELECT"

# Verify locale string similarities
import json
import os
import click
from difflib import SequenceMatcher

BASE_DIR = os.path.dirname(os.path.dirname(__file__))
LOCALE_FILE_PATH = os.path.join(BASE_DIR, "app/locales/taiga/locale-en.json")

def extract_keywords(prefix, data):
    results = []
    if prefix is not None and not isinstance(data, dict):
        results.append((".".join(prefix), data))
    elif prefix is not None and isinstance(data, dict):
        for sub_key in data.keys():
            results.extend(extract_keywords(prefix + [sub_key], data[sub_key]))
    elif prefix is None and isinstance(data, dict):
        for sub_key in data.keys():
            results.extend(extract_keywords([sub_key], data[sub_key]))
    return results

@click.command()
@click.option('--similarity-threshold', default=1.0, help='Minimum similarity score to display')
@click.option('--min-string-length', default=10, help='Minimum length of strings to compare')
@click.option('--skip-identical', default=False, is_flag=True, help='Skip identical string pairs')
def check_locale_similarity(similarity_threshold, min_string_length, skip_identical):
    locale_data = json.load(open(LOCALE_FILE_PATH))
    all_entries = extract_keywords(None, locale_data)
    processed_pairs = set()

    for key_a, text_a in all_entries:
        for key_b, text_b in all_entries:
            if key_a == key_b:
                continue
            if len(text_a) < min_string_length and len(text_b) < min_string_length:
                continue

            match_ratio = SequenceMatcher(None, text_a, text_b).ratio()

            if skip_identical and match_ratio == 1.0:
                continue

            if match_ratio >= similarity_threshold:
                pair = (key_a, key_b)
                reverse_pair = (key_b, key_a)
                if pair not in processed_pairs and reverse_pair not in processed_pairs:
                    processed_pairs.add(pair)
                    processed_pairs.add(reverse_pair)
                    click.echo(
                        "Keys {} and {} are similar with score {}\n - {}\n - {}".format(
                            key_a,
                            key_b,
                            match_ratio,
                            text_a,
                            text_b
                        )
                    )

