import math
import re

def process_thing_flags_read(input_value, flag_table):
    """
    Processes a thing's flags value.

    Extended patches can use mnemonics for flag names, separated by plus signs.

    @raise LookupError: if the input_value contains an unknown mnemonic.
        """ 
    if input_value.isdigit() == True:
        return input_value

    tokens = re.split(r"[,+| \t\f\r]+", input_value)
    result = 0

    for token in tokens:
        token = token.strip()

        # Locate the index of the flag mnemonic and convert it to a flag value.
        flag_entry = flag_table.flags.get(token)
        if flag_entry is None:
            raise LookupError('Ignoring unknown thing flag {}.'.format(token))
        mask = int(math.pow(2, flag_entry['index']))
        result += mask

    return result


def process_thing_flags_write(flags_value, flag_table):
    """
    Converts a thing flags value into a string of mnemonics. 
    """

    bit_position = 1
    output_list = []

    for _ in range(0, 32):
        if (flags_value & bit_position) == 0:
            bit_position *= 2
            continue

        for key_name, flag_data in flag_table.flags.iteritems():
            if int(math.pow(2, flag_data['index'])) == bit_position:    
                output_list.append(key_name)
                break

        bit_position *= 2

    if len(output_list) == 0:
        return 0
    else:
        return '+'.join(output_list)

