# Module for context-free grammar processing
from grammpy import Grammar
from .NongeneratingSymbolsRemove import remove_nongenerating_symbols
from .UnreachableSymbolsRemove import remove_unreachable_symbols

class ContextFreeGrammar:
    @staticmethod
    def eliminate_non_generating(grammar: Grammar, update_grammar=False):
        return remove_nongenerating_symbols(grammar, update_grammar)

    @staticmethod
    def check_if_generating(grammar: Grammar, update_grammar=False, execute_removal=True):
        g = grammar
        if execute_removal:
            g = ContextFreeGrammar.eliminate_non_generating(grammar, update_grammar=update_grammar)
        return g.start_get() in g.nonterms()

    @staticmethod
    def eliminate_unreachable(grammar: Grammar, update_grammar=False):
        return remove_unreachable_symbols(grammar, update_grammar)

    @staticmethod
    def clean_grammar(grammar: Grammar, update_grammar=False, *,
                      apply_unreachable_check=True,
                      apply_non_generating_check=True) -> Grammar:
        if apply_non_generating_check:
            grammar = ContextFreeGrammar.eliminate_non_generating(grammar, update_grammar=update_grammar)
            update_grammar = False
        if apply_unreachable_check:
            grammar = ContextFreeGrammar.eliminate_unreachable(grammar, update_grammar=update_grammar)
        return grammar

