# Handle model save signals for dirty field tracking
from django.db.models.signals import pre_save, post_save
from django.dispatch import receiver
from django.utils import timezone
from cityhallmonitor.models import DirtyFieldsModel, \
    Matter, MatterAttachment, MatterSponsor

@receiver(pre_save, sender=DirtyFieldsModel)
def on_pre_save(sender, obj, *args, **kwargs):
    """Update timestamp when model fields have changed"""
    if hasattr(sender, 'has_changes'):
        if obj.has_changes():
            obj.updated_at = timezone.now()

@receiver(post_save, sender=DirtyFieldsModel)
def on_post_save(sender, obj, **kwargs):
    """Clear dirty state and handle related document updates"""
    if hasattr(sender, 'has_changes'):
        if sender == Matter and obj.has_changes():
            for rel in obj.matterattachment_set.all():
                if hasattr(rel, 'document'):
                    rel.document.on_related_update()
        elif sender == MatterAttachment and obj.has_changes():
            if hasattr(obj, 'document'):
                obj.document.on_related_update()
        elif sender == MatterSponsor and obj.has_changes():
            for rel in obj.matter.matterattachment_set.all():
                if hasattr(rel, 'document'):
                    rel.document.on_related_update()

    if hasattr(sender, 'clear_state'):
        obj.clear_state()

# Reusable message sender implementation for handling long messages
from bot.api.domain import Message
from bot.logger.message_sender import MessageSender
from bot.logger.message_sender.api import ApiMessageSender
from bot.logger.message_sender.message_builder import MessageBuilder

class ReusableMessageSender(MessageSender):
    def __init__(self, api_sender: ApiMessageSender, msg_builder: MessageBuilder, max_msg_length: int = 4000):
        self.api_sender = api_sender
        self.msg_builder = msg_builder
        self.max_msg_length = max_msg_length
        self.current_message_id = None

    def send(self, content_text):
        message_obj = self._construct_message(content_text)
        self._obtain_sender_method()(message_obj)

    def _construct_message(self, content_text):
        self.msg_builder.append(content_text)
        self.__validate_size(content_text)
        return self.msg_builder.build()

    def __validate_size(self, content_text):
        if self.msg_builder.size() > self.max_msg_length:
            self.reset()
            # If size is still too large after reset, allow failure to prevent infinite loop
            self.msg_builder.append(content_text)

    def _obtain_sender_method(self):
        return self.__send_new_message if self.current_message_id is None else self.__send_update_message

    def __send_new_message(self, message: Message):
        try:
            self.current_message_id = self.api_sender.send(message)
        finally:
            if self.current_message_id is None:
                # Reset current state since message_id wasn't obtained successfully
                # This prevents issues like:
                #  - Failing again due to corrupted message content
                #  - Duplicate messages if the original was sent but interrupted (e.g., KeyboardInterrupt)
                self.reset()

    def __send_update_message(self, message: Message):
        self.api_sender.update(message, self.current_message_id)

    def reset(self):
        self.msg_builder.clear()
        self.current_message_id = None

# Migration to remove outdated data dependencies
from django.db import migrations
from resolwe.flow.utils import iterate_fields

def cleanup_data_dependencies(apps, schema_editor):
    Data = apps.get_model("flow", "Data")
    DataDependency = apps.get_model("flow", "DataDependency")

    for record in Data.objects.iterator():
        parent_ids = []

        # Extract parent data IDs from input fields
        for field_schema, fields in iterate_fields(
            record.input, record.process.input_schema
        ):
            field_name = field_schema["name"]
            field_value = fields[field_name]

            if field_schema.get("type", "").startswith("data:"):
                parent_ids.append(field_value)
            elif field_schema.get("type", "").startswith("list:data:"):
                parent_ids.extend(field_value)

        # Filter out non-existent parent records
        parent_ids = [
            pk if Data.objects.filter(pk=pk).exists() else None for pk in parent_ids
        ]

        # Remove valid dependencies and delete invalid ones
        for dep in DataDependency.objects.filter(child=record.id, kind="io"):
            parent_id = dep.parent.pk if dep.parent else None
            if parent_id in parent_ids:
                parent_ids.remove(parent_id)
            else:
                dep.delete()

class Migration(migrations.Migration):
    dependencies = [
        ("flow", "0045_unreferenced_storages"),
    ]
    operations = [
        migrations.RunPython(cleanup_data_dependencies),
    ]

# Calculate expected value using analytical formula and simulate via random sampling
from math import factorial
from random import randrange

def analytical_solution(n):
    return sum(factorial(n) / (pow(n, i) * float(factorial(n - i))) for i in range(1, n + 1))

def simulation(n, iterations):
    total_count = 0
    for _ in range(iterations):
        current_value, mask = 1, 0
        while not (mask & current_value):
            total_count += 1
            mask |= current_value
            current_value = 1 << randrange(n)
    return total_count / iterations

