# Import necessary libraries
import numpy as np

class ActivationFunction:
    @staticmethod
    def sigmoid_function(input_signal, calculate_derivative=False):
        if calculate_derivative:
            return input_signal * (1 - input_signal)
        result = 1 / (1 + np.exp(-input_signal))
        return result

    @staticmethod
    def hyperbolic_tangent(input_signal, calculate_derivative=False):
        if calculate_derivative:
            return 1 - np.power(np.tanh(input_signal), 2)
        result = np.tanh(input_signal)
        return result

    @staticmethod
    def exponential_linear_unit(input_signal, calculate_derivative=False, coefficient=1.0):
        result = (input_signal >= 0).astype(int) * input_signal + \
                 (input_signal < 0).astype(int) * (coefficient * (np.exp(input_signal) - 1))
        if calculate_derivative:
            gradient = (input_signal >= 0).astype(int) + \
                       (input_signal < 0) * (result + coefficient)
            return gradient
        return result

    @staticmethod
    def softmax_function(input_signal, calculate_derivative=False):
        # Normalize for numerical stability
        input_signal = input_signal - np.max(input_signal)
        result = np.exp(input_signal) / np.array([np.sum(np.exp(input_signal), axis=1)]).T

        if calculate_derivative:
            # Compute Jacobian matrix
            jacobian_matrix = - result[..., None] * result[:, None, :]
            diagonal_y, diagonal_x = np.diag_indices_from(jacobian_matrix[0])
            jacobian_matrix[:, diagonal_y, diagonal_x] = result * (1 - result)
            return jacobian_matrix.sum(axis=1)

        return result

# Validate question data structure and constraints
import os
import sys
import json
import collections
import unicodedata

TEXT_KEY = "t"
CHOICES_KEY = "o"
TYPE_KEY = "k"
ANSWER_KEY = "c"
REQUIRED_KEYS = {TEXT_KEY, CHOICES_KEY, ANSWER_KEY}

def normalize_string(s):
    return unicodedata.normalize("NFD", s)

def raise_validation_error(msg, *, line_num):
    raise ValueError(" ".join((msg, "({})".format(line_num))))

def validate_questions(questions_list):
    text_occurrences = collections.defaultdict(list)
    for idx, q in enumerate(questions_list, start=1):
        # Check required fields are present
        missing_keys = REQUIRED_KEYS - set(q.keys())
        if missing_keys:
            raise_validation_error("missing {}".format(", ".join(missing_keys)), line_num=idx)

        normalized_text = normalize_string(q[TEXT_KEY])
        text_occurrences[normalized_text].append(idx)

        # Validate type field if present
        if TYPE_KEY in q and q[TYPE_KEY] != "tr":
            raise_validation_error("{} != tr".format(TYPE_KEY), line_num=idx)

        # Process options: normalize and check uniqueness/quantity
        choices_normalized = tuple(map(normalize_string, q[CHOICES_KEY]))
        num_choices = len(choices_normalized)
        if len(set(choices_normalized)) != num_choices or num_choices < 4:
            raise_validation_error(">= 4 unique options are required", line_num=idx)

        # Validate answer indices
        answers = q[ANSWER_KEY]
        if len(answers) < 1:
            raise_validation_error(">= 1 correct index is required", line_num=idx)

        for pos in answers:
            try:
                choices_normalized[pos]
            except IndexError:
                raise_validation_error("index {} is not addressable".format(pos), line_num=idx)

    # Ensure no duplicate questions by text
    for txt, positions in text_occurrences.items():
        if len(positions) > 1:
            raise_validation_error(
                "t {} is repeated at {}".format(
                    txt, ", ".join(map(str, positions[1:]))), line_num=positions[0])

def run_validation():
    questions_file = os.path.normpath(
        os.path.join(
            os.path.dirname(__file__), "..", "src", "questions.json"))
    with open(questions_file, "r", encoding="utf-8") as f:
        data = json.load(f)
    try:
        validate_questions(data)
    except ValueError as err:
        print(err, file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    run_validation()

