            Column('updated_at', DateTime, server_default=text('current_timestamp'), server_onupdate=text('current_timestamp')),
            )
    _resource_field = __table__.c.resource

    # Define resource property with IDNA support
    @hybrid_property
    def resource(self):
        if isinstance(self, Domain):
            return self._resource_field.encode('ascii').decode('idna')
        return self._resource_field

    @resource.setter
    def resource(self, input_value):
        if isinstance(input_value, text_type):
            self._resource_field = input_value.encode('idna').decode('utf-8').lower()
        elif isinstance(input_value, binary_type):
            self._resource_field = input_value
        else:
            raise ValueError("Unable to store value as requested.")

    @resource.comparator
    def resource(cls):
        return IdnaComparator(cls._resource_field)

import discord
import requests
from discord.ext import commands

class ProxyValidator:
    """Module for validating proxy servers"""
    def __init__(self, client):
        self.client = client

    @commands.command(pass_context=True)
    async def validate_proxy(self, context, proxy_address):
        """Validates the given proxy server."""
        proxy = proxy_address
        proxies = {
            'http': proxy,
            'https': proxy
        }
        try:
            response = requests.get('https://pgorelease.nianticlabs.com/plfe/version', 
                                   proxies=proxies, timeout=5)
            if response.status_code == 200:
                await self.client.say(':white_check_mark: 200 OK, proxy is not banned.')
            elif response.status_code == 403:
                await self.client.say(':x: 403 Forbidden, proxy is banned.')
        except requests.exceptions.Timeout:
            await self.client.say(':x: Timed out checking proxy.')
        except requests.exceptions.RequestException as error:
            await self.client.say('There appears to be an issue with your proxy. Ensure you include the port number and omit http/https from your input. Authentication is currently unsupported.')

        if not context.message.channel.is_private:
            await self.client.delete_message(context.message)

def setup(client):
    client.add_cog(ProxyValidator(client))

