# Implementation of merge sort algorithm
def sorting_function(data_list):
    # Create temporary storage for merging
    temp_buffer = [None] * len(data_list)
    _recursive_sort(data_list, temp_buffer, 0, len(data_list) - 1)

def _recursive_sort(arr, buffer, start, end):
    if start < end:
        mid_point = (start + end) // 2
        _recursive_sort(arr, buffer, start, mid_point)
        _recursive_sort(arr, buffer, mid_point + 1, end)
        combine(arr, buffer, start, mid_point, end)

def combine(array, aux, left_start, mid, right_end):
    left_pos = left_start
    right_pos = mid + 1

    # Merge elements into temporary buffer
    for pos in range(left_start, right_end + 1):
        if left_pos > mid:
            aux[pos] = array[right_pos]
            right_pos += 1
        elif right_pos > right_end:
            aux[pos] = array[left_pos]
            left_pos += 1
        elif array[left_pos] <= array[right_pos]:
            aux[pos] = array[left_pos]
            left_pos += 1
        else:
            aux[pos] = array[right_pos]
            right_pos += 1

    # Copy merged elements back to original array
    for idx in range(left_start, right_end + 1):
        array[idx] = aux[idx]

