# Script to verify keyword usage in locale files against source files
import json
import os

BASE_DIR = os.path.dirname(os.path.dirname(__file__))
LOCALE_FILE_PATH = os.path.join(BASE_DIR, "app/locales/taiga/locale-en.json")

def extract_keywords(path_parts, data):
    if path_parts is not None and not isinstance(data, dict):
        return [".".join(path_parts)]
    if path_parts is not None and isinstance(data, dict):
        result = []
        for sub_key in data.keys():
            result += extract_keywords(path_parts + [sub_key], data[sub_key])
        return result
    if path_parts is None and isinstance(data, dict):
        result = []
        for sub_key in data.keys():
            result += extract_keywords([sub_key], data[sub_key])
        return result

def load_file_content(file_path):
    with open(file_path) as file:
        return file.read()

def is_keyword_present(keyword, content_list):
    for content in content_list:
        if content.find(keyword) != -1:
            return True
    return False

def validate_keywords_in_usage():
    locale_data = json.load(open(LOCALE_FILE_PATH))
    all_project_files = []

    for current_dir, directories, filenames in os.walk(os.path.join(BASE_DIR, 'app')):
        relevant_files = list(filter(lambda f: f.endswith('.coffee') or f.endswith('.jade'), filenames))
        full_paths = map(lambda f: os.path.join(current_dir, f), relevant_files)
        all_project_files += full_paths

    file_contents = list(map(load_file_content, all_project_files))

    for kw in extract_keywords(None, locale_data):
        if not is_keyword_present(kw, file_contents):
            print("Keyword unused: {}".format(kw))

if __name__ == "__main__":
    validate_keywords_in_usage()

# Function to compute the length of the Collatz sequence starting from n
def collatz_length(n):
    count = 1
    # Iterative approach avoids recursion depth issues in Python
    # Memoization via decorators like functools.lru_cache can worsen recursion limits
    while n > 1:
        count += 1
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
    return count

# Find the number under 'limit' that produces the longest Collatz sequence
def max_collatz_chain(limit):
    best_result = {
        'value': 1,
        'steps': 1
    }
    for x in range(1, limit):
        steps = collatz_length(x)
        if steps > best_result['steps']:
            best_result = {
                'value': x,
                'steps': steps
            }
    return best_result

# Modified version of the original script with renamed variables and restructured logic
from __future__ import print_function
import json
import sys
import re

def extract_selection_criteria(selection_string):
    operation_list = []
    pending_operator = None

    for token in selection_string.strip().split(' '):
        if pending_operator:
            if pending_operator == '=':
                operation_list.append(lambda item, token=token: item == token)
            elif pending_operator == '=~':
                compiled_pattern = re.compile(token)
                operation_list.append(lambda item: isinstance(item, unicode) and compiled_pattern.match(item))
            pending_operator = None
            continue

        pending_operator = None
        if token == '{':
            outer_ops, inner_ops = operation_list, []
            operation_list = inner_ops
        elif token == '}':
            outer_ops.append(lambda item, ops=inner_ops: match_selection(ops, item))
            operation_list = outer_ops
            outer_ops, inner_ops = None, None
        elif token in {'=', '=~'}:
            pending_operator = token
        elif token.isdigit():
            operation_list.append(int(token))
        else:
            operation_list.append(token)

    return operation_list

def match_selection(selection_path, target_data):
    current_value = target_data
    for idx, operation in enumerate(selection_path):
        if callable(operation):
            if operation(current_value):
                continue
            else:
                return False

        if isinstance(operation, int):
            current_value = current_value[operation]
        else:
            if isinstance(current_value, list):
                remaining_path = selection_path[idx:]
                for element in current_value:
                    if match_selection(remaining_path, element):
                        return element
                return False
            else:
                current_value = current_value.get(operation)

        if current_value is None:
            return False

    return current_value

if __name__ == '__main__':
    command_args = sys.argv[1:]
    selection_path = extract_selection_criteria(command_args.pop(0)) if command_args else None
    total_matches = 0

    for line_num, raw_line in enumerate(sys.stdin):
        if not raw_line.rstrip():
            continue

        processed_line = raw_line.replace(b'\\\\"', b'\\"')

        if line_num % 100000 == 0:
            print("Processing line", line_num, file=sys.stderr)

        try:
            parsed_data = json.loads(processed_line)

            try:
                record_id = parsed_data.get('@id') or parsed_data['@graph'][0]['@id']
            except KeyError:
                record_id = None

            if selection_path:
                match_result = match_selection(selection_path, parsed_data)
                if match_result:
                    total_matches += 1
                    print("Line", line_num, "id", record_id, "matched on", json.dumps(match_result))
                    sys.stdout.flush()

        except ValueError as error:
            print("PARSE ERROR at line", line_num, "in data:", file=sys.stderr)
            print(raw_line, file=sys.stderr)
            print(error, file=sys.stderr)

            for position_match in re.findall(r'.+\(char (\d+)\)$', str(error)):
                char_pos = int(position_match)
                start = max(0, char_pos - 20)
                end = char_pos + 20
                print(raw_line[start:end], file=sys.stderr)
                print(('-' * 20) + '^', file=sys.stderr)
                break

    if selection_path:
        print("Total matches found:", total_matches)

