# Import required modules for logging and model handling
import logging
LOGGER = logging.getLogger('BigML')
import numbers
from bigml.model import Model

def average_value(data):
    """Compute the average of a list of numbers."""
    return float(sum(data)) / len(data) if len(data) > 0 else float('nan')

class EnsembleModel(object):
    """An ensemble local model.
    Combines multiple BigML remote models to create a local predictor that can
    generate predictions in bulk using majority voting for classification tasks
    and mean voting for regression tasks.
    """
    def __init__(self, model_list):
        self.models = []
        if isinstance(model_list, list):
            for item in model_list:
                self.models.append(Model(item))
        else:
            self.models.append(Model(model_list))

    def predict(self, features):
        """Generates predictions by aggregating outputs from all models.
        """
        results = []
        for model in self.models:
            results.append(model.predict(features, by_name=False))

        # Check if all predictions are numeric (regression case)
        if all([isinstance(result, numbers.Number) for result in results]):
            return average_value(results)
        else:
            # Classification case: use voting
            vote_counts = {}
            for result in results:
                if result in vote_counts:
                    vote_counts[result] += 1
                else:
                    vote_counts[result] = 1
            return max(vote_counts, key=vote_counts.get)

