# Import necessary modules for Redis, JSON handling, and Kyokai framework
import json
import aioredis
from kyokai import Request
from kyokai.context import HTTPRequestContext

async def cached_execution(ctx: HTTPRequestContext, handler_func, *handler_args, ttl=300):
    """
    Execute an async function with caching support using Redis.
    Stores the result in Redis with a configurable expiration time.
    """
    assert isinstance(ctx.redis, aioredis.Redis)

    # Generate cache key from function name and arguments
    cache_key = handler_func.__name__ + repr(handler_args)

    # Try to retrieve cached result
    cached_value = await ctx.redis.get(cache_key)
    if cached_value:
        return cached_value.decode()

    # Execute the handler function if not cached
    execution_result = await handler_func(ctx, *handler_args)

    # Store the result in Redis with TTL
    await ctx.redis.set(cache_key, execution_result, expire=ttl)
    return execution_result

def json_response_decorator(handler_func):
    """
    Decorator to convert function results into JSON responses.
    Adds request metadata to the response.
    """
    async def wrapper(ctx: HTTPRequestContext):
        original_result = await handler_func(ctx)

        assert isinstance(ctx.request, Request)

        if isinstance(original_result, tuple):
            # Add request metadata to the first element of the tuple
            modified_result = {
                "_request": {
                    "route": ctx.request.path,
                    "api_ver": 1
                },
                **original_result[0]
            }

            if len(original_result) == 1:
                return json.dumps(modified_result), 200, {"Content-Type": "application/json"}
            elif len(original_result) == 2:
                return json.dumps(modified_result), original_result[1], {"Content-Type": "application/json"}
            else:
                # Merge additional headers if provided
                extra_headers = {**{"Content-Type": "application/json"}, **original_result[2]}
                return json.dumps(modified_result), original_result[1], extra_headers
        else:
            # Handle non-tuple result by adding request metadata
            final_result = {
                "_request": {
                    "route": ctx.request.path,
                    "api_ver": 1
                },
                **original_result
            }
            return json.dumps(final_result), 200, {"Content-Type": "application/json"}

    return wrapper

