import functools
from pyp2rpm import settings

def cache_by_arguments(func):
    """Caches return value of a function based on its arguments."""
    cache = {}
    @functools.wraps(func)
    def wrapped(*args):
        if args not in cache:
            result = func(*args)
            cache[args] = result
        return cache[args]
    return wrapped

def get_license_from_classifiers(classifiers):
    """Extracts license information from a list of trove classifiers.
    Args:
        classifiers: list of trove classifier strings
    Returns:
        Fedora-compatible license name(s) joined by ' and ', or an empty string if none found.
    """
    licenses = []
    for classifier in classifiers:
        if classifier is None:
            continue
        if 'License' in classifier:
            cleaned = classifier.strip()
            # Handle EGG-INFO format where classifier may start with "Classifier:"
            if cleaned.startswith('Classifier:'):
                cleaned = cleaned[len('Classifier:'):]
            # Extract portion starting from 'License'
            idx = cleaned.find('License')
            if idx != -1:
                key = cleaned[idx:].strip()
                if key in settings.TROVE_LICENSES:
                    licenses.append(settings.TROVE_LICENSES[key])
    return ' and '.join(licenses)

