# API client for Unleashed Software
import requests
from auth import UnleashedAuth

class UnleashedClient(object):
    """
    Client for interacting with the Unleashed API.
    """
    def __init__(self, base_url, client_id, secret_key):
        self.base_url = base_url
        self.auth = UnleashedAuth(client_id, secret_key)

    def _send_get_request(self, endpoint, query_params=None):
        query_params = query_params or {}
        request_headers = {
            'content-type': 'application/json',
            'accept': 'application/json',
        }
        response = requests.get(
            self.base_url + '/' + endpoint,
            headers=request_headers,
            params=query_params,
            auth=self.auth
        )
        return response

    def _send_post_request(self, endpoint, payload):
        request_headers = {
            'content-type': 'application/json',
            'accept': 'application/json',
        }
        response = requests.post(
            self.base_url + '/' + endpoint,
            payload,
            headers=request_headers,
            auth=self.auth
        )
        return response

