    self.data_lines = data_lines
    self._answers = None
    self._rules = []

  @property
  def category(self):
    return str(type(self)).strip("'<>").split('.').pop()

  @property
  def answer(self):
    return self.answers().peek()

  def add_constraint(self, predicate):
    self._rules.append(predicate)
    # Reset cached solutions
    self._answers = None

  def answers(self):
    if self._answers is None:
      self._answers = meta.Meta(
          (key, value) for key, value in self._compute().items() if all(
              [predicate(key, value) for predicate in self._rules]
          )
      )
    return self._answers

  def _compute(self):
    """Computes possible solutions.
    Returns:
      dict Mapping potential solution to its score.
    """
