def clean_stream_names(apps, schema_editor):
    # type: (StateApps, DatabaseSchemaEditor) -> None
    StreamModel = apps.get_model('zerver', 'Stream')
    SPECIAL_CHARS = ['*', '@', '`', '#']

    for stream in StreamModel.objects.all():
        if set(stream.name).intersection(SPECIAL_CHARS):
            for char in SPECIAL_CHARS:
                stream.name = stream.name.replace(char, ' ').strip()

            # Ensure uniqueness by appending '^' if needed
            while StreamModel.objects.filter(name__iexact=stream.name, realm=stream.realm).exists():
                stream.name = stream.name + '^'
                # Enforce maximum length constraint
                if len(stream.name) > 60:
                    stream.name = stream.name[-60:]

            stream.save(update_fields=['name'])

