# Compute the maximum chain length of words 
def maxWordChain(wordList):
    if not wordList:
        return 0

    # Dictionary mapping word length to set of words with that length
    lengthMap = {}
    lengths = []

    # Build dictionary where key is word length, value is dict of words
    for w in wordList:
        length = len(w)
        if length in lengthMap:
            lengthMap[length][w] = 1
        else:
            lengthMap[length] = {w: 1}
            lengths.append(length)

    # Sort lengths in ascending order
    lengths.sort()

    maxChainLength = 1
    # Process each length starting from second smallest
    for i in range(1, len(lengths)):
        currentLen = lengths[i]
        prevLen = currentLen - 1

        if prevLen in lengthMap:
            currentWords = lengthMap[currentLen]
            for word in currentWords:
                # Try removing each character to form predecessor
                for idx in range(len(word)):
                    predecessor = word[:idx] + word[idx + 1:]
                    if predecessor in lengthMap[prevLen]:
                        newChainLength = lengthMap[prevLen][predecessor] + 1
                        if newChainLength > lengthMap[currentLen][word]:
                            lengthMap[currentLen][word] = newChainLength
                            if newChainLength > maxChainLength:
                                maxChainLength = newChainLength

    return maxChainLength

