# Function to find the next palindrome greater than the given number
def find_next_palindrome(num_str):
    digits = list(num_str)
    length = len(num_str)
    center = length // 2

    # Check if we need to mirror from right to left
    should_mirror = False
    for idx in range(center, length):
        opposite_idx = length - 1 - idx
        if num_str[idx] < num_str[opposite_idx]:
            should_mirror = True
        if should_mirror:
            digits[idx] = digits[opposite_idx]

    # If mirroring didn't work, increment middle digit(s)
    if not should_mirror:
        pos = (length - 1) // 2
        while pos >= 0 and num_str[pos] == '9':
            pos -= 1
        if pos >= 0:
            digits[pos] = str(int(num_str[pos]) + 1)
            for k in range(pos + 1, (length + 1) // 2):
                digits[k] = '0'
            for k in range((length + 1) // 2, length):
                opposite_idx = length - 1 - k
                digits[k] = digits[opposite_idx]
        else:
            # Handle case like "999" -> "1001"
            digits = ['0'] * (length + 1)
            digits[0] = digits[-1] = '1'

    return ''.join(digits)

if __name__ == '__main__':
    test_cases = int(input())
    for _ in range(test_cases):
        number = input()
        print(find_next_palindrome(number))

