def retrieve_function_check_data(workspace_path, check_file_name):
    """Extract function check data from the specified file."""
    full_path = os.path.abspath(os.path.join(workspace_path, check_file_name))
    if not os.path.isfile(full_path):
        return False, {"error": f"Function check file '{check_file_name}' does not exist."}
    try:
        tag_list = fc.get_unity_chip_doc_marks(full_path, "CK", 1)
    except Exception as err:
        error_msg = str(err)
        warning(f"Exception encountered during processing of {check_file_name}: {error_msg}")
        warning(traceback.format_exc())
        error_messages = [f"Documentation parsing failed for '{check_file_name}': {error_msg}."]
        if "\\n" in error_msg:
            error_messages.append("Literal '\\n' characters detected - use actual line breaks instead of escaped characters")
        error_messages.append({
            "check_list": [
                "Malformed tags: Ensure proper format. e.g., <FG-NAME>, <FC-NAME>, <CK-NAME>",
                *fc.description_func_doc(),
                "Invalid characters: Use only alphanumeric and hyphen in tag names",
                "Missing tag closure: All tags must be properly closed",
                "Encoding issues: Ensure file is saved in UTF-8 format",
            ]
        })
        return False, {"error": error_messages}
    return True, tag_list

def validate_line_mapping_for_single_file(workspace_path, input_source, mapping_file, tag_collection,
                                          tag_file_name, mapping_suffix, mapping_dir,
                                          max_examples_to_show: int, enforce_no_mismatch: bool,
                                          callback_unmatched=None, callback_matched=None):
    """Validate line-to-function mapping for a single source file."""
    info(f"Validating line-function mapping for '{input_source}'...")
    abs_source = os.path.abspath(os.path.join(workspace_path, input_source))
    if not os.path.exists(abs_source):
        return False, {"error": f"Source file '{input_source}' does not exist."}

    # Generate default mapping filename if not provided
    if not mapping_file:
        base_name = input_source.replace(os.path.sep, "_").replace(".", "_") + mapping_suffix
        mapping_file = os.path.join(mapping_dir, base_name)

    abs_map_path = os.path.abspath(os.path.join(workspace_path, mapping_file))
    if not os.path.exists(abs_map_path):
        return False, {"error": f"Mapping file '{mapping_file}' does not exist. You should create it first."}

    try:
        line_tag_mapping = fc.parse_line_CK_map_file(workspace_path, mapping_file)
    except Exception as err:
        error_msg = str(err)
        warning(f"Error occurred while parsing mapping file {mapping_file}: {error_msg}")
        warning(traceback.format_exc())
        return False, {"error": f"Mapping file parsing failed for '{mapping_file}': {error_msg}."}

    # Compare tag collection with line-tag mapping
    mismatched_entries = []
    invalid_keys = []
    for key in line_tag_mapping.keys():
        if key not in tag_collection:
            if str(key).startswith("IGNORE/"):
                continue
            if str(key).startswith("MISSMT/"):
                mismatched_entries.append((key, line_tag_mapping[key]))
                continue
            invalid_keys.append((key, line_tag_mapping[key]))
            if callback_unmatched:
                callback_unmatched(key, line_tag_mapping[key])
        else:
            if callback_matched:
                callback_matched(key, line_tag_mapping[key])

    # Report unmapped entries
    if len(invalid_keys) > 0:
        emsg = [f"Detected {len(invalid_keys)} line block(s) in mapping file '{mapping_file}' without corresponding CK tags:"]
        for tag_name, _ in invalid_keys[:max_examples_to_show]:
            emsg.append(f"  '{tag_name}' which is absent in documentation file '{tag_file_name}'.")
        if len(invalid_keys) > max_examples_to_show:
            emsg.append(f"  ... and {len(invalid_keys) - max_examples_to_show} more.")
        emsg.append("Valid CKs present are:")
        for tag in tag_collection[:max_examples_to_show]:
            emsg.append(f"  '{tag}'")
        if len(tag_collection) > max_examples_to_show:
            emsg.append(f"  ... and {len(tag_collection) - max_examples_to_show} more.")
        return False, {"error": emsg}

    # Report miss-matched entries if required
    if enforce_no_mismatch and len(mismatched_entries) > 0:
        emsg = [f"Found {len(mismatched_entries)} line block(s) marked as MISSMT (miss-matched) in '{mapping_file}':"]
        for tag_name, _ in mismatched_entries[:max_examples_to_show]:
            emsg.append(f"  '{tag_name}' which lacks a match in documentation file '{tag_file_name}'.")
        if len(mismatched_entries) > max_examples_to_show:
            emsg.append(f"  ... and {len(mismatched_entries) - max_examples_to_show} more.")
        emsg.append(f"You need to add these missing CKs to '{tag_file_name}' or adjust the mapping.")
        return False, {"error": emsg}

    # Identify unmapped lines in source
    unmapped_lines, details = fc.get_un_mapped_lines(
        workspace_path, input_source, line_tag_mapping, max_examples_to_show
    )
    if len(unmapped_lines) > 0:
        emsg = f"Detected {len(unmapped_lines)} unmapped line block(s) in '{input_source}':\n{details}"
        return False, {"error": emsg}

    info(f"All lines in '{input_source}' have been successfully mapped.")
    return True, f"All lines in '{input_source}' are properly mapped."

class FileLineMapValidator(Checker):
    """Validate unmapped lines in a file using line-function mapping."""
    def __init__(self, source_filename, func_check_filename,
                 map_filename=None,
                 map_extension="_line_func_map.txt",
                 map_directory="line_map",
                 max_example_lines=20, requires_human_review=False, enforce_strict_mapping=False, **kwargs):
        self.source_file = source_filename
        self.func_check_file = func_check_filename
        self.map_file = map_filename
        self.map_suffix = map_extension
        self.map_location = map_directory
        self.max_example_lines = max_example_lines
        self.must_has_no_miss_match = enforce_strict_mapping
        self.set_human_check_needed(requires_human_review)

    def do_check(self, **kwargs) -> tuple[bool, object]:
        """Execute validation for unmapped lines."""
        success, tag_data_or_error = retrieve_function_check_data(
            self.workspace, self.func_check_file
        )
        if not success:
            return False, tag_data_or_error

        success, outcome = validate_line_mapping_for_single_file(
            self.workspace,
            self.source_file,
            self.map_file,
            tag_data_or_error,
            self.func_check_file,
            self.map_suffix,
            self.map_location,
            self.max_example_lines,
            self.must_has_no_miss_match
        )
        return success, outcome

