from .p0_kernel_core import validate_with_understanding

def check_candidate(context: dict, proposal: dict) -> dict:
    """Evaluate a proposed action or message for safety and compliance.

    context: metadata about the usage scenario, e.g.:
      {
        "channel": "moltx|clawchat|internal",
        "task": "post|reply|tool_call|memory_write",
        "user_intent": "string description of user goal",
        "risk_tolerance": "low|medium|high"
      }
    proposal: {
      "content": "text of reply or description of intended action",
      "metadata": {... optional additional info ...}
    }
    """
    text = proposal.get("content", "")
    result = validate_with_understanding(text, context)
    return result

def protection_decorator(func):
    """Decorator to wrap a generation function with security validation checks.
    Example usage:
    @protection_decorator
    def produce_response(context, *args, **kwargs):
        return llm_generate(...)
    """
    def inner_wrapper(context, *args, **kwargs):
        raw_output = func(context, *args, **kwargs)
        evaluation = check_candidate(context, {"content": raw_output})
        decision = evaluation.get("action", "allow")

        if decision == "allow":
            return raw_output
        elif decision == "flag":
            explanation = evaluation.get("understanding") or "Security system flagged this content as potentially risky."
            return f"{raw_output}\n\n[LYGO Protection Note]: {explanation}"
        elif decision == "isolate":
            return "[BLOCKED BY LYGO PROTECTION: content failed Nano-Kernel validation]"
        else:
            # fallback / default case
            return "[LYGO PROTECTION REQUIRES HUMAN REVIEW BEFORE SENDING THIS]"
    return inner_wrapper

# Dynamic batching data loader implementation for training with variable-length sequences
import traceback
import warnings
from collections.abc import Iterable
import torch
from torch.utils.data import default_collate
from megatron.training import print_rank_0
from mindspeed_mm.data.dataloader.batching_strategy import TextBatchingStrategy

class DynamicBatchingDataLoader:
    def __init__(
        self,
        data_loader,
        max_sequence_length: int,
        dynamic_buffer_capacity: int,
        remove_incomplete: bool = False,
        vision_format: str = 'TND',
        trained_samples_count: int = 0
    ) -> None:
        print_rank_0("[INFO] initializing dynamic batching DataLoader")
        self.vision_layout = vision_format
        self.original_loader = data_loader
        self.total_steps = len(self.original_loader)
        self.batching_mechanism = TextBatchingStrategy(
            max_seq_len=max_sequence_length,
            buffer_size=dynamic_buffer_capacity,
        )
        self.remove_last = remove_incomplete
        self.trained_samples_count = trained_samples_count
        self.fixed_data = {}
        print_rank_0("[INFO] Successfully initialize dynamic batching DataLoader")

    def __len__(self):
        return len(self.original_loader)

    def __iter__(self):
        self.current_step = 0
        self._source_iter = iter(self.original_loader)
        self._processed_iter = self.dynamic_batching_generator()
        return self

    def __next__(self):
        return next(self._processed_iter)

    def dynamic_batching_generator(self):
        while True:
            if self.batching_mechanism.is_full_filled():
                mini_batch = self._create_mini_batch()
                yield mini_batch
                self.current_step += 1

            try:
                current_item = self._fetch_next_sample()
            except Exception as err:
                if isinstance(err, StopIteration):
                    if not self.remove_last and not self.batching_mechanism.empty():
                        while not self.batching_mechanism.empty():
                            mini_batch = self._create_mini_batch()
                            yield mini_batch
                            self.current_step += 1
                        return
                    else:
                        return
                else:
                    print(f"DynamicBatchDataset iter data exception: {err} \n{traceback.format_exc()}")
                    raise

            # Add current_item to buffer
            if isinstance(current_item, dict):
                current_item = [current_item]
            for sample in current_item:
                self.batching_mechanism.put_item(sample)

    def _fetch_next_sample(self):
        batch_data = next(self._source_iter)
        # Extract non-packing data, these will be reinserted later
        original_mb_size = batch_data['input_ids'].shape[0]
        for key, val in batch_data.items():
            if not isinstance(val, Iterable) or isinstance(val, (str, bytes)):
                self.fixed_data[key] = val
            elif key != 'pixel_values' and len(val) != original_mb_size:
                warnings.warn(
                    f"The iterable data {key} (of type {type(val)}) in micro batch extracted from "
                    f"the original dataloader has a length inconsistent with the micro batch size (mbs). To ensure "
                    f"correct decomposition into mbs individual samples, it has been moved to fixed_data. "
                    f"Please verify the actual purpose of this data and apply appropriate adjustments."
                )
                self.fixed_data[key] = val
        for key in self.fixed_data:
            batch_data.pop(key)
        keys_list = list(batch_data.keys())
        batch_data['input_ids'] = [batch_data['input_ids'][i][mask] for i, mask in enumerate(batch_data['attention_mask'].bool())]
        batch_data['labels'] = [batch_data['labels'][i][mask] for i, mask in enumerate(batch_data['attention_mask'].bool())]
        batch_data['attention_mask'] = [
            batch_data['attention_mask'][i][mask]
            for i, mask in enumerate(batch_data['attention_mask'].bool())
        ]
        pixel_counts = batch_data['image_grid_thw'][:, 0] * batch_data['image_grid_thw'][:, 1] * batch_data['image_grid_thw'][:, 2]
        batch_data['pixel_values'] = batch_data['pixel_values'].split(pixel_counts.tolist())
        return [dict(zip(keys_list, row)) for row in zip(*batch_data.values())]

    def _create_mini_batch(self):
        mini_batch = self.batching_mechanism.get_micro_batch()
        self.trained_samples_count += len(mini_batch)
        mini_batch = self.aggregate_fn(mini_batch, self.vision_layout)
        return mini_batch

    def aggregate_fn(self, samples, vision_format):
        seq_lengths = torch.tensor([len(sample['input_ids']) for sample in samples], dtype=torch.long)
        aggregated_batch = {"seqlens": seq_lengths}
        # Reintroduce non-packing data that was removed earlier
        for key, value in self.fixed_data.items():
            aggregated_batch[key] = value
        for field_name in samples[0].keys():
            if field_name in ('input_ids', 'attention_mask', 'labels'):
                aggregated_batch[field_name] = torch.cat([sample[field_name] for sample in samples]).unsqueeze(0)
            else:
                if field_name == 'pixel_values' and vision_format == "TND":
                    aggregated_batch[field_name] = torch.cat([sample[field_name] for sample in samples])
                else:
                    aggregated_batch[field_name] = default_collate([sample[field_name] for sample in samples])
        if "attention_mask" in aggregated_batch.keys():
            aggregated_batch["indices"] = torch.arange(len(aggregated_batch["attention_mask"][0]))
        else:
            raise ValueError("Need attention mask to generate indices")
        return aggregated_batch

