# Transpiler from EAST3 AST to Kotlin Native code
from __future__ import annotations
from typing import Any

# Kotlin reserved keywords that need suffixing
_KOTLIN_KEYWORDS = {
    "as",
    "break",
    "class",
    "continue",
    "do",
    "else",
    "false",
    "for",
    "fun",
    "if",
    "in",
    "interface",
    "is",
    "null",
    "object",
    "package",
    "return",
    "super",
    "this",
    "throw",
    "true",
    "try",
    "typealias",
    "val",
    "var",
    "when",
    "while",
}

# Global tracking for classes and functions
_CLASS_NAMES: set[str] = set()
_FUNCTION_NAMES: set[str] = set()
_CLASS_BASES: dict[str, str] = {}
_CLASS_METHODS: dict[str, set[str]] = {}

def _make_valid_identifier(name: Any, default_val: str) -> str:
    """Convert a name to a valid identifier, escaping Kotlin keywords."""
    if not isinstance(name, str) or name == "":
        return default_val
    chars: list[str] = []
    idx = 0
    while idx < len(name):
        ch = name[idx]
        if ch.isalnum() or ch == "_":
            chars.append(ch)
        else:
            chars.append("_")
        idx += 1
    result = "".join(chars)
    if result == "":
        result = default_val
    if result[0].isdigit():
        result = "_" + result
    if result in _KOTLIN_KEYWORDS:
        result = result + "_"
    return result

def _escape_kotlin_string(text: str) -> str:
    """Escape special characters in a string for Kotlin."""
    out = text.replace("\\", "\\\\")
    out = out.replace('"', '\\"')
    out = out.replace("\n", "\\n")
    return '"' + out + '"'

def _extract_module_comments(east_doc: dict[str, Any], comment_prefix: str) -> list[str]:
    """Extract leading comments from module."""
    trivia_any = east_doc.get("module_leading_trivia")
    trivia = trivia_any if isinstance(trivia_any, list) else []
    result: list[str] = []
    for item_any in trivia:
        if not isinstance(item_any, dict):
            continue
        kind = item_any.get("kind")
        if kind == "comment":
            text = item_any.get("text")
            if isinstance(text, str):
                result.append(comment_prefix + text)
            continue
        if kind == "blank":
            count = item_any.get("count")
            n = count if isinstance(count, int) and count > 0 else 1
            i = 0
            while i < n:
                result.append("")
                i += 1
    while len(result) > 0 and result[-1] == "":
        result.pop()
    return result

def _extract_leading_comments(stmt: dict[str, Any], comment_prefix: str, indent: str = "") -> list[str]:
    """Extract leading comments from a statement."""
    trivia_any = stmt.get("leading_trivia")
    trivia = trivia_any if isinstance(trivia_any, list) else []
    result: list[str] = []
    for item_any in trivia:
        if not isinstance(item_any, dict):
            continue
        kind = item_any.get("kind")
        if kind == "comment":
            text = item_any.get("text")
            if isinstance(text, str):
                result.append(indent + comment_prefix + text)
            continue
        if kind == "blank":
            count = item_any.get("count")
            n = count if isinstance(count, int) and count > 0 else 1
            i = 0
            while i < n:
                result.append("")
                i += 1
    while len(result) > 0 and result[-1] == "":
        result.pop()
    return result

def _convert_type_to_kotlin(type_name: Any, *, allow_void: bool) -> str:
    """Convert a Python type to Kotlin type."""
    if not isinstance(type_name, str):
        return "Any?"
    if type_name == "None":
        return "Unit" if allow_void else "Any?"
    if type_name in {"int", "int64", "uint8"}:
        return "Long"
    if type_name in {"float", "float64"}:
        return "Double"
    if type_name == "bool":
        return "Boolean"
    if type_name == "str":
        return "String"
    if type_name.startswith("list[") or type_name.startswith("tuple["):
        return "MutableList<Any?>"
    if type_name.startswith("dict["):
        return "MutableMap<Any, Any?>"
    if type_name in {"bytes", "bytearray"}:
        return "MutableList<Any?>"
    if type_name in {"unknown", "object", "any"}:
        return "Any?"
    if type_name.isidentifier():
        return _make_valid_identifier(type_name, "Any")
    return "Any?"

def _get_default_value(kotlin_type: str) -> str:
    """Get default value for a Kotlin type."""
    if kotlin_type == "Long":
        return "0L"
    if kotlin_type == "Double":
        return "0.0"
    if kotlin_type == "Boolean":
        return "false"
    if kotlin_type == "String":
        return '""'
    if kotlin_type == "MutableList<Any?>":
        return "mutableListOf()"
    if kotlin_type == "MutableMap<Any, Any?>":
        return "mutableMapOf()"
    if kotlin_type == "Unit":
        return ""
    if kotlin_type == "Any?":
        return "null"
    return kotlin_type + "()"

def _check_method_in_base(class_name: str, method_name: str) -> bool:
    """Check if a method exists in base classes."""
    base = _CLASS_BASES.get(class_name, "")
    while base != "":
        methods = _CLASS_METHODS.get(base, set())
        if method_name in methods:
            return True
        base = _CLASS_BASES.get(base, "")
    return False

def _parse_tuple_types(type_name: Any) -> list[str]:
    """Parse element types from tuple type string."""
    if not isinstance(type_name, str):
        return []
    if not type_name.startswith("tuple[") or not type_name.endswith("]"):
        return []
    body = type_name[6:-1]
    result: list[str] = []
    buffer = ""
    depth = 0
    idx = 0
    while idx < len(body):
        ch = body[idx]
        if ch == "[":
            depth += 1
            buffer += ch
            idx += 1
            continue
        if ch == "]":
            depth -= 1
            buffer += ch
            idx += 1
            continue
        if ch == "," and depth == 0:
            piece = buffer.strip()
            if piece != "":
                result.append(piece)
            buffer = ""
            idx += 1
            continue
        buffer += ch
        idx += 1
    tail = buffer.strip()
    if tail != "":
        result.append(tail)
    return result

def _remove_outer_parens(expr: str) -> str:
    """Remove outer parentheses from expression."""
    current = expr.strip()
    while len(current) >= 2 and current[0] == "(" and current[-1] == ")":
        depth = 0
        valid = True
        idx = 0
        while idx < len(current):
            ch = current[idx]
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0 and idx != len(current) - 1:
                    valid = False
                    break
                if depth < 0:
                    valid = False
                    break
            idx += 1
        if not valid or depth != 0:
            break
        current = current[1:-1].strip()
    return current

def _is_direct_function_call(expr: str, fn_name: str) -> bool:
    """Check if expression is a direct function call."""
    txt = _remove_outer_parens(expr)
    prefix = fn_name + "("
    if not txt.startswith(prefix) or not txt.endswith(")"):
        return False
    depth = 0
    idx = len(fn_name)
    while idx < len(txt):
        ch = txt[idx]
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0 and idx != len(txt) - 1:
                return False
            if depth < 0:
                return False
        idx += 1
    return depth == 0

def _wrap_with_runtime_call(expr: str, fn_name: str) -> str:
    """Wrap expression with runtime function call."""
    inner = _remove_outer_parens(expr)
    if _is_direct_function_call(inner, fn_name):
        return inner
    return fn_name + "(" + inner + ")"

def _to_int_expression(expr: str) -> str:
    return _wrap_with_runtime_call(expr, "__pytra_int")

def _to_float_expression(expr: str) -> str:
    return _wrap_with_runtime_call(expr, "__pytra_float")

def _to_boolean_expression(expr: str) -> str:
    return _wrap_with_runtime_call(expr, "__pytra_truthy")

def _to_string_expression(expr: str) -> str:
    return _wrap_with_runtime_call(expr, "__pytra_str")

def _to_list_expression(expr: str) -> str:
    return _wrap_with_runtime_call(expr, "__pytra_as_list")

def _to_dict_expression(expr: str) -> str:
    return _wrap_with_runtime_call(expr, "__pytra_as_dict")

def _has_expected_type(node: Any, expected: set[str]) -> bool:
    if not isinstance(node, dict):
        return False
    resolved_any = node.get("resolved_type")
    if not isinstance(resolved_any, str):
        return False
    return resolved_any in expected

def _ensure_integer_operand(expr: str, node: Any) -> str:
    if _has_expected_type(node, {"int", "int64", "uint8"}):
        return expr
    return _to_int_expression(expr)

def _ensure_float_operand(expr: str, node: Any) -> str:
    if _has_expected_type(node, {"float", "float64"}):
        return expr
    return _to_float_expression(expr)

def _is_integer_literal(node: Any, expected: int) -> bool:
    if isinstance(node, int) and not isinstance(node, bool):
        return node == expected
    if not isinstance(node, dict):
        return False
    if node.get("kind") != "Constant":
        return False
    value = node.get("value")
    if isinstance(value, bool):
        return False
    return isinstance(value, int) and value == expected

def _cast_from_any_value(expr: str, kotlin_type: str) -> str:
    if kotlin_type == "Long":
        return _to_int_expression(expr)
    if kotlin_type == "Double":
        return _to_float_expression(expr)
    if kotlin_type == "Boolean":
        return _to_boolean_expression(expr)
    if kotlin_type == "String":
        return _to_string_expression(expr)
    if kotlin_type == "MutableList<Any?>":
        return _to_list_expression(expr)
    if kotlin_type == "MutableMap<Any, Any?>":
        return _to_dict_expression(expr)
    if kotlin_type == "Any?":
        return expr
    if kotlin_type in _CLASS_NAMES:
        return "__pytra_as_" + kotlin_type + "(" + expr + ")"
    return expr

def _render_variable_expr(expr: dict[str, Any]) -> str:
    name = _make_valid_identifier(expr.get("id"), "value")
    if name == "self":
        return "this"
    if name in _FUNCTION_NAMES:
        return "::" + name
    return name

def _render_constant_value(expr: dict[str, Any]) -> str:
    if "value" not in expr:
        return "__pytra_any_default()"
    value = expr.get("value")
    if value is None:
        resolved = expr.get("resolved_type")
        if resolved in {"int", "int64", "uint8"}:
            return "0L"
        if resolved in {"float", "float64"}:
            return "0.0"
        if resolved == "bool":
            return "false"
        if resolved == "str":
            return '""'
        return "__pytra_any_default()"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value) + "L"
    if isinstance(value, float):
        return str(value)
    if isinstance(value, str):
        return _escape_kotlin_string(value)
    return "__pytra_any_default()"

def _render_boolean_expression(expr: Any) -> str:
    if not isinstance(expr, dict):
        return "__pytra_truthy(" + _render_expression(expr) + ")"
    resolved = expr.get("resolved_type")
    rendered = _render_expression(expr)
    if isinstance(resolved, str):
        if resolved == "bool":
            return rendered
        if resolved in {"int", "int64", "uint8"}:
            return "(" + rendered + " != 0L)"
        if resolved in {"float", "float64"}:
            return "(" + rendered + " != 0.0)"
        if resolved == "str":
            return "(" + rendered + " != \"\")"
        if resolved.startswith("list[") or resolved.startswith("tuple[") or resolved.startswith("dict[") or resolved in {"bytes", "bytearray"}:
            return "(__pytra_len(" + rendered + ") != 0L)"
    kind = expr.get("kind")
    if kind in {"Compare", "BoolOp", "IsInstance"}:
        return rendered
    return "__pytra_truthy(" + rendered + ")"

def _get_binary_operator_symbol(op: Any) -> str:
    if op == "Add":
        return "+"
    if op == "Sub":
        return "-"
    if op == "Mult":
        return "*"
    if op == "Div":
        return "/"
    if op == "Mod":
        return "%"
    if op == "FloorDiv":
        return "/"
    if op == "LShift":
        return "shl"
    if op == "RShift":
        return "shr"
    if op == "BitAnd":
        return "and"
    if op == "BitOr":
        return "or"
    if op == "BitXor":
        return "xor"
    return "+"

def _render_unary_operation(expr: dict[str, Any]) -> str:
    op = expr.get("op")
    operand = _render_expression(expr.get("operand"))
    if op == "USub":
        return "(-" + operand + ")"
    if op == "UAdd":
        return "(+" + operand + ")"
    if op == "Not":
        return "(!" + _render_boolean_expression(expr.get("operand")) + ")"
    return operand

def _render_binary_operation(expr: dict[str, Any]) -> str:
    op = expr.get("op")
    if op == "Mult":
        left_any = expr.get("left")
        right_any = expr.get("right")
        if isinstance(left_any, dict) and left_any.get("kind") == "List":
            elems_any = left_any.get("elements")
            elems = elems_any if isinstance(elems_any, list) else []
            if len(elems) == 1:
                return "__pytra_list_repeat(" + _render_expression(elems[0]) + ", " + _render_expression(right_any) + ")"
        if isinstance(right_any, dict) and right_any.get("kind") == "List":
            elems_any = right_any.get("elements")
            elems = elems_any if isinstance(elems_any, list) else []
            if len(elems) == 1:
                return "__pytra_list_repeat(" + _render_expression(elems[0]) + ", " + _render_expression(left_any) + ")"
    left_node = expr.get("left")
    right_node = expr.get("right")
    left_expr = _render_expression(left_node)
    right_expr = _render_expression(right_node)
    resolved = expr.get("resolved_type")
    if op == "Div":
        return "(" + _ensure_float_operand(left_expr, left_node) + " / " + _ensure_float_operand(right_expr, right_node) + ")"
    if op == "FloorDiv":
        return "(" + _ensure_integer_operand(left_expr, left_node) + " / " + _ensure_integer_operand(right_expr, right_node) + ")"
    if op == "Mod":
        return "(" + _ensure_integer_operand(left_expr, left_node) + " % " + _ensure_integer_operand(right_expr, right_node) + ")"
    if op == "LShift" or op == "RShift":
        shift_kw = "shl" if op == "LShift" else "shr"
        lhs = _ensure_integer_operand(left_expr, left_node)
        rhs = _ensure_integer_operand(right_expr, right_node)
        return "(" + lhs + " " + shift_kw + " (" + rhs + ").toInt())"
    if resolved == "str" and op == "Add":
        return "(" + _to_string_expression(left_expr) + " + " + _to_string_expression(right_expr) + ")"
    if resolved in {"int", "int64", "uint8"}:
        sym = _get_binary_operator_symbol(op)
        return "(" + _ensure_integer_operand(left_expr, left_node) + " " + sym + " " + _ensure_integer_operand(right_expr, right_node) + ")"
    if resolved in {"float", "float64"}:
        sym = _get_binary_operator_symbol(op)
        return "(" + _ensure_float_operand(left_expr, left_node) + " " + sym + " " + _ensure_float_operand(right_expr, right_node) + ")"
    sym = _get_binary_operator_symbol(op)
    return "(" + left_expr + " " + sym + " " + right_expr + ")"

def _get_comparison_operator_symbol(op: Any) -> str:
    if op == "Eq":
        return "=="
    if op == "NotEq":
        return "!="
    if op == "Lt":
        return "<"
    if op == "LtE":
        return "<="
    if op == "Gt":
        return ">"
    if op == "GtE":
        return ">="
    return "=="

def _render_comparison_expression(expr: dict[str, Any]) -> str:
    left = _render_expression(expr.get("left"))
    ops_any = expr.get("ops")
    comps_any = expr.get("comparators")
    ops = ops_any if isinstance(ops_any, list) else []
    comps = comps_any if isinstance(comps_any, list) else []
    if len(ops) == 0 or len(comps) == 0:
        return "false"
    parts: list[str] = []
    current_left = left
    idx = 0
    while idx < len(ops) and idx < len(comps):
        comp_node = comps[idx]
        right = _render_expression(comp_node)
        op = ops[idx]
        if op == "In" or op == "NotIn":
            expr_txt = "__pytra_contains(" + right + ", " + current_left + ")"
            if op == "NotIn":
                expr_txt = "(!" + expr_txt + ")"
            parts.append("(" + expr_txt + ")")
            current_left = right
            idx += 1
            continue
        left_type = ""
        right_type = ""
        if idx == 0 and isinstance(expr.get("left"), dict):
            left_any = expr.get("left", {}).get("resolved_type")
            left_type = left_any if isinstance(left_any, str) else ""
        elif idx > 0 and isinstance(comps[idx - 1], dict):
            left_any = comps[idx - 1].get("resolved_type")
            left_type = left_any if isinstance(left_any, str) else ""
        if isinstance(comp_node, dict):
            right_any = comp_node.get("resolved_type")
            right_type = right_any if isinstance(right_any, str) else ""
        symbol = _get_comparison_operator_symbol(op)
        if left_type == "str" or right_type == "str":
            lhs = _to_string_expression(current_left)
            rhs = _to_string_expression(right)
            parts.append("(" + lhs + " " + symbol + " " + rhs + ")")
        elif left_type in {"int", "int64", "uint8"} or right_type in {"int", "int64", "uint8"}:
            lhs = _to_int_expression(current_left)
            rhs = _to_int_expression(right)
            parts.append("(" + lhs + " " + symbol + " " + rhs + ")")
        elif left_type in {"float", "float64"} or right_type in {"float", "float64"}:
            lhs = _to_float_expression(current_left)
            rhs = _to_float_expression(right)
            parts.append("(" + lhs + " " + symbol + " " + rhs + ")")
        else:
            if op in {"Eq", "NotEq"}:
                lhs = _to_string_expression(current_left)
                rhs = _to_string_expression(right)
                parts.append("(" + lhs + " " + symbol + " " + rhs + ")")
            else:
                lhs = _to_float_expression(current_left)
                rhs = _to_float_expression(right)
                parts.append("(" + lhs + " " + symbol + " " + rhs + ")")
        current_left = right
        idx += 1
    if len(parts) == 1:
        return parts[0]
    return "(" + " && ".join(parts) + ")"

def _render_boolean_operation(expr: dict[str, Any]) -> str:
    op = expr.get("op")
    values_any = expr.get("values")
    values = values_any if isinstance(values_any, list) else []
    if len(values) == 0:
        return "false"
    rendered: list[str] = []
    idx = 0
    while idx < len(values):
        rendered.append(_render_boolean_expression(values[idx]))
        idx += 1
    delimiter = " && " if op == "And" else " || "
    return "(" + delimiter.join(rendered) + ")"

def _snake_to_pascal_case(name: str) -> str:
    parts = name.split("_")
    result: list[str] = []
    idx = 0
    while idx < len(parts):
        part = parts[idx].strip()
        if part != "":
            result.append(part[0].upper() + part[1:])
        idx += 1
    return "".join(result)

def _resolve_runtime_symbol(runtime_call: str) -> str:
    name = runtime_call.strip()
    if name == "":
        return ""
    dot = name.find(".")
    if dot >= 0:
        module_name = name[:dot].strip()
        symbol_name = name[dot + 1 :].strip()
        if module_name == "" or symbol_name == "":
            return ""
        return "py" + _snake_to_pascal_case(module_name) + _snake_to_pascal_case(symbol_name)
    return "__pytra_" + name

def _render_attribute_access(expr: dict[str, Any]) -> str:
    value_any = expr.get("value")
    attr = _make_valid_identifier(expr.get("attr"), "field")
    semantic_tag_any = expr.get("semantic_tag")
    semantic_tag = semantic_tag_any if isinstance(semantic_tag_any, str) else ""
    runtime_call, _ = _get_resolved_runtime_call(expr)
    if semantic_tag.startswith("stdlib.") and runtime_call == "":
        raise RuntimeError("kotlin native emitter: unresolved stdlib runtime attribute: " + semantic_tag)
    resolved_runtime_any = expr.get("resolved_runtime_call")
    resolved_runtime = resolved_runtime_any if isinstance(resolved_runtime_any, str) else ""
    if resolved_runtime != "":
        resolved_source_any = expr.get("resolved_runtime_source")
        resolved_source = resolved_source_any if isinstance(resolved_source_any, str) else ""
        if resolved_source == "module_attr":
            runtime_symbol = _resolve_runtime_symbol(resolved_runtime)
            if runtime_symbol != "":
                if resolved_runtime.endswith(".pi") or resolved_runtime.endswith(".e"):
                    return runtime_symbol + "()"
                return runtime_symbol
            if semantic_tag.startswith("stdlib."):
                raise RuntimeError(
                    "kotlin native emitter: unresolved stdlib runtime attribute mapping: "
                    + semantic_tag
                    + " ("
                    + resolved_runtime
                    + ")"
                )
            return resolved_runtime
    value = _render_expression(value_any)
    return value + "." + attr

def _get_call_function_name(expr: dict[str, Any]) -> str:
    func_any = expr.get("func")
    if not isinstance(func_any, dict):
        return ""
    if func_any.get("kind") != "Name":
        return ""
    raw = func_any.get("id")
    if not isinstance(raw, str):
        return ""
    if raw == "super":
        return "super"
    return _make_valid_identifier(raw, "")

def _get_call_argument_nodes(expr: dict[str, Any]) -> list[Any]:
    args_any = expr.get("args")
    args = args_any if isinstance(args_any, list) else []
    result: list[Any] = []
    idx = 0
    while idx < len(args):
        result.append(args[idx])
        idx += 1
    keywords_any = expr.get("keywords")
    keywords = keywords_any if isinstance(keywords_any, list) else []
    if len(keywords) > 0:
        j = 0
        while j < len(keywords):
            kw = keywords[j]
            if isinstance(kw, dict):
                result.append(kw.get("value"))
            else:
                result.append(kw)
            j += 1
        return result
    kw_values_any = expr.get("kw_values")
    kw_values = kw_values_any if isinstance(kw_values_any, list) else []
    if len(kw_values) > 0:
        j = 0
        while j < len(kw_values):
            result.append(kw_values[j])
            j += 1
        return result
    kw_nodes_any = expr.get("kw_nodes")
    kw_nodes = kw_nodes_any if isinstance(kw_nodes_any, list) else []
    j = 0
    while j < len(kw_nodes):
        node = kw_nodes[j]
        if isinstance(node, dict):
            if node.get("kind") == "keyword":
                result.append(node.get("value"))
            else:
                result.append(node)
        else:
            result.append(node)
        j += 1
    return result

def _get_resolved_runtime_call(expr: dict[str, Any]) -> tuple[str, str]:
    runtime_call_any = expr.get("runtime_call")
    runtime_call = runtime_call_any if isinstance(runtime_call_any, str) else ""
    if runtime_call != "":
        return runtime_call, "runtime_call"
    resolved_any = expr.get("resolved_runtime_call")
    resolved = resolved_any if isinstance(resolved_any, str) else ""
    if resolved != "":
        return resolved, "resolved_runtime_call"
    return "", ""

def _matches_semantic_tag(runtime_call: str, semantic_tag: str) -> bool:
    if not semantic_tag.startswith("stdlib."):
        return True
    tail = semantic_tag.rsplit(".", 1)[-1].strip()
    call = runtime_call.strip()
    if tail == "" or call == "":
        return False
    if call == tail:
        return True
    return call.endswith("." + tail)

def _render_runtime_call_expression(
    runtime_call: str,
    runtime_source: str,
    semantic_tag: str,
    arguments: list[Any],
) -> str:
    if runtime_call.startswith("py_assert_"):
        rendered_args: list[str] = []
        idx = 0
        while idx < len(arguments):
            rendered_args.append(_render_expression(arguments[idx]))
            idx += 1
        return "__pytra_assert(" + ", ".join(rendered_args) + ")"
    if runtime_source == "runtime_call":
        if semantic_tag.startswith("stdlib.fn."):
            runtime_symbol = _resolve_runtime_symbol(runtime_call)
            if runtime_symbol == "":
                return ""
            rendered_args: list[str] = []
            idx = 0
            while idx < len(arguments):
                rendered_args.append(_render_expression(arguments[idx]))
                idx += 1
            return runtime_symbol + "(" + ", ".join(rendered_args) + ")"
        return ""
    if runtime_source == "resolved_runtime_call":
        if not _matches_semantic_tag(runtime_call, semantic_tag):
            return ""
    runtime_symbol = _resolve_runtime_symbol(runtime_call)
    if runtime_symbol == "":
        return ""
    if runtime_call.find(".") >= 0:
        rendered_args: list[str] = []
        idx = 0
        while idx < len(arguments):
            rendered_arg = _render_expression(arguments[idx])
            if runtime_symbol.startswith("pyMath"):
                rendered_arg = _to_float_expression(rendered_arg)
            rendered_args.append(rendered_arg)
            idx += 1
        if runtime_symbol == "pyMathPi" or runtime_symbol == "pyMathE":
            return "__pytra_float(" + runtime_symbol + "())"
        return runtime_symbol + "(" + ", ".join(rendered_args) + ")"
    rendered_args: list[str] = []
    idx = 0
    while idx < len(arguments):
        rendered_args.append(_render_expression(arguments[idx]))
        idx += 1
    return runtime_symbol + "(" + ", ".join(rendered_args) + ")"

def _render_call_expression(expr: dict[str, Any]) -> str:
    arguments = _get_call_argument_nodes(expr)
    semantic_tag_any = expr.get("semantic_tag")
    semantic_tag = semantic_tag_any if isinstance(semantic_tag_any, str) else ""
    if semantic_tag == "stdlib.symbol.Path":
        if len(arguments) == 0:
            return "Path(\"\")"
        return "Path(" + _render_expression(arguments[0]) + ")"
    runtime_call, runtime_source = _get_resolved_runtime_call(expr)
    if semantic_tag.startswith("stdlib.") and runtime_call == "":
        raise RuntimeError("kotlin native emitter: unresolved stdlib runtime call: " + semantic_tag)
    if runtime_call != "":
        rendered_runtime = _render_runtime_call_expression(
            runtime_call,
            runtime_source,
            semantic_tag,
            arguments,
        )
        if rendered_runtime != "":
            return rendered_runtime
        if semantic_tag.startswith("stdlib.") and runtime_source == "resolved_runtime_call":
            raise RuntimeError(
                "kotlin native emitter: unresolved stdlib runtime mapping: "
                + semantic_tag
                + " ("
                + runtime_call
                + ")"
            )
    callee_name = _get_call_function_name(expr)
    if callee_name.startswith("py_assert_"):
        rendered_args: list[str] = []
        idx = 0
        while idx < len(arguments):
            rendered_args.append(_render_expression(arguments[idx]))
            idx += 1
        return "__pytra_assert(" + ", ".join(rendered_args) + ")"
    if callee_name == "bytearray":
        if len(arguments) == 0:
            return "mutableListOf<Any?>()"
        return "__pytra_bytearray(" + _render_expression(arguments[0]) + ")"
    if callee_name == "bytes":
        if len(arguments) == 0:
            return "mutableListOf<Any?>()"
        return "__pytra_bytes(" + _render_expression(arguments[0]) + ")"
    if callee_name == "int":
        if len(arguments) == 0:
            return "0L"
        arg0 = arguments[0]
        rendered_arg0 = _render_expression(arg0)
        if _has_expected_type(arg0, {"int", "int64", "uint8"}):
            return rendered_arg0
        return _to_int_expression(rendered_arg0)
    if callee_name == "float":
        if len(arguments) == 0:
            return "0.0"
        arg0 = arguments[0]
        rendered_arg0 = _render_expression(arg0)
        if _has_expected_type(arg0, {"float", "float64"}):
            return rendered_arg0
        return _to_float_expression(rendered_arg0)
    if callee_name == "bool":
        if len(arguments) == 0:
            return "false"
        return _to_boolean_expression(_render_expression(arguments[0]))
    if callee_name == "str":
        if len(arguments) == 0:
            return '""'
        return _to_string_expression(_render_expression(arguments[0]))
    if callee_name == "len":
        if len(arguments) == 0:
            return "0L"
        return "__pytra_len(" + _render_expression(arguments[0]) + ")"
    if callee_name == "enumerate":
        if len(arguments) == 0:
            return "mutableListOf<Any?>()"
        return "__pytra_enumerate(" + _render_expression(arguments[0]) + ")"
    if callee_name == "min":
        if len(arguments) == 0:
            return "0L"
        current = _render_expression(arguments[0])
        idx = 1
        while idx < len(arguments):
            current = "__pytra_min(" + current + ", " + _render_expression(arguments[idx]) + ")"
            idx += 1
        return current
    if callee_name == "max":
        if len(arguments) == 0:
            return "0L"
        current = _render_expression(arguments[0])
        idx = 1
        while idx < len(arguments):
            current = "__pytra_max(" + current + ", " + _render_expression(arguments[idx]) + ")"
            idx += 1
        return current
    if callee_name == "print":
        rendered_args: list[str] = []
        idx = 0
        while idx < len(arguments):
            rendered_args.append(_render_expression(arguments[idx]))
            idx += 1
        return "__pytra_print(" + ", ".join(rendered_args) + ")"
    if callee_name in {"RuntimeError", "ValueError", "TypeError", "Exception", "AssertionError"}:
        if len(arguments) == 0:
            return '""'
        return _render_expression(arguments[0])
    func_any = expr.get("func")
    if isinstance(func_any, dict) and func_any.get("kind") == "Attribute":
        attr_name = _make_valid_identifier(func_any.get("attr"), "")
        owner_any = func_any.get("value")
        if isinstance(owner_any, dict) and owner_any.get("kind") == "Call":
            if _get_call_function_name(owner_any) in {"super", "super_"}:
                rendered_args: list[str] = []
                idx = 0
                while idx < len(arguments):
                    rendered_args.append(_render_expression(arguments[idx]))
                    idx += 1
                if attr_name == "__init__":
                    return "__pytra_noop()"
                return "super." + attr_name + "(" + ", ".join(rendered_args) + ")"
        if attr_name == "isdigit" and len(arguments) == 0:
            return "__pytra_isdigit(" + _render_expression(owner_any) + ")"
        if attr_name == "isalpha" and len(arguments) == 0:
            return "__pytra_isalpha(" + _render_expression(owner_any) + ")"
        owner_expr = _render_expression(owner_any)
        if attr_name == "get" and len(arguments) == 2:
            key_expr = _render_expression(arguments[0])
            default_expr = _render_expression(arguments[1])
            return "(" + owner_expr + ".get(" + key_expr + ") ?: " + default_expr + ")"
        rendered_args: list[str] = []
        idx = 0
