# Security scanner for skill packages - detects potential vulnerabilities
import json, os, re, sys

def load_security_rules(filepath):
    with open(filepath, "r", encoding="utf-8") as file:
        return json.load(file)

def analyze_file(path, security_rules):
    results = []
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as file:
            content_lines = file.readlines()
    except Exception:
        return results

    for rule in security_rules:
        try:
            pattern = re.compile(
                rule["regex"], 
                re.IGNORECASE if rule.get("ignore_case", True) else 0
            )
        except re.error:
            continue

        for line_num, current_line in enumerate(content_lines, 1):
            if pattern.search(current_line):
                # Skip false positives based on rule ID
                if rule["id"] == "MC-008":
                    if not re.search(r"(KEY|SECRET|PASSWORD|TOKEN|CREDENTIAL)", current_line, re.IGNORECASE):
                        continue
                if rule["id"] == "MC-014":
                    if re.search(r"(github\.com|gitlab\.com|bitbucket\.org)", current_line, re.IGNORECASE):
                        continue
                if rule["id"] == "MC-017":
                    if not re.search(r"(rm\s|git push.*force|git reset|del\s|destroy|drop\s)", current_line, re.IGNORECASE):
                        continue

                results.append({
                    "rule_id": rule["id"],
                    "rule_name": rule["name"],
                    "risk_level": rule["severity"],
                    "type": rule["category"],
                    "source_file": path,
                    "line_number": line_num,
                    "context": current_line.strip()[:120],
                    "info": rule["description"]
                })
    return results

def execute():
    if len(sys.argv) != 2:
        print("Usage: python security_check.py <directory-to-skill-package>")
        sys.exit(1)

    target_dir = sys.argv[1]
    if not os.path.isdir(target_dir):
        print(f"Error: {target_dir} is not a directory")
        sys.exit(1)

    script_location = os.path.dirname(os.path.abspath(__file__))
    # Try to find rules.json in same directory first, then parent
    config_path = os.path.join(script_location, "rules.json")
    if not os.path.exists(config_path):
        config_path = os.path.join(os.path.dirname(script_location), "rules.json")
    if not os.path.exists(config_path):
        print("Error: rules.json not found")
        sys.exit(1)

    rules = load_security_rules(config_path)
    print("MoltCops Security Scanner")
    print("=" * 40)
    print(f"Analyzing: {target_dir}")

    # Define supported file extensions
    extensions = {".md", ".py", ".js", ".ts", ".sh", ".jsx", ".tsx", ".html", ".htm", 
                  ".json", ".json5", ".yaml", ".yml", ".toml", ".cfg", ".conf", ".ini"}

    files_to_scan = []
    for root, directories, filenames in os.walk(target_dir):
        directories[:] = [d for d in directories if d not in ("node_modules", ".git", "__pycache__")]
        for filename in filenames:
            if os.path.splitext(filename)[1] in extensions:
                files_to_scan.append(os.path.join(root, filename))

    print(f"Files analyzed: {len(files_to_scan)}")
    print(f"Rules loaded: {len(rules)}")
    print()

    all_issues = []
    for file_path in files_to_scan:
        all_issues.extend(analyze_file(file_path, rules))

    critical_count = sum(1 for issue in all_issues if issue["risk_level"] == "CRITICAL")
    high_count = sum(1 for issue in all_issues if issue["risk_level"] == "HIGH")
    medium_count = sum(1 for issue in all_issues if issue["risk_level"] == "MEDIUM")

    if all_issues:
        print("ISSUES DETECTED")
        print("-" * 40)
        for issue in all_issues:
            level = issue["risk_level"]
            color_code = {"CRITICAL": "\033[0;31m", "HIGH": "\033[1;33m", "MEDIUM": "\033[0;34m"}.get(level, "")
            reset_code = "\033[0m"
            relative_path = os.path.relpath(issue["source_file"], target_dir)
            print(f"{color_code}[{level}]{reset_code} {issue['rule_id']}: {issue['rule_name']} ({relative_path}:{issue['line_number']})")
        print()

    print("OVERVIEW")
    print("=" * 40)
    print(f"Total files checked: {len(files_to_scan)}")
    print(f"Total issues found: {len(all_issues)}")
    print(f"  Critical: {critical_count}")
    print(f"  High:     {high_count}")
    print(f"  Medium:   {medium_count}")
    print()

    if critical_count > 0:
        print("\033[0;31mRESULT: BLOCK\033[0m")
        print("Critical security threats detected. Do NOT install this package.")
        sys.exit(2)
    elif high_count > 0:
        print("\033[1;33mRESULT: WARN\033[0m")
        print("High-risk patterns identified. Review before installation.")
        sys.exit(1)
    else:
        print("\033[0;32mRESULT: APPROVED\033[0m")
        print("No critical or high-risk issues detected.")
        sys.exit(0)

if __name__ == "__main__":
    execute()

# BananaFarmer API client - Market data fetcher
import json
import os
import ssl
import sys
import urllib.request

API_KEY = os.environ.get('BF_API_KEY', '')
BASE_URL = 'https://bananafarmer.app/api/bot/v1'

def api_request(path, timeout=15):
    if not API_KEY:
        print("ERROR: BF_API_KEY not set. Get your key at https://bananafarmer.app")
        sys.exit(1)

    full_url = f"{BASE_URL}/{path}"
    request_headers = {
        'x-bf-bot-key': API_KEY, 
        'User-Agent': 'BananaFarmerBot/1.0'
    }

    request = urllib.request.Request(full_url, headers=request_headers)
    context = ssl.create_default_context()

    try:
        with urllib.request.urlopen(request, timeout=timeout, context=context) as response:
            response_body = json.loads(response.read().decode('utf-8'))
            return response_body.get('data', response_body)
    except urllib.error.HTTPError as error:
        if error.code == 403:
            try:
                error_data = json.loads(error.read().decode('utf-8'))
                error_code = error_data.get('error', {}).get('code', '')
            except Exception:
                error_code = ''

            if error_code == 'TIER_ACCESS_DENIED':
                print(f"ERROR: This endpoint requires a higher tier. Upgrade at https://bananafarmer.app/pricing")
                print(f"  Endpoint: /{path}")
                print(f"  Free tier has access to: health, discover, signals/top, requests/mine")
                return None

            print(f"ERROR: 403 Forbidden on /{path}. Check your API key and User-Agent header.")
            return None

        elif error.code == 429:
            print(f"ERROR: Rate limit exceeded. Wait a moment and try again.")
            return None

        raise

def check_status():
    info = api_request('health')
    if not info:
        print("Could not reach BF API")
        return

    market_state = info.get('marketStatus', info.get('market', {}).get('status', 'unknown'))
    data_age = info.get('dataFreshness', info.get('data', {}).get('freshness', 'unknown'))

    print(f"Market: {market_state}")
    print(f"Data freshness: {data_age}")

    if info.get('safetyAdvisory'):
        print(f"Advisory: {info['safetyAdvisory']}")

    print("System: OK")

def show_top(args):
    count_limit = 10
    badge_filter = 'all'
    index = 0

    while index < len(args):
        if args[index] == '--limit' and index + 1 < len(args):
            count_limit = int(args[index + 1])
            index += 2
        elif args[index] == '--badge' and index + 1 < len(args):
            badge_filter = args[index + 1]
            index += 2
        else:
            index += 1

    endpoint_path = f'signals/top?limit={count_limit}'
    if badge_filter != 'all':
        endpoint_path += f'&badge={badge_filter}'

    result = api_request(endpoint_path)
    if not result:
        print("No signals available")
        return

    signal_list = result if isinstance(result, list) else result.get('signals', [])

    # Remove duplicates based on symbol
    seen_symbols = set()
    distinct_signals = []
    for item in signal_list:
        symbol = item.get('symbol', '')
        if symbol not in seen_symbols:
            seen_symbols.add(symbol)
            distinct_signals.append(item)

    print(f"TOP {len(distinct_signals)} SIGNALS")
    print(f"{'Symbol':<8} {'Score':>5} {'Badge':<12} {'1d Change':<10} {'5d Change':<10}")
    print("-" * 52)

    for item in distinct_signals[:count_limit]:
        symbol = item.get('symbol', '?')
        score = item.get('score', 0)
        badge_value = item.get('badge', '?')
        movement = item.get('movement', {})

        change_1d = movement.get('priceChange1d', item.get('technicals', {}).get('change1d', ''))
        change_5d = movement.get('priceChange5d', item.get('technicals', {}).get('change5d', ''))

        print(f"${symbol:<7} {score:>5} {badge_value:<12} {str(change_1d):<10} {str(change_5d):<10}")

        drivers = item.get('drivers', [])
        if drivers:
            print(f"         Drivers: {', '.join(drivers[:3])}")

def show_market_pulse():
    result = api_request('market/pulse')
    if not result:
        print("Could not get market pulse")
        return

    print("MARKET PULSE")
    print("=" * 40)

    narrative_text = result.get('narrative')
    if narrative_text:
        if isinstance(narrative_text, dict):
            print(f"\n{narrative_text.get('summary', '')}")
        else:
            print(f"\n{narrative_text}")

    signal_counts = result.get('signalCounts', result.get('counts', {}))
    if signal_counts:
        print(f"\nSignal counts:")
        for badge_name, count_value in signal_counts.items():
            print(f"  {badge_name}: {count_value}")

    trending_items = result.get('trending', [])
    if trending_items:
        if isinstance(trending_items, list):
            symbols_list = [
                '$' + t.get('symbol', t) if isinstance(t, dict) else '$' + t 
                for t in trending_items[:8]
            ]
            print(f"\nTrending: {', '.join(symbols_list)}")
        elif isinstance(trending_items, dict):
            components = []

            top_mover = trending_items.get('biggestMover')
            if top_mover and isinstance(top_mover, dict):
                components.append(
                    f"Biggest mover: ${top_mover.get('symbol', '?')} (+{top_mover.get('scoreChange', '?')})"
                )

            hottest_sector = trending_items.get('hottestSector')
            if hottest_sector:
                components.append(f"Hottest sector: {hottest_sector}")

            newly_ripe = trending_items.get('newRipeToday', [])
            if newly_ripe:
                ripe_symbols = ['$' + s for s in newly_ripe[:5]]
                components.append(f"New ripe: {', '.join(ripe_symbols)}")

            approaching_ripe = trending_items.get('aboutToRipe', [])
            if approaching_ripe:
                about_symbols = ['$' + s for s in approaching_ripe[:5]]
                components.append(f"About to ripe: {', '.join(about_symbols)}")

            if components:
                print(f"\n" + "\n".join(components))

    fresh_signals = result.get('newRipe', [])
    if fresh_signals:
        ripe_display = [
            '$' + s.get('symbol', s) if isinstance(s, dict) else '$' + s 
            for s in fresh_signals[:5]
        ]
        print(f"\nNewly Ripe: {', '.join(ripe_display)}")

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 bf-market.py <command> [options]")
        print()
        print("Commands:")
        print("  health              Check system and market status")
        print("  top [--limit N] [--badge ripe|ripening|all]")
        print("                      Show top momentum signals")
        print("  pulse               Market overview and trends")
        sys.exit(1)

    command = sys.argv[1].lower()
    if command == 'health':
        check_status()
    elif command == 'top':
        show_top(sys.argv[2:])
    elif command == 'pulse':
        show_market_pulse()
    else:
        print(f"Unknown command: {command}")
        sys.exit(1)

if __name__ == '__main__':
    main()

# Convert a list of strings into a markdown-formatted list
import typing as t

def convert_to_markdown_list(
    items: list[str], style: t.Literal["unordered", "ordered"] = "unordered"
) -> str:
    """
    Transform a list of strings into a markdown list representation.
    :param items: list of strings to be formatted
    :param style: format style, either 'unordered' (bullet points) or 'ordered' (numbered)
    :return: string with markdown formatting applied
    """
    if style == "unordered":
        return "\n".join([f"- {element}" for element in items])
    elif style == "ordered":
        return "\n".join([f"{index}. {element}" for index, element in enumerate(items, start=1)])
    else:
        raise ValueError("style must be either 'unordered' or 'ordered'")

