def _load_example_class(module_candidates: list[str]):
    """Attempt to import Example class from given modules.

    Args:
        module_candidates: List of module names to try in order.

    Returns:
        The Example class from the first successfully imported module.

    Raises:
        SkipNotImplemented: If no module can be imported successfully.
    """
    for mod_name in module_candidates:
        try:
            module = importlib.import_module(mod_name)
        except ModuleNotFoundError:
            continue
        return module.Example
    raise SkipNotImplemented

