class BaseGenEvalDataset(MMBaseDataset):
    def __init__(self,
            config: dict,
            **kwargs
    ):
        super().__init__(**config, **kwargs)

    def __getitem__(self, idx):
        return self.data_samples[idx]


class DimensionCounter:
    def __init__(self):
        self.counts = {}

    def increment(self, dims):
        for d in set(dims):
            self.counts[d] = self.counts.get(d, 0) + 1

    def min_occurrence(self, dims):
        return min(self.counts.get(d, 0) for d in set(dims))


dimension_mapping = {
    "subject_consistency": "subject_consistency",
    "background_consistency": "scene",
    "aesthetic_quality": "overall_consistency",
    "imaging_quality": "overall_consistency",
    "object_class": "object_class",
    "multiple_objects": "multiple_objects",
    "color": "color",
    "spatial_relationship": "spatial_relationship",
    "scene": "scene",
    "temporal_style": "temporal_style",
    "overall_consistency": "overall_consistency",
    "human_action": "human_action",
    "temporal_flickering": "temporal_flickering",
    "motion_smoothness": "subject_consistency",
    "dynamic_degree": "subject_consistency",
    "appearance_style": "appearance_style"
}


def normalize_dimensions(dim_list):
    if dim_list is None or len(dim_list) == 0:
        return []
    result_dims = set(dim_list)
    for d in set(dim_list):
        if d in dimension_mapping:
            result_dims.add(dimension_mapping[d])
    return list(result_dims)


class VbenchGenEvalDataset(BaseGenEvalDataset):
    def __init__(self,
            basic_param: dict,
            extra_config: dict,
            dimensions: list = None,
    ):
        super().__init__(basic_param)
        self.dimensions = normalize_dimensions(dimensions)
        self.enable_augmentation = extra_config.get("augment", False)
        self.prompts_per_dimension = extra_config.get("prompts_per_dim", 0)
        self.samples_per_prompt = extra_config.get("samples_per_prompt", 5)
        self.base_prompt_file = extra_config.get("prompt_file", "all_dimension.txt")
        self.augmented_prompt_path = extra_config.get("augmented_prompt_file",
                                                     "augmented_prompts/gpt_enhanced_prompts/all_dimension_longer.txt")

        self.text_captions = []
        self.enhanced_captions = []

        if self.dimensions and len(self.dimensions) > 0:
            prompt_paths = [os.path.join("prompts_per_dimension", f"{dim}.txt") for dim in self.dimensions]
            for pth in prompt_paths:
                full_path = os.path.join(self.data_folder, pth)
                if not os.path.exists(full_path):
                    continue
                raw_data = self.get_data(full_path)
                if self.prompts_per_dimension > 0:
                    self.text_captions += raw_data[:self.prompts_per_dimension]
                else:
                    self.text_captions += raw_data

            if self.enable_augmentation:
                aug_prompt_paths = [
                    os.path.join("augmented_prompts/gpt_enhanced_prompts/prompts_per_dimension_longer",
                                 f"{dim}_longer.txt") for dim in self.dimensions
                ]
                for aug_pth in aug_prompt_paths:
                    full_aug_path = os.path.join(self.data_folder, aug_pth)
                    if not os.path.exists(full_aug_path):
                        continue
                    raw_aug_data = self.get_data(full_aug_path)
                    if self.prompts_per_dimension > 0:
                        self.enhanced_captions += raw_aug_data[:self.prompts_per_dimension]
                    else:
                        self.enhanced_captions += raw_aug_data
        else:
            base_full_path = os.path.join(self.data_folder, self.base_prompt_file)
            self.text_captions += self.get_data(base_full_path)

            if self.enable_augmentation:
                aug_full_path = os.path.join(self.data_folder, self.augmented_prompt_path)
                self.enhanced_captions += self.get_data(aug_full_path)

    def create_item_template(self):
        return {
            "caption": "",
            "prefix": "",
        }

    def __getitem__(self, index):
        text_idx = index // self.samples_per_prompt
        sample_id = index % self.samples_per_prompt

        item = self.create_item_template()
        item["prefix"] = self.text_captions[text_idx] + f"-{sample_id}"
        item["caption"] = self.enhanced_captions[text_idx] if self.enable_augmentation else self.text_captions[text_idx]
        return item

    def __len__(self):
        return len(self.text_captions) * self.samples_per_prompt


class VbenchI2VGenEvalDataset(BaseGenEvalDataset):
    def __init__(self,
            basic_param: dict,
            extra_config: dict,
            dimensions: list,
    ):
        super().__init__(basic_param)
        self.aspect_ratio = extra_config.get("ratio", "16-9")
        self.prompts_per_dimension = extra_config.get("prompts_per_dim", 0)
        self.samples_per_prompt = extra_config.get("samples_per_prompt", 5)
        self.filter_by_dimension(dimensions)

    def create_item_template(self):
        return {
            "caption": "",
            "prefix": "",
            "image": "",
        }

    def filter_by_dimension(self, dims):
        if dims is None or len(dims) == 0:
            return

        selected_dims = set(dims)
        filtered_samples = []
        counter = DimensionCounter()

        for sample in self.data_samples:
            sample_dims = sample.get("dimension", [])
            if any(d in selected_dims for d in sample_dims):
                if 0 < self.prompts_per_dimension <= counter.min_occurrence(sample_dims):
                    continue
                filtered_samples.append(sample)
                counter.increment(sample_dims)

        self.data_samples = filtered_samples

    def __getitem__(self, index):
        caption_idx = index // self.samples_per_prompt
        sample_id = index % self.samples_per_prompt

        item = self.create_item_template()
        data = self.data_samples[caption_idx]

        item["caption"] = data.get("prompt_en", "")
        item["prefix"] = data.get("prompt_en", "") + f"-{sample_id}"
        item["image"] = os.path.join(self.data_folder, "crop", self.aspect_ratio, data.get("image_name", ""))

        return item

    def __len__(self):
        return len(self.data_samples) * self.samples_per_prompt

# Custom pagination class for REST framework
from rest_framework.pagination import PageNumberPagination
from rest_framework.response import Response

class CustomPageNumberPagination(PageNumberPagination):
    page_size_query_param = "page_size"
    max_page_size = 10000

    def paginate_queryset(self, queryset, request, view=None):
        # Handle custom page size logic
        requested_page_size = request.GET.get("page_size")
        if requested_page_size is None or requested_page_size in ["0", "-1"]:
            return None
        return super().paginate_queryset(queryset, request, view)

    def get_paginated_response(self, data):
        # Return custom response structure
        return Response(
            dict(
                [
                    ("count", self.page.paginator.count),
                    ("items", data),
                ]
            )
        )

