import unittest
from graph_net.fault_locator.fault_detector import has_fault_at, ES

class TestHasFaultAtFunction(unittest.TestCase):
    def test_fault_detected_scenario(self):
        """Test case: ES[t-1] is less than ES[max], should return True."""
        # tolerance = 5, so we examine ES[4]
        es_values: ES = {0: 0.1, 4: 0.5, 10: 0.9}
        threshold = 5
        # 0.5 < 0.9 evaluates to True
        self.assertTrue(has_fault_at(es_values, threshold))

    def test_no_fault_detected_scenario(self):
        """Test case: ES[t-1] is equal to or greater than ES[max], should return False."""
        # tolerance = 11, we examine ES[10]. The maximum key is 10.
        es_values: ES = {0: 0.1, 5: 0.5, 10: 0.9}
        threshold = 11
        # 0.9 < 0.9 evaluates to False
        self.assertFalse(has_fault_at(es_values, threshold))

    def test_invalid_tolerance_raises_error(self):
        """Test case: tolerance-1 is not present in ES, should raise AssertionError."""
        es_values: ES = {0: 0.1, 1: 0.2}
        threshold = 5  # index 4 is missing from ES
        with self.assertRaises(AssertionError):
            has_fault_at(es_values, threshold)

    def test_single_element_edge_case(self):
        """Test case: ES contains only one element, max is itself."""
        es_values: ES = {0: 0.5}
        threshold = 1
        # 0.5 < 0.5 evaluates to False
        self.assertFalse(has_fault_at(es_values, threshold))

