# Process the LLM output to retain only the largest code block for the specified language
from .get_comment import get_comment
from .comment_line import comment_line
from .find_section import find_section

def postprocess_0(llm_output: str, language: str) -> str:
    # Step 1: Retrieve the comment symbol based on the programming language
    comment_symbol = get_comment(language)

    # Step 2: Split the LLM output into individual lines and identify code sections
    line_list = llm_output.splitlines()
    section_list = find_section(line_list)

    # Step 3: Determine the largest code section matching the specified language
    best_section = None
    max_length = 0
    for lang, begin, finish in section_list:
        if lang.lower() == language.lower():
            current_length = finish - begin
            if current_length > max_length:
                max_length = current_length
                best_section = (begin, finish)

    # Step 4 & 5: Comment out lines that are not part of the largest matching section
    updated_lines = []
    inside_code_block = False
    for idx, current_line in enumerate(line_list):
        if best_section and idx == best_section[0] + 1:
            inside_code_block = True
        elif best_section and idx == best_section[1]:
            inside_code_block = False

        if not inside_code_block:
            updated_lines.append(comment_line(current_line, comment_symbol))
        else:
            updated_lines.append(current_line)

    # Return the final processed string
    return '\n'.join(updated_lines)

