def create_vllm_config(config_types: List[str],
                       updates: List[Dict[str, Any]]):
    config_obj = VllmConfigWrapper()
    for (cfg_type, update) in zip(config_types, updates):
        if cfg_type == "model":
            for param in update:
                setattr(config_obj.model_cfg, param, update[param])
        else:
            for param in update:
                setattr(config_obj, param, update[param])
    return config_obj

