# Embedding server implementation using Unix socket and threading
import json
import os
import sys
import time
import signal
import socket
import threading
import logging

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
logger = logging.getLogger("embed_server")

SOCKET_FILE = "/tmp/openclaw-embed.sock"
PID_PATH = "/tmp/openclaw-embed.pid"
MODEL_ID = "sentence-transformers/all-MiniLM-L6-v2"

# Global variables for model and timing
embedding_model = None
init_timestamp = None

def initialize_model():
    global embedding_model, init_timestamp
    logger.info(f"Initializing model {MODEL_ID}...")
    start = time.time()
    from sentence_transformers import SentenceTransformer
    embedding_model = SentenceTransformer(MODEL_ID)
    duration = (time.time() - start) * 1000
    init_timestamp = time.time()
    logger.info(f"Model initialized in {duration:.0f}ms")

def generate_embedding(text: str) -> list:
    vector = embedding_model.encode(text, normalize_embeddings=True)
    return vector.tolist()

def generate_batch_embeddings(texts: list) -> list:
    vectors = embedding_model.encode(texts, normalize_embeddings=True, batch_size=32)
    return vectors.tolist()

def process_client(connection):
    try:
        buffer = b""
        while True:
            piece = connection.recv(65536)
            if not piece:
                break
            buffer += piece
            if b"\n" in buffer:
                break
        if not buffer:
            return
        message = json.loads(buffer.decode().strip())
        operation = message.get("action", "")
        if operation == "ping":
            elapsed = round(time.time() - init_timestamp) if init_timestamp else 0
            reply = {"status": "ok", "model": MODEL_ID, "uptime": elapsed}
        elif operation == "embed":
            start = time.time()
            vector = generate_embedding(message["text"])
            ms = round((time.time() - start) * 1000)
            reply = {"embedding": vector, "ms": ms}
        elif operation == "embed_batch":
            start = time.time()
            vectors = generate_batch_embeddings(message["texts"])
            ms = round((time.time() - start) * 1000)
            reply = {"embeddings": vectors, "ms": ms}
        else:
            reply = {"error": f"Unknown action: {operation}"}
        connection.sendall((json.dumps(reply) + "\n").encode())
    except Exception as ex:
        try:
            connection.sendall((json.dumps({"error": str(ex)}) + "\n").encode())
        except:
            pass
    finally:
        connection.close()

def start_server():
    # Remove old socket file if exists
    if os.path.exists(SOCKET_FILE):
        os.unlink(SOCKET_FILE)
    initialize_model()
    server_socket = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    server_socket.bind(SOCKET_FILE)
    server_socket.listen(5)
    os.chmod(SOCKET_FILE, 0o666)
    # Save PID to file
    with open(PID_PATH, "w") as pid_file:
        pid_file.write(str(os.getpid()))

    def cleanup_handler(sig, frame):
        logger.info("Shutting down...")
        server_socket.close()
        if os.path.exists(SOCKET_FILE):
            os.unlink(SOCKET_FILE)
        if os.path.exists(PID_PATH):
            os.unlink(PID_PATH)
        sys.exit(0)

    signal.signal(signal.SIGTERM, cleanup_handler)
    signal.signal(signal.SIGINT, cleanup_handler)

    logger.info(f"Embedding server listening on {SOCKET_FILE}")
    while True:
        try:
            client_conn, _ = server_socket.accept()
            threading.Thread(target=process_client, args=(client_conn,), daemon=True).start()
        except OSError:
            break

def verify_status():
    if not os.path.exists(SOCKET_FILE):
        print("Embedding server: NOT RUNNING")
        return False
    try:
        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        sock.connect(SOCKET_FILE)
        sock.sendall(b'{"action":"ping"}\n')
        response_data = sock.recv(4096)
        sock.close()
        response = json.loads(response_data.decode().strip())
        print(f"Embedding server: RUNNING (uptime={response.get('uptime', '?')}s, model={response.get('model', '?')})")
        return True
    except:
        print("Embedding server: STALE SOCKET (not responding)")
        return False

def terminate_server():
    if os.path.exists(PID_PATH):
        with open(PID_PATH) as pid_file:
            process_id = int(pid_file.read().strip())
        try:
            os.kill(process_id, signal.SIGTERM)
            print(f"Sent SIGTERM to pid {process_id}")
        except ProcessLookupError:
            print(f"Process {process_id} not found")
        os.unlink(PID_PATH)
    if os.path.exists(SOCKET_FILE):
        os.unlink(SOCKET_FILE)

if __name__ == "__main__":
    if "--status" in sys.argv:
        verify_status()
    elif "--stop" in sys.argv:
        terminate_server()
    else:
        start_server()

