        if scales:
            if "MAXABS" in filename:
                return os.path.join(measurements_dir_path, file_entry)
        else:
            if "MAXABS" not in filename:
                return os.path.join(measurements_dir_path, file_entry)

def is_fused_moe_operation(node_name):
    return ("moe" in node_name.lower() and ".w13_list" not in node_name and ".w2_list" not in node_name)

def is_moe_expert_layer(node_name):
    return ("moe" in node_name.lower() and (".w13_list" in node_name or ".w2_list" in node_name))

def extract_expert_index(node_name):
    segments = node_name.split(".")
    assert segments[-1].isdigit()
    expert_idx = int(segments[-1])
    return expert_idx

def extract_expert_prefix(node_name):
    segments = node_name.split(".")
    assert segments[-1].isdigit()
    prefix = ".".join(segments[:-1])
    return prefix

def determine_local_expert_count(data):
    expert_idx = -1
    for mod_name in data:
        if is_moe_expert_layer(mod_name):
            idx = extract_expert_index(mod_name)
            expert_idx = max(expert_idx, idx)
    return expert_idx + 1

def consolidate_measurements(measurement_group,
                             measurements_dir_path,
                             output_directory,
                             groups_size,
                             groups_num,
                             group_index,
                             scales=False,
                             use_ep=False):
    measurement_files = []
    combined_name = ""

    # Collect all JSON paths for the current measurement group
    for measurement in measurement_group:
        file_path = locate_measurement_file(measurement, measurements_dir_path, scales, groups_size)
        if file_path is not None:
            measurement_files.append(file_path)
        combined_name += measurement

    if len(measurement_files) == 0:
        print("Error: invalid measurement paths. No *.json files or no "
              "*mod_list.json files.")
        return

    # Load all JSON contents for the current measurement group
    measurement_data = []
    for file_path in measurement_files:
        with open(file_path) as f:
            js = json.load(f)
            measurement_data.append(js["Nodes"])

    # Construct unified JSON filename
    base_path = locate_measurement_file(measurement_group[0], measurements_dir_path, scales, groups_size)
    old_suffix = "_" + measurement_group[0] + "_" + str(groups_size)
    new_suffix = "_" + str(group_index) + "_" + str(groups_num)
    unified_json_name = base_path.split("/")[-1].replace(old_suffix, new_suffix)
    unified_json_path = os.path.join(output_directory, unified_json_name)

    # Create initial unified JSON by copying first measurement file
    with open(measurement_files[0]) as origin, open(unified_json_path, "w") as copy:
        copy.write(origin.read())

    with open(unified_json_path) as json_file:
        unified_json = json.load(json_file)
        unified_json["LocalRank"] = group_index if groups_num != 1 else -1

    moe_expert_data = {}
    # expert_count is original local_expert_num, used only when use_ep is True
    expert_count = determine_local_expert_count(unified_json["Nodes"]) if use_ep else -1

    # Process each node in the unified JSON
    for node_name, node_values in unified_json["Nodes"].items():
        max_inputs = node_values["inputs"]
        max_outputs = None
        if node_values.get("outputs") is not None:
            max_outputs = node_values["outputs"]
        max_weight = None
        if node_values.get("params") is not None and node_values["params"].get("weight") is not None:
            max_weight = node_values["params"]["weight"]

        # Consolidate measurements based on scale type
        if scales:
            for idx, measurement_json in enumerate(measurement_data):
                # Handle MoE experts under expert parallelism
                if use_ep and is_moe_expert_layer(node_name):
                    if node_name not in moe_expert_data:
                        moe_expert_data[node_name] = node_values
                    else:
                        prefix, local_expert_id = extract_expert_prefix(node_name), extract_expert_index(node_name)
                        new_node_name = ".".join((prefix, str(expert_count * idx + local_expert_id)))
                        assert new_node_name not in moe_expert_data
                        moe_expert_data[new_node_name] = measurement_json[node_name]
                    continue

                # Handle fused MoE operations beyond first measurement
                if use_ep and is_fused_moe_operation(node_name) and idx > 0:
                    max_inputs[0] = max(measurement_json[node_name]["inputs"][0], max_inputs[0])
                    max_inputs.extend(measurement_json[node_name]["inputs"][1:])
                else:
                    for i in range(0, len(max_inputs)):
                        max_inputs[i] = max(measurement_json[node_name]["inputs"][i], max_inputs[i])

                if max_outputs is not None:
                    max_outputs = max(measurement_json[node_name]["outputs"], max_outputs)

                if max_weight is not None:
                    max_weight = max(measurement_json[node_name]["params"]["weight"], max_weight)
        else:
            for idx, measurement_json in enumerate(measurement_data):
                # Handle MoE experts under expert parallelism
                if use_ep and is_moe_expert_layer(node_name):
                    if node_name not in moe_expert_data:
                        moe_expert_data[node_name] = node_values
                    else:
                        prefix, local_expert_id = extract_expert_prefix(node_name), extract_expert_index(node_name)
                        new_node_name = ".".join((prefix, str(expert_count * idx + local_expert_id)))
                        assert new_node_name not in moe_expert_data
                        moe_expert_data[new_node_name] = measurement_json[node_name]
                    continue

                # Process input tensors
                for i in range(0, len(max_inputs)):
                    for j in range(0, len(max_inputs[i])):
                        max_inputs[i][j][0] = max(measurement_json[node_name]["inputs"][i][j][0], max_inputs[i][j][0])

                # Process output tensors
                if max_outputs is not None:
                    if use_ep and is_fused_moe_operation(node_name) and idx > 0:
                        max_outputs[0][0] = max(measurement_json[node_name]["outputs"][0][0], max_outputs[0][0])
                        max_outputs.extend(measurement_json[node_name]["outputs"][1:])
                    else:
                        for i in range(0, len(max_outputs)):
                            max_outputs[i][0] = max(measurement_json[node_name]["outputs"][i][0], max_outputs[i][0])

                # Process weight tensors
                if max_weight is not None:
                    for i in range(0, len(max_weight)):
                        max_weight[i][0] = max(measurement_json[node_name]["params"]["weight"][i][0], max_weight[i][0])

        # Update unified JSON with consolidated values
        if scales:
            for i in range(0, len(max_inputs)):
                unified_json["Nodes"][node_name]["inputs"][i] = max_inputs[i]
            if max_outputs is not None:
                unified_json["Nodes"][node_name]["outputs"] = max_outputs
            if max_weight is not None:
                unified_json["Nodes"][node_name]["params"]["weight"] = max_weight
        else:
            for i in range(0, len(max_inputs)):
                for j in range(0, len(max_inputs[i])):
                    unified_json["Nodes"][node_name]["inputs"][i][j][0] = max_inputs[i][j][0]
            if max_outputs is not None:
                for i in range(0, len(max_outputs)):
                    unified_json["Nodes"][node_name]["outputs"][i][0] = max_outputs[i][0]
            if max_weight is not None:
                for i in range(0, len(max_weight)):
                    unified_json["Nodes"][node_name]["params"]["weight"][i][0] = max_weight[i][0]

    if use_ep:
        unified_json["Nodes"].update(moe_expert_data)

    global_rank = None
    local_rank = group_index if groups_num != 1 else -1
    mode = ""
    layers = {}

    with open(unified_json_path, "w") as json_file:
        json.dump(unified_json, json_file, indent=4)

    mode = unified_json["Mode"]
    nodes = unified_json["Nodes"]

    # Create unified NPZ file from the unified JSON
    unified_npz_path = os.path.join(output_directory, unified_json_name.replace(".json", ".npz"))
    for layer, dlayer in nodes.items():
        layers[layer] = {}
        layers[layer]["inputs"] = [np.array(x) for x in dlayer["inputs"]]
        if dlayer.get("outputs") is not None:
            layers[layer]["outputs"] = [np.array(x) for x in dlayer["outputs"]]
        if dlayer.get("params") is not None and dlayer["params"].get("weight") is not None:
            layers[layer]["params"] = {}
            layers[layer]["params"]["weight"] = np.array(dlayer["params"]["weight"])

    df = {"GlobalRank": global_rank, "LocalRank": local_rank, "Mode": mode, "Nodes": layers}
    with open(unified_npz_path, "w"):
        np.savez(unified_npz_path, df)

def parse_arguments(args):
    parser = argparse.ArgumentParser(description="Run the measurements parser",
                                     formatter_class=argparse.ArgumentDefaultsHelpFormatter)
    parser.add_argument("-m",
                        "--measurements",
                        type=str,
                        help="path to the directory of the measurements that will be "
                        "unified")
    parser.add_argument("-r", "--rank", type=int, help="rank of unified measurements")
    parser.add_argument(
        "-o",
        "--out",
        type=str,
        default=os.getcwd(),
        help="path to the directory where the unified measurements will be "
        "written",
    )
    parser.add_argument(
        "-u",
        "--use_expert_paral",
        action="store_true",
        help="unify original measurement results based on expert parallelism "
        "rules",
    )
    parser.add_argument(
        "-s",
        "--skip_unify_scales",
        action="store_true",
        help="skip the scale unification step.",
    )
    return parser.parse_args(args)

def prepare_grouping_list(measurements_path, rank):
    measure_files = glob.glob(os.path.join(measurements_path, "*_mod_list.json"))
    if len(measure_files) > 0:
        matched = re.match(r"^(\w+)_(\d+)_(\d+)_(\w+)_(\w+)\.json$", os.path.basename(measure_files[0]))
        if matched:
            total_rank = int(matched.group(3))
            assert (rank < total_rank) and (total_rank % rank) == 0, (
                f"Original total_rank {total_rank} should be larger than your "
                f"target rank {rank} and be divisible by it")
            group_size = total_rank // rank
            group_list = [[str(i * group_size + j) for j in range(group_size)] for i in range(rank)]
            print("Card grouping list >> {}".format(group_list))
            return group_list
        else:
            raise ValueError("Unrecognized file name!")
    else:
        raise ValueError("*_mod_list.json doesn't exist in {}".format(measurements_path))

def main(args):
    args = parse_arguments(args)
    output_directory = args.out
    if not os.path.exists(output_directory):
        os.mkdir(output_directory)
    measurements_path = args.measurements
    groups = prepare_grouping_list(measurements_path, args.rank)

    num_jsons_drange = 0
    num_jsons_scales = 0
    for path in os.listdir(measurements_path):
        if path.endswith(".json"):
            if "MAXABS" in path:
                num_jsons_scales += 1
            elif "mod_list" not in path:
                num_jsons_drange += 1

    assert (os.path.isdir(measurements_path) and (num_jsons_drange % len(groups)) == 0
            and (num_jsons_scales % len(groups)) == 0)

    for group_index, group in enumerate(groups):
        consolidate_measurements(group,
                                 measurements_path,
                                 output_directory,
                                 num_jsons_drange,
                                 len(groups),
                                 group_index,
                                 scales=False,
                                 use_ep=args.use_expert_paral)
        if not args.skip_unify_scales:
            consolidate_measurements(
                group,
                measurements_path,
                output_directory,
                num_jsons_scales,
                len(groups),
                group_index,
                scales=True,
                use_ep=args.use_expert_paral,
            )
    print("finished measurement unifier script")

if __name__ == "__main__":
    main(sys.argv[1:])

# Command-line tool for fetching and parsing web pages
import argparse
import sys
import logging

def execute():
    parser = argparse.ArgumentParser(description='Web content extractor')
    parser.add_argument('target', help='Target URL to retrieve')
    parser.add_argument('--mode', choices=['standard', 'bypass', 'render'], default='standard',
                        help='Fetching strategy: standard (quick), bypass (anti-detection), render (execute JS)')
    parser.add_argument('--pattern', '-p', help='CSS selector for selecting specific elements')
    parser.add_argument('--field', default='text', help='Field to extract (text, href, src, etc.)')
    parser.add_argument('--output-json', action='store_true', help='Format output as JSON array')
    parser.add_argument('-v', '--verbose', action='store_false', dest='silence', help='Enable INFO logs (default: disabled)')
    arguments = parser.parse_args()

    if arguments.silence:
        logging.disable(logging.INFO)

    try:
        response = _retrieve(arguments.target, arguments.mode)
    except Exception as error:
        print(f"FAILURE: {error}", file=sys.stderr)
        sys.exit(1)

    if not arguments.pattern:
        # Default behavior: extract all visible text
        content = response.get_all_text(' ', ignore_tags=('script', 'style', 'noscript'))
        print(content)
        return

    matched_items = response.css(arguments.pattern)
    if not matched_items:
        print(f"No matches found for: {arguments.pattern}", file=sys.stderr)
        sys.exit(1)

    extracted_values = []
    for item in matched_items:
        if arguments.field == 'text':
            value = item.text or item.get_all_text()
        elif arguments.field == 'html':
            value = item.html_content
        else:
            value = item.attrib.get(arguments.field, '')
        extracted_values.append(value.strip())

    if arguments.output_json:
        import json
        print(json.dumps(extracted_values, ensure_ascii=False, indent=2))
    else:
        for value in extracted_values:
            if value:
                print(value)

def _retrieve(url, strategy):
    if strategy == 'standard':
        from scrapling.fetchers import Fetcher
        return Fetcher.get(url)
    elif strategy == 'bypass':
        from scrapling.fetchers import StealthyFetcher
        return StealthyFetcher.fetch(url, headless=True, network_idle=True)
    elif strategy == 'render':
        from scrapling.fetchers import DynamicFetcher
        return DynamicFetcher.fetch(url, headless=True, network_idle=True)

if __name__ == '__main__':
    execute()

