        if isinstance(image, Image.Image):
            processed_img = self.image_processor.preprocess(image)
        elif isinstance(image, torch.Tensor):
            if image.dim() == 3:
                image = image.unsqueeze(0)
            processed_img = image
        else:
            raise ValueError(f"Unsupported image type: {type(image)}")
        return processed_img

    @torch.no_grad()
    def infer(self, prompt, image_list=None):
        if self.cpu_offload and not self.qwen3_quantized:
            self.text_encoder.to(AI_DEVICE)

        if isinstance(prompt, str):
            prompt = [prompt]

        for idx, prompt_item in enumerate(prompt):
            messages = [{"role": "user", "content": prompt_item}]
            prompt_tokens = self.tokenizer.apply_chat_template(
                messages,
                tokenize=False,
                add_generation_prompt=True,
                enable_thinking=True
            )
            prompt[idx] = prompt_tokens

        text_inputs = self.tokenizer(
            prompt,
            max_length=self.tokenizer_max_length,
            padding="max_length",
            truncation=True,
            return_tensors="pt"
        ).to(AI_DEVICE)

        prompt_masks = text_inputs.attention_mask.bool().to(AI_DEVICE)
        prompt_embeds = self.text_encoder(
            input_ids=text_inputs.input_ids,
            attention_mask=prompt_masks,
            output_hidden_states=True,
        ).hidden_states[-2]

        embedding_list = []
        for idx in range(len(prompt_embeds)):
            extracted = prompt_embeds[idx][prompt_masks[idx]]
            embedding_list.append(extracted)

        image_info = {}
        if self.config["task"] == "i2i" and image_list is not None:
            vae_image_list = []
            for image in image_list:
                preprocessed_image = self.preprocess_image(image)
                vae_image_list.append(preprocessed_image)
            image_info = {
                "vae_image_list": vae_image_list,
            }

        if self.cpu_offload and not self.qwen3_quantized:
            self.text_encoder.to(torch.device("cpu"))
            torch_device_module.empty_cache()
            gc.collect()

        return embedding_list, image_info

# Convert GLM-4-MoE model weights to HuggingFace format
import re
import torch

def transform_glm4moe_to_hf(args, layer_name, weight_tensor):
    # Handle embedding and output layers
    if layer_name == "module.module.embedding.word_embeddings.weight":
        return [("model.embed_tokens.weight", weight_tensor)]
    if layer_name == "module.module.output_layer.weight":
        return [("lm_head.weight", weight_tensor)]
    if layer_name == "module.module.decoder.final_layernorm.weight":
        return [("model.norm.weight", weight_tensor)]

    # Compute head dimension with fallback
    try:
        dim_per_head = args.kv_channels if args.kv_channels is not None else args.hidden_size // args.num_attention_heads
    except AttributeError:
        dim_per_head = args.hidden_size // args.num_attention_heads

    q_per_group = args.num_attention_heads // args.num_query_groups
    decoder_pattern = r"module\.module\.decoder\.layers\.(\d+)\.(.+)"
    match = re.match(decoder_pattern, layer_name)

    if match:
        layer_id, rest_part = match.groups()

        # Experts handling
        expert_regex = r"mlp.experts\.(.+)\.weight(\d+)"
        exp_match = re.match(expert_regex, rest_part)
        if exp_match:
            rest_exp, expert_num = exp_match.groups()
            if rest_exp == "linear_fc1":
                gate_w, up_w = weight_tensor.chunk(2, dim=0)
                return [
                    (f"model.layers.{layer_id}.mlp.experts.{expert_num}.gate_proj.weight", gate_w),
                    (f"model.layers.{layer_id}.mlp.experts.{expert_num}.up_proj.weight", up_w),
                ]
            elif rest_exp == "linear_fc2":
                return [
                    (f"model.layers.{layer_id}.mlp.experts.{expert_num}.down_proj.weight", weight_tensor),
                ]
            else:
                raise ValueError(f"Unknown expert parameter name: {layer_name}")

        # Shared experts handling
        shared_exp_regex = r"mlp.shared_experts\.(.+)"
        sh_exp_match = re.match(shared_exp_regex, rest_part)
        if sh_exp_match:
            rest_sh = sh_exp_match.groups()[0]
            if rest_sh == "linear_fc1.weight":
                gate_w, up_w = weight_tensor.chunk(2, dim=0)
                return [
                    (f"model.layers.{layer_id}.mlp.shared_experts.gate_proj.weight", gate_w),
                    (f"model.layers.{layer_id}.mlp.shared_experts.up_proj.weight", up_w),
                ]
            elif rest_sh == "linear_fc2.weight":
                return [
                    (f"model.layers.{layer_id}.mlp.shared_experts.down_proj.weight", weight_tensor),
                ]
            else:
                raise ValueError(f"Unknown shared expert parameter name: {layer_name}")

        # Standard attention and MLP layers
        if rest_part == "self_attention.linear_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.o_proj.weight", weight_tensor)]
        elif rest_part == "self_attention.linear_qkv.weight":
            reshaped = weight_tensor.view(args.num_query_groups, -1, dim_per_head, args.hidden_size)
            q_t, k_t, v_t = torch.split(reshaped, split_size_or_sections=[q_per_group, 1, 1], dim=1)
            q_flat = q_t.reshape(-1, args.hidden_size)
            k_flat = k_t.reshape(-1, args.hidden_size)
            v_flat = v_t.reshape(-1, args.hidden_size)
            return [
                (f"model.layers.{layer_id}.self_attn.q_proj.weight", q_flat),
                (f"model.layers.{layer_id}.self_attn.k_proj.weight", k_flat),
                (f"model.layers.{layer_id}.self_attn.v_proj.weight", v_flat),
            ]
        elif rest_part == "self_attention.linear_qkv.bias":
            bias_view = weight_tensor.view(args.num_query_groups, -1)
            q_b, k_b, v_b = torch.split(
                bias_view,
                split_size_or_sections=[q_per_group * dim_per_head, dim_per_head, dim_per_head],
                dim=1,
            )
            q_b_flat = q_b.contiguous().flatten()
            k_b_flat = k_b.contiguous().flatten()
            v_b_flat = v_b.contiguous().flatten()
            return [
                (f"model.layers.{layer_id}.self_attn.q_proj.bias", q_b_flat),
                (f"model.layers.{layer_id}.self_attn.k_proj.bias", k_b_flat),
                (f"model.layers.{layer_id}.self_attn.v_proj.bias", v_b_flat),
            ]
        elif rest_part == "mlp.linear_fc1.weight":
            gate_w, up_w = weight_tensor.chunk(2, dim=0)
            return [
                (f"model.layers.{layer_id}.mlp.gate_proj.weight", gate_w),
                (f"model.layers.{layer_id}.mlp.up_proj.weight", up_w),
            ]
        elif rest_part == "mlp.linear_fc2.weight":
            return [(f"model.layers.{layer_id}.mlp.down_proj.weight", weight_tensor)]
        elif rest_part == "self_attention.linear_qkv.layer_norm_weight":
            return [(f"model.layers.{layer_id}.input_layernorm.weight", weight_tensor)]
        elif rest_part == "mlp.linear_fc1.layer_norm_weight":
            return [(f"model.layers.{layer_id}.post_attention_layernorm.weight", weight_tensor)]
        elif rest_part == "post_self_attn_layernorm.weight":
            return [(f"model.layers.{layer_id}.post_self_attn_layernorm.weight", weight_tensor)]
        elif rest_part == "post_mlp_layernorm.weight":
            return [(f"model.layers.{layer_id}.post_mlp_layernorm.weight", weight_tensor)]
        elif rest_part == "pre_mlp_layernorm.weight":
            return [(f"model.layers.{layer_id}.post_attention_layernorm.weight", weight_tensor)]
        elif rest_part == "mlp.router.weight":
            return [(f"model.layers.{layer_id}.mlp.gate.weight", weight_tensor)]
        elif rest_part == "mlp.router.expert_bias":
            return [(f"model.layers.{layer_id}.mlp.gate.e_score_correction_bias", weight_tensor)]
        # QK normalization
        elif rest_part == "self_attention.q_layernorm.weight":
            return [(f"model.layers.{layer_id}.self_attn.q_norm.weight", weight_tensor)]
        elif rest_part == "self_attention.k_layernorm.weight":
            return [(f"model.layers.{layer_id}.self_attn.k_norm.weight", weight_tensor)]

    # MTP layer handling
    mtp_pattern = r"module\.module\.mtp\.layers\.(\d+)\.(.+)"
    mtp_match = re.match(mtp_pattern, layer_name)
    if mtp_match:
        mtp_layer_id, rest_mtp = mtp_match.groups()
        adjusted_idx = int(mtp_layer_id) + args.num_layers
        if rest_mtp == "eh_proj.weight":
            return [(f"model.layers.{adjusted_idx}.eh_proj.weight", weight_tensor)]
        elif rest_mtp == "enorm.weight":
            return [(f"model.layers.{adjusted_idx}.enorm.weight", weight_tensor)]
        elif rest_mtp == "hnorm.weight":
            return [(f"model.layers.{adjusted_idx}.hnorm.weight", weight_tensor)]
        elif rest_mtp == "final_layernorm.weight":
            return [(f"model.layers.{adjusted_idx}.shared_head.norm.weight", weight_tensor)]
        else:
            new_name = f"module.module.decoder.layers.{adjusted_idx}.{rest_mtp}"
            new_name = new_name.replace("transformer_layer.", "")
            return transform_glm4moe_to_hf(args, new_name, weight_tensor)

    raise ValueError(f"Unknown parameter name: {layer_name}")

# Import necessary modules
import re
import warnings
from contextlib import contextmanager
from ...processing_utils import ProcessorMixin

class DonutProcessor(ProcessorMixin):
    r"""
    Constructs a Donut processor which wraps a Donut image processor and an XLMRoBERTa tokenizer into a single
    processor.
    [`DonutProcessor`] offers all the functionalities of [`DonutImageProcessor`] and
    [`XLMRobertaTokenizer`/`XLMRobertaTokenizerFast`]. See the [`~DonutProcessor.__call__`] and
    [`~DonutProcessor.decode`] for more information.
    Args:
        image_processor ([`DonutImageProcessor`], *optional*):
            An instance of [`DonutImageProcessor`]. The image processor is a required input.
        tokenizer ([`XLMRobertaTokenizer`/`XLMRobertaTokenizerFast`], *optional*):
            An instance of [`XLMRobertaTokenizer`/`XLMRobertaTokenizerFast`]. The tokenizer is a required input.
    """
    attributes = ["image_processor", "tokenizer"]
    image_processor_class = "AutoImageProcessor"
    tokenizer_class = "AutoTokenizer"

    def __init__(self, img_processor=None, text_tokenizer=None, **extra_kwargs):
        extractor = None
        if "feature_extractor" in extra_kwargs:
            warnings.warn(
                "The `feature_extractor` argument is deprecated and will be removed in v5, use `image_processor`"
                " instead.",
                FutureWarning,
            )
            extractor = extra_kwargs.pop("feature_extractor")

        img_processor = img_processor if img_processor is not None else extractor

        if img_processor is None:
            raise ValueError("You need to specify an `image_processor`.")
        if text_tokenizer is None:
            raise ValueError("You need to specify a `tokenizer`.")

        super().__init__(img_processor, text_tokenizer)
        self.active_processor = self.img_processor
        self._inside_context_manager = False

    def __call__(self, *input_args, **input_kwargs):
        """
        When used in normal mode, this method forwards all its arguments to AutoImageProcessor's
        [`~AutoImageProcessor.__call__`] and returns its output. If used in the context
        [`~DonutProcessor.as_target_processor`] this method forwards all its arguments to DonutTokenizer's
        [`~DonutTokenizer.__call__`]. Please refer to the doctsring of the above two methods for more information.
        """
        # For backward compatibility
        if self._inside_context_manager:
            return self.active_processor(*input_args, **input_kwargs)

        images_input = input_kwargs.pop("images", None)
        text_input = input_kwargs.pop("text", None)

        if len(input_args) > 0:
            images_input = input_args[0]
            input_args = input_args[1:]

        if images_input is None and text_input is None:
            raise ValueError("You need to specify either an `images` or `text` input to process.")

        if images_input is not None:
            image_inputs = self.image_processor(images_input, *input_args, **input_kwargs)
        if text_input is not None:
            tokenized_text = self.tokenizer(text_input, **input_kwargs)

        if text_input is None:
            return image_inputs
        elif images_input is None:
            return tokenized_text
        else:
            image_inputs["labels"] = tokenized_text["input_ids"]
            return image_inputs

    def batch_decode(self, *args, **kwargs):
        """
        This method forwards all its arguments to DonutTokenizer's [`~PreTrainedTokenizer.batch_decode`]. Please refer
        to the docstring of this method for more information.
        """
        return self.tokenizer.batch_decode(*args, **kwargs)

    def decode(self, *args, **kwargs):
        """
        This method forwards all its arguments to DonutTokenizer's [`~PreTrainedTokenizer.decode`]. Please refer to the
        docstring of this method for more information.
        """
        return self.tokenizer.decode(*args, **kwargs)

    @contextmanager
    def as_target_processor(self):
        """
        Temporarily sets the tokenizer for processing the input. Useful for encoding the labels when fine-tuning TrOCR.
        """
        warnings.warn(
            "`as_target_processor` is deprecated and will be removed in v5 of Transformers. You can process your "
            "labels by using the argument `text` of the regular `__call__` method (either in the same call as "
            "your images inputs, or in a separate call."
        )
        self._inside_context_manager = True
        self.active_processor = self.tokenizer
        yield
        self.active_processor = self.image_processor
        self._inside_context_manager = False

    def token2json(self, token_sequence, is_inner_value=False, added_vocab=None):
        """
        Convert a (generated) token sequence into an ordered JSON format.
        """
        if added_vocab is None:
            added_vocab = self.tokenizer.get_added_vocab()

        result_dict = {}
        while token_sequence:
            start_match = re.search(r"<s_(.*?)>", token_sequence, re.IGNORECASE)
            if start_match is None:
                break

            key = start_match.group(1)
            key_escaped = re.escape(key)
            end_match = re.search(rf"</s_{key_escaped}>", token_sequence, re.IGNORECASE)

            start_token_str = start_match.group()
            if end_match is None:
                token_sequence = token_sequence.replace(start_token_str, "")
            else:
                end_token_str = end_match.group()
                start_token_escaped = re.escape(start_token_str)
                end_token_escaped = re.escape(end_token_str)

                content_match = re.search(
                    f"{start_token_escaped}(.*?){end_token_escaped}", token_sequence, re.IGNORECASE | re.DOTALL
                )
                if content_match is not None:
                    content = content_match.group(1).strip()
                    if r"<s_" in content and r"</s_" in content:  # non-leaf node
                        nested_value = self.token2json(content, is_inner_value=True, added_vocab=added_vocab)
                        if nested_value:
                            if len(nested_value) == 1:
                                nested_value = nested_value[0]
                            result_dict[key] = nested_value
                    else:  # leaf nodes
                        result_dict[key] = []
                        for leaf in content.split(r"<sep/>"):
                            leaf = leaf.strip()
                            if leaf in added_vocab and leaf[0] == "<" and leaf[-2:] == "/>":
                                leaf = leaf[1:-2]  # for categorical special tokens
                            result_dict[key].append(leaf)
                        if len(result_dict[key]) == 1:
                            result_dict[key] = result_dict[key][0]

                token_sequence = token_sequence[token_sequence.find(end_token_str) + len(end_token_str):].strip()
                if token_sequence[:6] == r"<sep/>":  # non-leaf nodes
                    return [result_dict] + self.token2json(token_sequence[6:], is_inner_value=True, added_vocab=added_vocab)

        if len(result_dict):
            return [result_dict] if is_inner_value else result_dict
        else:
            return [] if is_inner_value else {"text_sequence": token_sequence}

    @property
    def feature_extractor_class(self):
        warnings.warn(
            "`feature_extractor_class` is deprecated and will be removed in v5. Use `image_processor_class` instead.",
            FutureWarning,
        )
        return self.image_processor_class

    @property
    def feature_extractor(self):
        warnings.warn(
            "`feature_extractor` is deprecated and will be removed in v5. Use `image_processor` instead.",
            FutureWarning,
        )
        return self.image_processor

# WebAuthn API endpoints for managing authentication credentials
from flask import Blueprint, request, g
from auth.unified import require_auth
from models import db
from models.webauthn import WebAuthnCredential
from services.webauthn_service import WebAuthnService
from services.audit_service import AuditService
from utils.response import success_response, error_response

bp = Blueprint('webauthn', __name__, url_prefix='/api/v2/webauthn')

@bp.route('/credentials', methods=['GET'])
@require_auth()
def list_credentials():
    """Retrieve all WebAuthn credentials for the authenticated user"""
    current_user = g.current_user
    user_creds = WebAuthnService.get_user_credentials(current_user.id)
    return success_response(data=[cred.to_dict() for cred in user_creds])

@bp.route('/credentials/<int:cred_id>', methods=['DELETE'])
@require_auth()
def remove_credential(cred_id):
    """Remove a specific WebAuthn credential"""
    current_user = g.current_user
    operation_success, status_msg = WebAuthnService.delete_credential(cred_id, current_user.id)

    if not operation_success:
        return error_response(status_msg, 404)

    AuditService.log_action(
        action='webauthn_delete',
        resource_type='webauthn',
        resource_id=str(cred_id),
        resource_name=f'WebAuthn credential {cred_id}',
        details=f'Deleted WebAuthn credential {cred_id}',
        success=True
    )

    return success_response(message=status_msg)

@bp.route('/credentials/<int:cred_id>/toggle', methods=['POST'])
@require_auth()
def update_credential_status(cred_id):
    """Enable or disable a WebAuthn credential"""
    current_user = g.current_user
    payload = request.get_json() or {}
    new_status = payload.get('enabled', True)

    operation_success, status_msg = WebAuthnService.toggle_credential(cred_id, current_user.id, new_status)

    if not operation_success:
        return error_response(status_msg, 404)

    AuditService.log_action(
        action='webauthn_toggle',
        resource_type='webauthn',
        resource_id=str(cred_id),
        resource_name=f'WebAuthn credential {cred_id}',
        details=f'{"Enabled" if new_status else "Disabled"} WebAuthn credential {cred_id}',
        success=True
    )

    return success_response(message=status_msg)

@bp.route('/register/options', methods=['POST'])
@require_auth()
def get_registration_params():
    """Generate WebAuthn registration parameters using secure cryptographic methods"""
    current_user = g.current_user
    server_host = request.host

    reg_options = WebAuthnService.generate_registration_options(current_user, server_host)
    return success_response(data=reg_options)

@bp.route('/register/verify', methods=['POST'])
@require_auth()
def confirm_registration():
    """Validate WebAuthn registration response and store credential"""
    current_user = g.current_user
    incoming_data = request.get_json()

    credential_info = incoming_data.get('credential', {})
    credential_label = incoming_data.get('name', 'Security Key')
    server_host = request.host

    operation_success, status_msg, new_credential = WebAuthnService.verify_registration(
        current_user.id, credential_info, server_host, credential_label
    )

    if not operation_success:
        return error_response(status_msg, 400)

    AuditService.log_action(
        action='webauthn_register',
        resource_type='webauthn',
        resource_id=str(new_credential.id) if new_credential else None,
        resource_name=credential_label,
        details=f'Registered WebAuthn credential: {credential_label}',
        success=True
    )

    return success_response(
        data=new_credential.to_dict() if new_credential else None, 
        message=status_msg
    )

# Custom YAML-based static analysis rules for Skylos
from __future__ import annotations
import ast
import fnmatch
from pathlib import Path
from skylos.rules.base import SkylosRule

class YamlAnalyzer(SkylosRule):
    def __init__(self, settings):
        self._rule_identifier = settings["rule_id"]
        self._title = settings["name"]
        self.severity_level = settings.get("severity", "MEDIUM")
        self.group = settings.get("category", "custom")
        self.match_criteria = settings.get("yaml_config", {}).get("pattern", {})
        self.report_text = settings.get("yaml_config", {}).get(
            "description", "Custom rule violation detected"
        )

    @property
    def identifier(self):
        return self._rule_identifier

    @property
    def title(self):
        return self._title

    def analyze_node(self, node, context):
        match_kind = self.match_criteria.get("type")
        if match_kind == "function":
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                return self._analyze_function(node, context)
        elif match_kind == "class":
            if isinstance(node, ast.ClassDef):
                return self._analyze_class(node, context)
        elif match_kind == "call":
            if isinstance(node, ast.Call):
                return self._analyze_call(node, context)
        return None

    def _analyze_function(self, node, context):
        decorator_requirements = self.match_criteria.get("decorators", {})
        any_decorator = decorator_requirements.get("has_any", [])
        additional_decorators = decorator_requirements.get("must_also_have_any", [])

        if not any_decorator:
            return None

        found_decorators = set()
        for deco in node.decorator_list:
            found_decorators.add(self._extract_decorator_name(deco))

        is_triggered = False
        for required_pattern in any_decorator:
            for deco_name in found_decorators:
                if required_pattern in deco_name:
                    is_triggered = True
                    break
            if is_triggered:
                break

        if not is_triggered:
            return None

        if additional_decorators:
            has_all_required = False
            for req_pattern in additional_decorators:
                for deco_name in found_decorators:
                    if req_pattern in deco_name:
                        has_all_required = True
                        break
                if has_all_required:
                    break
            if not has_all_required:
                return [self._create_finding(node, context)]
        return None

    def _analyze_class(self, node, context):
        name_match = self.match_criteria.get("name_pattern", "*")
        required_base_classes = self.match_criteria.get("must_inherit_any", [])

        if not fnmatch.fnmatch(node.name, name_match):
            return None

        if required_base_classes:
            base_names = set()
            for base in node.bases:
                base_names.add(self._extract_base_name(base))
            if not (set(required_base_classes) & base_names):
                return [self._create_finding(node, context)]
        return None

    def _analyze_call(self, node, context):
        function_patterns = self.match_criteria.get("function_match", [])
        argument_rules = self.match_criteria.get("args", {})

        func_name = self._extract_call_name(node)
        if not func_name:
            return None

        is_matched = any(pattern in func_name for pattern in function_patterns)
        if not is_matched:
            return None

        if argument_rules.get("is_dynamic"):
            arg_position = argument_rules.get("position", 0)
            if len(node.args) > arg_position:
                if self._is_dynamic_expression(node.args[arg_position]):
                    return [self._create_finding(node, context)]
        return None

    def _extract_decorator_name(self, deco):
        if isinstance(deco, ast.Name):
            return deco.id
        elif isinstance(deco, ast.Attribute):
            parent_name = self._extract_decorator_name(deco.value)
            return f"{parent_name}.{deco.attr}" if parent_name else deco.attr
        elif isinstance(deco, ast.Call):
            return self._extract_decorator_name(deco.func)
        return ""

    def _extract_base_name(self, base):
        if isinstance(base, ast.Name):
            return base.id
        elif isinstance(base, ast.Attribute):
            return base.attr
        return ""

    def _extract_call_name(self, node):
        func = node.func
        components = []
        while isinstance(func, ast.Attribute):
            components.append(func.attr)
            func = func.value
        if isinstance(func, ast.Name):
            components.append(func.id)
            components.reverse()
            return ".".join(components)
        return None

    def _is_dynamic_expression(self, node):
        if isinstance(node, ast.JoinedStr):
            return True
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Mod)):
            return True
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Attribute) and node.func.attr == "format":
                return True
        return False

    def _create_finding(self, node, context):
        name = None
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            name = getattr(node, "name", None)
        if name is None and isinstance(node, ast.Call):
            name = self._extract_call_name(node) or "<call>"
        return {
            "rule_id": self.identifier,
            "kind": "custom",
            "category": self.group,
            "severity": self.severity_level,
            "message": self.report_text,
            "name": name or "<custom>",
            "simple_name": name or "<custom>",
            "value": "-",
            "file": context.get("filename"),
            "basename": Path(context.get("filename", "")).name,
            "line": getattr(node, "lineno", 0),
            "col": getattr(node, "col_offset", 0),
        }

def load_yaml_rules(rule_configs):
    rules = []
    for config in rule_configs:
        if not config.get("enabled", True):
            continue
        if config.get("rule_type") != "yaml":
            continue
        try:
            rules.append(YamlAnalyzer(config))
        except Exception as error:
            print(f"Warning: Failed to load rule {config.get('rule_id')}: {error}")
    return rules

