# Custom exception classes for HTTP and network-related errors
from pip._vendor.urllib3.exceptions import HTTPError as BaseHTTPError
from .compat import JSONDecodeError as CompatJSONDecodeError

class RequestException(IOError):
    """An ambiguous exception occurred during request handling."""
    def __init__(self, *args, **kwargs):
        """Initialize with optional `request` and `response` objects."""
        response = kwargs.pop("response", None)
        self.response = response
        self.request = kwargs.pop("request", None)
        if response is not None and not self.request and hasattr(response, "request"):
            self.request = self.response.request
        super().__init__(*args, **kwargs)

class InvalidJSONError(RequestException):
    """An error occurred while processing JSON."""

class JSONDecodeError(InvalidJSONError, CompatJSONDecodeError):
    """Failed to decode text into JSON format."""
    def __init__(self, *args, **kwargs):
        """
        Initialize by first constructing the JSONDecodeError with all
        arguments, then using its args to initialize the IOError parent
        to preserve the JSON-specific error message.
        """
        CompatJSONDecodeError.__init__(self, *args)
        InvalidJSONError.__init__(self, *self.args, **kwargs)

class HTTPError(RequestException):
    """An HTTP protocol error occurred."""

class ConnectionError(RequestException):
    """A connection establishment failure occurred."""

class ProxyError(ConnectionError):
    """An error occurred while using a proxy server."""

class SSLError(ConnectionError):
    """An SSL/TLS security error occurred."""

class Timeout(RequestException):
    """The request exceeded the allowed time limit.
    This exception encompasses both
    :exc:`~requests.exceptions.ConnectTimeout` and
    :exc:`~requests.exceptions.ReadTimeout` scenarios.
    """

class ConnectTimeout(ConnectionError, Timeout):
    """Connection attempt exceeded the timeout limit.
    These requests are generally safe to retry.
    """

class ReadTimeout(Timeout):
    """The server failed to respond within the allocated time window."""

class URLRequired(RequestException):
    """A valid URL must be provided for the request."""

class TooManyRedirects(RequestException):
    """The request exceeded the maximum number of allowed redirects."""

class MissingSchema(RequestException, ValueError):
    """The URL lacks a required scheme (e.g., 'http://' or 'https://')."""

class InvalidSchema(RequestException, ValueError):
    """The URL uses an unsupported or invalid schema."""

class InvalidURL(RequestException, ValueError):
    """The provided URL is malformed or syntactically incorrect."""

class InvalidHeader(RequestException, ValueError):
    """The header value does not conform to expected format."""

class InvalidProxyURL(InvalidURL):
    """The specified proxy URL is invalid."""

class ChunkedEncodingError(RequestException):
    """The server used chunked transfer encoding but sent malformed chunks."""

class ContentDecodingError(RequestException, BaseHTTPError):
    """Response content could not be decoded properly."""

class StreamConsumedError(RequestException, TypeError):
    """Attempted to read response content that has already been consumed."""

class RetryError(RequestException):
    """Custom retry mechanism encountered a failure."""

class UnrewindableBodyError(RequestException):
    """Unable to rewind request body after an error condition."""

# Warning classes
class RequestsWarning(Warning):
    """Base warning type for Requests library warnings."""

class FileModeWarning(RequestsWarning, DeprecationWarning):
    """A file was opened in text mode while Requests needed binary data."""

class RequestsDependencyWarning(RequestsWarning):
    """An imported dependency version does not meet requirements."""

# Custom YAML serialization utilities for safe dumping of Python objects
import enum
import functools
import inspect
from contextlib import contextmanager
from typing import Any, Generator, Optional
import yaml

@contextmanager
def secure_yaml_dumpers() -> Generator[None, None, None]:
    """
    Context manager to temporarily register custom YAML representers and restore originals afterward.
    Safely adds support for functions, enums, torch dtypes, and other special types during serialization.
    Usage:
        with secure_yaml_dumpers():
            yaml_output = yaml.safe_dump(target_object)
    """
    # Preserve original representers before modification
    saved_representers = yaml.SafeDumper.yaml_representers.copy()
    saved_multi_representers = yaml.SafeDumper.yaml_multi_representers.copy()
    try:
        # Register custom representers for various object types
        yaml.SafeDumper.add_representer(functools.partial, _partial_obj_representer)
        yaml.SafeDumper.add_multi_representer(enum.Enum, _enum_obj_representer)
        yaml.SafeDumper.add_representer(type(lambda: ...), _func_representer)
        yaml.SafeDumper.add_representer(type(object), _func_representer)

        # Handle optional dependencies like PyTorch and Transformers
        try:
            import torch
            yaml.SafeDumper.add_representer(torch.dtype, _torch_dtype_representer)
        except ModuleNotFoundError:
            pass

        try:
            from transformers import GenerationConfig
            yaml.SafeDumper.add_representer(GenerationConfig, _gen_config_representer)
        except ModuleNotFoundError:
            pass

        try:
            from transformers import PretrainedConfig
            yaml.SafeDumper.add_multi_representer(PretrainedConfig, _pretrained_config_representer)
        except ModuleNotFoundError:
            pass

        # Fallback representer for general objects
        yaml.SafeDumper.add_multi_representer(object, _general_obj_representer)
        yield
    finally:
        # Restore original representers after use
        yaml.SafeDumper.yaml_representers = saved_representers
        yaml.SafeDumper.yaml_multi_representers = saved_multi_representers

def serialize_to_yaml(data: Any, filepath: Optional[str] = None) -> Optional[str]:
    """Convert a dataclass or arbitrary Python object into YAML format.
    Uses secure representers to handle complex types safely.

    Args:
        data: The object to be serialized.
        filepath: Optional path to write the YAML output. If omitted, returns the YAML string.

    Returns:
        YAML string if filepath is None; otherwise None.
    """
    with secure_yaml_dumpers():
        if filepath is not None:
            with open(filepath, "w+") as file_handle:
                yaml.safe_dump(data, file_handle)
        else:
            return yaml.safe_dump(data)

def _func_representer(dumper, func_obj):
    """Serialize function objects using module and qualified name."""
    info = {
        "_target_": f"{inspect.getmodule(func_obj).__name__}.{func_obj.__qualname__}",
        "_call_": False,
    }
    return dumper.represent_data(info)

def _torch_dtype_representer(dumper, dtype_obj):
    """Serialize PyTorch dtype objects."""
    info = {
        "_target_": str(dtype_obj),
        "_call_": False,
    }
    return dumper.represent_data(info)

def _general_obj_representer(dumper, obj):
    """
    Generic object serializer for YAML.
    Attempts to extract module and qualified name; falls back to class info if needed.
    Sets '_call_' flag based on whether direct instantiation is possible.
    """
    try:
        target = f"{inspect.getmodule(obj).__name__}.{obj.__qualname__}"
        call_flag = False
    except AttributeError:
        cls = obj.__class__
        target = f"{inspect.getmodule(cls).__name__}.{cls.__qualname__}"
        call_flag = True

    info = {
        "_target_": target,
        "_call_": call_flag,
    }
    return dumper.represent_data(info)

def _partial_obj_representer(dumper, partial_obj):
    """Serialize functools.partial objects."""
    base_func = partial_obj.func
    info = {
        "_target_": f"{inspect.getmodule(base_func).__name__}.{base_func.__qualname__}",
        "_partial_": True,
        "_args_": list(partial_obj.args) if partial_obj.args else [],
    }

    if partial_obj.keywords:
        for key, val in partial_obj.keywords.items():
            info[key] = val

    return dumper.represent_data(info)

def _enum_obj_representer(dumper, enum_member):
    """Serialize enum members."""
    enum_class = enum_member.__class__
    info = {
        "_target_": f"{inspect.getmodule(enum_class).__name__}.{enum_class.__qualname__}",
        "_call_": True,
        "_args_": [enum_member.value],
        "_name_": enum_member.name,
    }
    return dumper.represent_data(info)

def _gen_config_representer(dumper, gen_config):
    """Serialize transformers GenerationConfig objects."""
    cls = gen_config.__class__
    info = {
        "_target_": f"{inspect.getmodule(cls).__name__}.{cls.__qualname__}.from_dict",
        "_call_": True,
        "config_dict": gen_config.to_dict(),
    }
    return dumper.represent_data(info)

def _pretrained_config_representer(dumper, pretrained_config):
    """Serialize transformers PretrainedConfig objects generically using from_dict/to_dict methods."""
    cls = pretrained_config.__class__
    info = {
        "_target_": f"{inspect.getmodule(cls).__name__}.{cls.__qualname__}.from_dict",
        "_call_": True,
        "config_dict": pretrained_config.to_dict(),
    }
    return dumper.represent_data(info)

# Jenkins monitoring module using threading and API calls
import logging
import os
import subprocess
import sys
import threading
import time
import traceback
import urllib2
import json
import base64

logging.basicConfig(level=logging.ERROR)
_main_thread = None

class JenkinsMonitorThread(threading.Thread):
    def __init__(self, config):
        threading.Thread.__init__(self)
        self.active = False
        self.terminate = False
        self.data_store = {}
        self.parameters = {}
        self.interval = 60
        self.api_endpoint = config['base_url']
        self.user = config['username']
        self.token = config['apitoken']
        self._data_lock = threading.Lock()
        self._config_lock = threading.Lock()

    def stop(self):
        self.terminate = True
        if not self.active:
            return
        self.join()

    def run(self):
        global _main_thread
        self.active = True
        while not self.terminate:
            time.sleep(self.interval)
            self.update_statistics()
        self.active = False

    @staticmethod
    def _fetch_jenkins_data(url, username, apitoken):
        url += '/api/json'
        url += '?tree=jobs[color],overallLoad[busyExecutors[min[latest]],queueLength[min[latest]],totalExecutors[min[latest]]]'
        if username and apitoken:
            url += '&token=' + apitoken
            req = urllib2.Request(url)
            encoded_creds = base64.encodestring('%s:%s' % (username, apitoken)).replace('\n', '')
            req.add_header("Authorization", "Basic %s" % encoded_creds)
            response = urllib2.urlopen(req, None, 2)
        else:
            response = urllib2.urlopen(url, None, 2)
        raw_data = response.read()
        response.close()
        parsed = json.loads(raw_data)
        output = {}
        output['jenkins_overallload_busy_executors'] = parsed['overallLoad']['busyExecutors']['min']['latest']
        output['jenkins_overallload_queue_length'] = parsed['overallLoad']['queueLength']['min']['latest']
        output['jenkins_overallload_total_executors'] = parsed['overallLoad']['totalExecutors']['min']['latest']
        output['jenkins_jobs_total'] = len(parsed['jobs'])
        # Initialize counters for all job colors
        statuses = ['red', 'yellow', 'grey', 'disabled', 'aborted', 'notbuilt', 'blue']
        for status in statuses:
            output['jenkins_jobs_' + status] = 0
        # Count jobs by color
        for job in parsed['jobs']:
            job_color = job['color']
            for status in statuses:
                if job_color == status or job_color == status + '_anime':
                    output['jenkins_jobs_' + status] += 1
        return output

    def update_statistics(self):
        logging.debug('updating metrics')
        try:
            logging.debug(' accessing URL: ' + str(self.api_endpoint))
            stats = JenkinsMonitorThread._fetch_jenkins_data(self.api_endpoint, self.user, self.token)
        except:
            logging.warning('failed to update metrics')
            logging.warning(traceback.print_exc(file=sys.stdout))
        try:
            self._data_lock.acquire()
            self.data_store = {}
            for key, value in stats.items():
                self.data_store[key] = value
        except:
            logging.warning('error during metric update')
            logging.warning(traceback.print_exc(file=sys.stdout))
            return False
        finally:
            self._data_lock.release()
        if not self.data_store:
            logging.warning('metric update failed')
            return False
        logging.debug('metrics updated successfully')
        logging.debug('current data: ' + str(self.data_store))
        return True

    def get_value(self, name):
        logging.debug('retrieving metric: ' + name)
        try:
            if name in self.data_store:
                try:
                    self._data_lock.acquire()
                    logging.debug('metric: %s = %s' % (name, self.data_store[name]))
                    return self.data_store[name]
                finally:
                    self._data_lock.release()
        except:
            logging.warning('could not retrieve ' + name)
            return 0

    def get_config(self, name):
        logging.debug('retrieving configuration: ' + name)
        try:
            if name in self.parameters:
                try:
                    self._config_lock.acquire()
                    logging.debug('config: %s = %s' % (name, self.parameters[name]))
                    return self.parameters[name]
                finally:
                    self._config_lock.release()
        except:
            logging.warning('failed to fetch ' + name)
            return 0


def initialize_metrics(params):
    logging.debug('initialization: ' + str(params))
    global _main_thread
    DEFAULT_SETTINGS = {
        'units': 'jobs',
        'groups': 'jenkins',
        'slope': 'both',
        'value_type': 'uint',
        'format': '%d',
        'description': '',
        'callback': get_metric_value
    }
    METRIC_DESCRIPTIONS = dict(
        jenkins_overallload_busy_executors={
            'value_type': 'float',
            'format': '%.3f',
            'units': 'executors',
            'description': 'Active executors count (master and slaves)'},
        jenkins_overallload_queue_length={
            'value_type': 'float',
            'format': '%.3f',
            'units': 'pending tasks',
            'description': 'Queue size (master and slaves)'},
        jenkins_overallload_total_executors={
            'value_type': 'float',
            'format': '%.3f',
            'units': 'executors',
            'description': 'Total executor capacity (master and slaves)'},
        jenkins_jobs_total={
            'description': 'Aggregate job count'},
        jenkins_jobs_blue={
            'description': 'Successful jobs'},
        jenkins_jobs_red={
            'description': 'Failed jobs'},
        jenkins_jobs_yellow={
            'description': 'Unstable jobs'},
        jenkins_jobs_grey={
            'description': 'Pending jobs'},
        jenkins_jobs_disabled={
            'description': 'Disabled jobs'},
        jenkins_jobs_aborted={
            'description': 'Cancelled jobs'},
        jenkins_jobs_notbuilt={
            'description': 'Unbuilt jobs'})

    if _main_thread is not None:
        raise Exception('Monitoring thread already active')

    _main_thread = JenkinsMonitorThread(params)
    _main_thread.update_statistics()
    _main_thread.start()

    metric_list = []
    for name, desc in METRIC_DESCRIPTIONS.iteritems():
        entry = desc.copy()
        entry['name'] = str(name)
        [ entry.setdefault(key, DEFAULT_SETTINGS[key]) for key in DEFAULT_SETTINGS.iterkeys() ]
        metric_list.append(entry)
    return metric_list


def get_metric_value(name):
    global _main_thread
    return _main_thread.get_value(name)


def get_configuration_value(name):
    global _main_thread
    return _main_thread.get_config(name)


def release_resources():
    global _main_thread
    if _main_thread is not None:
        _main_thread.stop()
    logging.shutdown()


if __name__ == '__main__':
    from optparse import OptionParser
    try:
        logging.debug('command-line execution detected')
        parser = OptionParser()
        parser.add_option('-u', '--URL', dest='base_url', default='http://127.0.0.1:8080', help='Jenkins API endpoint (default: http://127.0.0.1:8080)')
        parser.add_option('-q', '--quiet', dest='silent', action='store_true', default=False)
        parser.add_option('-d', '--debug', dest='verbose', action='store_true', default=False)
        parser.add_option('-n', '--username', dest='username', default='', help='Jenkins username (default: empty)')
        parser.add_option('-a', '--apitoken', dest='apitoken', default='', help='API token (default: empty)')
        (opts, args) = parser.parse_args()

        descriptors = initialize_metrics({
            'base_url': opts.base_url,
            'username': opts.username,
            'apitoken': opts.apitoken,
        })

        if opts.verbose:
            from pprint import pprint
            pprint(descriptors)

        for item in descriptors:
            val = item['callback'](item['name'])
            if not opts.silent:
                print ' {0}: {1} {2} [{3}]' . format(item['name'], val, item['units'], item['description'])
        os._exit(1)
    except KeyboardInterrupt:
        time.sleep(0.2)
        os._exit(1)
    except StandardError:
        traceback.print_exc()
        os._exit(1)
    finally:
        release_resources()

