# Load environment variables and initialize Ollama integration
import json
import os
from dotenv import load_dotenv
from openai import OpenAI
from utils import JobInput

client = OpenAI(
    base_url='http://localhost:11434/v1/',
    # Required but ignored by Ollama
    api_key='REDACTED_CREDENTIAL',
)

class OllamaEngine:
    def __init__(self):
        load_dotenv()
        print("OllamaEngine initialized")

    async def generate(self, job_input):
        # Retrieve model name from environment, defaulting to 'llama3.2:1b'
        model = os.getenv("OLLAMA_MODEL_NAME", "llama3.2:1b")

        # Handle input based on type (string vs list)
        if isinstance(job_input.llm_input, str):
            # Construct JobInput for text completion endpoint
            openAiJob = JobInput({
                "openai_route": "/v1/completions",
                "openai_input": {
                    "model": model,
                    "prompt": job_input.llm_input,
                    "stream": job_input.stream
                }
            })
        else:
            # Construct JobInput for chat completions endpoint
            openAiJob = JobInput({
                "openai_route": "/v1/chat/completions",
                "openai_input": {
                    "model": model,
                    "messages": job_input.llm_input,
                    "stream": job_input.stream
                }
            })

        print("Generating response for job_input:", job_input)
        print("OpenAI job:", openAiJob)

        # Delegate to OpenAI-compatible engine
        openAIEngine = OllamaOpenAiEngine()
        generate = openAIEngine.generate(openAiJob)

        # Stream responses back to caller
        async for batch in generate:
            yield batch


class OllamaOpenAiEngine(OllamaEngine):
    def __init__(self):
        load_dotenv()
        print("OllamaOpenAiEngine initialized")

    async def generate(self, job_input):
        print("Generating response for job_input:", job_input)
        openai_input = job_input.openai_input

        # Route handling based on API endpoint
        if job_input.openai_route == "/v1/models":
            async for response in self._handle_model_request():
                yield response
        elif job_input.openai_route in ["/v1/chat/completions", "/v1/completions"]:
            is_chat = job_input.openai_route == "/v1/chat/completions"
            async for response in self._handle_chat_or_completion_request(openai_input, chat=is_chat):
                yield response
        else:
            yield {"error": "Invalid route"}

    async def _handle_model_request(self):
        try:
            response = client.models.list()
            # Convert Model objects to dictionaries
            yield {"object": "list", "data": [model.to_dict() for model in response.data]}
        except Exception as e:
            yield {"error": str(e)}

    async def _handle_chat_or_completion_request(self, openai_input, chat=False):
        try:
            # Route call to appropriate OpenAI method
            if chat:
                response = client.chat.completions.create(**openai_input)
            else:
                response = client.completions.create(**openai_input)

            # Non-streaming response
            if not openai_input.get("stream", False):
                yield response.to_dict()
                return

            # Streaming response
            for chunk in response:
                print("Message:", chunk)
                yield "data: " + json.dumps(chunk.to_dict(), separators=(',', ':')) + "\n\n"
            yield "data: [DONE]"
        except Exception as e:
            yield {"error": str(e)}

# Calculate conflicts and compatibility between skill contracts
import json
import os
import re
import sys
from collections import defaultdict

def load_skill_contracts(ontology_dir):
    """Load ontologyContract from all skill.json files in ontology_dir."""
    contracts = {}
    if not os.path.isdir(ontology_dir):
        return contracts
    for item in sorted(os.listdir(ontology_dir)):
        skill_file = os.path.join(ontology_dir, item, "skill.json")
        if not os.path.isfile(skill_file):
            continue
        try:
            with open(skill_file) as file:
                content = json.load(file)
        except (json.JSONDecodeError, IOError):
            continue
        contract = content.get("ontologyContract")
        if contract and contract.get("ontology"):
            contracts[item] = contract
    return contracts

def extract_postcondition(postcond_str):
    """Parse a postcondition string into structured format.
    Returns dict with: entity_type, property, operator, value
    or None if parsing fails.
    """
    segments = postcond_str.split(".", 1)
    if len(segments) != 2:
        return None
    entity = segments[0]
    remainder = segments[1]
    if " == " in remainder:
        prop, val = remainder.split(" == ", 1)
        return {
            "entity_type": entity,
            "property": prop.strip(),
            "operator": "==",
            "value": val.strip().strip("'\""),
        }
    elif " != " in remainder:
        prop, val = remainder.split(" != ", 1)
        return {
            "entity_type": entity,
            "property": prop.strip(),
            "operator": "!=",
            "value": val.strip().strip("'\""),
        }
    elif " is valid enum" in remainder:
        prop = remainder.replace(" is valid enum", "").strip()
        return {
            "entity_type": entity,
            "property": prop,
            "operator": "is_valid_enum",
            "value": None,
        }
    elif " exists" in remainder:
        prop = remainder.replace(" exists", "").strip()
        return {
            "entity_type": entity,
            "property": prop,
            "operator": "exists",
            "value": None,
        }
    return None

def find_incompatibilities(contracts_data):
    """Find conflicting postconditions across skills.
    Returns list of conflict dictionaries.
    """
    # Group postconditions by (entity_type, property)
    field_conditions = defaultdict(list)
    for skill_name, contract in contracts_data.items():
        ontology = contract.get("ontology", {})
        for condition in ontology.get("postconditions", []):
            parsed = extract_postcondition(condition)
            if parsed:
                key = (parsed["entity_type"], parsed["property"])
                field_conditions[key].append({
                    "skill": skill_name,
                    "raw": condition,
                    "parsed": parsed,
                })

    incompatibilities = []
    for field_key, items in field_conditions.items():
        if len(items) < 2:
            continue
        # Compare all pairs
        for idx_a in range(len(items)):
            for idx_b in range(idx_a + 1, len(items)):
                item_a = items[idx_a]
                item_b = items[idx_b]
                pa = item_a["parsed"]
                pb = item_b["parsed"]
                issue = None

                # Case 1: One requires equality to v, other forbids it
                if pa["operator"] == "==" and pb["operator"] == "!=" and pa["value"] == pb["value"]:
                    issue = {
                        "type": "equality_vs_inequality",
                        "description": (
                            f"{item_a['skill']} requires {pa['entity_type']}.{pa['property']} == '{pa['value']}' "
                            f"but {item_b['skill']} forbids it (!= '{pb['value']}')"
                        ),
                    }
                elif pa["operator"] == "!=" and pb["operator"] == "==" and pa["value"] == pb["value"]:
                    issue = {
                        "type": "equality_vs_inequality",
                        "description": (
                            f"{item_b['skill']} requires {pb['entity_type']}.{pb['property']} == '{pb['value']}' "
                            f"but {item_a['skill']} forbids it (!= '{pa['value']}')"
                        ),
                    }

                # Case 2: Both require equality but to different values
                elif pa["operator"] == "==" and pb["operator"] == "==" and pa["value"] != pb["value"]:
                    issue = {
                        "type": "contradictory_equality",
                        "description": (
                            f"{item_a['skill']} requires {pa['entity_type']}.{pa['property']} == '{pa['value']}' "
                            f"but {item_b['skill']} requires == '{pb['value']}'"
                        ),
                    }

                if issue:
                    issue["skill_a"] = item_a["skill"]
                    issue["skill_b"] = item_b["skill"]
                    issue["postcondition_a"] = item_a["raw"]
                    issue["postcondition_b"] = item_b["raw"]
                    issue["field"] = f"{pa['entity_type']}.{pa['property']}"
                    incompatibilities.append(issue)

    return incompatibilities

def main():
    skills_directory = os.path.expanduser(os.environ.get("_SKILLS_DIR", "~/.openclaw/skills"))
    use_json = os.environ.get("_JSON_OUTPUT", "false") == "true"

    contracts = load_skill_contracts(skills_directory)
    if not contracts:
        result = {"conflicts": [], "skills_checked": 0, "message": "no skills with ontology contracts found"}
        if use_json:
            print(json.dumps(result, indent=2))
        else:
            print("No skills with ontology contracts found")
        sys.exit(0)

    issues = find_incompatibilities(contracts)

    # Check reads/writes compatibility (informational, not a conflict)
    compatible_pairs = []
    for name_x, contract_x in contracts.items():
        for name_y, contract_y in contracts.items():
            if name_x >= name_y:
                continue
            writes_x = set(contract_x.get("ontology", {}).get("writes", []))
            reads_y = set(contract_y.get("ontology", {}).get("reads", []))
            writes_y = set(contract_y.get("ontology", {}).get("writes", []))
            reads_x = set(contract_x.get("ontology", {}).get("reads", []))
            overlap = (writes_x & reads_y) | (writes_y & reads_x)
            if overlap:
                compatible_pairs.append({
                    "skill_a": name_x,
                    "skill_b": name_y,
                    "shared_types": sorted(overlap),
                })

    result = {
        "conflicts": issues,
        "conflicts_found": len(issues),
        "skills_checked": len(contracts),
        "skills": sorted(contracts.keys()),
        "compatible_pairs": compatible_pairs,
    }

    if use_json:
        print(json.dumps(result, indent=2))
    else:
        print(f"Checked {len(contracts)} skill(s): {', '.join(sorted(contracts.keys()))}")
        print()
        if issues:
            print(f"CONFLICTS FOUND: {len(issues)}")
            for issue in issues:
                print(f"  * [{issue['type']}] {issue['description']}")
                print(f"    {issue['skill_a']}: {issue['postcondition_a']}")
                print(f"    {issue['skill_b']}: {issue['postcondition_b']}")
                print()
        else:
            print("No conflicts detected")

        if compatible_pairs:
            print()
            print("Compatible read/write pairs:")
            for pair in compatible_pairs:
                print(f"  {pair['skill_a']} <-> {pair['skill_b']}: {', '.join(pair['shared_types'])}")

    sys.exit(1 if issues else 0)

if __name__ == "__main__":
    main()

