# Modified version of the test suite with Type I clone transformations
from __future__ import annotations
import ast
import pytest
import skylos.rules.danger.danger_web.xss_flow as xss

def _locate_violation(findings, rule_code):
    for item in findings:
        if item.get("rule_id") == rule_code:
            return True
    return False

def test_qualified_name_from_call_simple():
    expr_node = ast.parse("foo(1)").body[0].value
    assert isinstance(expr_node, ast.Call)
    assert xss._qualified_name_from_call(expr_node) == "foo"

def test_qualified_name_from_call_chain():
    expr_node = ast.parse("a.b.c(1)").body[0].value
    assert isinstance(expr_node, ast.Call)
    assert xss._qualified_name_from_call(expr_node) == "a.b.c"

@pytest.mark.parametrize(
    "expression, expected",
    [
        ('f"hi {val}"', True),
        ('"a" + val', True),
        ('"<b>%s</b>" % val', True),
        ('"<b>{}</b>".format(val)', True),
        ('"plain"', False),
    ],
