# Modified version of IBootJBPatcher with renamed variables and reordered logic
from keystone import Ks, KS_ARCH_ARM64, KS_MODE_LITTLE_ENDIAN as KS_MODE_LE
from capstone.arm64_const import ARM64_OP_IMM, ARM64_OP_REG, ARM64_REG_W0
from .iboot import IBootPatcher, _disasm_one

_ks_engine = Ks(KS_ARCH_ARM64, KS_MODE_LE)

class IBootJBPatcher(IBootPatcher):
    """JB-only patcher for iBoot images."""

    def _assemble_at(self, asm_code, address):
        encoded, _ = _ks_engine.asm(asm_code, addr=address)
        if not encoded:
            raise RuntimeError(f"assembly failed at 0x{address:X}: {asm_code}")
        return bytes(encoded)

    def apply(self):
        self.applied_patches = []

        if self.mode == "ibss":
            self.patch_skip_generate_nonce()

        for offset, patch_bytes, _ in self.applied_patches:
            self.data[offset : offset + len(patch_bytes)] = patch_bytes

        if self.verbose and self.applied_patches:
            self._log(
                f"\n  [{len(self.applied_patches)} {self.mode.upper()} JB patches applied]"
            )

        return len(self.applied_patches)

    def _find_references_to_offset(self, target_offset):
        references = []
        for instruction_list in self._chunked_disasm():
            for idx in range(len(instruction_list) - 1):
                instr_a, instr_b = instruction_list[idx], instruction_list[idx + 1]

                # Check for adrp-add pair pattern
                if instr_a.mnemonic != "adrp" or instr_b.mnemonic != "add":
                    continue

                if len(instr_a.operands) < 2 or len(instr_b.operands) < 3:
                    continue

                if instr_a.operands[0].reg != instr_b.operands[1].reg:
                    continue

                if instr_a.operands[1].imm + instr_b.operands[2].imm == target_offset:
                    references.append((instr_a.address, instr_b.address, instr_b.operands[0].reg))

        return references

    def _find_string_references(self, search_string):
        if isinstance(search_string, str):
            search_string = search_string.encode()

        visited = set()
        found_refs = []
        current_offset = 0

        while True:
            string_pos = self.raw.find(search_string, current_offset)
            if string_pos < 0:
                break

            current_offset = string_pos + 1

            for ref in self._find_references_to_offset(string_pos):
                if ref[0] not in visited:
                    visited.add(ref[0])
                    found_refs.append(ref)

        return found_refs

    def patch_skip_generate_nonce(self):
        string_refs = self._find_string_references(b"boot-nonce")

        if not string_refs:
            self._log("  [-] iBSS JB: no references to 'boot-nonce' found")
            return False

        for _, add_instruction_offset, _ in string_refs:
            # Scan forward from the add instruction
            for scan_position in range(add_instruction_offset, min(add_instruction_offset + 0x100, self.size - 12), 4):
                inst0 = _disasm_one(self.raw, scan_position)
                inst1 = _disasm_one(self.raw, scan_position + 4)
                inst2 = _disasm_one(self.raw, scan_position + 8)

                if not inst0 or not inst1 or not inst2:
                    continue

                # Check first instruction is tbz/tbnz
                if inst0.mnemonic not in ("tbz", "tbnz"):
                    continue

                if len(inst0.operands) < 3:
                    continue

                # Verify operand checks
                if not (
                    inst0.operands[0].type == ARM64_OP_REG
                    and inst0.operands[0].reg == ARM64_REG_W0
                ):
                    continue

                if not (
                    inst0.operands[1].type == ARM64_OP_IMM 
                    and inst0.operands[1].imm == 0
                ):
                    continue

                # Check second instruction is mov w0, #0
                if inst1.mnemonic != "mov" or inst1.op_str != "w0, #0":
                    continue

                # Check third instruction is bl
                if inst2.mnemonic != "bl":
                    continue

                # Found matching pattern - patch it
                branch_target = inst0.operands[2].imm
                self.emit(
                    scan_position,
                    self._assemble_at(f"b #0x{branch_target:X}", scan_position),
                    "JB: skip generate_nonce",
                )
                return True

        self._log("  [-] iBSS JB: generate_nonce branch pattern not detected")
        return False

# Initialize default hook storage
def setup_default_hooks():
