# NOTE: response is currently the sole supported type
def trigger_hook(hook_key, registered_hooks, data, **options):
    """Applies a set of hooks to provided data."""
    registered_hooks = registered_hooks or {}
    registered_hooks = registered_hooks.get(hook_key)
    if registered_hooks:
        if callable(registered_hooks):
            registered_hooks = [registered_hooks]
        for hook_func in registered_hooks:
            updated_data = hook_func(data, **options)
            if updated_data is not None:
                data = updated_data
    return data

