# Apply chunk loss functionality to model modules
import logging
import types
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.distributed.tensor import DTensor

_logger = logging.getLogger(__name__)

def create_chunkloss_forward_function():
    def chunkloss_forward_impl(self, input_features: torch.Tensor, criterion_func: callable):
        # Convert distributed tensor weights/biases to local tensors if needed
        if isinstance(self.weight, DTensor):
            weight_local = self.weight.to_local()
            if self.bias is not None:
                if not isinstance(self.bias, DTensor):
                    raise TypeError(
                        f"Expected bias to be a DTensor when weight is a DTensor, "
                        f"but got bias of type {type(self.bias)}."
                    )
                bias_local = self.bias.to_local()
            else:
                bias_local = None
        else:
            weight_local = self.weight
            bias_local = self.bias

        loss_value = criterion_func(input_features, weight_local, bias_local)
        return loss_value

    return chunkloss_forward_impl

def patch_module_with_chunkloss(target_module):
    chunkloss_forward_method = create_chunkloss_forward_function()
    target_module.forward = types.MethodType(chunkloss_forward_method, target_module)

def retrieve_chunkloss_target_module(model_modules, configuration_plan):
    target_module_name = configuration_plan.apply_module
    selected_module = getattr(model_modules, target_module_name, None)

    if selected_module is None:
        raise ValueError(f"{target_module_name} does not exist, please specify correct module name for chunk loss.")

    if not isinstance(selected_module, torch.nn.Linear):
        raise ValueError(f"Chunk loss setup error for module '{selected_module}': "
                         f"expected torch.nn.Linear, but received {repr(type(selected_module))}. ")

    return selected_module

import random
import torch

class CogVideoXI2VProcessor:
    """
    The I2V Processor of CogVideoX:
    1. add noise to first frame
    2. encode the first frame
    3. random dropout image latent
    Args:
        config (dict): the processor config
        {
            "noised_image_all_concat": False,
            "noised_image_dropout": 0.05,
            "noised_image_input": True
        }
    """
    def __init__(self, settings):
        self.noised_image_all_concat = settings.get("noised_image_all_concat", False)
        self.noised_image_dropout = settings.get("noised_image_dropout", 0.05)
        self.noised_image_input = settings.get("noised_image_input", True)

    @staticmethod
    def inject_noise_into_frame(frame):
        sigma = torch.normal(mean=-3.0, std=0.5, size=(frame.shape[0],)).to(frame.device)
        sigma = torch.exp(sigma).to(frame.dtype)
        noise_tensor = torch.randn_like(frame) * sigma[:, None, None, None, None]
        frame = frame + noise_tensor
        return frame

    def __call__(self, encoder_model, videos, video_latents, images=None, **kwargs):
        if images is None:
            images = videos[:, 0:1]
        images = images.to(videos.dtype)

        if random.random() < self.noised_image_dropout:
            image_latents = torch.zeros_like(video_latents)
        else:
            if self.noised_image_input:
                images = self.inject_noise_into_frame(images)
            image_latents = encoder_model.encode(images, enable_cp=False)

            if self.noised_image_all_concat:
                image_latents = image_latents.repeat(1, 1, video_latents.size(2), 1, 1)
            else:
                image_latents = torch.cat(
                    [
                        image_latents,
                        torch.zeros_like(video_latents[:, :, 1:])
                    ],
                    dim=2
                )

        return {"masked_video": image_latents}

# Script to manage allowed users (admins and vendors) in a JSON file
import json
import sys
import os

# Determine the directory path for the skill and users file
SKILL_PATH = os.path.dirname(os.path.dirname(__file__))
USERS_DATA_FILE = os.path.join(SKILL_PATH, 'data', 'allowed_users.json')

def load_user_data():
    with open(USERS_DATA_FILE, 'r') as file:
        return json.load(file)

def save_user_data(data):
    with open(USERS_DATA_FILE, 'w') as file:
        json.dump(data, file, indent=2)

def promote_to_admin(user_id):
    data = load_user_data()
    if 'admins' not in data:
        data['admins'] = []
    if user_id in data['admins']:
        print('user already has admin privileges')
        return
    data['admins'].append(user_id)
    save_user_data(data)
    print('admin role assigned to', user_id)

def promote_to_vendor(user_id):
    data = load_user_data()
    if 'vendors' not in data:
        data['vendors'] = []
    if user_id in data['vendors']:
        print('user already has vendor status')
        return
    data['vendors'].append(user_id)
    save_user_data(data)
    print('vendor role assigned to', user_id)

def display_all_users():
    data = load_user_data()
    print(json.dumps(data, indent=2))

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: manage_users.py add-admin <id> | add-vendor <id> | list')
        sys.exit(1)

    command = sys.argv[1]
    if command == 'add-admin':
        promote_to_admin(sys.argv[2])
    elif command == 'add-vendor':
        promote_to_vendor(sys.argv[2])
    elif command == 'list':
        display_all_users()
    else:
        print('unknown command')

