# Type I Clone - Renamed variables, changed literals, reordered statements
import os
import yaml
import re
import glob
from pathlib import Path
from collections import defaultdict

class DBTResourceExtractor:
    def __init__(self, project_path):
        self.project_path = Path(project_path)
        self.items = {
            'metrics': [],
            'models': [],
            'sources': [],
            'seeds': [],
            'macros': [],
            'tests': [],
            'exposures': []
        }
        # Store column metadata in a dictionary
        self.column_metadata = defaultdict(list)
        self.documentations = defaultdict(str)

    def gather_all_resources(self):
        """Gather all resources from the dbt project without executing dbt"""
        self._process_yaml_documents()
        self._analyze_sql_models()
        self._locate_macros()
        self._discover_seeds()

        # Normalize paths relative to project root
        for item_category in self.items:
            for item in self.items[item_category]:
                if 'location' in item and isinstance(item['location'], str):
                    try:
                        full_path = Path(item['location']).resolve()
                        relative_location = full_path.relative_to(self.project_path.resolve())
                        item['location'] = str(relative_location)
                    except ValueError:
                        # If path is outside project_path, retain original (or log warning)
                        pass 
        return self.items, self.column_metadata, self.documentations

    def _process_yaml_documents(self):
        """Process all YAML files to identify metrics, sources, and other YAML-defined elements"""
        yaml_files = list(self.project_path.glob('**/*.yml')) + list(self.project_path.glob('**/*.yaml'))

        for y_file in yaml_files:
            try:
                with open(y_file, 'r') as stream:
                    yaml_data = yaml.safe_load(stream)

                if not yaml_data:
                    continue

                # Handle case where yaml_data is a string instead of a dictionary
                if isinstance(yaml_data, str):
                    print(f"Notice: YAML file {y_file} contains a string rather than a dictionary")
                    continue

                # Skip processing dbt_project.yml differently
                if y_file.name == 'dbt_project.yml':
                    print(f"Handling dbt_project.yml with specific logic")
                    # You could extract project-level information here if needed
                    continue

                # Process metrics
                if 'metrics' in yaml_data:
                    for metric in yaml_data['metrics']:
                        # Verify metric is a dictionary before accessing its attributes
                        if not isinstance(metric, dict):
                            print(f"Notice: Metric in {y_file} is not a dictionary: {metric}")
                            continue

                        metric_id = metric.get('name', '')

                        # Capture all useful metric details
                        metric_entry = {
                            'name': metric_id,
                            'location': str(y_file),
                            'kind': 'metric',
                            'summary': metric.get('description', ''),
                            'title': metric.get('label', ''),
