    def _analyze_sql_models(self):
        """Analyze SQL files to locate models"""
        sql_files = list(self.project_path.glob('models/**/*.sql'))

        for sql_file in sql_files:
            model_id = sql_file.stem
            sql_body = self._retrieve_sql_body(sql_file)

            # Find existing model in items
            existing_model = next(
                (m for m in self.items['models'] if m['name'] == model_id),
                None
            )

            if existing_model:
                # Update existing model with SQL content
                existing_model['sql_body'] = sql_body
            else:
                # If not found in YAML, add from SQL file
                description = self._extract_sql_summary(sql_file)
                self.items['models'].append({
                    'name': model_id,
                    'location': str(sql_file),
                    'kind': 'model_sql',
                    'summary': description,
                    'sql_body': sql_body
                })

                # Save documentation for this model
                if description:
                    self.documentations[f"model.{model_id}"] = description
            # Check for tests in SQL files (singular tests)
            if 'tests' in str(sql_file) and not any(t['name'] == model_id for t in self.items['tests']):
                description = self._extract_sql_summary(sql_file)
                self.items['tests'].append({
                    'name': model_id,
                    'location': str(sql_file),
                    'kind': 'singular_test',
                    'summary': description,
                    'sql_body': self._retrieve_sql_body(sql_file)
                })
        return self.items
    def _retrieve_sql_body(self, sql_file):
        """Retrieve the SQL body from a file"""
        try:
            with open(sql_file, 'r') as f:
                return f.read()
        except:
            return ''

    def _extract_sql_summary(self, sql_file):
        """Extract summary from SQL file comments if available"""
        try:
            with open(sql_file, 'r') as f:
                content = f.read()

            # Look for summary in SQL comments
            comment_match = re.search(r'/\*\*(.*?)\*/', content, re.DOTALL)
            if comment_match:
                return comment_match.group(1).strip()
            return ''
        except:
            return ''

    def _locate_macros(self):
        """Locate all macros in the project"""
        macro_files = list(self.project_path.glob('macros/**/*.sql'))

        for macro_file in macro_files:
            try:
                with open(macro_file, 'r') as f:
                    content = f.read()

                # Extract macro names using regex
                macro_matches = re.findall(r'{%-?\s*macro\s+([a-zA-Z0-9_]+)', content)

                for macro_id in macro_matches:
                    self.items['macros'].append({
                        'name': macro_id,
                        'location': str(macro_file),
                        'kind': 'macro',
                        'sql_body': content,  # Store raw file content
                    })
            except Exception as error:
                print(f"Issue processing macro {macro_file}: {error}")

    def _discover_seeds(self):
        """Discover all seed files"""
        seed_files = list(self.project_path.glob('seeds/**/*.csv'))

        for seed_file in seed_files:
            self.items['seeds'].append({
                'name': seed_file.stem,
                'location': str(seed_file),
                'kind': 'seed'
            })

    def get_overview(self):
        """Get an overview of all resources discovered"""
        overview = {}
        for item_category, entries in self.items.items():
            overview[item_category] = len(entries)
        return overview

    def export_to_csv(self, output_file):
        """Export all resources to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource Type', 'Name', 'Location', 'Description', 'Extra Info'])

            for item_category, entries in self.items.items():
                for entry in entries:
                    # Prepare extra info as a string
                    extra_info = {}
                    for key, value in entry.items():
                        if key not in ['name', 'location', 'kind', 'summary']:
                            extra_info[key] = value

                    writer.writerow([
                        item_category,
                        entry.get('name', ''),
                        entry.get('location', ''),
                        entry.get('summary', ''),
                        str(extra_info) if extra_info else ''
                    ])

    def export_fields_to_csv(self, output_file):
        """Export all fields to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource', 'Field Name', 'Summary', 'Data Type', 'Validations', 'Metadata'])

            for resource, fields in self.column_metadata.items():
                for field in fields:
                    writer.writerow([
                        resource,
                        field.get('name', ''),
                        field.get('summary', ''),
                        field.get('data_type', ''),
                        str(field.get('validations', [])),
                        str(field.get('metadata', {}))
                    ])

    def export_documentation_to_csv(self, output_file):
        """Export all documentation to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource', 'Documentation'])

            for resource, doc in self.documentations.items():
                writer.writerow([resource, doc])

import re
from datetime import datetime, timedelta
from dateutil import parser as dateutil_parser
from dateutil.relativedelta import relativedelta

# Common prefixes used by financial institutions in transaction descriptions
CLEANUP_PREFIXES = [
    r"^POS\s+(DEBIT\s+)?",
    r"^DEBIT\s+(CARD\s+)?(PURCHASE\s+)?",
    r"^ACH\s+(DEBIT\s+|CREDIT\s+)?",
    r"^CHECKCARD\s+\d+\s+",
    r"^PURCHASE\s+(AUTHORIZED\s+ON\s+)?",
    r"^RECURRING\s+(DEBIT\s+|PAYMENT\s+)?",
    r"^VISA\s+DDA\s+",
    r"^PENDING\s+",
    r"^ELECTRONIC\s+",
    r"^ONLINE\s+(BANKING\s+)?(PAYMENT\s+|TRANSFER\s+)?",
    r"^WIRE\s+(TRANSFER\s+)?",
    r"^BILL\s+PAY(MENT)?\s+",
    r"^AUTOPAY\s+",
    r"^MOBILE\s+(PURCHASE\s+)?",
    r"^SQ\s+\*",
    r"^TST\s+\*",
    r"^SP\s+\*?\s*",
]

# Suffixes to remove (dates, card numbers, reference IDs)
CLEANUP_SUFFIXES = [
    r"\s+\d{2}/\d{2}$",
    r"\s+\d{2}/\d{2}/\d{2,4}$",
    r"\s+\d{4,}$",
    r"\s+#\d+$",
    r"\s+REF\s*#?\s*\d+$",
    r"\s+CARD\s+\d+$",
    r"\s+X{2,}\d{4}$",
    r"\s+\d{2}:\d{2}:\d{2}$",
    r"\s+[A-Z]{2}\s+\d{5}(-\d{4})?$",  # state + zip
]

def sanitize_merchant_name(description):
    if not description:
        return ""
    name = description.strip().upper()
    for prefix in CLEANUP_PREFIXES:
        name = re.sub(prefix, "", name, flags=re.IGNORECASE).strip()
    for suffix in CLEANUP_SUFFIXES:
        name = re.sub(suffix, "", name, flags=re.IGNORECASE).strip()
    # Normalize whitespace
    name = re.sub(r"\s+", " ", name)
    # Convert to title case for better readability
    name = name.title()
    return name

def normalize_date(date_str):
    if not date_str:
        return None
    date_str = str(date_str).strip()
    # Standard date formats used by banks
    date_formats = [
        "%m/%d/%Y",
        "%m/%d/%y",
        "%Y-%m-%d",
        "%m-%d-%Y",
        "%m-%d-%y",
        "%d/%m/%Y",
        "%Y%m%d",
        "%m/%d/%Y %H:%M:%S",
        "%Y-%m-%dT%H:%M:%S",
    ]
    for fmt in date_formats:
        try:
            return datetime.strptime(date_str, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    # Fallback using dateutil parser
    try:
        return dateutil_parser.parse(date_str).strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return None

def standardize_amount(amount_str):
    if amount_str is None:
        return None
    if isinstance(amount_str, (int, float)):
        return round(float(amount_str), 2)
    s = str(amount_str).strip()
    s = s.replace("$", "").replace(",", "").strip()
    # Handle accounting-style negative values (parentheses)
    if s.startswith("(") and s.endswith(")"):
        s = "-" + s[1:-1]
    try:
        return round(float(s), 2)
    except ValueError:
        return None

def format_monetary_value(amount):
    if amount is None:
        return "$0.00"
    if amount < 0:
        return f"-${abs(amount):,.2f}"
    return f"${amount:,.2f}"

def interpret_time_reference(text):
    """Convert natural language time expressions into (start_date, end_date) tuples."""
    current_date = datetime.now()
    text = text.lower().strip()

    if text in ("this month", "current month"):
        start = current_date.replace(day=1)
        end = (start + relativedelta(months=1)) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    if text in ("last month", "previous month"):
        start = (current_date.replace(day=1) - relativedelta(months=1))
        end = current_date.replace(day=1) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    if text in ("this year", "current year", "ytd"):
        start = current_date.replace(month=1, day=1)
        return start.strftime("%Y-%m-%d"), current_date.strftime("%Y-%m-%d")

    if text in ("last year", "previous year"):
        start = current_date.replace(year=current_date.year - 1, month=1, day=1)
        end = current_date.replace(year=current_date.year - 1, month=12, day=31)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    if text in ("this week", "current week"):
        start = current_date - timedelta(days=current_date.weekday())
        end = start + timedelta(days=6)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    if text in ("last week", "previous week"):
        start = current_date - timedelta(days=current_date.weekday() + 7)
        end = start + timedelta(days=6)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    if text == "today":
        d = current_date.strftime("%Y-%m-%d")
        return d, d

    if text == "yesterday":
        d = (current_date - timedelta(days=1)).strftime("%Y-%m-%d")
        return d, d

    # Handle relative time periods like "last N days/weeks/months"
    m = re.match(r"last\s+(\d+)\s+(day|week|month|year)s?", text)
    if m:
        n = int(m.group(1))
        unit = m.group(2)
        if unit == "day":
            start = current_date - timedelta(days=n)
        elif unit == "week":
            start = current_date - timedelta(weeks=n)
        elif unit == "month":
            start = current_date - relativedelta(months=n)
        elif unit == "year":
            start = current_date - relativedelta(years=n)
        return start.strftime("%Y-%m-%d"), current_date.strftime("%Y-%m-%d")

    # Handle month names with optional year: "january", "february 2024", etc.
    month_mapping = {
        "january": 1, "february": 2, "march": 3, "april": 4,
        "may": 5, "june": 6, "july": 7, "august": 8,
        "september": 9, "october": 10, "november": 11, "december": 12,
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "jun": 6, "jul": 7, "aug": 8, "sep": 9, "sept": 9,
        "oct": 10, "nov": 11, "dec": 12,
    }
    m = re.match(r"(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)(?:\s+(\d{4}))?", text)
    if m:
        month = month_mapping[m.group(1)]
        year = int(m.group(2)) if m.group(2) else current_date.year
        start = datetime(year, month, 1)
        end = (start + relativedelta(months=1)) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Handle explicit date ranges: "2024-01-01 to 2024-01-31"
    m = re.match(r"(\d{4}-\d{2}-\d{2})\s+to\s+(\d{4}-\d{2}-\d{2})", text)
    if m:
        return m.group(1), m.group(2)

    return None, None

