def create_navit_attention_masks(
    batch_size: int,
    original_context_length_list: list,
    history_context_length: int,
    encoder_hidden_states_seq_len: int,
    device: torch.device,
    restrict_self_attn: bool = False,
    guidance_cross_attn: bool = False,
):
    # For navit_hidden_attention_mask
    if restrict_self_attn:
        cum_seqlens_q = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cum_seqlens_q.append(cum_seqlens_q[-1] + length)
        cum_seqlens_q = torch.tensor(cum_seqlens_q, device=device, dtype=torch.int32)
        max_seqlen_q = max(original_context_length_list)
        cum_seqlens_kv = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cum_seqlens_kv.append(cum_seqlens_kv[-1] + length + history_context_length)
        cum_seqlens_kv = torch.tensor(cum_seqlens_kv, device=device, dtype=torch.int32)
        max_seqlen_kv = max(original_context_length_list) + history_context_length
    else:
        cum_seqlens_kv = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cum_seqlens_kv.append(cum_seqlens_kv[-1] + length + history_context_length)
        cum_seqlens_kv = torch.tensor(cum_seqlens_kv, device=device, dtype=torch.int32)
        max_seqlen_kv = max(original_context_length_list) + history_context_length
        cum_seqlens_q = cum_seqlens_kv
        max_seqlen_q = max_seqlen_kv

    navit_hidden_attention_mask = (cum_seqlens_q, cum_seqlens_kv, max_seqlen_q, max_seqlen_kv)

    # For navit_history_hidden_attention_mask
    navit_history_hidden_attention_mask = None
    if restrict_self_attn:
        cum_seqlens_kv = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cum_seqlens_kv.append(cum_seqlens_kv[-1] + history_context_length)
        cum_seqlens_kv = torch.tensor(cum_seqlens_kv, device=device, dtype=torch.int32)
        max_seqlen_kv = history_context_length
        cum_seqlens_q = cum_seqlens_kv
        max_seqlen_q = max_seqlen_kv
        navit_history_hidden_attention_mask = (cum_seqlens_q, cum_seqlens_kv, max_seqlen_q, max_seqlen_kv)

    # For navit_encoder_attention_mask
    if guidance_cross_attn:
        cross_cum_seqlens_q = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cross_cum_seqlens_q.append(cross_cum_seqlens_q[-1] + length)
        cross_cum_seqlens_q = torch.tensor(cross_cum_seqlens_q, device=device, dtype=torch.int32)
        cross_max_seqlen_q = max(original_context_length_list)
    else:
        cross_cum_seqlens_q = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cross_cum_seqlens_q.append(cross_cum_seqlens_q[-1] + length + history_context_length)
        cross_cum_seqlens_q = torch.tensor(cross_cum_seqlens_q, device=device, dtype=torch.int32)
        cross_cum_seqlens_q[0] = 0
        cross_max_seqlen_q = max(original_context_length_list) + history_context_length

    cum_seqlens_kv = [0]
    for _ in range(batch_size):
        for length in original_context_length_list:
            cum_seqlens_kv.append(cum_seqlens_kv[-1] + encoder_hidden_states_seq_len)
    cum_seqlens_kv = torch.tensor(cum_seqlens_kv, device=device, dtype=torch.int32)
    max_seqlen_kv = encoder_hidden_states_seq_len

    navit_encoder_attention_mask = (cross_cum_seqlens_q, cum_seqlens_kv, cross_max_seqlen_q, max_seqlen_kv)
    return navit_hidden_attention_mask, navit_encoder_attention_mask, navit_history_hidden_attention_mask

@torch.compiler.disable
def _flash_attn_wrapper(q, k, v):
    return flash_attn_func(q, k, v)

@torch.compiler.disable
def _flash_attn_varlen_wrapper(q, k, v, cu_seqlens_q, cu_seqlens_kv, max_seqlen_q, max_seqlen_kv):
    return flash_attn_varlen_func(q, k, v, cu_seqlens_q, cu_seqlens_kv, max_seqlen_q, max_seqlen_kv)

def attn_varlen_func(q, k, v, attention_mask=None):
    if attention_mask is None:
        if flash_attn_func is not None:
            output = _flash_attn_wrapper(q, k, v)
            return output
        if sageattn is not None:
            output = sageattn(q, k, v, tensor_layout="NHD")
            return output
        if xformers_attn_func is not None:
            output = xformers_attn_func(q, k, v)
            return output
        output = torch.nn.functional.scaled_dot_product_attention(
            q.transpose(1, 2), k.transpose(1, 2), v.transpose(1, 2)
        ).transpose(1, 2)
        return output

    B, L, H, C = q.shape
    q_flat = q.flatten(0, 1)
    k_flat = k.flatten(0, 1)
    v_flat = v.flatten(0, 1)
    cu_seqlens_q, cu_seqlens_kv, max_seqlen_q, max_seqlen_kv = attention_mask

    if flash_attn_varlen_func is not None:
        output = _flash_attn_varlen_wrapper(q_flat, k_flat, v_flat, cu_seqlens_q, cu_seqlens_kv, max_seqlen_q, max_seqlen_kv)
    elif sageattn_varlen is not None:
        output = sageattn_varlen(q_flat, k_flat, v_flat, cu_seqlens_q, cu_seqlens_kv, max_seqlen_q, max_seqlen_kv)
    else:
        raise NotImplementedError("No Attn Installed!")

    output = output.unflatten(0, (B, L))
    return output

