class IdeficsImageProcessingTester(unittest.TestCase):
    def __init__(
        self,
        parent,
        batch_size=7,
        num_channels=3,
        image_size=18,
        min_resolution=30,
        max_resolution=400,
        size=None,
        image_mean=[0.48145466, 0.4578275, 0.40821073],
        image_std=[0.26862954, 0.26130258, 0.27577711],
    ):
        size = size if size is not None else {"shortest_edge": 30}
        self.parent = parent
        self.batch_size = batch_size
        self.num_channels = num_channels
        self.image_size = image_size
        self.min_resolution = min_resolution
        self.max_resolution = max_resolution
        self.image_mean = image_mean
        self.image_std = image_std

    def prepare_image_processor_dict(self):
        return {
            "image_mean": self.image_mean,
            "image_std": self.image_std,
            "image_size": self.image_size,
        }

    def get_expected_values(self, image_inputs, batched=False):
        """
        Computes expected output dimensions after preprocessing images with IdeficsImageProcessor.
        Assumes resizing with scalar size and size_divisor.
        """
        if not batched:
            target_size = self.image_size
            image = image_inputs[0]
            if isinstance(image, Image.Image):
                w, h = image.size
            elif isinstance(image, np.ndarray):
                h, w = image.shape[0], image.shape[1]
            else:
                h, w = image.shape[1], image.shape[2]

            scale_factor = target_size / min(w, h)
            if h < w:
                new_height, new_width = target_size, scale_factor * w
            else:
                new_height, new_width = scale_factor * h, target_size

            max_dimension = int((1333 / 800) * target_size)
            if max(new_height, new_width) > max_dimension:
                scale_factor = max_dimension / max(new_height, new_width)
                new_height *= scale_factor
                new_width *= scale_factor

            new_height = int(new_height + 0.5)
            new_width = int(new_width + 0.5)

            # Apply size divisor rounding
            divisor = getattr(self, 'size_divisor', 1)
            expected_height = (new_height // divisor) * divisor
            expected_width = (new_width // divisor) * divisor
        else:
            dimension_list = []
            for img in image_inputs:
                h, w = self.get_expected_values([img])
                dimension_list.append((h, w))

            max_height = max(dimension_list, key=lambda x: x[0])[0]
            max_width = max(dimension_list, key=lambda x: x[1])[1]
            expected_height, expected_width = max_height, max_width

        return expected_height, expected_width

    def expected_output_image_shape(self, images):
        height, width = self.get_expected_values(images, batched=True)
        return (self.num_channels, height, width)

    def prepare_image_inputs(self, equal_resolution=False, numpify=False, torchify=False):
        return prepare_image_inputs(
            batch_size=self.batch_size,
            num_channels=self.num_channels,
            min_resolution=self.min_resolution,
            max_resolution=self.max_resolution,
            equal_resolution=equal_resolution,
            numpify=numpify,
            torchify=torchify,
        )


@require_torch
@require_vision
class IdeficsImageProcessingTest(ImageProcessingTestMixin, unittest.TestCase):
    image_processing_class = IdeficsImageProcessor if is_vision_available() else None

    def setUp(self):
        super().setUp()
        self.image_processor_tester = IdeficsImageProcessingTester(self)

    @property
    def image_processor_dict(self):
        return self.image_processor_tester.prepare_image_processor_dict()

    def test_image_processor_properties(self):
        processor = self.image_processing_class(**self.image_processor_dict)
        self.assertTrue(hasattr(processor, "image_mean"))
        self.assertTrue(hasattr(processor, "image_std"))
        self.assertTrue(hasattr(processor, "image_size"))

    def test_image_processor_from_dict_with_kwargs(self):
        base_processor = self.image_processing_class.from_dict(self.image_processor_dict)
        self.assertNotEqual(base_processor.image_size, 30)

        modified_processor = self.image_processing_class.from_dict(
            self.image_processor_dict, image_size=42
        )
        self.assertEqual(modified_processor.image_size, 42)

    @require_torchvision
    def test_torchvision_numpy_transforms_equivalency(self):
        # Verify custom implementation matches torchvision behavior
        image_inputs = self.image_processor_tester.prepare_image_inputs(equal_resolution=False)
        processor = self.image_processing_class(**self.image_processor_dict, return_tensors="pt")

        def convert_to_rgb(img):
            # Handle transparent images correctly
            if img.mode == "RGB":
                return img
            rgba_img = img.convert("RGBA")
            background = Image.new("RGBA", rgba_img.size, (255, 255, 255))
            composite = Image.alpha_composite(background, rgba_img)
            return composite.convert("RGB")

        target_size = processor.image_size
        mean_values = processor.image_mean
        std_values = processor.image_std

        custom_transform = transforms.Compose([
            convert_to_rgb,
            transforms.Resize((target_size, target_size), interpolation=transforms.InterpolationMode.BICUBIC),
            transforms.ToTensor(),
            transforms.Normalize(mean=mean_values, std=std_values),
        ])

        # Process with default transform
        result_default = processor(image_inputs, transform=None, return_tensors="pt")
        # Process with explicit transform
        result_custom = processor(image_inputs, transform=custom_transform, return_tensors="pt")

        torch.testing.assert_close(result_default, result_custom, rtol=0.0, atol=0.0)

