# Custom logger implementation for Primus training system
import os
import jax
import numpy as np
from MaxText import max_logging, max_utils, maxtext_utils
from MaxText.metric_logger import MetadataKey, MetricLogger
from .max_utils import close_wandb_writer, initialize_wandb_writer

class PrimusMetricLogger(MetricLogger):
    """
    Extended logger that supports saving metrics to local storage, Google Cloud Storage,
    TensorBoard, and Weights & Biases (WandB).
    """
    def __init__(self, hyperparams, lr_schedule):
        super().__init__(hyperparams, lr_schedule)
        self.wandb_instance = None
        if hyperparams.enable_wandb:
            self.wandb_instance = initialize_wandb_writer(hyperparams)

    def record_metrics(self, data_dict, current_step, train_mode=True):
        """Main entry point for logging all training/validation metrics."""
        super().record_metrics(data_dict, current_step, train_mode)
        if hyperparams.enable_wandb:
            self.log_to_wandb(data_dict, current_step, train_mode)

    def log_to_wandb(self, metrics_data, step_num, is_train):
        """Sends metric data to WandB service."""
        if jax.process_index() != 0 or self.wandb_instance is None:
            return

        wandb_log = {}
        # Process scalar metrics
        for key in metrics_data.get("scalar", []):
            wandb_log[key] = float(np.array(metrics_data["scalar"][key]))

        # Handle nested scalar collections
        for group_name in metrics_data.get("scalars", []):
            for sub_key, value in metrics_data["scalars"][group_name].items():
                wandb_log[f"{group_name}/{sub_key}"] = float(value)

        self.wandb_instance.log(wandb_log, step=step_num)

    def log_initialization_details(self, model_params):
        """Records setup information including configuration, parameter count, and XLA settings."""
        total_params = max_utils.count_parameters_from_pytree(model_params)
        self.metadata[MetadataKey.PER_DEVICE_TFLOPS], _, _ = (
            maxtext_utils.compute_tflops_per_device_for_training(self.config)
        )
        self.metadata[MetadataKey.PER_DEVICE_TOKENS] = maxtext_utils.compute_tokens_per_device(
            self.config
        )

        max_logging.log(f"total parameters: {total_params/1e9:.3f} billion")
        max_utils.write_text_summary("parameter_count", str(total_params), self.writer)
        max_utils.write_text_summary("libtpu_init_arguments", os.environ["LIBTPU_INIT_ARGS"], self.writer)
        maxtext_utils.append_config_to_summary_writer(self.config, self.writer)

        if self.wandb_instance is not None:
            self.wandb_instance.log({"parameter_count": total_params})

    def finalize_logging_and_cleanup(self):
        super().finalize_logging_and_cleanup()
        if hyperparams.enable_wandb:
            close_wandb_writer(self.wandb_instance)

# Django-based mounted accounts API with SSE and JSON endpoints
import asyncio
import time
from django.contrib.auth import authenticate, login as auth_login, logout as auth_logout
from django.http import JsonResponse, StreamingHttpResponse
from django.shortcuts import redirect
from django.urls import reverse
import test_data

async def main_page(request):
    return JsonResponse(test_data.JSON_1K, safe=False)

async def event_stream(request):
    """Server-Sent Events endpoint that sends timestamp data every second."""
    async def stream_generator():
        while True:
            await asyncio.sleep(1)
            yield f"data: {time.time()}\n\n"
    return StreamingHttpResponse(stream_generator(), content_type="text/event-stream")

def accounts_home(request):
    """Mounted Django accounts testing index."""
    base = reverse("accounts-index").rstrip("/")
    return JsonResponse(
        {
            "source": "django_mount",
            "message": "Mounted Django accounts test endpoints",
            "endpoints": {
                "login": reverse("accounts-login"),
                "logout": reverse("accounts-logout"),
                "profile": reverse("accounts-profile"),
                "provider_callback": f"{reverse('accounts-provider-callback')}?code=demo&state=xyz",
                "django_auth_urls": f"{base}/auth/",
                "allauth_if_installed": f"{base}/allauth/",
            },
        }
    )

def accounts_signin(request):
    """
    Minimal login endpoint for mounted-Django testing.
    POST form fields:
    - username
    - password
    - next (optional, default: /accounts/profile/)
    """
    if request.method == "GET":
        return JsonResponse(
            {
                "source": "django_mount",
                "action": "login",
                "method": "POST",
                "required_fields": ["username", "password"],
                "optional_fields": ["next"],
            }
        )

    username = request.POST.get("username") or request.GET.get("username")
    password = request.POST.get("password") or request.GET.get("password")
    redirect_url = request.POST.get("next") or request.GET.get("next") or reverse("accounts-profile")

    if not username or not password:
        return JsonResponse(
            {"ok": False, "error": "username and password are required"},
            status=400,
        )

    user = authenticate(request, username=username, password=password)
    if user is None:
        return JsonResponse({"ok": False, "error": "invalid credentials"}, status=401)

    auth_login(request, user)
    return redirect(redirect_url)

def accounts_signout(request):
    """Logout endpoint for mounted-Django testing."""
    auth_logout(request)
    return redirect(reverse("accounts-login"))

def accounts_dashboard(request):
    """Simple auth state endpoint for mounted-Django testing."""
    user = request.user
    is_signed_in = bool(getattr(user, "is_authenticated", False))
    return JsonResponse(
        {
            "source": "django_mount",
            "authenticated": is_signed_in,
            "username": user.get_username() if is_signed_in else None,
        }
    )

def accounts_oauth_callback(request):
    """
    Simulates an OAuth provider callback endpoint (allauth-style URL shape).
    Example:
    /accounts/provider/callback/?code=demo-code&state=demo-state
    """
    return JsonResponse(
        {
            "source": "django_mount",
            "action": "provider_callback",
            "query": dict(request.GET.items()),
        }
    )

import json
import sys
from pypdf import PdfReader

# Extracts data for the fillable form fields in a PDF and outputs JSON that
# Claude uses to fill the fields. See forms.md.
# This matches the format used by PdfReader `get_fields` and `update_page_form_field_values` methods.

def get_full_annotation_field_id(annotation):
    parts = []
    while annotation:
        field_name = annotation.get('/T')
        if field_name:
            parts.append(field_name)
        annotation = annotation.get('/Parent')
    return ".".join(reversed(parts)) if parts else None

def create_field_dict(field, field_identifier):
    field_dict = {"field_id": field_identifier}
    ft = field.get('/FT')
    if ft == "/Tx":
        field_dict["type"] = "text"
    elif ft == "/Btn":
        field_dict["type"] = "checkbox"  # radio groups handled separately
        states = field.get("/_States_", [])
        if len(states) == 2:
            # "/Off" seems to always be the unchecked value, as suggested by
            # https://opensource.adobe.com/dc-acrobat-sdk-docs/standards/pdfstandards/pdf/PDF32000_2008.pdf#page=448
            # It can be either first or second in the "/_States_" list.
            if "/Off" in states:
                field_dict["checked_value"] = states[0] if states[0] != "/Off" else states[1]
                field_dict["unchecked_value"] = "/Off"
            else:
                print(f"Unexpected state values for checkbox `${field_identifier}`. Its checked and unchecked values may not be correct; if you're trying to check it, visually verify the results.")
                field_dict["checked_value"] = states[0]
                field_dict["unchecked_value"] = states[1]
    elif ft == "/Ch":
        field_dict["type"] = "choice"
        states = field.get("/_States_", [])
        field_dict["choice_options"] = [{
            "value": state[0],
            "text": state[1],
        } for state in states]
    else:
        field_dict["type"] = f"unknown ({ft})"
    return field_dict

# Returns a list of fillable PDF fields:
# [
#   {
#     "field_id": "name",
#     "page": 1,
#     "type": ("text", "checkbox", "radio_group", or "choice")
#     // Per-type additional fields described in forms.md
#   },
# ]
def extract_field_info(reader: PdfReader):
    fields = reader.get_fields()
    field_map = {}
    potential_radio_names = set()

    for field_id, field in fields.items():
        # Skip if this is a container field with children, except that it might be
        # a parent group for radio button options.
        if field.get("/Kids"):
            if field.get("/FT") == "/Btn":
                potential_radio_names.add(field_id)
            continue
        field_map[field_id] = create_field_dict(field, field_id)

    # Bounding rects are stored in annotations in page objects.
    # Radio button options have a separate annotation for each choice;
    # all choices have the same field name.
    # See https://westhealth.github.io/exploring-fillable-forms-with-pdfrw.html
    radio_map = {}
    for page_index, page in enumerate(reader.pages):
        annotations = page.get('/Annots', [])
        for ann in annotations:
            field_id = get_full_annotation_field_id(ann)
            if field_id in field_map:
                field_map[field_id]["page"] = page_index + 1
                field_map[field_id]["rect"] = ann.get('/Rect')
            elif field_id in potential_radio_names:
                try:
                    # ann['/AP']['/N'] should have two items. One of them is '/Off',
                    # the other is the active value.
                    on_values = [v for v in ann["/AP"]["/N"] if v != "/Off"]
                except KeyError:
                    continue
                if len(on_values) == 1:
                    rect = ann.get("/Rect")
                    if field_id not in radio_map:
                        radio_map[field_id] = {
                            "field_id": field_id,
                            "type": "radio_group",
                            "page": page_index + 1,
                            "radio_options": [],
                        }
                    # Note: at least on macOS 15.7, Preview.app doesn't show selected
                    # radio buttons correctly. (It does if you remove the leading slash
                    # from the value, but that causes them not to appear correctly in
                    # Chrome/Firefox/Acrobat/etc).
                    radio_map[field_id]["radio_options"].append({
                        "value": on_values[0],
                        "rect": rect,
                    })

    # Some PDFs have form field definitions without corresponding annotations,
    # so we can't tell where they are. Ignore these fields for now.
    fields_with_location = []
    for field_info in field_map.values():
        if "page" in field_info:
            fields_with_location.append(field_info)
        else:
            print(f"Unable to determine location for field id: {field_info.get('field_id')}, ignoring")

    # Sort by page number, then Y position (flipped in PDF coordinate system), then X.
    def sort_function(f):
        if "radio_options" in f:
            rect = f["radio_options"][0]["rect"] or [0, 0, 0, 0]
        else:
            rect = f.get("rect") or [0, 0, 0, 0]
        adjusted_position = [-rect[1], rect[0]]
        return [f.get("page"), adjusted_position]

    sorted_fields = fields_with_location + list(radio_map.values())
    sorted_fields.sort(key=sort_function)
    return sorted_fields

def save_field_info(pdf_path: str, json_output_path: str):
    reader = PdfReader(pdf_path)
    field_info = extract_field_info(reader)
    with open(json_output_path, "w") as output_file:
        json.dump(field_info, output_file, indent=2)
    print(f"Wrote {len(field_info)} fields to {json_output_path}")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: extract_form_field_info.py [input pdf] [output json]")
        sys.exit(1)
    save_field_info(sys.argv[1], sys.argv[2])

# Modified version of the backup API routes with structural and naming changes
import logging
import os
from datetime import datetime
from flask import Blueprint, request, jsonify, redirect, send_file
from app.web import (
    require_auth, _auth_required,
    get_config_manager, get_on_config_changed,
    _get_client_ip,
)
from werkzeug.utils import secure_filename

audit_logger = logging.getLogger("docsis.audit")
web_logger = logging.getLogger("docsis.web")
backup_routes = Blueprint("backup_bp", __name__)

@backup_routes.route("/api/backup", methods=["POST"])
@require_auth
def download_backup():
    """Generate a backup archive and stream it for download."""
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify({"error": "Not initialized"}), 500

    try:
        from .backup import create_backup
        buffer = create_backup(config_mgr.data_dir)
        timestamp = datetime.now().strftime("%Y-%m-%d_%H%M%S")
        file_name = f"docsight_backup_{timestamp}.tar.gz"
        audit_logger.info("Backup downloaded: ip=%s", _get_client_ip())
        return send_file(buffer, mimetype="application/gzip", as_attachment=True, download_name=file_name)
    except Exception as err:
        web_logger.error("Backup creation failed: %s", err)
        return jsonify({"error": str(err)}), 500

@backup_routes.route("/api/backup/scheduled", methods=["POST"])
@require_auth
def scheduled_backup():
    """Create a backup file in the configured directory."""
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify({"error": "Not initialized"}), 500

    backup_dir = config_mgr.get("backup_path", "/backup")
    retention_count = config_mgr.get("backup_retention", 5)

    try:
        from .backup import create_backup_to_file, cleanup_old_backups
        output_file = create_backup_to_file(config_mgr.data_dir, backup_dir)
        cleanup_old_backups(backup_dir, keep=retention_count)
        audit_logger.info("Scheduled backup created: ip=%s file=%s", _get_client_ip(), output_file)
        return jsonify({"success": True, "filename": output_file})
    except Exception as err:
        web_logger.error("Scheduled backup failed: %s", err)
        return jsonify({"error": str(err)}), 500

@backup_routes.route("/api/backup/list")
@require_auth
def list_backups_endpoint():
    """Return a list of available backups."""
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify([])

    backup_dir = config_mgr.get("backup_path", "/backup")
    from .backup import list_backups
    return jsonify(list_backups(backup_dir))

@backup_routes.route("/api/backup/<filename>", methods=["DELETE"])
@require_auth
def delete_backup(filename):
    """Remove a specific backup file."""
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify({"error": "Not initialized"}), 500

    backup_dir = config_mgr.get("backup_path", "/backup")
    safe_name = secure_filename(filename)

    if not safe_name or safe_name != filename:
        return jsonify({"error": "Invalid filename"}), 400

    full_path = os.path.join(backup_dir, safe_name)
    resolved_path = os.path.realpath(full_path)
    resolved_backup_dir = os.path.realpath(backup_dir)

    if not resolved_path.startswith(resolved_backup_dir + os.sep):
        return jsonify({"error": "Invalid path"}), 400

    if not os.path.exists(resolved_path):
        return jsonify({"error": "Not found"}), 404

    os.remove(resolved_path)
    audit_logger.info("Backup deleted: ip=%s file=%s", _get_client_ip(), safe_name)
    return jsonify({"success": True})

@backup_routes.route("/api/restore/validate", methods=["POST"])
def validate_restore():
    """Validate a backup archive and extract metadata.
    No authentication required during initial setup (when not yet configured).
    Authentication required after configuration.
    """
    config_mgr = get_config_manager()
    if config_mgr and config_mgr.is_configured() and _auth_required():
        return redirect("/login")

    if "file" not in request.files:
        return jsonify({"error": "No file provided"}), 400

    uploaded_file = request.files["file"]
    if not uploaded_file.filename:
        return jsonify({"error": "No file selected"}), 400

    content = uploaded_file.read()
    max_size = 500 * 1024 * 1024  # 500 MB limit

    if len(content) > max_size:
        return jsonify({"error": "File too large"}), 400

    try:
        from .backup import validate_backup
        metadata = validate_backup(content)
        return jsonify({"valid": True, "meta": metadata})
    except ValueError as exc:
        return jsonify({"valid": False, "error": str(exc)}), 400

@backup_routes.route("/api/restore", methods=["POST"])
def perform_restore():
    """Restore system state from a backup archive.
    No authentication required during initial setup (when not yet configured).
    Authentication required after configuration.
    """
    config_mgr = get_config_manager()
    if config_mgr and config_mgr.is_configured() and _auth_required():
        return redirect("/login")

    if "file" not in request.files:
        return jsonify({"error": "No file provided"}), 400

    uploaded_file = request.files["file"]
    if not uploaded_file.filename:
        return jsonify({"error": "No file selected"}), 400

    content = uploaded_file.read()
    max_size = 500 * 1024 * 1024  # 500 MB limit

    if len(content) > max_size:
        return jsonify({"error": "File too large"}), 400

    try:
        from .backup import restore_backup
        target_dir = config_mgr.data_dir if config_mgr else "/data"
        result = restore_backup(content, target_dir)

        audit_logger.info(
            "Backup restored: ip=%s files=%s",
            _get_client_ip(), result["restored_files"],
        )

        # Reload configuration to reflect restored state
        if config_mgr:
            config_mgr._load()

        on_change_handler = get_on_config_changed()
        if on_change_handler:
            on_change_handler()

        is_configured = bool(config_mgr and config_mgr.is_configured())
        return jsonify({
            "success": True,
            "restored_files": result["restored_files"],
            "configured": is_configured,
        })
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400
    except Exception as err:
        web_logger.error("Restore failed: %s", err)
        return jsonify({"error": str(err)}), 500

@backup_routes.route("/api/browse")
@require_auth
def browse_server_dirs():
    """Allow browsing server directories for backup path selection."""
    requested_path = request.args.get("path", "/backup")
    try:
        from .backup import browse_directory
        result = browse_directory(requested_path)
        return jsonify(result)
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400

# Forex market utility functions
import datetime

def fetch_trading_symbol(exchange_name: str):
    if exchange_name == 'binance':
        return 'BTC-USDT'
    elif exchange_name == 'okx':
        return 'ADA-USDT'
    elif exchange_name == 'coinbase_pro':
        return 'BTC-USD'
    elif exchange_name == 'alpaca':
        return 'AAPL'
    elif exchange_name == 'oanda':
        return 'EUR-USD'
    elif exchange_name == 'ftx':
        return 'BTC-USD'
    elif exchange_name == 'kucoin':
        return 'ETH-USDT'
    else:
        raise LookupError("Specified exchange not found.")

def is_forex_market_active():
    current_time = datetime.datetime.now()
    # Friday == 4, Saturday == 5
    # Note: Market technically reopens at 5pm Sunday but this isn't handled here
    if current_time.weekday() >= 5:
        return False
    elif current_time.weekday() == 4 and current_time.hour >= 17:
        return False
    else:
        return True

