    return GymnasiumGym.vectorize("CartPole-v1", num_envs=3)

def _make_dummy_policy(env, base_policy):
    """Generate a dummy policy compatible with the environment's action specifications."""
    sample_action = env.sample_action()
    assert sample_action.ndim == 2
    act_shape = tuple(sample_action.shape[1:])
    act_dtype = sample_action.dtype
    act_upper_bound = 1 if act_dtype in (torch.int64, torch.int32) else None
    act_lower_bound = 0 if act_dtype in (torch.int64, torch.int32) else None
    return base_policy.create(
        action_shape=act_shape,
        action_dtype=act_dtype,
        action_max=act_upper_bound,
        action_min=act_lower_bound,
    )

class TestTrajectoryRollout:
    """Tests for trajectory generation with variable action dimensions."""

    @pytest.mark.parametrize(
        "env_name, policy_env_name",
        [
            ("pusht_env", "pusht_env"),
            ("cartpole_env", "cartpole_env"),
            ("vec_cartpole_env", "vec_cartpole_env"),
        ]
    )
    def test_rollout_runs_without_error(self, request, base_policy, env_name, policy_env_name):
