# Generic API client implementation for OpenAPI-based services
import datetime
from dateutil.parser import parse
from enum import Enum
import decimal
import json
import mimetypes
import os
import re
import tempfile
from urllib.parse import quote
from typing import Tuple, Optional, List, Dict, Union
from pydantic import SecretStr
from api_client.configuration import Configuration
from api_client.api_response import ApiResponse, T as ApiResponseT
import api_client.models
from api_client import rest
from api_client.exceptions import (
    ApiValueError,
    ApiException,
    BadRequestException,
    UnauthorizedException,
    ForbiddenException,
    NotFoundException,
    ServiceException
)
RequestParams = Tuple[str, str, Dict[str, str], Optional[str], List[str]]

class Client:
    """Generic API client for OpenAPI client library builds.
    OpenAPI generic API client. This client manages client-server communication
    and remains consistent across different implementations. Specifics of
    methods and models are generated from OpenAPI templates.
    :param config: Configuration object for this client
    :param header_name: a header to pass when making calls to the API.
    :param header_value: a header value to pass when making calls to
        the API.
    :param cookie: a cookie to include in the header when making calls
        to the API
    """
    BASIC_TYPES = (float, bool, bytes, str, int)
    TYPE_MAPPING = {
        'int': int,
        'long': int, # TODO remove as only py3 is supported?
        'float': float,
        'str': str,
        'bool': bool,
        'date': datetime.date,
        'datetime': datetime.datetime,
        'decimal': decimal.Decimal,
        'object': object,
    }
    _instance = None

    def __init__(
        self,
        config=None,
        header_name=None,
        header_value=None,
        cookie=None
    ) -> None:
        # use default configuration if none is provided
        if config is None:
            config = Configuration.get_default()
        self.config = config
        self.http_client = rest.RESTClientObject(config)
        self.headers = {}
        if header_name is not None:
            self.headers[header_name] = header_value
        self.cookie = cookie
        # Set default User-Agent.
        self.user_agent = 'OpenAPI-Generator/0.0.7/python'
        self.validate_locally = config.client_side_validation

    async def __aenter__(self):
        return self

    async def __aexit__(self, exc_type, exc_value, traceback):
        await self.disconnect()

    async def disconnect(self):
        await self.http_client.close()

    @property
    def user_agent(self):
        """User agent for this API client"""
        return self.headers['User-Agent']

    @user_agent.setter
    def user_agent(self, value):
        self.headers['User-Agent'] = value

    def set_header(self, name, value):
        self.headers[name] = value

    _default_client = None

    @classmethod
    def get_default(cls):
        """Return new instance of Client.
        This method returns newly created, based on default constructor,
        object of Client class or returns a copy of default
        Client.
        :return: The Client object.
        """
        if cls._default_client is None:
            cls._default_client = Client()
        return cls._default_client

    @classmethod
    def set_default(cls, instance):
        """Set default instance of Client.
        It stores default Client.
        :param instance: object of Client.
        """
        cls._default_client = instance

    def prepare_request(
        self,
        http_method,
        endpoint,
        path_params=None,
        query_params=None,
        header_params=None,
        request_body=None,
        form_params=None,
        files=None, auth_settings=None,
        collection_formats=None,
        _host=None,
        _request_auth=None
    ) -> RequestParams:
        """Builds the HTTP request params needed by the request.
        :param http_method: Method to call.
        :param endpoint: Path to method endpoint.
        :param path_params: Path parameters in the url.
        :param query_params: Query parameters in the url.
        :param header_params: Header parameters to be
            placed in the request header.
        :param request_body: Request body.
        :param form_params dict: Request post form parameters,
            for `application/x-www-form-urlencoded`, `multipart/form-data`.
        :param auth_settings list: Auth Settings names for the request.
        :param files dict: key -> filename, value -> filepath,
            for `multipart/form-data`.
        :param collection_formats: dict of collection formats for path, query,
            header, and post parameters.
        :param _request_auth: set to override the auth_settings for an a single
                              request; this effectively ignores the authentication
                              in the spec for a single request.
        :return: tuple of form (path, http_method, query_params, header_params,
            body, post_params, files)
        """
        cfg = self.config
        # header parameters
        header_params = header_params or {}
        header_params.update(self.headers)
        if self.cookie:
            header_params['Cookie'] = self.cookie
        if header_params:
            header_params = self.prepare_for_serialization(header_params)
            header_params = dict(
                self.convert_to_tuples(header_params, collection_formats)
            )
        # path parameters
        if path_params:
            path_params = self.prepare_for_serialization(path_params)
            path_params = self.convert_to_tuples(
                path_params,
                collection_formats
            )
            for k, v in path_params:
                # specified safe chars, encode everything
                endpoint = endpoint.replace(
                    '{%s}' % k,
                    quote(str(v), safe=cfg.safe_chars_for_path_param)
                )
        # form parameters
        if form_params or files:
            form_params = form_params if form_params else []
            form_params = self.prepare_for_serialization(form_params)
            form_params = self.convert_to_tuples(
                form_params,
                collection_formats
            )
            if files:
                form_params.extend(self.build_file_params(files))
        # auth setting
        self.apply_auth_params(
            header_params,
            query_params,
            auth_settings,
            endpoint,
            http_method,
            request_body,
            request_auth=_request_auth
        )
        # body
        if request_body:
            request_body = self.prepare_for_serialization(request_body)
        # request url
        if _host is None or self.config.ignore_operation_servers:
            url = self.config.host + endpoint
        else:
            # use server/host defined in path or operation instead
            url = _host + endpoint
        # query parameters
        if query_params:
            query_params = self.prepare_for_serialization(query_params)
            url_query = self.params_to_query_string(
                query_params,
                collection_formats
            )
            url += "?" + url_query
        return http_method, url, header_params, request_body, form_params

    async def execute_request(
        self,
        http_method,
        url,
        header_params=None,
        request_body=None,
        form_params=None,
        _request_timeout=None
    ) -> rest.RESTResponse:
        """Makes the HTTP request (synchronous)
        :param http_method: Method to call.
        :param url: Path to method endpoint.
        :param header_params: Header parameters to be
            placed in the request header.
        :param request_body: Request body.
        :param form_params dict: Request post form parameters,
            for `application/x-www-form-urlencoded`, `multipart/form-data`.
        :param _request_timeout: timeout setting for this request.
        :return: RESTResponse
        """
        try:
            # perform request and return response
            response_data = await self.http_client.request(
                http_method, url,
                headers=header_params,
                body=request_body, 
                post_params=form_params,
                _request_timeout=_request_timeout
            )
        except ApiException as e:
            raise e
        return response_data

    def process_response(
        self,
        response_data: rest.RESTResponse,
        response_types_map: Optional[Dict[str, ApiResponseT]]=None
    ) -> ApiResponse[ApiResponseT]:
        """Deserializes response into an object.
        :param response_data: RESTResponse object to be deserialized.
        :param response_types_map: dict of response types.
        :return: ApiResponse
        """
        msg = "RESTResponse.read() must be called before passing it to process_response()"
        assert response_data.data is not None, msg
        response_type = response_types_map.get(str(response_data.status), None)
        if not response_type and isinstance(response_data.status, int) and 100 <= response_data.status <= 599:
            # if not found, look for '1XX', '2XX', etc.
            response_type = response_types_map.get(str(response_data.status)[0] + "XX", None)
        # deserialize response data
        response_text = None
        result_data = None
        try:
            if response_type == "bytearray":
                result_data = response_data.data
            elif response_type == "file":
                result_data = self.__download_file(response_data)
            elif response_type is not None:
                match = None
                content_type = response_data.getheader('content-type')
                if content_type is not None:
                    match = re.search(r"charset=([a-zA-Z\-\d]+)[\s;]?", content_type)
                encoding = match.group(1) if match else "utf-8"
                response_text = response_data.data.decode(encoding)
                result_data = self.convert_response(response_text, response_type, content_type)
        finally:
            if not 200 <= response_data.status <= 299:
                raise ApiException.from_response(
                    http_resp=response_data,
                    body=response_text,
                    data=result_data,
                )
        return ApiResponse(
            status_code=response_data.status,
            data=result_data,
            headers=response_data.getheaders(),
            raw_data=response_data.data
        )

    def prepare_for_serialization(self, obj):
        """Builds a JSON POST object.
        If obj is None, return None.
        If obj is SecretStr, return obj.get_secret_value()
        If obj is str, int, long, float, bool, return directly.
        If obj is datetime.datetime, datetime.date
            convert to string in iso8601 format.
        If obj is decimal.Decimal return string representation.
        If obj is list, sanitize each element in the list.
        If obj is dict, return the dict.
        If obj is OpenAPI model, return the properties dict.
        :param obj: The data to serialize.
        :return: The serialized form of data.
        """
        if obj is None:
            return None
        elif isinstance(obj, Enum):
            return obj.value
        elif isinstance(obj, SecretStr):
            return obj.get_secret_value()
        elif isinstance(obj, self.BASIC_TYPES):
            return obj
        elif isinstance(obj, list):
            return [
                self.prepare_for_serialization(sub_obj) for sub_obj in obj
            ]
        elif isinstance(obj, tuple):
            return tuple(
                self.prepare_for_serialization(sub_obj) for sub_obj in obj
            )
        elif isinstance(obj, (datetime.datetime, datetime.date)):
            return obj.isoformat()
        elif isinstance(obj, decimal.Decimal):
            return str(obj)
        elif isinstance(obj, dict):
            obj_dict = obj
        else:
            # Convert model obj to dict except
            # attributes `openapi_types`, `attribute_map`
            # and attributes which value is not None.
            # Convert attribute name to json key in
            # model definition for request.
            if hasattr(obj, 'to_dict') and callable(getattr(obj, 'to_dict')):
                obj_dict = obj.to_dict()
            else:
                obj_dict = obj.__dict__
        return {
            key: self.prepare_for_serialization(val)
            for key, val in obj_dict.items()
        }

    def convert_response(self, response_text: str, response_type: str, content_type: Optional[str]):
        """Deserializes response into an object.
        :param response: RESTResponse object to be deserialized.
        :param response_type: class literal for
            deserialized object, or string of class name.
        :param content_type: content type of response.
        :return: deserialized object.
        """
        # fetch data from response object
        if content_type is None:
            try:
                data = json.loads(response_text)
            except ValueError:
                data = response_text
        elif re.match(r'^application/(json|[\w!#$&.+-^_]+\+json)\s*(;|$)', content_type, re.IGNORECASE):
            if response_text == "":
                data = ""
            else:
                data = json.loads(response_text)
        elif re.match(r'^text\/[a-z.+-]+\s*(;|$)', content_type, re.IGNORECASE):
            data = response_text
        else:
            raise ApiException(
                status=0,
                reason="Unsupported content type: {0}".format(content_type)
            )
        return self.__convert(data, response_type)

    def __convert(self, data, klass):
        """Deserializes dict, list, str into an object.
        :param data: dict, list or str.
        :param klass: class literal, or string of class name.
        :return: object.
        """
        if data is None:
            return None
        if isinstance(klass, str):
            if klass.startswith('List['):
                m = re.match(r'List\[(.*)]', klass)
                assert m is not None, "Malformed List type definition"
                sub_kls = m.group(1)
                return [self.__convert(sub_data, sub_kls)
                        for sub_data in data]
            if klass.startswith('Dict['):
                m = re.match(r'Dict\[([^,]*), (.*)]', klass)
                assert m is not None, "Malformed Dict type definition"
                sub_kls = m.group(2)
                return {k: self.__convert(v, sub_kls)
                        for k, v in data.items()}
            # convert str to class
            if klass in self.TYPE_MAPPING:
                klass = self.TYPE_MAPPING[klass]
            else:
                klass = getattr(api_client.models, klass)
        if klass in self.BASIC_TYPES:
            return self.__convert_primitive(data, klass)
        elif klass == object:
            return self.__convert_object(data)
        elif klass == datetime.date:
            return self.__convert_date(data)
        elif klass == datetime.datetime:
            return self.__convert_datetime(data)
        elif klass == decimal.Decimal:
            return decimal.Decimal(data)
        elif issubclass(klass, Enum):
            return self.__convert_enum(data, klass)
        else:
            return self.__convert_model(data, klass)

    def convert_to_tuples(self, params, collection_formats):
        """Get parameters as list of tuples, formatting collections.
        :param params: Parameters as dict or list of two-tuples
        :param dict collection_formats: Parameter collection formats
        :return: Parameters as list of tuples, collections formatted
        """
        new_params: List[Tuple[str, str]] = []
        if collection_formats is None:
            collection_formats = {}
        for k, v in params.items() if isinstance(params, dict) else params:
            if k in collection_formats:
                collection_format = collection_formats[k]
                if collection_format == 'multi':
                    new_params.extend((k, value) for value in v)
                else:
                    if collection_format == 'ssv':
                        delimiter = ' '
                    elif collection_format == 'tsv':
                        delimiter = '\t'
                    elif collection_format == 'pipes':
                        delimiter = '|'
                    else:  # csv is the default
                        delimiter = ','
                    new_params.append(
                        (k, delimiter.join(str(value) for value in v)))
            else:
                new_params.append((k, v))
        return new_params

    def params_to_query_string(self, params, collection_formats):
        """Get parameters as list of tuples, formatting collections.
        :param params: Parameters as dict or list of two-tuples
        :param dict collection_formats: Parameter collection formats
        :return: URL query string (e.g. a=Hello%20World&b=123)
        """
        new_params: List[Tuple[str, str]] = []
        if collection_formats is None:
            collection_formats = {}
        for k, v in params.items() if isinstance(params, dict) else params:
            if isinstance(v, bool):
                v = str(v).lower()
            if isinstance(v, (int, float)):
                v = str(v)
            if isinstance(v, dict):
                v = json.dumps(v)
            if k in collection_formats:
                collection_format = collection_formats[k]
                if collection_format == 'multi':
                    new_params.extend((k, str(value)) for value in v)
                else:
                    if collection_format == 'ssv':
                        delimiter = ' '
                    elif collection_format == 'tsv':
                        delimiter = '\t'
                    elif collection_format == 'pipes':
                        delimiter = '|'
                    else:  # csv is the default
                        delimiter = ','
                    new_params.append(
                        (k, delimiter.join(quote(str(value)) for value in v))
                    )
            else:
                new_params.append((k, quote(str(v))))
        return "&".join(["=".join(map(str, item)) for item in new_params])

    def build_file_params(
        self,
        files: Dict[str, Union[str, bytes, List[str], List[bytes], Tuple[str, bytes]]],
    ):
        """Builds form parameters.
        :param files: File parameters.
        :return: Form parameters with files.
        """
        params = []
        for k, v in files.items():
            if isinstance(v, str):
                with open(v, 'rb') as f:
                    filename = os.path.basename(f.name)
                    filedata = f.read()
            elif isinstance(v, bytes):
                filename = k
                filedata = v
            elif isinstance(v, tuple):
                filename, filedata = v
            elif isinstance(v, list):
                for file_param in v:
                    params.extend(self.build_file_params({k: file_param}))
                continue
            else:
                raise ValueError("Unsupported file value")
            mimetype = (
                mimetypes.guess_type(filename)[0]
                or 'application/octet-stream'
            )
            params.append(
                tuple([k, tuple([filename, filedata, mimetype])])
            )
        return params

    def select_accept_header(self, accepts: List[str]) -> Optional[str]:
        """Returns `Accept` based on an array of accepts provided.
        :param accepts: List of headers.
        :return: Accept (e.g. application/json).
        """
        if not accepts:
            return None
        for accept in accepts:
            if re.search('json', accept, re.IGNORECASE):
                return accept
        return accepts[0]

    def select_content_type(self, content_types):
        """Returns `Content-Type` based on an array of content_types provided.
        :param content_types: List of content-types.
        :return: Content-Type (e.g. application/json).
        """
        if not content_types:
            return None
        for content_type in content_types:
            if re.search('json', content_type, re.IGNORECASE):
                return content_type
        return content_types[0]

    def apply_auth_params(
        self,
        headers,
        queries,
        auth_settings,
        resource_path,
        method,
        body,
        request_auth=None
    ) -> None:
        """Updates header and query params based on authentication setting.
        :param headers: Header parameters dict to be updated.
        :param queries: Query parameters tuple list to be updated.
        :param auth_settings: Authentication setting identifiers list.
        :resource_path: A string representation of the HTTP request resource path.
        :method: A string representation of the HTTP request method.
        :body: A object representing the body of the HTTP request.
        The object type is the return value of prepare_for_serialization().
        :param request_auth: if set, the provided settings will
                             override the token in the configuration.
        """
        if not auth_settings:
            return
        if request_auth:
            self._apply_single_auth(
                headers,
                queries,
                resource_path,
                method,
                body,
                request_auth
            )
        else:
            for auth in auth_settings:
                auth_setting = self.config.auth_settings().get(auth)
                if auth_setting:
                    self._apply_single_auth(
                        headers,
                        queries,
                        resource_path,
                        method,
                        body,
                        auth_setting
                    )

    def _apply_single_auth(
        self,
        headers,
        queries,
        resource_path,
        method,
        body,
        auth_setting
    ) -> None:
        """Updates the request parameters based on a single auth_setting
        :param headers: Header parameters dict to be updated.
        :param queries: Query parameters tuple list to be updated.
        :resource_path: A string representation of the HTTP request resource path.
        :method: A string representation of the HTTP request method.
        :body: A object representing the body of the HTTP request.
        The object type is the return value of prepare_for_serialization().
        :param auth_setting: auth settings for the endpoint
        """
        if auth_setting['in'] == 'cookie':
            headers['Cookie'] = auth_setting['value']
        elif auth_setting['in'] == 'header':
            if auth_setting['type'] != 'http-signature':
                headers[auth_setting['key']] = auth_setting['value']
        elif auth_setting['in'] == 'query':
            queries.append((auth_setting['key'], auth_setting['value']))
        else:
            raise ApiValueError(
                'Authentication token must be in `query` or `header`'
            )

    def __download_file(self, response):
        """Deserializes body to file
        Saves response body into a file in a temporary folder,
        using the filename from the `Content-Disposition` header if provided.
        handle file downloading
        save response body into a tmp file and return the instance
        :param response:  RESTResponse.
        :return: file path.
        """
        fd, path = tempfile.mkstemp(dir=self.config.temp_folder_path)
        os.close(fd)
        os.remove(path)
        content_disposition = response.getheader("Content-Disposition")
        if content_disposition:
            m = re.search(
                r'filename=[\'"]?([^\'"\s]+)[\'"]?',
                content_disposition
            )
            assert m is not None, "Unexpected 'content-disposition' header value"
            filename = m.group(1)
            path = os.path.join(os.path.dirname(path), filename)
        with open(path, "wb") as f:
            f.write(response.data)
        return path

    def __convert_primitive(self, data, klass):
        """Deserializes string to primitive type.
        :param data: str.
        :param klass: class literal.
        :return: int, long, float, str, bool.
        """
        try:
            return klass(data)
        except UnicodeEncodeError:
            return str(data)
        except TypeError:
            return data

    def __convert_object(self, value):
        """Return an original value.
        :return: object.
        """
        return value

    def __convert_date(self, string):
        """Deserializes string to date.
        :param string: str.
        :return: date.
        """
        try:
            return parse(string).date()
        except ImportError:
            return string
        except ValueError:
            raise rest.ApiException(
                status=0,
                reason="Failed to parse `{0}` as date object".format(string)
            )

    def __convert_datetime(self, string):
        """Deserializes string to datetime.
        The string should be in iso8601 datetime format.
        :param string: str.
        :return: datetime.
        """
        try:
            return parse(string)
        except ImportError:
            return string
        except ValueError:
            raise rest.ApiException(
                status=0,
                reason=(
                    "Failed to parse `{0}` as datetime object"
                    .format(string)
                )
            )

    def __convert_enum(self, data, klass):
        """Deserializes primitive type to enum.
        :param data: primitive type.
        :param klass: class literal.
        :return: enum value.
        """
        try:
            return klass(data)
        except ValueError:
            raise rest.ApiException(
                status=0,
                reason=(
                    "Failed to parse `{0}` as `{1}`"
                    .format(data, klass)
                )
            )

    def __convert_model(self, data, klass):
        """Deserializes list or dict to model.
        :param data: dict, list.
        :param klass: class literal.
        :return: model object.
        """
        return klass.from_dict(data)

# Cloudflare DNS and Ingress Manager
import os
import sys
import json
import requests
import yaml
import subprocess
import argparse

# --- Configuration ---
# Standardize on CLOUDFLARE_* prefix
CLOUDFLARE_API_KEY = os.getenv("CLOUDFLARE_API_TOKEN") or os.getenv("CF_API_TOKEN")
CLOUDFLARE_ZONE_IDENTIFIER = os.getenv("CLOUDFLARE_ZONE_ID") or os.getenv("CF_ZONE_ID")
CONFIG_FILE_PATH = "/etc/cloudflared/config.yml"

class DnsManager:
    def __init__(self, simulate=False):
        self.simulate_mode = simulate
        self.auth_headers = {
            "Authorization": f"Bearer {CLOUDFLARE_API_KEY}",
            "Content-Type": "application/json"
        } if CLOUDFLARE_API_KEY else None

    def _validate_credentials(self):
        if not self.auth_headers or not CLOUDFLARE_ZONE_IDENTIFIER:
            return {"error": "Missing CLOUDFLARE_API_TOKEN or CLOUDFLARE_ZONE_ID."}
        return None

    def get_dns_records(self):
