    def adjust_ingress_rule(self, domain_name, backend_service):
        """
        Modifies cloudflared configuration for ingress routing.
        REQUIRES: Sudo privileges on the host system.
        Use --simulate to preview changes without applying them.
        """
        try:
            # Verify config file existence unless in simulation mode
            if not os.path.exists(CONFIG_FILE_PATH) and not self.simulate_mode:
                 return {"error": f"Configuration file missing at {CONFIG_FILE_PATH}"}

            # Load current configuration (may require elevated permissions)
            try:
                with open(CONFIG_FILE_PATH, 'r') as stream:
                    current_config = yaml.safe_load(stream)
            except PermissionError:
                # Attempt reading via sudo cat
                command = ["sudo", "cat", CONFIG_FILE_PATH]
                process_result = subprocess.run(command, capture_output=True, text=True, check=True)
                current_config = yaml.safe_load(process_result.stdout)

            if 'ingress' not in current_config:
                current_config['ingress'] = []

            # Check if domain already exists in ingress rules
            found = False
            for item in current_config['ingress']:
                if item.get('hostname') == domain_name:
                    item['service'] = backend_service
                    found = True
                    break

            if not found:
                # Insert before final catch-all entry if present
                if current_config['ingress'] and 'service' in current_config['ingress'][-1] and 'hostname' not in current_config['ingress'][-1]:
                    current_config['ingress'].insert(-1, {"hostname": domain_name, "service": backend_service})
                else:
                    current_config['ingress'].append({"hostname": domain_name, "service": backend_service})

            updated_yaml = yaml.dump(current_config, default_flow_style=False)

            if self.simulate_mode:
                return {
                    "status": "simulation", 
                    "operation": "adjust_ingress_rule", 
                    "target_file": CONFIG_FILE_PATH,
                    "preview_content": updated_yaml
                }

            # Write updated configuration using sudo tee
            writer = subprocess.Popen(['sudo', 'tee', CONFIG_FILE_PATH], stdin=subprocess.PIPE, stdout=subprocess.PIPE)
            writer.communicate(input=updated_yaml.encode())

            # Restart cloudflared service
            subprocess.run(['sudo', 'systemctl', 'restart', 'cloudflared'], check=True)
            return {"status": "success", "message": f"Ingress rule updated for {domain_name} and cloudflared restarted."}

        except Exception as exception:
            return {"status": "failure", "message": str(exception)}

