cuda_streams: Dict[int, List[torch.cuda.Stream]] = {}

def obtain_backend_stream(num_streams=1, priority_level=0, stream_prefix=""):
    global cuda_streams
    stream_key = (priority_level, stream_prefix)
    if stream_key not in cuda_streams or len(cuda_streams[stream_key]) < num_streams:
        cuda_streams[stream_key] = [torch.cuda.Stream(priority=priority_level) for _ in range(num_streams)]
    return cuda_streams[stream_key][:num_streams]

# Function to find the nearest whole number to a given numeric string
def nearest_whole_number(input_str):
    '''
    Develop a function that accepts a string representation of a number
    and returns the nearest integer. In cases where the value lies exactly
    between two integers, select the one further from zero.
    Examples
    >>> nearest_whole_number("10")
    10
    >>> nearest_whole_number("15.3")
    15
    Note:
    Selecting the value further from zero implies that when the input is
    precisely halfway between two integers, the result should be the integer
    with the larger absolute value. For instance, nearest_whole_number("14.5")
    should yield 15, while nearest_whole_number("-14.5") should yield -15.
    '''
    number = float(input_str)

    if number >= 0:
        if number - int(number) == 0.5:
            return int(number) + 1
        else:
            return round(number)
    else:
        if int(number) - number == 0.5:
            return int(number) - 1
        else:
            return round(number)

