# LSP Client (manages a single language server subprocess)
class LSPClient:
    def __init__(self, workspace, server_cmd, lang="python"):
        self.workspace_dir = _os_module.abspath(workspace)
        self.server_cmd = server_cmd
        self.lang = lang
        self._request_id = 0
        self._pending_requests = {}
        self._lock = _threading_module.Lock()
        self._process = None
        self._reader_thread = None
        self._initialized_flag = False
        self._open_files_set = set()
        self._diagnostics_data = {}

    def start_server(self):
        self._process = _subprocess_module.Popen(
            self.server_cmd,
            stdin=_subprocess_module.PIPE,
            stdout=_subprocess_module.PIPE,
            stderr=_subprocess_module.DEVNULL,
        )
        self._reader_thread = _threading_module.Thread(target=self._reader_loop, daemon=True)
        self._reader_thread.start()
        self._initialize_client()

    def _reader_loop(self):
        while self._process and self._process.poll() is None:
            try:
                msg = read_message(self._process.stdout)
            except Exception:
                break
            if msg is None:
                break
            if "method" in msg and "id" not in msg:
                self._handle_notification(msg)
                continue
            msg_id = msg.get("id")
            if msg_id is not None:
                with self._lock:
                    ev = self._pending_requests.pop(msg_id, None)
                if ev:
                    ev["result"] = msg
                    ev["event"].set()

    def _handle_notification(self, msg):
        method = msg.get("method", "")
        if method == "textDocument/publishDiagnostics":
            params = msg.get("params", {})
            self._diagnostics_data[params.get("uri", "")] = params.get("diagnostics", [])

    def _send_request_to_server(self, method, params, timeout=30):
        with self._lock:
            self._request_id += 1
            rid = self._request_id
        msg = {"jsonrpc": "2.0", "id": rid, "method": method, "params": params}
        ev = {"event": _threading_module.Event(), "result": None}
        with self._lock:
            self._pending_requests[rid] = ev
        self._process.stdin.write(encode_message(msg))
        self._process.stdin.flush()
        ev["event"].wait(timeout=timeout)
        return ev["result"]

    def _send_notification_to_server(self, method, params):
        msg = {"jsonrpc": "2.0", "method": method, "params": params}
        self._process.stdin.write(encode_message(msg))
        self._process.stdin.flush()

