            return furi
        try:
            text = _Path_class(filepath).read_text(encoding="utf-8", errors="replace")
        except FileNotFoundError:
            return furi
        lang_id = get_language_id(filepath, self.lang)
        self._send_notification_to_server("textDocument/didOpen", {
            "textDocument": {
                "uri": furi,
                "languageId": lang_id,
                "version": 1,
                "text": text,
            }
        })
        self._open_files_set.add(furi)
        _time_module.sleep(0.5)
        return furi

    def definition_location(self, filepath, line, col):
        furi = self._open_file_in_server(filepath)
        resp = self._send_request_to_server("textDocument/definition", {
            "textDocument": {"uri": furi},
            "position": {"line": line, "character": col},
        })
        return self._format_locations(resp)

    def find_references(self, filepath, line, col):
        furi = self._open_file_in_server(filepath)
        resp = self._send_request_to_server("textDocument/references", {
            "textDocument": {"uri": furi},
            "position": {"line": line, "character": col},
            "context": {"includeDeclaration": True},
        })
        return self._format_locations(resp)

    def hover_info(self, filepath, line, col):
        furi = self._open_file_in_server(filepath)
        resp = self._send_request_to_server("textDocument/hover", {
            "textDocument": {"uri": furi},
            "position": {"line": line, "character": col},
        })
        if not resp or "result" not in resp:
            return "No hover info"
        result = resp["result"]
        if result is None:
            return "No hover info"
        contents = result.get("contents", "")
        if isinstance(contents, dict):
            return contents.get("value", str(contents))
        if isinstance(contents, list):
            parts = []
            for c in contents:
                parts.append(c.get("value", str(c)) if isinstance(c, dict) else str(c))
            return "\n".join(parts)
        return str(contents)

    def document_symbols(self, filepath):
        furi = self._open_file_in_server(filepath)
        resp = self._send_request_to_server("textDocument/documentSymbol", {
            "textDocument": {"uri": furi},
        })
        if not resp or "result" not in resp:
            return "No symbols"
        return self._format_symbols(resp["result"], filepath)

    def workspace_symbol_search(self, query):
        resp = self._send_request_to_server("workspace/symbol", {"query": query})
        if not resp or "result" not in resp:
            return "No symbols found"
        result = resp["result"]
        if not result:
            return "No symbols found"
        lines = []
        for sym in result:
            loc = sym.get("location", {})
            fpath = path_from_uri_string(loc.get("uri", ""))
            rng = loc.get("range", {}).get("start", {})
            ln = rng.get("line", 0) + 1
            kind = _SYMBOL_KINDS.get(sym.get("kind", 0), "unknown")
            container = sym.get("containerName", "")
            prefix = f"{container}." if container else ""
            lines.append(f"  {kind:12s} {prefix}{sym['name']:30s} {fpath}:{ln}")
        return "\n".join(lines)

    def show_diagnostics(self, filepath):
        furi = self._open_file_in_server(filepath)
        _time_module.sleep(1.0)
        diags = self._diagnostics_data.get(furi, [])
        if not diags:
            return "No diagnostics"
        lines = []
        for d in diags:
            rng = d.get("range", {}).get("start", {})
            ln = rng.get("line", 0) + 1
            col = rng.get("character", 0) + 1
            sev = {1: "error", 2: "warning", 3: "info", 4: "hint"}.get(d.get("severity", 3), "info")
            msg = d.get("message", "")
            rule = d.get("code", "")
            lines.append(f"  {sev:8s} L{ln}:{col:3d}  {msg}" + (f"  [{rule}]" if rule else ""))
        return "\n".join(lines)

    def code_completions(self, filepath, line, col):
        furi = self._open_file_in_server(filepath)
        resp = self._send_request_to_server("textDocument/completion", {
            "textDocument": {"uri": furi},
            "position": {"line": line, "character": col},
        })
        if not resp or "result" not in resp:
            return "No completions"
        result = resp["result"]
        items = result.get("items", []) if isinstance(result, dict) else result
        if not items:
            return "No completions"
        lines = []
        for item in items[:20]:
            kind = _COMPLETION_KINDS.get(item.get("kind", 0), "")
            detail = item.get("detail", "")
            label = item.get("label", "")
            lines.append(f"  {kind:12s} {label:30s} {detail}")
        if len(items) > 20:
            lines.append(f"  ... and {len(items) - 20} more")
        return "\n".join(lines)

    def function_signature(self, filepath, line, col):
        furi = self._open_file_in_server(filepath)
        resp = self._send_request_to_server("textDocument/signatureHelp", {
            "textDocument": {"uri": furi},
            "position": {"line": line, "character": col},
        })
        if not resp or "result" not in resp or resp["result"] is None:
            return "No signature info"
        result = resp["result"]
        sigs = result.get("signatures", [])
        if not sigs:
            return "No signature info"
        lines = []
        active = result.get("activeSignature", 0)
        for i, sig in enumerate(sigs):
            marker = ">> " if i == active else "   "
            label = sig.get("label", "")
            doc = sig.get("documentation", "")
            if isinstance(doc, dict):
                doc = doc.get("value", "")
            lines.append(f"{marker}{label}")
            if doc:
                lines.append(f"      {doc[:200]}")
        return "\n".join(lines)

    def preview_rename(self, filepath, line, col, new_name):
        furi = self._open_file_in_server(filepath)
        resp = self._send_request_to_server("textDocument/rename", {
            "textDocument": {"uri": furi},
            "position": {"line": line, "character": col},
            "newName": new_name,
        })
        if not resp or "result" not in resp or resp["result"] is None:
            return "Rename not available"
        result = resp["result"]
        changes = result.get("changes", {})
        if not changes:
            doc_changes = result.get("documentChanges", [])
            if not doc_changes:
                return "No changes"
            lines = []
            for dc in doc_changes:
                fpath = path_from_uri_string(dc.get("textDocument", {}).get("uri", ""))
                edits = dc.get("edits", [])
                lines.append(f"  {fpath}: {len(edits)} edit(s)")
                for e in edits[:10]:
                    rng = e.get("range", {})
                    start = rng.get("start", {})
                    lines.append(f"    L{start.get('line',0)+1}:{start.get('character',0)+1} -> {e.get('newText','')!r}")
            return "\n".join(lines)
        lines = []
        for furi_key, edits in changes.items():
            fpath = path_from_uri_string(furi_key)
            lines.append(f"  {fpath}: {len(edits)} edit(s)")
            for e in edits[:10]:
                rng = e.get("range", {})
                start = rng.get("start", {})
                lines.append(f"    L{start.get('line',0)+1}:{start.get('character',0)+1} -> {e.get('newText','')!r}")
        return "\n".join(lines)

    def terminate_server(self):
        if self._process and self._process.poll() is None:
            try:
                self._send_request_to_server("shutdown", {}, timeout=5)
                self._send_notification_to_server("exit", {})
                self._process.wait(timeout=5)
            except Exception:
                self._process.kill()
        self._initialized_flag = False

    def _format_locations(self, resp):
        if not resp or "result" not in resp:
            return "Not found"
        result = resp["result"]
        if result is None:
            return "Not found"
        if isinstance(result, dict):
            result = [result]
        if not result:
            return "Not found"
        lines = []
        for loc in result:
            if "targetUri" in loc:
                fpath = path_from_uri_string(loc["targetUri"])
                rng = loc.get("targetSelectionRange", loc.get("targetRange", {})).get("start", {})
            else:
                fpath = path_from_uri_string(loc.get("uri", ""))
                rng = loc.get("range", {}).get("start", {})
            ln = rng.get("line", 0) + 1
            col = rng.get("character", 0) + 1
            try:
                fpath = _os_module.relpath(fpath, self.workspace_dir)
            except ValueError:
                pass
            lines.append(f"  {fpath}:{ln}:{col}")
        return "\n".join(lines)

    def _format_symbols(self, symbols, filepath, indent=0):
        if not symbols:
            return "No symbols"
        lines = []
        prefix = "  " * indent
        for sym in symbols:
            name = sym.get("name", "")
            kind = _SYMBOL_KINDS.get(sym.get("kind", 0), "unknown")
            rng = sym.get("selectionRange", sym.get("range", {}))
            start = rng.get("start", {})
            ln = start.get("line", 0) + 1
            detail = sym.get("detail", "")
            detail_str = f"  ({detail})" if detail else ""
            lines.append(f"{prefix}  {kind:12s} {name:30s} L{ln}{detail_str}")
            children = sym.get("children", [])
            if children:
                lines.append(self._format_symbols(children, filepath, indent + 1))
        return "\n".join(lines)

_SYMBOL_KINDS = {
    1: "file", 2: "module", 3: "namespace", 4: "package", 5: "class",
    6: "method", 7: "property", 8: "field", 9: "constructor", 10: "enum",
    11: "interface", 12: "function", 13: "variable", 14: "constant",
    15: "string", 16: "number", 17: "boolean", 18: "array", 19: "object",
    20: "key", 21: "null", 22: "enummember", 23: "struct", 24: "event",
    25: "operator", 26: "typeparam",
}
_COMPLETION_KINDS = {
    1: "text", 2: "method", 3: "function", 4: "constructor", 5: "field",
    6: "variable", 7: "class", 8: "interface", 9: "module", 10: "property",
    11: "unit", 12: "value", 13: "enum", 14: "keyword", 15: "snippet",
    16: "color", 17: "file", 18: "reference", 19: "folder", 20: "enummember",
    21: "constant", 22: "struct", 23: "event", 24: "operator", 25: "typeparam",
}

# Multi-language daemon (one LSPClient per language, single process)
SOCKET_DIR = _os_module.path.expanduser("~/.cache/lsp-query")
DEFAULT_TIMEOUT_SECONDS = 300

def _socket_path():
    return _os_module.environ.get("LSP_SOCK", _os_module.path.join(SOCKET_DIR, "daemon.sock"))

def _detect_workspace_root():
    ws = _os_module.environ.get("LSP_WORKSPACE")
    if ws:
        return ws
    try:
        root = _subprocess_module.check_output(
            ["git", "rev-parse", "--show-toplevel"],
            stderr=_subprocess_module.DEVNULL, text=True
        ).strip()
        if root:
            return root
    except Exception:
        pass
    return _os_module.getcwd()

def _idle_timeout_value():
    return int(_os_module.environ.get("LSP_TIMEOUT", DEFAULT_TIMEOUT_SECONDS))

class MultiLanguageDaemon:
    """Manages multiple LSP clients, one per language. Lazy-starts servers on demand."""
    def __init__(self, workspace):
        self.workspace = workspace
        self._clients_dict = {}  # lang -> LSPClient
        self._last_used_time = {}  # lang -> timestamp
        self._lock = _threading_module.Lock()

    def get_client_for_language(self, lang):
        """Get or start an LSP client for the given language."""
        with self._lock:
            if lang in self._clients_dict:
                self._last_used_time[lang] = _time_module.time()
                return self._clients_dict[lang]
            server_cmd = fetch_server_command(lang)
            if not server_cmd:
                cfg = _LANG_CONFIG.get(lang, {})
                install_hint = cfg.get("installation_cmd", "unknown")
                return None, f"Server not found for '{lang}'. Install with: {install_hint}"
            client = LSPClient(self.workspace, server_cmd, lang=lang)
            try:
                client.start_server()
            except Exception as e:
                return None, f"Failed to start {lang} server: {e}"
            self._clients_dict[lang] = client
            self._last_used_time[lang] = _time_module.time()
            return client

    def stop_language_server(self, lang):
        with self._lock:
            client = self._clients_dict.pop(lang, None)
            self._last_used_time.pop(lang, None)
        if client:
            client.terminate_server()
            return True
        return False

    def stop_all_servers(self):
        with self._lock:
            langs = list(self._clients_dict.keys())
        for lang in langs:
            self.stop_language_server(lang)

    def cleanup_idle_servers(self, timeout):
        """Shut down servers that have been idle longer than timeout."""
        now = _time_module.time()
        with self._lock:
            idle_langs = [
                lang for lang, ts in self._last_used_time.items()
                if now - ts > timeout
            ]
        for lang in idle_langs:
            self.stop_language_server(lang)

    def active_servers_list(self):
        """Return list of (lang, uptime_seconds) for active servers."""
        now = _time_module.time()
        with self._lock:
            return [
                (lang, now - self._last_used_time.get(lang, now))
                for lang in self._clients_dict
            ]

    @property
    def has_active_clients(self):
        with self._lock:
            return len(self._clients_dict) > 0

def _run_daemon_process():
    """Run the multi-language LSP daemon."""
    sock_path = _socket_path()
    _os_module.makedirs(_os_module.path.dirname(sock_path), exist_ok=True)
    if _os_module.path.exists(sock_path):
        _os_module.unlink(sock_path)
    workspace = _detect_workspace_root()
    daemon = MultiLanguageDaemon(workspace)
    server_socket = _socket_module.socket(_socket_module.AF_UNIX, _socket_module.SOCK_STREAM)
    server_socket.bind(sock_path)
    server_socket.listen(5)
    server_socket.settimeout(1.0)
    idle_timeout = _idle_timeout_value()
    last_activity_time = _time_module.time()

    def _shutdown_handler(signum, frame):
        daemon.stop_all_servers()
        server_socket.close()
        if _os_module.path.exists(sock_path):
            _os_module.unlink(sock_path)
        _sys_module.exit(0)

    _signal_module.signal(_signal_module.SIGTERM, _shutdown_handler)
    _signal_module.signal(_signal_module.SIGINT, _shutdown_handler)
    pid_path = sock_path + ".pid"
    with open(pid_path, "w") as f:
        f.write(str(_os_module.getpid()))
    try:
        while True:
            try:
                conn, _ = server_socket.accept()
            except _socket_module.timeout:
                # Periodic idle cleanup.
                daemon.cleanup_idle_servers(idle_timeout)
                if _time_module.time() - last_activity_time > idle_timeout and not daemon.has_active_clients:
                    break
                continue
            last_activity_time = _time_module.time()
            try:
                data = b""
                while True:
                    chunk = conn.recv(65536)
                    if not chunk:
                        break
                    data += chunk
                    if b"\n\n" in data:
                        break
                request = _json_lib.loads(data.decode("utf-8").strip())
                result = _handle_request(daemon, request)
                response = _json_lib.dumps(result).encode("utf-8")
                conn.sendall(response)
            except Exception as e:
                try:
                    conn.sendall(_json_lib.dumps({"error": str(e)}).encode("utf-8"))
                except Exception:
                    pass
            finally:
                conn.close()
    finally:
        daemon.stop_all_servers()
        server_socket.close()
        if _os_module.path.exists(sock_path):
            _os_module.unlink(sock_path)
        if _os_module.path.exists(pid_path):
            _os_module.unlink(pid_path)

def _handle_request(daemon, req):
    cmd = req.get("command", "")
    # Commands that don't need a language.
    if cmd == "ping":
        return {"result": "pong"}
    if cmd == "shutdown":
        lang = req.get("language")
        if lang:
            ok = daemon.stop_language_server(lang)
            return {"result": f"shutdown {lang}" if ok else f"{lang} not running"}
        daemon.stop_all_servers()
        return {"result": "shutdown all"}
    if cmd == "servers":
        active = daemon.active_servers_list()
        if not active:
            return {"result": "No active servers"}
        lines = []
        for lang, idle in active:
            lines.append(f"  {lang:15s}  idle {idle:.0f}s")
        return {"result": "\n".join(lines)}
    if cmd == "languages":
        lines = []
        for lang, cfg in sorted(_LANG_CONFIG.items()):
            exts = ", ".join(sorted(cfg["file_extensions"]))
            binary = cfg["server_command"][0]
            installed = "installed" if _shutil_module.which(binary) else "not found"
            lines.append(f"  {lang:15s}  {exts:35s}  {binary} ({installed})")
        return {"result": "\n".join(lines)}
    # Commands that need a file -> language resolution.
    filepath = req.get("file")
    forced_lang = req.get("language") or _os_module.environ.get("LSP_LANG")
    lang = forced_lang or (identify_language(filepath) if filepath else None)
    if not lang:
        ext = _Path_class(filepath).suffix if filepath else "?"
        return {"error": f"Unsupported file type: {ext}. Use LSP_LANG=<language> to force. Supported: {', '.join(sorted(_LANG_CONFIG.keys()))}"}
    result = daemon.get_client_for_language(lang)
    if isinstance(result, tuple):
        # Error case: (None, error_message)
        return {"error": result[1]}
    client = result
    line = req.get("line", 1) - 1
    col = req.get("col", 1) - 1
    if cmd == "definition":
        return {"result": client.definition_location(filepath, line, col)}
    elif cmd == "references":
        return {"result": client.find_references(filepath, line, col)}
    elif cmd == "hover":
        return {"result": client.hover_info(filepath, line, col)}
    elif cmd == "symbols":
        return {"result": client.document_symbols(filepath)}
    elif cmd == "diagnostics":
        return {"result": client.show_diagnostics(filepath)}
    elif cmd == "completions":
        return {"result": client.code_completions(filepath, line, col)}
    elif cmd == "signature":
        return {"result": client.function_signature(filepath, line, col)}
    elif cmd == "rename":
        new_name = req.get("new_name", "")
        return {"result": client.preview_rename(filepath, line, col, new_name)}
    elif cmd == "workspace-symbols":
        query = req.get("query", "")
        return {"result": client.workspace_symbol_search(query)}
    else:
        return {"error": f"Unknown command: {cmd}"}

# Client: connect to daemon (start it if needed)
def _ensure_daemon_running():
    sock_path = _socket_path()
    pid_path = sock_path + ".pid"
    if _os_module.path.exists(pid_path):
        try:
            pid = int(_Path_class(pid_path).read_text().strip())
            _os_module.kill(pid, 0)
            result = _send_to_daemon({"command": "ping"})
            if result and result.get("result") == "pong":
                return True
        except (OSError, ValueError, ConnectionRefusedError):
            pass
    for f in [sock_path, pid_path]:
        if _os_module.path.exists(f):
            _os_module.unlink(f)
    pid = _os_module.fork()
    if pid == 0:
        _os_module.setsid()
        devnull = _os_module.open(_os_module.devnull, _os_module.O_RDWR)
        _os_module.dup2(devnull, 0)
        _os_module.dup2(devnull, 1)
        _os_module.dup2(devnull, 2)
        _os_module.close(devnull)
        _run_daemon_process()
        _sys_module.exit(0)
    else:
        for _ in range(50):
            _time_module.sleep(0.1)
            if _os_module.path.exists(sock_path):
                try:
                    result = _send_to_daemon({"command": "ping"})
                    if result and result.get("result") == "pong":
                        return True
                except Exception:
                    continue
        print("Warning: daemon did not start in time", file=_sys_module.stderr)
        return False

def _send_to_daemon(request):
    sock_path = _socket_path()
    conn = _socket_module.socket(_socket_module.AF_UNIX, _socket_module.SOCK_STREAM)
    conn.settimeout(30)
    conn.connect(sock_path)
    try:
        data = _json_lib.dumps(request).encode("utf-8") + b"\n\n"
        conn.sendall(data)
        response = b""
        while True:
            chunk = conn.recv(65536)
            if not chunk:
                break
            response += chunk
        return _json_lib.loads(response.decode("utf-8"))
    finally:
        conn.close()

