from .selectors import (
    HAS_SELECT,
    DefaultSelector,
    EVENT_READ,
    EVENT_WRITE
)

def _poll_for_io_activity(sockets_list, operation_flags, time_limit=None):
    """ 
    Checks for I/O activity on provided socket objects.
    Returns sockets ready for the specified operations (read/write).
    """
    if not HAS_SELECT:
        raise RuntimeError('Selector functionality unavailable on this platform')

    # Normalize input to list format
    if not isinstance(sockets_list, list):
        if hasattr(sockets_list, 'fileno'):
            sockets_list = [sockets_list]
        else:
            sockets_list = list(sockets_list)

    with DefaultSelector() as selector:
        # Register each socket for the requested event types
        for socket in sockets_list:
            selector.register(socket, operation_flags)

        # Select sockets with pending events and filter by requested operations
        ready_sockets = []
        for sock_key, event_mask in selector.select(time_limit):
            if event_mask & operation_flags:
                ready_sockets.append(sock_key.fileobj)
        return ready_sockets

def await_read_ready(sockets, time_limit=None):
    """ 
    Waits until data can be read from sockets without blocking.
    Accepts either a single socket or an iterable of sockets.
    """
    return _poll_for_io_activity(sockets, EVENT_READ, time_limit)

def await_write_ready(sockets, time_limit=None):
    """ 
    Waits until sockets are ready for writing without blocking.
    Accepts either a single socket or an iterable of sockets.
    """
    return _poll_for_io_activity(sockets, EVENT_WRITE, time_limit)

import json
from django.core.serializers.base import DeserializationError
from django.core.serializers.json import (
    DjangoJSONEncoder, PythonDeserializer, Serializer as BaseJsonSerializer)
from prices import Money

MONEY_MARKER = 'Money'

class Serializer(BaseJsonSerializer):
    def _init_options(self):
        super()._init_options()
        self.json_kwargs['cls'] = CustomEncoder

class CustomEncoder(DjangoJSONEncoder):
    def default(self, value):
        if isinstance(value, Money):
            return {
                '_type': MONEY_MARKER, 
                'amount': float(value.amount),
                'currency': str(value.currency)}
        return super().default(value)

def restore_money_object(data):
    if '_type' in data and data['_type'] == MONEY_MARKER:
        return Money(data['amount'], data['currency'])
    return data

def Deserializer(input_stream, **kwargs):
    """Deserialize JSON data with custom Money handling. 
    Accepts either a file-like object or a string/bytes input."""

    # Handle different input types
    if not isinstance(input_stream, (bytes, str)):
        input_stream = input_stream.read()

    # Ensure we work with string data
    if isinstance(input_stream, bytes):
        input_stream = input_stream.decode('utf-8')

    try:
        # Parse JSON with custom object hook for Money objects
        parsed_data = json.loads(input_stream, object_hook=restore_money_object)

        # Use Django's PythonDeserializer to process the deserialized data
        yield from PythonDeserializer(parsed_data, **kwargs)

    except (GeneratorExit, DeserializationError):
        raise
    except Exception as error:
        raise DeserializationError(f"Failed to deserialize JSON: {error}") from error

# Custom decorator for caching function results with time-based expiration

from datetime import datetime, timedelta
import os

class cache_decorator(object):
    def __init__(self, *args, **kwargs):
        self.cache_storage = {}
        # Get cache duration from environment variable or use default
        cache_duration_seconds = int(os.environ.get('CACHE_AGE', 300))  # Default to 5 minutes if not set
        self.default_expiration = kwargs.get("cache_ttl", timedelta(seconds=cache_duration_seconds))

    def __call__(self, function_to_cache):
        def wrapper(*arguments, **keyword_arguments):
            # Extract the key parameter (second argument if present, otherwise first)
            cache_key = arguments[1] if len(arguments) > 1 else arguments[0]

            # Determine expiration time for this call
            expiration_time = keyword_arguments.get('cache_duration', self.default_expiration)

            # Initialize cache structure for this function if needed
            if function_to_cache not in self.cache_storage:
                self.cache_storage[function_to_cache] = {}

            # Check if we need to fetch fresh data
            should_refresh = (
                expiration_time is None or 
                cache_key not in self.cache_storage[function_to_cache] or 
                (datetime.now() - self.cache_storage[function_to_cache][cache_key]['timestamp']) > expiration_time
            )

            if should_refresh:
                # Clean up max_age parameter if present to avoid passing it to the original function
                if 'cache_duration' in keyword_arguments:
                    del keyword_arguments['cache_duration']

                # Execute the original function and store result
                result = function_to_cache(*arguments, **keyword_arguments)
                self.cache_storage[function_to_cache][cache_key] = {
                    'value': result, 
                    'timestamp': datetime.now()
                }

            return self.cache_storage[function_to_cache][cache_key]['value']

        return wrapper

