from webapp_health_monitor import errors

class BaseChecker(object):
    checker_name = None

    def __init__(self, **parameters):
        # Initialize with optional configuration parameters
        pass

    def execute(self):
        # Main execution method that must be implemented by subclasses
        raise NotImplementedError()

    def __repr__(self):
        # Return string representation using name or class name
        if self.checker_name:
            return self.checker_name
        else:
            return self.__class__.__name__

class IntervalChecker(BaseChecker):
    min_threshold = None
    max_threshold = None

    def execute(self):
        # Perform validation checks in sequence
        self._validate_setup()
        self._validate_measurement()

    def _validate_setup(self):
        # Ensure threshold values are properly configured
        if not self._setup_is_valid():
            raise errors.BadConfigurationError()

    def _setup_is_valid(self):
        # Check if lower bound is missing but upper bound exists
        if self.min_threshold is None:
            return self.max_threshold is not None
        # Check if both bounds exist and lower <= upper
        elif self.max_threshold is not None:
            return self.min_threshold <= self.max_threshold
        # Only lower bound is set (valid configuration)
        else:
            return True

    def _validate_measurement(self):
        # Get current value and validate against thresholds
        current_value = self.obtain_value()
        self._verify_minimum(current_value)
        self._verify_maximum(current_value)

    def obtain_value(self):
        # Abstract method to be implemented by subclasses
        raise NotImplementedError

    def _verify_minimum(self, value):
        # Check if value falls below minimum threshold
        if self.min_threshold is not None:
            if value < self.min_threshold:
                raise errors.VerificationFailure()

    def _verify_maximum(self, value):
        # Check if value exceeds maximum threshold
        if self.max_threshold is not None:
            if value > self.max_threshold:
                raise errors.VerificationFailure()

