class DynamicEPackageWrapper(EObserver):
    """A DynamicEPackageWrapper enables direct access to metaclasses
    from a metamodel, mimicking the behavior of a statically generated EPackage.

    Example usage with an existing dynamic EPackage 'myroot' containing two EClasses: 'A' and 'B'
    >>> from pyecore.utils import DynamicEPackageWrapper
    >>> MyAPI = DynamicEPackageWrapper(myroot)
    >>> MyAPI.A
