    def __init__(self, epackage):
        if not isinstance(epackage, EPackage):
            raise BadValueError(got=epackage, expected=EPackage)

        super().__init__(notifier=epackage)

        # Register all top-level classifiers as attributes
        for classifier in epackage.eClassifiers:
            setattr(self, classifier.name, classifier)

        # Recursively handle nested packages
        for nested_package in epackage.eSubpackages:
            setattr(self, nested_package.name, DynamicEPackageWrapper(nested_package))

    def notifyChanged(self, notification):
        change_type = notification.kind

        # Handle changes to the list of classifiers
        if notification.feature is EPackage.eClassifiers:
            if change_type == Kind.ADD:
                added_item = notification.new
                setattr(self, added_item.name, added_item)

            elif change_type == Kind.ADD_MANY:
                for item in notification.new:
