# A helper module for generating HTML-like elements

def _is_generator(obj):
    # Check if object is a generator using iteration protocol
    try:
        iter(obj)
        return hasattr(obj, '__next__')
    except TypeError:
        return False

class TagElement(object):
    tag_name = ''
    is_self_closing = False

    def __init__(self, *args, **kwargs):
        # Handle attribute parsing - check if first argument is a dictionary
        if args and isinstance(args[0], dict):
            self.attributes = args[0]
            remaining_args = args[1:]
        else:
            self.attributes = kwargs
            remaining_args = args

        # Process class-related attributes
        if 'css_classes' in kwargs:
            class_values = [c for c in kwargs.pop('css_classes') if c]
            kwargs['class'] = ' '.join(class_values)
        elif 'class_name' in kwargs:
            kwargs['class'] = kwargs.pop('class_name')

        self.content = []
        self.append_content(remaining_args)

    def __call__(self, *new_children):
        self.append_content(new_children)
        return self

    def __str__(self):
        attr_parts = [' {}="{}"'.format(k, v) for k, v in self.attributes.items() if v is not None]
        return '<{}{}>'.format(self.tag_name, ''.join(attr_parts))

    def append_content(self, items):
        if self.is_self_closing and items:
            raise ValueError("Self-closing elements cannot contain children.")

        # Unpack generators/iterables passed as single item
        if items and _is_generator(items[0]):
            items = items[0]

        for item in items:
            if item is not None:
                if isinstance(item, (list, tuple)):
                    self.append_content(item)
                else:
                    self.content.append(item)

# Reimplementation of WSGIResponse with modified logic for header handling and status code mapping

from typing import Iterable, List, Tuple
from werkzeug.http import HTTP_STATUS_CODES
from apistar import http

__all__ = ['WSGIEnviron', 'WSGIResponse']

# Create status code lookup dictionary using different approach
STATUS_CODES = {}
for code, msg in HTTP_STATUS_CODES.items():
    STATUS_CODES[code] = f"{code} {msg}"

CORS_HEADER = 'Access-Control-Allow-Origin'
WSGIEnviron = http.WSGIEnviron

class WSGIResponse(object):
    __slots__ = ('status', 'headers', 'iterator')

    def __init__(self,
                 status: str,
                 headers: List[Tuple[str, str]],
                 iterator: Iterable[bytes]) -> None:
        self.status = status
        self.headers = headers
        self.iterator = iterator

    @classmethod
    def build(cls, response: http.Response):
        # Handle status text with alternative logic
        if response.status in STATUS_CODES:
            status_text = STATUS_CODES[response.status]
        else:
            status_text = str(response.status)

        # Build headers list with different iteration method
        headers = []
        for key, value in response.headers.items():
            headers.append((key, value))

        # Add CORS header only if missing (using different condition check)
        has_cors = False
        for header_name, _ in headers:
            if header_name.lower() == CORS_HEADER.lower():
                has_cors = True
                break

        if not has_cors:
            headers.append((CORS_HEADER, '*'))

        return WSGIResponse(
            status=status_text,
            headers=headers,
            iterator=[response.content]
        )

