import math

def calculate_vino_love_mode_distribution(data_records):
    # Initialize counters for binary labels (0 and 1)
    label_counts = {False: 0, True: 0}

    for record in data_records:
        # Convert first element to boolean-like index
        label = bool(record[0])
        label_counts[label] += 1

    # Handle tie-breaking by preferring label 1 when counts are equal
    if label_counts[False] > label_counts[True]:
        return False
    else:
        return True

def filter_by_feature_attribute(feature_index, feature_value, data_collection):
    filtered_items = []
    for item in data_collection:
        if item[feature_index] == feature_value:
            filtered_items.append(item)
    return filtered_items

def compute_entropy(data_samples):
    # Initialize counters for binary classification
    class_frequencies = {0: 0, 1: 0}

    for sample in data_samples:
        class_label = sample[0]
        class_frequencies[class_label] += 1

    total_samples = len(data_samples)
    if total_samples == 0:
        return 0.0

    prob_0 = class_frequencies[0] / total_samples
    prob_1 = class_frequencies[1] / total_samples

    # Calculate entropy using base-2 logarithm
    entropy_value = 0.0
    if prob_0 > 0:
        entropy_value -= prob_0 * math.log2(prob_0)
    if prob_1 > 0:
        entropy_value -= prob_1 * math.log2(prob_1)

    return entropy_value

def select_optimal_split_attribute(data_points, features_with_options):
    highest_information_gain = -1
    best_feature = None

    for feature_name, possible_values in features_with_options.items():
        current_entropy = compute_entropy(data_points)
        weighted_average_entropy = 0.0

        for option_value in possible_values:
            partition = filter_by_feature_attribute(feature_name, option_value, data_points)
            partition_size = len(partition)

            if partition_size > 0:
                weight = partition_size / len(data_points)
                weighted_average_entropy += weight * compute_entropy(partition)

        information_gain = current_entropy - weighted_average_entropy

        if information_gain > highest_information_gain or best_feature is None:
            highest_information_gain = information_gain
            best_feature = feature_name

    return best_feature

import datetime
import numpy as np

class Epoch(datetime.datetime):
    @property
    def julian_date(self):
        # Calculate Julian Date using standard astronomical formula
        year = self.year
        month = self.month
        day = self.day
        hour = self.hour
        minute = self.minute
        second = self.second

        # Adjust for months January/February being treated as 13th/14th month
        if month <= 2:
            year -= 1
            month += 12

        a = np.floor(year / 100.0)
        b = 2 - a + np.floor(a / 4.0)

        jd = (np.floor(365.25 * (year + 4716)) +
              np.floor(30.6001 * (month + 1)) +
              day + b - 1524.5 +
              (hour + minute / 60.0 + second / 3600.0) / 24.0)
        return jd

    @property
    def jd2000(self):
        return self.julian_date - 2451545.0

    @property
    def jd1950(self):
        return self.julian_date - 2433282.423459043

    @property
    def modified_julian_date(self):
        return self.julian_date - 2400000.5

