from sympy import sympify

class SymbolicInterval:
    """A symbolic interval representation for summation purposes.

    This class represents a symbolic interval used in tensor operations,
    supporting optional lower and upper bounds. Bounds must either both be
    provided or both omitted. Intervals are treated as atomic and disjoint
    unless explicitly equal.

    .. warning::
         Different intervals are always considered disjoint regardless of bounds.
    """
    __slots__ = [
        '_name',
        '_min_val',
        '_max_val'
    ]

    def __init__(self, name, min_val=None, max_val=None):
        """Create a symbolic interval with given name and optional bounds."""
        self._name = name
        # Convert bounds to symbolic expressions if provided
        self._min_val = sympify(min_val) if min_val is not None else None

        if self._min_val is None:
            # If minimum is not provided, maximum must also be absent
            if max_val is not None:
                raise ValueError('Minimum value must be specified when maximum is given.')
            self._max_val = None
        else:
            # Minimum exists, so maximum must also be provided
            if max_val is None:
                raise ValueError('Maximum value must be specified when minimum is given.')
            self._max_val = sympify(max_val)

    @property
    def name(self):
        """Return the identifier/name of this interval."""
        return self._name

    @property
    def start(self):
        """Return the starting bound of the interval."""
        return self._min_val

    @property
    def end(self):
        """Return the ending bound of the interval."""
        return self._max_val

    @property
    def parameters(self):
        """Return tuple of parameters needed to reconstruct this interval.

        Returns either (name,) for unbounded intervals or 
        (name, start_bound, end_bound) for bounded intervals.
        """
        if self._min_val is not None:
            return (self._name, self._min_val, self._max_val)
        else:
            return (self._name,)

    def __hash__(self):
        """Generate hash based on interval parameters."""
        return hash(self.parameters)

    def __eq__(self, other):
        """Check equality between two intervals."""
        return isinstance(other, type(self)) and (self.parameters == other.parameters)

    def __repr__(self):
        """Generate formal string representation."""
        param_strs = [repr(p) for p in self.parameters]
        return f"SymbolicInterval({', '.join(param_strs)})"

    def __str__(self):
        """Return human-readable label."""
        return str(self._name)

