import xml.etree.ElementTree as ET
import codecs

def format_element(elem, depth=0):
    # Helper function to pretty-print XML elements
    indent_str = "\n" + depth * "  "

    if len(elem):
        # Element has children
        if not elem.text or elem.text.isspace():
            elem.text = indent_str + "  "

        for child in elem:
            format_element(child, depth + 1)

        if not elem.tail or elem.tail.isspace():
            elem.tail = indent_str
    else:
        # Leaf element
        if depth > 0 and (not elem.tail or elem.tail.isspace()):
            elem.tail = indent_str

class XMLOutput:
    def __init__(self, groups):
        root_element = ET.Element("parameters")

        # Add version info
        version_elem = ET.SubElement(root_element, "version")
        version_elem.text = "2"

        # Process each group
        for group in groups:
            group_elem = ET.SubElement(root_element, "group")
            group_name = group.GetName()
            group_elem.set("name", group_name)

            # Process parameters in the group
            for param in group.GetParams():
                param_elem = ET.SubElement(group_elem, "parameter")

                # Process field codes for this parameter
                for field_code in param.GetFieldCodes():
                    field_value = param.GetFieldValue(field_code)

                    if field_code == "code":
                        param_elem.set("name", field_value)
                    elif field_code == "default":
                        param_elem.set("default", field_value)
                    elif field_code == "type":
                        param_elem.set("type", field_value)
                    else:
                        # Create sub-element for other field codes
                        sub_elem = ET.SubElement(param_elem, field_code)
                        sub_elem.text = field_value

        # Apply formatting to XML tree
        format_element(root_element)
        self.xml_tree = ET.ElementTree(root_element)

    def Save(self, filename):
        with codecs.open(filename, 'w', 'utf-8') as file:
            self.xml_tree.write(file, encoding='unicode')

