import logging
import sys
import types

# Initialize flags for different metadata libraries
USE_IMPORTLIB_METADATA_STDLIB = False
USE_IMPORTLIB_METADATA = False
USE_PKG_RESOURCES = False

# Determine which metadata library to use based on Python version and availability
if sys.version_info >= (3, 10):
    # Python 3.10+ includes the required functionality in importlib.metadata
    import importlib.metadata as importlib_metadata
    USE_IMPORTLIB_METADATA_STDLIB = True
else:
    if sys.version_info >= (3, 6):
        # Try using backported importlib_metadata for older versions
        try:
            import importlib_metadata
            version_parts = [
                int(part) 
                for part in importlib_metadata.version("importlib_metadata").split(".") 
                if part.isdigit()
            ]
            if tuple(version_parts) >= (3, 3, 0):
                # Version 3.3.0+ contains the needed fix
                USE_IMPORTLIB_METADATA = True
        except (ImportError, ValueError):
            pass

# Fallback to pkg_resources if other options aren't available
if not (USE_IMPORTLIB_METADATA_STDLIB or USE_IMPORTLIB_METADATA):
    try:
        import pkg_resources
        USE_PKG_RESOURCES = True
    except ImportError:
        pass

# Set up logger
logger = logging.getLogger(__name__)

def get_entry_points(group, name=None):
    """Retrieve entry points matching the specified group and optionally name."""
    results = []

    if USE_IMPORTLIB_METADATA_STDLIB:
        logger.debug("Using importlib.metadata to load entry points")
        eps = importlib_metadata.entry_points()
    elif USE_IMPORTLIB_METADATA:
        logger.debug("Using importlib_metadata to load entry points")
        eps = importlib_metadata.entry_points()
    elif USE_PKG_RESOURCES:
        logger.debug("Using pkg_resources to load entry points")
        results = list(pkg_resources.iter_entry_points(group, name=name))
        return results
    else:
        return results

    # Process entry points from importlib-based libraries
    if USE_IMPORTLIB_METADATA_STDLIB or USE_IMPORTLIB_METADATA:
        for category, points in eps.items():
            if category != group:
                continue
            for point in points:
                if name is not None and point.name != name:
                    continue
                results.append(point)

    return results

def get_distribution_info(entry_point):
    """Extract name and version information from an entry point."""
    if USE_IMPORTLIB_METADATA_STDLIB or USE_IMPORTLIB_METADATA:
        dist_meta = entry_point.dist.metadata
        return types.SimpleNamespace(
            name=dist_meta["name"], 
            version=entry_point.dist.version
        )
    elif USE_PKG_RESOURCES:
        return types.SimpleNamespace(
            name=entry_point.dist.key, 
            version=entry_point.dist.version
        )

# Duplicate file detection and management tool

import os as _os
import sys as _sys
from pprint import pprint as _pprint
from dduplicated import commands as _commands

def collect_valid_directories(arguments):
    directories = []
    for arg in arguments:
        full_path = _os.path.join(_os.getcwd(), arg)
        # Check if path exists, is a directory, and is not a symbolic link
        if _os.path.exists(full_path) and _os.path.isdir(full_path) and not _os.path.islink(full_path):
            directories.append(full_path)
    return directories

def execute():
    args = _sys.argv.copy()
    del args[0]  # Remove script name

    if len(args) == 0 or "help" in args:
        _commands.help()
        return

    processed_items = []

    if "detect" in args:
        detected = _commands.detect(collect_valid_directories(args))
        processed_items = detected

    elif "delete" in args:
        to_delete = _commands.detect(collect_valid_directories(args))
        processed_items = _commands.delete(to_delete)

    elif "link" in args:
        to_link = _commands.detect(collect_valid_directories(args))
        processed_items = _commands.link(to_link)

    else:
        _commands.help()
        return

    if processed_items:
        _pprint(processed_items)
    else:
        print("No duplicates found")
        print("Great! Bye!")

if __name__ == "__main__":
    execute()

import pytest
from hypothesis import given, strategies as st
from datatyping.datatyping import validate

def test_empty_case():
    assert validate([], []) is None

@given(st.lists(st.integers()))
def test_integer_list_validation(int_list):
    assert validate([int], int_list) is None

@given(st.lists(st.floats(), min_size=1))
def test_float_list_rejects_int_type(float_list):
    with pytest.raises(TypeError):
        validate([int], float_list)

@given(st.one_of(st.lists(st.integers(), min_size=5),
                 st.lists(st.integers(), max_size=3)))
def test_mismatched_length_constraints(data_list):
    with pytest.raises(ValueError):
        validate([int, int, int, str], data_list)

@given(st.lists(st.lists(st.integers(), min_size=1), min_size=1))
def test_nested_structure_validation(nested_lists):
    assert validate([[int]], nested_lists) is None
    with pytest.raises(TypeError):
        validate([int], nested_lists)

@st.composite
def complex_nested_strategy(draw):
    return [
        draw(st.lists(st.integers(), min_size=1, max_size=3)),
        draw(st.floats()),
        draw(st.lists(st.lists(st.floats(), min_size=1, max_size=3), 
                      min_size=1, max_size=3))
    ]

@given(complex_nested_strategy())
def test_deeply_nested_validation(data):
    assert validate([[int], float, [[float]]], data) is None
    with pytest.raises(TypeError):
        validate([[str], int, int], data)
    with pytest.raises(TypeError):
        validate([[[float]]], data)

