# Regression test for line number calculation during edit application
# This test verifies that the fix event correctly identifies deletion positions
# even when file revisions differ.

from sensibility.evaluation.distance import determine_fix_event
from sensibility.edit import Deletion
from sensibility.language import language

# Original problematic code snippet (with extra closing brace)
error_content = b"""
/**
 * ##### # ########### ## ##### ############## ####.
 *
 * @###### (#### ####)
 * @####### (# ####### ###### ## # ####)
 */
public class DaysAlivePrint
{
    public static void  main(String[] args)
    {
        Day birthday = new Day(1951, 5, 25);
        Day today = new Day(2012, 7, 23);
        int days = today.daysFrom(birthday);
        System.out.println(days);
    }
    }
}"""

# Corrected version after applying fix
fixed_content = b"""
public class DaysAlivePrint
{
     public static void  main(String[] args)
    {
        Day birthday = new Day(1951, 5, 25);
        Day today = new Day(2012, 7, 23);
        int days = today.daysFrom(birthday);
        System.out.println(days); //print result
    }
}"""

def initialize_language():
    """Set up the programming language context for analysis."""
    language.set_language('java')

def test_line_number_regression() -> None:
    """Verify that the fix event correctly identifies deletion positions."""
    initialize_language()

    # Determine the fix event between error and fixed versions
    fix_event = determine_fix_event(error_content, fixed_content)

    # Confirm the fix involves a deletion operation
    assert isinstance(fix_event.fix, Deletion)

    # Verify the deleted token is a closing brace
    assert fix_event.fix.original_token == language.vocabulary.to_index('}')

    # Ensure the line number falls within expected range for brace deletions
    assert fix_event.line_no in {19, 22, 23}

import json
from slack import WebClient

class SlackNotifier:
    """Class to handle Slack notifications for a specific channel"""

    def __init__(self, api_token, target_channel):
        self.channel_id = None
        self.channel_name = target_channel

        # Initialize Slack client with API token
        self.slack_client = WebClient(token=api_token)

        # Try to find the channel in public channels first
        try:
            response = self.slack_client.conversations_list(exclude_archived=True, types=['public_channel'])

            if response.get("ok"):
                for channel in response["channels"]:
                    if channel["name"] == target_channel:
                        self.channel_id = channel["id"]
                        self.channel_name = channel["name"]
                        break

            # If not found in public channels, check private groups
            if not self.channel_id:
                response = self.slack_client.conversations_list(exclude_archived=True, types=['private_channel'])

                if response.get("ok"):
                    for channel in response["channels"]:
                        if channel["name"] == target_channel:
                            self.channel_id = channel["id"]
                            self.channel_name = channel["name"]
                            break
        except Exception as e:
            pass  # Silently handle errors during channel lookup

    def post_message(self, text_content, blocks=None):
        """Send a message to the configured Slack channel"""
        try:
            result = self.slack_client.chat_postMessage(
                channel=self.channel_id,
                text=text_content,
                blocks=blocks,
                link_names=True,
                unfurl_links=True
            )

            if not result.get("ok"):
                raise Exception(result.get("error", "Unknown Slack error"))

            return result
        except Exception as e:
            raise SystemError(f"Slack API Error: {str(e)}")

def send_slack_rating_notification(rating_data, application):
    # Check configuration before proceeding
    if "SLACK_TOKEN" in application.config and application.config.get("SLACK_NOTIFICATION_CHANNEL"):
        notifier = SlackNotifier(
            application.config["SLACK_TOKEN"],
            application.config["SLACK_NOTIFICATION_CHANNEL"]
        )

        application.logger.info(
            f"Sending Slack notification for {rating_data.user.nickname}'s rating of {rating_data.movie.name}"
        )

        try:
            # Prepare attachment content
            attachment_blocks = [{
                "type": "section",
                "text": {
                    "type": "mrkdwn",
                    "text": rating_data.comment or "_No comment_"
                }
            }]

            # Send movie link message
            movie_link = f"<{rating_data.movie.url}?language=fr|{rating_data.movie.name}>"
            notifier.post_message(movie_link)

            # Send rating message with user info
            rating_text = f"Note de @{rating_data.user.nickname}: *{rating_data.rating}*"
            notifier.post_message(rating_text, blocks=attachment_blocks)

            return 0

        except Exception as error:
            application.logger.error(f"Failed to send Slack notification: {str(error)}")
            return 1
    else:
        return -1

import json
from django.core.management.base import BaseCommand
from readthedocs.oauth.models import RemoteRepository

class Command(BaseCommand):
    help = "Update RemoteRepository project associations using JSON input"

    def add_arguments(self, parser):
        parser.add_argument(
            '--input-file',
            required=True,
            nargs=1,
            type=str,
            help='Path to JSON file containing repository-project mappings.',
        )

    def handle(self, *args, **options):
        input_path = options['input_file'][0]

        try:
            with open(input_path, 'r', encoding='utf-8') as json_file:
                repo_data_list = json.load(json_file)
        except (IOError, json.JSONDecodeError) as err:
            self.stderr.write(
                self.style.ERROR(
                    f"Failed to read or parse file '{input_path}': {err}"
                )
            )
            return

        for entry in repo_data_list:
            try:
                remote_id = entry.get('remote_id')
                project_id = entry.get('project_id')

                if not remote_id or project_id is None:
                    self.stderr.write(
                        self.style.WARNING(
                            f"Skipping entry with missing fields: {entry}"
                        )
                    )
                    continue

                updated_rows = RemoteRepository.objects.filter(
                    remote_id=remote_id
                ).update(project_id=project_id)

                if updated_rows == 0:
                    self.stderr.write(
                        self.style.WARNING(
                            f"No match found for remote_id={remote_id}; "
                            f"could not assign project_id={project_id}."
                        )
                    )

            except Exception as exc:
                self.stderr.write(
                    self.style.ERROR(
                        f"Error processing entry {entry.get('slug', 'unknown')}: "
                        f"{exc}"
                    )
                )

