def is_simulation_complete(directory, output_file='lammps_out.txt'):
    contents = os.listdir(directory)

    if output_file in contents:
        full_path = os.path.join(directory, output_file)
        try:
            with open(full_path, 'r') as f:
                lines = f.readlines()

            if len(lines) > 0:
                if 'Total wall time' in lines[-1]:
                    print('%-20s -> finished' % os.path.basename(directory))
                else:
                    print('%-20s -> running' % os.path.basename(directory))
            else:
                print('%-20s -> NOT started' % os.path.basename(directory))
        except Exception:
            print('%-20s -> error reading file' % os.path.basename(directory))
    elif all(os.path.isdir(os.path.join(directory, item)) for item in contents):
        print('########## %s ##########' % directory)
        for sub_dir in contents:
            is_simulation_complete(os.path.join(directory, sub_dir))
    else:
        print('Directory structure issue detected...')

