import glob
import re
import snmpy

class log_processor(snmpy.plugin):
    def setup(self):
        # Initialize counters based on configuration
        for key, value in sorted(self.conf['objects'].items()):
            # Compile regex patterns and set defaults
            count_pattern = re.compile(value['count'])
            reset_pattern = re.compile(value['reset']) if 'reset' in value else None

            # Set initial value and options
            initial_value = int(value['start']) if 'start' in value else 0
            rotation_enabled = bool(value['rotate']) if 'rotate' in value else False

            # Register SNMP data items: string label and integer counter with metadata
            self.data['1.%s' % key] = ('string', value['label'])
            self.data['2.%s' % key] = ('integer', initial_value, {
                'count': count_pattern,
                'reset': reset_pattern,
                'start': initial_value,
                'rotate': rotation_enabled
            })

        # Start tailing the log file
        self.tail()

    @snmpy.plugin.task
    def tail(self):
        # Get first matching log file and start tailing
        log_files = glob.glob(self.conf['file_name'])
        if not log_files:
            return

        for line in snmpy.plugin.tail(log_files[0], True):
            # Handle rotation signal
            if line is True:
                for item_key in self.data['2.0':]:
                    if self.data[item_key]['rotate']:
                        self.data[item_key] = self.data[item_key]['start']
                continue

            # Process each log line against registered patterns
            for item_key in self.data['2.0':]:
                meta = self.data[item_key]

                # Try to match count pattern
                count_match = meta['count'].search(line)
                if count_match:
                    increment = 1
                    if count_match.groups():
                        try:
                            increment = int(count_match.group(1))
                        except ValueError:
                            pass
                    self.data[item_key] += increment
                    break

                # Try to match reset pattern
                if meta['reset'] is not None:
                    reset_match = meta['reset'].search(line)
                    if reset_match:
                        self.data[item_key] = meta['start']
                        break

