class Web3Service(metaclass=Singleton):
    """Manages a single Web3 instance configured via Django settings."""

    def __init__(self, *args, **kwargs):
        """Constructs the Web3 service instance.

        Args:
            rpc_provider (Provider, optional): Custom web3 Provider instance.
        """
        # Extract custom provider if provided
        custom_provider = kwargs.pop('rpc_provider', None)

        # Use provided provider or construct one based on available modules
        if custom_provider is not None:
            provider = custom_provider
        else:
            provider = self._create_default_provider()

        self.web3 = Web3(provider)
        super().__init__()

    def _create_default_provider(self):
        """Creates an appropriate provider based on available modules and settings."""
        if HTTPProvider is not None:
            # Construct HTTPS/HTTP URI based on SSL setting
            scheme = "https" if getattr(settings, 'ETHEREUM_NODE_SSL', False) else "http"
            uri = f"{scheme}://{settings.ETHEREUM_NODE_HOST}:{settings.ETHEREUM_NODE_PORT}"

            return HTTPProvider(
                endpoint_uri=uri,
                timeout=getattr(settings, "ETHEREUM_NODE_TIMEOUT", 10)
            )
        elif RPCProvider is not None:
            return RPCProvider(
                host=settings.ETHEREUM_NODE_HOST,
                port=settings.ETHEREUM_NODE_PORT,
                ssl=getattr(settings, 'ETHEREUM_NODE_SSL', False),
                timeout=getattr(settings, "ETHEREUM_NODE_TIMEOUT", 10)
            )
        else:
            raise ValueError("No suitable RPC provider module available")

