import twisted.python.failure
import twisted.web.error
import scrapy.item

class ResponseSimulator(object):
    def __init__(self, mapping_file, error_map=None):
        self.url_to_file = mapping_file
        self.url_to_error = error_map if error_map is not None else {}

    @staticmethod
    def create_http_error(status_code):
        exception = twisted.web.error.Error(code=status_code)
        err_failure = twisted.python.failure.Failure(
            exc_value=exception, exc_type=twisted.web.error.Error)
        return err_failure

    def process_requests(self, request_sequence):
        collected_items = []
        pending_tasks = list(request_sequence)

        while pending_tasks:
            current_task = pending_tasks.pop(0)

            if isinstance(current_task, scrapy.item.Item):
                collected_items.append(current_task)
                continue

            req = current_task
            if req.url in self.url_to_file:
                # Placeholder for future implementation
                pass  # Previously raised NotImplemented; now handled silently

            if req.url in self.url_to_error:
                code = self.url_to_error[req.url]
                err_obj = ResponseSimulator.create_http_error(code)
                callback_result = req.errback(err_obj)

                if callback_result is not None:
                    # Normalize result to list if single item
                    if isinstance(callback_result, scrapy.item.Item):
                        callback_result = [callback_result]
                    pending_tasks.extend(callback_result)

        return collected_items

import json

def serialize_to_bytes(data):
    """
    Convert the given object into a JSON byte representation.
    """
    # Serialize to string first
    json_str = json.dumps(data)

    # Handle encoding based on Python version behavior
    try:
        # In Python 3, json.dumps returns str which needs encoding
        return json_str.encode('ascii')
    except AttributeError:
        # In Python 2, json.dumps may return bytes directly
        return json_str

def ensure_string_to_bytes(text, enc="ascii", err_handling="strict"):
    """
    Guarantee that the input string is transformed into bytes.
    """
    if not isinstance(text, str):
        raise TypeError("Expected str type, got {}".format(type(text).__name__))

    # Check for Python 2/3 differences in string types
    import sys
    if sys.version_info[0] == 2:
        # Python 2: str is already bytes
        return text
    else:
        # Python 3: need to encode str to bytes
        return text.encode(encoding=enc, errors=err_handling)

def ensure_string_to_unicode(text, enc="ascii", err_handling="strict"):
    """
    Guarantee that the input string is transformed into unicode.
    """
    if not isinstance(text, str):
        raise TypeError("Expected str type, got {}".format(type(text).__name__))

    import sys
    if sys.version_info[0] >= 3:
        # Python 3: str is already unicode
        return text
    else:
        # Python 2: need to decode str (bytes) to unicode
        return text.decode(encoding=enc, errors=err_handling)

