# Convert language XML files from v2 format to new format

import sys
import os
from xml.etree import ElementTree as ET

def transform_language_file(source_path, template_path, result_path):
    # Parse the source (old) language file
    source_tree = ET.parse(source_path)
    source_root = source_tree.getroot()

    # Parse the template file
    template_tree = ET.parse(template_path)
    template_root = template_tree.getroot()

    # Collect original strings from template
    required_strings = set()
    for string_elem in template_root.findall('string'):
        original_text = string_elem.find('original')
        if original_text is not None:
            required_strings.add(original_text.text)

    # Build translation dictionary from source file
    translation_map = {}
    for word_elem in source_root.findall('word'):
        key_elem = word_elem.find('key')
        if key_elem is not None:
            key_text = key_elem.text
            if key_text in required_strings:
                trans_elem = word_elem.find('translation')
                if trans_elem is not None and trans_elem.text:
                    translation_map[key_text] = trans_elem.text

    # Update translations in template based on available mappings
    for string_elem in template_root.findall('string'):
        original_elem = string_elem.find('original')
        translation_elem = string_elem.find('translation')

        if original_elem is None or translation_elem is None:
            continue

        original_text = original_elem.text
        if original_text in translation_map:
            print(f"{translation_elem.text} -> {translation_map[original_text]}")
            translation_elem.text = translation_map[original_text]
        else:
            translation_elem.text = original_text

    # Write updated template to output file
    template_tree.write(result_path, encoding='utf-8', xml_declaration=True)

def show_help(program_name="ConvertLanguage"):
    print(f"Usage: {program_name} input.xml template.xml output.xml")
    print("File descriptions:")
    print("input.xml       The old (v2) language file to convert")
    print("template.xml    Template file to use for missing translations")
    print("output.xml      Output file name")

if __name__ == "__main__":
    if len(sys.argv) < 4:
        show_help(os.path.basename(sys.argv[0]))
    else:
        transform_language_file(sys.argv[1], sys.argv[2], sys.argv[3])

def chessKnight(cell):
    # Validate the input cell using regular expression
    import re
    pattern = r'^([a-h])([1-8])$'
    match = re.match(pattern, cell, re.IGNORECASE)

    if not match:
        # Invalid cell format
        return 0

    file_char = match.group(1).lower()
    rank_num = int(match.group(2))

    # Start with maximum possible moves (8)
    possible_moves = 8

    # Adjust based on horizontal position (file)
    if file_char in ['a', 'h']:
        possible_moves -= 4
        if rank_num in [2, 7]:
            possible_moves -= 1
        elif rank_num in [1, 8]:
            possible_moves -= 2
    elif file_char in ['b', 'g']:
        possible_moves -= 2
        if rank_num in [2, 7]:
            possible_moves -= 2
        elif rank_num in [1, 8]:
            possible_moves -= 3
    else:
        # Files c-f (not a, b, g, h)
        if rank_num in [2, 7]:
            possible_moves -= 2
        elif rank_num in [1, 8]:
            possible_moves -= 4

    return possible_moves

def main():
    test_cases = [
        ["a1", 2],
        ["c2", 6],
        ["d4", 8],
        ["g6", 6],
        ["a10", 0]
    ]

    for test in test_cases:
        result = chessKnight(test[0])
        expected = test[1]
        if result == expected:
            print("PASSED: chessKnight({}) returned {}".format(test[0], result))
        else:
            print("FAILED: chessKnight({}) returned {}, expected: {}".format(test[0], result, expected))

if __name__ == '__main__':
    main()

