    config.addinivalue_line("markers",
                            "skip_on_travis: Mark test to be skipped in Travis environment")

    # Start background progress reporter for Travis to prevent timeout
    global _progress_monitor
    if config.getoption("--travis-mode") and _progress_monitor is None:
        import multiprocessing
        import time

        def keep_alive():
            while True:
                print(".", flush=True)
                time.sleep(60)

        _progress_monitor = multiprocessing.Process(target=keep_alive, daemon=True)
        _progress_monitor.start()

