import copy
import os
from subprocess import STDOUT, run as _run, CalledProcessError, TimeoutExpired, FileNotFoundError, ProcessLookupError

# Environment setup to capture glibc errors by forcing them to stderr
ENV = copy.copy(os.environ)
ENV["LIBC_FATAL_STDERR_"] = "1"

def execute_command(cmd, input_data=None, timeout=None):
    execution_status = 'success'

    try:
        process_result = _run(
            cmd,
            stderr=STDOUT,
            timeout=timeout,
            input=input_data,
            env=ENV,
            check=True
        )
        result_content = process_result.stdout if hasattr(process_result, 'stdout') else None

    except CalledProcessError as error:
        execution_status = 'called process error'
        result_content = error.output if hasattr(error, 'output') and error.output else str(error)

    except TimeoutExpired as error:
        execution_status = f'timed out after {timeout} seconds'
        result_content = error.output if hasattr(error, 'output') and error.output else str(error)

    except FileNotFoundError as error:
        execution_status = 'not found'
        result_content = str(error)

    except ProcessLookupError as error:
        # Attempt recursive retry on process lookup error
        try:
            return execute_command(cmd, input_data=input_data, timeout=timeout)
        except Exception:
            execution_status = 'process lookup error'
            result_content = str(error)

    # Ensure result is converted to string
    try:
        if not isinstance(result_content, str):
            if result_content is None:
                result_content = ""
            else:
                result_content = result_content.decode('utf-8')
    except UnicodeDecodeError:
        try:
            result_content = result_content.decode('cp437')
        except (AttributeError, UnicodeDecodeError):
            result_content = str(result_content) if result_content else ""

    return (execution_status, result_content)

import sys
import lxml.etree

class XPathException(Exception):
    pass

def load_xml_document(filepath):
    return lxml.etree.parse(filepath)

def create_xpath_expression(expression):
    try:
        return lxml.etree.XPath(expression)
    except lxml.etree.XPathSyntaxError as error:
        exc_info = sys.exc_info()
        raise XPathException(error.msg), None, exc_info[2]

def register_custom_functions():
    namespace = lxml.etree.FunctionNamespace(None)
    namespace['is_call'] = check_function_call

def check_function_call(context, *function_names):
    current_node = context.context_node

    # Check if the node is a function call expression
    if current_node.tag != 'ParameterizedExpr':
        return False

    # Verify the first child is a name expression for a function
    if len(current_node) == 0 or current_node[0].tag != 'NameExpr':
        return False
    if current_node[0].get('kind') != 'FUN':
        return False

    # Extract the function name being called
    name_element = current_node[0][0]
    if name_element is None or name_element.get('nameId') is None:
        return False
    called_name = name_element.get('nameId')

    # Compare against provided names (supporting both string and list inputs)
    for name in function_names:
        if isinstance(name, basestring):
            if called_name == name:
                return True
        else:
            if any(called_name == n for n in name):
                return True

    return False

