def validate_cli_arguments(arguments):
    """
    Validates the command-line interface arguments.

    :param arguments: Dictionary of parsed CLI arguments (e.g., from docopt)
    :return: None
    """
    # Regex pattern to detect invalid characters in project name
    project_name_pattern = re.compile(r'[^a-zA-Z0-9_]')

    # Validate genconfig-specific options
    if arguments.get('genconfig'):
        if arguments['--type'] not in ('scraper', 'crawler'):
            raise InvalidType("--type must be either 'scraper' or 'crawler'")
        if arguments['--selector'] not in ('xpath', 'css'):
            raise InvalidSelector("--selector must be either 'xpath' or 'css'")

    # Validate generate/run-specific options
    if arguments.get('generate') or arguments.get('run'):
        if arguments['--output_type'] not in ('json', 'csv'):
            raise InvalidOutputType("--output_type must be either 'json' or 'csv'")

    # Validate project name for all relevant commands
    if any(arguments.get(cmd) for cmd in ['genconfig', 'generate', 'run']):
        if project_name_pattern.search(arguments['<projectname>']) is not None:
            raise ValueError("<projectname> can only contain letters, digits, and underscores")

    # Validate levels parameter
    try:
        levels_value = int(arguments['--levels'])
        if levels_value < 1:
            raise ValueError("--levels must be at least 1")
    except ValueError:
        raise ValueError("--levels must be a valid integer")

    return

import collections
import typing

class Meta(collections.OrderedDict, typing.MutableMapping[str, float]):
    def __init__(self, *args, **kwargs) -> None:
        self._min_value = float('inf')
        self._max_value = 0.0
        self._sorted_flag = True
        super(Meta, self).__init__(*args, **kwargs)

    def __setitem__(self, key: str, value: float) -> None:
        if key in self and self[key] == value:
            raise AssertionError('Duplicate assignment')

        if value < self._min_value:
            self._min_value = value
        else:
            self._sorted_flag = False

        if value > self._max_value:
            self._max_value = value

        super(Meta, self).__setitem__(key, value)
        self._update_state()

    def items(self) -> typing.ItemsView[str, float]:
        self._sort_items()
        return super(Meta, self).items()

    def first_item(self) -> typing.Tuple[str, float]:
        self._sort_items()
        for k, v in self.items():
            return k, v

    def first_key(self) -> str:
        self._sort_items()
        for key in self:
            return key

    def max_value(self) -> float:
        return self._max_value

    def _sort_items(self) -> None:
        if self._sorted_flag:
            return

        sorted_pairs = sorted(super(Meta, self).items(), key=lambda x: x[1], reverse=True)
        for k, _ in sorted_pairs:
            self.move_to_end(k)
        self._sorted_flag = True

    def _update_state(self):
        pass

# Custom permission class for OAuth2 scope validation

from django.core.exceptions import ImproperlyConfigured
from rest_framework.permissions import BasePermission

HTTP_METHODS_READ_ONLY = ['GET', 'HEAD', 'OPTIONS']

class OAuth2ScopeChecker(BasePermission):
    """
    Validates that incoming requests are authenticated and that the 
    access token includes the necessary permissions (scopes) for the operation.
    """

    def has_permission(self, request, view):
        auth_token = request.auth

        # Determine if the request is read-only
        is_safe_request = request.method in HTTP_METHODS_READ_ONLY

        # Reject unauthenticated requests
        if not auth_token:
            return False

        # Proceed only if token supports scope checking
        if hasattr(auth_token, 'scope'):
            # Retrieve required scopes from the view
            scope_config = self._extract_scopes(request, view)

            # Check base required scopes first
            if scope_config['mandatory'] is not None:
                scope_check_result = auth_token.is_valid(scope_config['mandatory'])
                if scope_check_result is False:
                    return False
            else:
                # No mandatory scopes defined
                scope_check_result = False

            # Apply method-specific scope checks
            if is_safe_request:
                if scope_config['read_only'] is not None:
                    return auth_token.is_valid(scope_config['read_only'])
            else:
                if scope_config['write_operations'] is not None:
                    return auth_token.is_valid(scope_config['write_operations'])

            return scope_check_result

        # Fail fast if authentication backend isn't compatible
        raise AssertionError(
            'OAuth2ScopeChecker requires the '
            '`oauth_api.authentication.OAuth2Authentication` '
            'authentication class to be configured.'
        )

    def _extract_scopes(self, request, view):
        # Extract scope definitions from the view
        mandatory_scopes = getattr(view, 'required_scopes', None)
        read_only_scopes = getattr(view, 'read_scopes', None)
        write_operation_scopes = getattr(view, 'write_scopes', None)

        # Ensure at least one scope type is defined
        if not mandatory_scopes and not read_only_scopes and not write_operation_scopes:
            raise ImproperlyConfigured(
                'OAuth-protected endpoints must define at least one scope type: '
                'required_scopes, read_scopes, or write_scopes.'
            )

        return {
            'mandatory': mandatory_scopes,
            'read_only': read_only_scopes,
            'write_operations': write_operation_scopes,
        }

# Extract external library imports from Python source files

import ast
import os
from collections import deque
import sys
from stdlib_list import stdlib_list

# Configuration for import filtering
settings = {
    'skip_relative_imports': True,
    'exclude_standard_modules': True,
    'python_version': None,
}

def extract_imported_packages(source_code):
    """Parse Python code and extract top-level imported package names."""
    parsed_tree = ast.parse(source_code)
    imported_packages = deque()

    for node in parsed_tree.body:
        # Handle 'import module' or 'import module1, module2'
        if isinstance(node, ast.Import):
            for alias in node.names:
                module_name = alias.name.split('.')[0]
                imported_packages.append(module_name)

        # Handle 'from module import ...'
        elif isinstance(node, ast.ImportFrom):
            # Skip relative imports based on configuration
            if node.level > 0:
                if settings['skip_relative_imports'] or not node.module:
                    continue
                else:
                    imported_packages.append(node.module.split('.')[0])

    return list(imported_packages)

def scan_directory_for_libraries(project_path):
    """Scan a directory tree for third-party library imports."""
    detected_libraries = set()

    for dirpath, _, filenames in os.walk(project_path):
        for filename in filenames:
            if filename.endswith('.py'):
                print('.', end='', flush=True)
                full_path = os.path.join(dirpath, filename)

                try:
                    with open(full_path, 'r', encoding='utf-8') as file:
                        content = file.read()

                    imports = extract_imported_packages(content)
                    detected_libraries.update(imports)
                except (UnicodeDecodeError, IOError):
                    # Skip files that can't be read or parsed
                    continue

    # Filter out standard library modules if configured
    if settings['exclude_standard_modules']:
        if not settings['python_version']:
            settings['python_version'] = f"{sys.version_info.major}.{sys.version_info.minor}"

        # Get standard library modules for Python 3.4
        standard_modules = stdlib_list("3.4")
        detected_libraries = {lib for lib in detected_libraries if lib not in standard_modules}

    return list(detected_libraries)

