def test_position_tolerance(
    models_close,
    inas_input,  # pylint: disable=redefined-outer-name
    inas_symmetries,  # pylint: disable=redefined-outer-name
    sample,
):
    """
    Test the 'position_tolerance' argument in the 'symmetrize' method.
    """
    modified_input = copy.deepcopy(inas_input)
    reference_with_shift = tbmodels.io.load(sample("InAs_sym_reference.hdf5"))

    # Apply small positional shift to both models
    modified_input.pos[0] += 0.01
    reference_with_shift.pos[0] += 0.01

    # First attempt without tolerance - should fail
    with pytest.raises(tbmodels.exceptions.TbmodelsException):
        result_model = modified_input
        for sym_op in inas_symmetries:
            if hasattr(sym_op, "full_group"):
                result_model = result_model.symmetrize(
                    sym_op.symmetries, 
                    full_group=sym_op.full_group
                )
            else:
                result_model = result_model.symmetrize([sym_op], full_group=False)

    # Second attempt with position_tolerance - should succeed
    result_model = modified_input
    for sym_op in inas_symmetries:
        if hasattr(sym_op, "full_group"):
            result_model = result_model.symmetrize(
                sym_op.symmetries, 
                full_group=sym_op.full_group,
