from collections import OrderedDict

def _convert_sheets_to_lists(data):
    columns = OrderedDict()
    if not data or len(data) == 0:
        return [], None

    # Extract column names from first row (if list) and subsequent dicts
    if isinstance(data[0], list):
        for item in data[0]:
            columns[item] = True

    # Process remaining rows to collect all possible keys
    for row in data:
        if isinstance(row, dict):
            for key in row.keys():
                columns[key] = True

    # Convert to list of column names
    col_list = list(columns.keys())

    # Build output table
    result_rows = []
    has_valid_row = False

    for row in data:
        current_row = []
        for col in col_list:
            value = row.get(col, '') if isinstance(row, dict) else ''
            if value is None:
                value = ''
            current_row.append(value)

        if len(current_row) > 0:
            has_valid_row = True

        result_rows.append(current_row)

    return col_list, result_rows if has_valid_row else None

def ss_structure_to_mdtable(spreadsheet_data):
    """
    Converts a dictionary or OrderedDict containing spreadsheet-like data 
    into a markdown document with tables.
    """
    try:
        import tabulate
    except ImportError:
        raise ImportError("tabulate module is required for this function")

    result_sections = []

    def format_cell(cell_value):
        return '' if cell_value is None else str(cell_value)

    for sheet_name, sheet_content in spreadsheet_data.items():
        headers, processed_content = _convert_sheets_to_lists(sheet_content)

        if processed_content:
            # Add section header
            result_sections.append(f'# {sheet_name}')

            # Convert content using tabulate with orgtbl format
            table = tabulate.tabulate(
                [list(map(format_cell, row)) for row in processed_content],
                headers=list(map(format_cell, headers)),
                tablefmt="orgtbl"
            )
            result_sections.append(table)

    return '\n\n'.join(result_sections)

