# Custom parser for Django SQL query transformation, extending version 19 base parser

from django.db.models.expressions import Star
from django.db.models.sql.datastructures import EmptyResultSet
from django.db.models.sql.where import SubqueryConstraint
from .version_19 import Parser as BaseParser

class ExtendedQueryParser(BaseParser):
    def _setup_for_transformation(self):
        from django.db.models.sql.where import EmptyWhere
        # Handle empty WHERE clause by raising EmptyResultSet if needed
        if isinstance(self.django_query.where, EmptyWhere):
            raise EmptyResultSet()

    def _process_leaf_node(self, node, is_negated, updated_parent, join_type, model_instance, sql_compiler):
        # Skip processing for subqueries (handled elsewhere)
        if not isinstance(node, SubqueryConstraint):
            # Check for empty Q() objects (leaf nodes without lhs/rhs attributes)
            if not hasattr(node, "lhs") and not hasattr(node, "rhs"):
                return

        # Delegate to parent implementation for remaining cases
        return super(ExtendedQueryParser, self)._process_leaf_node(
            node, is_negated, updated_parent, join_type, model_instance, sql_compiler
        )

    def _classify_query_type(self):
        current_query = self.django_query

        # Determine if this is a COUNT query based on annotations
        if current_query.annotations:
            if "__count" in current_query.annotations:
                field_info = current_query.annotations["__count"].input_field
                if isinstance(field_info, Star) or getattr(field_info, "value", None) == "*":
                    return "COUNT"

        # Default to SELECT for regular queries
        return "SELECT"

# Reimplementation with equivalent functionality but different structure and variable names

import json
import os
import click
from difflib import SequenceMatcher

# Determine base directory path
BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LOCALE_FILE_PATH = os.path.join(BASE_DIR, "app/locales/taiga/locale-en.json")

def flatten_dict_keys(prefix, data):
    """Recursively extract key-value pairs from nested dictionaries."""
    results = []

    if prefix is None:
        # Top-level processing: iterate over top-level keys
        for root_key in data:
            results.extend(flatten_dict_keys([root_key], data[root_key]))
    elif isinstance(data, dict):
        # Nested dictionary: recurse into sub-dictionaries
        for sub_key in data:
            new_prefix = prefix + [sub_key]
            results.extend(flatten_dict_keys(new_prefix, data[sub_key]))
    else:
        # Leaf node: store the full key path and value
        results.append((".".join(prefix), data))

    return results

@click.command()
@click.option('--similarity-threshold', default=1.0, help='Minimum similarity ratio required')
@click.option('--min-string-length', default=10, help='Minimum string length to consider')
@click.option('--skip-identical', is_flag=True, default=False, help='Exclude exact matches')
def check_duplicate_translations(similarity_threshold, min_string_length, skip_identical):
    """Find similar translation strings in locale files."""

    # Load locale data
    with open(LOCALE_FILE_PATH, 'r', encoding='utf-8') as f:
        translations = json.load(f)

    # Extract all key-value pairs
    translation_pairs = flatten_dict_keys(None, translations)

    # Track processed pairs to avoid duplicates
    processed_pairs = set()

    # Compare each pair of translations
    for idx1, (path1, text1) in enumerate(translation_pairs):
        for idx2, (path2, text2) in enumerate(translation_pairs):
            # Skip identical keys
            if path1 == path2:
                continue

            # Skip short strings unless one meets minimum length
            if len(text1) < min_string_length and len(text2) < min_string_length:
                continue

            # Calculate similarity
            matcher = SequenceMatcher(None, text1, text2)
            ratio = matcher.ratio()

            # Apply filters
            if skip_identical and ratio == 1.0:
                continue

            if ratio >= similarity_threshold:
                # Avoid duplicate reporting
                pair_tuple = (path1, path2)
                reverse_pair = (path2, path1)

                if pair_tuple not in processed_pairs and reverse_pair not in processed_pairs:
                    processed_pairs.add(pair_tuple)
                    processed_pairs.add(reverse_pair)

                    click.echo(
                        "The keys {} and {} have a similarity of {:.4f}\n - {}\n - {}".format(
                            path1,
                            path2,
                            ratio,
                            text1,
                            text2
                        )
                    )

if __name__ == "__main__":
    check_duplicate_translations()

