from grammpy import Grammar
from .NongeneratingSymbolsRemove import remove_nongenerating_symbols
from .UnreachableSymbolsRemove import remove_unreachable_symbols

class ContextFree:
    @staticmethod
    def eliminate_non_generating(grammar: Grammar, update_grammar=False):
        return remove_nongenerating_symbols(grammar, update_grammar)

    @staticmethod
    def check_if_generating(grammar: Grammar, update_grammar=False, apply_removal=True):
        g = grammar
        if apply_removal:
            g = ContextFree.eliminate_non_generating(grammar, update_grammar=update_grammar)
        return g.start_get() in g.nonterms()

    @staticmethod
    def eliminate_unreachable(grammar: Grammar, update_grammar=False):
        return remove_unreachable_symbols(grammar, update_grammar)

    @staticmethod
    def clean_grammar(grammar: Grammar, update_grammar=False, *,
                      skip_unreachable_check=False,
                      skip_non_generating_check=False) -> Grammar:
        result = grammar
        if not skip_non_generating_check:
            result = ContextFree.eliminate_non_generating(result, update_grammar=update_grammar)
            update_grammar = False
        if not skip_unreachable_check:
            result = ContextFree.eliminate_unreachable(result, update_grammar=update_grammar)
        return result

