from importlib import import_module

def execute_harvester(source_name, **kwargs):
    module_path = "mdf_indexers.harvesters." + source_name + "_harvester"
    harvester_module = import_module(module_path)
    harvester_module.harvest(**kwargs)

def process_converter(sources, input_path=None, metadata=None, verbose=False):
    # Ensure sources is always a list
    if not isinstance(sources, list):
        sources = [sources]

    if verbose:
        print("CONVERTING THE FOLLOWING DATASETS:", sources)

    for src in sources:
        if verbose:
            print("\nCONVERTER FOR", src, "\n")

        module_path = "mdf_indexers.converters." + src + "_converter"
        converter_module = import_module(module_path)

        # Set default input path if not provided
        if input_path is None:
            input_path = "mdf_indexers/datasets/" + src + "/"

        converter_module.convert(
            input_path=input_path, 
            metadata=metadata, 
            verbose=verbose
        )

    if verbose:
        print("\nALL CONVERTING COMPLETE")

if __name__ == "__main__":
    import sys

    if len(sys.argv) > 1:
        # Pass command-line arguments to process_converter
        args = sys.argv[1:]
        # Convert string 'True'/'False' to boolean for verbose flag if present
        processed_args = []
        for arg in args:
            if arg == 'True':
                processed_args.append(True)
            elif arg == 'False':
                processed_args.append(False)
            else:
                processed_args.append(arg)
        process_converter(*processed_args)
    else:
        process_converter()

