# Reusable message sender implementation that handles message splitting and editing

from bot.api.domain import Message
from bot.logger.message_sender import MessageSender
from bot.logger.message_sender.api import ApiMessageSender
from bot.logger.message_sender.message_builder import MessageBuilder


class AdaptiveMessageSender(MessageSender):
    def __init__(self, api_sender: ApiMessageSender, text_builder: MessageBuilder, max_size: int = 4000):
        self.api_sender = api_sender
        self.text_builder = text_builder
        self.max_size = max_size
        self.current_message_id = None

    def deliver(self, content):
        prepared_message = self._prepare_message(content)
        self._select_send_method()(prepared_message)

    def _prepare_message(self, content):
        self.text_builder.append(content)
        self._validate_size(content)
        return self.text_builder.build()

    def _validate_size(self, content):
        if self.text_builder.size() > self.max_size:
            self.reset()
            # If size still exceeds limit after reset, allow failure to prevent infinite loop
            self.text_builder.append(content)

    def _select_send_method(self):
        return self._send_initial_message if self.current_message_id is None else self._send_update_message

    def _send_initial_message(self, message: Message):
        try:
            self.current_message_id = self.api_sender.send(message)
        except Exception:
            # On any error during initial send, discard current state to avoid inconsistency
            # This ensures next operation starts fresh without risk of duplicate or corrupted messages
            self.reset()
            raise
        finally:
            if self.current_message_id is None:
                self.reset()

    def _send_update_message(self, message: Message):
        self.api_sender.update(message, self.current_message_id)

    def reset(self):
        self.text_builder.clear()
        self.current_message_id = None

