from resolwe.flow.utils import iterate_fields

def remove_unused_data_dependencies(apps, schema_editor):
    Data = apps.get_model("flow", "Data")
    DataDependency = apps.get_model("flow", "DataDependency")

    # Iterate through all data objects to collect current valid parent IDs
    for data_record in Data.objects.iterator():
        current_parent_ids = []

        # Process input fields to extract data dependencies
        for field_spec, field_values in iterate_fields(
            data_record.input, data_record.process.input_schema
        ):
            field_name = field_spec["name"]
            field_value = field_values[field_name]

            # Handle single data reference
            if field_spec.get("type", "").startswith("data:"):
                current_parent_ids.append(field_value)
            # Handle list of data references
            elif field_spec.get("type", "").startswith("list:data:"):
                current_parent_ids.extend(field_value)

        # Filter out non-existent parent records
        current_parent_ids = [
            pk if Data.objects.filter(pk=pk).exists() else None 
            for pk in current_parent_ids
        ]

        # Check existing dependencies and remove obsolete ones
        for dependency in DataDependency.objects.filter(
            child=data_record.id, kind="io"
        ):
            parent_id = dependency.parent.pk if dependency.parent else None

            # Keep dependency if it's still valid, otherwise delete
            if parent_id in current_parent_ids:
                current_parent_ids.remove(parent_id)
            else:
                dependency.delete()

