import numpy as np

class ActivationFunction:
    @staticmethod
    def sigmoid(x, calculate_derivative=False):
        if calculate_derivative:
            return x * (1 - x)
        return 1 / (1 + np.exp(-x))

    @staticmethod
    def tanh(x, calculate_derivative=False):
        if calculate_derivative:
            return 1 - np.tanh(x) ** 2
        return np.tanh(x)

    @staticmethod
    def elu(x, calculate_derivative=False, scale=1.0):
        positive_part = (x >= 0).astype(float) * x
        negative_part = (x < 0).astype(float) * (scale * (np.exp(np.clip(x, -500, 500)) - 1))
        result = positive_part + negative_part

        if calculate_derivative:
            derivative_positive = (x >= 0).astype(float)
            derivative_negative = (x < 0).astype(float) * (result + scale)
            return derivative_positive + derivative_negative

        return result

    @staticmethod
    def softmax(x, calculate_derivative=False):
        # Numerical stability: subtract max value
        shifted_x = x - np.max(x, axis=1, keepdims=True)
        exp_x = np.exp(shifted_x)
        probabilities = exp_x / np.sum(exp_x, axis=1, keepdims=True)

        if calculate_derivative:
            # Compute Jacobian diagonal for numerical efficiency
            batch_size, num_classes = probabilities.shape
            jacobian_diag = np.zeros((batch_size, num_classes))

            # Diagonal elements: p_i * (1 - p_i)
            jacobian_diag = probabilities * (1 - probabilities)

            return jacobian_diag

        return probabilities

