import discord
import requests
from discord.ext import commands

class ProxyValidator:
    """Cog for validating proxy servers"""

    def __init__(self, bot_instance):
        self.bot = bot_instance

    @commands.command(name="checkproxy", pass_context=True)
    async def validate_proxy(self, ctx, proxy_address):
        """Validates the provided proxy server."""
        proxy = proxy_address
        proxies = {
            'http': proxy,
            'https': proxy
        }

        try:
            response = requests.get(
                'https://pgorelease.nianticlabs.com/plfe/version',
                proxies=proxies,
                timeout=5
            )

            if response.status_code == 200:
                await self.bot.say(':white_check_mark: 200 OK, proxy is not banned.')
            elif response.status_code == 403:
                await self.bot.say(':x: 403 Forbidden, proxy is banned.')

        except requests.exceptions.Timeout:
            await self.bot.say(':x: Timed out checking proxy.')
        except requests.exceptions.RequestException:
            await self.bot.say('Something is wrong with your proxy. Make sure to put the port as well as remove http or https from your input. Authentication is not supported right now.')

        # Delete command message in public channels
        if not ctx.message.channel.is_private:
            await self.bot.delete_message(ctx.message)

def setup(bot):
    bot.add_cog(ProxyValidator(bot))

