def reverse(seq):
    """Return the reverse of the given sequence (i.e. 3' to 
    5')."""
    return seq[::-1]

def complement(seq):
    """Return the complement of the given sequence (i.e. G=>C, 
    A=>T, etc.)"""
    # Using a dictionary-based translation instead of string.maketrans
    comp_map = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C',
                'a': 't', 't': 'a', 'c': 'g', 'g': 'c'}
    return ''.join(comp_map.get(nuc, nuc) for nuc in seq)

def reverse_complement(seq):
    """Return the reverse complement of the given sequence 
    (e.g.  the opposite strand)."""
    return complement(reverse(seq))

# Fixed version: handle empty sequences and use float division
def gc_content(seq):
    """Return the GC content of the given sequence (e.g. the 
    fraction of nucleotides that are either G or C)."""
    if len(seq) == 0:
        return 0.0
    return sum(1 for x in seq if x.upper() in 'GC') / float(len(seq))

