    def __init__(self, bounding_box, field_type=FieldType.STRING, mandatory=False,
                 label=None):
        self.bounding_box = bounding_box
        self.field_type = field_type
        self.mandatory = mandatory
        self.label = label

class Schema(object):
    @classmethod
    def get_pdf_selectors(cls, target_field=None):
        """Generate pdfminer selectors for specified field. If no field is
        provided, return selectors for all fields in the schema.
        """
        if target_field is not None:
            field = getattr(cls, target_field, None)
            if (field is None) or (not isinstance(field, Field)):
                raise ValueError(
                    f"'{target_field}' is not a valid Field attribute on {cls.__name__}"
                )
            field_list = [('document_year', field)]
        else:
            field_list = inspect.getmembers(
                cls, lambda item: isinstance(item, Field)
            )

        base_selectors = [('convert_text', 'text')]
        base_selectors.extend(
            (name, f'LTTextLineHorizontal:in_bbox("{",".join(str(val) for val in field.bounding_box)}")')
            for name, field in field_list
        )
        return base_selectors

class PaperDocument(object):
    options = []

    def __init__(self, source_file):
        # Initialize with PDFQuery instance
        self._source = PDFQuery(source_file)
        self._content = {}
        self._validate_setup()

    @property
    def content(self):
        """Read-only property containing extracted data after extraction."""
        return self._content

    def identify_variant(self):
        raise NotImplementedError('Subclass PaperDocument and implement this method')

    def process(self):
        self._source.load()
        selected_schema = self.identify_variant()
        query_selectors = selected_schema.get_pdf_selectors()
        results = self._source.extract(query_selectors)
        self._content = results

    def _validate_setup(self):
        if not self.options:
            raise ValueError(
                f"Class '{self.__class__.__name__}' requires at least one variant. "
                "Assign a list of Schema subclasses to {self.__class__.__name__}.options"
            )

