import json
import requests
import six

class SlackApiCaller(object):
    @staticmethod
    def execute(token, api_method="?", payload=None, base_url="slack.com"):
        '''
        Execute a POST request to the Slack Web API

        Args:
            token (str): your authentication token
            api_method (str): the Slack API method to invoke. For example: 'channels.list'
            payload (dict): key-value pairs to include in the request body. For example:
                {'channel': 'CABC12345'}
            base_url (str): override the default domain if needed
        '''
        payload = payload or {}

        # Handle file uploads separately from JSON data
        upload_endpoints = ['files.upload']
        file_data = None

        if api_method in upload_endpoints:
            if 'file' in payload:
                file_data = {'file': payload.pop('file')}

        # Convert non-string values to JSON strings
        for key, value in six.iteritems(payload):
            if not isinstance(value, six.string_types):
                payload[key] = json.dumps(value)

        # Construct the full API URL
        endpoint_url = f'https://{base_url}/api/{api_method}'
        payload['token'] = token

        # Send the HTTP POST request
        return requests.post(endpoint_url, data=payload, files=file_data)

# Alternative implementation using dictionary-based mapping for pattern matching
def wordPattern(pattern, s):
    words = s.split()

    # Early exit if lengths don't match
    if len(pattern) != len(words):
        return False

    # Create mappings from pattern characters to words and vice versa
    char_to_word = {}
    word_to_char = {}

    for i in range(len(pattern)):
        p_char = pattern[i]
        w_word = words[i]

        # Check if pattern character already has a mapping
        if p_char in char_to_word:
            if char_to_word[p_char] != w_word:
                return False
        else:
            char_to_word[p_char] = w_word

        # Check if word already has a mapping
        if w_word in word_to_char:
            if word_to_char[w_word] != p_char:
                return False
        else:
            word_to_char[w_word] = p_char

    return True

