import os
import sys
import json
import yaml

def combine_dictionaries(base_dict, update_dict):
    # Validate that both inputs are dictionaries
    if not (isinstance(base_dict, dict) and isinstance(update_dict, dict)):
        raise ValueError("Error combining variables: '{}' and '{}'".format(
            type(base_dict).__name__, type(update_dict).__name__
        ))

    # Start with a copy of the base dictionary
    combined = base_dict.copy()

    # Iterate through all key-value pairs in the update dictionary
    for key, value in update_dict.items():
        # If both the existing value and new value are dictionaries, merge recursively
        if isinstance(combined.get(key), dict):
            combined[key] = combine_dictionaries(combined[key], update_dict[key])
        else:
            # Otherwise, overwrite or add the value
            combined[key] = value

    return combined

def read_manifest_file(manifest_path):
    # Load the manifest file using YAML
    with open(manifest_path, 'r') as file_handle:
        manifest_data = yaml.safe_load(file_handle)

    # Handle inheritance if specified
    if 'inherit' in manifest_data:
        inherited_file_path = os.path.join(
            os.path.dirname(manifest_path), 
            manifest_data.pop('inherit')
        )
        # Recursively load and merge inherited manifest
        manifest_data = combine_dictionaries(
            read_manifest_file(inherited_file_path), 
            manifest_data
        )

    return manifest_data

def process_variable_files(variable_files_list):
    # Initialize empty variables dictionary
    variables = {}

    # Process each variable file
    for var_file in variable_files_list:
        with open(var_file, 'r') as file_handle:
            file_vars = json.load(file_handle)
            # Merge with existing variables
            variables = combine_dictionaries(variables, file_vars)

    # Transform keys to uppercase and serialize complex types
    transformed_vars = {}
    for key, value in variables.items():
        upper_key = key.upper()
        if isinstance(value, (dict, list)):
            transformed_vars[upper_key] = json.dumps(value)
        else:
            transformed_vars[upper_key] = value

    return transformed_vars

def generate_paas_manifest(manifest_path, *variable_files):
    """Create a PaaS manifest by merging template with variables"""
    # Load the base manifest
    base_manifest = read_manifest_file(manifest_path)

    # Load and process variable files
    processed_variables = process_variable_files(variable_files)

    # Update environment section with processed variables
    if 'env' not in base_manifest:
        base_manifest['env'] = {}
    base_manifest['env'].update(processed_variables)

    # Return formatted YAML string
    return yaml.dump(
        base_manifest, 
        default_flow_style=False, 
        allow_unicode=True,
        sort_keys=False
    )

if __name__ == "__main__":
    # Execute when run as script
    print(generate_paas_manifest(*sys.argv[1:]))

