def extract_keywords(prefix, data):
    """
    Recursively extract dot-separated keywords from nested dictionary structure.
    Returns a list of keyword strings.
    """
    result = []

    if prefix is not None:
        if isinstance(data, dict):
            # Traverse nested dictionary
            for key in data:
                new_prefix = prefix + [key]
                result.extend(extract_keywords(new_prefix, data[key]))
        else:
            # Base case: non-dict value with existing prefix
            result.append(".".join(prefix))
    else:
        # Starting point: no prefix yet
        if isinstance(data, dict):
            for key in data:
                result.extend(extract_keywords([key], data[key]))

    return result

def read_file_content(filepath):
