import sys
import logging
from modularodm import Q
from framework.transactions.context import TokuTransaction
from scripts import utils as script_utils
from website.app import init_app
from website.project.model import Node, NodeLog

logger = logging.getLogger(__name__)

def process_duplicate_logs():
    # Identify nodes that have more than one 'preprint_license_updated' log
    all_log_nodes = [l.node._id for l in NodeLog.find(Q('action', 'eq', 'preprint_license_updated'))]
    unique_node_ids = list(set(all_log_nodes))

    problematic_nodes = []
    for node_id in unique_node_ids:
        count = NodeLog.find(Q('action', 'eq', 'preprint_license_updated') & Q('node', 'eq', node_id)).count()
        if count > 1:
            node_obj = Node.load(node_id)
            if node_obj:
                problematic_nodes.append(node_obj)

    logger.info('Detected {} nodes with duplicate preprint_license_updated entries'.format(len(problematic_nodes)))

    for target_node in problematic_nodes:
        # Collect all relevant logs for this node
        relevant_logs = [log for log in target_node.logs if log.action == 'preprint_license_updated']

        # Sort logs by date descending to process most recent first
        relevant_logs.sort(key=lambda x: x.date, reverse=True)

        current_log = relevant_logs.pop(0) if relevant_logs else None

        while relevant_logs and current_log:
            next_log = relevant_logs.pop(0)
            time_diff = current_log.date - next_log.date

            if abs(time_diff.total_seconds()) < 1:
                logger.info(
                    'Marking duplicate log (ID: {}) from node {} as hidden; time gap: {}'.format(
                        current_log._id, target_node._id, time_diff
                    )
                )
                current_log.should_hide = True
                current_log.save()
            else:
                logger.info(
                    'Preserving log (ID: {}) from node {}; time gap: {}'.format(
                        current_log._id, target_node._id, time_diff
                    )
                )

            current_log = next_log

def run_migration(dry_run=True):
    init_app(set_backends=True, routes=False)

    with TokuTransaction():
        process_duplicate_logs()

        if dry_run:
            raise Exception('Rollback Transaction - Simulation Mode')

if __name__ == '__main__':
    is_dry = '--dry' in sys.argv

    if not is_dry:
        script_utils.add_file_logger(logger, __file__)

    # Configure logging level based on command-line arguments
    if 'debug' in sys.argv:
        logger.setLevel(logging.DEBUG)
    elif 'warning' in sys.argv:
        logger.setLevel(logging.WARNING)
    elif 'info' in sys.argv:
        logger.setLevel(logging.INFO)
    elif 'error' in sys.argv:
        logger.setLevel(logging.ERROR)

    run_migration(dry_run=is_dry)

import json
import aioredis
from kyokai import Request
from kyokai.context import HTTPRequestContext

async def cached_execution(ctx: HTTPRequestContext, handler_func, *handler_args, ttl=300):
    """
    Execute an async function with Redis caching support.
    Caches the result using a composite key derived from function name and arguments.
    """
    assert isinstance(ctx.redis, aioredis.Redis)

    # Generate cache key from function name and argument representation
    cache_key = handler_func.__name__ + repr(handler_args)

    # Try to retrieve cached result
    cached_value = await ctx.redis.get(cache_key)
    if cached_value is not None:
        return cached_value.decode('utf-8')

    # Execute the handler function when cache miss occurs
    execution_result = await handler_func(ctx, *handler_args)

    # Store the result in Redis with expiration time
    await ctx.redis.set(cache_key, execution_result, ex=ttl)

    return execution_result

def json_response_decorator(handler_func):
    """
    Decorator to automatically convert function results to JSON responses.
    Adds request metadata to all responses.
    """
    async def wrapped_handler(ctx: HTTPRequestContext):
        # Execute the original handler function
        raw_result = await handler_func(ctx)

        # Ensure we have access to the request object
        assert isinstance(ctx.request, Request)

        # Prepare base response structure with request metadata
        base_response = {
            "_request": {
                "route": ctx.request.path,
                "api_version": 1
            }
        }

        # Handle different response formats
        if isinstance(raw_result, tuple):
            # Merge base response with first element of tuple
            merged_response = {**base_response, **raw_result[0]}

            # Format response based on tuple length
            if len(raw_result) == 1:
                return json.dumps(merged_response), 200, {"Content-Type": "application/json"}
            elif len(raw_result) == 2:
                return json.dumps(merged_response), raw_result[1], {"Content-Type": "application/json"}
            else:
                # Combine additional headers with default JSON header
                extra_headers = dict(raw_result[2]) if len(raw_result) > 2 else {}
                combined_headers = {**{"Content-Type": "application/json"}, **extra_headers}
                return json.dumps(merged_response), raw_result[1], combined_headers
        else:
            # Single value response - merge directly with base response
            final_response = {**base_response, **raw_result}
            return json.dumps(final_response), 200, {"Content-Type": "application/json"}

    return wrapped_handler

