import functools
from pyp2rpm import settings

def cache_by_arguments(func):
    """Caches return value of a function based on its positional arguments."""
    cache = {}
    @functools.wraps(func)
    def wrapped(*args):
        if args not in cache:
            result = func(*args)
            cache[args] = result
        return cache[args]
    return wrapped

def derive_license_from_classifiers(classifier_list):
    """Extracts license information from a list of PyPI trove classifiers.

    Args:
        classifier_list: list of trove classifier strings

    Returns:
        A string containing the Fedora-compatible license name(s), joined with ' and ',
        or an empty string if no valid license classifiers are found.
    """
    licenses_found = []
    for item in classifier_list:
        if item is None:
            continue
        # Check if 'License' appears in the classifier (case-sensitive)
        idx = item.find('License')
        if idx != -1:
            cleaned = item.strip()
            # Remove leading 'Classifier:' if present (common in EGG-INFO metadata)
            if cleaned.startswith('Classifier:'):
                cleaned = cleaned[len('Classifier:'):]
            # Extract substring starting from 'License'
            license_part = cleaned[idx:]
            if license_part in settings.TROVE_LICENSES:
                licenses_found.append(settings.TROVE_LICENSES[license_part])
    return ' and '.join(licenses_found)

