    @property
    def category(self):
        type_str = str(type(self))
        cleaned = type_str.strip("'<>")
        parts = cleaned.split('.')
        return parts[-1] if parts else "Problem"

    @property
    def best_solution(self):
        return self.get_solutions().first()

    def add_constraint(self, predicate):
        self._filter_functions.append(predicate)
        # Clear cached solutions when constraints change
        self._cached_solutions = None

    def get_solutions(self):
        if self._cached_solutions is None:
            raw_results = self._compute_candidates()

            # Filter results based on all constraints
            filtered_items = {}
            for key, value in raw_results.items():
                if all(check(key, value) for check in self._filter_functions):
                    filtered_items[key] = value

            self._cached_solutions = meta.Meta(filtered_items)

        return self._cached_solutions

