# Enhanced palindrome generator that finds the next palindrome greater than the input number

def generate_next_palindrome(number_str):
    digits = list(number_str)
    length = len(digits)
    center = length // 2

    # Try to mirror the left half to the right half first
    attempt_mirroring = True
    for idx in range(center, length):
        opposite_idx = length - 1 - idx
        if digits[idx] < digits[opposite_idx]:
            attempt_mirroring = False
            break
        elif digits[idx] > digits[opposite_idx]:
            break

    # If mirroring produces a larger number, use it directly
    if attempt_mirroring:
        for pos in range(center, length):
            mirror_pos = length - 1 - pos
            digits[pos] = digits[mirror_pos]
        return ''.join(digits)

    # Otherwise, increment the middle part and mirror
    mid_left = (length - 1) // 2
    while mid_left >= 0 and digits[mid_left] == '9':
        mid_left -= 1

    if mid_left >= 0:
        incremented_value = str(int(digits[mid_left]) + 1)
        digits[mid_left] = incremented_value

        # Set all positions after the incremented digit to '0' up to the middle
        for pos in range(mid_left + 1, (length + 1) // 2):
            digits[pos] = '0'

        # Mirror the left half to the right half
        for pos in range((length + 1) // 2, length):
            mirror_pos = length - 1 - pos
            digits[pos] = digits[mirror_pos]
    else:
        # Special case: all 9s (e.g., "999" -> "1001")
        digits = ['0'] * (length + 1)
        digits[0] = digits[-1] = '1'

    return ''.join(digits)

if __name__ == '__main__':
    test_cases = int(input())
    for _ in range(test_cases):
        original_number = input().strip()
        result = generate_next_palindrome(original_number)
        print(result)

import ddt
import polib
from unittest import TestCase
from i18n.config import CONFIGURATION, LOCALE_DIR

@ddt.ddt
class TestCompiledMessages(TestCase):
    """
    Verify consistency between .po and compiled .mo translation files
    """
    SOURCE_PO_FILES = ['django.po', 'djangojs.po']

    @ddt.data(*CONFIGURATION.locales)
    def test_translated_messages(self, locale):
        # Construct paths for message files
        locale_dir = LOCALE_DIR / locale / 'LC_MESSAGES'

        for po_filename in self.SOURCE_PO_FILES:
            po_file_path = locale_dir / po_filename
            mo_file_path = po_file_path.with_suffix('.mo')

            # Load both PO and MO files
            po_data = polib.pofile(po_file_path)
            mo_data = polib.mofile(mo_file_path)

            # Create dictionaries of translated entries keyed by msgid
            po_entries_dict = {
                entry.msgid: entry 
                for entry in po_data.translated_entries()
            }
            mo_entries_dict = {
                entry.msgid: entry 
                for entry in mo_data.translated_entries()
            }

            # Ensure both files contain the same set of msgids
            self.assertEqual(set(po_entries_dict.keys()), set(mo_entries_dict.keys()))

            # Compare corresponding entries field by field
            for msg_id, po_entry in po_entries_dict.items():
                mo_entry = mo_entries_dict[msg_id]

                # Fields to compare between entries
                comparison_attrs = [
                    'msgstr', 'msgid_plural', 'msgstr_plural',
                    'msgctxt', 'obsolete', 'encoding'
                ]

                for field_name in comparison_attrs:
                    po_value = getattr(po_entry, field_name)
                    mo_value = getattr(mo_entry, field_name)

                    # Normalize plural forms: MO uses int keys, PO uses string keys
                    if field_name == 'msgstr_plural':
                        po_value = {int(k): v for k, v in po_value.items()}

                    # Assert equality with descriptive error message
                    self.assertEqual(
                        po_value,
                        mo_value,
                        f"Mismatch in '{field_name}' for entry '{msg_id}': "
                        f"PO value '{po_value}' differs from MO value '{mo_value}'"
                    )

