    abs_path = os.path.abspath(full_path)

    if not os.path.isfile(abs_path):
        return False, {"error": f"Function check file '{doc_file_name}' does not exist."}

    try:
        marker_list = fc.get_unity_chip_doc_marks(abs_path, "CK", 1)
    except Exception as exc:
        err_msg = str(exc)
        warning(f"Exception during parsing '{doc_file_name}': {err_msg}")
        warning(traceback.format_exc())

        error_report = [
            f"Documentation parsing failed for '{doc_file_name}': {err_msg}."
        ]
        if "\\n" in err_msg:
            error_report.append("Literal '\\n' found — replace with actual newlines.")
        error_report.extend([
            "Malformed tags: Use proper format like <FG-NAME>, <FC-NAME>, <CK-NAME>",
            *fc.description_func_doc(),
            "Invalid characters: Only alphanumeric and hyphens allowed in tag names",
            "Missing closing tags: All XML-style tags must be properly closed",
            "Encoding issue: Ensure file is UTF-8 encoded.",
        ])
        return False, {"error": error_report}

    return True, marker_list


def validate_line_mapping_for_single_file(
    workspace,
    src_file,
    map_file=None,
    ck_markers=None,
    ck_file_name=None,
    map_file_suffix="_line_func_map.txt",
    map_dir="line_map",
    max_examples=20,
    enforce_no_mismatches=False,
    on_unmatched_callback=None,
    on_matched_callback=None
):
    """Verify line-to-function mapping consistency for one source file."""
    info(f"Validating line-to-function mapping for '{src_file}'...")
    abs_src_path = os.path.abspath(os.path.join(workspace, src_file))

    if not os.path.isfile(abs_src_path):
        return False, {"error": f"Source file '{src_file}' not found."}

    # Determine mapping file path if not explicitly given
    if not map_file:
        base_name = src_file.replace(os.sep, "_").replace(".", "_")
        map_file = os.path.join(map_dir, base_name + map_file_suffix)

    abs_map_path = os.path.abspath(os.path.join(workspace, map_file))
    if not os.path.isfile(abs_map_path):
        return False, {"error": f"Mapping file '{map_file}' missing. Generate it first."}

    try:
        line_to_marker = fc.parse_line_CK_map_file(workspace, abs_map_path)
    except Exception as parse_err:
        err_str = str(parse_err)
        warning(f"Parsing mapping file '{map_file}' failed: {err_str}")
        warning(traceback.format_exc())
        return False, {"error": f"Failed to parse mapping file '{map_file}': {err_str}"}

    # Analyze discrepancies between expected markers and actual mappings
    unmatched_entries = []
    mismatched_entries = []
    unexpected_keys = []

    for key, value in line_to_marker.items():
        if key.startswith("IGNORE/"):
            continue
        elif key.startswith("MISSMT/"):
            mismatched_entries.append((key, value))
            continue
        elif key not in ck_markers:
            unexpected_keys.append((key, value))
            if on_unmatched_callback:
                on_unmatched_callback(key, value)
        else:
            if on_matched_callback:
                on_matched_callback(key, value)

    # Report unexpected keys (non-matching CKs)
    if unexpected_keys:
        msg_prefix = [f"{len(unexpected_keys)} unmapped line block(s) in '{map_file}' lack corresponding CK tags:"]
        for idx, (ck_tag, _) in enumerate(unexpected_keys[:max_examples]):
            msg_prefix.append(f"  '{ck_tag}' absent in '{ck_file_name}'.")
        if len(unexpected_keys) > max_examples:
            msg_prefix.append(f"  ... plus {len(unexpected_keys) - max_examples} more.")
        msg_prefix.append("Available CKs:")
        for idx, marker in enumerate(ck_markers[:max_examples]):
            msg_prefix.append(f"  '{marker}'")
        if len(ck_markers) > max_examples:
            msg_prefix.append(f"  ... plus {len(ck_markers) - max_examples} more.")
        return False, {"error": msg_prefix}

    # Enforce no mismatches if required
    if enforce_no_mismatches and mismatched_entries:
        msg_prefix = [f"{len(mismatched_entries)} MISSMT entries in '{map_file}' require resolution:"]
        for idx, (ck_tag, _) in enumerate(mismatched_entries[:max_examples]):
            msg_prefix.append(f"  '{ck_tag}' not present in '{ck_file_name}'.")
        if len(mismatched_entries) > max_examples:
            msg_prefix.append(f"  ... plus {len(mismatched_entries) - max_examples} more.")
        msg_prefix.append("Either add missing CKs or fix mapping.")
        return False, {"error": msg_prefix}

    # Detect unmapped lines in source
    unmapped_lines, details = fc.get_un_mapped_lines(
        workspace, abs_src_path, line_to_marker, max_examples
    )
    if unmapped_lines:
        summary = f"Unmapped line blocks in '{src_file}':\n{details}"
        return False, {"error": summary}

    info(f"All lines in '{src_file}' successfully mapped.")
    return True, f"All lines in '{src_file}' are correctly mapped."


class FileLineMapChecker(Checker):
    """Checker for unmapped lines using line-to-function mapping."""
    def __init__(
        self,
        source_filename,
        func_doc_filename,
        map_filename=None,
        map_ext="_line_func_map.txt",
        map_folder="line_map",
        example_limit=20,
        human_review_required=False,
        strict_no_mismatch=False,
        **kwargs
    ):
        self.source_file = source_filename
        self.func_check_file = func_doc_filename
        self.map_file = map_filename
        self.map_suffix = map_ext
        self.map_location = map_folder
        self.max_example_lines = example_limit
        self.must_has_no_miss_match = strict_no_mismatch
        self.set_human_check_needed(human_review_required)

    def do_check(self, **options) -> tuple[bool, object]:
        """Execute the line mapping validation."""
        ok, result = retrieve_function_check_data(
            self.workspace, self.func_check_file
        )
        if not ok:
            return False, result

        return validate_line_mapping_for_single_file(
            workspace=self.workspace,
            src_file=self.source_file,
            map_file=self.map_file,
            ck_markers=result,
            ck_file_name=self.func_check_file,
            map_file_suffix=self.map_suffix,
            map_dir=self.map_location,
            max_examples=self.max_example_lines,
            enforce_no_mismatches=self.must_has_no_miss_match,
            on_unmatched_callback=None,
            on_matched_callback=None
        )

# Image processing pipeline utility using PIL/Pillow
from functools import wraps
from PIL import Image
from PIL import ImageEnhance
from PIL import ImageFilter
import click

@click.group(chain=True)
def image_pipeline():
    """Process multiple images through a sequence of transformations,
    similar to Unix pipes. Each command modifies or passes along images.

    Examples:
        imagepipe load -i photo1.jpg scale -w 256 show
        imagepipe load -i scene.png gaussian-blur export
    """

@image_pipeline.result_callback()
def execute_pipeline(steps):
    """Executes the chain of image processing steps by composing them
    together in the order they were specified on the command line.
    """
    # Initialize with an empty sequence
    data = iter([])

    # Apply each step sequentially
    for step in steps:
        data = step(data)

    # Consume all results to trigger side effects
    try:
        while True:
            next(data)
    except StopIteration:
        pass

def transform(func):
    """Decorator that converts a function into a stream transformer.
    The wrapped function receives a stream of images plus its own arguments.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        def apply_to_stream(image_stream):
            return func(image_stream, *args, **kwargs)
        return apply_to_stream
    return wrapper

def source(func):
    """Decorator for generator functions that produce new images.
    Yields original stream items first, then generates new ones.
    """
    @transform
    def wrapper(stream, *args, **kwargs):
        yield from stream
        yield from func(*args, **kwargs)
    return wrapper

def preserve_metadata(target, source_img):
    """Copies filename metadata from source to target image."""
    target.filename = getattr(source_img, 'filename', None)
    return target

@image_pipeline.command("load")
@click.option(
    "-i",
    "--input",
    "files",
    type=click.Path(exists=True),
    multiple=True,
    required=True,
    help="Input image file(s) to process."
)
@source
def load_images(files):
    """Load one or more image files for subsequent processing."""
    for filepath in files:
        try:
            click.echo(f"Loading '{filepath}'")
            if filepath == "-":
                img = Image.open(click.get_binary_stdin())
                img.filename = "-"
            else:
                img = Image.open(filepath)
                img.filename = filepath
            yield img
        except Exception as err:
            click.echo(f"Failed to load '{filepath}': {err}", err=True)

@image_pipeline.command("export")
@click.option(
    "--pattern",
    default="output_{:03}.png",
    type=click.Path(),
    help="Filename pattern for exported images.",
    show_default=True,
)
@transform
def save_images(images, pattern):
    """Save processed images to disk using the specified naming pattern."""
    for idx, img in enumerate(images):
        try:
            path = pattern.format(idx + 1)
            click.echo(f"Saving '{getattr(img, 'filename', 'image')}' as '{path}'")
            img.save(path)
            yield img
        except Exception as err:
            click.echo(f"Error saving '{getattr(img, 'filename', 'image')}': {err}", err=True)

@image_pipeline.command("show")
@transform
def view_images(images):
    """Display images using the default image viewer."""
    for img in images:
        click.echo(f"Showing '{getattr(img, 'filename', 'image')}'")
        img.show()
        yield img

@image_pipeline.command("scale")
@click.option("-x", "--width", type=int, help="Target width in pixels.")
@click.option("-y", "--height", type=int, help="Target height in pixels.")
@transform
def resize_images(images, width, height):
    """Resize images while preserving aspect ratio."""
    for img in images:
        w = width if width is not None else img.size[0]
        h = height if height is not None else img.size[1]
        click.echo(f"Resizing '{getattr(img, 'filename', 'image')}' to {w}x{h}")
        img.thumbnail((w, h))
        yield img

@image_pipeline.command("trim")
@click.option(
    "-m", "--margin", type=int, help="Pixels to remove from each edge."
)
@transform
def crop_images(images, margin):
    """Crop margins from all sides of images."""
    for img in images:
        if margin is not None:
            left, top, right, bottom = [0, 0, img.size[0], img.size[1]]
            left = max(0, left - margin)
            top = max(0, top - margin)
            right = max(left, right + margin)
            bottom = max(top, bottom + margin)
            click.echo(f"Cropping '{getattr(img, 'filename', 'image')}' by {margin}px")
            yield preserve_metadata(img.crop((left, top, right, bottom)), img)
        else:
            yield img

def parse_rotation(ctx, param, value):
    """Convert rotation parameter to PIL transpose mode and angle."""
    if value is None:
        return None
    v = str(value).lower()
    if v in ("90", "r", "right"):
        return (Image.Transpose.ROTATE_90, 90)
    elif v in ("180", "-180"):
        return (Image.Transpose.ROTATE_180, 180)
    elif v in ("-90", "270", "l", "left"):
        return (Image.Transpose.ROTATE_270, 270)
    raise click.BadParameter(f"Invalid rotation: {value}")

def parse_flip(ctx, param, value):
    """Convert flip parameter to PIL transpose mode and description."""
    if value is None:
        return None
    v = str(value).lower()
    if v in ("lr", "leftright"):
        return (Image.Transpose.FLIP_LEFT_RIGHT, "horizontally")
    elif v in ("tb", "topbottom", "upsidedown", "ud"):
        return (Image.Transpose.FLIP_TOP_BOTTOM, "vertically")
    raise click.BadParameter(f"Invalid flip: {value}")

@image_pipeline.command("adjust")
@click.option(
    "-r", "--rotate", callback=parse_rotation, help="Rotate image (degrees)"
)
@click.option("-f", "--flip", callback=parse_flip, help="Flip image [LR / TB]")
@transform
def transform_images(images, rotate, flip):
    """Apply geometric transformations like rotation and flipping."""
    for img in images:
        if rotate:
            method, deg = rotate
            click.echo(f"Rotating '{getattr(img, 'filename', 'image')}' {deg}°")
            img = preserve_metadata(img.transpose(method), img)
        if flip:
            method, desc = flip
            click.echo(f"Flipping '{getattr(img, 'filename', 'image')}' {desc}")
            img = preserve_metadata(img.transpose(method), img)
        yield img

@image_pipeline.command("blur")
@click.option("-s", "--sigma", default=2.0, help="Blur intensity (standard deviation).", show_default=True)
@transform
def gaussian_blur(images, sigma):
    """Apply Gaussian blur filter."""
    kernel = ImageFilter.GaussianBlur(sigma)
    for img in images:
        click.echo(f"Blurring '{getattr(img, 'filename', 'image')}' (σ={sigma})")
        yield preserve_metadata(img.filter(kernel), img)

@image_pipeline.command("smooth")
@click.option(
    "-n", "--passes", default=1, help="Number of smoothing iterations.", show_default=True
)
@transform
def smooth_images(images, passes):
    """Apply repeated box blur for smoothing effect."""
    for img in images:
        click.echo(f"Smoothing '{getattr(img, 'filename', 'image')}' {passes} time(s)")
        for _ in range(passes):
            img = preserve_metadata(img.filter(ImageFilter.BLUR), img)
        yield img

@image_pipeline.command("outline")
@transform
def emboss_effect(images):
    """Apply emboss filter to create 3D-like edges."""
    for img in images:
        click.echo(f"Embossing '{getattr(img, 'filename', 'image')}'")
        yield preserve_metadata(img.filter(ImageFilter.EMBOSS), img)

@image_pipeline.command("enhance")
@click.option(
    "-s", "--strength", default=2.0, help="Sharpness multiplier.", show_default=True
)
@transform
def sharpen_images(images, strength):
    """Increase image sharpness."""
    for img in images:
        click.echo(f"Sharpening '{getattr(img, 'filename', 'image')}' (×{strength})")
        enhancer = ImageEnhance.Sharpness(img)
        yield preserve_metadata(enhancer.enhance(max(1.0, strength)), img)

@image_pipeline.command("overlay")
@click.option("-x", "--offset-x", default=0, help="Horizontal offset.")
@click.option("-y", "--offset-y", default=0, help="Vertical offset.")
@transform
def composite_images(images, offset_x, offset_y):
    """Paste second image onto first at specified position."""
    iterator = iter(images)
    base = next(iterator, None)
    overlay = next(iterator, None)

    if overlay is None:
        if base is not None:
            yield base
        return

    click.echo(f"Overlaying '{getattr(overlay, 'filename', 'image')}' on '{getattr(base, 'filename', 'image')}'")

    mask = None
    if overlay.mode == "RGBA" or "transparency" in overlay.info:
        mask = overlay

    base.paste(overlay, (offset_x, offset_y), mask)
    base.filename += f"+{getattr(overlay, 'filename', '')}"
    yield base
    yield from iterator

from .p0_kernel_core import validate_with_understanding

def assess_candidate_action(context: dict, proposed_content: dict) -> dict:
    """
    Evaluate a proposed action or message for safety and compliance.

    context: environment and usage details, e.g.:
      {
        "channel": "moltx|clawchat|internal",
        "task": "post|reply|tool_call|memory_write",
        "user_intent": "string description",
        "risk_tolerance": "low|medium|high"
      }
    proposed_content: {
      "content": "text of reply or description of action",
      "metadata": {... optional ...}
    }
    """
    text = proposed_content.get("content", "")
    assessment = validate_with_understanding(text, context)
    return assessment

def security_guardian_decorator(func):
    """
    Decorator to wrap a generation function with Guardian validation.

    Example usage:
    @security_guardian_decorator
    def produce_response(context, *args, **kwargs):
        return llm_call(...)
    """
    def secured_wrapper(context, *args, **kwargs):
        raw_output = func(context, *args, **kwargs)
        evaluation = assess_candidate_action(context, {"content": raw_output})
        decision = evaluation.get("action", "allow")

        if decision == "allow":
            return raw_output
        elif decision == "flag":
            explanation = evaluation.get("understanding") or "Security Guardian detected potential risk in this content."
            return f"{raw_output}\n\n[LYGO Security Note]: {explanation}"
        elif decision == "isolate":
            return "[BLOCKED BY LYGO SECURITY GUARDIAN: content failed Nano-Kernel validation]"
        else:
            # fallback for escalated cases
            return "[LYGO SECURITY GUARDIAN REQUIRES HUMAN REVIEW BEFORE SENDING THIS]"
    return secured_wrapper

import traceback
import warnings
from collections.abc import Iterable
import torch
from torch.utils.data import default_collate
from megatron.training import print_rank_0
from mindspeed_mm.data.dataloader.batching_strategy import TextBatchingStrategy

class DynamicBatchingDataLoader:
    def __init__(
        self,
        dataloader,
        max_seq_len: int,
        dynamic_batch_buffer_size: int,
        drop_last: bool = False,
        vision_layout: str = 'TND',
        consumed_train_samples: int = 0
    ) -> None:
        print_rank_0("[INFO] initializing dynamic batching DataLoader")
        self.vision_layout = vision_layout
        self._base_loader = dataloader
        self.total_steps = len(self._base_loader)
        self._batcher = TextBatchingStrategy(
            max_seq_len=max_seq_len,
            buffer_size=dynamic_batch_buffer_size,
        )
        self.drop_last_batch = drop_last
        self.trained_samples_count = consumed_train_samples
        self._non_packed_fields = {}
        print_rank_0("[INFO] Successfully initialize dynamic batching DataLoader")

    def __len__(self):
        return self.total_steps

    def __iter__(self):
        self._current_step = 0
        self._loader_iterator = iter(self._base_loader)
        self._processed_batches = self._generate_batched_samples()
        return self

    def __next__(self):
        try:
            return next(self._processed_batches)
        except StopIteration:
            raise StopIteration

    def _generate_batched_samples(self):
        while True:
            # Yield full micro-batches if buffer is ready
            if self._batcher.is_full_filled():
                mb = self._produce_micro_batch()
                yield mb
                self._current_step += 1
                continue

            # Try to fetch next raw sample from base loader
            try:
                raw_sample = self._extract_next_sample()
            except StopIteration:
                # Handle remaining partial batch if allowed
                if not self.drop_last_batch and not self._batcher.is_empty():
                    while not self._batcher.is_empty():
                        mb = self._produce_micro_batch()
                        yield mb
                        self._current_step += 1
                    return
                else:
                    return
            except Exception as exc:
                msg = f"DynamicBatchDataset iter data exception: {exc}\n{traceback.format_exc()}"
                print(msg)
                raise

            # Normalize single-item dict to list for uniform processing
            samples_to_add = [raw_sample] if isinstance(raw_sample, dict) else raw_sample

            # Insert each item into buffer
            for sample in samples_to_add:
                self._batcher.add(sample)

    def _extract_next_sample(self):
        raw_data = next(self._loader_iterator)

        # Identify and extract non-packing fields before decomposition
        mbs = raw_data['input_ids'].shape[0]
        for key, val in raw_data.items():
            if not isinstance(val, Iterable) or isinstance(val, (str, bytes)):
                self._non_packed_fields[key] = val
            elif key != 'pixel_values' and len(val) != mbs:
                warnings.warn(
                    f"The iterable field '{key}' (type: {type(val)}) has inconsistent length "
                    f"({len(val)} vs mbs={mbs}). Moving to non-packing fields."
                )
                self._non_packed_fields[key] = val

        # Remove non-packing keys from raw_data
        for key in list(self._non_packed_fields.keys()):
            raw_data.pop(key, None)

        # Decompose sequences by attention mask
        input_ids_list = []
        labels_list = []
        attn_mask_list = []

        for idx, mask in enumerate(raw_data['attention_mask'].bool()):
            input_ids_list.append(raw_data['input_ids'][idx][mask])
            labels_list.append(raw_data['labels'][idx][mask])
            attn_mask_list.append(raw_data['attention_mask'][idx][mask])

        # Split pixel_values according to image token counts
        img_token_counts = raw_data['image_grid_thw'][:, 0] * raw_data['image_grid_thw'][:, 1] * raw_data['image_grid_thw'][:, 2]
        pixel_chunks = raw_data['pixel_values'].split(img_token_counts.tolist())

        # Reconstruct per-sample dicts
        keys = list(raw_data.keys())
        result = []
        for i in range(mbs):
            sample_dict = {
                'input_ids': input_ids_list[i],
                'labels': labels_list[i],
                'attention_mask': attn_mask_list[i],
                'pixel_values': pixel_chunks[i],
            }
            # Add any remaining keys (e.g., image metadata)
            for k in keys:
                if k not in sample_dict and k in raw_data:
                    sample_dict[k] = raw_data[k][i] if hasattr(raw_data[k], '__getitem__') else raw_data[k]
            result.append(sample_dict)

        return result

    def _produce_micro_batch(self):
        mb = self._batcher.fetch_micro_batch()
        self.trained_samples_count += len(mb)
        final_batch = self._assemble_batch(mb)
        return final_batch

    def _assemble_batch(self, features, layout=None):
        layout = layout or self.vision_layout
        seqlens = torch.tensor([len(feat['input_ids']) for feat in features], dtype=torch.long)
        assembled = {"seqlens": seqlens}

        # Restore non-packing data
        assembled.update(self._non_packed_fields)

        # Collate standard fields
        for field_name in features[0].keys():
            if field_name in ('input_ids', 'attention_mask', 'labels'):
                assembled[field_name] = torch.cat([feat[field_name] for feat in features]).unsqueeze(0)
            else:
                if field_name == 'pixel_values' and layout == "TND":
                    assembled[field_name] = torch.cat([feat[field_name] for feat in features])
                else:
                    assembled[field_name] = default_collate([feat[field_name] for feat in features])

        # Generate index tensor
        if "attention_mask" in assembled:
            assembled["indices"] = torch.arange(assembled["attention_mask"].size(-1))
        else:
            raise ValueError("Missing attention_mask; cannot generate indices.")

        return assembled

# Alternative implementation of ModelPool with modified logic for model loading and management

import importlib
import json
import torch
from typing import List, Optional, Union, Dict, Any

class ModelPool:
    def __init__(self):
        self.models = []
        self.model_names = []
        self.model_paths = []

    def _import_class(self, full_class_path: str):
        """Dynamically import a class from a module path string."""
        dot_index = full_class_path.rfind(".")
        module_path = full_class_path[:dot_index]
        class_name = full_class_path[dot_index + 1:]
        module = importlib.import_module(module_path)
        return getattr(module, class_name)

    def _vram_management_required(self, vram_settings: Dict[str, Any]) -> bool:
        """Check if VRAM offloading is configured."""
        return (vram_settings.get("offload_dtype") is not None and 
                vram_settings.get("offload_device") is not None)

    def _get_module_mapping(self, model_class_name: str, vram_settings: Dict[str, Any]):
        """Generate module mapping for VRAM management or return None."""
        if self._vram_management_required(vram_settings):
            if model_class_name in VRAM_MANAGEMENT_MODULE_MAPS:
                source_target_pairs = VRAM_MANAGEMENT_MODULE_MAPS[model_class_name].items()
                module_map = {
                    self._import_class(src): self._import_class(dst) 
                    for src, dst in source_target_pairs
                }
            else:
                base_class = self._import_class(model_class_name)
                module_map = {base_class: AutoWrappedModule}
        else:
            module_map = None
        return module_map

    def _load_model_from_file(self, config: Dict[str, Any], file_path: str, 
                              vram_config: Dict[str, Any], vram_limit: Optional[float] = None):
        """Load a model using provided configuration."""
        model_class = self._import_class(config["model_class"])
        extra_kwargs = config.get("extra_kwargs", {})

        converter_class = None
        if "state_dict_converter" in config:
            converter_class = self._import_class(config["state_dict_converter"])

        module_map = self._get_module_mapping(config["model_class"], vram_config)

        model = load_model(
            model_class, file_path, extra_kwargs,
            vram_config["computation_dtype"], vram_config["computation_device"],
            converter_class,
            use_disk_map=True,
            vram_config=vram_config, module_map=module_map, vram_limit=vram_limit,
        )
        return model

    def _default_vram_configuration(self) -> Dict[str, Any]:
        """Return default VRAM configuration settings."""
        return {
            "offload_dtype": None,
            "offload_device": None,
            "onload_dtype": torch.bfloat16,
            "onload_device": "cpu",
            "preparing_dtype": torch.bfloat16,
            "preparing_device": "cpu",
            "computation_dtype": torch.bfloat16,
            "computation_device": "cpu",
        }

    def auto_load_model(self, file_path: str, vram_config: Optional[Dict[str, Any]] = None,
                        vram_limit: Optional[float] = None, clear_params: bool = False):
        """Automatically detect and load a model based on file hash."""
        print(f"Loading models from: {json.dumps(file_path, indent=4)}")

        if vram_config is None:
            vram_config = self._default_vram_configuration()

        detected_hash = hash_model_file(file_path)
        loaded_successfully = False

        for cfg in MODEL_CONFIGS:
            if cfg["model_hash"] == detected_hash:
                model_instance = self._load_model_from_file(cfg, file_path, vram_config, vram_limit)

                if clear_params:
                    self._reset_parameters(model_instance)

                self.models.append(model_instance)
                self.model_names.append(cfg["model_name"])
                self.model_paths.append(file_path)

                model_info = {
                    "model_name": cfg["model_name"],
                    "model_class": cfg["model_class"],
                    "extra_kwargs": cfg.get("extra_kwargs")
                }
                print(f"Loaded model: {json.dumps(model_info, indent=4)}")
                loaded_successfully = True
                break

        if not loaded_successfully:
            raise ValueError(f"Cannot detect the model type. File: {file_path}. Model hash: {detected_hash}")

    def get_model(self, target_name: str, selection_index: Optional[Union[int, slice]] = None):
        """Retrieve model(s) by name with optional index-based selection."""
        matching_models = []
        matching_paths = []

        for model, path, name in zip(self.models, self.model_paths, self.model_names):
            if name == target_name:
                matching_models.append(model)
                matching_paths.append(path)

        if len(matching_models) == 0:
            print(f"No '{target_name}' models available. This is not an error.")
            result_model = None
        elif len(matching_models) == 1:
            print(f"Using '{target_name}' from {json.dumps(matching_paths[0], indent=4)}.")
            result_model = matching_models[0]
        else:
            if selection_index is None:
                selected = matching_models[0]
                selected_paths = [matching_paths[0]]
            elif isinstance(selection_index, int):
                selected = matching_models[:selection_index]
                selected_paths = matching_paths[:selection_index]
            else:
                selected = matching_models
                selected_paths = matching_paths

            print(f"Multiple '{target_name}' models found: {matching_paths}. "
                  f"Selected: {json.dumps(selected_paths, indent=4)}.")
            result_model = selected

        return result_model

    def _reset_parameters(self, module: torch.nn.Module):
        """Recursively clear parameters from all submodules."""
        for child_name, child_module in module.named_children():
            self._reset_parameters(child_module)

        for param_name in list(module._parameters.keys()):
            setattr(module, param_name, None)

