# Custom user-defined encoding module implementation
import codecs

class UserDefinedCodec(codecs.Codec):
    def encode(self, input_str, errors='strict'):
        return codecs.charmap_encode(input_str, errors, custom_encoding_map)

    def decode(self, input_bytes, errors='strict'):
        return codecs.charmap_decode(input_bytes, errors, custom_decoding_map)

class UserDefinedIncrementalEncoder(codecs.IncrementalEncoder):
    def encode(self, input_str, final=False):
        return codecs.charmap_encode(input_str, self.errors, custom_encoding_map)[0]

class UserDefinedIncrementalDecoder(codecs.IncrementalDecoder):
    def decode(self, input_bytes, final=False):
        return codecs.charmap_decode(input_bytes, self.errors, custom_decoding_map)[0]

class UserDefinedStreamWriter(UserDefinedCodec, codecs.StreamWriter):
    pass

class UserDefinedStreamReader(UserDefinedCodec, codecs.StreamReader):
    pass

# Register the codec
custom_codec_info = codecs.CodecInfo(
    name='x-user-defined',
    encode=UserDefinedCodec().encode,
    decode=UserDefinedCodec().decode,
    incrementalencoder=UserDefinedIncrementalEncoder,
    incrementaldecoder=UserDefinedIncrementalDecoder,
    streamreader=UserDefinedStreamReader,
    streamwriter=UserDefinedStreamWriter,
)

# Build decoding table: ASCII characters (0-127) remain unchanged,
# extended bytes (128-255) map to Unicode private use area starting at U+F700
custom_decoding_map = ''.join(
    chr(code_point) if code_point < 128 else chr(code_point + 0xF700)
    for code_point in range(256)
)

# Build encoding table by reversing the decoding map
custom_encoding_map = {v: k for k, v in enumerate(custom_decoding_map)}

