def dict2dataframe(d):
    # Convert dictionary to DataFrame with each key as column and value in a single row
    return pd.DataFrame({key: [d[key]] for key in d})

def string_to_list(s):
    # Safely parse string representations of lists or convert strings/other types to list
    if isinstance(s, str):
        if s.startswith('[') and s.endswith(']'):
            try:
                parsed = ast.literal_eval(s)
                return [str(x) for x in parsed]
            except:
                return [s]
        else:
            return [s]
    elif isinstance(s, list):
        return [str(x) for x in s]
    raise NotImplementedError("Unsupported input type for string_to_list")

def is_expected_type(s, expected_type):
    # Check if the input is already of expected type or can be parsed to it
    if isinstance(s, expected_type):
        return True
    try:
        return isinstance(ast.literal_eval(s), expected_type)
    except Exception:
        return False

def is_cn_string(s):
    # Detect presence of Chinese characters using Unicode range
    pattern = re.compile(r'[\u4e00-\u9fff]')
    return bool(pattern.search(s))

def build_option_str(option_dict):
    # Build a formatted string listing options from a dictionary
    result = 'There are several options: \n'
    for code, content in option_dict.items():
        if not pd.isna(content):
            result += f'{code}. {content}\n'
    return result

def extract_choices(item):
    """
    Extract valid multiple-choice options (A, B, C...) from a question item.
    Returns only those where the field exists and is non-null.
    """
    ret = {}
    for ch in string.ascii_uppercase:
        if ch in item and pd.notna(item[ch]):
            ret[ch] = item[ch]
    return ret

def check_answer_in_text(answer, choices):
    # Case-insensitive substring matching for answer detection
    answer = answer.lower()
    if not isinstance(choices, dict):
        raise TypeError("Expected 'choices' to be a dict.")

    # Normalize all choice values to lowercase strings
    normalized_choices = {}
    for k, v in choices.items():
        if k not in string.ascii_uppercase:
            raise ValueError(f"Expected 'k' to be an uppercase letter, got '{k}'.")
        normalized_choices[k] = str(v).lower()

    # Find matching keys whose value appears in the answer
    matches = [k for k, v in normalized_choices.items() if v in answer]
    return matches[0] if len(matches) == 1 else False

def extract_answer_from_item(item, dataset_name=None):
    logger_rank_0('Evaluation')
    choices = extract_choices(item)
    result = check_answer(item['prediction'], choices)
    if result:
        return dict(opt=result, log=item['prediction'])
    else:
        return dict(opt='Z', log='Failed in Prefetch, no GPT-based answer matching under `exact_matching` policy.')

def check_answer_in_option(answer, choices):
    # Clean up answer text and look for exact option letters
    answer = str(answer)
    verbose = os.environ.get('VERBOSE', 0)

    # Reject known error messages
    reject_messages = [
        "Sorry, I can't help with images of people yet.",
        "I can't process this file.",
        "I'm sorry, but without the image provided",
        'Cannot determine the answer'
    ]
    for err_msg in reject_messages:
        if err_msg in answer:
            return 'Z'

    # Preprocess answer by removing punctuation and splitting into tokens
    cleaned = copy.copy(answer)
    punct_chars = '.()[],:;!*#{}'
    for p in punct_chars:
        cleaned = cleaned.replace(p, ' ')

    tokens = [x.strip() for x in cleaned.split()]

    # Look for uppercase letters A-D that match options
    found_options = [ch for ch in choices if ch in tokens]

    if len(found_options) == 1:
        candidate = found_options[0]
        # Special case: avoid false positives when 'A' appears as part of sentence
        if 'A' in tokens and len(tokens) > 3 and verbose:
            logger_rank_0(f'A might be a quantifier in the string: {answer}.')
            return False
        return candidate
    elif not found_options and ('Z' in tokens or '' in tokens):
        return 'Z'
    return False

def check_answer(answer, choices):
    # Main answer checking logic: try direct option match first, then fallback to text matching
    if not isinstance(answer, str):
        answer = str(answer)

    option_match = check_answer_in_option(answer, choices)
    if not option_match:
        return check_answer_in_text(answer, choices)
    else:
        return option_match

def logger_rank_0(message):
    # Print only on rank 0 in distributed settings
    if dist.is_initialized():
        if dist.get_rank() == 0:
            print(message, flush=True)
    else:
        print(message, flush=True)

def get_world_size_and_rank():
    # Get current process's rank and total world size
    if dist.is_initialized():
        return dist.get_rank(), dist.get_world_size()
    else:
        raise Exception('torch distributed is not initialized')

def process_punctuation(in_text):
    # Remove or replace punctuation marks based on context
    out_text = in_text
    punctuation_list = [
        ';', r'/', '[', ']', '"', '{', '}', '(', ')', '=', '+', '\\', '_', '-',
        '>', '<', '@', '`', ',', '?', '!'
    ]

    # Patterns for numeric commas and periods
    comma_pattern = re.compile(r'(\d)(,)(\d)')
    period_pattern = re.compile(r'(?!<=\d)(\.)(?!\d)')

    for p in punctuation_list:
        if (p + ' ' in in_text or ' ' + p in in_text) or (re.search(comma_pattern, in_text)):
            out_text = out_text.replace(p, '')
        else:
            out_text = out_text.replace(p, ' ')

    # Apply period stripping
    out_text = period_pattern.sub('', out_text, flags=re.UNICODE)
    return out_text

def _process_digit_article(in_text):
