        'neednt': "needn't", 'notve': "not've", 'oclock': "o'clock",
        'oughtnt': "oughtn't", "ow's'at": "'ow's'at", "'ows'at": "'ow's'at",
        "'ow'sat": "'ow's'at", 'shant': "shan't", "shed've": "she'd've",
        "she'dve": "she'd've", "she's": "she's", 'shouldve': "should've",
        'shouldnt': "shouldn't", "shouldnt've": "shouldn't've", "shouldn'tve": "shouldn't've",
        "somebody'd": 'somebodyd', "somebodyd've": "somebody'd've", "somebody'dve": "somebody'd've",
        'somebodyll': "somebody'll", 'somebodys': "somebody's",
        'someoned': "someone'd", "someoned've": "someone'd've", "someone'dve": "someone'd've",
        'someonell': "someone'll", 'someones': "someone's",
        'somethingd': "something'd", "somethingd've": "something'd've", "something'dve": "something'd've",
        'somethingll': "something'll", 'thats': "that's",
        'thered': "there'd", "thered've": "there'd've", "there'dve": "there'd've",
        'therere': "there're", 'theres': "there's",
        'theyd': "they'd", "theyd've": "they'd've", "they'dve": "they'd've",
        'theyll': "they'll", 'theyre': "they're", 'theyve': "they've",
        'twas': "'twas", 'wasnt': "wasn't",
        "wed've": "we'd've", "we'dve": "we'd've", 'weve': "we've",
        'werent': "weren't", 'whatll': "what'll",
        'whatre': "what're", 'whats': "what's", 'whatve': "what've",
        'whens': "when's", 'whered': "where'd", 'wheres': "where's",
        'whereve': "where've", 'whod': "who'd", "whod've": "who'd've",
        "who'dve": "who'd've", 'wholl': "who'll", 'whos': "who's",
        'whove': "who've", 'whyll': "why'll", 'whyre': "why're",
        'whys': "why's", 'wont': "won't", 'wouldve': "would've",
        'wouldnt': "wouldn't", "wouldnt've": "wouldn't've", "wouldn'tve": "wouldn't've",
        'yall': "y'all", "yall'll": "y'all'll", "y'allll": "y'all'll",
        "yall'd've": "y'all'd've", "y'alld've": "y'all'd've", "y'all'dve": "y'all'd've",
        'youd': "you'd", "youd've": "you'd've", "you'dve": "you'd've",
        'youll': "you'll", 'youre': "you're", 'youve': "you've"
    }

    processed_words = []
    for word in words:
        # Replace number words with digits
        word = number_map.get(word, word)
        # Skip articles
        if word not in articles:
            processed_words.append(word)

    # Expand contractions
    for idx, word in enumerate(processed_words):
        if word in contractions:
            processed_words[idx] = contractions[word]

    return ' '.join(processed_words)

def is_list_in_str(list_input, s):
    # Check if any item in list appears in string (case-insensitive)
    if not isinstance(list_input, list):
        raise TypeError(f"Expected 'list_input' to be of type list, but got {type(list_input).__name__}.")

    lower_s = s.lower()
    for item in list_input:
        if item.lower() in lower_s:
            return True
    return False

def process_answer(answer):
    # Standardize answer format: clean whitespace, punctuation, and normalize text
    answer = answer.replace('\n', ' ').replace('\t', ' ').strip()
    answer = process_punctuation(answer)
    answer = _process_digit_article(answer)
    return answer

import typing as t

def convert_to_markdown_list(
    items: list[str], 
    style: t.Literal["unordered", "ordered"] = "unordered"
) -> str:
    """
    Convert a list of strings into markdown list format.
    :param items: list of strings to be formatted
    :param style: formatting style ('unordered' for bullet points, 'ordered' for numbered)
    :return: markdown-formatted string
    """
    if style == "unordered":
        return "\n".join(f"- {element}" for element in items)
    elif style == "ordered":
        return "\n".join(f"{index}. {element}" for index, element in enumerate(items, 1))
    else:
        raise ValueError("style must be either 'unordered' or 'ordered'")

