import os
import yaml
from typing import Dict, Any, Optional, Union, List
from .functions import render_template, dump_as_json, replace_bash_var, get_abs_path_cwd_ucagent
from .log import info

class Settings:
    """Configuration class for UCAgent settings (renamed from Config to Settings)."""
    def __init__(self, data: Optional[Dict[str, Any]] = None) -> None:
        self._locked = False
        self.load_from_dict(data)

    def load_from_dict(self, data: Optional[Dict[str, Any]]) -> "Settings":
        if data is None:
            return self
        for key, value in data.items():
            if isinstance(value, dict):
                setattr(self, key, Settings(value))
            elif isinstance(value, list):
                setattr(self, key, [
                    Settings(item) if isinstance(item, dict) else item 
                    for item in value
                ])
            else:
                setattr(self, key, value)
        return self

    def is_empty(self) -> bool:
        return len(self.to_dict()) <= 1

    def to_dict(self) -> Dict[str, Any]:
        result = {}
        for key, value in self.__dict__.items():
            if key == "_locked":
                continue
            if isinstance(value, Settings):
                result[key] = value.to_dict()
            elif isinstance(value, list):
                result[key] = [
                    item.to_dict() if isinstance(item, Settings) else item 
                    for item in value
                ]
            else:
                result[key] = value
        return result

    def __str__(self):
        return "Settings(" + dump_as_json(self.to_dict()) + ")"

    def apply_template(self, template_dict):
        self.unlock()  # Ensure the configuration is mutable

        def _process_list(lst_val):
            for idx, item in enumerate(lst_val):
                if isinstance(item, Settings):
                    item.apply_template(template_dict)
                elif isinstance(item, str):
                    new_val = render_template(item, template_dict)
                    if new_val != item:
                        lst_val[idx] = new_val
                elif isinstance(item, list):
                    _process_list(item)
                else:
                    raise TypeError(
                        f"Unsupported list item type: {type(item)}. "
                        "Supported types are: str, Settings, and list."
                    )

        for key, value in self.__dict__.items():
            if isinstance(value, Settings):
                value.apply_template(template_dict)
            elif isinstance(value, list):
                _process_list(value)
            elif isinstance(value, str):
                new_val = render_template(value, template_dict)
                if new_val != value:
                    setattr(self, key, new_val)

        self.lock()  # Lock the configuration after updating
        return self

    def to_yaml_string(self, indent=2):
        return yaml.dump(self.to_dict(),
                         default_flow_style=False,
                         indent=indent, allow_unicode=True)

    def lock(self):
        for _, value in self.__dict__.items():
            if isinstance(value, Settings):
                value.lock()
            elif isinstance(value, list):
                for v in value:
                    if isinstance(v, Settings):
                        v.lock()
        self._locked = True
        return self

    def unlock(self):
        for _, value in self.__dict__.items():
            if isinstance(value, Settings):
                value.unlock()
            elif isinstance(value, list):
                for v in value:
                    if isinstance(v, Settings):
                        v.unlock()
        self._locked = False
        return self

    def __setattr__(self, name, value):
        if name != "_locked":
            if getattr(self, "_locked", False) == True:
                raise RuntimeError("Configuration is locked, cannot modify.")
        super().__setattr__(name, value)

    def __getattr__(self, name):
        if name in self.__dict__:
            return self.__dict__[name]
        return Settings()  # Return an empty Settings object if the attribute does not exist

    def has_attribute(self, name):
        return name in self.__dict__

    def combine_with(self, other):
        if not isinstance(other, Settings):
            raise TypeError("Can only combine with another Settings instance.")
        for key, value in other.__dict__.items():
            if isinstance(value, Settings):
                if self.has_attribute(key) and isinstance(getattr(self, key), Settings):
                    getattr(self, key).combine_with(value)
                else:
                    setattr(self, key, value)
            else:
                setattr(self, key, value)
        return self

    def merge_from_dict(self, data):
        if not isinstance(data, dict):
            raise TypeError("Can only merge from a dictionary.")
        for key, value in data.items():
            if isinstance(value, dict):
                if self.has_attribute(key) and isinstance(getattr(self, key), Settings):
                    getattr(self, key).merge_from_dict(value)
                else:
                    setattr(self, key, Settings(value))
            else:
                setattr(self, key, value)
        return self

    def assign_value(self, key, value):
        keys = key.split('.')
        current = self
        for k in keys[:-1]:
            if not self.has_attribute(k):
                raise AttributeError(f"Configuration does not have attribute '{k}'")
            current = getattr(current, k)
        setattr(current, keys[-1], value)
        return self

    def fetch_value(self, key, default=None):
        keys = key.split('.')
        current = self
        for k in keys[:-1]:
            if not self.has_attribute(k):
                raise AttributeError(f"Configuration does not have attribute '{k}'")
            current = getattr(current, k)
        if not current.has_attribute(keys[-1]):
            return default
        return getattr(current, keys[-1], default)

    def __getitem__(self, key):
        if not isinstance(key, str):
            raise TypeError("Key must be a string.")
        assert self.has_attribute(key), f"Configuration does not have attribute '{key}'"
        return self.fetch_value(key)

    def assign_values(self, values):
        if values is None:
            return self
        for key, value in values.items():
            self.assign_value(key, value)
        return self


def locate_file_in_directories(filename, search_dirs):
    if filename.startswith('/'):
        if os.path.isfile(filename):
            return filename
        else:
            return None

    for directory in search_dirs:
        full_path = os.path.join(directory, filename)
        if os.path.isfile(full_path):
            return full_path
    return None


def obtain_settings(config_file=None, cfg_override=None, workspace=None):
    def parse_yaml_with_env_vars(file_path):
        with open(file_path, 'r') as file:
            content = file.read()
            rendered_content = replace_bash_var(content, os.environ)
            return yaml.safe_load(rendered_content)

    processed_configs = []

    # 1. Load default config
    default_config_file = os.path.abspath(os.path.join(os.path.dirname(__file__), "../setting.yaml"))
    assert os.path.isfile(default_config_file), f"Default configuration file '{default_config_file}' not found."
    settings = Settings(parse_yaml_with_env_vars(default_config_file))
    info(f"Load config from '{default_config_file}' completed.")
    processed_configs.append(default_config_file)

    # 2. Load user config
    user_home = os.path.expanduser('~')
    user_config_file = os.path.abspath(os.path.join(user_home, '.ucagent/setting.yaml'))
    if os.path.isfile(user_config_file):
        settings.combine_with(Settings(parse_yaml_with_env_vars(user_config_file)))
        info(f"Load config from '{user_config_file}' completed.")
        processed_configs.append(user_config_file)
    else:
        info(f"User config file '{user_config_file}' not found, touch an empty one.")
        os.makedirs(os.path.dirname(user_config_file), exist_ok=True)
        with open(user_config_file, 'w') as f:
            f.write("# UCAgent user configuration file\n")
        processed_configs.append(user_config_file)

    # 3. Load language config
    lang = settings.fetch_value('lang', 'zh')
    lang_config_file = os.path.abspath(os.path.join(os.path.dirname(__file__), f"../lang/{lang}/config/default.yaml"))
    info(f"Load config from '{lang_config_file}'")
    assert os.path.isfile(lang_config_file), f"Language configuration file '{lang_config_file}' not found."
    settings.combine_with(Settings(parse_yaml_with_env_vars(lang_config_file)))
    processed_configs.append(lang_config_file)

    # 4. Load workspace config
    if workspace is not None:
        cwd_setting_file = get_abs_path_cwd_ucagent(workspace, "setting.yaml")
        if os.path.isfile(cwd_setting_file):
            settings.combine_with(Settings(parse_yaml_with_env_vars(cwd_setting_file)))
            info(f"Load config from '{cwd_setting_file}' completed.")
            processed_configs.append(cwd_setting_file)
        else:
            info(f"Workspace config file '{cwd_setting_file}' not found, ignore.")

    # 5. Find user specified config file
    target_file = config_file
    if config_file is None:
        target_file = 'config.yaml'  # Default configuration file

    user_config_file_path = locate_file_in_directories(target_file, [
        os.getcwd(),
        os.path.join(user_home, '.ucagent/'),
        os.path.join(os.path.dirname(__file__), f"../lang/{lang}/config/")
    ])

    if config_file is not None:
        assert user_config_file_path is not None, f"Config file '{config_file}' not found in current directory or default config path."

    if user_config_file_path is None:
        info(f"Default user config file '{config_file}' not found, ignore.")
    else:
        user_config_file_path = os.path.abspath(user_config_file_path)
        if user_config_file_path not in processed_configs:
            settings.combine_with(Settings(parse_yaml_with_env_vars(user_config_file_path)))
            info(f"Load config from '{user_config_file_path}' completed.")
        else:
            info(f"Config file '{user_config_file_path}' already loaded, ignore.")

    return settings.assign_values(cfg_override).lock()

