class DimensionCounter:
    def __init__(self):
        self.frequency = {}

    def increment(self, dims):
        unique_dims = set(dims)
        for d in unique_dims:
            current = self.frequency.get(d, 0)
            self.frequency[d] = current + 1

    def get_min_frequency(self, dims):
        unique_dims = set(dims)
        counts = [self.frequency.get(d, 0) for d in unique_dims]
        return min(counts) if counts else 0


# Mapping from original dimension names to canonical ones
DIMENSION_MAPPING = {
    "subject_consistency": "subject_consistency",
    "background_consistency": "scene",
    "aesthetic_quality": "overall_consistency",
    "imaging_quality": "overall_consistency",
    "object_class": "object_class",
    "multiple_objects": "multiple_objects",
    "color": "color",
    "spatial_relationship": "spatial_relationship",
    "scene": "scene",
    "temporal_style": "temporal_style",
    "overall_consistency": "overall_consistency",
    "human_action": "human_action",
    "temporal_flickering": "temporal_flickering",
    "motion_smoothness": "subject_consistency",
    "dynamic_degree": "subject_consistency",
    "appearance_style": "appearance_style"
}


def normalize_dimensions(dim_list):
    if not dim_list:
        return []
    normalized = set(dim_list)
    for d in list(dim_list):
        if d in DIMENSION_MAPPING:
            normalized.add(DIMENSION_MAPPING[d])
    return list(normalized)


class VideoGenEvalDataset(GenEvalBaseDataset):
    def __init__(self,
                 config: dict,
                 extra_config: dict,
                 dims: list = None,
                 ):
        super().__init__(config)
        self.selected_dims = normalize_dimensions(dims)
        self.apply_augmentation = extra_config.get("augment", False)
        self.max_prompts_per_dim = extra_config.get("prompts_per_dim", 0)
        self.repeats_per_prompt = extra_config.get("samples_per_prompt", 5)
        self.base_prompt_file = extra_config.get("prompt_file", "all_dimension.txt")
        self.augmented_prompt_file = extra_config.get(
            "augmented_prompt_file",
            "augmented_prompts/gpt_enhanced_prompts/all_dimension_longer.txt"
        )
        self.text_captions = []
        self.enhanced_captions = []

        if self.selected_dims:
            prompt_paths = [
                os.path.join("prompts_per_dimension", f"{dim}.txt") for dim in self.selected_dims
            ]
            for pth in prompt_paths:
                full_path = os.path.join(self.data_folder, pth)
                if not os.path.isfile(full_path):
                    continue
                raw_data = self.load_data(full_path)
                limit = self.max_prompts_per_dim if self.max_prompts_per_dim > 0 else len(raw_data)
                self.text_captions.extend(raw_data[:limit])

            if self.apply_augmentation:
                aug_paths = [
                    os.path.join(
                        "augmented_prompts/gpt_enhanced_prompts/prompts_per_dimension_longer",
                        f"{dim}_longer.txt"
                    ) for dim in self.selected_dims
                ]
                for aug_pth in aug_paths:
                    full_aug_path = os.path.join(self.data_folder, aug_pth)
                    if not os.path.isfile(full_aug_path):
                        continue
                    raw_aug_data = self.load_data(full_aug_path)
                    limit = self.max_prompts_per_dim if self.max_prompts_per_dim > 0 else len(raw_aug_data)
                    self.enhanced_captions.extend(raw_aug_data[:limit])
        else:
            full_base_path = os.path.join(self.data_folder, self.base_prompt_file)
            self.text_captions.extend(self.load_data(full_base_path))
            if self.apply_augmentation:
                full_aug_path = os.path.join(self.data_folder, self.augmented_prompt_file)
                self.enhanced_captions.extend(self.load_data(full_aug_path))

    def create_empty_item(self):
        return {
            "caption": "",
            "prefix": ""
        }

    def fetch_item(self, index):
        caption_idx = index // self.repeats_per_prompt
        sample_idx = index % self.repeats_per_prompt
        item = self.create_empty_item()
        prefix_text = self.text_captions[caption_idx]
        item["prefix"] = f"{prefix_text}-{sample_idx}"
        item["caption"] = (
            self.enhanced_captions[caption_idx]
            if self.apply_augmentation
            else self.text_captions[caption_idx]
        )
        return item

    def total_items(self):
        return len(self.text_captions) * self.repeats_per_prompt


class ImageToVideoGenEvalDataset(GenEvalBaseDataset):
    def __init__(self,
                 config: dict,
                 extra_config: dict,
                 dims: list,
                 ):
        super().__init__(config)
        self.aspect_ratio = extra_config.get("ratio", "16-9")
        self.max_prompts_per_dim = extra_config.get("prompts_per_dim", 0)
        self.repeats_per_prompt = extra_config.get("samples_per_prompt", 5)
        self.filter_by_dims(dims)

    def create_empty_item(self):
        return {
            "caption": "",
            "prefix": "",
            "image": ""
        }

    def filter_by_dims(self, dims):
        if not dims:
            return
        target_dims = set(dims)
        filtered_samples = []
        counter = DimensionCounter()

        for sample in self.data_samples:
            dims_in_sample = sample.get("dimension", [])
            if any(d in target_dims for d in dims_in_sample):
                min_freq = counter.get_min_frequency(dims_in_sample)
                if 0 < self.max_prompts_per_dim <= min_freq:
                    continue
                filtered_samples.append(sample)
                counter.increment(dims_in_sample)

        self.data_samples = filtered_samples

    def fetch_item(self, index):
        caption_idx = index // self.repeats_per_prompt
        sample_idx = index % self.repeats_per_prompt
        item = self.create_empty_item()
        data = self.data_samples[caption_idx]

        prompt_text = data.get("prompt_en", "")
        item["caption"] = prompt_text
        item["prefix"] = f"{prompt_text}-{sample_idx}"
        image_name = data.get("image_name", "")
        item["image"] = os.path.join(
            self.data_folder,
            "crop",
            self.aspect_ratio,
            image_name
        )
        return item

    def total_items(self):
        return len(self.data_samples) * self.repeats_per_prompt

from rest_framework.pagination import PageNumberPagination
from rest_framework.response import Response

class CustomPageNumberPagination(PageNumberPagination):
    page_size_query_param = "page_size"
    max_page_size = 10000

    def paginate_queryset(self, queryset, request, view=None):
        # Get page size from query parameters
        requested_page_size = request.GET.get("page_size")

        # Disable pagination if page_size is not provided or set to special values
        if requested_page_size is None or requested_page_size in ["0", "-1"]:
            return None

        # Proceed with default pagination logic
        return super().paginate_queryset(queryset, request, view)

    def get_paginated_response(self, data):
        # Construct custom response structure
        response_data = {
            "count": self.page.paginator.count,
            "items": data
        }

        return Response(response_data)

