SF_PATH = os.path.join(BASE_DIR, "cli", "sf.py")
DB_PATH = os.path.join(BASE_DIR, "data", "platform.db")

def run_sf_command(*args, use_json=False):
    """Execute sf CLI command and return (exit_code, stdout, stderr)."""
    command = [sys.executable, SF_PATH, "--db", "--db-path", DB_PATH, "--no-color"]
    if use_json:
        command.append("--json")
    command.extend(args)

    result = subprocess.run(command, capture_output=True, text=True, timeout=15)
    return result.returncode, result.stdout, result.stderr

class TestStatusModule:
    def test_status_check(self):
        exit_code, output, _ = run_sf_command("status")
        assert exit_code == 0
        assert ("ok" in output) or ("offline" in output)

