# Helper function to normalize provider names (case-insensitive)
def _normalize_provider_name(name):
    return name.lower()

# Helper function to get environment variable in uppercase format
def _get_env_var_for_provider(provider):
    normalized = _normalize_provider_name(provider)
    env_key = f"{normalized.upper()}_API_KEY"
    return os.environ.get(env_key)

