import logging
import os
from flask import Blueprint, jsonify, request
from app.web import get_config_manager, get_module_loader, require_auth

log = logging.getLogger("docsis.modules")
modules_bp = Blueprint("modules_bp", __name__)

def _module_to_json(mod):
    """Transform ModuleInfo into a JSON-serializable dictionary."""
    contributes_keys = getattr(mod, "contributes", [])
    return {
        "id": mod.id,
        "name": mod.name,
        "description": mod.description,
        "version": mod.version,
        "author": mod.author,
        "type": mod.type,
        "enabled": mod.enabled,
        "builtin": mod.builtin,
        "error": mod.error,
        "homepage": mod.homepage,
        "is_threshold": "thresholds" in contributes_keys,
        "is_theme": mod.type == "theme",
    }

@modules_bp.route("/api/modules")
@require_auth
def list_all_modules():
    """Return metadata and status for every discovered module."""
    loader = get_module_loader()
    if loader is None:
        return jsonify([])
    modules = loader.get_modules()
    return jsonify([_module_to_json(m) for m in modules])

@modules_bp.route("/api/modules/<mid>/enable", methods=["POST"])
@require_auth
def enable_module(mid):
    """Enable a currently disabled module (changes are persistent, restart needed)."""
    loader = get_module_loader()
    if not loader:
        return jsonify({"success": False, "error": "Module system not initialized"}), 500

    target = next((m for m in loader.get_modules() if m.id == mid), None)
    if target is None:
        return jsonify({"success": False, "error": f"Module '{mid}' not found"}), 404

    cfg_mgr = get_config_manager()
    if not cfg_mgr:
        return jsonify({"success": False, "error": "Config not initialized"}), 500

    raw_disabled = cfg_mgr.get("disabled_modules", "")
    disabled_ids = {x.strip() for x in raw_disabled.split(",") if x.strip()}

    # Enforce mutual exclusion: only one threshold module active at a time
    if "thresholds" in getattr(target, "contributes", []):
        for t_mod in loader.get_threshold_modules():
            if t_mod.id != mid and t_mod.id not in disabled_ids:
                disabled_ids.add(t_mod.id)
                log.info("Auto-disabled threshold module '%s' due to mutual exclusion", t_mod.id)

    # Enforce mutual exclusion: only one theme active at a time
    if target.type == "theme":
        for th_mod in loader.get_theme_modules():
            if th_mod.id != mid and th_mod.id not in disabled_ids:
                disabled_ids.add(th_mod.id)
                log.info("Auto-disabled theme module '%s' due to mutual exclusion", th_mod.id)

    disabled_ids.discard(mid)
    new_disabled_str = ",".join(sorted(disabled_ids))
    updates = {"disabled_modules": new_disabled_str}
    if target.type == "theme":
        updates["active_theme"] = mid
    cfg_mgr.save(updates)
    log.info("Module '%s' enabled (restart required)", mid)
    return jsonify({"success": True, "restart_required": True})

@modules_bp.route("/api/modules/<mid>/disable", methods=["POST"])
@require_auth
def disable_module(mid):
    """Disable a currently enabled module (changes are persistent, restart needed)."""
    loader = get_module_loader()
    if not loader:
        return jsonify({"success": False, "error": "Module system not initialized"}), 500

    target = next((m for m in loader.get_modules() if m.id == mid), None)
    if target is None:
        return jsonify({"success": False, "error": f"Module '{mid}' not found"}), 404

    cfg_mgr = get_config_manager()
    if not cfg_mgr:
        return jsonify({"success": False, "error": "Config not initialized"}), 500

    raw_disabled = cfg_mgr.get("disabled_modules", "")
    disabled_ids = {x.strip() for x in raw_disabled.split(",") if x.strip()}

    # Prevent disabling the last active theme
    if target.type == "theme":
        remaining_themes = [
            m for m in loader.get_theme_modules()
            if m.id not in disabled_ids and m.id != mid
        ]
        if not remaining_themes:
            return jsonify({
                "success": False,
                "error": "Cannot disable the only active theme. Enable a different theme first.",
            }), 409

    # Prevent disabling the last active threshold profile
    if "thresholds" in getattr(target, "contributes", []):
        remaining_thresholds = [
            m for m in loader.get_threshold_modules()
            if m.id not in disabled_ids and m.id != mid
        ]
        if not remaining_thresholds:
            return jsonify({
                "success": False,
                "error": "Cannot disable the only active threshold profile. Enable a different one first.",
            }), 409

    disabled_ids.add(mid)
    cfg_mgr.save({"disabled_modules": ",".join(sorted(disabled_ids))})
    log.info("Module '%s' disabled (restart required)", mid)
    return jsonify({"success": True, "restart_required": True})

@modules_bp.route("/api/themes")
@require_auth
def list_themes():
    """List all installed theme modules along with their CSS variables."""
    loader = get_module_loader()
    if not loader:
        return jsonify([])
    themes = loader.get_theme_modules()
    output = []
    for t in themes:
        entry = _module_to_json(t)
        entry["theme_data"] = getattr(t, "theme_data", {})
        output.append(entry)
    return jsonify(output)

@modules_bp.route("/api/themes/registry")
@require_auth
def fetch_registry_themes():
    """Retrieve available themes from remote registry."""
    cfg_mgr = get_config_manager()
    if not cfg_mgr:
        return jsonify([])

    registry_url = cfg_mgr.get(
        "theme_registry_url",
        "https://raw.githubusercontent.com/itsDNNS/docsight-themes/main/registry.json"
    )
    from app.theme_registry import fetch_registry
    all_themes = fetch_registry(registry_url)

    loader = get_module_loader()
    installed = set()
    if loader:
        installed = {m.id for m in loader.get_theme_modules()}
    uninstalled = [t for t in all_themes if t["id"] not in installed]
    return jsonify(uninstalled)

@modules_bp.route("/api/themes/install", methods=["POST"])
@require_auth
def install_theme():
    """Install a theme from the remote registry."""
    payload = request.get_json(silent=True)
    if not payload or "download_url" not in payload or "id" not in payload:
        return jsonify({"success": False, "error": "Missing download_url or id"}), 400

    safe_id = payload["id"].replace(".", "_")
    dest_dir = os.path.join("/modules", safe_id)
    from app.theme_registry import download_theme
    success = download_theme(payload["download_url"], dest_dir)
    if success:
        return jsonify({"success": True, "restart_required": True})
    else:
        return jsonify({"success": False, "error": "Download failed"}), 500

