    def create_alias(self, alias_name, target_collection):
        return self.client.alias.create(alias_name=alias_name, target_collection=target_collection)

    def update_alias(self, alias_name, new_target_collection):
        return self.client.alias.update(alias_name=alias_name, new_target_collection=new_target_collection)

    def delete_alias(self, alias_name):
        return self.client.alias.delete(alias_name=alias_name)

    def get_alias_info(self, alias_name):
        return self.client.alias.get(alias_name=alias_name)

    def list_all_aliases(self):
        return self.client.alias.list_all()

    def list_aliases_for_collection(self, collection_name):
        return self.client.alias.list_all(collection=collection_name)


