    # Dataset implementations
    class SimpleSequenceDataset(Dataset):
        def __init__(self, size: int = 101):
            self.size = size
        def __len__(self):
            return self.size
        def __getitem__(self, idx) -> int:
            return idx

    class BatchProcessor:
        def __call__(self, samples):
            return {"input_ids": torch.tensor(samples), "labels": torch.tensor(samples)}

    class MinimalNetwork(nn.Module):
        def __init__(self):
            super().__init__()
            # Include some parameters to avoid DDP complaints
            self.linear_layer = nn.Linear(128, 64)
        def forward(self, input_ids, labels=None):
            if labels is not None:
                return torch.tensor(0.0, device=input_ids.device), input_ids
            else:
                return input_ids

    class LinearRegressionModel(nn.Module):
        def __init__(self, weight=0.0, bias=0.0, dual_output=False):
            super().__init__()
            self.weight_param = nn.Parameter(torch.tensor(weight).float())
            self.bias_param = nn.Parameter(torch.tensor(bias).float())
            self.dual_output = dual_output
            self.config = None
        def forward(self, input_data, labels=None, **kwargs):
            output = input_data * self.weight_param + self.bias_param
            if labels is None:
                return (output, output) if self.dual_output else (output,)
            error = nn.functional.mse_loss(output, labels)
            return (error, output, output) if self.dual_output else (error, output)

    class InfiniteSampler(IterableDataset):
        def __init__(self, slope=2.0, intercept=3.0, count=64, random_seed=42, target_names=None):
            self.dataset = LinearRegressionDataset(slope=slope, intercept=intercept, count=count, 
                                                  random_seed=random_seed, target_names=target_names)
        def __iter__(self):
            for index in range(len(self.dataset)):
                yield self.dataset[index]

    class BoundedSampler(InfiniteSampler):
        def __init__(self, slope=2.0, intercept=3.0, count=64, random_seed=42, target_names=None):
            super().__init__(slope, intercept, count, random_seed, target_names)
            self.current_index = 0
        def __iter__(self):
            while self.current_index < len(self.dataset):
                yield self.dataset[self.current_index]
                self.current_index += 1

    class LinearRegressionDataset:
        def __init__(self, slope=2.0, intercept=3.0, count=64, random_seed=42, target_names=None):
            np.random.seed(random_seed)
            self.target_names = ["labels"] if target_names is None else target_names
            self.count = count
            self.inputs = np.random.normal(size=(count,)).astype(np.float32)
            self.outputs = [slope * self.inputs + intercept + 
                           np.random.normal(scale=0.1, size=(count,)) for _ in self.target_names]
            self.outputs = [y.astype(np.float32) for y in self.outputs]
        def __len__(self):
            return self.count
        def __getitem__(self, index):
            result = {name: value[index] for name, value in zip(self.target_names, self.outputs)}
            result["input_data"] = self.inputs[index]
            return result

