from graph_net.fault_locator.fault_detector import has_fault_at, ES

class TestHasFaultAt(unittest.TestCase):
    def test_fault_detected(self):
        """Verify fault detection when the previous ES value is below the maximum."""
        # Tolerance of 5 means we compare ES[4] against ES[max_key]
        es_values: ES = {0: 0.1, 4: 0.5, 10: 0.9}
        margin = 5
        # Since 0.5 < 0.9, a fault should be detected
        self.assertTrue(has_fault_at(es_values, margin))

    def test_no_fault_detected(self):
        """Verify no fault when the previous ES value meets or exceeds the maximum."""
        # With tolerance=11, we check ES[10], which is also the max key
        es_values: ES = {0: 0.1, 5: 0.5, 10: 0.9}
        margin = 11
        # Since 0.9 >= 0.9, no fault is detected
        self.assertFalse(has_fault_at(es_values, margin))

    def test_invalid_tolerance(self):
        """Ensure AssertionError is raised when required index is missing from ES."""
        es_values: ES = {0: 0.1, 1: 0.2}
        margin = 5  # Index 4 (margin-1) is not present in es_values
        with self.assertRaises(AssertionError):
            has_fault_at(es_values, margin)

    def test_single_element_case(self):
        """Handle scenario where ES contains only one entry."""
        es_values: ES = {3: 0.7}
        margin = 1  # We'd check ES[0], but it's not present - wait, actually margin-1=0 not in keys
        # Correction: Let's adjust to match original intent
        es_values: ES = {0: 0.5}
        margin = 1
        # Since there's only one element, max is at same position as "previous"
        # So 0.5 < 0.5 evaluates to False
        self.assertFalse(has_fault_at(es_values, margin))

