def create_vllm_configuration(subconfig_kinds: List[str],
                              modifications: List[Dict[str, Any]]):
    """
    Create and configure a SimpleVllmConfig instance with specified overrides.
    """
    base_config = SimpleVllmConfig()
    for (kind, mod) in zip(subconfig_kinds, modifications):
        if kind == "model":
            for param in mod:
                setattr(base_config.model_config, param, mod[param])
        else:
            for param in mod:
                setattr(base_config, param, mod[param])
    return base_config

@dataclass
class SimpleVllmConfig:
    extra_settings: Dict[str, Any] = field(default_factory=dict)
    # Default max_model_len to suppress warnings
    model_config: ModelConfig = field(
        default_factory=lambda: ModelConfig(max_model_len=1024))

@dataclass
class SimpleConfig(Config):
    vllm_instance: SimpleVllmConfig
    param_a: str
    param_b: str
    param_c: int

    def matches(self, other: Config) -> bool:
        """Check if two configs are equal, excluding vllm_instance."""
        for attr in fields(self):
            if attr.name != "vllm_instance":
                if getattr(self, attr.name) != getattr(other, attr.name):
                    return False
        return True

