class LazySimpleAgentV3:
    """Minimal wrapper for SimpleAgentV3 with deferred initialization."""
    _underlying_class = None

    def __new__(cls, *args, **kwargs):
        """Initialize and instantiate the actual SimpleAgentV3 when needed."""
        if cls._underlying_class is None:
            cls._underlying_class = SimpleAgentV3
        # Delegate to the real implementation class
        return cls._underlying_class(*args, **kwargs)

    @classmethod
    def wrap_as_tool(cls, *args, **kwargs):
        """Defer loading of as_tool until it's explicitly requested."""
        if cls._underlying_class is None:
            cls._underlying_class = SimpleAgentV3
        return cls._underlying_class.as_tool(*args, **kwargs)

    @classmethod
    def wrap_as_structured_tool(cls, *args, **kwargs):
        """Defer loading of as_structured_tool until it's explicitly requested."""
        if cls._underlying_class is None:
            cls._underlying_class = SimpleAgentV3
        return cls._underlying_class.as_structured_tool(*args, **kwargs)


