def initialize_model():
    global model_instance, server_start_time
    logger.info(f"Initializing embedding model: {MODEL_NAME}")
    start_load = time.time()
    from sentence_transformers import SentenceTransformer
    model_instance = SentenceTransformer(MODEL_NAME)
    load_duration = (time.time() - start_load) * 1000
    server_start_time = time.time()
    logger.info(f"Model loaded successfully in {load_duration:.0f}ms")

def generate_embedding(text: str) -> list:
    vector = model_instance.encode([text], normalize_embeddings=True)[0]
    return vector.tolist()

def generate_batch_embeddings(texts: list) -> list:
    vectors = model_instance.encode(texts, normalize_embeddings=True, batch_size=32)
    return vectors.tolist()

def process_client_connection(client_socket):
    try:
        buffer = b""
        while True:
            part = client_socket.recv(8192)
            if not part:
                break
            buffer += part
            if b'\n' in buffer:
                break

        if not buffer:
            return

        raw_data = buffer.decode().strip()
        request = json.loads(raw_data)

        operation = request.get("action", "")

        if operation == "ping":
            current_uptime = round(time.time() - server_start_time) if server_start_time else 0
            response = {
                "status": "ok",
                "model_name": MODEL_NAME,
                "uptime_seconds": current_uptime
            }
        elif operation == "embed":
            timing_start = time.time()
            result_vector = generate_embedding(request["text"])
            elapsed_ms = round((time.time() - timing_start) * 1000)
            response = {
                "embedding": result_vector,
                "processing_time_ms": elapsed_ms
            }
        elif operation == "embed_batch":
            timing_start = time.time()
            result_vectors = generate_batch_embeddings(request["texts"])
            elapsed_ms = round((time.time() - timing_start) * 1000)
            response = {
                "embeddings": result_vectors,
                "processing_time_ms": elapsed_ms
            }
        else:
            response = {"error": f"Unsupported action: {operation}"}

        client_socket.sendall((json.dumps(response) + "\n").encode())

    except Exception as exception:
        try:
            error_response = {"error": str(exception)}
            client_socket.sendall((json.dumps(error_response) + "\n").encode())
        except:
            pass
    finally:
        client_socket.close()

def start_embed_server():
    # Remove any existing socket file
    if os.path.exists(SOCKET_PATH):
        os.remove(SOCKET_PATH)

    # Load the model before starting to serve requests
    initialize_model()

    # Create and configure Unix domain socket server
    server_socket = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    server_socket.bind(SOCKET_PATH)
    server_socket.listen(5)

    # Set permissions for socket file
    os.chmod(SOCKET_PATH, 0o666)

    # Write PID file
    with open(PID_FILE, "w") as pid_file:
        pid_file.write(str(os.getpid()))

    def graceful_shutdown(signum, frame):
        logger.info("Initiating shutdown sequence...")
        server_socket.close()

        # Clean up files
        for path in [SOCKET_PATH, PID_FILE]:
            if os.path.exists(path):
                os.remove(path)

        sys.exit(0)

    # Register signal handlers
    signal.signal(signal.SIGTERM, graceful_shutdown)
    signal.signal(signal.SIGINT, graceful_shutdown)

    logger.info(f"Embedding service started on socket: {SOCKET_PATH}")

    while True:
        try:
            client_conn, _ = server_socket.accept()
            thread = threading.Thread(
                target=process_client_connection,
                args=(client_conn,),
                daemon=True
            )
            thread.start()
        except OSError:
            break

def verify_service_status():
    if not os.path.exists(SOCKET_PATH):
        print("Embedding service: OFFLINE")
        return False

    try:
        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        sock.connect(SOCKET_PATH)
        sock.sendall(b'{"action":"ping"}\n')
        response_data = sock.recv(4096).decode().strip()
        sock.close()

        response = json.loads(response_data)
        print(f"Embedding service: ONLINE (uptime={response.get('uptime_seconds', '?')}s, model={response.get('model_name', '?')})")
        return True
    except:
        print("Embedding service: UNRESPONSIVE (stale socket)")
        return False

def terminate_service():
    if os.path.exists(PID_FILE):
        with open(PID_FILE) as pid_file:
            pid_content = pid_file.read().strip()
            try:
                pid = int(pid_content)
                os.kill(pid, signal.SIGTERM)
                print(f"Termination signal sent to process {pid}")
            except (ValueError, ProcessLookupError) as e:
                print(f"Process ID {pid_content} invalid or not found: {e}")

        if os.path.exists(PID_FILE):
            os.remove(PID_FILE)

    if os.path.exists(SOCKET_PATH):
        os.remove(SOCKET_PATH)

if __name__ == "__main__":
    if "--status" in sys.argv:
        verify_service_status()
    elif "--stop" in sys.argv:
        terminate_service()
    else:
        start_embed_server()

import argparse
import glob
import json
import os
import re
import sys
import numpy as np

def locate_measurement_file(measurement_name, measurements_dir, use_scales, group_size):
    search_tag = "_" + measurement_name + "_" + str(group_size)
    for file_entry in os.listdir(measurements_dir):
        decoded_name = os.fsdecode(file_entry)
        if not decoded_name.endswith(".json") or "_mod_list" in decoded_name or search_tag not in decoded_name:
            continue
        if use_scales:
            if "MAXABS" in decoded_name:
                return os.path.join(measurements_dir, file_entry)
        else:
            if "MAXABS" not in decoded_name:
                return os.path.join(measurements_dir, file_entry)

def is_moe_fusion_operation(node_identifier):
    name_lower = node_identifier.lower()
    return ("moe" in name_lower and ".w13_list" not in node_identifier and ".w2_list" not in node_identifier)

def is_moe_expert_layer(node_identifier):
    name_lower = node_identifier.lower()
    return ("moe" in name_lower and (".w13_list" in node_identifier or ".w2_list" in node_identifier))

def extract_expert_index(node_identifier):
    segments = node_identifier.split(".")
    assert segments[-1].isdigit(), f"Invalid expert node: {node_identifier}"
    return int(segments[-1])

def extract_expert_base(node_identifier):
    segments = node_identifier.split(".")
    assert segments[-1].isdigit(), f"Invalid expert node: {node_identifier}"
    return ".".join(segments[:-1])

def determine_local_expert_count(json_data):
    max_idx = -1
    for mod_name in json_data["Nodes"]:
        if is_moe_expert_layer(mod_name):
            idx = extract_expert_index(mod_name)
            max_idx = max(max_idx, idx)
    return max_idx + 1

def consolidate_measurements(measurement_set,
                             measurements_dir,
                             output_dir,
                             total_groups,
                             num_groups,
                             group_id,
                             use_scales=False,
                             enable_expert_parallelism=False):
    file_paths = []
    combined_name = ""

    # Collect all relevant JSON files for the current measurement set
    for measurement in measurement_set:
        path = locate_measurement_file(measurement, measurements_dir, use_scales, total_groups)
        if path is not None:
            file_paths.append(path)
        combined_name += measurement

    if not file_paths:
        print("Error: No valid measurement files found.")
        return

    # Load all JSON contents
    json_contents = []
    for path in file_paths:
        with open(path) as f:
            data = json.load(f)
            json_contents.append(data["Nodes"])

    # Prepare unified JSON filename
    base_path = locate_measurement_file(measurement_set[0], measurements_dir, use_scales, total_groups)
    old_pattern = "_" + measurement_set[0] + "_" + str(total_groups)
    new_pattern = "_" + str(group_id) + "_" + str(num_groups)
    unified_filename = os.path.basename(base_path).replace(old_pattern, new_pattern)
    unified_filepath = os.path.join(output_dir, unified_filename)

    # Create initial unified JSON by copying first file
    with open(file_paths[0]) as src, open(unified_filepath, "w") as dst:
        dst.write(src.read())

    # Load unified JSON for modification
    with open(unified_filepath) as f:
        unified_data = json.load(f)
        unified_data["LocalRank"] = group_id if num_groups != 1 else -1

    expert_storage = {}
    local_expert_count = determine_local_expert_count(unified_data) if enable_expert_parallelism else -1

    # Process each node in the unified JSON
    for node_name, node_data in unified_data["Nodes"].items():
        input_max = node_data["inputs"]
        output_max = node_data.get("outputs")
        weight_max = None
        if node_data.get("params") and node_data["params"].get("weight"):
            weight_max = node_data["params"]["weight"]

        if use_scales:
            for idx, content in enumerate(json_contents):
                if enable_expert_parallelism and is_moe_expert_layer(node_name):
                    if node_name not in expert_storage:
                        expert_storage[node_name] = node_data.copy()
                    else:
                        base_name = extract_expert_base(node_name)
                        expert_id = extract_expert_index(node_name)
                        new_node_name = f"{base_name}.{local_expert_count * idx + expert_id}"
                        assert new_node_name not in expert_storage
                        expert_storage[new_node_name] = content[node_name]
                    continue

                if enable_expert_parallelism and is_moe_fusion_operation(node_name) and idx > 0:
                    input_max[0] = max(content[node_name]["inputs"][0], input_max[0])
                    input_max.extend(content[node_name]["inputs"][1:])
                else:
                    for i in range(len(input_max)):
                        input_max[i] = max(content[node_name]["inputs"][i], input_max[i])

                if output_max is not None:
                    output_max = max(content[node_name]["outputs"], output_max)

                if weight_max is not None:
                    weight_max = max(content[node_name]["params"]["weight"], weight_max)
        else:
            for idx, content in enumerate(json_contents):
                if enable_expert_parallelism and is_moe_expert_layer(node_name):
                    if node_name not in expert_storage:
                        expert_storage[node_name] = node_data.copy()
                    else:
                        base_name = extract_expert_base(node_name)
                        expert_id = extract_expert_index(node_name)
                        new_node_name = f"{base_name}.{local_expert_count * idx + expert_id}"
                        assert new_node_name not in expert_storage
                        expert_storage[new_node_name] = content[node_name]
                    continue

                for i in range(len(input_max)):
                    for j in range(len(input_max[i])):
                        input_max[i][j][0] = max(content[node_name]["inputs"][i][j][0], input_max[i][j][0])

                if output_max is not None:
                    if enable_expert_parallelism and is_moe_fusion_operation(node_name) and idx > 0:
                        output_max[0][0] = max(content[node_name]["outputs"][0][0], output_max[0][0])
                        output_max.extend(content[node_name]["outputs"][1:])
                    else:
                        for i in range(len(output_max)):
                            output_max[i][0] = max(content[node_name]["outputs"][i][0], output_max[i][0])

                if weight_max is not None:
                    for i in range(len(weight_max)):
                        weight_max[i][0] = max(content[node_name]["params"]["weight"][i][0], weight_max[i][0])

        # Update unified JSON with maximum values
        if use_scales:
            for i in range(len(input_max)):
                unified_data["Nodes"][node_name]["inputs"][i] = input_max[i]
            if output_max is not None:
                unified_data["Nodes"][node_name]["outputs"] = output_max
            if weight_max is not None:
                unified_data["Nodes"][node_name]["params"]["weight"] = weight_max
        else:
            for i in range(len(input_max)):
                for j in range(len(input_max[i])):
                    unified_data["Nodes"][node_name]["inputs"][i][j][0] = input_max[i][j][0]
            if output_max is not None:
                for i in range(len(output_max)):
                    unified_data["Nodes"][node_name]["outputs"][i][0] = output_max[i][0]
            if weight_max is not None:
                for i in range(len(weight_max)):
                    unified_data["Nodes"][node_name]["params"]["weight"][i][0] = weight_max[i][0]

    if enable_expert_parallelism:
        unified_data["Nodes"].update(expert_storage)

    global_rank = None
    local_rank = group_id if num_groups != 1 else -1
    mode = unified_data["Mode"]
    layers = {}

    # Save updated JSON
    with open(unified_filepath, "w") as f:
        json.dump(unified_data, f, indent=4)

    # Prepare NPZ data
    npz_path = os.path.join(output_dir, unified_filename.replace(".json", ".npz"))
    for layer_name, layer_data in unified_data["Nodes"].items():
        layers[layer_name] = {
            "inputs": [np.array(x) for x in layer_data["inputs"]],
        }
        if layer_data.get("outputs"):
            layers[layer_name]["outputs"] = [np.array(x) for x in layer_data["outputs"]]
        if layer_data.get("params") and layer_data["params"].get("weight"):
            layers[layer_name]["params"] = {
                "weight": np.array(layer_data["params"]["weight"])
            }

    final_data = {
        "GlobalRank": global_rank,
        "LocalRank": local_rank,
        "Mode": mode,
        "Nodes": layers
    }
    np.savez(npz_path, **final_data)

def parse_arguments(cli_args):
    parser = argparse.ArgumentParser(
        description="Consolidate measurement files",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter
    )
    parser.add_argument("-m", "--measurements", type=str,
                        help="Directory containing measurement files to unify")
    parser.add_argument("-r", "--rank", type=int,
                        help="Target number of ranks for unification")
    parser.add_argument("-o", "--output", type=str, default=os.getcwd(),
                        help="Output directory for unified files")
    parser.add_argument("-u", "--expert-parallel", action="store_true",
                        help="Enable expert parallelism during unification")
    parser.add_argument("-s", "--skip-scales", action="store_true",
                        help="Skip scale unification step")
    return parser.parse_args(cli_args)

def create_grouping(measurements_dir, target_ranks):
    mod_files = glob.glob(os.path.join(measurements_dir, "*_mod_list.json"))
    if not mod_files:
        raise ValueError(f"No *_mod_list.json files found in {measurements_dir}")

    filename = os.path.basename(mod_files[0])
    match = re.match(r"^(\w+)_(\d+)_(\d+)_(\w+)_(\w+)\.json$", filename)
    if not match:
        raise ValueError(f"Unrecognized file naming pattern: {filename}")

    original_ranks = int(match.group(3))
    if target_ranks >= original_ranks or original_ranks % target_ranks != 0:
        raise ValueError(f"Invalid rank configuration: {original_ranks} cannot be grouped into {target_ranks}")

    group_size = original_ranks // target_ranks
    groups = [[str(i * group_size + j) for j in range(group_size)] for i in range(target_ranks)]
    print(f"Card grouping list >> {groups}")
    return groups

def main(cli_args):
    args = parse_arguments(cli_args)
    output_dir = args.output
    os.makedirs(output_dir, exist_ok=True)

    measurements_dir = args.measurements
    groups = create_grouping(measurements_dir, args.rank)

    # Count measurement files
    drange_count = sum(1 for f in os.listdir(measurements_dir) 
                      if f.endswith(".json") and "MAXABS" not in f and "mod_list" not in f)
    scales_count = sum(1 for f in os.listdir(measurements_dir) 
                      if f.endswith(".json") and "MAXABS" in f)

    assert len(groups) > 0 and drange_count % len(groups) == 0 and scales_count % len(groups) == 0

    for idx, group in enumerate(groups):
        consolidate_measurements(group, measurements_dir, output_dir,
                                drange_count, len(groups), idx,
                                use_scales=False,
                                enable_expert_parallelism=args.expert_parallel)

        if not args.skip_scales:
            consolidate_measurements(group, measurements_dir, output_dir,
                                    scales_count, len(groups), idx,
                                    use_scales=True,
                                    enable_expert_parallelism=args.expert_parallel)

    print("Measurement consolidation completed successfully")

if __name__ == "__main__":
    main(sys.argv[1:])

