import functools
import logging
import warnings
from torch.utils.data import DataLoader, DistributedSampler, IterableDataset
from torch.utils.data.dataloader import _BaseDataLoaderIter
from speechbrain.dataio.batch import BatchsizeGuesser, PaddedBatch
from speechbrain.dataio.dataset import DynamicItemDataset
from speechbrain.dataio.sampler import (
    DistributedSamplerWrapper,
    ReproducibleRandomSampler,
)
from speechbrain.utils.checkpoints import (
    mark_as_loader,
    mark_as_saver,
    register_checkpoint_hooks,
)

# WebDataset support (with version detection)
try:
    import webdataset as wds
    from importlib_metadata import version as pkg_version
    WDS_ENABLED = True
    v_str = pkg_version("webdataset")
    WDS_BASE_CLASS = wds.dataset.Composable if v_str.startswith("0.1.") else wds.DataPipeline
except ImportError:
    WDS_ENABLED = False
    WDS_BASE_CLASS = None

_logger = logging.getLogger(__name__)


def prepare_distributed_config(is_ddp: bool, local_rank: int, data_obj, kwargs_dict):
    """Adjusts DataLoader configuration for distributed training scenarios."""
    sampler = kwargs_dict.get("sampler", None)
    do_shuffle = kwargs_dict.get("shuffle", False)

    if is_ddp and not isinstance(data_obj, IterableDataset):
        drop_last = kwargs_dict.get("drop_last", False)

        if sampler is not None:
            wrapped_sampler = DistributedSamplerWrapper(
                sampler,
                rank=local_rank,
                drop_last=drop_last,
                shuffle=do_shuffle,
            )
            kwargs_dict["shuffle"] = False
            kwargs_dict["sampler"] = wrapped_sampler
        elif kwargs_dict.get("batch_sampler") is None:
            dist_sampler = DistributedSampler(
                data_obj,
                rank=local_rank,
                drop_last=drop_last,
            )
            kwargs_dict["shuffle"] = False
            kwargs_dict["sampler"] = dist_sampler
        else:
            batch_sampler = kwargs_dict["batch_sampler"]
            wrapped_batch_sampler = DistributedSamplerWrapper(
                batch_sampler,
                rank=local_rank,
            )
            kwargs_dict["batch_sampler"] = wrapped_batch_sampler
    elif is_ddp and isinstance(data_obj, IterableDataset):
        _logger.warning(
            "Automatic distributed sampling not supported for IterableDataset."
        )

    return kwargs_dict


def build_data_pipeline(dataset, epoch_steps=None, **loader_opts):
    """Constructs a DataLoader with SpeechBrain conventions."""
    # Default collation for dict-returning datasets
    if "collate_fn" not in loader_opts and isinstance(dataset, DynamicItemDataset):
        loader_opts["collate_fn"] = PaddedBatch

    # Handle shuffling via reproducible sampler
    if loader_opts.get("shuffle", False):
        if loader_opts.get("sampler") is not None:
            raise ValueError("Cannot specify both shuffle=True and a sampler.")
        new_sampler = ReproducibleRandomSampler(dataset)
        loader_opts["sampler"] = new_sampler
        del loader_opts["shuffle"]

    # Set default batch_size=None for webdataset pipelines
    if (
        WDS_ENABLED
        and isinstance(dataset, WDS_BASE_CLASS)
        and "batch_size" not in loader_opts
    ):
        loader_opts["batch_size"] = None

    # Instantiate appropriate loader type
    if isinstance(dataset, IterableDataset):
        base_loader = DataLoader(dataset, **loader_opts)
    else:
        base_loader = SaveableDataLoader(dataset, **loader_opts)

    # Wrap in LoopedLoader if needed
    if epoch_steps is not None:
        return LoopedLoader(base_loader, epoch_steps)
    return base_loader


# Patch PyTorch's internal iterator initialization for checkpoint recovery
def _patched_init(self, loader, *args, **kwargs):
    self.__base_init__(loader, *args, **kwargs)
    skip_count = getattr(loader, "_speechbrain_recovery_skip_to", None)
    if skip_count is not None and skip_count > 0:
        for idx in range(skip_count):
            try:
                next(self._sampler_iter)
            except StopIteration:
                msg = (
                    f"Attempted to skip {skip_count} samples after checkpoint "
                    f"recovery, but stopped early at index {idx}."
                )
                warnings.warn(msg)
                break
            self._num_yielded = idx + 1
        loader._speechbrain_recovery_skip_to = None


def _patched_reset(self, loader, first_time=False, *args, **kwargs):
    if not first_time:
        self._sampler_iter = iter(self._index_sampler)
        self._num_yielded = 0
        self._IterableDataset_len_called = loader._IterableDataset_len_called


functools.update_wrapper(_patched_init, _BaseDataLoaderIter.__init__)
_BaseDataLoaderIter.__base_init__ = _BaseDataLoaderIter.__init__
_BaseDataLoaderIter.__init__ = _patched_init

if hasattr(_BaseDataLoaderIter, "_reset"):
    _BaseDataLoaderIter._reset = _patched_reset


@register_checkpoint_hooks
class CheckpointableDataLoader(DataLoader):
    """A PyTorch DataLoader subclass supporting state persistence."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        if isinstance(self.dataset, IterableDataset):
            logging.warning(
                "Checkpointing position in IterableDataset is unsupported. "
                "Please manage state on the dataset directly."
            )
        self._sb_recovery_step = None
        self._sb_active_iter = None

    def __iter__(self):
        it = super().__iter__()
        self._sb_active_iter = it
        return it

    @mark_as_saver
    def _sb_save_state(self, path):
        if isinstance(self.dataset, IterableDataset):
            logging.warning(
                "Cannot persist IterableDataset position during checkpointing."
            )
            return

        current_pos = (
            self._sb_active_iter._num_yielded
            if self._sb_active_iter is not None
            else None
        )
        with open(path, "w") as f:
            f.write(str(current_pos))

    @mark_as_loader
    def _sb_load_state(self, path, at_epoch_end):
        if self._sb_active_iter is not None:
            logging.debug(
                "Ignoring load request: DataLoader already iterated. "
                "This may be expected during evaluation."
            )
            return

        if at_epoch_end:
            return

        with open(path) as f:
            content = f.read().strip()
            if content == "None":
                return
            self._sb_recovery_step = int(content)


@register_checkpoint_hooks
class InfiniteEpochLoader:
    """Provides repeated iteration over a loader with configurable epoch boundaries."""

    def __init__(self, source_loader, steps_per_epoch, size_estimator=None):
        self.source = source_loader
        self.iterator = None
        self.epoch_limit = steps_per_epoch
        self.current_step = 0
        self.global_step = 0
        self.total_seen = 0

        self.size_func = size_estimator or BatchsizeGuesser()

    def __iter__(self):
        if self.iterator is None:
            self.iterator = iter(self.source)
        return self

    def __next__(self):
        if self.current_step < self.epoch_limit:
            self.current_step += 1
            self.global_step += 1

            try:
                item = next(self.iterator)
            except StopIteration:
                self.iterator = iter(self.source)
                item = next(self.iterator)

            self.total_seen += self.size_func(item)
            return item
        else:
            self.current_step = 0
            raise StopIteration

    def __len__(self):
        return self.epoch_limit

    @mark_as_saver
    def sb_save(self, path):
        with open(path, "w") as f:
            print(self.current_step, file=f)
            print(self.global_step, file=f)
            print(self.total_seen, file=f)

    @mark_as_loader
    def sb_load(self, path, at_epoch_end=True):
        with open(path) as f:
            lines = [line.strip() for line in f.readlines()]
            self.current_step = int(lines[0])
            self.global_step = int(lines[1])
            self.total_seen = int(lines[2])

            if not at_epoch_end and self.current_step == 0 and self.global_step > 0:
                self.current_step = self.epoch_limit

import argparse
import sys
import logging

def run():
    parser = argparse.ArgumentParser(description='Scrapling fetcher tool')
    parser.add_argument('target_url', metavar='URL', help='Target URL to retrieve')
    parser.add_argument('--mode', choices=['standard', 'evasive', 'rendered'], default='standard',
