import uuid
import torch.distributed as dist
from torch.distributed.distributed_c10d import _get_default_store

class DistributedMutex:
    def __init__(self, identifier, retry_delay=0.05, group_suffix=None):
        if not dist.is_initialized():
            raise RuntimeError("Distributed process group must be initialized first")

        self.backend = _get_default_store()
        suffix = group_suffix or f"group{dist.get_world_size()}"
        self.prefix = f"distributed_mutex/{suffix}/{identifier}"
        self.counter_key = f"{self.prefix}/seq"
        self.owner_key = f"{self.prefix}/holder"
        self.retry_interval = retry_delay
        self.my_id = None

        # Initialize counter atomically if not exists
        try:
            self.backend.add(self.counter_key, 0)
        except RuntimeError:
            pass

    def lock(self, max_wait=None):
        begin_time = time.perf_counter()
        current_delay = self.retry_interval
        my_identity = f"{dist.get_rank()}:{uuid.uuid4()}".encode()

        while True:
            try:
                # Atomically increment and get previous value
                prev_count = self.backend.add(self.counter_key, 1)

                if prev_count == 0:
                    # First in line, claim the lock
                    self._assign_holder(my_identity)
                    self.my_id = my_identity
                    return True

                # Not first, decrement counter (rollback)
                self._decrement_counter()

            except RuntimeError:
                # Handle contention or network issues gracefully
                pass

            # Check timeout condition
            if max_wait is not None and (time.perf_counter() - begin_time) > max_wait:
                return False

            # Exponential backoff with cap
            time.sleep(current_delay)
            current_delay = min(current_delay * 1.5, 0.5)

    def unlock(self):
        if self.my_id is None:
            raise RuntimeError("Attempted to release unheld lock")

        current_holder = self._retrieve_holder()
        if current_holder is not None and current_holder != self.my_id:
            raise RuntimeError("Lock ownership conflict: cannot release another's lock")

        self._remove_holder()
        self._decrement_counter()
        self.my_id = None

    def _decrement_counter(self):
        wait_time = self.retry_interval
        while True:
            try:
                self.backend.add(self.counter_key, -1)
                return
            except RuntimeError:
                time.sleep(wait_time)
                wait_time = min(wait_time * 1.5, 0.5)

    def _assign_holder(self, identity: bytes):
        try:
            self.backend.set(self.owner_key, identity)
        except RuntimeError as e:
            self._decrement_counter()
            raise RuntimeError("Unable to record lock holder") from e

    def _retrieve_holder(self) -> bytes | None:
        try:
            result = self.backend.get(self.owner_key)
            return result if result else None
        except RuntimeError:
            return None

    def _remove_holder(self):
        try:
            self.backend.set(self.owner_key, b"")
        except RuntimeError:
            pass

    def __enter__(self):
        self.lock()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.unlock()
        return False

