# Utility: Dynamic patch registration
def register_patches(manager, patch_map):
    """Register multiple patches at once using a mapping."""
    for target_path, (patch_obj, force) in patch_map.items():
        manager.register_patch(target_path, patch_obj, force_patch=force)

# Decorator classes for type-safe wrapping
class LinearWrapper:
    def __init__(self, fn):
        self.fn = fn

    def __call__(self, inp, weight, bias=None):
        dtypes = {inp.dtype, weight.dtype}
        if dtypes == {mindspore.float32, mindspore.bfloat16}:
            res = self.fn(
                inp.to(mindspore.float32),
                weight.to(mindspore.float32),
                bias.to(mindspore.float32) if bias is not None else None
            )
            return res.to(weight.dtype)
        return self.fn(inp, weight, bias)

class MatmulWrapper:
    def __init__(self, fn):
        self.fn = fn

    def __call__(self, inp, other, *args, **kwargs):
        dtypes = {inp.dtype, other.dtype}
        if dtypes == {mindspore.float32, mindspore.bfloat16}:
            res = self.fn(
                inp.to(mindspore.float32),
                other.to(mindspore.float32),
                *args,
                **kwargs
            )
            return res.to(inp.dtype)
        return self.fn(inp, other, *args, **kwargs)

class ScatterAddWrapper:
    def __init__(self, fn):
        self.fn = fn

    def __call__(self, self_tensor, dim, index, src):
        if not index.is_contiguous():
            index = index.contiguous()
        return self.fn(self_tensor, dim, index, src)

# Custom masked_scatter implementation
def custom_masked_scatter(tensor, mask, updates):
    orig_dtype = None
    if tensor.dtype in (mindspore.float16, mindspore.bfloat16):
        orig_dtype = tensor.dtype
        tensor = tensor.to(mindspore.float32)
    if updates.dtype in (mindspore.float16, mindspore.bfloat16):
        updates = updates.to(mindspore.float32)
    result = mindspore.ops.MaskedScatter()(tensor, mask, updates)
    return result.to(orig_dtype) if orig_dtype else result

# Helper: Version-aware conditional patching
