# Text encoder implementation for Qwen3-based models with optional quantization and CPU offloading

import gc
import os
import torch
from PIL import Image
from lightx2v.utils.envs import *
try:
    from transformers import Qwen2Tokenizer, Qwen3Model
except ImportError:
    Qwen2Tokenizer = None
    Qwen3Model = None
from lightx2v_platform.base.global_var import AI_DEVICE
torch_device_module = getattr(torch, AI_DEVICE)
try:
    from diffusers.image_processor import VaeImageProcessor
except ImportError:
    VaeImageProcessor = None

class Qwen3TextEncoderWrapper:
    def __init__(self, config_params):
        self.config = config_params
        self.max_seq_len = 512
        self.enable_cpu_offload = config_params.get("qwen3_cpu_offload", config_params.get("cpu_offload", False))
        self.is_quantized = config_params.get("qwen3_quantized", False)
        self._initialize_components()

    def _initialize_components(self):
        if self.is_quantized:
            assert self.config["qwen3_quant_scheme"] == "int4"
            model_path = self.config["qwen3_quantized_ckpt"]
            self.text_model = Qwen3Model.from_pretrained(
                model_path, 
                torch_dtype=GET_DTYPE(), 
                device_map=AI_DEVICE
            )
        else:
            base_path = self.config.get("qwen3_original_ckpt", os.path.join(self.config["model_path"], "text_encoder"))
            if self.enable_cpu_offload:
                self.text_model = Qwen3Model.from_pretrained(
                    base_path, 
                    torch_dtype=GET_DTYPE(), 
                    device_map="cpu"
                )
            else:
                self.text_model = Qwen3Model.from_pretrained(
                    base_path, 
                    torch_dtype=GET_DTYPE(), 
                    device_map=AI_DEVICE
                )

        tokenizer_dir = self.config.get("qwen3_tokenizer_path", os.path.join(self.config["model_path"], "tokenizer"))
        self.tokenizer = Qwen2Tokenizer.from_pretrained(tokenizer_dir)

        if self.config["task"] == "i2i":
            scale_factor = self.config["vae_scale_factor"] * 2
            self.image_transformer = VaeImageProcessor(vae_scale_factor=scale_factor)

    def prepare_image_input(self, img_data):
        if isinstance(img_data, Image.Image):
            processed_img = self.image_transformer.preprocess(img_data)
        elif isinstance(img_data, torch.Tensor):
            if len(img_data.shape) == 3:
                img_data = img_data.unsqueeze(0)
            processed_img = img_data
        else:
            raise TypeError(f"Unsupported image format: {type(img_data)}")
        return processed_img

    @torch.no_grad()
    def encode(self, text_prompts, images=None):
        # Move model to device if needed
        if self.enable_cpu_offload and not self.is_quantized:
            self.text_model.to(AI_DEVICE)

        # Normalize input to list format
        if isinstance(text_prompts, str):
            text_prompts = [text_prompts]

        # Apply chat template to each prompt
        for idx, prompt in enumerate(text_prompts):
            conversation = [{"role": "user", "content": prompt}]
            formatted_prompt = self.tokenizer.apply_chat_template(
                conversation, 
                tokenize=False, 
                add_generation_prompt=True, 
                enable_thinking=True
            )
            text_prompts[idx] = formatted_prompt

        # Tokenize inputs
        tokenized_inputs = self.tokenizer(
            text_prompts, 
            max_length=self.max_seq_len, 
            padding="max_length", 
            truncation=True, 
            return_tensors="pt"
        ).to(AI_DEVICE)

        attention_mask = tokenized_inputs.attention_mask.bool().to(AI_DEVICE)

        # Extract hidden states from the second-to-last layer
        outputs = self.text_model(
            input_ids=tokenized_inputs.input_ids,
            attention_mask=attention_mask,
            output_hidden_states=True,
        )
        hidden_states = outputs.hidden_states[-2]

        # Collect per-prompt embeddings by masking padded tokens
        final_embeddings = []
        for i in range(len(hidden_states)):
            masked_tokens = hidden_states[i][attention_mask[i]]
            final_embeddings.append(masked_tokens)

        # Prepare image-related data if applicable
        image_context = {}
        if self.config["task"] == "i2i" and images is not None:
            processed_images = []
            for img in images:
                processed_images.append(self.prepare_image_input(img))
            image_context = {
                "processed_vae_inputs": processed_images,
            }

        # Offload model back to CPU if enabled
        if self.enable_cpu_offload and not self.is_quantized:
            self.text_model.to(torch.device("cpu"))
            torch_device_module.empty_cache()
            gc.collect()

        return final_embeddings, image_context

