class _PydanticMock(MagicMock):
    """Custom mock that supports Pydantic schema generation."""
    def __init__(self, *args, **kwargs):
        identifier = kwargs.pop("name", None)
        super().__init__(*args, **kwargs)
        self.__spec__ = ModuleSpec(identifier, None)
        self._mock_name = identifier or "placeholder"

    def __get_pydantic_core_schema__(self, src_type, handler):
        return core_schema.any_schema()


class _AdaptiveParser(ArgumentParser):
    """Parser with deprecation handling and fallback support."""
    _deprecated_actions: set[Action] = set()
    _notified_deprecated: set[str] = set()

    if sys.version_info < (3, 13):
        def parse_known_args(self, args=None, namespace=None):
            ns, remaining = super().parse_known_args(args, namespace)
            for act in _AdaptiveParser._deprecated_actions:
                attr_name = act.dest
                if hasattr(ns, attr_name) and getattr(ns, attr_name) != act.default and attr_name not in _AdaptiveParser._notified_deprecated:
                    _AdaptiveParser._notified_deprecated.add(attr_name)
                    log.warning("Deprecated option '%s' used", attr_name)
            return ns, remaining

    def add_argument(self, *args, **kwargs):
        deprecated_flag = kwargs.pop("deprecated", False)
        action = super().add_argument(*args, **kwargs)
        if deprecated_flag:
            _AdaptiveParser._deprecated_actions.add(action)
        return action

    class _ExtendedGroup(_ArgumentGroup):
        def add_argument(self, *args, **kwargs):
            deprecated_flag = kwargs.pop("deprecated", False)
            action = super().add_argument(*args, **kwargs)
            if deprecated_flag:
                _AdaptiveParser._deprecated_actions.add(action)
            return action

    def add_argument_group(self, *args, **kwargs):
        group = self._ExtendedGroup(self, *args, **kwargs)
        self._action_groups.append(group)
        return group


def _extract_cli_parser():
    """
    Extract CLI parser definition by parsing serve.py AST.
    Avoids runtime import issues via static analysis.
    """
    cli_file = PROJECT_ROOT / "vllm_omni" / "entrypoints" / "cli" / "serve.py"
    try:
        with open(cli_file, encoding="utf-8") as fh:
            content = fh.read()
        tree = ast.parse(content, filename=str(cli_file))

        # Locate OmniServeCommand class and subparser_init method
        for node in tree.body:
            if isinstance(node, ast.ClassDef) and node.name == "OmniServeCommand":
                for stmt in node.body:
                    if isinstance(stmt, ast.FunctionDef) and stmt.name == "subparser_init":
                        func_ast = ast.Module(body=[stmt], type_ignores=[])
                        compiled = compile(func_ast, filename=str(cli_file), mode="exec")

                        # Prepare execution environment
                        local_env = {}
                        desc_match = re.search(r'DESCRIPTION\s*=\s*([ru]?""".*?""")', content, re.DOTALL)
                        description = desc_match.group(1)[3:-3] if desc_match else ""

                        exec_globals = {
                            "_AdaptiveParser": _AdaptiveParser,
                            "FlexibleArgumentParser": _AdaptiveParser,
                            "make_arg_parser": lambda p: p,
                            "VLLM_SUBCMD_PARSER_EPILOG": "",
                            "log": log,
                            "DummySubparsers": type("DummySubparsers", (), {
                                "add_parser": lambda self, name, **kw: _AdaptiveParser(prog=name)
                            })(),
                            "argparse": __import__("argparse"),
                            "json": __import__("json"),
                            "DESCRIPTION": description,
                        }
                        exec(compiled, exec_globals, local_env)

                        # Retrieve and wrap the extracted function
                        init_func = local_env["subparser_init"]
                        def factory():
                            class DummyInstance:
                                name = "serve"
                            return init_func(DummyInstance(), type("DummySubparsers", (), {
                                "add_parser": lambda self, name, **kw: _AdaptiveParser(prog=name)
                            })())
                        return factory
        raise RuntimeError("Failed to extract subparser_init from OmniServeCommand")
    except Exception as e:
        raise RuntimeError(f"CLI parser extraction failed: {e}")


# Construct OmniServeCommand dynamically using extracted parser factory
OmniServeCommand = type("OmniServeCommand", (), {"subparser_init": staticmethod(_extract_cli_parser())})


class _MarkdownHelpFormatter(HelpFormatter):
    """Generates markdown-formatted help output."""
    def __init__(self, prog: str, heading_level: int = 3):
        super().__init__(prog, max_help_position=sys.maxsize, width=sys.maxsize)
        self._section_prefix = "#" * heading_level
        self._option_prefix = "#" * (heading_level + 1)
        self._output_lines: list[str] = []

    def start_section(self, title: str):
        if title not in {"positional arguments", "options"}:
            self._output_lines.append(f"\n{self._section_prefix} {title}\n\n")

    def end_section(self):
        pass

    def add_text(self, text: str):
        if text:
            self._output_lines.append(f"{text.strip()}\n\n")

    def add_usage(self, usage, actions, groups, prefix=None):
        pass

    def add_arguments(self, actions: Iterable[Action]):
        for act in actions:
            if not act.option_strings or "--help" in act.option_strings:
                continue

            # Format option strings
            opts = f"`{'`, `'.join(act.option_strings)}`"
            self._output_lines.append(f"{self._option_prefix} {opts}\n\n")

            # Handle choices/metavar
            if act.choices:
                choices_str = f"`{'`, `'.join(str(c) for c in act.choices)}`"
                self._output_lines.append(f"Possible choices: {choices_str}\n\n")
            elif act.metavar and isinstance(act.metavar, (list, tuple)):
                metavar_str = f"`{'`, `'.join(str(m) for m in act.metavar)}`"
                self._output_lines.append(f"Possible choices: {metavar_str}\n\n")

            # Add help text
            if act.help:
                self._output_lines.append(f"{act.help}\n\n")

            # Include default value if applicable
            default_val = act.default
            if default_val is not SUPPRESS:
                if default_val == "":
                    default_val = '""'
                self._output_lines.append(f"Default: `{default_val}`\n\n")

    def format_help(self) -> str:
        return "".join(self._output_lines)


def _build_parser_from_command(cmd_class):
    """Constructs an argument parser using command class's subparser_init method."""
    dummy_subparsers = type("DummySubparsers", (), {
        "add_parser": lambda self, name, **kw: _AdaptiveParser(prog=name)
    })()

    init_method = getattr(cmd_class, "subparser_init", None)
    if init_method is None:
        raise ValueError("Command class lacks subparser_init method")

    # Determine call signature
    import inspect
    sig = inspect.signature(init_method)
    if len(sig.parameters) == 0:
        parser = init_method()
    else:
        parser = cmd_class().subparser_init(dummy_subparsers)

    parser.formatter_class = _MarkdownHelpFormatter
    return parser


def generate_docs(command: Literal["build", "gh-deploy", "serve"], force: bool):
    """Main entry point for generating CLI documentation."""
    log.info("Generating vllm-omni CLI documentation")
    log.debug("Project root: %s", PROJECT_ROOT.resolve())
    log.debug("Output directory: %s", CLI_DOCS_DIR.resolve())

    CLI_DOCS_DIR.mkdir(parents=True, exist_ok=True)

    # Register parsers for all supported commands
    command_parsers = {
        "omni_serve": _build_parser_from_command(OmniServeCommand),
    }

    # Generate markdown files for each parser
    for name, parser in command_parsers.items():
        output_path = CLI_DOCS_DIR / f"{name}.inc.md"
        with open(output_path, "w", encoding="utf-8") as md_file:
            md_file.write(super(type(parser), parser).format_help())
        log.info("Generated: %s", output_path.relative_to(PROJECT_ROOT))


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    generate_docs("build", False)

