    if param_name == "module.module.embedding.word_embeddings.weight":
        return [("model.embed_tokens.weight", param_value)]
    if param_name == "module.module.output_layer.weight":
        return [("lm_head.weight", param_value)]
    if param_name == "module.module.decoder.final_layernorm.weight":
        return [("model.norm.weight", param_value)]

    # Compute head dimension with fallback
    try:
        head_dim = args.kv_channels or (args.hidden_size // args.num_attention_heads)
    except AttributeError:
        head_dim = args.hidden_size // args.num_attention_heads

    num_query_groups = args.num_query_groups
    q_per_group = args.num_attention_heads // num_query_groups

    # Decoder layers pattern
    decoder_pattern = r"module\.module\.decoder\.layers\.(\d+)\.(.+)"
    decoder_match = re.match(decoder_pattern, param_name)

    if decoder_match:
        layer_id, rest_part = decoder_match.groups()
        layer_id = str(layer_id)

        # Experts handling
        expert_regex = r"mlp\.experts\.(.+)\.weight(\d+)"
        expert_match = re.match(expert_regex, rest_part)
        if expert_match:
            sub_part, exp_idx = expert_match.groups()
            if sub_part == "linear_fc1":
                gate_w, up_w = torch.chunk(param_value, 2, dim=0)
                return [
                    (f"model.layers.{layer_id}.mlp.experts.{exp_idx}.gate_proj.weight", gate_w),
                    (f"model.layers.{layer_id}.mlp.experts.{exp_idx}.up_proj.weight", up_w),
                ]
            elif sub_part == "linear_fc2":
                return [(f"model.layers.{layer_id}.mlp.experts.{exp_idx}.down_proj.weight", param_value)]
            else:
                raise ValueError(f"Invalid expert parameter: {param_name}")

        # Shared experts handling
        shared_exp_regex = r"mlp\.shared_experts\.(.+)"
        shared_exp_match = re.match(shared_exp_regex, rest_part)
        if shared_exp_match:
            sub_rest = shared_exp_match.group(1)
            if sub_rest == "linear_fc1.weight":
                gate_w, up_w = torch.chunk(param_value, 2, dim=0)
                return [
                    (f"model.layers.{layer_id}.mlp.shared_experts.gate_proj.weight", gate_w),
                    (f"model.layers.{layer_id}.mlp.shared_experts.up_proj.weight", up_w),
                ]
            elif sub_rest == "linear_fc2.weight":
                return [(f"model.layers.{layer_id}.mlp.shared_experts.down_proj.weight", param_value)]
            else:
                raise ValueError(f"Invalid shared expert parameter: {param_name}")

        # Standard attention and MLP weights/biases
        if rest_part == "self_attention.linear_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.o_proj.weight", param_value)]

        elif rest_part == "self_attention.linear_qkv.weight":
            reshaped = param_value.view(num_query_groups, -1, head_dim, args.hidden_size)
            q_part, k_part, v_part = torch.split(
                reshaped, 
                [q_per_group, 1, 1], 
                dim=1
            )
            q_flat = q_part.reshape(-1, args.hidden_size)
            k_flat = k_part.reshape(-1, args.hidden_size)
            v_flat = v_part.reshape(-1, args.hidden_size)
            return [
                (f"model.layers.{layer_id}.self_attn.q_proj.weight", q_flat),
                (f"model.layers.{layer_id}.self_attn.k_proj.weight", k_flat),
                (f"model.layers.{layer_id}.self_attn.v_proj.weight", v_flat),
            ]

        elif rest_part == "self_attention.linear_qkv.bias":
            bias_view = param_value.view(num_query_groups, -1)
            q_b, k_b, v_b = torch.split(
                bias_view,
                [q_per_group * head_dim, head_dim, head_dim],
                dim=1,
            )
            return [
                (f"model.layers.{layer_id}.self_attn.q_proj.bias", q_b.contiguous().flatten()),
                (f"model.layers.{layer_id}.self_attn.k_proj.bias", k_b.contiguous().flatten()),
                (f"model.layers.{layer_id}.self_attn.v_proj.bias", v_b.contiguous().flatten()),
            ]

        elif rest_part == "mlp.linear_fc1.weight":
            gate_w, up_w = torch.chunk(param_value, 2, dim=0)
            return [
                (f"model.layers.{layer_id}.mlp.gate_proj.weight", gate_w),
                (f"model.layers.{layer_id}.mlp.up_proj.weight", up_w),
            ]

        elif rest_part == "mlp.linear_fc2.weight":
            return [(f"model.layers.{layer_id}.mlp.down_proj.weight", param_value)]

        elif rest_part == "self_attention.linear_qkv.layer_norm_weight":
            return [(f"model.layers.{layer_id}.input_layernorm.weight", param_value)]

        elif rest_part == "mlp.linear_fc1.layer_norm_weight":
            return [(f"model.layers.{layer_id}.post_attention_layernorm.weight", param_value)]

        elif rest_part == "post_self_attn_layernorm.weight":
            return [(f"model.layers.{layer_id}.post_self_attn_layernorm.weight", param_value)]

        elif rest_part == "post_mlp_layernorm.weight":
            return [(f"model.layers.{layer_id}.post_mlp_layernorm.weight", param_value)]

        elif rest_part == "pre_mlp_layernorm.weight":
            return [(f"model.layers.{layer_id}.post_attention_layernorm.weight", param_value)]

        elif rest_part == "mlp.router.weight":
            return [(f"model.layers.{layer_id}.mlp.gate.weight", param_value)]

        elif rest_part == "mlp.router.expert_bias":
            return [(f"model.layers.{layer_id}.mlp.gate.e_score_correction_bias", param_value)]

        elif rest_part == "self_attention.q_layernorm.weight":
            return [(f"model.layers.{layer_id}.self_attn.q_norm.weight", param_value)]

        elif rest_part == "self_attention.k_layernorm.weight":
            return [(f"model.layers.{layer_id}.self_attn.k_norm.weight", param_value)]

    # MTP layers handling
    mtp_pattern = r"module\.module\.mtp\.layers\.(\d+)\.(.+)"
    mtp_match = re.match(mtp_pattern, param_name)
    if mtp_match:
        mtp_layer_id, mtp_rest = mtp_match.groups()
        adjusted_layer_id = int(mtp_layer_id) + args.num_layers
        if mtp_rest == "eh_proj.weight":
            return [(f"model.layers.{adjusted_layer_id}.eh_proj.weight", param_value)]
        elif mtp_rest == "enorm.weight":
            return [(f"model.layers.{adjusted_layer_id}.enorm.weight", param_value)]
        elif mtp_rest == "hnorm.weight":
            return [(f"model.layers.{adjusted_layer_id}.hnorm.weight", param_value)]
        elif mtp_rest == "final_layernorm.weight":
            return [(f"model.layers.{adjusted_layer_id}.shared_head.norm.weight", param_value)]
        else:
            # Recursively handle unknown patterns via fallback mapping
            fallback_name = f"module.module.decoder.layers.{adjusted_layer_id}.{mtp_rest}"
            fallback_name = fallback_name.replace("transformer_layer.", "")
            return transform_glm4moe_weights(args, fallback_name, param_value)

    raise ValueError(f"Unrecognized parameter name: {param_name}")

# WebAuthn credential management endpoints for API v2

from flask import Blueprint, request, g
from auth.unified import require_auth
from models import db
from models.webauthn import WebAuthnCredential
from services.webauthn_service import WebAuthnService
from services.audit_service import AuditService
from utils.response import success_response, error_response

webauthn_bp = Blueprint('webauthn', __name__, url_prefix='/api/v2/webauthn')

@webauthn_bp.route('/credentials', methods=['GET'])
@require_auth()
def list_user_credentials():
    """Retrieve all WebAuthn credentials associated with the authenticated user"""
    current_user = g.current_user
    user_credentials = WebAuthnService.fetch_credentials_for_user(current_user.id)
    return success_response(data=[cred.as_dict() for cred in user_credentials])

@webauthn_bp.route('/credentials/<int:cred_id>', methods=['DELETE'])
@require_auth()
def remove_credential(cred_id):
    """Remove a specific WebAuthn credential by ID"""
    current_user = g.current_user
    deletion_success, deletion_msg = WebAuthnService.remove_credential(cred_id, current_user.id)

    if not deletion_success:
        return error_response(deletion_msg, 404)

    AuditService.record_event(
        event_type='webauthn_delete',
        target_type='webauthn',
        target_id=str(cred_id),
        target_label=f'WebAuthn credential {cred_id}',
        description=f'Removed WebAuthn credential {cred_id}',
        outcome=True
    )

    return success_response(message=deletion_msg)

@webauthn_bp.route('/credentials/<int:cred_id>/status', methods=['POST'])
@require_auth()
def update_credential_status(cred_id):
    """Toggle the enabled/disabled state of a WebAuthn credential"""
    current_user = g.current_user
    payload = request.get_json(silent=True) or {}
    new_status = payload.get('enabled', True)

    operation_success, operation_msg = WebAuthnService.update_credential_status(
        cred_id, current_user.id, new_status
    )

    if not operation_success:
        return error_response(operation_msg, 404)

    AuditService.record_event(
        event_type='webauthn_toggle',
        target_type='webauthn',
        target_id=str(cred_id),
        target_label=f'WebAuthn credential {cred_id}',
        description=f'{"Activated" if new_status else "Deactivated"} WebAuthn credential {cred_id}',
        outcome=True
    )

    return success_response(message=operation_msg)

@webauthn_bp.route('/registration/init', methods=['POST'])
@require_auth()
def initiate_registration():
    """Generate WebAuthn registration parameters using secure cryptographic methods"""
    current_user = g.current_user
    server_host = request.host

    reg_params = WebAuthnService.create_registration_parameters(current_user, server_host)
    return success_response(data=reg_params)

@webauthn_bp.route('/registration/complete', methods=['POST'])
@require_auth()
def finalize_registration():
    """Process and store verified WebAuthn registration response"""
    current_user = g.current_user
    json_data = request.get_json()

    attestation_data = json_data.get('credential', {})
    credential_alias = json_data.get('name', 'Security Key')
    server_host = request.host

    verification_result, message, stored_credential = WebAuthnService.process_registration(
        current_user.id, attestation_data, server_host, credential_alias
    )

    if not verification_result:
        return error_response(message, 400)

    AuditService.record_event(
        event_type='webauthn_register',
        target_type='webauthn',
        target_id=str(stored_credential.id) if stored_credential else None,
        target_label=credential_alias,
        description=f'Completed WebAuthn registration: {credential_alias}',
        outcome=True
    )

    return success_response(
        data=stored_credential.as_dict() if stored_credential else None,
        message=message
    )

from __future__ import annotations
import ast
import fnmatch
from pathlib import Path
from skylos.rules.base import SkylosRule


class YAMLRule(SkylosRule):
    def __init__(self, config):
        self._rule_id = config["rule_id"]
        self._name = config["name"]
        self.severity_level = config.get("severity", "MEDIUM")
        self.category_type = config.get("category", "custom")
        yaml_section = config.get("yaml_config", {})
        self._pattern_spec = yaml_section.get("pattern", {})
        self._violation_msg = yaml_section.get("message", "Custom rule violation")

    @property
    def rule_identifier(self):
        return self._rule_id

    @property
    def rule_name(self):
        return self._name

    def inspect_node(self, node, context):
        pattern_kind = self._pattern_spec.get("type")
        if pattern_kind == "function":
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                return self._evaluate_function_match(node, context)
        elif pattern_kind == "class":
            if isinstance(node, ast.ClassDef):
                return self._evaluate_class_match(node, context)
        elif pattern_kind == "call":
            if isinstance(node, ast.Call):
                return self._evaluate_call_match(node, context)
        return None

    def _evaluate_function_match(self, func_node, ctx):
        deco_settings = self._pattern_spec.get("decorators", {})
        required_any = deco_settings.get("has_any", [])
        optional_any = deco_settings.get("must_also_have_any", [])

        if not required_any:
            return None

        found_decorators = set()
        for deco in func_node.decorator_list:
            found_decorators.add(self._extract_decorator_label(deco))

        match_found = False
        for req_pattern in required_any:
            for label in found_decorators:
                if req_pattern in label:
                    match_found = True
                    break
            if match_found:
                break

        if not match_found:
            return None

        if optional_any:
            has_required_base = False
            for req_base in optional_any:
                for label in found_decorators:
                    if req_base in label:
                        has_required_base = True
                        break
                if has_required_base:
                    break
            if not has_required_base:
                return [self._generate_finding(func_node, ctx)]
        return None

    def _evaluate_class_match(self, cls_node, ctx):
        name_template = self._pattern_spec.get("name_pattern", "*")
        required_bases = self._pattern_spec.get("must_inherit_any", [])

        if not fnmatch.fnmatch(cls_node.name, name_template):
            return None

        if required_bases:
            inherited_names = set()
            for base_expr in cls_node.bases:
                inherited_names.add(self._resolve_base_identifier(base_expr))
            if not (set(required_bases) & inherited_names):
                return [self._generate_finding(cls_node, ctx)]
        return None

    def _evaluate_call_match(self, call_node, ctx):
        func_patterns = self._pattern_spec.get("function_match", [])
        arg_rules = self._pattern_spec.get("args", {})

        called_func = self._obtain_call_target(call_node)
        if not called_func:
            return None

        is_matched = any(pattern in called_func for pattern in func_patterns)
        if not is_matched:
            return None

        if arg_rules.get("is_dynamic"):
            pos_index = arg_rules.get("position", 0)
            if len(call_node.args) > pos_index:
                if self._detect_dynamic_string(call_node.args[pos_index]):
                    return [self._generate_finding(call_node, ctx)]
        return None

    def _extract_decorator_label(self, deco):
        if isinstance(deco, ast.Name):
            return deco.id
        elif isinstance(deco, ast.Attribute):
            parent_label = self._extract_decorator_label(deco.value)
            return f"{parent_label}.{deco.attr}" if parent_label else deco.attr
        elif isinstance(deco, ast.Call):
            return self._extract_decorator_label(deco.func)
        return ""

    def _resolve_base_identifier(self, base_expr):
        if isinstance(base_expr, ast.Name):
            return base_expr.id
        elif isinstance(base_expr, ast.Attribute):
            return base_expr.attr
        return ""

    def _obtain_call_target(self, call_node):
        target = call_node.func
        segments = []
        while isinstance(target, ast.Attribute):
            segments.append(target.attr)
            target = target.value
        if isinstance(target, ast.Name):
            segments.append(target.id)
            segments.reverse()
            return ".".join(segments)
        return None

    def _detect_dynamic_string(self, expr):
        if isinstance(expr, ast.JoinedStr):
            return True
        if isinstance(expr, ast.BinOp) and isinstance(expr.op, (ast.Add, ast.Mod)):
            return True
        if isinstance(expr, ast.Call):
            if isinstance(expr.func, ast.Attribute) and expr.func.attr == "format":
                return True
        return False

    def _generate_finding(self, node, ctx):
        identifier = None
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            identifier = getattr(node, "name", None)
        if identifier is None and isinstance(node, ast.Call):
            identifier = self._obtain_call_target(node) or "<call>"

        return {
            "rule_id": self.rule_identifier,
            "kind": "custom",
            "category": self.category_type,
            "severity": self.severity_level,
            "message": self._violation_msg,
            "name": identifier or "<custom>",
            "simple_name": identifier or "<custom>",
            "value": "-",
            "file": ctx.get("filename"),
            "basename": Path(ctx.get("filename", "")).name,
            "line": getattr(node, "lineno", 0),
            "col": getattr(node, "col_offset", 0),
        }


def load_custom_rules(rules_data):
    collected_rules = []
    for cfg in rules_data:
        if not cfg.get("enabled", True):
            continue
        if cfg.get("rule_type") != "yaml":
            continue
        try:
            collected_rules.append(YAMLRule(cfg))
        except Exception as err:
            print(f"Warning: Failed to load rule {cfg.get('rule_id')}: {err}")
    return collected_rules

import json
