        position = person.get('position', 'N/A')
        pitch_text = person.get('pitch', 'N/A')

        # Build needs list items safely
        needs_list_items = ""
        for item in person.get('needs', []):
            needs_list_items += f"<li>{item}</li>"

        page_content += f"""
        <div class="card">
            <div class="person-name">{person['name']}</div>
            <div class="job-title">{position}</div>
