                <ul>
                    {needs_list_items}
                </ul>
            </div>
            <div class="suggestion-box">
                <strong>Outreach Strategy:</strong> {pitch_text}
            </div>
        </div>
"""

    # Close the HTML document
    page_content += """
    </div>
</body>
</html>
"""
    return page_content

if __name__ == "__main__":
    if len(sys.argv) > 1:
