# Custom exception hierarchy for HTTP client operations

from pip._vendor.urllib3.exceptions import HTTPError as BaseHTTPError
from .compat import JSONDecodeError as CompatJSONDecodeError

class RequestException(IOError):
    """Base exception for ambiguous errors during request processing."""

    def __init__(self, *args, **kwargs):
        # Extract response and request from kwargs
        resp = kwargs.pop("response", None)
        self.response = resp
        self.request = kwargs.pop("request", None)

        # If response exists but request doesn't, try to get it from response
        if resp is not None and not self.request and hasattr(resp, "request"):
            self.request = resp.request

        super().__init__(*args, **kwargs)

class InvalidJSONError(RequestException):
    """Raised when a JSON parsing issue occurs."""

class JSONDecodeError(InvalidJSONError, CompatJSONDecodeError):
    """Raised when JSON decoding fails."""

    def __init__(self, *args, **kwargs):
        """
        Initialize by first creating the base JSONDecodeError,
        then passing its arguments to the parent RequestException.
        This preserves the original JSON error message.
        """
        CompatJSONDecodeError.__init__(self, *args)
        InvalidJSONError.__init__(self, *self.args, **kwargs)

class HTTPError(RequestException):
    """Raised when an HTTP protocol error happens."""

class ConnectionError(RequestException):
    """Raised when network connection fails."""

class ProxyError(ConnectionError):
    """Raised when proxy-related issues occur."""

class SSLError(ConnectionError):
    """Raised when SSL/TLS handshake or verification fails."""

class Timeout(RequestException):
    """Raised when request duration exceeds allowed time limit.

    Includes both connection and read timeout scenarios.
    """

class ConnectTimeout(ConnectionError, Timeout):
    """Raised when connection establishment exceeds timeout limit.

    These requests are generally safe to retry.
    """

class ReadTimeout(Timeout):
    """Raised when server takes too long to send response data."""

class URLRequired(RequestException):
    """Raised when a valid URL is missing for the request."""

class TooManyRedirects(RequestException):
    """Raised when redirect limit is exceeded."""

class MissingSchema(RequestException, ValueError):
    """Raised when URL lacks required scheme (e.g., 'http://' or 'https://')."""

class InvalidSchema(RequestException, ValueError):
    """Raised when URL uses unsupported or invalid scheme."""

class InvalidURL(RequestException, ValueError):
    """Raised when URL format is malformed."""

class InvalidHeader(RequestException, ValueError):
    """Raised when header value is syntactically incorrect."""

class InvalidProxyURL(InvalidURL):
    """Raised when proxy URL is invalid."""

class ChunkedEncodingError(RequestException):
    """Raised when chunked transfer encoding is malformed."""

class ContentDecodingError(RequestException, BaseHTTPError):
    """Raised when content decoding fails."""

class StreamConsumedError(RequestException, TypeError):
    """Raised when attempting to consume already consumed response body."""

class RetryError(RequestException):
    """Raised when custom retry strategy fails."""

class UnrewindableBodyError(RequestException):
    """Raised when body cannot be rewound after failure."""

# Warning classes
class RequestsWarning(Warning):
