# Jenkins monitoring module - Type III clone with refactored logic

import logging
import os
import subprocess
import sys
import threading
import time
import traceback
import urllib2
import json
import base64

logging.basicConfig(level=logging.ERROR)

_monitor_thread = None

class JenkinsMonitor(threading.Thread):
    def __init__(self, config):
        threading.Thread.__init__(self)
        self.active = False
        self.terminate = False
        self.data_store = {}
        self.config_store = {}
        self.poll_interval = 60
        self.jenkins_url = config['base_url']
        self.auth_user = config['username']
        self.api_key = config['apitoken']
        self._data_lock = threading.Lock()
        self._config_lock = threading.Lock()

    def stop(self):
        self.terminate = True
        if not self.active:
            return
        self.join()

    def run(self):
        global _monitor_thread
        self.active = True
        while not self.terminate:
            time.sleep(self.poll_interval)
            self.update_metrics()
        self.active = False

    @staticmethod
    def fetch_jenkins_data(url, user, token):
        url += '/api/json'
        url += '?tree=jobs[color],overallLoad[busyExecutors[min[latest]],queueLength[min[latest]],totalExecutors[min[latest]]]'
        if user and token:
            url += '&token=' + token
            req = urllib2.Request(url)
            auth_string = base64.encodestring('%s:%s' % (user, token)).replace('\n', '')
            req.add_header("Authorization", "Basic %s" % auth_string)
            response = urllib2.urlopen(req, None, 2)
        else:
            response = urllib2.urlopen(url, None, 2)

        raw_data = response.read()
        response.close()

        parsed = json.loads(raw_data)
        output = {}
        output['jenkins_overallload_busy_executors'] = parsed['overallLoad']['busyExecutors']['min']['latest']
        output['jenkins_overallload_queue_length'] = parsed['overallLoad']['queueLength']['min']['latest']
        output['jenkins_overallload_total_executors'] = parsed['overallLoad']['totalExecutors']['min']['latest']
        output['jenkins_jobs_total'] = len(parsed['jobs'])

        # Initialize job status counters
        status_types = ['red', 'yellow', 'grey', 'disabled', 'aborted', 'notbuilt', 'blue']
        for status in status_types:
            output['jenkins_jobs_' + status] = 0

        # Count jobs by color/status
        for job in parsed['jobs']:
            job_color = job['color']
            for status in status_types:
                if job_color == status or job_color == status + '_anime':
                    output['jenkins_jobs_' + status] += 1

        return output

    def update_metrics(self):
        logging.debug('updating metrics')
        try:
            logging.debug('connecting to: ' + str(self.jenkins_url))
            metrics = JenkinsMonitor.fetch_jenkins_data(self.jenkins_url, self.auth_user, self.api_key)
        except Exception as e:
            logging.warning('failed to update metrics')
            logging.warning(traceback.format_exc())
            return

        try:
            self._data_lock.acquire()
            self.data_store = {}
            for key, value in metrics.items():
                self.data_store[key] = value
        except Exception as e:
            logging.warning('error updating metrics')
            logging.warning(traceback.format_exc())
            return False
        finally:
            self._data_lock.release()

        if not self.data_store:
            logging.warning('metrics update failed')
            return False

        logging.debug('metrics updated successfully')
        logging.debug('current metrics: ' + str(self.data_store))
        return True

    def get_value(self, metric_name):
        logging.debug('retrieving metric: ' + metric_name)
        try:
            if metric_name in self.data_store:
                try:
                    self._data_lock.acquire()
                    logging.debug('metric: %s = %s' % (metric_name, self.data_store[metric_name]))
                    return self.data_store[metric_name]
                finally:
                    self._data_lock.release()
        except Exception as e:
            logging.warning('could not retrieve ' + metric_name)
            return 0

    def get_config(self, config_name):
        logging.debug('retrieving config: ' + config_name)
        try:
            if config_name in self.config_store:
                try:
                    self._config_lock.acquire()
                    logging.debug('config: %s = %s' % (config_name, self.config_store[config_name]))
                    return self.config_store[config_name]
                finally:
                    self._config_lock.release()
        except Exception as e:
            logging.warning('could not retrieve ' + config_name)
            return 0

def initialize_metrics(params):
    logging.debug('initializing: ' + str(params))
    global _monitor_thread

    DEFAULT_METRIC_SETTINGS = {
        'units': 'jobs',
        'groups': 'jenkins',
        'slope': 'both',
        'value_type': 'uint',
        'format': '%d',
        'description': '',
        'callback': get_metric_value
    }

    METRIC_DEFINITIONS = dict(
        jenkins_overallload_busy_executors = {
            'value_type': 'float',
            'format': '%.3f',
            'units': 'executors',
            'description': 'Number of busy executors (master and slaves)'},
        jenkins_overallload_queue_length = {
            'value_type': 'float',
            'format': '%.3f',
            'units': 'queued items',
            'description': 'Length of the queue (master and slaves)'},
        jenkins_overallload_total_executors = {
            'value_type': 'float',
            'format': '%.3f',
            'units': 'executors',
            'description': 'Number of executors (master and slaves)'},
        jenkins_jobs_total = {
            'description': 'Total number of jobs'},
        jenkins_jobs_blue = {
            'description': 'Blue jobs'},
        jenkins_jobs_red = {
            'description': 'Red jobs'},
        jenkins_jobs_yellow = {
            'description': 'Yellow jobs'},
        jenkins_jobs_grey = {
            'description': 'Grey jobs'},
        jenkins_jobs_disabled = {
            'description': 'Disabled jobs'},
        jenkins_jobs_aborted = {
            'description': 'Aborted jobs'},
        jenkins_jobs_notbuilt = {
            'description': 'Not-built jobs'})

    if _monitor_thread is not None:
        raise Exception('Monitoring thread already active')

    _monitor_thread = JenkinsMonitor(params)
    _monitor_thread.update_metrics()
    _monitor_thread.start()

    descriptors = []
    for name, definition in METRIC_DEFINITIONS.iteritems():
        descriptor = definition.copy()
        descriptor['name'] = str(name)
        [ descriptor.setdefault(key, DEFAULT_METRIC_SETTINGS[key]) for key in DEFAULT_METRIC_SETTINGS.iterkeys() ]
        descriptors.append(descriptor)

    return descriptors

def get_metric_value(name):
    global _monitor_thread
    return _monitor_thread.get_value(name)

def get_configuration_value(name):
    global _monitor_thread
    return _monitor_thread.get_config(name)

def cleanup_metrics():
    global _monitor_thread
    if _monitor_thread is not None:
        _monitor_thread.stop()
    logging.shutdown()

if __name__ == '__main__':
    from optparse import OptionParser
    try:
        logging.debug('running from command line')
        parser = OptionParser()
        parser.add_option('-u', '--URL', dest='base_url', default='http://127.0.0.1:8080', help='Base-URL for jenkins api (default: http://127.0.0.1:8080)')
        parser.add_option('-q', '--quiet', dest='quiet', action='store_true', default=False)
        parser.add_option('-d', '--debug', dest='debug', action='store_true', default=False)
        parser.add_option('-n', '--username', dest='username', default='', help='Your Jenkins username (default: empty)')
        parser.add_option('-a', '--apitoken', dest='apitoken', default='', help='Your API token (default: empty)')
        (options, args) = parser.parse_args()

        descriptors = initialize_metrics({
            'base_url': options.base_url,
            'username': options.username,
            'apitoken': options.apitoken,
        })

        if options.debug:
            from pprint import pprint
            pprint(descriptors)

        for d in descriptors:
            v = d['callback'](d['name'])
            if not options.quiet:
                print ' {0}: {1} {2} [{3}]' . format(d['name'], v, d['units'], d['description'])

        os._exit(1)
    except KeyboardInterrupt:
        time.sleep(0.2)
        os._exit(1)
    except StandardError:
        traceback.print_exc()
        os._exit(1)
    finally:
        cleanup_metrics()

