def _create_test_excel(
    rows: list[list],
    header_mods: dict | None = None,
    sheet_name: str = "E log",
) -> Path:
    """Construct a minimal E log Excel file adhering to expected layout."""
    num_cols = 138
    total_lines = DATA_START_ROW + len(rows)
    grid = [[None] * num_cols for _ in range(total_lines)]

    # Layout markers
    grid[2][8] = "MAIN ENGINE PARAMETERS"
    grid[3][10] = "RPM"
    grid[2][83] = "HFO CONSUMPTION (MT)"
    grid[2][90] = "MGO CONSUMPTION (MT)"

    if header_mods:
        for (row_idx, col_idx), val in header_mods.items():
            grid[row_idx][col_idx] = val

    for idx, row_vals in enumerate(rows):
        for jdx, val in enumerate(row_vals):
            if jdx < num_cols:
                grid[DATA_START_ROW + idx][jdx] = val

    df = pd.DataFrame(grid)
    tmp_file = tempfile.NamedTemporaryFile(suffix=".xlsx", delete=False)
    with pd.ExcelWriter(tmp_file.name, engine="openpyxl") as writer:
        df.to_excel(writer, sheet_name=sheet_name, index=False, header=False)
    return Path(tmp_file.name)

def _build_data_line(**kwargs) -> list:
    """Generate a data line using COLUMN_MAP keys."""
    line = [None] * 138
    for field, value in kwargs.items():
        if field in COLUMN_MAP:
            line[COLUMN_MAP[field]] = value
    return line

