class Configuration(object):
    def __init__(self, data):
        for key, value in data.items():
            if isinstance(value, dict):
                setattr(self, key, Configuration(value))
            else:
                setattr(self, key, value)

    def flatten(self):
        result = {}
        for attr_name, attr_value in self.__dict__.items():
            if isinstance(attr_value, self.__class__):
                result[attr_name] = attr_value.flatten()
            else:
                result[attr_name] = attr_value
        return result

def setup_model_parallelism(
    tp_size=1,
    pp_size=1,
    vpp_size=None,
    pp_split_rank=None,
    cp_size=1,
):
    ps.destroy_model_parallel()
    ps.initialize_model_parallel(
        tensor_model_parallel_size=tp_size,
        pipeline_model_parallel_size=pp_size,
        virtual_pipeline_model_parallel_size=vpp_size,
        pipeline_model_parallel_split_rank=pp_split_rank,
        context_parallel_size=cp_size,
    )

def reset_module_namespace(prefix):
    import sys
    candidates = [name for name in sys.modules if name.startswith(prefix)]
    for module_name in candidates:
        del sys.modules[module_name]

