load_dotenv()
client = OpenAI(
    base_url='http://localhost:11434/v1/',
    api_key='REDACTED_CREDENTIAL',  # Required but ignored by Ollama
)

class OllamaEngine:
    def __init__(self):
        print("OllamaEngine initialized")

    async def generate(self, job_input):
        # Retrieve model name from environment or use default
        model_name = os.getenv("OLLAMA_MODEL_NAME", "llama3.2:1b")

        # Prepare request parameters based on input type
        if isinstance(job_input.llm_input, str):
            route = "/v1/completions"
            payload = {
                "model": model_name,
                "prompt": job_input.llm_input,
                "stream": job_input.stream
            }
        else:
            route = "/v1/chat/completions"
            payload = {
                "model": model_name,
                "messages": job_input.llm_input,
                "stream": job_input.stream
            }

        # Create new job input with OpenAI-compatible format
        adapted_job = JobInput({
            "openai_route": route,
            "openai_input": payload
        })

        # Delegate to OpenAI-compatible engine
        adapter_engine = OllamaOpenAiEngine()
        async for result in adapter_engine.generate(adapted_job):
            yield result


class OllamaOpenAiEngine(OllamaEngine):
    def __init__(self):
        print("OllamaOpenAiEngine initialized")

    async def generate(self, job_input):
        route = job_input.openai_route
        input_data = job_input.openai_input

        if route == "/v1/models":
            async for item in self._process_model_list():
                yield item
        elif route in ["/v1/chat/completions", "/v1/completions"]:
            is_chat = route == "/v1/chat/completions"
            async for item in self._process_completion_request(input_data, is_chat):
                yield item
        else:
            yield {"error": "Unsupported endpoint"}

    async def _process_model_list(self):
        try:
            models_response = client.models.list()
            formatted_models = [
                {"id": m.id, "created": m.created, "object": m.object, "owned_by": m.owned_by}
                for m in models_response.data
            ]
            yield {"object": "list", "data": formatted_models}
        except Exception as err:
            yield {"error": str(err)}

    async def _process_completion_request(self, params, is_chat=False):
        try:
            # Route call appropriately
            if is_chat:
                raw_response = client.chat.completions.create(**params)
            else:
                raw_response = client.completions.create(**params)

            # Handle non-streaming case
            if not params.get("stream", False):
                yield raw_response.model_dump()
                return

            # Stream chunks
            for chunk in raw_response:
                print("Chunk received:", chunk)
                yield f"data: {json.dumps(chunk.model_dump(), separators=(',', ':'))}\n\n"
            yield "data: [DONE]"
        except Exception as exc:
            yield {"error": str(exc)}

# Type III Clone: Restructured logic for detecting ontology contract conflicts
import json
import os
import re
import sys
from collections import defaultdict

def gather_skill_contracts(base_path):
    """Traverse directory to collect all valid ontology contracts."""
    skill_contracts = {}

    if not os.path.isdir(base_path):
        return skill_contracts

    # Sort entries for deterministic processing order
    for item in sorted(os.listdir(base_path)):
        skill_dir = os.path.join(base_path, item)
        skill_file = os.path.join(skill_dir, "skill.json")

        # Skip non-files and missing files
        if not os.path.isfile(skill_file):
            continue

        try:
            with open(skill_file, 'r') as file_handle:
                raw_data = json.load(file_handle)
        except (json.JSONDecodeError, IOError):
            continue

        # Extract and store valid contracts
        contract = raw_data.get("ontologyContract")
        if contract and contract.get("ontology"):
            skill_contracts[item] = contract

    return skill_contracts

def extract_postcondition_info(condition_text):
    """Parse postcondition string into structured components."""
    segments = condition_text.split(".", 1)
    if len(segments) != 2:
        return None

    entity_type = segments[0]
    remainder = segments[1]

    # Handle equality checks
    if " == " in remainder:
        prop_part, val_part = remainder.split(" == ", 1)
        return {
            "entity": entity_type,
            "field": prop_part.strip(),
            "operator": "==",
            "target_value": val_part.strip().strip("'\""),
        }

    # Handle inequality checks
    elif " != " in remainder:
        prop_part, val_part = remainder.split(" != ", 1)
        return {
            "entity": entity_type,
            "field": prop_part.strip(),
            "operator": "!=",
            "target_value": val_part.strip().strip("'\""),
        }

    # Handle enum validity assertions
    elif " is valid enum" in remainder:
        field_name = remainder.replace(" is valid enum", "").strip()
        return {
            "entity": entity_type,
            "field": field_name,
            "operator": "valid_enum",
            "target_value": None,
        }

    # Handle existence assertions
    elif " exists" in remainder:
        field_name = remainder.replace(" exists", "").strip()
        return {
            "entity": entity_type,
            "field": field_name,
            "operator": "exists",
            "target_value": None,
        }

    return None

def find_ontology_conflicts(skill_contracts):
    """Identify conflicting postconditions across skills."""
    # Organize parsed postconditions by (entity, field) pair
    field_constraints = defaultdict(list)

    for skill_name, contract in skill_contracts.items():
        ontology = contract.get("ontology", {})
        for constraint in ontology.get("postconditions", []):
            parsed = extract_postcondition_info(constraint)
            if parsed:
                key = (parsed["entity"], parsed["field"])
                field_constraints[key].append({
                    "skill": skill_name,
                    "original": constraint,
                    "structure": parsed,
                })

    detected_issues = []

    # Examine each field's constraints for inconsistencies
    for field_key, constraint_list in field_constraints.items():
        if len(constraint_list) < 2:
            continue

        # Compare all unique pairs of constraints
        for idx_a in range(len(constraint_list)):
            for idx_b in range(idx_a + 1, len(constraint_list)):
                entry_a = constraint_list[idx_a]
                entry_b = constraint_list[idx_b]

                struct_a = entry_a["structure"]
                struct_b = entry_b["structure"]

                conflict_record = None

                # Case 1: One requires value, other forbids same value
                if (struct_a["operator"] == "==" and 
                    struct_b["operator"] == "!=" and 
                    struct_a["target_value"] == struct_b["target_value"]):

                    conflict_record = {
                        "type": "equality_vs_inequality",
                        "description": (
                            f"{entry_a['skill']} mandates {struct_a['entity']}.{struct_a['field']} == '{struct_a['target_value']}' "
                            f"while {entry_b['skill']} prohibits it (!= '{struct_b['target_value']}')"
                        ),
                    }

                elif (struct_b["operator"] == "==" and 
                      struct_a["operator"] == "!=" and 
                      struct_b["target_value"] == struct_a["target_value"]):

                    conflict_record = {
                        "type": "equality_vs_inequality",
                        "description": (
                            f"{entry_b['skill']} mandates {struct_b['entity']}.{struct_b['field']} == '{struct_b['target_value']}' "
                            f"while {entry_a['skill']} prohibits it (!= '{struct_a['target_value']}')"
                        ),
                    }

                # Case 2: Two different required values
                elif (struct_a["operator"] == "==" and 
                      struct_b["operator"] == "==" and 
                      struct_a["target_value"] != struct_b["target_value"]):

                    conflict_record = {
                        "type": "contradictory_equality",
                        "description": (
                            f"{entry_a['skill']} requires {struct_a['entity']}.{struct_a['field']} == '{struct_a['target_value']}' "
                            f"but {entry_b['skill']} requires == '{struct_b['target_value']}'"
                        ),
                    }

                if conflict_record:
                    conflict_record.update({
                        "skill_x": entry_a["skill"],
                        "skill_y": entry_b["skill"],
                        "constraint_x": entry_a["original"],
                        "constraint_y": entry_b["original"],
                        "affected_field": f"{struct_a['entity']}.{struct_a['field']}",
                    })
                    detected_issues.append(conflict_record)

    return detected_issues

def main():
    # Determine base path from environment or use default
    base_path = os.path.expanduser(
        os.environ.get("_SKILLS_DIR", "~/.openclaw/skills")
    )

    # Check if JSON output mode is enabled
    use_json_output = os.environ.get("_JSON_OUTPUT", "false") == "true"

    # Load all contracts
    contracts = gather_skill_contracts(base_path)

    if not contracts:
        result = {
            "conflicts": [],
            "skills_analyzed": 0,
            "message": "no skills with ontology contracts found"
        }

        if use_json_output:
            print(json.dumps(result, indent=2))
        else:
            print("No skills with ontology contracts found")
        sys.exit(0)

    # Detect conflicts
    issues = find_ontology_conflicts(contracts)

    # Analyze read/write compatibility between skills
    compatible_pairs = []
    skills_list = list(contracts.keys())

    for i in range(len(skills_list)):
        for j in range(i + 1, len(skills_list)):
            name_x = skills_list[i]
            name_y = skills_list[j]

            contract_x = contracts[name_x]
            contract_y = contracts[name_y]

            writes_x = set(contract_x.get("ontology", {}).get("writes", []))
            reads_x = set(contract_x.get("ontology", {}).get("reads", []))
            writes_y = set(contract_y.get("ontology", {}).get("writes", []))
            reads_y = set(contract_y.get("ontology", {}).get("reads", []))

            shared_resources = (writes_x & reads_y) | (writes_y & reads_x)

            if shared_resources:
                compatible_pairs.append({
                    "skill_1": name_x,
                    "skill_2": name_y,
                    "shared_entities": sorted(shared_resources),
                })

    # Prepare final result
    result = {
        "conflicts": issues,
        "conflict_count": len(issues),
        "skills_analyzed": len(contracts),
        "skills": sorted(contracts.keys()),
        "compatible_pairs": compatible_pairs,
    }

    if use_json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"Analyzed {len(contracts)} skill(s): {', '.join(sorted(contracts.keys()))}")
        print()

        if issues:
