            for issue in issues:
                print(f"  * [{issue['type']}] {issue['description']}")
                print(f"    {issue['skill_x']}: {issue['constraint_x']}")
                print(f"    {issue['skill_y']}: {issue['constraint_y']}")
                print()
        else:
            print("No conflicts detected")

        if compatible_pairs:
            print()
            print("Compatible read/write pairs:")
            for pair in compatible_pairs:
                print(f"  {pair['skill_1']} <-> {pair['skill_2']}: {', '.join(pair['shared_entities'])}")

    sys.exit(1 if issues else 0)

