def initialize_hook_system():
    hook_registry = {}
    for event_name in HOOKS:
        hook_registry[event_name] = []
    return hook_registry

# Execute hooks for a specific event type
def trigger_hooks(event_key, registered_hooks, data_payload, **additional_params):
    """Triggers all registered hooks for a specified event."""
    registered_hooks = registered_hooks if registered_hooks else {}
    target_hooks = registered_hooks.get(event_key)

    if target_hooks:
        # Ensure hooks is always a list for consistent processing
        if callable(target_hooks):
            target_hooks = [target_hooks]

        current_data = data_payload
        for hook_function in target_hooks:
            processed_data = hook_function(current_data, **additional_params)
            if processed_data is not None:
                current_data = processed_data
        return current_data

    return data_payload

