        return loop.run_until_complete(coro)

    def test_callback_executed_with_params(self):
        captured = {}
        def handler(name, cid, txt):
            captured.update({"name": name, "cid": cid, "txt": txt})
            return "done"
        ch = DummyChannel({}, on_message=handler)
        result = self._execute_async(ch.handle_message("chat_99", "go ahead"))
        assert result == "done"
        assert captured["name"] == "dummy"
        assert captured["cid"] == "chat_99"
        assert captured["txt"] == "go ahead"

