            raise RuntimeError("internal failure")
        ch = DummyChannel({}, on_message=faulty_handler)
        result = self._execute_async(ch.handle_message("u1", "cmd"))
        assert "Error" in result
        assert "internal failure" in result

    def test_dry_run_blocks_execution(self):
        executed = []
        def handler(name, cid, txt):
            executed.append(txt)
            return "executed"
        ch = DummyChannel({}, on_message=handler)
        preview = self._execute_async(ch.handle_message("u1", "--dry-run move forward"))
        assert "Dry-run plan" in preview
        assert executed == []
        final = self._execute_async(ch.handle_message("u1", "confirm"))
        assert final == "executed"
        assert executed == ["move forward"]

    def test_policy_block_shows_alternatives(self):
        ch = DummyChannel({}, on_message=lambda *_: "ok")
        response = self._execute_async(ch.handle_message("u1", "access restricted zone"))
        assert "I cannot execute" in response
        assert "Safe alternatives" in response
        assert "EXP-" in response


