# Alternative implementation of Timeout class with modified logic

from __future__ import absolute_import
import time
from socket import _GLOBAL_DEFAULT_TIMEOUT, getdefaulttimeout
from ..exceptions import TimeoutStateError

_Default = object()

# Use monotonic clock if available for better timing precision
try:
    current_time = time.monotonic
except AttributeError:
    current_time = time.time

class Timeout(object):
    """Timeout configuration - restructured version with equivalent functionality"""

    DEFAULT_TIMEOUT = _GLOBAL_DEFAULT_TIMEOUT

    def __init__(self, total=None, connect=_Default, read=_Default):
        # Store timeout values after validation
        self._connect_timeout = self._check_timeout_value(connect, "connect")
        self._read_timeout = self._check_timeout_value(read, "read")
        self._total_timeout = self._validate_total_timeout(total)
        self._connection_start_time = None

    def _check_timeout_value(self, value, param_name):
        """Validate and process individual timeout parameters"""
        if value is _Default:
            return self.DEFAULT_TIMEOUT
        if value is None or value is self.DEFAULT_TIMEOUT:
            return value

        # Ensure numeric type
        if isinstance(value, bool):
            raise ValueError(
                f"Timeout cannot be a boolean value. {param_name} must be int, float or None."
            )

        try:
            num_value = float(value)
        except (TypeError, ValueError):
            raise ValueError(
                f"Timeout value '{param_name}' was '{value}', but it must be an int, float or None."
            )

        # Check for non-positive values
        if num_value <= 0:
            raise ValueError(
                f"Attempted to set {param_name} timeout to {value}, but the "
                "timeout cannot be set to a value less than or equal to 0."
            )

        return num_value

    def _validate_total_timeout(self, value):
        """Validate total timeout parameter specifically"""
        if value is _Default:
            return self.DEFAULT_TIMEOUT
        if value is None or value is self.DEFAULT_TIMEOUT:
            return value

        # Ensure numeric type
        if isinstance(value, bool):
            raise ValueError(
                "Total timeout cannot be a boolean value. It must be int, float or None."
            )

        try:
            num_value = float(value)
        except (TypeError, ValueError):
            raise ValueError(
                f"Total timeout value was '{value}', but it must be an int, float or None."
            )

        # Check for non-positive values
        if num_value <= 0:
            raise ValueError(
                f"Attempted to set total timeout to {value}, but the "
                "timeout cannot be set to a value less than or equal to 0."
            )

        return num_value

    def __repr__(self):
        return "%s(connect=%r, read=%r, total=%r)" % (
            type(self).__name__,
            self._connect_timeout,
            self._read_timeout,
            self._total_timeout,
        )

    __str__ = __repr__

    @classmethod
    def resolve_default_timeout(cls, timeout):
        """Resolve default timeout to actual system timeout if needed"""
        return getdefaulttimeout() if timeout is cls.DEFAULT_TIMEOUT else timeout

    @classmethod
    def from_float(cls, timeout):
        """Create new Timeout instance using legacy single timeout value"""
        return Timeout(read=timeout, connect=timeout)

    def clone(self):
        """Create a copy of the timeout configuration"""
        return Timeout(
            connect=self._connect_timeout, 
            read=self._read_timeout, 
            total=self._total_timeout
        )

    def start_connect(self):
        """Start connection timer"""
        if self._connection_start_time is not None:
            raise TimeoutStateError("Connection timeout timer has already been started.")
        self._connection_start_time = current_time()
        return self._connection_start_time

    def get_connect_duration(self):
        """Calculate elapsed time since connection started"""
        if self._connection_start_time is None:
            raise TimeoutStateError(
                "Cannot calculate connection duration for timer that hasn't started."
            )
        return current_time() - self._connection_start_time

    @property
    def connect_timeout(self):
        """Determine effective connection timeout value"""
        # If no total timeout specified, use connect timeout directly
        if self._total_timeout is None:
            return self._connect_timeout

        # If connect timeout is default or infinite, use total timeout
        if self._connect_timeout is None or self._connect_timeout is self.DEFAULT_TIMEOUT:
            return self._total_timeout

        # Otherwise use minimum of connect and total timeouts
        return min(self._connect_timeout, self._total_timeout)

    @property
    def read_timeout(self):
        """Calculate effective read timeout considering connection time"""
        # Only adjust read timeout when total timeout is explicitly set
        if (
            self._total_timeout is not None 
            and self._total_timeout is not self.DEFAULT_TIMEOUT
            and self._read_timeout is not None
            and self._read_timeout is not self.DEFAULT_TIMEOUT
        ):
            # If connection hasn't started yet, return original read timeout
            if self._connection_start_time is None:
                return self._read_timeout

            # Calculate remaining time after connection
            elapsed = self.get_connect_duration()
            remaining = self._total_timeout - elapsed
            return max(0, min(remaining, self._read_timeout))

        # Handle case where only total timeout is specified
        elif self._total_timeout is not None and self._total_timeout is not self.DEFAULT_TIMEOUT:
            elapsed = self.get_connect_duration() if self._connection_start_time is not None else 0
            return max(0, self._total_timeout - elapsed)

        # Otherwise use original read timeout
        else:
            return self._read_timeout

