import json
import sys
import urllib.request
import urllib.error

BASE_URL = "https://compute.x402layer.cc"

def list_regions() -> dict:
    """Retrieve and display available deployment regions."""
    try:
        with urllib.request.urlopen(f"{BASE_URL}/compute/regions", timeout=30) as response:
            if response.status != 200:
                return {"error": f"HTTP {response.status}", "response": response.read().decode()[:500]}
            data = json.loads(response.read().decode())
            regions = data.get("regions", [])
            print(f"Discovered {len(regions)} region(s)")
            for region in regions:
                print(f"  {region['id']:6s}  {region['city']}, {region['country']} ({region['continent']})")
            return data
    except urllib.error.HTTPError as e:
        return {"error": f"HTTP {e.code}", "response": str(e.reason)[:500]}
    except Exception as e:
        return {"error": "Connection failed", "response": str(e)[:500]}

if __name__ == "__main__":
    outcome = list_regions()
    if "error" in outcome:
        print(json.dumps(outcome, indent=2))
        sys.exit(1)

import logging
import types
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.distributed.tensor import DTensor

logger = logging.getLogger(__name__)

def create_chunkloss_forward_handler():
    def custom_forward(self, input_features: torch.Tensor, loss_computation: callable):
        # Convert distributed weights/biases to local representation when needed
        if isinstance(self.weight, DTensor):
            weight_local = self.weight.to_local()
            if self.bias is not None:
                if not isinstance(self.bias, DTensor):
                    raise TypeError(
                        f"Expected bias to be a DTensor when weight is a DTensor, "
                        f"but got bias of type {type(self.bias)}."
                    )
                bias_local = self.bias.to_local()
            else:
                bias_local = None
        else:
            weight_local = self.weight
            bias_local = self.bias

        # Compute the loss using the provided function
        computed_loss = loss_computation(input_features, weight_local, bias_local)
        return computed_loss

    return custom_forward

def inject_chunkloss_behavior(target_module):
    forward_handler = create_chunkloss_forward_handler()
    target_module.forward = types.MethodType(forward_handler, target_module)

def retrieve_chunkloss_target(modules_collection, configuration_plan):
    target_module = getattr(modules_collection, configuration_plan.apply_module, None)

    if target_module is None:
        raise ValueError(f"{configuration_plan.apply_module} does not exist; please specify a valid module name for chunk loss.")

    if not isinstance(target_module, torch.nn.Linear):
        raise ValueError(
            f"Invalid module type for chunk loss: '{target_module}' "
            f"expected torch.nn.Linear, but received {repr(type(target_module))}."
        )

    return target_module

import calendar
