class RequestAdapter:
    """Adapts a request object to work with cookie handling systems.
    Provides an interface compatible with cookie management requirements,
    allowing domain and path validation for cookie policies.
    """
    def __init__(self, original_request):
        self._req = original_request
        self._headers_dict = {}
        self._protocol = urlparse(self._req.url).scheme

    def protocol(self):
        return self._protocol

    def host(self):
        return urlparse(self._req.url).netloc

    def primary_host(self):
        return self.host()

    def full_url(self):
        # Return original URL unless Host header was explicitly set
        if "Host" not in self._req.headers:
            return self._req.url

        # Reconstruct URL with explicit Host header
        host_header = to_native_string(self._req.headers["Host"], encoding="utf-8")
        parsed_url = urlparse(self._req.url)
        return urlunparse([
            parsed_url.scheme,
            host_header,
            parsed_url.path,
            parsed_url.params,
            parsed_url.query,
            parsed_url.fragment,
        ])

    def cannot_be_verified(self):
        return True

    def has_header_field(self, field_name):
        return field_name in self._req.headers or field_name in self._headers_dict

    def get_header_field(self, field_name, fallback=None):
        return self._req.headers.get(field_name, self._headers_dict.get(fallback))

    def append_header(self, key, value):
        raise NotImplementedError(
            "Use add_header_direct() for cookie headers"
        )

    def add_header_direct(self, name, value):
        self._headers_dict[name] = value

    def current_headers(self):
        return self._headers_dict

    @property
    def unverifiable(self):
        return self.cannot_be_verified()

    @property
    def requested_host(self):
        return self.primary_host()

    @property
    def hostname(self):
        return self.host()

class ResponseAdapter:
    """Adapts HTTP response headers for cookie processing."""
    def __init__(self, header_obj):
        self._header_obj = header_obj

    def metadata(self):
        return self._header_obj

    def fetch_headers(self, header_name):
        return self._header_obj.getheaders(header_name)

def transfer_cookies_to_jar(jar, req_obj, resp_obj):
    """Extract cookies from response into the provided cookie jar.
    :param jar: cookielib.CookieJar instance
    :param req_obj: requests.Request object
    :param resp_obj: urllib3.HTTPResponse object
    """
    if not (hasattr(resp_obj, "_original_response") and resp_obj._original_response):
        return

    adapted_req = RequestAdapter(req_obj)
    adapted_res = ResponseAdapter(resp_obj._original_response.msg)
    jar.extract_cookies(adapted_res, adapted_req)

def build_cookie_header(jar, request):
    """Generate appropriate Cookie header string for request.
    :rtype: str or None
    """
    adapter = RequestAdapter(request)
    jar.add_cookie_header(adapter)
    return adapter.current_headers().get("Cookie")

def delete_cookie_by_name(cookie_container, cookie_name, domain=None, path=None):
    """Remove cookies by name, optionally filtered by domain and path.
    Wraps CookieJar.clear(), complexity O(n).
    """
    targets = []
    for cookie in cookie_container:
        if cookie.name != cookie_name:
            continue
        if domain is not None and domain != cookie.domain:
            continue
        if path is not None and path != cookie.path:
            continue
        targets.append((cookie.domain, cookie.path, cookie.name))

    for dom, pth, name in targets:
        cookie_container.clear(dom, pth, name)

class DuplicateCookieError(RuntimeError):
    """Multiple cookies match the specified criteria.
    Use get/set with domain and path parameters for precise matching.
    """

class CustomCookieJar(cookielib.CookieJar, MutableMapping):
    """Implements dict-like interface on top of cookielib.CookieJar.
    Designed for compatibility with external libraries expecting dict operations.
    All instances are pickle-serializable.
    .. warning:: Some operations may have O(n) complexity instead of O(1).
    """
    def retrieve(self, name, default=None, domain=None, path=None):
        """Dict-style retrieval supporting optional domain/path filtering.
        .. warning:: operation is O(n), not O(1).
        """
        try:
            return self._locate_unicast(name, domain, path)
        except KeyError:
            return default

    def assign(self, name, value, **options):
        """Dict-style assignment supporting optional domain/path filtering.
        Supports unsetting cookies by assigning None.
        """
        if value is None:
            delete_cookie_by_name(
                self, name, domain=options.get("domain"), path=options.get("path")
            )
            return

        if isinstance(value, Morsel):
            cookie_obj = convert_morsel_to_cookie(value)
        else:
            cookie_obj = make_cookie(name, value, **options)
        self.set_cookie(cookie_obj)
        return cookie_obj

    def names_iterator(self):
        """Iterator over cookie names in the jar."""
        for cookie in iter(self):
            yield cookie.name

    def names_list(self):
        """List of cookie names in the jar."""
        return list(self.names_iterator())

    def values_iterator(self):
        """Iterator over cookie values in the jar."""
        for cookie in iter(self):
            yield cookie.value

    def values_list(self):
        """List of cookie values in the jar."""
        return list(self.values_iterator())

    def items_iterator(self):
        """Iterator over (name, value) pairs in the jar."""
        for cookie in iter(self):
            yield cookie.name, cookie.value

    def items_list(self):
        """List of (name, value) pairs in the jar."""
        return list(self.items_iterator())

    def enumerate_domains(self):
        """Return list of unique domains in the jar."""
        unique_domains = []
        for cookie in iter(self):
            if cookie.domain not in unique_domains:
                unique_domains.append(cookie.domain)
        return unique_domains

    def enumerate_paths(self):
        """Return list of unique paths in the jar."""
        unique_paths = []
        for cookie in iter(self):
            if cookie.path not in unique_paths:
                unique_paths.append(cookie.path)
        return unique_paths

    def multiple_origin_check(self):
        """Check if jar contains multiple domains.
        :rtype: bool
        """
        seen_domains = []
        for cookie in iter(self):
            if cookie.domain is not None and cookie.domain in seen_domains:
                return True
            seen_domains.append(cookie.domain)
        return False

    def to_dict(self, domain=None, path=None):
        """Convert matching cookies to plain dictionary.
        :rtype: dict
        """
        result = {}
        for cookie in iter(self):
            if (domain is None or cookie.domain == domain) and (
                path is None or cookie.path == path
            ):
                result[cookie.name] = cookie.value
        return result

    def __contains__(self, name):
        try:
            return super().__contains__(name)
        except DuplicateCookieError:
            return True

    def __getitem__(self, name):
        """Dictionary-style access - throws exception on conflicts."""
        return self._locate_unicast(name)

    def __setitem__(self, name, value):
        """Dictionary-style assignment - throws exception on conflicts."""
        self.assign(name, value)

    def __delitem__(self, name):
        """Delete cookie by name."""
        delete_cookie_by_name(self, name)

    def store_cookie(self, cookie, *args, **kwargs):
        if (
            hasattr(cookie.value, "startswith")
            and cookie.value.startswith('"')
            and cookie.value.endswith('"')
        ):
            cookie.value = cookie.value.replace('\\"', "")
        return super().store_cookie(cookie, *args, **kwargs)

    def merge(self, other):
        """Merge cookies from another source."""
        if isinstance(other, cookielib.CookieJar):
            for cookie in other:
                self.store_cookie(copy.copy(cookie))
        else:
            super().merge(other)

    def _locate(self, name, domain=None, path=None):
        """Internal method to find cookie value without conflict checking.
        :return: cookie.value
        """
        for cookie in iter(self):
            if cookie.name == name:
                if domain is None or cookie.domain == domain:
                    if path is None or cookie.path == path:
                        return cookie.value
        raise KeyError(f"name={name!r}, domain={domain!r}, path={path!r}")

    def _locate_unicast(self, name, domain=None, path=None):
        """Find cookie value ensuring no conflicts exist.
        :raises KeyError: if cookie not found
        :raises DuplicateCookieError: if multiple matching cookies
        :return: cookie.value
        """
        found_value = None
        for cookie in iter(self):
            if cookie.name == name:
                if domain is None or cookie.domain == domain:
                    if path is None or cookie.path == path:
                        if found_value is not None:
                            raise DuplicateCookieError(
                                f"Multiple cookies found with name {name!r}"
                            )
                        found_value = cookie.value
        if found_value is not None:
            return found_value
        raise KeyError(f"name={name!r}, domain={domain!r}, path={path!r}")

    def __getstate__(self):
        """Prepare for pickling by removing unpickleable lock."""
        state = self.__dict__.copy()
        state.pop("_cookies_lock", None)
        return state

    def __setstate__(self, state):
        """Restore state during unpickling."""
        self.__dict__.update(state)
        if "_cookies_lock" not in self.__dict__:
            self._cookies_lock = threading.RLock()

    def duplicate(self):
        """Create a copy of this cookie jar."""
        new_jar = CustomCookieJar()
        new_jar.set_policy(self.get_policy())
        new_jar.merge(self)
        return new_jar

    def get_policy(self):
        """Return the CookiePolicy instance used."""
        return self._policy

def duplicate_cookiejar(jar):
    """Create a copy of a cookie jar.
    :param jar: CookieJar instance or None
    :rtype: CookieJar or None
    """
    if jar is None:
        return None
    if hasattr(jar, "duplicate"):
        return jar.duplicate()

    new_jar = copy.copy(jar)
    new_jar.clear()
    for cookie in jar:
        new_jar.store_cookie(copy.copy(cookie))
    return new_jar

def make_cookie(name, value, **kwargs):
    """Create a cookie from basic parameters.
    By default creates a cookie valid for all domains and paths.
    """
    defaults = {
        "version": 0,
        "name": name,
        "value": value,
        "port": None,
        "domain": "",
        "path": "/",
        "secure": False,
        "expires": None,
        "discard": True,
        "comment": None,
        "comment_url": None,
        "rest": {"HttpOnly": None},
        "rfc2109": False,
    }

    invalid_keys = set(kwargs) - set(defaults)
    if invalid_keys:
        raise TypeError(
            f"make_cookie() received unexpected arguments: {list(invalid_keys)}"
        )

    defaults.update(kwargs)
    defaults["port_specified"] = bool(defaults["port"])
    defaults["domain_specified"] = bool(defaults["domain"])
    defaults["domain_initial_dot"] = defaults["domain"].startswith(".")
    defaults["path_specified"] = bool(defaults["path"])

    return cookielib.Cookie(**defaults)

def convert_morsel_to_cookie(morsel):
    """Transform Morsel object into Cookie."""
    expires = None
    if morsel["max-age"]:
        try:
            expires = int(time.time() + int(morsel["max-age"]))
        except ValueError:
            raise TypeError(f"max-age: {morsel['max-age']} must be integer")
    elif morsel["expires"]:
        time_format = "%a, %d-%b-%Y %H:%M:%S GMT"
        expires = calendar.timegm(time.strptime(morsel["expires"], time_format))

    return make_cookie(
        comment=morsel["comment"],
        comment_url=bool(morsel["comment"]),
        discard=False,
        domain=morsel["domain"],
        expires=expires,
        name=morsel.key,
        path=morsel["path"],
        port=None,
        rest={"HttpOnly": morsel["httponly"]},
        rfc2109=False,
        secure=bool(morsel["secure"]),
        value=morsel.value,
        version=morsel["version"] or 0,
    )

def build_cookiejar_from_dict(cookie_dict, jar=None, replace=True):
    """Create CookieJar from dictionary of cookies.
    :param cookie_dict: Dictionary of key/value pairs
    :param jar: Optional existing CookieJar to populate
    :param replace: Whether to overwrite existing cookies
    :rtype: CookieJar
    """
    if jar is None:
        jar = CustomCookieJar()

    if cookie_dict is not None:
        existing_names = [cookie.name for cookie in jar]
        for name in cookie_dict:
            if replace or (name not in existing_names):
                jar.store_cookie(make_cookie(name, cookie_dict[name]))

    return jar

def combine_cookies(jar, cookies):
    """Add cookies to jar and return combined result.
    :param jar: CookieJar to add to
    :param cookies: Dictionary or CookieJar to add
    :rtype: CookieJar
    """
    if not isinstance(jar, cookielib.CookieJar):
        raise ValueError("Can only merge into CookieJar instances")

    if isinstance(cookies, dict):
        jar = build_cookiejar_from_dict(cookies, jar=jar, replace=False)
    elif isinstance(cookies, cookielib.CookieJar):
        try:
            jar.merge(cookies)
        except AttributeError:
            for cookie_in_source in cookies:
                jar.store_cookie(cookie_in_source)

    return jar

