import gc
import weakref
from typing import Any, Dict, List, Tuple, Optional
from statgpt.common.config import multiline_logger as logger


class ObjectLifecycleMonitor:
    """Monitors object lifecycles using weak references and logs GC events."""

    def __init__(self):
        self._monitor_registry: Dict[str, weakref.ReferenceType] = {}

    def _create_callback(self, obj_name: str, obj_type_name: str):
        """Factory for weak reference callbacks."""
        def _on_deletion(ref: weakref.ReferenceType):
            logger.info(f"GC: Object '{obj_name}' (type={obj_type_name}) has been garbage collected")
        return _on_deletion

    def register_object(self, target: Any, label: str) -> None:
        """Register an object for lifecycle monitoring."""
        obj_type_name = type(target).__name__
        callback = self._create_callback(label, obj_type_name)
        proxy = weakref.ref(target, callback)
        self._monitor_registry[label] = proxy
        logger.info(f"GC: Now tracking object '{label}' (type={obj_type_name}, id={id(target)})")

    def inspect_registered_objects(self) -> Tuple[List[Tuple[str, str, int]], List[str]]:
        """Inspect which registered objects are still alive or have been collected."""
        live_entries: List[Tuple[str, str, int]] = []
        deceased_names: List[str] = []

        for name, proxy in self._monitor_registry.items():
            instance = proxy()
            if instance is not None:
                live_entries.append((name, type(instance).__name__, id(instance)))
            else:
                deceased_names.append(name)

        if live_entries:
            logger.info("GC: Still active objects:")
            for name, typ, obj_id in live_entries:
                logger.info(f"  - {name} (type={typ}, id={obj_id})")

        if deceased_names:
            logger.info(f"GC: Collected objects: {deceased_names}")

        return live_entries, deceased_names

    def trace_references(self, label: str, max_refs: int = 5) -> str:
        """Trace who holds references to a monitored object."""
        proxy = self._monitor_registry.get(label)
        if proxy is None:
            return f"Object '{label}' is not tracked"

        referent = proxy()
        if referent is None:
            return f"Object '{label}' has already been garbage collected"

        referrers = gc.get_referrers(referent)
        logger.info(f"GC: Object '{label}' has {len(referrers)} referrers:")

        count = 0
        for item in referrers:
            if count >= max_refs:
                break
            item_type = type(item).__name__
            if item_type == 'frame':
                continue  # Omit internal frame objects

            logger.info(f"  [{count}] Type: {item_type}")
            if hasattr(item, '__name__'):
                logger.info(f"      Name: {getattr(item, '__name__', None)}")
            if hasattr(item, '__class__'):
                logger.info(f"      Class: {item.__class__.__name__}")
            if isinstance(item, dict):
                sample_keys = list(item.keys())[:3]
                logger.info(f"      Dict keys: {sample_keys}")
            count += 1

        return f"Found {len(referrers)} referrers for '{label}'"


# Global monitor instance
lifecycle_monitor = ObjectLifecycleMonitor()


def report_gc_metrics() -> None:
    """Report detailed garbage collection statistics."""
    generation_stats = gc.get_stats()
    for idx, gen_stat in enumerate(generation_stats):
        logger.info(
            f"GC Generation {idx}: collections={gen_stat['collections']}, "
            f"collected={gen_stat['collected']}, uncollectable={gen_stat['uncollectable']}"
        )

    logger.info("GC: Initiating forced collection...")
    freed_count = gc.collect()
    logger.info(f"GC: Freed {freed_count} objects")

    # Check for unreachable but uncollectable objects
    if gc.garbage:
        logger.warning(f"GC: Detected {len(gc.garbage)} uncollectable objects!")
        for idx, obj in enumerate(gc.garbage[:5]):
            logger.warning(f"  - Type: {type(obj).__name__}, ID: {id(obj)}")

