import os
import yaml
import re
import glob
from pathlib import Path
from collections import defaultdict

class DBTResourceExtractor:
    def __init__(self, project_dir):
        self.project_dir = Path(project_dir)
        self.resource_collections = {
            'metrics': [],
            'models': [],
            'sources': [],
            'seeds': [],
            'macros': [],
            'tests': [],
            'exposures': []
        }
        # Column info storage with alternative structure
        self.column_data = defaultdict(list)
        self.documentations = defaultdict(str)

    def gather_all_resources(self):
        """Gather all resources from the dbt project without running dbt"""
        self._process_yaml_documents()
        self._analyze_sql_models()
        self._locate_macros()
        self._discover_seeds()

        # Normalize paths relative to project root
        for resource_category in self.resource_collections:
            for item in self.resource_collections[resource_category]:
                if 'path' in item and isinstance(item['path'], str):
                    try:
                        full_path = Path(item['path']).resolve()
                        rel_path = full_path.relative_to(self.project_dir.resolve())
                        item['path'] = str(rel_path)
                    except ValueError:
                        # Keep original path if outside project directory
                        pass 
        return self.resource_collections, self.column_data, self.documentations

    def _process_yaml_documents(self):
        """Process all YAML files to extract metrics, sources, and other YAML-defined resources"""
        yaml_files = list(self.project_dir.glob('**/*.yml')) + list(self.project_dir.glob('**/*.yaml'))

        for y_file in yaml_files:
            try:
                with open(y_file, 'r') as stream:
                    parsed_yaml = yaml.safe_load(stream)

                if not parsed_yaml:
                    continue

                # Handle non-dict YAML contents
                if isinstance(parsed_yaml, str):
                    print(f"Warning: YAML file {y_file} contains a string instead of a dictionary")
                    continue

                # Skip dbt_project.yml processing (special handling)
                if y_file.name == 'dbt_project.yml':
                    print(f"Processing dbt_project.yml with special handling")
                    continue

                # Extract metrics
                if 'metrics' in parsed_yaml:
                    for metric_item in parsed_yaml['metrics']:
                        if not isinstance(metric_item, dict):
                            print(f"Warning: Metric in {y_file} is not a dictionary: {metric_item}")
                            continue

                        metric_name = metric_item.get('name', '')

                        # Build comprehensive metric object
                        metric_obj = {
                            'name': metric_name,
                            'path': str(y_file),
                            'type': 'metric',
                            'description': metric_item.get('description', ''),
                            'label': metric_item.get('label', ''),
                            'calculation_method': metric_item.get('calculation_method', ''),
                            'expression': metric_item.get('expression', ''),
                            'timestamp': metric_item.get('timestamp', ''),
                            'time_grains': metric_item.get('time_grains', []),
                            'dimensions': metric_item.get('dimensions', []),
                            'filters': metric_item.get('filters', []),
                            'meta': metric_item.get('meta', {}),
                            'model': metric_item.get('model', ''),
                            'model_ref': metric_item.get('model_ref', ''),
                            'sql': metric_item.get('sql', ''),
                            'window': metric_item.get('window', {}),
                            'tags': metric_item.get('tags', []),
                            'refs': metric_item.get('refs', []),
                            'depends_on': metric_item.get('depends_on', []),
                            'columns': []
                        }

                        # Process metric-specific columns
                        if 'columns' in metric_item:
                            for col in metric_item.get('columns', []):
                                column_info = {
                                    'name': col.get('name', ''),
                                    'description': col.get('description', ''),
                                    'data_type': col.get('data_type', ''),
                                    'tests': col.get('tests', []),
                                    'meta': col.get('meta', {})
                                }
                                metric_obj['columns'].append(column_info)
                                self.column_data[f"metric.{metric_name}"].append(column_info)

                        self.resource_collections['metrics'].append(metric_obj)

                        # Store documentation
                        if 'description' in metric_item and metric_item['description']:
                            self.documentations[f"metric.{metric_name}"] = metric_item['description']

                # Extract sources
                if 'sources' in parsed_yaml:
                    if not isinstance(parsed_yaml['sources'], list):
                        print(f"Warning: Sources in {y_file} is not a list")
                        continue
                    for src in parsed_yaml['sources']:
                        source_name = src.get('name', '')
                        source_description = src.get('description', '')

                        for table in src.get('tables', []):
                            table_name = table.get('name', '')
                            full_source_id = f"{source_name}.{table_name}"

                            self.resource_collections['sources'].append({
                                'name': full_source_id,
                                'path': str(y_file),
                                'type': 'source',
                                'description': table.get('description', ''),
                                'database': src.get('database', ''),
                                'schema': src.get('schema', ''),
                                'loader': src.get('loader', ''),
                                'freshness': table.get('freshness', {}),
                                'meta': table.get('meta', {})
                            })

                            # Extract columns for this source
                            for col in table.get('columns', []):
                                self.column_data[f"source.{full_source_id}"].append({
                                    'name': col.get('name', ''),
                                    'description': col.get('description', ''),
                                    'data_type': col.get('data_type', ''),
                                    'tests': col.get('tests', []),
                                    'meta': col.get('meta', {})
                                })

                            # Store documentation
                            if 'description' in table and table['description']:
                                self.documentations[f"source.{full_source_id}"] = table['description']

                # Extract exposures
                if 'exposures' in parsed_yaml:
                    for exp in parsed_yaml['exposures']:
                        exposure_name = exp.get('name', '')
                        self.resource_collections['exposures'].append({
                            'name': exposure_name,
                            'path': str(y_file),
                            'type': 'exposure',
                            'description': exp.get('description', ''),
                            'maturity': exp.get('maturity', ''),
                            'url': exp.get('url', ''),
                            'depends_on': exp.get('depends_on', []),
                            'owner': exp.get('owner', {})
                        })

                # Extract model configurations from schema files
                if 'models' in parsed_yaml:
                    for model in parsed_yaml['models']:
                        model_name = model.get('name', '')
                        self.resource_collections['models'].append({
                            'name': model_name,
                            'path': str(y_file),
                            'type': 'model_config',
                            'description': model.get('description', ''),
                            'config': model.get('config', {}),
                            'meta': model.get('meta', {})
                        })

                        # Extract columns for this model
                        for col in model.get('columns', []):
                            self.column_data[f"model.{model_name}"].append({
                                'name': col.get('name', ''),
                                'description': col.get('description', ''),
                                'data_type': col.get('data_type', ''),
                                'tests': col.get('tests', []),
                                'meta': col.get('meta', {})
                            })

                        # Store documentation
                        if 'description' in model and model['description']:
                            self.documentations[f"model.{model_name}"] = model['description']

                # Extract docs
                if 'docs' in parsed_yaml:
                    for doc_entry in parsed_yaml.get('docs', {}).get('docs', []):
                        doc_name = doc_entry.get('name', '')
                        doc_content = doc_entry.get('content', '')
                        if doc_name and doc_content:
                            self.documentations[f"doc.{doc_name}"] = doc_content

            except Exception as err:
                print(f"Error parsing {y_file}: {err}")

    def _analyze_sql_models(self):
        """Analyze SQL files to identify models"""
        sql_files = list(self.project_dir.glob('models/**/*.sql'))

        for sql_file in sql_files:
            model_name = sql_file.stem
            sql_text = self._read_sql_content(sql_file)

            # Check for existing model entry
            matched_model = next(
                (m for m in self.resource_collections['models'] if m['name'] == model_name),
                None
            )

            if matched_model:
                # Update with SQL content
                matched_model['sql_content'] = sql_text
            else:
                # Add new model from SQL file
                description = self._extract_commented_description(sql_file)
                self.resource_collections['models'].append({
                    'name': model_name,
                    'path': str(sql_file),
                    'type': 'model_sql',
                    'description': description,
                    'sql_content': sql_text
                })

                # Store documentation
                if description:
                    self.documentations[f"model.{model_name}"] = description

            # Check for singular tests in SQL files
            if 'tests' in str(sql_file) and not any(t['name'] == model_name for t in self.resource_collections['tests']):
                description = self._extract_commented_description(sql_file)
                self.resource_collections['tests'].append({
                    'name': model_name,
                    'path': str(sql_file),
                    'type': 'singular_test',
                    'description': description,
                    'sql_content': self._read_sql_content(sql_file)
                })
        return self.resource_collections

    def _read_sql_content(self, sql_file):
        """Read the SQL content from a file"""
        try:
            with open(sql_file, 'r') as f:
                return f.read()
        except:
            return ''

    def _extract_commented_description(self, sql_file):
        """Extract description from SQL file comments if available"""
        try:
            with open(sql_file, 'r') as f:
                content = f.read()

            # Look for description in SQL comments
            comment_match = re.search(r'/\*\*(.*?)\*/', content, re.DOTALL)
            if comment_match:
                return comment_match.group(1).strip()
            return ''
        except:
            return ''

    def _locate_macros(self):
        """Locate all macros in the project"""
        macro_files = list(self.project_dir.glob('macros/**/*.sql'))

        for macro_file in macro_files:
            try:
                with open(macro_file, 'r') as f:
                    content = f.read()

                # Extract macro names using regex
                macro_names = re.findall(r'{%-?\s*macro\s+([a-zA-Z0-9_]+)', content)

                for macro_name in macro_names:
                    self.resource_collections['macros'].append({
                        'name': macro_name,
                        'path': str(macro_file),
                        'type': 'macro',
                        'sql_content': content,
                    })
            except Exception as error:
                print(f"Error parsing macro {macro_file}: {error}")

    def _discover_seeds(self):
        """Discover all seed files"""
        seed_files = list(self.project_dir.glob('seeds/**/*.csv'))

        for seed_file in seed_files:
            self.resource_collections['seeds'].append({
                'name': seed_file.stem,
                'path': str(seed_file),
                'type': 'seed'
            })

    def get_summary(self):
        """Get a summary of all resources found"""
        summary = {}
        for category, items in self.resource_collections.items():
            summary[category] = len(items)
        return summary

    def export_to_csv(self, output_file):
        """Export all resources to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource Type', 'Name', 'Path', 'Description', 'Additional Info'])

            for resource_type, items in self.resource_collections.items():
                for item in items:
                    # Prepare additional info as a string
                    extra_info = {}
                    for key, value in item.items():
                        if key not in ['name', 'path', 'type', 'description']:
                            extra_info[key] = value

                    writer.writerow([
                        resource_type,
                        item.get('name', ''),
                        item.get('path', ''),
                        item.get('description', ''),
                        str(extra_info) if extra_info else ''
                    ])

    def export_columns_to_csv(self, output_file):
        """Export all columns to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource', 'Column Name', 'Description', 'Data Type', 'Tests', 'Meta'])

            for resource, columns in self.column_data.items():
                for column in columns:
                    writer.writerow([
                        resource,
                        column.get('name', ''),
                        column.get('description', ''),
                        column.get('data_type', ''),
                        str(column.get('tests', [])),
                        str(column.get('meta', {}))
                    ])

    def export_docs_to_csv(self, output_file):
        """Export all documentation to a CSV file"""
        import csv

        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Resource', 'Documentation'])

            for resource, doc in self.documentations.items():
                writer.writerow([resource, doc])

