# Common prefixes used by financial institutions in transaction descriptions
BANK_PREFIXES = [
    r"^POS\s+(DEBIT\s+)?",
    r"^DEBIT\s+(CARD\s+)?(PURCHASE\s+)?",
    r"^ACH\s+(DEBIT\s+|CREDIT\s+)?",
    r"^CHECKCARD\s+\d+\s+",
    r"^PURCHASE\s+(AUTHORIZED\s+ON\s+)?",
    r"^RECURRING\s+(DEBIT\s+|PAYMENT\s+)?",
    r"^VISA\s+DDA\s+",
    r"^PENDING\s+",
    r"^ELECTRONIC\s+",
    r"^ONLINE\s+(BANKING\s+)?(PAYMENT\s+|TRANSFER\s+)?",
    r"^WIRE\s+(TRANSFER\s+)?",
    r"^BILL\s+PAY(MENT)?\s+",
    r"^AUTOPAY\s+",
    r"^MOBILE\s+(PURCHASE\s+)?",
    r"^SQ\s+\*",
    r"^TST\s+\*",
    r"^SP\s+\*?\s*",
]

# Suffix patterns to remove (dates, card numbers, reference IDs)
TRANSACTION_SUFFIXES = [
    r"\s+\d{2}/\d{2}$",
    r"\s+\d{2}/\d{2}/\d{2,4}$",
    r"\s+\d{4,}$",
    r"\s+#\d+$",
    r"\s+REF\s*#?\s*\d+$",
    r"\s+CARD\s+\d+$",
    r"\s+X{2,}\d{4}$",
    r"\s+\d{2}:\d{2}:\d{2}$",
    r"\s+[A-Z]{2}\s+\d{5}(-\d{4})?$",  # state + zip
]

def normalize_merchant_name(raw_text):
    if not raw_text:
        return ""

    # Clean and standardize the input
    merchant = raw_text.strip().upper()

    # Remove known prefixes
    for pattern in BANK_PREFIXES:
        merchant = re.sub(pattern, "", merchant, flags=re.IGNORECASE).strip()

    # Remove trailing suffixes
    for pattern in TRANSACTION_SUFFIXES:
        merchant = re.sub(pattern, "", merchant, flags=re.IGNORECASE).strip()

    # Normalize whitespace
    merchant = re.sub(r"\s+", " ", merchant)

    # Convert to title case for consistent formatting
    merchant = merchant.title()
    return merchant

def convert_date_string(date_input):
    if not date_input:
        return None

    date_str = str(date_input).strip()

    # List of common date formats used by banks
    date_formats = [
        "%m/%d/%Y",
        "%m/%d/%y",
        "%Y-%m-%d",
        "%m-%d-%Y",
        "%m-%d-%y",
        "%d/%m/%Y",
        "%Y%m%d",
        "%m/%d/%Y %H:%M:%S",
        "%Y-%m-%dT%H:%M:%S",
    ]

    # Try parsing with each format
    for fmt in date_formats:
        try:
            parsed_date = datetime.strptime(date_str, fmt)
            return parsed_date.strftime("%Y-%m-%d")
        except ValueError:
            continue

    # Fallback: use dateutil's flexible parser
    try:
        parsed = dateutil_parser.parse(date_str)
        return parsed.strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return None

def interpret_amount(value):
    if value is None:
        return None

    # Handle numeric inputs directly
    if isinstance(value, (int, float)):
        return round(float(value), 2)

    # Process string representation
    amount_str = str(value).strip()
    amount_str = amount_str.replace("$", "").replace(",", "").strip()

    # Handle accounting notation for negatives (parentheses)
    if amount_str.startswith("(") and amount_str.endswith(")"):
        amount_str = "-" + amount_str[1:-1]

    try:
        return round(float(amount_str), 2)
    except ValueError:
        return None

def display_currency(value):
    if value is None:
        return "$0.00"

    abs_val = abs(value)
    formatted = f"${abs_val:,.2f}"

    if value < 0:
        return "-" + formatted
    return formatted

def interpret_relative_time(expression):
    """Convert natural language time expressions into date ranges."""
    current_date = datetime.now()
    expr = expression.lower().strip()

    # This month
    if expr in ("this month", "current month"):
        start = current_date.replace(day=1)
        end = (start + relativedelta(months=1)) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Last month
    if expr in ("last month", "previous month"):
        start = (current_date.replace(day=1) - relativedelta(months=1))
        end = current_date.replace(day=1) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Year-to-date or this year
    if expr in ("this year", "current year", "ytd"):
        start = current_date.replace(month=1, day=1)
        return start.strftime("%Y-%m-%d"), current_date.strftime("%Y-%m-%d")

    # Last year
    if expr in ("last year", "previous year"):
        start = current_date.replace(year=current_date.year - 1, month=1, day=1)
        end = current_date.replace(year=current_date.year - 1, month=12, day=31)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # This week
    if expr in ("this week", "current week"):
        days_since_monday = current_date.weekday()
        start = current_date - timedelta(days=days_since_monday)
        end = start + timedelta(days=6)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Last week
    if expr in ("last week", "previous week"):
        days_since_monday = current_date.weekday() + 7
        start = current_date - timedelta(days=days_since_monday)
        end = start + timedelta(days=6)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Today / Yesterday
    if expr == "today":
        d = current_date.strftime("%Y-%m-%d")
        return d, d
    if expr == "yesterday":
        d = (current_date - timedelta(days=1)).strftime("%Y-%m-%d")
        return d, d

    # Handle "last N days/weeks/months/years"
    match = re.match(r"last\s+(\d+)\s+(day|week|month|year)s?", expr)
    if match:
        count = int(match.group(1))
        unit = match.group(2)

        if unit == "day":
            start_date = current_date - timedelta(days=count)
        elif unit == "week":
            start_date = current_date - timedelta(weeks=count)
        elif unit == "month":
            start_date = current_date - relativedelta(months=count)
        elif unit == "year":
            start_date = current_date - relativedelta(years=count)

        return start_date.strftime("%Y-%m-%d"), current_date.strftime("%Y-%m-%d")

    # Handle month names (e.g., "january", "february 2024")
    month_map = {
        "january": 1, "february": 2, "march": 3, "april": 4,
        "may": 5, "june": 6, "july": 7, "august": 8,
        "september": 9, "october": 10, "november": 11, "december": 12,
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "jun": 6, "jul": 7, "aug": 8, "sep": 9, "sept": 9,
        "oct": 10, "nov": 11, "dec": 12,
    }

    month_match = re.match(
        r"(january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)(?:\s+(\d{4}))?",
        expr
    )
    if month_match:
        month_num = month_map[month_match.group(1)]
        year_val = int(month_match.group(2)) if month_match.group(2) else current_date.year

        start = datetime(year_val, month_num, 1)
        end = (start + relativedelta(months=1)) - timedelta(days=1)
        return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")

    # Explicit date range format: "YYYY-MM-DD to YYYY-MM-DD"
    range_match = re.match(r"(\d{4}-\d{2}-\d{2})\s+to\s+(\d{4}-\d{2}-\d{2})", expr)
    if range_match:
        return range_match.group(1), range_match.group(2)

    return None, None

import os

def read_file_safely(filename):
    """Read file - SAFE: Validate and sanitize input path"""
    base_dir = "/path/to/user/documents"

    # Normalize the path and ensure it stays within base_dir
    full_path = os.path.abspath(os.path.join(base_dir, filename))

    # Prevent directory traversal by checking if resolved path starts with base_dir
    if not full_path.startswith(os.path.abspath(base_dir) + os.sep):
        raise ValueError("Invalid path: access denied")

    with open(full_path, 'r') as f:
        return f.read()

def read_config_safely(config_name):
    """Read config - SAFE: Use predefined allowed paths"""
    allowed_configs = {
        "settings": "/etc/app/settings.conf",
        "database": "/etc/app/database.conf",
        "logging": "/etc/app/logging.conf"
    }

    if config_name not in allowed_configs:
        raise ValueError(f"Config '{config_name}' not allowed")

    path = allowed_configs[config_name]
    with open(path, 'r') as f:
        return f.read()

