# Global port tracking
_port_root = None  # Set by Hauntimator before communication starts

def _open_serial_port(timeout=5):
    global _port_root
    device = None

    for available in list_ports.comports():
        if not isinstance(available.manufacturer, str):
            continue

        if 'MicroPython' in available.manufacturer:
            try:
                device = serial.Serial(available.device, baudrate=115200, timeout=timeout)
                _port_root = available.device
                break
            except Exception:
                device = None

    return device

def _get_active_port():
    return _port_root

def _send_to_device(serial_conn, message):
    written = serial_conn.write(message.encode('utf-8'))
    return written

def _send_string_to_device(message):
    conn = _open_serial_port()
    if conn is not None:
        _send_to_device(conn, message)
        conn.close()

def _receive_line_from_device():
    line_data = ''
    conn = _open_serial_port()
    if conn is not None:
        raw = conn.readline()
        if raw:
            line_data = raw.decode('utf-8', errors='replace')
        conn.close()
    return line_data

def check_connection_ready():
    connection = _open_serial_port()
    if connection is not None:
        connection.close()
        return True
    return False

def cleanup_resources():
