def get_binary_size_info():
    binary_mode = False
    block_sizes = []

    conn = _open_serial_port()
    if conn is not None:
        _send_to_device(conn, 'statusb\n')

        response1 = conn.readline().decode('utf-8', errors='replace')
        binary_mode = response1.startswith('True')

        response2 = conn.readline().decode('utf-8', errors='replace')
        parts = response2.strip().split()
        block_sizes = [int(x) for x in parts]

        conn.close()

    return binary_mode, block_sizes

def compute_file_checksum(filepath):
    checksum_value = -1

    conn = _open_serial_port(timeout=None)
    if conn is not None:
        _send_to_device(conn, f'c {filepath}\n')
        result = conn.readline().decode('utf-8', errors='replace').strip()
        conn.close()

        if result:
            try:
                checksum_value = int(result)
            except ValueError:
                pass

    return checksum_value

