def transfer_file_to_controller(source_filename, destination='', progress_callback=None):
    connection = _open_serial_port()
    if connection is None:
        return True  # Error occurred

    if os.path.isfile(source_filename):
        with open(source_filename, 'rb') as file_handle:
            file_size = os.fstat(file_handle.fileno()).st_size * 2  # Hex representation size

            _send_to_device(connection, f'b {destination} {file_size}\n')

            if progress_callback:
                progress_callback.maximum = file_size

            bytes_processed = 0
            chunk = file_handle.read(512)

            while chunk:
                hex_chunk = binascii.hexlify(chunk)
                connection.write(hex_chunk)
                bytes_processed += len(chunk) * 2

                if progress_callback:
                    if file_size > 20000:
                        progress_callback.value = bytes_processed
                        if progress_callback.canceled:
                            break
                    else:
                        progress_callback.visible = False

                chunk = file_handle.read(512)

    time.sleep(2)
    connection.close()
    return False

def transfer_csv_to_controller(csv_filename, destination='', progress_callback=None):
    output_filename = None
    result_code = 0

    wants_binary = are_tables_synchronized() and tables.PREFER_BINARY

    if wants_binary:
        output_filename = tables.convert_csv_to_binary(csv_filename)
        if output_filename:
            result_code = 0
            if destination and len(destination) >= 4:
                destination = destination[:-4] + '.bin'

            if transfer_file_to_controller(output_filename, destination, progress_callback):
                os.remove(output_filename)
                result_code = -1
        else:
            result_code = 1
            if transfer_file_to_controller(csv_filename, destination, progress_callback):
                result_code = -1
    elif wants_binary is False:
        result_code = 0
        if transfer_file_to_controller(csv_filename, destination, progress_callback):
            result_code = -1
    else:
        result_code = 1
        if transfer_file_to_controller(csv_filename, destination, progress_callback):
            result_code = -1

    return result_code

