def build_attention_cumulative_lengths(
    batch_size: int,
    seq_lengths_list: list,
    extra_kv_length: int = 0,
    include_q: bool = True,
    device: torch.device = None,
):
    """
    Helper to compute cumulative sequence lengths for variable-length attention.
    If include_q=False, only computes KV cumulatives (for encoder cross-attention).
    """
    cum_lens = [0]
    for _ in range(batch_size):
        for length in seq_lengths_list:
            cum_lens.append(cum_lens[-1] + length + extra_kv_length)
    cum_lens_tensor = torch.tensor(cum_lens, device=device, dtype=torch.int32)
    max_len = max(seq_lengths_list) + extra_kv_length if seq_lengths_list else 0
    return cum_lens_tensor, max_len


def create_navit_attention_masks(
    batch_size: int,
    original_context_length_list: list,
    history_context_length: int,
    encoder_hidden_states_seq_len: int,
    device: torch.device,
    restrict_self_attn: bool = False,
    guidance_cross_attn: bool = False,
):
    # --- Self-attention masks (hidden & history) ---
    if restrict_self_attn:
        q_lens, _ = build_attention_cumulative_lengths(
            batch_size, original_context_length_list, device=device
        )
        kv_lens, kv_max = build_attention_cumulative_lengths(
            batch_size, original_context_length_list,
            extra_kv_length=history_context_length, device=device
        )
        q_max = max(original_context_length_list)
    else:
        kv_lens, kv_max = build_attention_cumulative_lengths(
            batch_size, original_context_length_list,
            extra_kv_length=history_context_length, device=device
        )
        q_lens, q_max = kv_lens, kv_max

    navit_hidden_mask = (q_lens, kv_lens, q_max, kv_max)

    # History-only mask (only when restrict_self_attn)
    navit_history_mask = None
    if restrict_self_attn:
        hist_kv_lens, hist_kv_max = build_attention_cumulative_lengths(
            batch_size, original_context_length_list,
            extra_kv_length=history_context_length, device=device
        )
        navit_history_mask = (hist_kv_lens, hist_kv_lens, hist_kv_max, hist_kv_max)

    # --- Cross-attention mask (encoder) ---
    if guidance_cross_attn:
        cross_q_lens, cross_q_max = build_attention_cumulative_lengths(
            batch_size, original_context_length_list, device=device
        )
    else:
        cross_q_lens, cross_q_max = build_attention_cumulative_lengths(
            batch_size, original_context_length_list,
            extra_kv_length=history_context_length, device=device
        )
        cross_q_lens[0] = 0  # Ensure first element is zero

    enc_kv_lens, enc_kv_max = build_attention_cumulative_lengths(
        batch_size, [encoder_hidden_states_seq_len], device=device
    )

    navit_encoder_mask = (cross_q_lens, enc_kv_lens, cross_q_max, enc_kv_max)

    return navit_hidden_mask, navit_encoder_mask, navit_history_mask


@torch.compiler.disable
def _flash_wrapper(q, k, v):
    return flash_attn_func(q, k, v)


@torch.compiler.disable
def _flash_varlen_wrapper(q, k, v, cu_seqlens_q, cu_seqlens_k, max_seqlen_q, max_seqlen_k):
    return flash_attn_varlen_func(q, k, v, cu_seqlens_q, cu_seqlens_k, max_seqlen_q, max_seqlen_k)


def attn_varlen_func(q, k, v, attention_mask=None):
    B, L, H, C = q.shape

    if attention_mask is None:
        # Packed case: no variable-length masking needed
        if flash_attn_func is not None:
            out = _flash_wrapper(q, k, v)
        elif sageattn is not None:
            out = sageattn(q, k, v, tensor_layout="NHD")
        elif xformers_attn_func is not None:
            out = xformers_attn_func(q, k, v)
        else:
            out = torch.nn.functional.scaled_dot_product_attention(
                q.transpose(1, 2), k.transpose(1, 2), v.transpose(1, 2)
            ).transpose(1, 2)
        return out

    # Unflatten for varlen processing
    q_flat = q.view(B * L, H, C)
    k_flat = k.view(B * L, H, C)
    v_flat = v.view(B * L, H, C)

    q_cu, kv_cu, q_max, kv_max = attention_mask

    if flash_attn_varlen_func is not None:
        out = _flash_varlen_wrapper(q_flat, k_flat, v_flat, q_cu, kv_cu, q_max, kv_max)
    elif sageattn_varlen is not None:
        out = sageattn_varlen(q_flat, k_flat, v_flat, q_cu, kv_cu, q_max, kv_max)
    else:
        raise NotImplementedError("No varlen attention kernel available!")

    return out.view(B, L, H, C)

