class IdeficsImageProcessingTester(unittest.TestCase):
    def __init__(
        self,
        parent,
        batch_size=7,
        num_channels=3,
        image_size=18,
        min_resolution=30,
        max_resolution=400,
        size=None,
        image_mean=[0.48145466, 0.4578275, 0.40821073],
        image_std=[0.26862954, 0.26130258, 0.27577711],
    ):
        # Use default shortest_edge if not provided
        size = size if size is not None else {"shortest_edge": 30}
        self.parent = parent
        self.batch_size = batch_size
        self.num_channels = num_channels
        self.image_size = image_size
        self.min_resolution = min_resolution
        self.max_resolution = max_resolution
        self.image_mean = image_mean
        self.image_std = image_std
        # Extract size divisor from size dict (assumed to be 8 for consistency)
        self.size_divisor = 8

    def prepare_image_processor_dict(self):
        return {
            "image_mean": self.image_mean,
            "image_std": self.image_std,
            "image_size": self.image_size,
        }

    def compute_expected_dimensions(self, image_data, batched=False):
        """
        Compute expected output dimensions after resizing and rounding.
        """
        if not batched:
            target_shortest = self.image_size
            img = image_data[0]

            # Determine original dimensions based on input type
            if isinstance(img, Image.Image):
                orig_w, orig_h = img.size
            elif isinstance(img, np.ndarray):
                orig_h, orig_w = img.shape[:2]
            else:
                orig_h, orig_w = img.shape[1], img.shape[2]

            # Compute scale factor to match shortest edge
            scale = target_shortest / min(orig_w, orig_h)

            # Calculate new dimensions
            if orig_h < orig_w:
                new_height, new_width = target_shortest, int(scale * orig_w)
            else:
                new_height, new_width = int(scale * orig_h), target_shortest

            # Apply max size constraint (1333/800 ratio)
            max_allowed = int((1333 / 800) * target_shortest)
            if max(new_height, new_width) > max_allowed:
                scale_factor = max_allowed / max(new_height, new_width)
                new_height = int(new_height * scale_factor)
                new_width = int(new_width * scale_factor)

            # Round to nearest multiple of size_divisor
            rounded_height = (new_height // self.size_divisor) * self.size_divisor
            rounded_width = (new_width // self.size_divisor) * self.size_divisor

            return rounded_height, rounded_width
        else:
            # Process each image individually and take max dimensions
            dims_list = [self.compute_expected_dimensions([img]) for img in image_data]
            max_h = max(dims_list, key=lambda x: x[0])[0]
            max_w = max(dims_list, key=lambda x: x[1])[1]
            return max_h, max_w

    def get_output_shape(self, images):
        height, width = self.compute_expected_dimensions(images, batched=True)
        return (self.num_channels, height, width)

    def generate_test_images(self, equal_res=False, to_numpy=False, to_torch=False):
        return prepare_image_inputs(
            batch_size=self.batch_size,
            num_channels=self.num_channels,
            min_resolution=self.min_resolution,
            max_resolution=self.max_resolution,
            equal_resolution=equal_res,
            numpify=to_numpy,
            torchify=to_torch,
        )


@require_torch
@require_vision
class IdeficsImageProcessingTest(ImageProcessingTestMixin, unittest.TestCase):
    image_processor_class = IdeficsImageProcessor if is_vision_available() else None

    def setUp(self):
        super().setUp()
        self.tester = IdeficsImageProcessingTester(self)

    @property
    def config_dict(self):
        return self.tester.prepare_image_processor_dict()

    def test_basic_properties(self):
        processor = self.image_processor_class(**self.config_dict)
        self.assertTrue(hasattr(processor, "image_mean"))
        self.assertTrue(hasattr(processor, "image_std"))
        self.assertTrue(hasattr(processor, "image_size"))

    def test_from_dict_with_override(self):
        base_processor = self.image_processor_class.from_dict(self.config_dict)
        self.assertNotEqual(base_processor.image_size, 30)

        modified_processor = self.image_processor_class.from_dict(
            self.config_dict, image_size=42
        )
        self.assertEqual(modified_processor.image_size, 42)

    @require_torchvision
    def test_transform_equivalence(self):
        # Verify custom implementation matches torchvision behavior
        inputs = self.tester.generate_test_images(equal_res=False)
        processor = self.image_processor_class(**self.config_dict, return_tensors="pt")

        def ensure_rgb(image):
            if image.mode == "RGB":
                return image
            rgba = image.convert("RGBA")
            bg = Image.new("RGBA", rgba.size, (255, 255, 255))
            composite = Image.alpha_composite(bg, rgba).convert("RGB")
            return composite

        img_size = processor.image_size
        mean_vals = processor.image_mean
        std_vals = processor.image_std

        custom_transform = transforms.Compose([
            ensure_rgb,
            transforms.Resize((img_size, img_size), interpolation=transforms.InterpolationMode.BICUBIC),
            transforms.ToTensor(),
            transforms.Normalize(mean=mean_vals, std=std_vals),
        ])

        result_default = processor(inputs, transform=None, return_tensors="pt")
        result_custom = processor(inputs, transform=custom_transform, return_tensors="pt")

        torch.testing.assert_close(result_default, result_custom, rtol=0.0, atol=0.0)

