def _zero_gather_param(param: torch.Tensor, name: str = None) -> torch.Tensor:
    """Gather and detach parameter from DeepSpeed zero stage 3 if applicable."""
    try:
        from deepspeed import zero
        from deepspeed.runtime.zero.partition_parameters import ZeroParamStatus
        if hasattr(param, "ds_id"):
            if param.ds_status == ZeroParamStatus.NOT_AVAILABLE:
                if name:
                    print(f"[{name}] not available; skipping gather unless ignored.")
            with zero.GatheredParameters([param]):
                return param.data.detach().cpu().clone()
    except ImportError:
        pass
    return param.detach().cpu().clone()


def extract_adapter_weights(
    named_params: List[Tuple[str, torch.Tensor]],
    target_keys: List[str]
) -> Dict[str, torch.Tensor]:
    """Extract adapter-related weights matching any key in target_keys."""
    filtered = {k: v for k, v in named_params if any(kw in k for kw in target_keys)}
    return {k: _zero_gather_param(v, name=k).cpu() for k, v in filtered.items()}


def _distribute_indices_evenly(indices: List[int], lengths: List[int], num_parts: int) -> List[List[int]]:
    """
    Distribute indices across chunks such that total length per chunk is balanced.
    Uses greedy bin-packing strategy.
    """
    if len(indices) % num_parts != 0:
        # Fallback: round-robin assignment
        return [indices[i::num_parts] for i in range(num_parts)]

    chunk_size = len(indices) // num_parts
    chunks = [[] for _ in range(num_parts)]
    chunk_loads = [0] * num_parts

    for idx in indices:
        min_idx = chunk_loads.index(min(chunk_loads))
        chunks[min_idx].append(idx)
        chunk_loads[min_idx] += lengths[idx]
        if len(chunks[min_idx]) == chunk_size:
            chunk_loads[min_idx] = float('inf')

    return chunks


def _shuffle_by_modality_and_megabatch(
    lengths: List[int],
    batch_size: int,
    world_size: int,
    generator: Optional[torch.Generator] = None
) -> List[int]:
    """Create megabatches grouped by modality (lang vs vision), then interleave them randomly."""
    assert all(l != 0 for l in lengths), "Zero-length samples not allowed."

    pos_ids = [i for i, l in enumerate(lengths) if l > 0]
    neg_ids = [i for i, l in enumerate(lengths) if l < 0]

    if not pos_ids or not neg_ids:
        return _group_by_length(indices=list(range(len(lengths))), lengths=lengths,
                                batch_size=batch_size, world_size=world_size, generator=generator)

    mm_lengths = [lengths[i] for i in pos_ids]
    lang_lengths = [-lengths[i] for i in neg_ids]

    mm_order = [pos_ids[i] for i in _group_by_length(mm_lengths, batch_size, world_size, generator=None)]
    lang_order = [neg_ids[i] for i in _group_by_length(lang_lengths, batch_size, world_size, generator=None)]

    megabatch_len = world_size * batch_size
    mm_batches = [mm_order[i:i + megabatch_len] for i in range(0, len(mm_order), megabatch_len)]
    lang_batches = [lang_order[i:i + megabatch_len] for i in range(0, len(lang_order), megabatch_len)]

    last_mm_batch = mm_batches[-1]
    last_lang_batch = lang_batches[-1]
    leftover = sorted(last_mm_batch + last_lang_batch)

    mixed_megabatches = mm_batches[:-1] + lang_batches[:-1]
    perm = torch.randperm(len(mixed_megabatches), generator=generator)
    shuffled = [mixed_megabatches[i] for i in perm]

    if leftover:
        shuffled.append(leftover)

    return list(chain.from_iterable(shuffled))


def _group_by_length(
    indices: List[int],
    lengths: List[int],
    batch_size: int,
    world_size: int,
    generator: Optional[torch.Generator] = None
) -> List[int]:
    """Shuffle indices, sort within megabatches by descending length, split evenly."""
    perm = torch.randperm(len(indices), generator=generator).tolist()
    megabatch_size = world_size * batch_size

    megabatches = [
        sorted(perm[i:i + megabatch_size], key=lambda j: lengths[j], reverse=True)
        for i in range(0, len(indices), megabatch_size)
    ]

    distributed = [
        _distribute_indices_evenly(batch, lengths, world_size)
        for batch in megabatches
    ]

    return list(chain.from_iterable(chain.from_iterable(distributed)))


class BalancedLengthSampler(Sampler):
    """
    Custom sampler that groups samples by approximate sequence length,
    optionally separating modalities (language/vision), while preserving randomness.
    """

    def __init__(
        self,
        batch_size: int,
        world_size: int,
        lengths: List[int],
        generator: Optional[torch.Generator] = None,
        separate_modalities: bool = False,
    ):
        if not lengths:
            raise ValueError("Lengths list cannot be empty.")
        self.batch_size = batch_size
        self.world_size = world_size
        self.lengths = lengths
        self.generator = generator
        self.separate_modalities = separate_modalities

    def __len__(self) -> int:
        return len(self.lengths)

    def __iter__(self):
        if self.separate_modalities:
            indices = _shuffle_by_modality_and_megabatch(
                self.lengths, self.batch_size, self.world_size, self.generator
            )
        else:
            indices = _group_by_length(
                list(range(len(self.lengths))), self.lengths,
                self.batch_size, self.world_size, self.generator
            )
        return iter(indices)


class LLaVATrainerCustom(LLaVATrainer):  # Note: assuming base class exists or use Trainer directly
    def _get_train_sampler(self):
        if self.train_dataset is None or not has_length(self.train_dataset):
            return None
        if getattr(self.args, 'group_by_modality_length', False):
            lengths = getattr(self.train_dataset, 'modality_lengths', None)
            if lengths is None:
                raise RuntimeError("Modality lengths not found in dataset.")
            return BalancedLengthSampler(
                batch_size=self.args.train_batch_size,
                world_size=self.args.world_size * self.args.gradient_accumulation_steps,
                lengths=lengths,
                separate_modalities=True,
            )
        return super()._get_train_sampler()

    def build_optimizer_groups(self, model: nn.Module) -> List[Dict[str, Any]]:
        """Construct parameter groups for optimizer with optional projector-specific LR."""
        all_named = list(model.named_parameters())
        no_decay = get_parameter_names(model, ALL_LAYERNORM_LAYERS)
        bias_free = [n for n in no_decay if "bias" not in n]

        projector_names = {n for n, _ in all_named if "mm_projector" in n}

        groups = []

        # Base decay group
        base_decay = [p for n, p in all_named if n in bias_free and n not in projector_names and p.requires_grad]
        if base_decay:
            groups.append({"params": base_decay, "weight_decay": self.args.weight_decay})

        # Non-decay group
        base_nondecay = [p for n, p in all_named if n not in bias_free and n not in projector_names and p.requires_grad]
        if base_nondecay:
            groups.append({"params": base_nondecay, "weight_decay": 0.0})

        # Projector-specific groups
        proj_lr = getattr(self.args, "mm_projector_lr", None)
        if proj_lr is not None:
            proj_decay = [p for n, p in all_named if n in bias_free and n in projector_names and p.requires_grad]
            if proj_decay:
                groups.append({
                    "params": proj_decay,
                    "weight_decay": self.args.weight_decay,
                    "lr": proj_lr,
                })

            proj_nondecay = [p for n, p in all_named if n not in bias_free and n in projector_names and p.requires_grad]
            if proj_nondecay:
                groups.append({
                    "params": proj_nondecay,
                    "weight_decay": 0.0,
                    "lr": proj_lr,
                })

        return groups

    def create_optimizer(self):
        if is_sagemaker_mp_enabled():
            return super().create_optimizer()

        model = self.model
        if self.optimizer is None:
            grouped_params = self.build_optimizer_groups(model)
            opt_class, opt_kwargs = Trainer.get_optimizer_cls_and_kwargs(self.args)
            self.optimizer = opt_class(grouped_params, **opt_kwargs)

            if opt_class.__name__ == "Adam8bit":
                import bitsandbytes as bnb
                manager = bnb.optim.GlobalOptimManager.get_instance()
                skipped_count = 0
                for module in model.modules():
                    if isinstance(module, nn.Embedding):
                        params_to_skip = sum(p.numel() for p in module.parameters())
                        skipped_count += params_to_skip
                        logger.info(f"Skipping embedding module '{module}' ({params_to_skip / 2 ** 20:.2f}M params)")
                        manager.register_module_override(module, "weight", {"optim_bits": 32})
                        logger.debug(f"BitsAndBytes: Optimizing {module} in fp32")
                logger.info(f"Total skipped embeddings: {skipped_count / 2 ** 20:.2f}M params")

        return self.optimizer

    def _save_checkpoint(self, model, trial, metrics=None):
        if getattr(self.args, 'tune_mm_mlp_adapter', False):
            from transformers.trainer_utils import PREFIX_CHECKPOINT_DIR
            step_dir = f"{PREFIX_CHECKPOINT_DIR}-{self.state.global_step}"
            full_path = os.path.join(self._get_output_dir(trial), step_dir)

            match_keys = ['mm_projector', 'vision_resampler']
            if getattr(self.args, "use_im_start_end", False):
                match_keys.extend(['embed_tokens', 'embed_in'])

            state_dict = extract_adapter_weights(list(model.named_parameters()), match_keys)
            if self.args.local_rank in [0, -1]:
                model.config.save_pretrained(full_path)
                torch.save(state_dict, os.path.join(full_path, 'mm_projector.bin'))
        else:
            super()._save_checkpoint(model, trial, metrics)

    def _save(self, output_dir: Optional[str] = None, state_dict=None):
        if getattr(self.args, 'tune_mm_mlp_adapter', False):
            # Skip default save when tuning only adapters
            return
        super()._save(output_dir, state_dict)

import gc
import torch
from loguru import logger
from safetensors import safe_open
from lightx2v.utils.envs import *
from lightx2v.utils.lora_loader import LoRALoader
from lightx2v_platform.base.global_var import AI_DEVICE

class LoraAdapter:
    def __init__(self, model, model_prefix=None):
        self.model = model
        self.lora_metadata = {}
        self.lora_loader = LoRALoader(model_prefix=model_prefix)
        # Determine device: use AI_DEVICE unless CPU offloading is enabled
        if self.model.config.get("cpu_offload", False):
            self.device = torch.device("cpu")
        else:
            self.device = torch.device(AI_DEVICE)

    def _fetch_lora_tensors(self, lora_file_path):
        with safe_open(lora_file_path, framework="pt") as f:
            tensor_map = {
                key: f.get_tensor(key).to(GET_DTYPE()).to(self.device) 
                for key in f.keys()
            }
        return tensor_map

    def inject_lora_weights(self, lora_settings, target_model_type=None):
        # Ensure the model has original weights stored before applying LoRA
        if not hasattr(self.model, "original_weight_dict"):
            logger.error("Model missing 'original_weight_dict'. Cannot apply LoRA.")
            return False

        for setting in lora_settings:
            lora_tensors = self._fetch_lora_tensors(setting["path"])
            strength = setting.get("scale", 1.0)  # Use 'scale' as alias for 'strength'

            self.lora_loader.apply_lora(
                weight_dict=self.model.original_weight_dict,
                lora_weights=lora_tensors,
                strength=strength,
            )

            if target_model_type is not None:
                logger.info(f"LoRA injected into {target_model_type} model: {setting['path']} (scale: {strength})")
            else:
                logger.info(f"LoRA injected into model: {setting['path']} (scale: {strength})")

            # Clean up temporary tensors and trigger garbage collection
            del lora_tensors
            gc.collect()

        # Finalize weight updates on the model
        self.model._apply_weights(self.model.original_weight_dict)

        # Release GPU memory if applicable
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

import os
import jax
import numpy as np
from MaxText import max_logging, max_utils, maxtext_utils
from MaxText.metric_logger import MetadataKey, MetricLogger
from .max_utils import close_wandb_writer, initialize_wandb_writer

class PrimusMetricLogger(MetricLogger):
    """
    Logger for saving metrics to a local file, GCS and TensorBoard/WandB.
    """
    def __init__(self, cfg, lr_schedule):
        super().__init__(cfg, lr_schedule)
        self.wandb_instance = None
        if cfg.enable_wandb:
            self.wandb_instance = initialize_wandb_writer(cfg)

    def record_metrics(self, data, current_step, train_mode=True):
        """Main handler for metric logging during training/inference."""
        super().record_metrics(data, current_step, train_mode)
        if self.config.enable_wandb:
            self._log_to_wandb(data, current_step, train_mode)

    def _log_to_wandb(self, metrics_dict, step_num, is_train):
        """Internal method to push scalar metrics to Weights & Biases."""
        if jax.process_index() != 0 or self.wandb_instance is None:
            return
        wandb_data = {}
        # Extract scalar metrics
        for key in metrics_dict.get("scalar", []):
            wandb_data[key] = float(np.asarray(metrics_dict["scalar"][key]))
        # Handle nested scalar groups (e.g., per-layer metrics)
        for group_name in metrics_dict.get("scalars", []):
            for sub_key, value in metrics_dict["scalars"][group_name].items():
                wandb_data[f"{group_name}/{sub_key}"] = float(value)
        self.wandb_instance.log(wandb_data, step=step_num)

    def log_setup_details(self, model_params):
        """Records configuration, parameter count, XLA settings, etc., to TensorBoard and optionally WandB."""
        total_params = max_utils.count_parameters_from_pytree(model_params)
        self.metadata[MetadataKey.PER_DEVICE_TFLOPS], _, _ = (
            maxtext_utils.compute_tflops_per_device_for_training(self.config)
        )
        self.metadata[MetadataKey.PER_DEVICE_TOKENS] = maxtext_utils.compute_tokens_per_device_for_training(
            self.config
        )
        max_logging.info(f"model size: {total_params/1e9:.3f} B")
        max_utils.write_text_summary("parameter_count", str(total_params), self.writer)
        max_utils.write_text_summary("libtpu_init_arguments", os.getenv("LIBTPU_INIT_ARGS", ""), self.writer)
        maxtext_utils.append_config_to_tensorboard(self.config, self.writer)
        if self.wandb_instance is not None:
            self.wandb_instance.log({"parameter_count": total_params})

    def finalize_logging_and_cleanup(self):
        super().finalize_logging_and_cleanup()
        if self.config.enable_wandb:
            close_wandb_writer(self.wandb_instance)

import asyncio
import time
from django.contrib.auth import authenticate, login as auth_login, logout as auth_logout
from django.http import JsonResponse, StreamingHttpResponse
from django.shortcuts import redirect
from django.urls import reverse
import test_data

async def home(request):
    return JsonResponse(test_data.JSON_1K, safe=False)

async def event_stream(request):
    """Endpoint for Server-Sent Events that transmits timestamp updates every second."""
    async def stream_generator():
        current_time = 0
        while True:
            await asyncio.sleep(1)
            current_time = time.time()
            yield f"data: {current_time}\n\n"
    return StreamingHttpResponse(stream_generator(), content_type="text/event-stream")

def accounts_home(request):
    """Root endpoint for mounted Django accounts testing suite."""
    base_url = reverse("accounts-index").rstrip("/")
    return JsonResponse(
        {
            "origin": "django_mount",
            "description": "Mounted Django accounts test endpoints",
            "available_routes": {
                "authentication": reverse("accounts-login"),
                "deauthentication": reverse("accounts-logout"),
                "user_profile": reverse("accounts-profile"),
                "oauth_callback": f"{reverse('accounts-provider-callback')}?code=demo&state=xyz",
                "django_standard_auth": f"{base_url}/auth/",
                "allauth_integration": f"{base_url}/allauth/" if "allauth" in dir() else None,
            },
        }
    )

def accounts_sign_in(request):
    """
    Simplified login handler for mounted-Django integration tests.
    Accepts POST or GET with query parameters:
    - username (required)
    - password (required)
    - redirect_to (optional, defaults to /accounts/profile/)
    """
    if request.method == "GET":
        return JsonResponse(
            {
                "origin": "django_mount",
                "operation": "sign_in",
                "http_method": "POST",
                "mandatory_fields": ["username", "password"],
                "optional_fields": ["redirect_to"],
            }
        )

    # Extract credentials from either POST or GET
    user_name = request.POST.get("username") or request.GET.get("username")
    pass_word = request.POST.get("password") or request.GET.get("password")
    target_url = (
        request.POST.get("redirect_to") 
        or request.GET.get("redirect_to") 
        or reverse("accounts-profile")
    )

    # Validate presence of required fields
    if not user_name or not pass_word:
        return JsonResponse(
            {"success": False, "issue": "username and password must be provided"},
            status=400,
        )

    # Authenticate user
    authenticated_user = authenticate(request, username=user_name, password=pass_word)
    if authenticated_user is None:
        return JsonResponse({"success": False, "issue": "invalid credentials"}, status=401)

    # Log the user in
    auth_login(request, authenticated_user)
    return redirect(target_url)

def accounts_sign_out(request):
    """Logout endpoint for mounted-Django testing."""
    auth_logout(request)
    return redirect(reverse("accounts-sign_in"))

def accounts_dashboard(request):
    """User profile/status endpoint for mounted-Django testing."""
    current_user = request.user
    logged_in = bool(getattr(current_user, "is_authenticated", False))
    return JsonResponse(
        {
            "origin": "django_mount",
            "status": "logged_in" if logged_in else "logged_out",
            "identifier": current_user.get_username() if logged_in else None,
        }
    )

def accounts_oauth_callback(request):
    """
    Simulates an OAuth provider callback endpoint (similar to allauth's structure).
    Example URL:
    /accounts/oauth/callback/?code=abc123&state=xyz789
    """
    return JsonResponse(
        {
            "origin": "django_mount",
            "event": "oauth_callback",
            "parameters": dict(request.GET.items()),
        }
    )

import json
import sys
from pypdf import PdfReader

def extract_field_identifier(annotation):
    """Builds the full hierarchical field ID by traversing parent fields."""
    path_parts = []
    current = annotation
    while current:
        name = current.get('/T')
        if name:
            path_parts.append(name)
        current = current.get('/Parent')
    return ".".join(reversed(path_parts)) if path_parts else None

def build_field_descriptor(field, full_id):
    """Constructs a structured description of a PDF form field."""
    descriptor = {"field_id": full_id}
    field_type = field.get('/FT')

    if field_type == "/Tx":
        descriptor["type"] = "text"
    elif field_type == "/Btn":
        descriptor["type"] = "checkbox"
        states = field.get("/_States_", [])
        if len(states) == 2:
            if "/Off" in states:
                checked_state = [s for s in states if s != "/Off"][0]
                descriptor["checked_value"] = checked_state
                descriptor["unchecked_value"] = "/Off"
            else:
                print(f"Warning: Non-standard checkbox states for '{full_id}'. Values may be incorrect.")
                descriptor["checked_value"] = states[0]
                descriptor["unchecked_value"] = states[1]
        else:
            print(f"Unexpected number of states ({len(states)}) for checkbox '{full_id}'")
    elif field_type == "/Ch":
        descriptor["type"] = "choice"
        options_data = field.get("/_States_", [])
        descriptor["choice_options"] = [
            {"value": opt[0], "text": opt[1]} 
            for opt in options_data
        ]
    else:
        descriptor["type"] = f"unknown ({field_type})"

    return descriptor

def collect_form_fields(pdf_reader):
    """Extracts and organizes all fillable form fields from a PDF."""
    raw_fields = pdf_reader.get_fields()
    processed_fields = {}
    potential_radio_groups = set()

    # First pass: process non-container fields
    for field_id, field in raw_fields.items():
        if field.get("/Kids"):
            # Container field - might be radio group parent
            if field.get("/FT") == "/Btn":
                potential_radio_groups.add(field_id)
            continue
        processed_fields[field_id] = build_field_descriptor(field, field_id)

    # Second pass: handle radio buttons via annotations
    radio_details = {}
    for page_idx, page in enumerate(pdf_reader.pages):
        annotations = page.get('/Annots', [])
        for ann in annotations:
            full_id = extract_field_identifier(ann)
            if not full_id:
                continue

            if full_id in processed_fields:
                rect = ann.get('/Rect')
                processed_fields[full_id]["page"] = page_idx + 1
                processed_fields[full_id]["rect"] = rect
            elif full_id in potential_radio_groups:
                try:
                    appearance = ann.get("/AP", {})
                    normal_appearance = appearance.get("/N", {})
                    on_states = [v for v in normal_appearance.keys() if v != "/Off"]
                except (KeyError, AttributeError):
                    continue

                if len(on_states) == 1:
                    rect = ann.get("/Rect")
                    if full_id not in radio_details:
                        radio_details[full_id] = {
                            "field_id": full_id,
                            "type": "radio_group",
                            "page": page_idx + 1,
                            "radio_options": [],
                        }
                    radio_details[full_id]["radio_options"].append({
                        "value": on_states[0],
                        "rect": rect,
                    })

    # Filter to only fields with location data
    complete_fields = []
    for field_desc in processed_fields.values():
        if "page" in field_desc:
            complete_fields.append(field_desc)
        else:
            missing_id = field_desc.get("field_id", "unknown")
            print(f"Warning: Field '{missing_id}' has no position info; skipping")

    # Combine regular fields and radio groups
    all_fields = complete_fields + list(radio_details.values())

    # Sort by page, then vertical position (PDF uses bottom-left origin), then horizontal
    def position_sorter(field):
        if "radio_options" in field:
            rect = field["radio_options"][0].get("rect") or [0, 0, 0, 0]
        else:
            rect = field.get("rect") or [0, 0, 0, 0]
        y_coord = -rect[1] if len(rect) > 1 else 0
        x_coord = rect[0] if len(rect) > 0 else 0
        return [field.get("page", 0), y_coord, x_coord]

    all_fields.sort(key=position_sorter)
    return all_fields

def export_field_data(pdf_path, output_json):
    """Reads PDF form fields and writes JSON representation."""
    reader = PdfReader(pdf_path)
    field_list = collect_form_fields(reader)

    with open(output_json, 'w') as file:
        json.dump(field_list, file, indent=2)

    print(f"Exported {len(field_list)} fields to {output_json}")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python extract_form_fields.py <input.pdf> <output.json>")
        sys.exit(1)

    input_pdf = sys.argv[1]
    output_json = sys.argv[2]
    export_field_data(input_pdf, output_json)

from __future__ import print_function
import numpy as np
import torch
from PIL import Image
import os
import importlib
import argparse
from argparse import Namespace
import torchvision

def str2bool(v):
    if isinstance(v, bool):
        return v
    val = str(v).lower()
    if val in {'yes', 'true', 't', 'y', '1'}:
        return True
    elif val in {'no', 'false', 'f', 'n', '0'}:
        return False
    else:
        raise argparse.ArgumentTypeError('Boolean value expected.')

def copyconf(base_opt, **modifications):
    opt_copy = Namespace(**vars(base_opt))
    for param_name, new_val in modifications.items():
        setattr(opt_copy, param_name, new_val)
    return opt_copy

def genvalconf(train_opts, **overrides):
    conf = Namespace(**vars(train_opts))
    for attr_name, attr_val in train_opts.__dict__.items():
        if 'val' in attr_name:
            base_key = attr_name.split('_', 1)[0]
            if base_key in train_opts.__dict__:
                setattr(conf, base_key, attr_val)
    for key, val in overrides.items():
        setattr(conf, key, val)
    return conf

def find_class_in_module(class_name, module_path):
    normalized_name = class_name.replace('_', '').lower()
    module_obj = importlib.import_module(module_path)
    target_class = None
    for name, cls_candidate in module_obj.__dict__.items():
        if name.lower() == normalized_name:
            target_class = cls_candidate
            break
    assert target_class is not None, \
        f"In module '{module_path}', no class found matching '{class_name}' (case-insensitive, underscore removed)"
    return target_class

def tensor2im(tensor_input, dtype=np.uint8):
    """
    Convert a PyTorch tensor or NumPy array to an image array.

    Parameters:
        tensor_input (tensor/array) -- input image data, values in [0, 1]
        dtype (type)               -- desired output type
    """
    if isinstance(tensor_input, np.ndarray):
        img_np = tensor_input
    elif isinstance(tensor_input, torch.Tensor):
        img_tensor = tensor_input.detach().data
        img_np = img_tensor.clamp(0.0, 1.0).cpu().float().numpy()
        if img_np.shape[0] == 1:
            img_np = np.repeat(img_np, 3, axis=0)
        img_np = np.transpose(img_np, (1, 2, 0)) * 255.0
    else:
        return tensor_input

    return img_np.astype(dtype)

def diagnose_network(model, name='network'):
    """Compute and display average absolute gradient magnitude."""
    total_grad_norm = 0.0
    grad_count = 0
    for param in model.parameters():
        if param.grad is not None:
            total_grad_norm += torch.mean(torch.abs(param.grad.data)).item()
            grad_count += 1
    avg_grad = total_grad_norm / grad_count if grad_count > 0 else 0.0
    print(name)
    print(f"{avg_grad:.6f}")

def save_image(image_data, file_path, aspect_ratio=None):
    """Save a NumPy image array to disk with optional resizing."""
    pil_img = Image.fromarray(image_data)
    height, width = image_data.shape[:2]

    if aspect_ratio is not None and aspect_ratio != 1.0:
        if aspect_ratio > 1.0:
            new_size = (height, int(width * aspect_ratio))
        else:
            new_size = (int(height / aspect_ratio), width)
        pil_img = pil_img.resize(new_size, Image.BICUBIC)

    pil_img.save(file_path)

def print_numpy(arr, show_values=True, show_shape=False):
    """Print statistics of a NumPy array: mean, min, max, median, std, and optionally shape/values."""
    arr = arr.astype(np.float64)
    if show_shape:
        print(f"shape: {arr.shape}")
    if show_values:
        flat_arr = arr.flatten()
        stats = (
            np.mean(flat_arr),
            np.min(flat_arr),
            np.max(flat_arr),
            np.median(flat_arr),
            np.std(flat_arr)
        )
        print(f"mean = {stats[0]:.3f}, min = {stats[1]:.3f}, max = {stats[2]:.3f}, "
              f"median = {stats[3]:.3f}, std = {stats[4]:.3f}")

def mkdirs(dir_paths):
    """Create directories for each path in a list or single path."""
    if isinstance(dir_paths, (list, tuple)) and not isinstance(dir_paths, str):
        for p in dir_paths:
            mkdir(p)
    else:
        mkdir(dir_paths)

def mkdir(dir_path):
    """Create a directory if it doesn't exist."""
    if not os.path.exists(dir_path):
        os.makedirs(dir_path)

def correct_resize_label(tensor_data, new_size):
    device = tensor_data.device
    cpu_tensor = tensor_data.detach().cpu()
    resized_tensors = []

    for idx in range(cpu_tensor.size(0)):
        single_channel = cpu_tensor[idx, :1]
        # Convert to HWC uint8
        arr = np.transpose(single_channel.numpy().astype(np.uint8), (1, 2, 0))[:, :, 0]
        pil_img = Image.fromarray(arr).resize(new_size, Image.NEAREST)
        resized_arr = torch.from_numpy(np.array(pil_img)).long()
        resized_tensors.append(resized_arr)

    return torch.stack(resized_tensors, dim=0).to(device)

def correct_resize(tensor_data, new_size, interpolation=Image.BICUBIC):
    device = tensor_data.device
    cpu_tensor = tensor_data.detach().cpu()
    resized_tensors = []

    for idx in range(cpu_tensor.size(0)):
        single_sample = cpu_tensor[idx:idx+1]
        # Convert to PIL image
        img_array = tensor2im(single_sample)
        pil_img = Image.fromarray(img_array).resize(new_size, interpolation)
        # Back to tensor, normalized to [-1, 1]
        resized_tensor = torchvision.transforms.functional.to_tensor(pil_img) * 2.0 - 1.0
        resized_tensors.append(resized_tensor)

    return torch.stack(resized_tensors, dim=0).to(device)

def draw_landmarks(images, landmarks, color='r', radius=2):
    """
    Draw landmarks on images.

    Returns:
        images (np.array): (B, H, W, 3) RGB images with landmarks drawn, range [0, 255]

    Parameters:
        images      -- (B, H, W, 3) RGB images, uint8
        landmarks   -- (B, N, 2) landmark coordinates (x, y), y measured from top
        color       -- 'r' (red) or 'b' (blue)
        radius      -- half-size of square around each landmark point
    """
    if color == 'r':
        rgb = np.array([255, 0, 0], dtype=np.uint8)
    else:
        rgb = np.array([0, 0, 255], dtype=np.uint8)

    batch_size, height, width = images.shape[:3]
    images = images.copy()
    landmarks = landmarks.copy()

    # Flip y-coordinates vertically (image origin vs coordinate system)
    landmarks[..., 1] = height - 1 - landmarks[..., 1]
    landmarks = np.round(landmarks).astype(np.int32)

    num_points = landmarks.shape[1]
    for pt_idx in range(num_points):
        x_coords = landmarks[:, pt_idx, 0]
        y_coords = landmarks[:, pt_idx, 1]

        for dx in range(-radius, radius + 1):
            for dy in range(-radius, radius + 1):
                u = np.clip(x_coords + dx, 0, width - 1)
                v = np.clip(y_coords + dy, 0, height - 1)

                for b in range(batch_size):
                    images[b, v[b], u[b]] = rgb

    return images

# Custom import hooking and patching utilities for dynamic module manipulation

import sys
import importlib.util
import importlib.abc
from collections import defaultdict
import wrapt
from ucm.logger import init_logger

logger = init_logger(__name__)

# Registry for post-import hooks: maps module names to lists of callback functions
_POST_IMPORT_CALLBACKS = defaultdict(list)

class ImportInterceptor(importlib.abc.MetaPathFinder):
    """
    Intercepts the Python import mechanism to inject post-load behavior.
    Delegates actual loading to default finders but wraps loaders to execute
    registered callbacks after module initialization.
    """
    def find_spec(self, fullname, path, target=None):
        # Skip if no hooks registered for this module
        if fullname not in _POST_IMPORT_CALLBACKS:
            return None

        # Temporarily remove ourselves from sys.meta_path to avoid recursion
        original_meta_path = sys.meta_path[:]
        sys.meta_path = [finder for finder in sys.meta_path 
                         if not isinstance(finder, ImportInterceptor)]

        try:
            spec = importlib.util.find_spec(fullname, path)
            if spec is None or spec.loader is None:
                return None

            original_loader = spec.loader

            class HookedLoader(importlib.abc.Loader):
                """Loader wrapper that triggers callbacks after module execution."""
                def create_module(self, spec):
                    return original_loader.create_module(spec)

                def exec_module(self, module):
                    original_loader.exec_module(module)

                    # Execute all registered post-import callbacks
                    if fullname in _POST_IMPORT_CALLBACKS:
                        try:
                            for callback in _POST_IMPORT_CALLBACKS[fullname]:
                                callback(module)
                        except Exception as e:
                            logger.error(
                                f"Post-import hook execution failed for '{fullname}': {e}"
                            )
                            raise
            spec.loader = HookedLoader()
            return spec
        finally:
            sys.meta_path = original_meta_path
            sys.path_importer_cache.clear()

# Global instance of our import interceptor
_IMPORT_INTERCEPTOR = ImportInterceptor()

# Register the interceptor at the front of sys.meta_path if not already present
if not any(isinstance(finder, ImportInterceptor) for finder in sys.meta_path):
    sys.meta_path.insert(0, _IMPORT_INTERCEPTOR)

def register_on_import(module_name):
    """
    Decorator factory to register a function that will be called immediately after
    the specified module is imported.

    If the module is already loaded, the callback runs immediately.
    """
    def decorator(callback):
        if module_name not in _POST_IMPORT_CALLBACKS:
            _POST_IMPORT_CALLBACKS[module_name] = []
        _POST_IMPORT_CALLBACKS[module_name].append(callback)

        # Handle case where module is already imported
        if module_name in sys.modules:
            mod = sys.modules[module_name]
            if not getattr(mod, "_ucm_hooked", False):
                setattr(mod, "_ucm_hooked", True)
                try:
                    callback(mod)
                except Exception as e:
                    logger.warning(
                        f"Immediate callback execution failed for '{module_name}': {e}"
                    )
        return callback
    return decorator

def transfer_dataclass_features(target_class, source_class, *, 
                                 include_methods=True, include_slots=True):
    """
    Migrates dataclass-related attributes from source_class to target_class.
    Useful for runtime class transformation and inheritance replacement.
    """
    # Copy core dataclass metadata
    target_class.__annotations__ = getattr(source_class, "__annotations__", {})
    target_class.__dataclass_fields__ = getattr(source_class, "__dataclass_fields__", {})
    target_class.__dataclass_params__ = getattr(source_class, "__dataclass_params__", None)

    # Copy special methods
    for method_name in ["__init__", "__post_init__"]:
        if hasattr(source_class, method_name):
            setattr(target_class, method_name, getattr(source_class, method_name))

    # Copy comparison and representation methods if requested
    if include_methods:
        for method_name in [
            "__repr__", "__eq__", "__hash__", "__ne__",
            "__lt__", "__le__", "__gt__", "__ge__"
        ]:
            if hasattr(source_class, method_name):
                setattr(target_class, method_name, getattr(source_class, method_name))

    # Copy match_args if available and requested
    if include_slots and hasattr(source_class, "__match_args__"):
        target_class.__match_args__ = source_class.__match_args__

    return target_class

def _create_replacement_wrapper(new_implementation):
    """Factory function to generate wrappers for function replacement."""
    def wrapper(wrapped, instance, args, kwargs):
        if instance is not None:
            return new_implementation(instance, *args, **kwargs)
        return new_implementation(*args, **kwargs)
    return wrapper

def replace_or_add(target_module, function_name, new_function):
    """
    Dynamically replaces an existing function or adds a new one to a module/class.
    Uses wrapt for wrapping when replacing to preserve function signatures.
    """
    if hasattr(target_module, function_name):
        wrapt.wrap_function_wrapper(
            target_module, 
            function_name, 
            _create_replacement_wrapper(new_function)
        )
        logger.debug(
            f"Replaced: {getattr(target_module, '__name__', 'object')}.{function_name}"
        )
    else:
        setattr(target_module, function_name, new_function)
        logger.debug(
            f"Added: {getattr(target_module, '__name__', 'object')}.{function_name}"
        )

class OperatorPatch(wrapt.ObjectProxy):
    """
    Specialized proxy for patching PyTorch operators (torch.ops).
    Designed to work with custom operations registered via vLLM's 
    'direct_register_custom_op' mechanism.
    """
    def __init__(self, original, implementation, fake_impl=None):
        super().__init__(original)
        self._self_impl = implementation
        self._self_fake_impl = fake_impl or getattr(original, "fake_impl", None)

    def __call__(self, *args, **kwargs):
        return self._self_impl(*args, **kwargs)

    @property
    def fake_impl(self):
        return self._self_fake_impl

