import logging
import os
from datetime import datetime
from flask import Blueprint, request, jsonify, redirect, send_file
from app.web import (
    require_auth, _auth_required,
    get_config_manager, get_on_config_changed,
    _get_client_ip,
)
from werkzeug.utils import secure_filename

audit_log = logging.getLogger("docsis.audit")
log = logging.getLogger("docsis.web")
backup_bp = Blueprint("backup_routes", __name__)

@backup_bp.route("/api/download-backup", methods=["POST"])
@require_auth
def download_backup():
    """Generate and stream a compressed backup archive for download."""
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify({"error": "System not initialized"}), 500

    try:
        from .backup import generate_archive
        buffer_stream = generate_archive(config_mgr.data_directory)
        timestamp = datetime.now().strftime("%Y-%m-%d_%H%M%S")
        safe_name = f"docsight_backup_{timestamp}.tar.gz"

        audit_log.info("Backup downloaded by user: client_ip=%s", _get_client_ip())
        return send_file(
            buffer_stream, 
            mimetype="application/gzip", 
            as_attachment=True, 
            download_name=safe_name
        )
    except Exception as exc:
        log.exception("Failed to create backup archive: %s", exc)
        return jsonify({"error": str(exc)}), 500

@backup_bp.route("/api/schedule-backup", methods=["POST"])
@require_auth
def schedule_backup():
    """Persist backup to configured storage location and manage retention."""
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify({"error": "System not initialized"}), 500

    storage_location = config_mgr.get("backup_directory", "/backups")
    max_retention = config_mgr.get("backup_retention_count", 5)

    try:
        from .backup import save_archive_to_disk, prune_old_archives
        saved_path = save_archive_to_disk(config_mgr.data_directory, storage_location)
        pruned_count = prune_old_archives(storage_location, max_retention)

        audit_log.info(
            "Scheduled backup completed: ip=%s path=%s retained=%d",
            _get_client_ip(), saved_path, pruned_count
        )
        return jsonify({
            "success": True, 
            "saved_file": os.path.basename(saved_path),
            "retained_count": pruned_count
        })
    except Exception as err:
        log.error("Scheduled backup operation failed: %s", err)
        return jsonify({"error": str(err)}), 500

@backup_bp.route("/api/backups/list")
@require_auth
def list_available_backups():
    """Retrieve list of existing backups in configured directory."""
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify([])

    storage_dir = config_mgr.get("backup_directory", "/backups")
    from .backup import fetch_backup_list
    return jsonify(fetch_backup_list(storage_dir))

@backup_bp.route("/api/backups/<backup_name>", methods=["DELETE"])
@require_auth
def remove_backup(backup_name):
    """Delete specified backup file after validation."""
    config_mgr = get_config_manager()
    if not config_mgr:
        return jsonify({"error": "System not initialized"}), 500

    storage_dir = config_mgr.get("backup_directory", "/backups")
    sanitized_name = secure_filename(backup_name)

    if not sanitized_name or sanitized_name != backup_name:
        return jsonify({"error": "Invalid filename provided"}), 400

    full_path = os.path.join(storage_dir, sanitized_name)
    canonical_path = os.path.realpath(full_path)
    canonical_storage = os.path.realpath(storage_dir)

    # Prevent directory traversal attacks
    if not canonical_path.startswith(canonical_storage + os.sep):
        return jsonify({"error": "Access denied: invalid path"}), 400

    if not os.path.isfile(canonical_path):
        return jsonify({"error": "Backup file not found"}), 404

    os.unlink(canonical_path)
    audit_log.info("Backup removed: ip=%s file=%s", _get_client_ip(), sanitized_name)
    return jsonify({"success": True})

@backup_bp.route("/api/validate-upload", methods=["POST"])
def validate_upload():
    """Validate uploaded backup archive and extract metadata.
    Authentication bypassed during initial setup phase.
    """
    config_mgr = get_config_manager()
    if config_mgr and config_mgr.is_setup_complete() and _auth_required():
        return redirect("/login")

    if "archive" not in request.files:
        return jsonify({"error": "No archive file included"}), 400

    uploaded_file = request.files["archive"]
    if not uploaded_file.filename:
        return jsonify({"error": "Empty filename provided"}), 400

    content = uploaded_file.read()
    if len(content) > 512 * 1024 * 1024:  # 512 MB limit
        return jsonify({"error": "File exceeds maximum allowed size"}), 400

    try:
        from .backup import inspect_archive
        metadata = inspect_archive(content)
        return jsonify({"valid": True, "info": metadata})
    except ValueError as issue:
        return jsonify({"valid": False, "message": str(issue)}), 400

@backup_bp.route("/api/apply-restore", methods=["POST"])
def apply_restore():
    """Apply backup restoration from uploaded archive.
    Authentication bypassed during initial setup phase.
    """
    config_mgr = get_config_manager()
    if config_mgr and config_mgr.is_setup_complete() and _auth_required():
        return redirect("/login")

    if "archive" not in request.files:
        return jsonify({"error": "No archive file submitted"}), 400

    uploaded_file = request.files["archive"]
    if not uploaded_file.filename:
        return jsonify({"error": "No filename specified"}), 400

    content = uploaded_file.read()
    if len(content) > 512 * 1024 * 1024:
        return jsonify({"error": "Archive too large"}), 400

    try:
        from .backup import execute_restoration
        target_dir = config_mgr.data_directory if config_mgr else "/app/data"
        outcome = execute_restoration(content, target_dir)

        audit_log.info(
            "Restore operation completed: client_ip=%s files_restored=%d",
            _get_client_ip(), len(outcome["restored_files"]),
        )

        # Refresh configuration state post-restoration
        if config_mgr:
            config_mgr.reload()

        on_change_handler = get_on_config_changed()
        if on_change_handler:
