import collections
import ssl
import threading
import time
import traceback
import msgpack
from websocket import create_connection
import blankly
from blankly.utils.utils import info_print
from blankly.exchanges.abc_exchange_websocket import ABCExchangeWebsocket
from blankly.exchanges.auth.utils import load_auth
from blankly.exchanges.interfaces.alpaca.alpaca_websocket_utils import parse_alpaca_timestamp, switch_type


def send_subscription_message(connection, action_type, channel_name, symbols_tuple):
    payload = {
        'action': action_type,
        channel_name: symbols_tuple
    }
    connection.send(msgpack.packb(payload))


def subscribe_to_channel(connection, channel, symbol):
    send_subscription_message(connection, 'subscribe', channel, tuple([symbol]))


def unsubscribe_from_channel(connection, channel):
    send_subscription_message(connection, 'unsubscribe', channel, tuple())


def establish_and_authenticate_connection(symbol, url, stream):
    # Establish raw WebSocket connection without certificate validation
    connection = create_connection(
        url,
        sslopt={"cert_reqs": ssl.CERT_NONE},
        header={'Content-Type': 'application/msgpack'}
    )

    # Load Alpaca credentials
    _, auth_data = load_auth('alpaca')

    # Send authentication payload
    auth_payload = {
        'action': 'auth',
        'key': auth_data['API_KEY'],
        'secret': auth_data['API_SECRET']
    }
    connection.send(msgpack.packb(auth_payload))

    # Wait for initial connection confirmation
    raw_response = msgpack.unpackb(connection.recv())
    if not (isinstance(raw_response, list) and len(raw_response) > 0 and raw_response[0].get('msg') == 'connected'):
        info_print("Connection failed during handshake.")
        raise ConnectionError("Initial connection response was invalid.")

    # Subscribe to requested stream
    subscribe_to_channel(connection, stream, symbol)

    # Confirm subscription success
    sub_response = msgpack.unpackb(connection.recv())
    if isinstance(sub_response, list) and len(sub_response) > 0:
        message = sub_response[0].get('msg', '')
        if message == 'authenticated':
            return connection
        elif message == 'connection limit exceeded':
            # Retry after unsubscribing
            unsubscribe_from_channel(connection, stream)
            _ = msgpack.unpackb(connection.recv())  # consume unsubscribe ack
            subscribe_to_channel(connection, stream, symbol)
            _ = msgpack.unpackb(connection.recv())  # consume resubscribe ack
            return connection
        else:
            info_print(f"Authentication failed: {message}")
            raise PermissionError(f"Auth error: {message}")
    else:
        raise ValueError("Unexpected subscription response format.")


class Tickers(ABCExchangeWebsocket):
    def __init__(self, currency_id, stream_type, log_file=None,
                 pre_event_handler=None, initially_inactive=False,
                 websocket_endpoint="wss://stream.data.alpaca.markets/v2/iex/", **kwargs):
        """
        Initialize ticker stream handler.
        Args:
            currency_id: Trading pair like "BTC-USD"
            stream_type: One of trades, quotes, bars, dailyBars, statuses, lulds
            log_file: Optional path to write logs
            websocket_endpoint: Default Alpaca IEX feed URL
        """
        self.__currency = currency_id
        self.__stream = stream_type
        self.__log_callback, self.__interface_transformer, log_header = switch_type(stream_type)
        self.__extra_kwargs = kwargs

        # Setup logging file
        self.__logging_enabled = False
        self.__log_path = None
        self.__log_handle = None
        if log_file is not None:
            self.__logging_enabled = True
            self.__log_path = log_file
            try:
                self.__log_handle = open(log_file, 'x+')
                self.__log_handle.write(log_header)
            except FileExistsError:
                self.__log_handle = open(log_file, 'a')

        self.URL = websocket_endpoint
        self.connection = None
        self.__last_raw_response = None
        self.__subscription_ack = None
        self.__latest_tick = None
        self.__latest_time = None
        self.__event_listeners = []
        self.__pre_event_hook = pre_event_handler

        # Load user preferences
        user_prefs = blankly.utils.load_user_preferences()
        buffer_capacity = user_prefs["settings"]["websocket_buffer_size"]

        # Simulate deque with bounded lists
        self.__price_buffer = []
        self.__time_buffer = []
        self.__max_buffer_size = buffer_capacity

        if not initially_inactive:
            self.start_websocket()

    def start_websocket(self):
        """Start or restart the WebSocket connection."""
        if self.connection is None:
            try:
                self.connection = establish_and_authenticate_connection(
                    self.__currency, self.URL, self.__stream
                )
                self.__last_raw_response = self.connection.recv()
                worker_thread = threading.Thread(target=self.__process_incoming_messages)
                worker_thread.daemon = True
                worker_thread.start()
            except Exception as e:
                traceback.print_exc()
                info_print(f"Failed to start websocket for {self.__currency}: {e}")
        else:
            if self.is_websocket_open():
                print("WebSocket already active.")
            else:
                info_print("Restarting closed connection...")
                self.connection = None
                self.start_websocket()

    def __process_incoming_messages(self):
        attempt_count = 0
        while self.is_websocket_open():
            keep_alive = self.is_websocket_open()
            try:
                raw_bytes = self.connection.recv()
                parsed = self.__unpack_first_item(raw_bytes)

                # Handle timestamp conversion
                if 't' in parsed:
                    parsed['t'] = parse_alpaca_timestamp(parsed['t'])
                    event_time = parsed['t']
                elif 'code' in parsed:
                    continue
                else:
                    event_time = time.time()

                # Log and transform data
                if self.__logging_enabled:
                    self.__log_response(self.__log_callback, parsed)
                transformed = self.__interface_transformer(parsed)

                # Update latest values
                self.__latest_time = event_time
                self.__time_buffer.append(event_time)
                self.__latest_tick = transformed
                self.__price_buffer.append(transformed)

                # Enforce buffer size manually
                if len(self.__time_buffer) > self.__max_buffer_size:
                    self.__time_buffer.pop(0)
                if len(self.__price_buffer) > self.__max_buffer_size:
                    self.__price_buffer.pop(0)

                # Notify registered callbacks
                for listener in self.__event_listeners:
                    try:
                        listener(transformed, **self.__extra_kwargs)
                    except Exception:
                        traceback.print_exc()

                attempt_count += 1

            except Exception as exc:
                traceback.print_exc()
                if keep_alive:
                    continue
                else:
                    info_print(f"Websocket read error for {self.__currency} on {self.__stream}. Reconnecting...")
                    time.sleep(2)
                    try:
                        self.connection.close()
                    except:
                        pass
                    self.connection = None
                    self.start_websocket()
                    break

    @staticmethod
    def __unpack_first_item(data):
        unpacked = msgpack.unpackb(data)
        if isinstance(unpacked, list) and len(unpacked) > 0:
            return unpacked[0]
        return unpacked

    def __log_response(self, formatter, data):
        if self.__logging_enabled and self.__log_handle:
            try:
                self.__log_handle.write(formatter(data))
                self.__log_handle.flush()
            except Exception:
                pass

    """ Required interface methods """

    def is_websocket_open(self):
        return self.connection is not None and self.connection.connected

    def get_currency_id(self):
        return self.__currency

    def add_callback(self, handler):
        self.__event_listeners.append(handler)

    def get_latest_tick(self):
        return self.__latest_tick

    def get_latest_timestamp(self):
        return self.__latest_time

    def get_time_series(self):
        return list(self.__time_buffer)

    def get_price_series(self):
        return list(self.__price_buffer)

    def get_last_raw_response(self):
        return self.__last_raw_response

    def terminate_connection(self):
        if self.connection and self.connection.connected:
            self.connection.close()
        else:
            print(f"Websocket for {self.__currency} ({self.__stream}) is already closed.")

    def reset_stream(self):
        self.start_websocket()

