def forex_market_open():
    current_time = datetime.datetime.now()
    day_of_week = current_time.weekday()
    hour_of_day = current_time.hour

    # Forex market is closed on weekends (Saturday=5, Sunday=6)
    # Also closed after 5pm (17:00) on Friday
    if day_of_week == 5 or day_of_week == 6:
        return False
    elif day_of_week == 4 and hour_of_day >= 17:
        return False
    else:
        return True

