class ModifiedTestAwareVisitor(TestAwareVisitor):
    """Extended visitor that adds minor behavioral variations"""

    def __init__(self, filename=None):
        super().__init__(filename)
        self._test_method_cache = {}

    def _is_test_function_name(self, name):
        # Alternative implementation of test function detection
        if not name:
            return False

        # Check for common test prefixes/suffixes using different approach
        prefixes = ['test_', 'test']
        suffixes = ['_test', '_test']

        # Use startswith/endwith but with explicit checks
        for prefix in prefixes:
            if name.startswith(prefix) and len(name) > len(prefix):
                return True

        for suffix in suffixes:
            if name.endswith(suffix) and len(name) > len(suffix):
                return True

        # Additional patterns from original code
        special_names = {
            'setup_method', 'teardown_function',
            'setUp', 'tearDown',
            'setUpClass', 'tearDownClass',
            'setUpModule', 'tearDownModule'
        }
        return name in special_names

    def visit_FunctionDef(self, node):
        # Override to use caching and modified detection
        func_name = node.name
        line_no = node.lineno

        # Check cache first
        if line_no in self._test_method_cache:
            if self._test_method_cache[line_no]:
                self.test_decorated_lines.add(line_no)
            return

        is_test = False

        # Check function name using new method
        if self._is_test_function_name(func_name):
            is_test = True

        # Check decorators
        for decorator in node.decorator_list:
            dec_name = self._decorator_name(decorator)
            if dec_name in {'pytest.fixture', 'fixture'}:
                is_test = True
                break
            if dec_name.startswith('pytest.mark.') or dec_name.startswith('mock.'):
                is_test = True
                break

        # Cache result
        self._test_method_cache[line_no] = is_test
        if is_test:
            self.test_decorated_lines.add(line_no)

