# Type alias for serialized request components
RequestSerialized = Tuple[str, str, Dict[str, str], Optional[str], List[str]]


class ApiClient:
    """
    Generic API client for OpenAPI-based services.
    Handles communication between client and server in a uniform way across implementations.
    Specifics like methods/models are generated from templates.

    :param configuration: Optional Configuration object; defaults to global default if not provided.
    :param header_name: Custom header name to include in requests.
    :param header_value: Value corresponding to custom header.
    :param cookie: Cookie string to attach to headers.
    """

    # Supported primitive types
    SUPPORTED_SCALAR_TYPES = (float, bool, bytes, str, int)

    # Mapping from OpenAPI type strings to Python types
    TYPE_MAP = {
        'int': int,
        'long': int,
        'float': float,
        'str': str,
        'bool': bool,
        'date': datetime.date,
        'datetime': datetime.datetime,
        'decimal': decimal.Decimal,
        'object': object,
    }

    _instance = None

    def __init__(
        self,
        config=None,
        custom_header_name=None,
        custom_header_value=None,
        session_cookie=None
    ) -> None:
        self.config = config or Configuration.get_default()
        self.http_backend = rest.RESTClientObject(self.config)
        self.global_headers = {}
        if custom_header_name:
            self.global_headers[custom_header_name] = custom_header_value
        self.session_cookie = session_cookie
        self.user_agent_string = 'OpenAPI-Generator/0.0.7/python'
        self.validate_locally = self.config.client_side_validation

    async def __aenter__(self):
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        await self.shutdown()

    async def shutdown(self):
        await self.http_backend.close()

    @property
    def user_agent_string(self) -> str:
        """User-Agent header value used in requests."""
        return self.global_headers.get('User-Agent', '')

    @user_agent_string.setter
    def user_agent_string(self, value: str):
        self.global_headers['User-Agent'] = value

    def set_global_header(self, key: str, value: str):
        """Set a default header to be included in every request."""
        self.global_headers[key] = value

    @classmethod
    def get_default(cls):
        """Return singleton instance of ApiClient."""
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    @classmethod
    def set_default(cls, instance):
        """Set the global default client instance."""
        cls._instance = instance

    def prepare_request(
        self,
        http_method,
        endpoint_path,
        path_vars=None,
        query_params=None,
        header_params=None,
        payload=None,
        form_data=None,
        file_fields=None,
        auth_names=None,
        collection_formats=None,
        override_host=None,
        request_auth_override=None
    ) -> RequestSerialized:
        """Constructs the low-level HTTP request parameters."""
        cfg = self.config
        headers = header_params or {}
        headers.update(self.global_headers)
        if self.session_cookie:
            headers['Cookie'] = self.session_cookie

        headers = self._prepare_for_json(headers)
        headers = dict(self._params_to_pairs(headers, collection_formats))

        # Process path variables
        if path_vars:
            path_vars = self._prepare_for_json(path_vars)
            path_vars = self._params_to_pairs(path_vars, collection_formats)
            for var_key, var_val in path_vars:
                placeholder = '{' + var_key + '}'
                encoded_val = url_quote(str(var_val), safe=cfg.safe_chars_for_path_param)
                endpoint_path = endpoint_path.replace(placeholder, encoded_val)

        # Handle form data & files
        post_fields = []
        if form_data or file_fields:
            post_fields = list(form_data) if form_data else []
            post_fields = self._prepare_for_json(post_fields)
            post_fields = self._params_to_pairs(post_fields, collection_formats)
            if file_fields:
                post_fields.extend(self._build_file_params(file_fields))

        # Apply authentication
        self._inject_auth_credentials(
            headers, query_params, auth_names, endpoint_path, http_method, payload, request_auth_override
        )

        # Serialize body if present
        if payload is not None:
            payload = self._prepare_for_json(payload)

        # Build final URL
        base_url = override_host or cfg.host
        full_url = base_url + endpoint_path
        if query_params:
            query_params = self._prepare_for_json(query_params)
            query_str = self._params_to_query_string(query_params, collection_formats)
            full_url += '?' + query_str

        return http_method, full_url, headers, payload, post_fields

    async def execute_request(
        self,
        method,
        url,
        headers=None,
        body=None,
        form_data=None,
        timeout=None
    ):
        """Perform the actual HTTP call asynchronously."""
        try:
            resp = await self.http_backend.request(
                method, url,
                headers=headers,
                body=body,
                post_params=form_data,
                timeout=timeout
            )
        except ApiException as err:
            raise err
        return resp

    def process_response(
        self,
        raw_response,
        expected_types_map=None
    ) -> ApiResponse[ApiResponseT]:
        """Parse and wrap the raw response into structured format."""
        assert raw_response.data is not None, "Response body must be read before deserialization"

        status_code = raw_response.status
        response_type = expected_types_map.get(str(status_code))
        if not response_type and isinstance(status_code, int) and 100 <= status_code <= 599:
            response_type = expected_types_map.get(f"{status_code // 100}XX")

        content_type = raw_response.getheader('content-type')
        encoding_match = re.search(r"charset=([a-zA-Z\-\d]+)[\s;]?", content_type or "")
        encoding = encoding_match.group(1) if encoding_match else "utf-8"
        decoded_body = raw_response.data.decode(encoding)

        result_obj = None
        if response_type == "bytearray":
            result_obj = raw_response.data
        elif response_type == "file":
            result_obj = self._save_temp_file(raw_response)
        elif response_type:
            result_obj = self._parse_content(decoded_body, response_type, content_type)

        if not (200 <= status_code <= 299):
            raise ApiException.from_response(
                http_resp=raw_response,
                body=decoded_body,
                data=result_obj,
            )

        return ApiResponse(
            status_code=status_code,
            data=result_obj,
            headers=raw_response.getheaders(),
            raw_data=raw_response.data
        )

    def _prepare_for_json(self, obj):
        """Converts objects into JSON-compatible representations."""
        if obj is None:
            return None
        elif isinstance(obj, Enum):
            return obj.value
        elif isinstance(obj, SecretStr):
            return obj.get_secret_value()
        elif isinstance(obj, self.SUPPORTED_SCALAR_TYPES):
            return obj
        elif isinstance(obj, list):
            return [self._prepare_for_json(item) for item in obj]
        elif isinstance(obj, tuple):
            return tuple(self._prepare_for_json(item) for item in obj)
        elif isinstance(obj, (datetime.datetime, datetime.date)):
            return obj.isoformat()
        elif isinstance(obj, decimal.Decimal):
            return str(obj)
        elif isinstance(obj, dict):
            obj_dict = obj
        else:
            if hasattr(obj, 'to_dict') and callable(getattr(obj, 'to_dict')):
                obj_dict = obj.to_dict()
            else:
                obj_dict = vars(obj)

        return {k: self._prepare_for_json(v) for k, v in obj_dict.items()}

    def _parse_content(self, text: str, target_type: str, content_type: Optional[str]):
        """Deserialize response body based on content type."""
        if content_type is None:
            try:
                return json.loads(text) if text else ""
            except ValueError:
                return text
        elif re.match(r'^application/(json|[\w!#$&.+-^_]+\+json)\s*(;|$)', content_type, re.IGNORECASE):
            return json.loads(text) if text else ""
        elif re.match(r'^text\/[a-z.+-]+\s*(;|$)', content_type, re.IGNORECASE):
            return text
        else:
            raise ApiException(status=0, reason=f"Unsupported content type: {content_type}")

    def _deserialize_value(self, raw_data, type_hint):
        """Recursively deserialize raw data according to given type hint."""
        if raw_data is None:
            return None

        if isinstance(type_hint, str):
            if type_hint.startswith('List['):
                match = re.match(r'List\[(.*)]', type_hint)
                assert match, "Invalid List type definition"
                inner_type = match.group(1)
                return [self._deserialize_value(item, inner_type) for item in raw_data]
            elif type_hint.startswith('Dict['):
                match = re.match(r'Dict\[([^,]*), (.*)]', type_hint)
                assert match, "Invalid Dict type definition"
                val_type = match.group(2)
                return {k: self._deserialize_value(v, val_type) for k, v in raw_data.items()}
            elif type_hint in self.TYPE_MAP:
                type_hint = self.TYPE_MAP[type_hint]
            else:
                type_hint = getattr(hindsight_client_api.models, type_hint)

        if type_hint in self.SUPPORTED_SCALAR_TYPES:
            return self._convert_primitive(raw_data, type_hint)
        elif type_hint == object:
            return raw_data
        elif type_hint == datetime.date:
            return self._parse_date(raw_data)
        elif type_hint == datetime.datetime:
            return self._parse_datetime(raw_data)
        elif type_hint == decimal.Decimal:
            return decimal.Decimal(raw_data)
        elif issubclass(type_hint, Enum):
            return self._convert_enum(raw_data, type_hint)
        else:
            return type_hint.from_dict(raw_data)

    def _params_to_pairs(self, params, formats=None):
        """Convert parameter dictionaries/lists into list of tuples with optional formatting."""
        result = []
        fmts = formats or {}
        for key, value in (params.items() if isinstance(params, dict) else params):
            if key in fmts:
                fmt = fmts[key]
                if fmt == 'multi':
                    result.extend((key, str(val)) for val in value)
                else:
                    delimiters = {'ssv': ' ', 'tsv': '\t', 'pipes': '|'}
                    sep = delimiters.get(fmt, ',')
                    result.append((key, sep.join(str(x) for x in value)))
            else:
                result.append((key, value))
        return result

    def _params_to_query_string(self, params, formats=None):
        """Build URL-encoded query string from parameters."""
        parts = []
        fmts = formats or {}
        for key, value in (params.items() if isinstance(params, dict) else params):
            if isinstance(value, bool):
                value = str(value).lower()
            elif isinstance(value, (int, float)):
                value = str(value)
            elif isinstance(value, dict):
                value = json.dumps(value)

            if key in fmts:
                fmt = fmts[key]
                if fmt == 'multi':
                    parts.extend(f"{url_quote(str(key))}={url_quote(str(val))}" for val in value)
                else:
                    delimiters = {'ssv': ' ', 'tsv': '\t', 'pipes': '|'}
                    sep = delimiters.get(fmt, ',')
                    joined = sep.join(url_quote(str(x)) for x in value)
                    parts.append(f"{url_quote(str(key))}={joined}")
            else:
                parts.append(f"{url_quote(str(key))}={url_quote(str(value))}")
        return "&".join(parts)

    def _build_file_params(self, files_dict):
        """Prepare multipart/form-data file uploads."""
        result = []
        for field_name, file_info in files_dict.items():
            if isinstance(file_info, str):
                with open(file_info, 'rb') as f:
                    filename = os.path.basename(f.name)
                    content = f.read()
            elif isinstance(file_info, bytes):
                filename = field_name
                content = file_info
            elif isinstance(file_info, tuple):
                filename, content = file_info
            elif isinstance(file_info, list):
                for sub_file in file_info:
                    result.extend(self._build_file_params({field_name: sub_file}))
                continue
            else:
                raise ValueError("Invalid file input type")

            mime_type = mimetypes.guess_type(filename)[0] or 'application/octet-stream'
            result.append((field_name, (filename, content, mime_type)))
        return result

    def _select_accept_header(self, candidates):
        """Choose best Accept header from list."""
        if not candidates:
            return None
        for candidate in candidates:
            if 'json' in candidate.lower():
                return candidate
        return candidates[0]

    def _select_content_type(self, options):
        """Select appropriate Content-Type header."""
        if not options:
            return None
        for opt in options:
            if 'json' in opt.lower():
                return opt
        return options[0]

    def _inject_auth_credentials(
        self,
        headers,
        queries,
        auth_names,
        path,
        method,
        body,
        override_auth=None
    ):
        """Apply authentication settings to headers and queries."""
        if not auth_names:
            return
        if override_auth:
            self._apply_single_auth(headers, queries, path, method, body, override_auth)
        else:
            for name in auth_names:
                setting = self.config.auth_settings().get(name)
                if setting:
                    self._apply_single_auth(headers, queries, path, method, body, setting)

    def _apply_single_auth(self, headers, queries, path, method, body, auth_config):
        """Inject one specific auth credential into request."""
        location = auth_config['in']
        if location == 'cookie':
            headers['Cookie'] = auth_config['value']
        elif location == 'header':
            if auth_config['type'] != 'http-signature':
                headers[auth_config['key']] = auth_config['value']
        elif location == 'query':
            queries.append((auth_config['key'], auth_config['value']))
        else:
            raise ApiValueError("Auth must be in query or header")

    def _save_temp_file(self, response):
        """Save downloaded file to temporary directory."""
        _, temp_path = tempfile.mkstemp(dir=self.config.temp_folder_path)
        os.remove(temp_path)

        cd_header = response.getheader("Content-Disposition")
        filename = None
        if cd_header:
            m = re.search(r'filename=[\'"]?([^\'"\s]+)[\'"]?', cd_header)
            assert m, "Missing filename in Content-Disposition"
            filename = m.group(1)
            temp_path = os.path.join(os.path.dirname(temp_path), filename)

        with open(temp_path, "wb") as f:
            f.write(response.data)
        return temp_path

    def _convert_primitive(self, data, target_type):
        """Convert raw data to primitive Python type."""
        try:
            return target_type(data)
        except (UnicodeEncodeError, TypeError):
            return str(data)

    def _parse_date(self, date_str):
        """Parse ISO date string into datetime.date."""
        try:
            return date_parse(date_str).date()
        except ImportError:
            return date_str
        except ValueError:
            raise rest.ApiException(status=0, reason=f"Failed to parse '{date_str}' as date")

    def _parse_datetime(self, dt_str):
        """Parse ISO datetime string into datetime.datetime."""
        try:
            return date_parse(dt_str)
        except ImportError:
            return dt_str
        except ValueError:
            raise rest.ApiException(status=0, reason=f"Failed to parse '{dt_str}' as datetime")

    def _convert_enum(self, value, enum_class):
        """Convert raw value to enum member."""
        try:
            return enum_class(value)
        except ValueError:
            raise rest.ApiException(
                status=0,
                reason=f"Cannot convert '{value}' to {enum_class.__name__}"
            )

# Cloudflare DNS & Ingress Manager (Type III Clone)
