# and refactored helper functions while preserving original functionality.

import os
import sys
import json
import requests
import yaml
import subprocess
import argparse

# --- Configuration ---
# Renamed variables for clarity; maintains backward compatibility via fallbacks
API_TOKEN = os.getenv("CLOUDFLARE_API_TOKEN") or os.getenv("CF_API_TOKEN")
ZONE_IDENTIFIER = os.getenv("CLOUDFLARE_ZONE_ID") or os.getenv("CF_ZONE_ID")
CONFIG_FILE_PATH = "/etc/cloudflared/config.yml"

class CloudflareManager:
    def __init__(self, simulate_mode=False):
        self.simulate_mode = simulate_mode
        # Use conditional expression to build headers safely
        self.headers = {
            "Authorization": f"Bearer {API_TOKEN}",
            "Content-Type": "application/json"
        } if API_TOKEN else None

    def _validate_credentials(self):
        # Refactored validation with clearer error message structure
        missing = []
        if not self.headers:
            missing.append("CLOUDFLARE_API_TOKEN")
        if not ZONE_IDENTIFIER:
            missing.append("CLOUDFLARE_ZONE_ID")

        if missing:
            return {"error": f"Missing required credentials: {', '.join(missing)}."}
        return None

    def list_dns_records(self):
        if err := self._validate_credentials(): 
            return err

        base_url = "https://api.cloudflare.com/client/v4/zones"
        endpoint = f"{base_url}/{ZONE_IDENTIFIER}/dns_records"
        query_params = {"per_page": 100}

        response = requests.get(endpoint, headers=self.headers, params=query_params)
        return response.json()

    def create_dns_record(self, record_type, record_name, record_value, 
                          enable_proxy=True, description=""):
        if err := self._validate_credentials(): 
            return err

        api_endpoint = f"https://api.cloudflare.com/client/v4/zones/{ZONE_IDENTIFIER}/dns_records"
        payload = {
            "type": record_type,
            "name": record_name,
            "content": record_value,
            "proxied": enable_proxy,
            "comment": description
        }

        if self.simulate_mode:
            return {"status": "simulation", "action": "create_dns_record", "payload": payload}

        result = requests.post(api_endpoint, headers=self.headers, json=payload)
        return result.json()

    def modify_dns_record(self, record_uuid, record_type, record_name, 
                          record_value, enable_proxy=True, description=""):
        if err := self._validate_credentials(): 
            return err

        api_url = f"https://api.cloudflare.com/client/v4/zones/{ZONE_IDENTIFIER}/dns_records/{record_uuid}"
        payload_data = {
            "type": record_type,
            "name": record_name,
            "content": record_value,
            "proxied": enable_proxy,
            "comment": description
        }

        if self.simulate_mode:
            return {"status": "simulation", "action": "modify_dns_record", "url": api_url, "payload": payload_data}

        response = requests.put(api_url, headers=self.headers, json=payload_data)
        return response.json()

    def remove_dns_record(self, record_uuid):
        if err := self._validate_credentials(): 
            return err

        delete_url = f"https://api.cloudflare.com/client/v4/zones/{ZONE_IDENTIFIER}/dns_records/{record_uuid}"

        if self.simulate_mode:
            return {"status": "simulation", "action": "remove_dns_record", "target": delete_url}

        deletion_result = requests.delete(delete_url, headers=self.headers)
        return deletion_result.json()

    def configure_zone_setting(self, setting_key, new_value):
        if err := self._validate_credentials(): 
            return err

        patch_url = f"https://api.cloudflare.com/client/v4/zones/{ZONE_IDENTIFIER}/settings/{setting_key}"
        payload_body = {"value": new_value}

        if self.simulate_mode:
            return {"status": "simulation", "action": "configure_zone_setting", "data": payload_body}

        update_response = requests.patch(patch_url, headers=self.headers, json=payload_body)
        return update_response.json()

    def adjust_ingress_rules(self, domain_label, backend_service):
        """
        Adjusts cloudflared ingress configuration.
        REQUIRES: Sudo privileges on the host system.
        Use --simulate-mode to preview changes without committing.
        """
        try:
            # Verify config file existence unless in simulation mode
            if not os.path.exists(CONFIG_FILE_PATH) and not self.simulate_mode:
                return {"error": f"Configuration file missing at {CONFIG_FILE_PATH}"}

            # Load current configuration using multiple strategies
            config_data = None
            try:
                with open(CONFIG_FILE_PATH, 'r') as stream:
                    config_data = yaml.safe_load(stream)
            except PermissionError:
                # Attempt reading via sudo cat when direct access fails
                proc = subprocess.run(
                    ["sudo", "cat", CONFIG_FILE_PATH], 
                    capture_output=True, text=True, check=True
                )
                config_data = yaml.safe_load(proc.stdout)

            # Ensure ingress section exists
            if 'ingress' not in config_data:
                config_data['ingress'] = []

            # Search for existing hostname entry
            found = False
            for item in config_data['ingress']:
                if item.get('hostname') == domain_label:
                    item['service'] = backend_service
                    found = True
                    break

            # Add new rule if not found
            if not found:
                # Insert before final catch-all if present
                if config_data['ingress'] and \
                   'service' in config_data['ingress'][-1] and \
                   'hostname' not in config_data['ingress'][-1]:
                    config_data['ingress'].insert(-1, {"hostname": domain_label, "service": backend_service})
                else:
                    config_data['ingress'].append({"hostname": domain_label, "service": backend_service})

            # Serialize updated configuration
            updated_yaml = yaml.dump(config_data, default_flow_style=False)

            if self.simulate_mode:
                return {
                    "status": "simulation", 
                    "action": "adjust_ingress_rules", 
                    "file": CONFIG_FILE_PATH,
                    "preview_content": updated_yaml
                }

            # Persist changes using tee with sudo
            writer = subprocess.Popen(['sudo', 'tee', CONFIG_FILE_PATH], 
                                      stdin=subprocess.PIPE, stdout=subprocess.PIPE)
            writer.communicate(input=updated_yaml.encode())

            # Trigger service restart
            subprocess.run(['sudo', 'systemctl', 'restart', 'cloudflared'], check=True)
            return {"status": "success", "message": f"Ingress updated for {domain_label} and cloudflared restarted."}

        except Exception as ex:
            return {"status": "failure", "message": str(ex)}

