# Mock imports for compatibility; assume these exist in real environment
class BaseAgent:
    def load(self, path): pass
    def save(self, path): pass
    def pretrain_step(self, batch, step): return {}
    def train_step(self, batch, step): return {}
    def prepare_training(self): pass
    def sample_actions(self, obs, deterministic=True, num_samples=1):
