class CompositeLogger:
    def __init__(self, log_dir, name, logger_config):
        self.log_dir = log_dir
        self.name = name
        self.config = logger_config
        self.step_counts = {}

    def log_scalars(self, prefix, metrics, step):
        key = f"{prefix}/{step}"
        self.step_counts[key] = metrics

    def close(self):
        pass


def set_seed_everywhere(seed):
    np.random.seed(seed)


class D4RLDataset:
    def __init__(self, task, clip_eps, scan, norm_obs, norm_reward):
        self.task = task
        self.clip_eps = clip_eps
        self.scan = scan
        self.norm_obs = norm_obs
        self.norm_reward = norm_reward

    def get_obs_stats(self):
        return np.zeros(17), np.ones(17)

    def sample(self, batch_size):
        return {}


def make_env(task, seed):
    env = gym.make(task)
    env.seed(seed)
    return env


class Trainer:
    def __init__(self, config):
        self.config = config
        set_seed_everywhere(config.seed)

        # Construct log directory manually
        log_parts = [config.log.dir, config.algo.name, config.log.tag, config.task]
        full_log_dir = os.path.join(*log_parts)
        ckpt_save_dir = os.path.join(full_log_dir, "ckpt")

        # Initialize logger
        wandb_cfg = {}
        if hasattr(config.log, 'project') and hasattr(config.log, 'entity'):
            wandb_cfg = {
                "activate": True,
                "config": self._to_container(config),
                "settings": wandb.Settings(_disable_stats=True),
                "project": config.log.project,
                "entity": config.log.entity
            }
        else:
            wandb_cfg["activate"] = False

        self.logger = CompositeLogger(
            log_dir=full_log_dir,
            name="seed" + str(config.seed),
            logger_config={
                "TensorboardLogger": {"activate": True},
                "WandbLogger": wandb_cfg
            }
        )

        self.ckpt_save_dir = ckpt_save_dir
        os.makedirs(self.logger.log_dir, exist_ok=True)

        # Save config manually
        with open(os.path.join(self.logger.log_dir, "config.yaml"), 'w') as f:
            yaml.safe_dump(self._to_container(config), f)

        print("=" * 35 + " Config " + "=" * 35)
        print(yaml.dump(self._to_container(config)))
        print("=" * 80)
        print(f"\nSave results to: {self.logger.log_dir}\n")

        # Dataset setup
        self.dataset = D4RLDataset(
            task=config.task,
            clip_eps=config.data.clip_eps,
            scan=config.data.scan,
            norm_obs=config.data.norm_obs,
            norm_reward=config.data.norm_reward,
        )
        self.obs_mean, self.obs_std = self.dataset.get_obs_stats()

        # Environment factory
        def make_env_fn(task, seed):
            env = make_env(task, seed)
            return TransformObservation(env, lambda obs: (obs - self.obs_mean) / self.obs_std)

        self.env = make_env_fn(config.task, config.seed)
        self.eval_envs = gym.vector.SyncVectorEnv([
            lambda: make_env_fn(config.task, config.seed + i)
            for i in range(config.eval.num_episodes)
        ])

        algo_name = config.algo.name
        if algo_name not in SUPPORTED_AGENTS:
            raise ValueError(f"Unsupported algorithm: {algo_name}")
        self.agent = SUPPORTED_AGENTS[algo_name](
            obs_dim=self.env.observation_space.shape[0],
            act_dim=self.env.action_space.shape[0],
            cfg=config.algo,
            seed=config.seed,
        )

    @staticmethod
    def _to_container(cfg):
        # Simulate OmegaConf.to_container without OmegaConf
        result = {}
        for key in dir(cfg):
            if not key.startswith('_'):
                val = getattr(cfg, key)
                if isinstance(val, (int, float, str, bool, type(None))):
                    result[key] = val
                elif hasattr(val, '__dict__'):
                    result[key] = Trainer._to_container(val)
                else:
                    result[key] = val
        return result

    def train(self):
        try:
            if self.config.load is not None:
                self.agent.load(self.config.load)
            else:
                if self.config.pretrain_steps > 0:
                    pbar = tqdm(range(self.config.pretrain_steps + 1), desc="pretraining")
                    for i in pbar:
                        if i % self.config.eval.interval == 0:
                            self.eval_and_save(i, prefix="pretrain_eval")
                        batch = self.dataset.sample(batch_size=self.config.data.batch_size)
                        update_info = self.agent.pretrain_step(batch, step=i)
                        if i % self.config.log.interval == 0:
                            self.logger.log_scalars("pretrain", update_info, step=i)

            if getattr(self.config, 'pretrain_only', False):
                print("Pretrain completed! Aborting.")
                return

            self.agent.prepare_training()
            pbar = tqdm(range(self.config.train_steps + 1), desc="training")
            for i in pbar:
                if i % self.config.eval.interval == 0:
                    self.eval_and_save(i)
                if i % self.config.eval.stats_interval == 0:
                    batch = self.dataset.sample(batch_size=self.config.data.batch_size)
                    stats = self.agent.compute_statistics(batch)
                    if stats is not None:
                        self.logger.log_scalars("", stats, step=i)
                batch = self.dataset.sample(batch_size=self.config.data.batch_size)
                update_info = self.agent.train_step(batch, step=i)
                if i % self.config.log.interval == 0:
                    self.logger.log_scalars("", update_info, step=i)
        except KeyboardInterrupt:
            print("Stopped by keyboard interruption.")
        except Exception as e:
            print("Stopped by exception:", str(e))
        finally:
            self.logger.close()

    def eval_and_save(self, step: int, prefix: str = "eval"):
        returns = np.zeros(self.config.eval.num_episodes)
        lengths = np.zeros(self.config.eval.num_episodes)
        dones = np.zeros(self.config.eval.num_episodes, dtype=bool)

        obs = self.eval_envs.reset()
        while not np.all(dones):
            actions, _ = self.agent.sample_actions(
                obs,
                deterministic=True,
                num_samples=self.config.eval.num_samples,
            )
            obs, _, new_dones, infos = self.eval_envs.step(actions)

            for idx, (done_flag, info) in enumerate(zip(new_dones, infos)):
                if done_flag and not dones[idx]:
                    returns[idx] = info['episode']['return']
                    lengths[idx] = info['episode']['length']
                    dones[idx] = True

        eval_metrics = {
            "mean": np.mean(returns),
            "median": np.median(returns),
            "std": np.std(returns),
            "min": np.min(returns),
            "max": np.max(returns),
            "length": np.mean(lengths),
        }

        self.logger.log_scalars(prefix, eval_metrics, step=step)
        if getattr(self.config.log, 'save_ckpt', False):
            self.agent.save(os.path.join(self.ckpt_save_dir, str(step)))


def main(config):
    os.environ["CUDA_VISIBLE_DEVICES"] = str(config.device)
    os.environ["XLA_PYTHON_CLIENT_PREALLOCATE"] = "false"

    algo_name = getattr(config, 'algo', None)
    if algo_name is None or not hasattr(algo_name, 'name'):
        err_msg = "Algorithm is not specified. Please specify the algorithm via `algo=<algo_name>` in command.\n"
        err_msg += "Available algorithms are:\n  "
        err_msg += "\n  ".join(SUPPORTED_AGENTS.keys())
        print(err_msg)
        return

    trainer = Trainer(config)
    trainer.train()


# Simulated Hydra decorator
