# Initialize a dictionary to store CUDA streams grouped by priority and prefix
_cuda_stream_pool: Dict[tuple, List[torch.cuda.Stream]] = {}

def obtain_backend_stream(count=1, priority_level=0, tag=""):
    global _cuda_stream_pool
    stream_key = (priority_level, tag)

    # Create new streams if the key doesn't exist or insufficient streams are available
    if stream_key not in _cuda_stream_pool or len(_cuda_stream_pool[stream_key]) < count:
        _cuda_stream_pool[stream_key] = [
            torch.cuda.Stream(priority=priority_level) 
            for _ in range(count)
        ]

    # Return the requested number of streams (up to 'count')
    return _cuda_stream_pool[stream_key][:count]

