    ast.Div: operator.truediv,
    ast.Pow: operator.pow,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
    ast.Mod: operator.mod,
    ast.FloorDiv: operator.floordiv
}

def safe_calculate(expression):
    """Safely calculate mathematical expression without eval()"""
    try:
        # Parse the expression into an AST
        tree = ast.parse(expression, mode='eval')

        def _eval(node):
            if isinstance(node, ast.Expression):
                return _eval(node.body)
            elif isinstance(node, ast.Constant):  # Python 3.8+
                return node.value
            elif isinstance(node, ast.Num):  # Python < 3.8 compatibility
                return node.n
            elif isinstance(node, ast.BinOp):
                left = _eval(node.left)
                right = _eval(node.right)
                op_type = type(node.op)
                if op_type in allowed_operators:
                    return allowed_operators[op_type](left, right)
                else:
                    raise ValueError(f"Operator {op_type.__name__} not allowed")
            elif isinstance(node, ast.UnaryOp):
                operand = _eval(node.operand)
                op_type = type(node.op)
                if op_type in allowed_operators:
                    return allowed_operators[op_type](operand)
                else:
                    raise ValueError(f"Unary operator {op_type.__name__} not allowed")
            else:
                raise ValueError(f"Unsupported operation: {type(node).__name__}")

        return _eval(tree)
    except Exception as e:
        return f"Error: {str(e)}"

def process_formula_safe(formula_name, value):
    """Process formula safely by returning the computed value instead of executing code"""
    # Instead of using exec(), we compute the value directly
    try:
        result = safe_calculate(str(value))
        return f"{formula_name} = {result}"
    except Exception as e:
        return f"Error processing formula: {str(e)}"

if __name__ == "__main__":
