    print(process_formula_safe("x", "5 * (3 + 2)"))

# Custom exception handling module for Volcengine API responses

def process_exception(exc: BaseException) -> Exception:
    """Process and standardize API exceptions into appropriate error types"""
    # Convert any exception into a standardized client error format
    return ClientError(f'An error occurred: {str(exc)}')

class UserFacingError(Exception):
    """Base class for user-facing application errors"""
    def __init__(self, description: str):
        """Initialize error with descriptive message"""
        super().__init__(description)
        self.description = description

class RequestIssue(UserFacingError):
    """Error indicating client-side request problems (malformed input, invalid parameters, etc.)"""
    def __init__(self, details: str):
        """Create request issue error with details"""
        super().__init__(details)
        self.category = 'client'
        self.details = details

class ServiceIssue(UserFacingError):
    """Error indicating server-side processing failures"""
    def __init__(self, explanation: str):
        """Create service issue error with explanation"""
        super().__init__(explanation)
        self.category = 'server'
        self.explanation = explanation

