# Multi-language daemon (one LSPClient per language, single process)
SOCK_DIR = os.path.expanduser("~/.cache/lsp-query")
DEFAULT_TIMEOUT = 300

def _sock_path():
    return os.environ.get("LSP_SOCK", os.path.join(SOCK_DIR, "daemon.sock"))

def _workspace_root():
    ws = os.environ.get("LSP_WORKSPACE")
    if ws:
        return ws
    try:
        root = subprocess.check_output(
            ["git", "rev-parse", "--show-toplevel"],
            stderr=subprocess.DEVNULL, text=True
        ).strip()
        if root:
            return root
    except Exception:
        pass
    return os.getcwd()

def _idle_timeout():
    return int(os.environ.get("LSP_TIMEOUT", DEFAULT_TIMEOUT))

class MultiLangDaemon:
    """Manages multiple LSP clients, one per language. Lazy-starts servers on demand."""
    def __init__(self, workspace):
        self.workspace = workspace
        self._clients = {}  # lang -> LSPClient
        self._last_used = {}  # lang -> timestamp
        self._lock = threading.Lock()

    def get_client(self, lang):
        """Get or start an LSP client for the given language."""
        with self._lock:
            if lang in self._clients:
                self._last_used[lang] = time.time()
                return self._clients[lang]
            server_cmd = get_server_cmd(lang)
            if not server_cmd:
                cfg = LANG_CONFIG.get(lang, {})
                install_hint = cfg.get("install", "unknown")
                return None, f"Server not found for '{lang}'. Install with: {install_hint}"
            client = LSPClient(self.workspace, server_cmd, lang=lang)
            try:
                client.start()
            except Exception as e:
                return None, f"Failed to start {lang} server: {e}"
            self._clients[lang] = client
            self._last_used[lang] = time.time()
            return client

    def shutdown_lang(self, lang):
        with self._lock:
            client = self._clients.pop(lang, None)
            self._last_used.pop(lang, None)
        if client:
            client.shutdown()
            return True
        return False

    def shutdown_all(self):
        with self._lock:
            langs = list(self._clients.keys())
        for lang in langs:
            self.shutdown_lang(lang)

    def cleanup_idle(self, timeout):
        """Shut down servers that have been idle longer than timeout."""
        now = time.time()
        with self._lock:
            idle_langs = [
                lang for lang, ts in self._last_used.items()
                if now - ts > timeout
            ]
        for lang in idle_langs:
            self.shutdown_lang(lang)

    def active_servers(self):
        """Return list of (lang, uptime_seconds) for active servers."""
        now = time.time()
        with self._lock:
            return [
                (lang, now - self._last_used.get(lang, now))
                for lang in self._clients
            ]

    @property
    def has_clients(self):
        with self._lock:
            return len(self._clients) > 0

def _run_daemon():
    """Run the multi-language LSP daemon."""
    sock_path = _sock_path()
    os.makedirs(os.path.dirname(sock_path), exist_ok=True)
    if os.path.exists(sock_path):
        os.unlink(sock_path)
    workspace = _workspace_root()
    daemon = MultiLangDaemon(workspace)
    server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    server.bind(sock_path)
    server.listen(5)
    server.settimeout(1.0)
    idle_timeout = _idle_timeout()
    last_activity = time.time()

    def _shutdown_handler(signum, frame):
        daemon.shutdown_all()
        server.close()
        if os.path.exists(sock_path):
            os.unlink(sock_path)
        sys.exit(0)

    signal.signal(signal.SIGTERM, _shutdown_handler)
    signal.signal(signal.SIGINT, _shutdown_handler)
    pid_path = sock_path + ".pid"
    with open(pid_path, "w") as f:
        f.write(str(os.getpid()))
    try:
        while True:
            try:
                conn, _ = server.accept()
            except socket.timeout:
                # Periodic idle cleanup.
                daemon.cleanup_idle(idle_timeout)
                if time.time() - last_activity > idle_timeout and not daemon.has_clients:
                    break
                continue
            last_activity = time.time()
            try:
                data = b""
                while True:
                    chunk = conn.recv(65536)
                    if not chunk:
                        break
                    data += chunk
                    if b"\n\n" in data:
                        break
                request = json.loads(data.decode("utf-8").strip())
                result = _handle_request(daemon, request)
                response = json.dumps(result).encode("utf-8")
                conn.sendall(response)
            except Exception as e:
                try:
                    conn.sendall(json.dumps({"error": str(e)}).encode("utf-8"))
                except Exception:
                    pass
            finally:
                conn.close()
    finally:
        daemon.shutdown_all()
        server.close()
        if os.path.exists(sock_path):
            os.unlink(sock_path)
        if os.path.exists(pid_path):
            os.unlink(pid_path)

def _handle_request(daemon, req):
    cmd = req.get("command", "")
    # Commands that don't need a language.
    if cmd == "ping":
        return {"result": "pong"}
    if cmd == "shutdown":
        lang = req.get("language")
        if lang:
            ok = daemon.shutdown_lang(lang)
            return {"result": f"shutdown {lang}" if ok else f"{lang} not running"}
        daemon.shutdown_all()
        return {"result": "shutdown all"}
    if cmd == "servers":
        active = daemon.active_servers()
        if not active:
            return {"result": "No active servers"}
        lines = []
        for lang, idle in active:
            lines.append(f"  {lang:15s}  idle {idle:.0f}s")
        return {"result": "\n".join(lines)}
    if cmd == "languages":
        lines = []
        for lang, cfg in sorted(LANG_CONFIG.items()):
            exts = ", ".join(sorted(cfg["extensions"]))
            binary = cfg["server_cmd"][0]
            installed = "installed" if shutil.which(binary) else "not found"
            lines.append(f"  {lang:15s}  {exts:35s}  {binary} ({installed})")
        return {"result": "\n".join(lines)}
    # Commands that need a file -> language resolution.
    filepath = req.get("file")
    forced_lang = req.get("language") or os.environ.get("LSP_LANG")
    lang = forced_lang or (detect_language(filepath) if filepath else None)
    if not lang:
        ext = Path(filepath).suffix if filepath else "?"
        return {"error": f"Unsupported file type: {ext}. Use LSP_LANG=<language> to force. Supported: {', '.join(sorted(LANG_CONFIG.keys()))}"}
    result = daemon.get_client(lang)
    if isinstance(result, tuple):
        # Error case: (None, error_message)
        return {"error": result[1]}
    client = result
    line = req.get("line", 1) - 1
    col = req.get("col", 1) - 1
    if cmd == "definition":
        return {"result": client.definition(filepath, line, col)}
    elif cmd == "references":
        return {"result": client.references(filepath, line, col)}
    elif cmd == "hover":
        return {"result": client.hover(filepath, line, col)}
    elif cmd == "symbols":
        return {"result": client.symbols(filepath)}
    elif cmd == "diagnostics":
        return {"result": client.diagnostics(filepath)}
    elif cmd == "completions":
        return {"result": client.completions(filepath, line, col)}
    elif cmd == "signature":
        return {"result": client.signature(filepath, line, col)}
    elif cmd == "rename":
        new_name = req.get("new_name", "")
        return {"result": client.rename(filepath, line, col, new_name)}
    elif cmd == "workspace-symbols":
        query = req.get("query", "")
        return {"result": client.workspace_symbols(query)}
    else:
        return {"error": f"Unknown command: {cmd}"}

# Client: connect to daemon (start it if needed)
def _ensure_daemon():
    sock_path = _sock_path()
    pid_path = sock_path + ".pid"
    if os.path.exists(pid_path):
        try:
            pid = int(Path(pid_path).read_text().strip())
            os.kill(pid, 0)
            result = _send_to_daemon({"command": "ping"})
            if result and result.get("result") == "pong":
                return True
        except (OSError, ValueError, ConnectionRefusedError):
            pass
    for f in [sock_path, pid_path]:
        if os.path.exists(f):
            os.unlink(f)
    pid = os.fork()
    if pid == 0:
        os.setsid()
        devnull = os.open(os.devnull, os.O_RDWR)
        os.dup2(devnull, 0)
        os.dup2(devnull, 1)
        os.dup2(devnull, 2)
        os.close(devnull)
        _run_daemon()
        sys.exit(0)
    else:
        for _ in range(50):
            time.sleep(0.1)
            if os.path.exists(sock_path):
                try:
                    result = _send_to_daemon({"command": "ping"})
                    if result and result.get("result") == "pong":
                        return True
                except Exception:
                    continue
        print("Warning: daemon did not start in time", file=sys.stderr)
        return False

def _send_to_daemon(request):
    sock_path = _sock_path()
    conn = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    conn.settimeout(30)
    conn.connect(sock_path)
    try:
        data = json.dumps(request).encode("utf-8") + b"\n\n"
        conn.sendall(data)
        response = b""
        while True:
            chunk = conn.recv(65536)
            if not chunk:
                break
            response += chunk
        return json.loads(response.decode("utf-8"))
    finally:
        conn.close()

# CLI
USAGE = """Usage: lsp-query <command> [args...]
Navigation:
  definition <file> <line> <col>          Go to definition
  references <file> <line> <col>          Find all references
  hover <file> <line> <col>               Type/docstring info
  symbols <file>                          List document symbols
  diagnostics <file>                      Show errors/warnings
  completions <file> <line> <col>         Code completions
  signature <file> <line> <col>           Function signature help
  rename <file> <line> <col> <new_name>   Preview rename
  workspace-symbols <query>               Search symbols across workspace
Management:
  languages                               Show supported languages + install status
  servers                                 List running language server daemons
  shutdown [language]                     Stop one or all daemons
Lines and columns are 1-indexed. Language is auto-detected from file extension.
Supported: python, typescript/js, rust, go, c/c++, bash, java, css, html, json
Environment:
  LSP_WORKSPACE   Workspace root (default: git root or cwd)
  LSP_SERVER      Override server command for all languages
  LSP_LANG        Force a specific language (bypass auto-detection)
  LSP_TIMEOUT     Daemon idle timeout in seconds (default: 300)
"""

def main():
    if len(sys.argv) < 2:
        print(USAGE)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd in ("-h", "--help", "help"):
        print(USAGE)
        return
    if cmd == "daemon":
        _run_daemon()
        return
    if cmd == "languages":
        _ensure_daemon()
        result = _send_to_daemon({"command": "languages"})
        print(result.get("result", result.get("error", "")))
        return
    if cmd == "servers":
        try:
            result = _send_to_daemon({"command": "servers"})
            print(result.get("result", result.get("error", "")))
        except Exception:
            print("No daemon running")
        return
    if cmd == "shutdown":
        lang = sys.argv[2] if len(sys.argv) > 2 else None
        try:
            result = _send_to_daemon({"command": "shutdown", "language": lang})
            print(result.get("result", result.get("error", "")))
        except Exception:
            print("No daemon running")
        return
    _ensure_daemon()
    request = {"command": cmd}
    if cmd in ("definition", "references", "hover", "completions", "signature"):
        if len(sys.argv) < 5:
            print(f"Usage: lsp-query {cmd} <file> <line> <col>")
            sys.exit(1)
        request["file"] = os.path.abspath(sys.argv[2])
        request["line"] = int(sys.argv[3])
        request["col"] = int(sys.argv[4])
    elif cmd == "rename":
        if len(sys.argv) < 6:
            print(f"Usage: lsp-query {cmd} <file> <line> <col> <new_name>")
            sys.exit(1)
        request["file"] = os.path.abspath(sys.argv[2])
        request["line"] = int(sys.argv[3])
        request["col"] = int(sys.argv[4])
        request["new_name"] = sys.argv[5]
    elif cmd in ("symbols", "diagnostics"):
        if len(sys.argv) < 3:
            print(f"Usage: lsp-query {cmd} <file>")
            sys.exit(1)
        request["file"] = os.path.abspath(sys.argv[2])
    elif cmd == "workspace-symbols":
        if len(sys.argv) < 3:
            print(f"Usage: lsp-query {cmd} <query>")
            sys.exit(1)
        request["query"] = sys.argv[2]
    else:
        print(f"Unknown command: {cmd}")
        print(USAGE)
        sys.exit(1)
    try:
        result = _send_to_daemon(request)
    except ConnectionRefusedError:
        print("Error: could not connect to LSP daemon", file=sys.stderr)
        sys.exit(1)
    if "error" in result:
        print(f"Error: {result['error']}", file=sys.stderr)
        sys.exit(1)
    print(result.get("result", ""))

if __name__ == "__main__":
    main()

import machine
import utime
import os
import sys
import random
import helpers
import gc

# Constants for port types
DIGITAL = 1
PWM = 2

# Constants for control data file format
CSV = 5
BIN = 7

# Global state variables
firstTime = True
verbose = False
memuse = 0  # 0 = no memory stats, 1 = GC count, 2 = debug mem use

# LED configuration
led_onboard = machine.Pin(25, machine.Pin.OUT)
led_offboard = machine.Pin(26, machine.Pin.OUT)

# Button configurations
trigger2 = machine.Pin(27, machine.Pin.IN, machine.Pin.PULL_UP)
trigger1 = machine.Pin(28, machine.Pin.IN, machine.Pin.PULL_UP)

# Button state tracking
trigger2_laststate = True
trigger1_laststate = True

def debounce_button(pin, last_state):
    """Improved button debouncing with configurable pin"""
    current = pin.value()
    if current != last_state:
        utime.sleep_ms(50)  # Debounce delay
        if pin.value() != last_state:
            return not last_state
    return last_state

def is_trigger1_pressed():
    global trigger1_laststate
    trigger1_laststate = debounce_button(trigger1, trigger1_laststate)
    return trigger1_laststate

def is_trigger2_pressed():
    global trigger2_laststate
    trigger2_laststate = debounce_button(trigger2, trigger2_laststate)
    return trigger2_laststate

def blink_leds():
    """Toggle both LEDs simultaneously"""
    led_onboard.toggle()
    led_offboard.toggle()

def light_up_leds():
    """Turn on both LEDs"""
    led_onboard.on()
    led_offboard.on()

def run_animation_sequence(animations, idle_anim=None, shuffle=False, loop_forever=False, 
                          skip_intro=False, single_run=False):
    """Execute animation sequence with improved flow control"""
    global firstTime

    # Reset hardware state
    helpers.clearAllDigital()
    helpers.releaseAllServos()

    # Determine blink rate based on animation availability
    blink_interval = 1000 if animations else 100

    # Clear any initial button presses
    while is_trigger1_pressed() or is_trigger2_pressed():
        utime.sleep_ms(100)

    # Initialize LED states
    led_onboard.off()
    led_offboard.off()

    # Main execution loop
    anim_index = 0
    if shuffle and animations:
        anim_index = random.randint(0, len(animations)-1)

    while True:
        # Intro phase - blink until button press
        if not loop_forever and not skip_intro:
            while not is_trigger1_pressed() and not is_trigger2_pressed():
                # Run idle animation if available and not first time
                if idle_anim and not firstTime:
                    execute_single_animation(*idle_anim, idle=True)

                blink_leds()

                # Blink timing loop
                for _ in range(blink_interval):
                    if helpers.isThereInput():
                        if helpers.handleInput() == 1:
                            break
                    else:
                        utime.sleep_ms(1)

                    if is_trigger1_pressed() or is_trigger2_pressed():
                        break

                if helpers.isThereInput() and helpers.handleInput() == 1:
                    break

            # Wait for button release with LED indication
            light_up_leds()
            for _ in range(100):
                utime.sleep_ms(50)
                if not is_trigger1_pressed():
                    break

        # Continuous mode activation
        if is_trigger1_pressed():
            while True:
                blink_leds()
                utime.sleep_ms(100)
                if not is_trigger1_pressed():
                    break
            loop_forever = True

        # Execute current animation if available
        if animations:
            firstTime = False
            if verbose:
                print(f"Playing animation {anim_index}: {animations[anim_index][0]}")

            execute_single_animation(*animations[anim_index])

        # Reset flags
        skip_intro = False
        if single_run:
            break

        # Check for stop condition
        if is_trigger1_pressed():
            if verbose:
                print("Stop button pressed")
            loop_forever = False

            # Wait for button release
            while is_trigger1_pressed():
                utime.sleep_ms(100)

        # Ensure opto button is released
        while is_trigger2_pressed():
            utime.sleep_ms(10)

        # Advance to next animation
        if animations:
            anim_index += 1
            if anim_index >= len(animations):
                anim_index = 0
            if shuffle:
                anim_index = random.randint(0, len(animations)-1)

        if verbose:
            print("Loop iteration complete")

class FileDataSource:
    def __init__(self, filename=None, block_size=0, lock=None):
        self.file_handle = None
        self.block_size = block_size
        self.lock = lock

        if lock:
            lock.acquire()

        try:
            if block_size > 0:
                self.file_handle = open(filename, 'rb')
            else:
                self.file_handle = open(filename, 'r')
        except Exception as e:
            if verbose:
                print(f"Failed to open file {filename}: {e}")
            self.file_handle = None

        if lock:
            lock.release()

    def read_next_line(self, buffer=None):
        """Read next line from file with optimized buffer handling"""
        if not self.file_handle:
            return ''

        if self.lock:
            self.lock.acquire()

        try:
            if self.block_size > 0:
                if buffer is None:
                    buffer = bytearray(self.block_size)

                bytes_read = 0
                chunk_size = 512
                view = memoryview(buffer)

                while bytes_read < self.block_size:
                    remaining = self.block_size - bytes_read
                    read_size = min(chunk_size, remaining)
                    bytes_read += self.file_handle.readinto(view[bytes_read:bytes_read+read_size])

                result = buffer if bytes_read > 0 else ''
            else:
                result = self.file_handle.readline()
        finally:
            if self.lock:
                self.lock.release()

        return result

    def cleanup(self):
        """Close file handle safely"""
        if self.file_handle:
            self.file_handle.close()
            self.file_handle = None

def execute_single_animation(csv_file, wave_file, idle=False):
    """Execute a single animation with robust file handling"""
    # Determine file format
    bin_block_size = 0
    file_format = CSV

    # Get binary block sizes if needed
    block_sizes = helpers.tables.getBinarysizes()
    board_list = helpers.tables.boardList()

    if verbose:
        for board in board_list:
            print(f"Board ID: {board.pca9685.address}, Ports: {board.firstport}-{board.firstport+block_sizes[1]+block_sizes[2]}")

    # Get PWM list for GPIO pins
    pwm_list = helpers.tables.pwmList()
    if verbose:
        for port in pwm_list:
            print(f"PWM Port: {port} on GPIO pin")

    # Detect file format by reading first byte
    try:
        with open(csv_file, 'rb') as test_file:
            first_byte = test_file.read(1)
            if first_byte == b'T':
                file_format = CSV
            elif first_byte == b'0':
                file_format = HEX
                print("HEX format no longer supported!")
                return
            elif first_byte == b'\x00':
                file_format = BIN
                bin_block_size = block_sizes[0]
            else:
                print(f"Unknown file format: {csv_file}")
                return
    except Exception as e:
        print(f"Error opening control file {csv_file}: {e}")
        csv_file = None

    # Initialize audio player if wave file exists
    audio_player = None
    if helpers.isfile(wave_file):
        audio_player = helpers.WavePlayer(
            wave_file, 
            csvfilename=csv_file, 
            binblocksize=bin_block_size,
            verbose=0 if not verbose else 1
        )

    # Set up data source
    data_source = None
    if helpers.isfile(csv_file):
        if audio_player:
            data_source = audio_player
        else:
            data_source = FileDataSource(csv_file, bin_block_size)

    # Initialize statistics tracking
    stats = {
        'set_time': 0,
        'dig_time': 0,
        'servo_time': 0,
        'servo_count': 0,
        'skips': 0,
        'read_time': 0,
        'split_time': 0,
        'data_time': 0,
        'servo_data_time': 0,
        'button_time': 0,
        'gc_time': 0,
        'led_time': 0,
        'max_cycle_time': 0,
        'collections': 0
    }

    # Start audio playback
    if verbose:
        print(f"Playing audio: {wave_file}")

    if audio_player:
        audio_player.play()

    if data_source:
        start_time = utime.ticks_ms()
        wait_time = 0

        # Read first data line
        line = data_source.read_next_line()
        if file_format == CSV:
            parts = line.split(',')
            next_frame_time = int(parts[0])
        else:
            next_frame_time = int.from_bytes(line[:4], 'little')

        # Process animation frames
        frame_start = utime.ticks_us()
        while len(line) > 0:
            cycle_start = utime.ticks_us()

            # Wait until 20ms before next frame
            while (utime.ticks_diff(utime.ticks_ms(), start_time) < next_frame_time - 20):
                utime.sleep_ms(1)
                wait_time += 1

            # Process frame data
            frame_time = utime.ticks_us()

            if file_format == BIN:
                # Binary format processing
                board_offset = block_sizes[1] + block_sizes[2]
                for board in board_list:
                    start_addr = board.firstport * 4 + board_offset
                    board.pca9685.jambytes(line[start_addr:start_addr+board.numbytes])

                # Handle PWM on GPIO pins
                for port in pwm_list:
                    addr = port * 4 + block_offset
                    helpers.tables.dosomething(port, line[addr+2:addr+4])

                # Process digital outputs
                bits = int.from_bytes(line[block_sizes[1]:block_sizes[1]+block_sizes[2]], 'little')
                helpers.tables.intToDigital(bits)
                helpers.tables.outputDigital()

                stats['set_time'] += utime.ticks_diff(utime.ticks_us(), frame_time)
                stats['servo_count'] += 1
            else:
                # CSV format processing
                parts = line.split(',')

                for i in range(1, len(parts)):
                    if i < len(parts):
                        port_type = None
                        port_num = None

                        if parts[i]:
                            indicator = parts[i][0]
                            try:
                                port_num = int(parts[i][1:])

                                if indicator == 'D':
                                    port_type = DIGITAL
                                elif indicator == 'S':
                                    port_type = PWM
                            except ValueError:
                                continue

                        if port_type and port_num is not None:
                            value = int(parts[i][1:]) if parts[i][1:].isdigit() else 0

                            if port_type == DIGITAL:
                                if port_num >= 0:
                                    helpers.setDigital(port_num, value)
                                else:
                                    helpers.tables.intToDigital(value)
                            elif port_type == PWM:
                                if port_num >= 0:
                                    helpers.setServo(port_num, value, push=False)
                                else:
                                    vals = []
                                    for p in range(32):
                                        vals.append(value & 0xFFFF)
                                        value >>= 16
                                    helpers.tables.intsToPWM(vals)

                # Output all channels
                helpers.outputDigital()
                helpers.pushServos()
                stats['servo_count'] += 1

            # Check for stop conditions
            if is_trigger1_pressed():
                if verbose:
                    print("Stop button pressed during animation")
                break

            if idle and is_trigger2_pressed():
                if verbose:
                    print("Trigger 2 interrupted idle animation")
                break

            # Update LED status
            blink_leds()

            # Read next line
            line = data_source.read_next_line(line if file_format == BIN else None)

            # Parse next frame time
            if len(line) > 0:
                if file_format == CSV:
                    parts = line.split(',')
                    next_frame_time = int(parts[0])
                else:
                    next_frame_time = int.from_bytes(line[:4], 'little')

                # Skip frames that are already past
                while len(line) > 0 and next_frame_time < utime.ticks_diff(utime.ticks_ms(), start_time):
                    stats['skips'] += 1
                    line = data_source.read_next_line(line if file_format == BIN else None)
                    if len(line) > 0:
                        if file_format == CSV:
                            parts = line.split(',')
                            next_frame_time = int(parts[0])
                        else:
                            next_frame_time = int.from_bytes(line[:4], 'little')

            # Track cycle time
            cycle_time = utime.ticks_diff(utime.ticks_us(), cycle_start)
            if cycle_time > stats['max_cycle_time']:
                stats['max_cycle_time'] = cycle_time

        # Cleanup data source
        if data_source != audio_player:
            data_source.cleanup()

        # Report statistics if requested
        if verbose:
            total_time = utime.ticks_diff(utime.ticks_ms(), start_time)
            print("="*60)
            print("Animation Statistics")
            print(f"Total time: {total_time}ms")
            print(f"Wait time: {wait_time}ms")
            print(f"Frame duration: {next_frame_time}ms")
            print(f"Skipped frames: {stats['skips']}")
            print(f"Processed frames: {stats['servo_count']}")
            print("="*60)

    # Stop audio and release servos
    if audio_player:
        while audio_player.playing():
            if is_trigger1_pressed() or (idle and is_trigger2_pressed()):
                if verbose:
                    print("Stopping audio playback")
                audio_player.stop()
                break
            utime.sleep_ms(1)

    helpers.releaseAllServos()

def main():
    """Main entry point with improved initialization"""
    # Initialize status LEDs
    light_up_leds()

    # Find animation files
    animations = []
    idle_animation = None

    try:
        animations, idle_animation = helpers.findAnimFiles(dir='/sd/anims')
    except Exception as e:
        if verbose:
            print(f"Error loading /sd/anims: {e}")

    if not animations:
        try:
            animations, idle_animation = helpers.findAnimFiles()
        except Exception as e:
            if verbose:
                print(f"Error loading default animations: {e}")

    # Start animation sequence
    run_animation_sequence(animations, idle_anim=idle_animation)

if __name__ == "__main__":
    main()
